/* Domain definitions */
CREATE DOMAIN D_BOOLEAN AS SMALLINT
         CHECK (VALUE IN (0, 1));
CREATE DOMAIN NEW_DOMAIN AS INTEGER;
CREATE DOMAIN NUMERIC_11_2 AS NUMERIC(13, 2);
CREATE DOMAIN NUMERIC_11_4 AS NUMERIC(15, 4);
CREATE DOMAIN NUMERIC_13_2 AS NUMERIC(15, 2);
CREATE DOMAIN NUMERIC_3_4 AS NUMERIC(7, 4);
CREATE DOMAIN T_D_QUANT AS DOUBLE PRECISION
         DEFAULT 00000.00;
CREATE DOMAIN T_FONE_GERAL AS CHAR(13);
CREATE DOMAIN T_N_G AS DOUBLE PRECISION;
CREATE DOMAIN T_N_GERAL AS DOUBLE PRECISION
         DEFAULT 000.00;
CREATE DOMAIN T_N_GERAL2 AS DOUBLE PRECISION;
CREATE DOMAIN T_PROD_COD AS CHAR(6);
CREATE DOMAIN T_VL3CASAS AS DOUBLE PRECISION
         DEFAULT 000000000.000;
CREATE DOMAIN T_VL_TODOS AS DOUBLE PRECISION
         DEFAULT 000000000.00;

/* Table: ACOESRETORNO, Owner: SYSDBA */
CREATE TABLE ACOESRETORNO (COD_BANCO CHAR(3) NOT NULL,
        CARTEIRA CHAR(3) NOT NULL,
        OCORRENCIA CHAR(2) NOT NULL,
        DESCRICAO VARCHAR(40),
        ACAO INTEGER NOT NULL,
CONSTRAINT PK_ACOESRETORNO PRIMARY KEY (COD_BANCO, CARTEIRA, OCORRENCIA));

/* Table: ADM_CARTAO, Owner: SYSDBA */
CREATE TABLE ADM_CARTAO (COD_ADM INTEGER NOT NULL,
        COD_EMPRESA INTEGER NOT NULL,
        COD_CLIENTE INTEGER NOT NULL,
        DESCRICAO_ADM VARCHAR(30) NOT NULL,
        NUM_ESTAB_ADM INTEGER,
        END_ARQUIVO_ADM VARCHAR(255),
        ATIVO INTEGER DEFAULT 1,
        REDES BLOB SUB_TYPE TEXT SEGMENT SIZE 1024,
        TAXA_POR_CONTROLE_BANDEIRA CHAR(1),
        COD_ADQUIRENTE INTEGER,
        CAMPO_NSU_OBRIG VARCHAR(1) DEFAULT 'S',
        CAMPO_NUM_AUT_OBRIG VARCHAR(1) DEFAULT 'S',
CONSTRAINT PK_ADM_CARTAO PRIMARY KEY (COD_ADM, COD_EMPRESA));

/* Table: ADM_CARTAO_REDES, Owner: SYSDBA */
CREATE TABLE ADM_CARTAO_REDES (REDE VARCHAR(32) NOT NULL,
        COD_EMPRESA INTEGER NOT NULL,
        COD_ADM INTEGER,
        TBAND SMALLINT,
        DEBCRED CHAR(1),
CONSTRAINT PK_ADM_CARTAO_REDES PRIMARY KEY (REDE, COD_EMPRESA));

/* Table: ADM_CARTAO_TAXAS_BANDEIRAS, Owner: SYSDBA */
CREATE TABLE ADM_CARTAO_TAXAS_BANDEIRAS (SEQID INTEGER NOT NULL,
        COD_EMPRESA INTEGER NOT NULL,
        COD_BANDEIRA INTEGER NOT NULL,
        COD_ADM INTEGER NOT NULL,
        DEBITO_CREDITO CHAR(1) default 'C',
        PARCELAS_DE SMALLINT,
        PARCELAS_ATE SMALLINT,
        TAXA T_VL_TODOS,
CONSTRAINT PK_ADM_CARTAO_TAXAS_BANDEIRAS PRIMARY KEY (SEQID, COD_EMPRESA));

/* Table: AGENDA, Owner: SYSDBA */
CREATE TABLE AGENDA (COD_AGENDA INTEGER NOT NULL,
        COD_EMPRESA INTEGER NOT NULL,
        COD_CLIENTE INTEGER NOT NULL,
        NOME_CLIENTE VARCHAR(35),
        FONE_CLIENTE CHAR(13),
        DATA_AGENDA TIMESTAMP,
        HORA_AGENDA VARCHAR(2),
        DESCR_AGENDA VARCHAR(30),
        OBSERVACAO BLOB SUB_TYPE TEXT SEGMENT SIZE 80,
        STATUS_AGENDA VARCHAR(10),
        TMO_SERVICO T_N_GERAL,
        NPED INTEGER,
        COD_EQUIP INTEGER,
        COD_VEICULO INTEGER,
        PLACA VARCHAR(10),
        CHASSI VARCHAR(17),
        COD_USUARIO INTEGER,
        MINUTO_AGENDA VARCHAR(2),
CONSTRAINT PK_AGENDA PRIMARY KEY (COD_AGENDA, COD_EMPRESA));

/* Table: AGENDAMENTO, Owner: SYSDBA */
CREATE TABLE AGENDAMENTO (COD_AGENDAMENTO INTEGER NOT NULL,
        COD_EMPRESA INTEGER NOT NULL,
        COD_AGENDAMENTO_PROX INTEGER,
        COD_AGENDAMENTO_ANT INTEGER,
        COD_CLIENTE INTEGER,
        COD_VENDEDOR INTEGER,
        COD_CONTATO INTEGER,
        COD_FINALIZACAO INTEGER,
        DESCRICAO BLOB SUB_TYPE TEXT SEGMENT SIZE 80,
        STATUS VARCHAR(32),
        NPED INTEGER,
        TIPO_PED CHAR(3),
        DATA_CADASTRO TIMESTAMP,
        DATA_AGENDADA TIMESTAMP,
        DATA_FINALIZACAO TIMESTAMP,
        AUTOMATICO CHAR(1),
        COD_USUARIO INTEGER,
        ATIVO SMALLINT DEFAULT 1,
        CODMOD_POTVEIC INTEGER,
        CONDPAG_POTVEIC VARCHAR(30),
CONSTRAINT PK_AGENDAMENTO PRIMARY KEY (COD_AGENDAMENTO, COD_EMPRESA));

/* Table: AGENDA_ITENS, Owner: SYSDBA */
CREATE TABLE AGENDA_ITENS (COD_AGENDA INTEGER NOT NULL,
        COD_EMPRESA INTEGER NOT NULL,
        NITEM INTEGER NOT NULL,
        COD_SERVICO INTEGER NOT NULL,
        DESC_SERVICO CHAR(60),
        TMO_SERVICO T_N_GERAL,
        CODIGO_NOP T_N_GERAL,
        VALOR_SERVICO T_N_GERAL,
        COD_BOX INTEGER,
        COD_VENDEDOR INTEGER,
        NPED INTEGER,
        COD_USUARIO INTEGER,
CONSTRAINT PK_AGENDA_ITENS PRIMARY KEY (COD_AGENDA, COD_EMPRESA, NITEM, COD_SERVICO));

/* Table: AJ_REDBENEF, Owner: SYSDBA */
CREATE TABLE AJ_REDBENEF (ID CHAR(36) NOT NULL,
        CHAVE_DFE VARCHAR(50) NOT NULL,
        COD_EMPRESA INTEGER NOT NULL,
        REGRA_ID CHAR(36) NOT NULL,
        IND_AJ SMALLINT NOT NULL,
        COD_AJ SMALLINT NOT NULL,
        DATA_REF TIMESTAMP NOT NULL,
        CST CHAR(2) NOT NULL,
        VBC NUMERIC_11_2 NOT NULL,
        PPIS_AJ NUMERIC_11_4 NOT NULL,
        VPIS_AJ NUMERIC_11_2 NOT NULL,
        PCOFINS_AJ NUMERIC_11_4 NOT NULL,
        VCOFINS_AJ NUMERIC_11_2 NOT NULL,
        AUTOMATICO SMALLINT NOT NULL,
CONSTRAINT PK_AJ_REDBENEF PRIMARY KEY (ID));

/* Table: ALIQ, Owner: SYSDBA */
CREATE TABLE ALIQ (SEQUENCIA VARCHAR(4) NOT NULL,
        ALIQ T_N_GERAL NOT NULL,
        COD_TERMINAL INTEGER NOT NULL,
        NSERIEECF CHAR(20) NOT NULL,
        COD_EMPRESA INTEGER NOT NULL,
        SERVICO CHAR(1) NOT NULL,
        INDICE SMALLINT,
CONSTRAINT PK_ALIQ PRIMARY KEY (SEQUENCIA, ALIQ, COD_TERMINAL, NSERIEECF, COD_EMPRESA));

/* Table: ALIQ_ANT_ST, Owner: SYSDBA */
CREATE TABLE ALIQ_ANT_ST (ID INTEGER NOT NULL,
        COD_EMPRESA INTEGER NOT NULL,
        UF_ORIGEM CHAR(2) NOT NULL,
        UF_DESTINO CHAR(2) NOT NULL,
        CEST VARCHAR(7),
        NCM VARCHAR(8),
        ALIQUOTA T_VL_TODOS,
        TRIB_SEFAZ_ID VARCHAR(16),
CONSTRAINT PK_ALIQ_ANT_ST PRIMARY KEY (ID, COD_EMPRESA));

/* Table: ANOTACOES, Owner: SYSDBA */
CREATE TABLE ANOTACOES (CODIGO INTEGER NOT NULL,
        COD_EMPRESA INTEGER DEFAULT 1 NOT NULL,
        TIPO VARCHAR(13),
        COD_CLIENTE INTEGER,
        COD_USUARIO INTEGER,
        ASSUNTO VARCHAR(60),
        CONTATO VARCHAR(40),
        EMAIL VARCHAR(30),
        FONE CHAR(13),
        DATA TIMESTAMP,
        HORA CHAR(8),
        OBSERVACAO BLOB SUB_TYPE TEXT SEGMENT SIZE 80,
        STATUS VARCHAR(12),
        US_STATUS INTEGER,
        ATIVO INTEGER DEFAULT 1,
        TP_ATEND CHAR(1),
        TP_CONTR CHAR(1),
        HORA_INICIAL CHAR(8),
        HORA_FINAL CHAR(8),
        COD_TIPOANOT INTEGER,
        CODPESQUISA INTEGER,
        COD_SOFT INTEGER,
CONSTRAINT PK_ANOTACOES PRIMARY KEY (CODIGO, COD_EMPRESA));

/* Table: APURACAO_BALANCO, Owner: SYSDBA */
CREATE TABLE APURACAO_BALANCO (COD_SEQBALANCO INTEGER NOT NULL,
        MES INTEGER NOT NULL,
        ANO INTEGER NOT NULL,
        COD_EMPRESA INTEGER NOT NULL,
