CONSTRAINT PK_APURACAO_BALANCO PRIMARY KEY (COD_SEQBALANCO, MES, ANO, COD_EMPRESA));

/* Table: APURACAO_DEPTO, Owner: SYSDBA */
CREATE TABLE APURACAO_DEPTO (COD_DEP INTEGER NOT NULL,
        MES INTEGER NOT NULL,
        ANO INTEGER NOT NULL,
        TPDESP CHAR(4) NOT NULL,
        COD_EMPRESA INTEGER NOT NULL,
        VALOR T_VL_TODOS,
        PE T_VL_TODOS,
        DNADEP CHAR(50),
        ATIVO INTEGER DEFAULT 1,
        DATACAD_AP TIMESTAMP,
        PERC_VALOR T_VL_TODOS,
        VALOR_DINHEIRO T_VL_TODOS,
        VALOR_FATURADO T_VL_TODOS,
        MARGMIN DOUBLE PRECISION DEFAULT 000.0000,
        MARKUPMIN DOUBLE PRECISION DEFAULT 000.0000,
        APURACAO_CONTABIL CHAR(1),
        APURACAO_MEDIA CHAR(1),
        APURACAO_MEDIA_MESES SMALLINT,
CONSTRAINT PK_APURACAO_DEPTO PRIMARY KEY (COD_DEP, MES, ANO, TPDESP, COD_EMPRESA));

/* Table: ARQUIVOS_FISCAL, Owner: SYSDBA */
CREATE TABLE ARQUIVOS_FISCAL (COD_ARQUIVO INTEGER NOT NULL,
        COD_FISCAL INTEGER NOT NULL,
        NOME_ARQUIVO VARCHAR(30) NOT NULL,
        MD5_ARQUIVO VARCHAR(32) NOT NULL,
CONSTRAINT PK_ARQUIVOS_FISCAL PRIMARY KEY (COD_ARQUIVO));

/* Table: ARQ_BOLETO, Owner: SYSDBA */
CREATE TABLE ARQ_BOLETO (SEQID BIGINT NOT NULL,
