CONSTRAINT PK_ARQ_FABRICA PRIMARY KEY (NOMEARQUIVO, TIPOARQUIVO, COD_EMPRESA));

/* Table: ATESTADO_ECF, Owner: SYSDBA */
CREATE TABLE ATESTADO_ECF (N_OS INTEGER NOT NULL,
