        LARGURA_P DECIMAL(15, 1) DEFAULT 210 NOT NULL,
        DISTANCIA_ENTRECOL DECIMAL(15, 1) DEFAULT 1 NOT NULL,
        TAMANHO_ETI_H COMPUTED BY (((LARGURA_P - MARGEM_ESQUERDA - MARGEM_DIREITA - ((COLUNAS-1) * DISTANCIA_ENTRECOL)) / COLUNAS)),
        TAMANHO_ETI_V DECIMAL(15, 1) DEFAULT 30.0 NOT NULL,
        MARGEM_SUPERIOR DECIMAL(15, 1) DEFAULT 10 NOT NULL,
        MARGEM_INFERIOR DECIMAL(15, 1) DEFAULT 10 NOT NULL,
