/* Table: PRODUTOS_HISTORICO_PRECO, Owner: SYSDBA */
CREATE TABLE PRODUTOS_HISTORICO_PRECO (ID CHAR(36) NOT NULL,
        COD_EMPRESA INTEGER NOT NULL,
        DATA TIMESTAMP NOT NULL,
        GRUPO_PROD INTEGER NOT NULL,
        COD_PROD CHAR(6) NOT NULL,
        TABELA_ID VARCHAR(36),
        CUSTO T_VL_TODOS,
        PRECO T_VL_TODOS,
        QUANTIDADE T_VL_TODOS,
        USUARIO VARCHAR(32),
        MARKUP COMPUTED BY (iif (coalesce (CUSTO, 0) <= 0, 0, (PRECO / CUSTO - 1) * 100)),
        MARGEM COMPUTED BY (iif (coalesce (PRECO, 0) <= 0, 0, (PRECO - CUSTO) / PRECO * 100)),
        DESCRICAO VARCHAR(128),
CONSTRAINT PK_PRODUTOS_HISTORICO_PRECO PRIMARY KEY (ID, COD_EMPRESA));

