ALTER TABLE TP_DESPTIP_XLS ADD CONSTRAINT FK_TP_DESCRDESP_XLS FOREIGN KEY (COD_DESPESAS) REFERENCES DESCR_DESPESAS_XLS (COD_DESPESAS);

