ALTER TABLE TRANSITO_MOTOS ADD CONSTRAINT FK_TRANSITO_NF_TRANS FOREIGN KEY (NUM_NOTAT, N_CAIXA, COD_EMPRESA) REFERENCES NF_TRANSITO (NUM_NOTAT, N_CAIXA, COD_EMPRESA) ON DELETE CASCADE;

ALTER TABLE TRANSITO_MOTOS ADD FOREIGN KEY (NUM_NOTAT, N_CAIXA, COD_EMPRESA) REFERENCES NF_TRANSITO (NUM_NOTAT, N_CAIXA, COD_EMPRESA) ON DELETE CASCADE;

ALTER TABLE TRIB_SEFAZ ADD CONSTRAINT FK_TRIB_SEFAZ_LANCFISCAL FOREIGN KEY (COD_OBS, COD_EMPRESA) REFERENCES SPED_LANCAMENTO_FISCAL (COD_OBS, COD_EMPRESA) ON UPDATE CASCADE;

ALTER TABLE VALOR_TIPO_GRADE_EC ADD CONSTRAINT FK_VALOR_TIPO_GRADE_EC_TP_GR FOREIGN KEY (COD_TIPO, COD_EMPRESA) REFERENCES TIPO_GRADE_EC (COD_TIPO, COD_EMPRESA);

ALTER TABLE VEICULOS ADD CONSTRAINT FK_VEICULOS_CLIENTES__CLIENTES FOREIGN KEY (COD_CLIENTE, COD_EMPRESA) REFERENCES CLIENTES (COD_CLIENTE, COD_EMPRESA);

ALTER TABLE VEICULOS_TRANSPORTE ADD CONSTRAINT FK_VEIC_TRANSP_CLIENTE FOREIGN KEY (COD_PROP_TERCEIRO, COD_EMPRESA) REFERENCES CLIENTES (COD_CLIENTE, COD_EMPRESA) ON UPDATE CASCADE;

