cf.acquirer_id, cf.acquirer_name, 
cf.brand_id, cf.brand_name, 
cf.event_type, cf.event_type_description, 
cf.description,
stpag.id as bank_recon_status,
stpag.descricao as bank_recon_description,
coalesce(cf.gross_amount, 0) gross_amount,
coalesce(cf.event_net_amount, 0) event_net_amount,
coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
cf.tax, cf.sale_tax, cf.customer_tax, 
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number,
emp.identificacao_emp, 
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_status vwf
inner join conciliacao_financeiro cf on
    vwf.id = cf.id
    and vwf.installment_number = cf.installment_number
    and vwf.installments_total = cf.installments_total
    and vwf.cod_empresa = cf.cod_empresa
inner join empresa emp on
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
    band_adq.codigo = cf.bandeira_cod
    and band_adq.id_adquirente = adq.id
left join conciliacao_bandeira band on
    band.id = band_adq.id_bandeira
left join conciliacao_cod_ajuste_adq codajt_adq on
    codajt_adq.codigo = cf.cod_ajuste_cod
    and codajt_adq.id_adquirente = adq.id
left join conciliacao_cod_ajuste codajt on
    codajt.id = codajt_adq.id_cod_ajuste
left join conciliacao_form_pag_adq formpag_adq on
    formpag_adq.codigo = cf.form_pag_cod
    and formpag_adq.id_adquirente = adq.id
left join conciliacao_form_pag formpag on
    formpag.id = formpag_adq.id_form_pag
left join conciliacao_grupo_cartao_adq grcartao_adq on
    grcartao_adq.codigo = cf.grupo_cartao_cod
    and grcartao_adq.id_adquirente = cf.acquirer_id
left join conciliacao_grupo_cartao grcartao on
    grcartao.id = grcartao_adq.id_grupo_cartao
left join conciliacao_motivo_rej_adq motrej_adq on
    motrej_adq.codigo = cf.motivo_rej_cod
    and motrej_adq.id_adquirente = adq.id
left join conciliacao_motivo_rej motrej on
    motrej.id = motrej_adq.id_motivo_rej
left join conciliacao_origem_ajuste_adq orig_transf_adq on
    orig_transf_adq.codigo = cf.origem_ajuste_cod
    and orig_transf_adq.id_adquirente = adq.id
left join conciliacao_origem_ajuste orig_transf on
    orig_transf.id = orig_transf_adq.id_origem_ajuste
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
left join conciliacao_status_transf_adq st_transf_adq on
    st_transf_adq.codigo = cf.status_transf_cod
    and st_transf_adq.id_adquirente = adq.id
left join conciliacao_status_transf st_transf on
    st_transf.id = st_transf_adq.id_status_transf
left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
    tpantec.id = tpantec_adq.id_tipo_antecip
left join conciliacao_tipo_cartao_adq tpcartao_adq on
    tpcartao_adq.codigo = cf.tipo_cartao_cod
    and tpcartao_adq.id_adquirente = adq.id
left join conciliacao_tipo_cartao tpcartao on
    tpcartao.id = tpcartao_adq.id_tipo_cartao
left join conciliacao_tipo_lanc_adq tplanc_adq on
    tplanc_adq.codigo = cf.tipo_lancamento_cod
    and tplanc_adq.id_aquirente = adq.id
left join conciliacao_tipo_lanc tplanc on
    tplanc.id = tplanc_adq.id_tipo_lanc
left join conciliacao_tipo_liq_adq tpliq_adq on
    tpliq_adq.codigo = cf.tipo_liquidacao_cod
    and tpliq_adq.id_adquirente = adq.id
left join conciliacao_tipo_liq tpliq on
    tpliq.id = tpliq_adq.id_tipo_liq
left join conciliacao_tipo_transacao_adq tptr_adq on
    tptr_adq.codigo = cf.tipo_transacao_cod
    and tptr_adq.id_adquirente = adq.id
left join conciliacao_tipo_transacao tptr on
    tptr.id = tptr_adq.id_tipo_transacao
where trim(cf.event_type_description) = 'Ajuste' and coalesce(cf.event_net_amount, 0) < 0
;

/* View: VW_CONCILIACAO_FINANCEIRO, Owner: SYSDBA */
CREATE VIEW VW_CONCILIACAO_FINANCEIRO (DATA, DATE_, REQUEST_DATE, EFFECTED_DATE, PAYMENT_DATE, BANK_SHIPPING_DATE, ID, COD_EMPRESA, ARQUIVO, DATA_ARQUIVO, ESTABLISHMENT_NUMBER, NSU, AUTHORIZATION_NUMBER, TYPE_, TYPE_DESCRIPTION, ACQUIRER_ID, ACQUIRER_NAME, BRAND_ID, BRAND_NAME, EVENT_TYPE, EVENT_TYPE_DESCRIPTION, DESCRIPTION, BANK_RECON_STATUS, BANK_RECON_DESCRIPTION, GROSS_AMOUNT, EVENT_NET_AMOUNT, BATCH_NET_AMOUNT, GROSS_EVENT_AMOUNT, BATCH_GROSS_AMOUNT, TAX, SALE_TAX, CUSTOMER_TAX, INSTALLMENT_NUMBER, INSTALLMENTS_TOTAL, BANK_NUMBER, BANK_NAME, BRANCH_NUMBER, ACCOUNT_NUMBER, IDENTIFICACAO_EMP, CODIGO_CTRL, NOME_CTRL, CODIGO_CTRL_TX, NOME_CTRL_TX, N_CONTA_PLC_TX_CARTAO, N_CONTA_PLC_TARIFA_CARTAO, N_CONTA_PLC, DESC_PLC, COD_CRED, N_DOC_V, N_DOC_C, TP_DOC_V, VALOR_C, VALOR_LIQUIDO, VALOR_ORIGINAL, DATA_REC_C, DATA_VENC_C, STATUS_C, DATQ_C, TAXA_CRED, COD_CLIENTE, NOME_CLIENTE, RAZAO, COD_TERMINAL_ADM, DESC_TERM_ADM, COD_ADM, DESCRICAO_ADM, COD_BANDEIRA_ADM, DESC_BANDEIRA_ADM, QTDE_REG, PIX_ID, FORM_PAG_COD, FORM_PAG, COD_AJUSTE_COD, COD_AJUSTE, BANDEIRA_COD, BANDEIRA, STATUS_PAG_COD, STATUS_PAG, STATUS_PAG_ST, TIPO_LANCAMENTO_COD, TIPO_LANCAMENTO, TIPO_LIQUIDACAO_COD, TIPO_LIQUIDACAO, TIPO_ANTECIPACAO_COD, TIPO_ANTECIPACAO, TIPO_CARTAO_COD, TIPO_CARTAO, MOTIVO_REJ_COD, MOTIVO_REJ, GRUPO_CARTAO_COD, GRUPO_CARTAO, TIPO_TRANSACAO_COD, TIPO_TRANSACAO, STATUS_TRANSF_COD, STATUS_TRANSF, STATUS_TRANSF_ST, ORIGEM_AJUSTE_COD, ORIGEM_AJUSTE) AS

select case when (cf.payment_date is not null) then cf.payment_date else cf.date_ end data,
cf.date_, cf.request_date, cf.effected_date, cf.payment_date, cf.bank_shipping_date,
cf.id, cf.cod_empresa, cf.arquivo, cf.data_arquivo,
cf.establishment_number,
cf.nsu, cf.authorization_number,
cf.type_, cf.type_description, 
cf.acquirer_id, cf.acquirer_name, 
cf.brand_id, cf.brand_name, 
cf.event_type, cf.event_type_description, 
cf.description,
stpag.id as bank_recon_status,
stpag.descricao as bank_recon_description,
coalesce(cf.gross_amount, 0) gross_amount,
coalesce(cf.event_net_amount, 0) event_net_amount,
coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
case when ((coalesce(cf.event_net_amount, 0) > 0) and (coalesce(cc.valor_c, 0) > 0)) then
       ((1 - (coalesce(cf.event_net_amount, 0) / coalesce(cc.valor_c, 0))) * 100)
     else
       0
end tax,
cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number, 
emp.identificacao_emp, 
ctrl.codigo_ctrl, ctrl.nome_ctrl, 
ctrl2.codigo_ctrl as codigo_ctrl_tx, ctrl2.nome_ctrl as nome_ctrl_tx, 
ctrl2.n_conta_plc_tx_cartao, ctrl2.n_conta_plc_tarifa_cartao, 
cc.n_conta_plc, p.desc_plc, 
cc.cod_cred, cc.n_doc_v, cc.n_doc_c, cc.tp_doc_v, 
cc.valor_c, cc.valor_liquido, cc.valor_original, cc.data_rec_c, cc.data_venc_c, cc.status_c, cc.datq_c,
case when ((coalesce(cc.valor_liquido, 0) > 0) and (coalesce(cc.valor_c, 0) > 0)) then
        ((1 - (coalesce(cc.valor_liquido, 0) / coalesce(cc.valor_c, 0))) * 100)
     else
        0
end taxa_cred,
coalesce(cc.cod_cliente, 0) cod_cliente,
trim(case when (cc.cod_cliente > 0) then cl.nome_cliente else cc.nome_c end) nome_cliente, 
trim(case when (cc.cod_cliente > 0) then cl.razao else cc.razao end) razao,
cc.cod_terminal_adm, termc.desc_term_adm, cc.cod_adm, adm.descricao_adm, 
cc.cod_bandeira_adm, bande.descricao, credq.qtde_reg,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_status vwf
inner join conciliacao_financeiro cf on
    vwf.id = cf.id
    and vwf.installment_number = cf.installment_number
    and vwf.installments_total = cf.installments_total
    and vwf.cod_empresa = cf.cod_empresa
inner join empresa emp on 
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
    band_adq.codigo = cf.bandeira_cod
    and band_adq.id_adquirente = adq.id
left join conciliacao_bandeira band on
    band.id = band_adq.id_bandeira
left join conciliacao_cod_ajuste_adq codajt_adq on
    codajt_adq.codigo = cf.cod_ajuste_cod
    and codajt_adq.id_adquirente = adq.id
left join conciliacao_cod_ajuste codajt on
    codajt.id = codajt_adq.id_cod_ajuste
left join conciliacao_form_pag_adq formpag_adq on
    formpag_adq.codigo = cf.form_pag_cod
    and formpag_adq.id_adquirente = adq.id
left join conciliacao_form_pag formpag on
    formpag.id = formpag_adq.id_form_pag
left join conciliacao_grupo_cartao_adq grcartao_adq on
    grcartao_adq.codigo = cf.grupo_cartao_cod
    and grcartao_adq.id_adquirente = cf.acquirer_id
left join conciliacao_grupo_cartao grcartao on
    grcartao.id = grcartao_adq.id_grupo_cartao
left join conciliacao_motivo_rej_adq motrej_adq on
    motrej_adq.codigo = cf.motivo_rej_cod
    and motrej_adq.id_adquirente = adq.id
left join conciliacao_motivo_rej motrej on
    motrej.id = motrej_adq.id_motivo_rej
left join conciliacao_origem_ajuste_adq orig_transf_adq on
    orig_transf_adq.codigo = cf.origem_ajuste_cod
    and orig_transf_adq.id_adquirente = adq.id
left join conciliacao_origem_ajuste orig_transf on
    orig_transf.id = orig_transf_adq.id_origem_ajuste
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
left join conciliacao_status_transf_adq st_transf_adq on
    st_transf_adq.codigo = cf.status_transf_cod
    and st_transf_adq.id_adquirente = adq.id
left join conciliacao_status_transf st_transf on
    st_transf.id = st_transf_adq.id_status_transf
left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
    tpantec.id = tpantec_adq.id_tipo_antecip
left join conciliacao_tipo_cartao_adq tpcartao_adq on
    tpcartao_adq.codigo = cf.tipo_cartao_cod
    and tpcartao_adq.id_adquirente = adq.id
left join conciliacao_tipo_cartao tpcartao on
    tpcartao.id = tpcartao_adq.id_tipo_cartao
left join conciliacao_tipo_lanc_adq tplanc_adq on
    tplanc_adq.codigo = cf.tipo_lancamento_cod
    and tplanc_adq.id_aquirente = adq.id
left join conciliacao_tipo_lanc tplanc on
    tplanc.id = tplanc_adq.id_tipo_lanc
left join conciliacao_tipo_liq_adq tpliq_adq on
    tpliq_adq.codigo = cf.tipo_liquidacao_cod
    and tpliq_adq.id_adquirente = adq.id
left join conciliacao_tipo_liq tpliq on
    tpliq.id = tpliq_adq.id_tipo_liq
left join conciliacao_tipo_transacao_adq tptr_adq on
    tptr_adq.codigo = cf.tipo_transacao_cod
    and tptr_adq.id_adquirente = adq.id
left join conciliacao_tipo_transacao tptr on
    tptr.id = tptr_adq.id_tipo_transacao
left join p_contas p on
    p.n_conta_plc = (case when (cf.event_net_amount >= 0) then codajt.n_conta_plc_e else codajt.n_conta_plc_s end)
left join getcreditosemaberto_nsu_aut (
    trim(cf.nsu),
    trim(cf.authorization_number),
    iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)),
    cf.cod_empresa) credq on 1 = 1
inner join controle_creditos cc on
    cc.cod_cred = credq.cod_cred
    and cc.codigo_emp = credq.codigo_emp
left join terminal_cartao termc on
    termc.cod_term_adm = cc.cod_terminal_adm 
    and termc.cod_empresa = cc.cod_emp_mult 
left join adm_cartao adm on 
    adm.cod_adm = termc.cod_adm 
    and adm.cod_empresa = termc.cod_empresa 
left join bandeiras_cartao bande on
    bande.cod_bandeira = cc.cod_bandeira_adm
   and bande.cod_empresa = cc.cod_emp_mult
left join clientes cl on 
    cl.cod_cliente = cc.cod_cliente 
    and cl.cod_empresa = cc.cod_emp_mult 
left join retorna_ctrl_ag_conta (
    cf.branch_number,
    cf.account_number,
    cf.cod_empresa) ctrl on 1 = 1
left join controles ctrl2 on 
    ctrl2.codigo_ctrl = cc.codigo_ctrl 
    and ctrl2.codigo_emp = cc.codigo_emp 
where ((trim(cf.event_type_description) = 'Venda') or (trim(cf.event_type_description) like 'Antecipa%'))
and cf.pix_id is null
union
select case when (cf.payment_date is not null) then cf.payment_date else cf.date_ end data,
cf.date_, cf.request_date, cf.effected_date, cf.payment_date, cf.bank_shipping_date,
cf.id, cf.cod_empresa, cf.arquivo, cf.data_arquivo,
cf.establishment_number,
cf.nsu, cf.authorization_number,
cf.type_, cf.type_description, 
cf.acquirer_id, cf.acquirer_name, 
cf.brand_id, cf.brand_name, 
cf.event_type, cf.event_type_description, 
cf.description,
stpag.id as bank_recon_status,
stpag.descricao as bank_recon_description,
coalesce(cf.gross_amount, 0) gross_amount,
coalesce(cf.event_net_amount, 0) event_net_amount,
coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
case when ((coalesce(cf.event_net_amount, 0) > 0) and (coalesce(cc.valor_c, 0) > 0)) then
       ((1 - (coalesce(cf.event_net_amount, 0) / coalesce(cc.valor_c, 0))) * 100)
     else
       0
end tax,
cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number,
emp.identificacao_emp, 
ctrl.codigo_ctrl, ctrl.nome_ctrl, 
ctrl2.codigo_ctrl as codigo_ctrl_tx, ctrl2.nome_ctrl as nome_ctrl_tx, 
ctrl2.n_conta_plc_tx_cartao, ctrl2.n_conta_plc_tarifa_cartao, 
cc.n_conta_plc, p.desc_plc, 
cc.cod_cred, cc.n_doc_v, cc.n_doc_c, cc.tp_doc_v, 
cc.valor_c, cc.valor_liquido, cc.valor_original, cc.data_rec_c, cc.data_venc_c, cc.status_c, cc.datq_c,
case when ((coalesce(cc.valor_liquido, 0) > 0) and (coalesce(cc.valor_c, 0) > 0)) then
        ((1 - (coalesce(cc.valor_liquido, 0) / coalesce(cc.valor_c, 0))) * 100)
     else
        0
end taxa_cred,
coalesce(cc.cod_cliente, 0) cod_cliente,
trim(case when (cc.cod_cliente > 0) then cl.nome_cliente else cc.nome_c end) nome_cliente, 
trim(case when (cc.cod_cliente > 0) then cl.razao else cc.razao end) razao,
cc.cod_terminal_adm, termc.desc_term_adm, cc.cod_adm, adm.descricao_adm, 
cc.cod_bandeira_adm, bande.descricao, credq.qtde_reg,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_pix_status vwfp
inner join conciliacao_financeiro cf on
    vwfp.pix_id = cf.pix_id
    and vwfp.cod_empresa = cf.cod_empresa
inner join empresa emp on 
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
    band_adq.codigo = cf.bandeira_cod
    and band_adq.id_adquirente = adq.id
left join conciliacao_bandeira band on
    band.id = band_adq.id_bandeira
left join conciliacao_cod_ajuste_adq codajt_adq on
    codajt_adq.codigo = cf.cod_ajuste_cod
    and codajt_adq.id_adquirente = adq.id
left join conciliacao_cod_ajuste codajt on
    codajt.id = codajt_adq.id_cod_ajuste
left join conciliacao_form_pag_adq formpag_adq on
    formpag_adq.codigo = cf.form_pag_cod
    and formpag_adq.id_adquirente = adq.id
left join conciliacao_form_pag formpag on
    formpag.id = formpag_adq.id_form_pag
left join conciliacao_grupo_cartao_adq grcartao_adq on
    grcartao_adq.codigo = cf.grupo_cartao_cod
    and grcartao_adq.id_adquirente = cf.acquirer_id
left join conciliacao_grupo_cartao grcartao on
    grcartao.id = grcartao_adq.id_grupo_cartao
left join conciliacao_motivo_rej_adq motrej_adq on
    motrej_adq.codigo = cf.motivo_rej_cod
    and motrej_adq.id_adquirente = adq.id
left join conciliacao_motivo_rej motrej on
    motrej.id = motrej_adq.id_motivo_rej
left join conciliacao_origem_ajuste_adq orig_transf_adq on
    orig_transf_adq.codigo = cf.origem_ajuste_cod
    and orig_transf_adq.id_adquirente = adq.id
left join conciliacao_origem_ajuste orig_transf on
    orig_transf.id = orig_transf_adq.id_origem_ajuste
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
left join conciliacao_status_transf_adq st_transf_adq on
    st_transf_adq.codigo = cf.status_transf_cod
    and st_transf_adq.id_adquirente = adq.id
left join conciliacao_status_transf st_transf on
    st_transf.id = st_transf_adq.id_status_transf
left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
    tpantec.id = tpantec_adq.id_tipo_antecip
left join conciliacao_tipo_cartao_adq tpcartao_adq on
    tpcartao_adq.codigo = cf.tipo_cartao_cod
    and tpcartao_adq.id_adquirente = adq.id
left join conciliacao_tipo_cartao tpcartao on
    tpcartao.id = tpcartao_adq.id_tipo_cartao
left join conciliacao_tipo_lanc_adq tplanc_adq on
    tplanc_adq.codigo = cf.tipo_lancamento_cod
    and tplanc_adq.id_aquirente = adq.id
left join conciliacao_tipo_lanc tplanc on
    tplanc.id = tplanc_adq.id_tipo_lanc
left join conciliacao_tipo_liq_adq tpliq_adq on
    tpliq_adq.codigo = cf.tipo_liquidacao_cod
    and tpliq_adq.id_adquirente = adq.id
left join conciliacao_tipo_liq tpliq on
    tpliq.id = tpliq_adq.id_tipo_liq
left join conciliacao_tipo_transacao_adq tptr_adq on
    tptr_adq.codigo = cf.tipo_transacao_cod
    and tptr_adq.id_adquirente = adq.id
left join conciliacao_tipo_transacao tptr on
    tptr.id = tptr_adq.id_tipo_transacao
left join p_contas p on
    p.n_conta_plc = (case when (cf.event_net_amount >= 0) then codajt.n_conta_plc_e else codajt.n_conta_plc_s end)
left join getcreditosemaberto_nsu_aut (
    trim(cf.nsu),
    trim(cf.authorization_number),
    iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)),
    cf.cod_empresa) credq on 1 = 1
inner join controle_creditos cc on
    cc.cod_cred = credq.cod_cred
    and cc.codigo_emp = credq.codigo_emp
left join terminal_cartao termc on
    termc.cod_term_adm = cc.cod_terminal_adm 
    and termc.cod_empresa = cc.cod_emp_mult 
left join adm_cartao adm on 
    adm.cod_adm = termc.cod_adm 
    and adm.cod_empresa = termc.cod_empresa 
left join bandeiras_cartao bande on
    bande.cod_bandeira = cc.cod_bandeira_adm
   and bande.cod_empresa = cc.cod_emp_mult
left join clientes cl on 
    cl.cod_cliente = cc.cod_cliente 
    and cl.cod_empresa = cc.cod_emp_mult 
left join retorna_ctrl_ag_conta (
    cf.branch_number,
    cf.account_number,
    cf.cod_empresa) ctrl on 1 = 1
left join controles ctrl2 on
    ctrl2.codigo_ctrl = cc.codigo_ctrl 
    and ctrl2.codigo_emp = cc.codigo_emp 
where ((trim(cf.event_type_description) = 'Venda') or (trim(cf.event_type_description) like 'Antecipa%'))
and cf.pix_id is not null
union
select case when (cf.payment_date is not null) then cf.payment_date else cf.date_ end data,
cf.date_, cf.request_date, cf.effected_date, cf.payment_date, cf.bank_shipping_date,
cf.id, cf.cod_empresa, cf.arquivo, cf.data_arquivo,
cf.establishment_number,
cf.nsu, cf.authorization_number,
cf.type_, cf.type_description, 
cf.acquirer_id, cf.acquirer_name, 
cf.brand_id, cf.brand_name, 
cf.event_type, cf.event_type_description, 
cf.description,
stpag.id as bank_recon_status,
stpag.descricao as bank_recon_description,
coalesce(cf.gross_amount, 0) gross_amount,
coalesce(cf.event_net_amount, 0) event_net_amount,
coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
case when ((coalesce(cf.event_net_amount, 0) > 0) and (coalesce(cc.valor_c, 0) > 0)) then
       ((1 - (coalesce(cf.event_net_amount, 0) / coalesce(cc.valor_c, 0))) * 100)
     else
       0
end tax,
cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number,
emp.identificacao_emp, 
ctrl.codigo_ctrl, ctrl.nome_ctrl, 
ctrl2.codigo_ctrl as codigo_ctrl_tx, ctrl2.nome_ctrl as nome_ctrl_tx, 
ctrl2.n_conta_plc_tx_cartao, ctrl2.n_conta_plc_tarifa_cartao, 
cc.n_conta_plc, p.desc_plc, 
cc.cod_cred, cc.n_doc_v, cc.n_doc_c, cc.tp_doc_v, 
cc.valor_c, cc.valor_liquido, cc.valor_original, cc.data_rec_c, cc.data_venc_c, cc.status_c, cc.datq_c,
case when ((coalesce(cc.valor_liquido, 0) > 0) and (coalesce(cc.valor_c, 0) > 0)) then
        ((1 - (coalesce(cc.valor_liquido, 0) / coalesce(cc.valor_c, 0))) * 100)
     else
        0
end taxa_cred,
coalesce(cc.cod_cliente, 0) cod_cliente,
trim(case when (cc.cod_cliente > 0) then cl.nome_cliente else cc.nome_c end) nome_cliente, 
trim(case when (cc.cod_cliente > 0) then cl.razao else cc.razao end) razao,
cc.cod_terminal_adm, termc.desc_term_adm, cc.cod_adm, adm.descricao_adm, 
cc.cod_bandeira_adm, bande.descricao, credq.qtde_reg,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_status vwf
inner join conciliacao_financeiro cf on
    vwf.id = cf.id
    and vwf.installment_number = cf.installment_number
    and vwf.installments_total = cf.installments_total
    and vwf.cod_empresa = cf.cod_empresa
inner join empresa emp on
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
