left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
    tpantec.id = tpantec_adq.id_tipo_antecip
left join conciliacao_tipo_cartao_adq tpcartao_adq on
    tpcartao_adq.codigo = cf.tipo_cartao_cod
    and tpcartao_adq.id_adquirente = adq.id
left join conciliacao_tipo_cartao tpcartao on
    tpcartao.id = tpcartao_adq.id_tipo_cartao
left join conciliacao_tipo_lanc_adq tplanc_adq on
    tplanc_adq.codigo = cf.tipo_lancamento_cod
    and tplanc_adq.id_aquirente = adq.id
left join conciliacao_tipo_lanc tplanc on
    tplanc.id = tplanc_adq.id_tipo_lanc
left join conciliacao_tipo_liq_adq tpliq_adq on
    tpliq_adq.codigo = cf.tipo_liquidacao_cod
    and tpliq_adq.id_adquirente = adq.id
left join conciliacao_tipo_liq tpliq on
    tpliq.id = tpliq_adq.id_tipo_liq
left join conciliacao_tipo_transacao_adq tptr_adq on
    tptr_adq.codigo = cf.tipo_transacao_cod
    and tptr_adq.id_adquirente = adq.id
left join conciliacao_tipo_transacao tptr on
    tptr.id = tptr_adq.id_tipo_transacao
left join p_contas p on
    p.n_conta_plc = (case when (cf.event_net_amount >= 0) then codajt.n_conta_plc_e else codajt.n_conta_plc_s end)
left join getcreditosemaberto_nsu_aut (
    trim(cf.nsu),
    trim(cf.authorization_number),
    iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)),
    cf.cod_empresa) credq on 1 = 1
inner join controle_creditos cc on
    cc.cod_cred = credq.cod_cred
    and cc.codigo_emp = credq.codigo_emp
left join terminal_cartao termc on 
    termc.cod_term_adm = cc.cod_terminal_adm 
    and termc.cod_empresa = cc.cod_emp_mult 
left join adm_cartao adm on 
    adm.cod_adm = termc.cod_adm 
    and adm.cod_empresa = termc.cod_empresa 
left join bandeiras_cartao bande on
    bande.cod_bandeira = cc.cod_bandeira_adm
   and bande.cod_empresa = cc.cod_emp_mult
left join clientes cl on 
    cl.cod_cliente = cc.cod_cliente 
    and cl.cod_empresa = cc.cod_emp_mult 
left join retorna_ctrl_ag_conta (
    cf.branch_number,
    cf.account_number,
    cf.cod_empresa) ctrl on 1 = 1
left join controles ctrl2 on
    ctrl2.codigo_ctrl = cc.codigo_ctrl 
    and ctrl2.codigo_emp = cc.codigo_emp 
where trim(cf.event_type_description) in  ('Cancelamento', 'Chargeback')
union
select case when (cf.payment_date is not null) then cf.payment_date else cf.date_ end data,
cf.date_, cf.request_date, cf.effected_date, cf.payment_date, cf.bank_shipping_date,
cf.id, cf.cod_empresa, cf.arquivo, cf.data_arquivo,
cf.establishment_number,
cf.nsu, cf.authorization_number,
cf.type_, cf.type_description, 
cf.acquirer_id, cf.acquirer_name, 
cf.brand_id, cf.brand_name, 
cf.event_type, cf.event_type_description, 
cf.description,
stpag.id as bank_recon_status,
stpag.descricao as bank_recon_description,
coalesce(cf.gross_amount, 0) gross_amount,
coalesce(cf.event_net_amount, 0) event_net_amount,
coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
cf.tax, cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number,
emp.identificacao_emp, 
ctrl.codigo_ctrl, ctrl.nome_ctrl, 
null codigo_ctrl_tx, null nome_ctrl_tx,
null n_conta_plc_tx_cartao, null n_conta_plc_tarifa_cartao,
p.n_conta_plc, p.desc_plc,
null cod_cred, null n_doc_v, null n_doc_c, null tp_doc_v,
null valor_c, null valor_liquido, null valor_original, null data_rec_c, null data_venc_c, null status_c, null datq_c, null taxa_cred,
null cod_cliente, null nome_cliente, null razao,
null cod_terminal_adm, null desc_term_adm, null cod_adm, null descricao_adm,
null cod_bandeira_adm, null descricao, null qtde_reg,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
