cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
