coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
cf.tax, cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number,
emp.identificacao_emp, 
ctrl.codigo_ctrl, ctrl.nome_ctrl, 
null codigo_ctrl_tx, null  nome_ctrl_tx,
null n_conta_plc_tx_cartao, null n_conta_plc_tarifa_cartao,
p.n_conta_plc, p.desc_plc,
null cod_cred, null n_doc_v, null n_doc_c, null tp_doc_v,
null valor_c, null valor_liquido, null valor_original, null data_rec_c, null data_venc_c, null status_c, null datq_c, null taxa_cred,
null cod_cliente, null nome_cliente, null razao,
null cod_terminal_adm, null desc_term_adm, null cod_adm, null descricao_adm,
null cod_bandeira_adm, null descricao, null qtde_reg,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_status vwf
inner join conciliacao_financeiro cf on
    vwf.id = cf.id
    and vwf.installment_number = cf.installment_number
    and vwf.installments_total = cf.installments_total
    and vwf.cod_empresa = cf.cod_empresa
inner join empresa emp on
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
    band_adq.codigo = cf.bandeira_cod
    and band_adq.id_adquirente = adq.id
left join conciliacao_bandeira band on
    band.id = band_adq.id_bandeira
left join conciliacao_cod_ajuste_adq codajt_adq on
    codajt_adq.codigo = cf.cod_ajuste_cod
    and codajt_adq.id_adquirente = adq.id
left join conciliacao_cod_ajuste codajt on
    codajt.id = codajt_adq.id_cod_ajuste
left join conciliacao_form_pag_adq formpag_adq on
    formpag_adq.codigo = cf.form_pag_cod
    and formpag_adq.id_adquirente = adq.id
left join conciliacao_form_pag formpag on
    formpag.id = formpag_adq.id_form_pag
left join conciliacao_grupo_cartao_adq grcartao_adq on
    grcartao_adq.codigo = cf.grupo_cartao_cod
    and grcartao_adq.id_adquirente = cf.acquirer_id
left join conciliacao_grupo_cartao grcartao on
    grcartao.id = grcartao_adq.id_grupo_cartao
left join conciliacao_motivo_rej_adq motrej_adq on
    motrej_adq.codigo = cf.motivo_rej_cod
    and motrej_adq.id_adquirente = adq.id
left join conciliacao_motivo_rej motrej on
    motrej.id = motrej_adq.id_motivo_rej
left join conciliacao_origem_ajuste_adq orig_transf_adq on
    orig_transf_adq.codigo = cf.origem_ajuste_cod
    and orig_transf_adq.id_adquirente = adq.id
left join conciliacao_origem_ajuste orig_transf on
    orig_transf.id = orig_transf_adq.id_origem_ajuste
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
left join conciliacao_status_transf_adq st_transf_adq on
    st_transf_adq.codigo = cf.status_transf_cod
    and st_transf_adq.id_adquirente = adq.id
left join conciliacao_status_transf st_transf on
    st_transf.id = st_transf_adq.id_status_transf
left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
    tpantec.id = tpantec_adq.id_tipo_antecip
left join conciliacao_tipo_cartao_adq tpcartao_adq on
    tpcartao_adq.codigo = cf.tipo_cartao_cod
    and tpcartao_adq.id_adquirente = adq.id
left join conciliacao_tipo_cartao tpcartao on
    tpcartao.id = tpcartao_adq.id_tipo_cartao
left join conciliacao_tipo_lanc_adq tplanc_adq on
    tplanc_adq.codigo = cf.tipo_lancamento_cod
    and tplanc_adq.id_aquirente = adq.id
left join conciliacao_tipo_lanc tplanc on
    tplanc.id = tplanc_adq.id_tipo_lanc
left join conciliacao_tipo_liq_adq tpliq_adq on
    tpliq_adq.codigo = cf.tipo_liquidacao_cod
    and tpliq_adq.id_adquirente = adq.id
left join conciliacao_tipo_liq tpliq on
    tpliq.id = tpliq_adq.id_tipo_liq
left join conciliacao_tipo_transacao_adq tptr_adq on
    tptr_adq.codigo = cf.tipo_transacao_cod
    and tptr_adq.id_adquirente = adq.id
left join conciliacao_tipo_transacao tptr on
    tptr.id = tptr_adq.id_tipo_transacao
left join p_contas p on
    p.n_conta_plc = (case when (cf.event_net_amount >= 0) then codajt.n_conta_plc_e else codajt.n_conta_plc_s end)
left join retorna_ctrl_ag_conta (
    cf.branch_number,
    cf.account_number,
    cf.cod_empresa) ctrl on 1 = 1
where trim(cf.event_type_description) = 'Ajuste' and coalesce(cf.event_net_amount, 0) < 0
and (select count(*) from contas_a_pagar ctp
     where ctp.id_financ_confere = cf.id
     and ctp.cod_emp_mult = cf.cod_empresa
     and ctp.datq_ctp is not null) = 0
;

/* View: VW_TABELA_PRECOS, Owner: SYSDBA */
CREATE VIEW VW_TABELA_PRECOS (COD_PROMOCAO, COD_TPPRECO, COD_EMPRESA, DESCR_PROMOCAO, ORDEM, TIPO, DETALHE, GRUPO_PROD, COD_PROD, DESCR_PROD, PREC_CUSM_PROD, PREC_TAB_PROD, COD_LOCALIDADE, COD_SETOR, COD_CIDADE, PORCENTAGEM, VALOR_PROMOCAO, PROPORCAO_TABELA, MARKUP) AS

select COD_PROMOCAO, COD_TPPRECO, COD_EMPRESA, DESCR_PROMOCAO, ORDEM, TIPO, DETALHE, GRUPO_PROD, COD_PROD, DESCR_PROD,
       PREC_CUSM_PROD, PREC_TAB_PROD, COD_LOCALIDADE, COD_SETOR, COD_CIDADE, PORCENTAGEM, VALOR_PROMOCAO, PROPORCAO_TABELA, MARKUP
from (
  select
  pm.cod_promocao, pm.cod_tppreco, pm.cod_empresa, pm.descr_promocao, pm.ordem,
  case when l.cod_localidade is not null then 'LOCALIDADE'
       when s.cod_setor is not null then 'SETOR'
       when c.cod_cidade is not null then 'CIDADE'
       when pp.cod_tppreco = 1 then 'PROMOCAO'
    else
      'AVULSA'
  end tipo,
  case when l.cod_localidade is not null then l.localidade
       when s.cod_setor is not null then s.setor
       when c.cod_cidade is not null then c.nome_cidade
    else
      pm.descr_promocao
  end detalhe,
  pr.grupo_prod,  pr.cod_prod, pr.descr_prod, pr.prec_cusm_prod, pr.prec_tab_prod,
  pp.cod_localidade, pp.cod_setor, pp.cod_cidade, pp.porcentagem,
  case
    when (coalesce(pp.valor_promocao, 0) = 0) and (pp.cod_tppreco = 1) and (pp.porcentagem <> 0) then
      pr.prec_tab_prod * (1 - abs(pp.porcentagem) / 100)
    else pp.valor_promocao
  end valor_promocao, pp.PROPORCAO_TABELA, pp.markup
  from promocao_produto pp
  inner join promocao  pm on pm.cod_promocao = pp.cod_promocao and pm.cod_tppreco = pp.cod_tppreco and pm.cod_empresa = pp.cod_empresa
  inner join produtos pr on pr.grupo_prod = pp.grupo_prod and pr.cod_prod = pp.cod_prod and pr.cod_empresa = pp.cod_empresa
  left join localidade l on l.cod_localidade = pp.cod_localidade and l.cod_empresa = pp.cod_empresa
  left join setor s on s.cod_setor = pp.cod_setor and s.cod_empresa = pp.cod_empresa
  left join cidades c on c.cod_cidade = pp.cod_cidade and c.cod_cidade > 0
  where pm.ativo = 1
) as q
;

/* View: MAPA_REC, Owner: SYSDBA */
CREATE VIEW MAPA_REC (N_CONTA_PLC, DESC_PLC, VALOR_L, DESC_GR, TIPO_GR, HISTORICO_L, DATA, GRUP_CT, COD_LANC, COD_DEP, MES_MAPA, DESC_P) AS

select p.n_conta_plc,p.desc_plc,l.valor_l,c.desc_gr,c.tipo_gr,
       l.historico_l,l.data,p.grup_ct,l.cod_lanc,c.cod_dep,extract(month from l.data),p.desc_padr
       from Lancamentos l RIGHT JOIN p_contas p ON l.n_conta_plc = p.n_conta_plc and l.lote is null
       INNER JOIN GRUPOS_CT c on
       p.grup_ct = c.grup_ct and (c.tipo_gr = 'E') WHERE p.ativo = 1
;

/* View: MAPA_DESP_T, Owner: SYSDBA */
CREATE VIEW MAPA_DESP_T (N_CONTA_PLC, DESC_PLC, VALOR_L, DESC_GR, TIPO_GR, HISTORICO_L, DATA, GRUP_CT, COD_LANC, COD_DEP, MES_MAPA, DESC_P) AS

select p.n_conta_plc,p.desc_plc,l.valor_l,c.desc_gr,c.tipo_gr,
       l.historico_l,l.data,p.grup_ct,l.cod_lanc,c.cod_dep,extract(month from l.data),p.desc_padr
       from Lancamentos l RIGHT JOIN p_contas p ON l.n_conta_plc = p.n_conta_plc and l.lote is null
       INNER JOIN GRUPOS_CT c on
       p.grup_ct = c.grup_ct and (c.tipo_gr = 'S' or (c.desc_gr like '%INVEST%'))
union
select P.n_conta_plc,p.desc_plc,
       ctr.valor_pago,c.desc_gr,c.tipo_gr,ctr.historico_ctp,
       ctr.datq_ctp,p.grup_ct,ctr.cod_contrp,c.cod_dep,extract(month from ctr.datq_ctp),p.desc_padr
       from contas_a_pagar ctr RIGHT JOIN p_contas p ON ctr.n_conta_plc = p.n_conta_plc and ctr.lote is not null
       INNER JOIN grupos_ct c ON p.grup_ct = c.grup_ct and
       (c.tipo_gr = 'S' or (c.desc_gr like '%INVEST%'))
;

/* View: NOTAFISCAL_DANFE, Owner: SYSDBA */
CREATE VIEW NOTAFISCAL_DANFE (COD_NF, COD_EMPRESA, NATUREZA_NF, DESC_NATUREZA_NF, NUM_NF, SERIE, MODELO_NF, TIPO_NF, STATUS, SITUACAO_NFE, EMISSAO_PROPRIA, DATA_LANC, DATA_EMISSAO, DATA_ENTRADA_SAIDA, CHAVE_NFE, NPED, TIPO_PED, STATUS_PED, COD_RASTREAMENTO, COD_FORMA_RAST, DESCR_FORM_RAST, DATA_ENVIO_RAST, VALOR_TOTAL, VALOR_PROD, VALOR_SERV, VALOR_FRETE, IDMOBILE, ID_COMMERCE, LOCAL_VENDA, STATUS_EC, METODO_ENTREGA, RAZAO_EMP, FANTASIA_EMP, IDENTIFICACAO_EMP, CPFCGC_EMP, ENDERECO_COMPL_EMP, ENDERECO_EMP, NUMERO_END, COMPLEMENTO_EMP, BAIRRO_EMP, CIDADE_EMP, UF_EMP, CEP_EMP, TELEFONE_EMP, EMAIL_EMP, IE_EMP, IM_EMP, COD_CL, NOME_CL, RAZAO_CL, CPFCGC_CL, CEP_CL, TELEFONE_CL, CELULAR_CL, EMAIL_CL, ENDERECO_COMPL_CL, ENDERECO_CL, CIDADE_CL, BAIRRO_CL, UF_CL, COMPLEMENTO_CL, NUM_END_CL, QTDE_VOLUMES_TR, FRETECONTA_TR, COD_TR, NOME_TR, CNPJ_TR, END_COMPL_TR, END_TR, MUNICIPIO_TR, UF_TR, IE_TR, PESO_B_NF, PESO_L_NF, PESO_B_PROD, PESO_L_PROD) AS

SELECT NOTAFISCAL.COD_NF, NOTAFISCAL.COD_EMPRESA,
NOTAFISCAL.NATUREZA_NF,
CASE WHEN (NOTAFISCAL.NATUREZA_NF = 'S') then 'SAIDA' else 'ENTRADA' END DESC_NATUREZA_NF,
NOTAFISCAL.NUM_NF, NOTAFISCAL.SERIE,
NOTAFISCAL.MODELO_NF, NOTAFISCAL.TIPO_NF, NOTAFISCAL.EMISSAO_PROPRIA,
NOTAFISCAL.STATUS, NOTAFISCAL.SITUACAO_NFE, NOTAFISCAL.DATA_LANC, NOTAFISCAL.DATA_CONTABIL, NOTAFISCAL.DATA_ENT_SAIDA,
NOTAFISCAL.CHAVE_NFE,
NOTAFISCAL.NPED, NOTAFISCAL.TIPO_PED, PEDVENDA.STATUS_PED,
PEDVENDA.COD_RASTREAMENTO,
PEDVENDA.COD_FORMA_RAST,
FORMAS_ENVIO_EC.DESCRICAO AS DESCR_FORM_RAST,
PEDVENDA.DATA_ENVIO_RAST,
NOTAFISCAL.VALOR_TOTAL, NOTAFISCAL.VALOR_PROD, NOTAFISCAL.VALOR_SERV, NOTAFISCAL.VALOR_FRETE,
PEDVENDA.IDMOBILE,
PEDVENDA.ID_COMMERCE,
PEDVENDA.LOCAL_VENDA,
PEDVENDA.STATUS_EC,
PEDVENDA.METODO_ENTREGA,
EMPRESA.NOME_EMP,
EMPRESA.FANTASIA_EMP,
EMPRESA.IDENTIFICACAO_EMP,
EMPRESA.CGC_EMP,
(coalesce(EMPRESA.ENDRECO_EMP, '') ||
    iif(coalesce(EMPRESA.NUMERO_END, 0) > 0, ', N: ' || coalesce(EMPRESA.NUMERO_END, 0), '') ||
    iif((trim(coalesce(EMPRESA.COMPLEMENTO_EMP, '')) <> ''), ', ' || trim(coalesce(EMPRESA.COMPLEMENTO_EMP, '')), '') ||
    iif(trim(coalesce(EMPRESA.CEP_EMP, '')) <> '', ', ' || trim(coalesce(EMPRESA.CEP_EMP, '')), '') ||
    iif(trim(coalesce(EMPRESA.BAIRRO_EMP, '')) <> '', ', ' || trim(coalesce(EMPRESA.BAIRRO_EMP, '')), '') ||
    iif(trim(coalesce(EMPRESA.CIDADE_EMP, '')) <> '', ', ' || trim(coalesce(EMPRESA.CIDADE_EMP, '')), '') ||
    iif(trim(coalesce(ESTEMP.SIGLA_UF, '')) <> '', ', ' || trim(coalesce(ESTEMP.SIGLA_UF, '')), '')
) ENDERECO_COMPL_EMP,
EMPRESA.ENDRECO_EMP,
EMPRESA.NUMERO_END,
EMPRESA.COMPLEMENTO_EMP,
EMPRESA.BAIRRO_EMP,
EMPRESA.CIDADE_EMP,
ESTEMP.SIGLA_UF UF_EMP,
EMPRESA.CEP_EMP,
EMPRESA.TELEFONE_EMP,
EMPRESA.EMAIL_EMP,
EMPRESA.IE_EMP,
EMPRESA.IM_EMP,
NOTAFISCAL.COD_CLIENTE,
CLIENTES.NOME_CLIENTE,
CLIENTES.RAZAO,
CLIENTES.CPFCGC,
CLIENTES.CEP,
CLIENTES.FONE_CLIENTE,
CLIENTES.FONE_CELULAR,
CLIENTES.EMAIL,
(coalesce(CLIENTES.ENDERECO, '') ||
    iif(trim(coalesce(CLIENTES.NUM_END_CLIENTE, '')) <> '', ', N: ' || trim(coalesce(CLIENTES.NUM_END_CLIENTE, '')), '') ||
    iif((trim(coalesce(CLIENTES.COMPLEMENTO, '')) <> ''), ', ' || trim(coalesce(CLIENTES.COMPLEMENTO, '')), '') ||
    iif(trim(coalesce(CLIENTES.CEP, '')) <> '', ', ' || trim(coalesce(CLIENTES.CEP, '')), '') ||
    iif(trim(coalesce(BAICL.NOME_BAIRRO, '')) <> '', ', ' || trim(coalesce(BAICL.NOME_BAIRRO, '')), '') ||
    iif(trim(coalesce(CIDCL.NOME_CIDADE, '')) <> '', ', ' || trim(coalesce(CIDCL.NOME_CIDADE, '')), '') ||
    iif(trim(coalesce(ESTEMP.SIGLA_UF, '')) <> '', ', ' || trim(coalesce(ESTEMP.SIGLA_UF, '')), '')
) ENDERECO_COMPL_CL,
CLIENTES.ENDERECO,
CIDCL.NOME_CIDADE CIDADE_CL,
BAICL.NOME_BAIRRO BAIRRO_CL,
ESTCL.SIGLA_UF UF_CL,
CLIENTES.COMPLEMENTO,
CLIENTES.NUM_END_CLIENTE,
NOTAFISCAL.CODIGO_TR,
TRANSPORTADOR.NOME_TR,
TRANSPORTADOR.CNPJ_TR,
(coalesce(TRANSPORTADOR.END_TR, '') ||
    iif(trim(coalesce(TRANSPORTADOR.MUNICIPIO_TR, '')) <> '', ', ' || trim(coalesce(TRANSPORTADOR.MUNICIPIO_TR, '')), '') ||
    iif(trim(coalesce(ESTTR.SIGLA_UF, '')) <> '', ', ' || trim(coalesce(ESTTR.SIGLA_UF, '')), '')
) END_COMPL_TR,
TRANSPORTADOR.END_TR,
TRANSPORTADOR.MUNICIPIO_TR,
ESTTR.SIGLA_UF UF_TR,
TRANSPORTADOR.IE_TR,
NOTAFISCAL.QTDE_VOLUMES_TR,
NOTAFISCAL.FRETECONTA_TR,
COALESCE((SELECT SUM(COALESCE(NOTAFISCAL_ITEM.PESO_B, 0)) FROM NOTAFISCAL_ITEM
          WHERE NOTAFISCAL_ITEM.COD_NF = NOTAFISCAL.COD_NF
          AND NOTAFISCAL_ITEM.COD_EMPRESA = NOTAFISCAL.COD_EMPRESA), 0) PESO_B_NF,
COALESCE((SELECT SUM(COALESCE(NOTAFISCAL_ITEM.PESO_L, 0)) FROM NOTAFISCAL_ITEM
          WHERE NOTAFISCAL_ITEM.COD_NF = NOTAFISCAL.COD_NF
          AND NOTAFISCAL_ITEM.COD_EMPRESA = NOTAFISCAL.COD_EMPRESA), 0) PESO_L_NF,
COALESCE((SELECT SUM(COALESCE(PRODUTOS.PESO_BRUT_PROD, 0) * COALESCE(NOTAFISCAL_ITEM.QUANTIDADE, 0)) FROM NOTAFISCAL_ITEM
          INNER JOIN PRODUTOS ON
            PRODUTOS.GRUPO_PROD = NOTAFISCAL_ITEM.GRUPO_PROD
            AND PRODUTOS.COD_PROD = NOTAFISCAL_ITEM.COD_PROD
            AND PRODUTOS.COD_EMPRESA = NOTAFISCAL_ITEM.COD_EMPRESA
          WHERE NOTAFISCAL_ITEM.COD_NF = NOTAFISCAL.COD_NF
          AND NOTAFISCAL_ITEM.COD_EMPRESA = NOTAFISCAL.COD_EMPRESA), 0) PESO_B_PROD,
COALESCE((SELECT SUM(COALESCE(PRODUTOS.PESO_LIQ_PROD, 0) * COALESCE(NOTAFISCAL_ITEM.QUANTIDADE, 0)) FROM NOTAFISCAL_ITEM
          INNER JOIN PRODUTOS ON
            PRODUTOS.GRUPO_PROD = NOTAFISCAL_ITEM.GRUPO_PROD
            AND PRODUTOS.COD_PROD = NOTAFISCAL_ITEM.COD_PROD
            AND PRODUTOS.COD_EMPRESA = NOTAFISCAL_ITEM.COD_EMPRESA
          WHERE NOTAFISCAL_ITEM.COD_NF = NOTAFISCAL.COD_NF
          AND NOTAFISCAL_ITEM.COD_EMPRESA = NOTAFISCAL.COD_EMPRESA), 0) PESO_L_PROD FROM NOTAFISCAL
LEFT JOIN EMPRESA ON
  EMPRESA.COD_EMPRESA = NOTAFISCAL.COD_EMPRESA
LEFT JOIN ESTADOS ESTEMP ON
  ESTEMP.CODIGO_UF = EMPRESA.UF_EMP
LEFT JOIN CLIENTES ON
  CLIENTES.COD_CLIENTE = NOTAFISCAL.COD_CLIENTE
  AND CLIENTES.COD_EMPRESA = NOTAFISCAL.COD_EMPRESA
LEFT JOIN CIDADES CIDCL ON
  CIDCL.COD_CIDADE = CLIENTES.COD_CIDADE
LEFT JOIN BAIRROS BAICL ON
  BAICL.COD_BAIRRO = CLIENTES.COD_BAIRRO
LEFT JOIN ESTADOS ESTCL ON
  ESTCL.CODIGO_UF = CLIENTES.CODIGO_UF
LEFT JOIN TRANSPORTADOR ON
  TRANSPORTADOR.CODIGO_TR = NOTAFISCAL.CODIGO_TR
  AND TRANSPORTADOR.COD_EMPRESA = NOTAFISCAL.COD_EMPRESA
LEFT JOIN ESTADOS ESTTR ON
  ESTTR.CODIGO_UF = TRANSPORTADOR.UF_TR
LEFT JOIN PEDVENDA ON
  PEDVENDA.NPED = NOTAFISCAL.NPED
  AND PEDVENDA.TIPO = NOTAFISCAL.TIPO_PED
  AND PEDVENDA.COD_EMPRESA = NOTAFISCAL.COD_EMPRESA
LEFT JOIN FORMAS_ENVIO_EC ON
  FORMAS_ENVIO_EC.COD_FORMA = PEDVENDA.COD_FORMA_RAST
  AND FORMAS_ENVIO_EC.COD_EMPRESA = PEDVENDA.COD_EMPRESA
;

/* View: VW_CONCILIACAO_FINANCEIRO_REC, Owner: SYSDBA */
CREATE VIEW VW_CONCILIACAO_FINANCEIRO_REC (DATA, DATE_, REQUEST_DATE, EFFECTED_DATE, PAYMENT_DATE, BANK_SHIPPING_DATE, ID, COD_EMPRESA, ARQUIVO, DATA_ARQUIVO, ESTABLISHMENT_NUMBER, NSU, AUTHORIZATION_NUMBER, TYPE_, TYPE_DESCRIPTION, ACQUIRER_ID, ACQUIRER_NAME, BRAND_ID, BRAND_NAME, EVENT_TYPE, EVENT_TYPE_DESCRIPTION, DESCRIPTION, BANK_RECON_STATUS, BANK_RECON_DESCRIPTION, GROSS_AMOUNT, EVENT_NET_AMOUNT, BATCH_NET_AMOUNT, GROSS_EVENT_AMOUNT, BATCH_GROSS_AMOUNT, TAX, SALE_TAX, CUSTOMER_TAX, INSTALLMENT_NUMBER, INSTALLMENTS_TOTAL, BANK_NUMBER, BANK_NAME, BRANCH_NUMBER, ACCOUNT_NUMBER, IDENTIFICACAO_EMP, CODIGO_CTRL, NOME_CTRL, CODIGO_CTRL_TX, NOME_CTRL_TX, N_CONTA_PLC_TX_CARTAO, N_CONTA_PLC_TARIFA_CARTAO, N_CONTA_PLC, DESC_PLC, COD_CRED, N_DOC_V, N_DOC_C, TP_DOC_V, VALOR_C, VALOR_LIQUIDO, VALOR_ORIGINAL, DATA_REC_C, DATA_VENC_C, STATUS_C, DATQ_C, TAXA_CRED, COD_CLIENTE, NOME_CLIENTE, RAZAO, COD_TERMINAL_ADM, DESC_TERM_ADM, COD_ADM, DESCRICAO_ADM, COD_BANDEIRA_ADM, DESC_BANDEIRA_ADM, PIX_ID, FORM_PAG_COD, FORM_PAG, COD_AJUSTE_COD, COD_AJUSTE, BANDEIRA_COD, BANDEIRA, STATUS_PAG_COD, STATUS_PAG, STATUS_PAG_ST, TIPO_LANCAMENTO_COD, TIPO_LANCAMENTO, TIPO_LIQUIDACAO_COD, TIPO_LIQUIDACAO, TIPO_ANTECIPACAO_COD, TIPO_ANTECIPACAO, TIPO_CARTAO_COD, TIPO_CARTAO, MOTIVO_REJ_COD, MOTIVO_REJ, GRUPO_CARTAO_COD, GRUPO_CARTAO, TIPO_TRANSACAO_COD, TIPO_TRANSACAO, STATUS_TRANSF_COD, STATUS_TRANSF, STATUS_TRANSF_ST, ORIGEM_AJUSTE_COD, ORIGEM_AJUSTE) AS

select case when (cf.payment_date is not null) then cf.payment_date else cf.date_ end data,
cf.date_, cf.request_date, cf.effected_date, cf.payment_date, cf.bank_shipping_date,
cf.id, cf.cod_empresa, cf.arquivo, cf.data_arquivo,
cf.establishment_number,
cf.nsu, cf.authorization_number,
cf.type_, cf.type_description,
cf.acquirer_id, cf.acquirer_name,
cf.brand_id, cf.brand_name,
cf.event_type, cf.event_type_description,
cf.description,
stpag.id as bank_recon_status,
stpag.descricao as bank_recon_description,
coalesce(cf.gross_amount, 0) gross_amount,
coalesce(cf.event_net_amount, 0) event_net_amount,
coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
case when ((coalesce(cf.event_net_amount, 0) > 0) and (coalesce(cc.valor_c, 0) > 0)) then
       ((1 - (coalesce(cf.event_net_amount, 0) / coalesce(cc.valor_c, 0))) * 100)
     else
       0
end tax,
cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number,
emp.identificacao_emp,
ctrl.codigo_ctrl, ctrl.nome_ctrl,
ctrl2.codigo_ctrl as codigo_ctrl_tx, ctrl2.nome_ctrl as nome_ctrl_tx,
ctrl2.n_conta_plc_tx_cartao, ctrl2.n_conta_plc_tarifa_cartao,
cc.n_conta_plc, p.desc_plc,
cc.cod_cred, cc.n_doc_v, cc.n_doc_c, cc.tp_doc_v,
cc.valor_c, cc.valor_liquido, cc.valor_original, cc.data_rec_c, cc.data_venc_c, cc.status_c, cc.datq_c,
case when ((coalesce(cc.valor_liquido, 0) > 0) and (coalesce(cc.valor_c, 0) > 0)) then
        ((1 - (coalesce(cc.valor_liquido, 0) / coalesce(cc.valor_c, 0))) * 100)
     else
        0
end taxa_cred,
coalesce(cc.cod_cliente, 0) cod_cliente,
trim(case when (cc.cod_cliente > 0) then cl.nome_cliente else cc.nome_c end) nome_cliente,
trim(case when (cc.cod_cliente > 0) then cl.razao else cc.razao end) razao,
cc.cod_terminal_adm, termc.desc_term_adm, cc.cod_adm, adm.descricao_adm,
cc.cod_bandeira_adm, bande.descricao,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_status vwf
inner join conciliacao_financeiro cf on
    vwf.id = cf.id
    and vwf.installment_number = cf.installment_number
    and vwf.installments_total = cf.installments_total
    and vwf.cod_empresa = cf.cod_empresa
inner join empresa emp on
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
    band_adq.codigo = cf.bandeira_cod
    and band_adq.id_adquirente = adq.id
left join conciliacao_bandeira band on
    band.id = band_adq.id_bandeira
left join conciliacao_cod_ajuste_adq codajt_adq on
    codajt_adq.codigo = cf.cod_ajuste_cod
    and codajt_adq.id_adquirente = adq.id
left join conciliacao_cod_ajuste codajt on
    codajt.id = codajt_adq.id_cod_ajuste
left join conciliacao_form_pag_adq formpag_adq on
    formpag_adq.codigo = cf.form_pag_cod
    and formpag_adq.id_adquirente = adq.id
left join conciliacao_form_pag formpag on
    formpag.id = formpag_adq.id_form_pag
left join conciliacao_grupo_cartao_adq grcartao_adq on
    grcartao_adq.codigo = cf.grupo_cartao_cod
    and grcartao_adq.id_adquirente = cf.acquirer_id
left join conciliacao_grupo_cartao grcartao on
    grcartao.id = grcartao_adq.id_grupo_cartao
left join conciliacao_motivo_rej_adq motrej_adq on
    motrej_adq.codigo = cf.motivo_rej_cod
    and motrej_adq.id_adquirente = adq.id
left join conciliacao_motivo_rej motrej on
    motrej.id = motrej_adq.id_motivo_rej
left join conciliacao_origem_ajuste_adq orig_transf_adq on
    orig_transf_adq.codigo = cf.origem_ajuste_cod
    and orig_transf_adq.id_adquirente = adq.id
left join conciliacao_origem_ajuste orig_transf on
    orig_transf.id = orig_transf_adq.id_origem_ajuste
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
left join conciliacao_status_transf_adq st_transf_adq on
    st_transf_adq.codigo = cf.status_transf_cod
    and st_transf_adq.id_adquirente = adq.id
left join conciliacao_status_transf st_transf on
    st_transf.id = st_transf_adq.id_status_transf
left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
    tpantec.id = tpantec_adq.id_tipo_antecip
left join conciliacao_tipo_cartao_adq tpcartao_adq on
    tpcartao_adq.codigo = cf.tipo_cartao_cod
    and tpcartao_adq.id_adquirente = adq.id
left join conciliacao_tipo_cartao tpcartao on
    tpcartao.id = tpcartao_adq.id_tipo_cartao
left join conciliacao_tipo_lanc_adq tplanc_adq on
    tplanc_adq.codigo = cf.tipo_lancamento_cod
    and tplanc_adq.id_aquirente = adq.id
left join conciliacao_tipo_lanc tplanc on
    tplanc.id = tplanc_adq.id_tipo_lanc
left join conciliacao_tipo_liq_adq tpliq_adq on
    tpliq_adq.codigo = cf.tipo_liquidacao_cod
    and tpliq_adq.id_adquirente = adq.id
left join conciliacao_tipo_liq tpliq on
    tpliq.id = tpliq_adq.id_tipo_liq
left join conciliacao_tipo_transacao_adq tptr_adq on
    tptr_adq.codigo = cf.tipo_transacao_cod
    and tptr_adq.id_adquirente = adq.id
left join conciliacao_tipo_transacao tptr on
    tptr.id = tptr_adq.id_tipo_transacao
left join p_contas p on
    p.n_conta_plc = (case when (cf.event_net_amount >= 0) then codajt.n_conta_plc_e else codajt.n_conta_plc_s end)
left join getcreditosquitados(
    trim(cf.nsu),
    trim(cf.authorization_number),
    iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)),
    cf.cod_empresa) credq on 1 = 1
inner join controle_creditos cc on
    cc.cod_cred = credq.cod_cred
    and cc.codigo_emp = credq.codigo_emp
left join terminal_cartao termc on
    termc.cod_term_adm = cc.cod_terminal_adm
    and termc.cod_empresa = cc.cod_emp_mult
left join adm_cartao adm on
    adm.cod_adm = termc.cod_adm
    and adm.cod_empresa = termc.cod_empresa
left join bandeiras_cartao bande on
    bande.cod_bandeira = cc.cod_bandeira_adm
   and bande.cod_empresa = cc.cod_emp_mult
left join clientes cl on
    cl.cod_cliente = cc.cod_cliente
    and cl.cod_empresa = cc.cod_emp_mult
left join retorna_ctrl_ag_conta (
    cf.branch_number,
    cf.account_number,
    cf.cod_empresa) ctrl on 1 = 1
left join controles ctrl2 on
    ctrl2.codigo_ctrl = cc.codigo_ctrl
    and ctrl2.codigo_emp = cc.codigo_emp
where ((trim(cf.event_type_description) = 'Venda') or (trim(cf.event_type_description) like 'Antecipa%'))
and cf.pix_id is null
union
select case when (cf.payment_date is not null) then cf.payment_date else cf.date_ end data,
cf.date_, cf.request_date, cf.effected_date, cf.payment_date, cf.bank_shipping_date,
cf.id, cf.cod_empresa, cf.arquivo, cf.data_arquivo,
cf.establishment_number,
cf.nsu, cf.authorization_number,
cf.type_, cf.type_description,
cf.acquirer_id, cf.acquirer_name,
cf.brand_id, cf.brand_name,
cf.event_type, cf.event_type_description,
cf.description,
stpag.id as bank_recon_status,
stpag.descricao as bank_recon_description,
coalesce(cf.gross_amount, 0) gross_amount,
coalesce(cf.event_net_amount, 0) event_net_amount,
coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
case when ((coalesce(cf.event_net_amount, 0) > 0) and (coalesce(cc.valor_c, 0) > 0)) then
       ((1 - (coalesce(cf.event_net_amount, 0) / coalesce(cc.valor_c, 0))) * 100)
     else
       0
end tax,
cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number,
emp.identificacao_emp,
ctrl.codigo_ctrl, ctrl.nome_ctrl,
ctrl2.codigo_ctrl as codigo_ctrl_tx, ctrl2.nome_ctrl as nome_ctrl_tx,
ctrl2.n_conta_plc_tx_cartao, ctrl2.n_conta_plc_tarifa_cartao,
cc.n_conta_plc, p.desc_plc,
cc.cod_cred, cc.n_doc_v, cc.n_doc_c, cc.tp_doc_v,
cc.valor_c, cc.valor_liquido, cc.valor_original, cc.data_rec_c, cc.data_venc_c, cc.status_c, cc.datq_c,
case when ((coalesce(cc.valor_liquido, 0) > 0) and (coalesce(cc.valor_c, 0) > 0)) then
        ((1 - (coalesce(cc.valor_liquido, 0) / coalesce(cc.valor_c, 0))) * 100)
     else
        0
end taxa_cred,
coalesce(cc.cod_cliente, 0) cod_cliente,
trim(case when (cc.cod_cliente > 0) then cl.nome_cliente else cc.nome_c end) nome_cliente,
trim(case when (cc.cod_cliente > 0) then cl.razao else cc.razao end) razao,
cc.cod_terminal_adm, termc.desc_term_adm, cc.cod_adm, adm.descricao_adm,
cc.cod_bandeira_adm, bande.descricao,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_pix_status vwfp
inner join conciliacao_financeiro cf on
    vwfp.pix_id = cf.pix_id
    and vwfp.cod_empresa = cf.cod_empresa
inner join empresa emp on
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
    band_adq.codigo = cf.bandeira_cod
    and band_adq.id_adquirente = adq.id
left join conciliacao_bandeira band on
    band.id = band_adq.id_bandeira
left join conciliacao_cod_ajuste_adq codajt_adq on
    codajt_adq.codigo = cf.cod_ajuste_cod
    and codajt_adq.id_adquirente = adq.id
left join conciliacao_cod_ajuste codajt on
    codajt.id = codajt_adq.id_cod_ajuste
left join conciliacao_form_pag_adq formpag_adq on
    formpag_adq.codigo = cf.form_pag_cod
    and formpag_adq.id_adquirente = adq.id
left join conciliacao_form_pag formpag on
    formpag.id = formpag_adq.id_form_pag
left join conciliacao_grupo_cartao_adq grcartao_adq on
    grcartao_adq.codigo = cf.grupo_cartao_cod
    and grcartao_adq.id_adquirente = cf.acquirer_id
left join conciliacao_grupo_cartao grcartao on
    grcartao.id = grcartao_adq.id_grupo_cartao
left join conciliacao_motivo_rej_adq motrej_adq on
    motrej_adq.codigo = cf.motivo_rej_cod
    and motrej_adq.id_adquirente = adq.id
left join conciliacao_motivo_rej motrej on
    motrej.id = motrej_adq.id_motivo_rej
left join conciliacao_origem_ajuste_adq orig_transf_adq on
    orig_transf_adq.codigo = cf.origem_ajuste_cod
    and orig_transf_adq.id_adquirente = adq.id
left join conciliacao_origem_ajuste orig_transf on
    orig_transf.id = orig_transf_adq.id_origem_ajuste
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
left join conciliacao_status_transf_adq st_transf_adq on
    st_transf_adq.codigo = cf.status_transf_cod
    and st_transf_adq.id_adquirente = adq.id
left join conciliacao_status_transf st_transf on
    st_transf.id = st_transf_adq.id_status_transf
left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
    tpantec.id = tpantec_adq.id_tipo_antecip
left join conciliacao_tipo_cartao_adq tpcartao_adq on
    tpcartao_adq.codigo = cf.tipo_cartao_cod
    and tpcartao_adq.id_adquirente = adq.id
left join conciliacao_tipo_cartao tpcartao on
    tpcartao.id = tpcartao_adq.id_tipo_cartao
left join conciliacao_tipo_lanc_adq tplanc_adq on
    tplanc_adq.codigo = cf.tipo_lancamento_cod
    and tplanc_adq.id_aquirente = adq.id
left join conciliacao_tipo_lanc tplanc on
    tplanc.id = tplanc_adq.id_tipo_lanc
left join conciliacao_tipo_liq_adq tpliq_adq on
    tpliq_adq.codigo = cf.tipo_liquidacao_cod
    and tpliq_adq.id_adquirente = adq.id
left join conciliacao_tipo_liq tpliq on
    tpliq.id = tpliq_adq.id_tipo_liq
left join conciliacao_tipo_transacao_adq tptr_adq on
    tptr_adq.codigo = cf.tipo_transacao_cod
    and tptr_adq.id_adquirente = adq.id
left join conciliacao_tipo_transacao tptr on
    tptr.id = tptr_adq.id_tipo_transacao
left join p_contas p on
    p.n_conta_plc = (case when (cf.event_net_amount >= 0) then codajt.n_conta_plc_e else codajt.n_conta_plc_s end)
left join getcreditosquitados(
    trim(cf.nsu),
    trim(cf.authorization_number),
    iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)),
    cf.cod_empresa) credq on 1 = 1
inner join controle_creditos cc on
    cc.cod_cred = credq.cod_cred
    and cc.codigo_emp = credq.codigo_emp
left join terminal_cartao termc on
    termc.cod_term_adm = cc.cod_terminal_adm
    and termc.cod_empresa = cc.cod_emp_mult
left join adm_cartao adm on
    adm.cod_adm = termc.cod_adm
    and adm.cod_empresa = termc.cod_empresa
left join bandeiras_cartao bande on
    bande.cod_bandeira = cc.cod_bandeira_adm
   and bande.cod_empresa = cc.cod_emp_mult
left join clientes cl on
    cl.cod_cliente = cc.cod_cliente
    and cl.cod_empresa = cc.cod_emp_mult
left join retorna_ctrl_ag_conta (
    cf.branch_number,
    cf.account_number,
    cf.cod_empresa) ctrl on 1 = 1
left join controles ctrl2 on
    ctrl2.codigo_ctrl = cc.codigo_ctrl
    and ctrl2.codigo_emp = cc.codigo_emp
where ((trim(cf.event_type_description) = 'Venda') or (trim(cf.event_type_description) like 'Antecipa%'))
and cf.pix_id is not null
union
select case when (cf.payment_date is not null) then cf.payment_date else cf.date_ end data,
cf.date_, cf.request_date, cf.effected_date, cf.payment_date, cf.bank_shipping_date,
cf.id, cf.cod_empresa, cf.arquivo, cf.data_arquivo,
cf.establishment_number,
cf.nsu, cf.authorization_number,
cf.type_, cf.type_description, 
cf.acquirer_id, cf.acquirer_name, 
cf.brand_id, cf.brand_name, 
cf.event_type, cf.event_type_description, 
cf.description,
stpag.id as bank_recon_status,
stpag.descricao as bank_recon_description,
coalesce(cf.gross_amount, 0) gross_amount,
coalesce(cf.event_net_amount, 0) event_net_amount,
coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
cf.tax, cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number,
emp.identificacao_emp, 
ctrl.codigo_ctrl, ctrl.nome_ctrl,
null codigo_ctrl_tx, null nome_ctrl_tx,
null n_conta_plc_tx_cartao, null n_conta_plc_tarifa_cartao,
p.n_conta_plc, p.desc_plc,
null cod_cred, null n_doc_v, null n_doc_c, null tp_doc_v,
null valor_c, null valor_liquido, null valor_original, null data_rec_c, null data_venc_c, null status_c, null datq_c, null taxa_cred,
null cod_cliente, null nome_cliente, null razao,
null cod_terminal_adm, null desc_term_adm, null cod_adm, null descricao_adm,
null cod_bandeira_adm, null descricao,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_status vwf
inner join conciliacao_financeiro cf on
    vwf.id = cf.id
    and vwf.installment_number = cf.installment_number
    and vwf.installments_total = cf.installments_total
    and vwf.cod_empresa = cf.cod_empresa
inner join empresa emp on
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
    band_adq.codigo = cf.bandeira_cod
    and band_adq.id_adquirente = adq.id
left join conciliacao_bandeira band on
    band.id = band_adq.id_bandeira
left join conciliacao_cod_ajuste_adq codajt_adq on
    codajt_adq.codigo = cf.cod_ajuste_cod
    and codajt_adq.id_adquirente = adq.id
left join conciliacao_cod_ajuste codajt on
    codajt.id = codajt_adq.id_cod_ajuste
left join conciliacao_form_pag_adq formpag_adq on
    formpag_adq.codigo = cf.form_pag_cod
    and formpag_adq.id_adquirente = adq.id
left join conciliacao_form_pag formpag on
    formpag.id = formpag_adq.id_form_pag
left join conciliacao_grupo_cartao_adq grcartao_adq on
    grcartao_adq.codigo = cf.grupo_cartao_cod
    and grcartao_adq.id_adquirente = cf.acquirer_id
left join conciliacao_grupo_cartao grcartao on
    grcartao.id = grcartao_adq.id_grupo_cartao
left join conciliacao_motivo_rej_adq motrej_adq on
    motrej_adq.codigo = cf.motivo_rej_cod
    and motrej_adq.id_adquirente = adq.id
left join conciliacao_motivo_rej motrej on
    motrej.id = motrej_adq.id_motivo_rej
left join conciliacao_origem_ajuste_adq orig_transf_adq on
    orig_transf_adq.codigo = cf.origem_ajuste_cod
    and orig_transf_adq.id_adquirente = adq.id
left join conciliacao_origem_ajuste orig_transf on
    orig_transf.id = orig_transf_adq.id_origem_ajuste
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
left join conciliacao_status_transf_adq st_transf_adq on
    st_transf_adq.codigo = cf.status_transf_cod
    and st_transf_adq.id_adquirente = adq.id
left join conciliacao_status_transf st_transf on
    st_transf.id = st_transf_adq.id_status_transf
left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
    tpantec.id = tpantec_adq.id_tipo_antecip
left join conciliacao_tipo_cartao_adq tpcartao_adq on
    tpcartao_adq.codigo = cf.tipo_cartao_cod
    and tpcartao_adq.id_adquirente = adq.id
left join conciliacao_tipo_cartao tpcartao on
    tpcartao.id = tpcartao_adq.id_tipo_cartao
left join conciliacao_tipo_lanc_adq tplanc_adq on
    tplanc_adq.codigo = cf.tipo_lancamento_cod
    and tplanc_adq.id_aquirente = adq.id
left join conciliacao_tipo_lanc tplanc on
    tplanc.id = tplanc_adq.id_tipo_lanc
left join conciliacao_tipo_liq_adq tpliq_adq on
    tpliq_adq.codigo = cf.tipo_liquidacao_cod
    and tpliq_adq.id_adquirente = adq.id
left join conciliacao_tipo_liq tpliq on
    tpliq.id = tpliq_adq.id_tipo_liq
left join conciliacao_tipo_transacao_adq tptr_adq on
    tptr_adq.codigo = cf.tipo_transacao_cod
    and tptr_adq.id_adquirente = adq.id
left join conciliacao_tipo_transacao tptr on
    tptr.id = tptr_adq.id_tipo_transacao
left join p_contas p on
    p.n_conta_plc = (case when (cf.event_net_amount >= 0) then codajt.n_conta_plc_e else codajt.n_conta_plc_s end)
left join retorna_ctrl_ag_conta (
    cf.branch_number,
    cf.account_number,
    cf.cod_empresa) ctrl on 1 = 1
where trim(cf.event_type_description) = 'Ajuste' and coalesce(cf.event_net_amount, 0) >= 0
and (select count(*) from lancamentos lanc
     where lanc.id_financ_confere = cf.id
     and lanc.cod_emp_mult = cf.cod_empresa) <> 0
union
select case when (cf.payment_date is not null) then cf.payment_date else cf.date_ end data,
cf.date_, cf.request_date, cf.effected_date, cf.payment_date, cf.bank_shipping_date,
cf.id, cf.cod_empresa, cf.arquivo, cf.data_arquivo,
cf.establishment_number,
cf.nsu, cf.authorization_number,
cf.type_, cf.type_description, 
cf.acquirer_id, cf.acquirer_name, 
cf.brand_id, cf.brand_name, 
cf.event_type, cf.event_type_description, 
cf.description,
stpag.id as bank_recon_status,
stpag.descricao as bank_recon_description,
coalesce(cf.gross_amount, 0) gross_amount,
coalesce(cf.event_net_amount, 0) event_net_amount,
coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
cf.tax, cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number,
emp.identificacao_emp, 
ctrl.codigo_ctrl, ctrl.nome_ctrl, 
null codigo_ctrl_tx, null  nome_ctrl_tx,
null n_conta_plc_tx_cartao, null n_conta_plc_tarifa_cartao,
p.n_conta_plc, p.desc_plc,
null cod_cred, null n_doc_v, null n_doc_c, null tp_doc_v,
null valor_c, null valor_liquido, null valor_original, null data_rec_c, null data_venc_c, null status_c, null datq_c, null taxa_cred,
null cod_cliente, null nome_cliente, null razao,
null cod_terminal_adm, null desc_term_adm, null cod_adm, null descricao_adm,
null cod_bandeira_adm, null descricao,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_status vwf
inner join conciliacao_financeiro cf on
    vwf.id = cf.id
    and vwf.installment_number = cf.installment_number
    and vwf.installments_total = cf.installments_total
    and vwf.cod_empresa = cf.cod_empresa
inner join empresa emp on
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
    band_adq.codigo = cf.bandeira_cod
    and band_adq.id_adquirente = adq.id
left join conciliacao_bandeira band on
    band.id = band_adq.id_bandeira
left join conciliacao_cod_ajuste_adq codajt_adq on
    codajt_adq.codigo = cf.cod_ajuste_cod
    and codajt_adq.id_adquirente = adq.id
left join conciliacao_cod_ajuste codajt on
    codajt.id = codajt_adq.id_cod_ajuste
left join conciliacao_form_pag_adq formpag_adq on
    formpag_adq.codigo = cf.form_pag_cod
    and formpag_adq.id_adquirente = adq.id
left join conciliacao_form_pag formpag on
    formpag.id = formpag_adq.id_form_pag
left join conciliacao_grupo_cartao_adq grcartao_adq on
    grcartao_adq.codigo = cf.grupo_cartao_cod
    and grcartao_adq.id_adquirente = cf.acquirer_id
left join conciliacao_grupo_cartao grcartao on
    grcartao.id = grcartao_adq.id_grupo_cartao
left join conciliacao_motivo_rej_adq motrej_adq on
    motrej_adq.codigo = cf.motivo_rej_cod
    and motrej_adq.id_adquirente = adq.id
left join conciliacao_motivo_rej motrej on
    motrej.id = motrej_adq.id_motivo_rej
left join conciliacao_origem_ajuste_adq orig_transf_adq on
    orig_transf_adq.codigo = cf.origem_ajuste_cod
    and orig_transf_adq.id_adquirente = adq.id
left join conciliacao_origem_ajuste orig_transf on
    orig_transf.id = orig_transf_adq.id_origem_ajuste
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
left join conciliacao_status_transf_adq st_transf_adq on
    st_transf_adq.codigo = cf.status_transf_cod
    and st_transf_adq.id_adquirente = adq.id
left join conciliacao_status_transf st_transf on
    st_transf.id = st_transf_adq.id_status_transf
left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
    tpantec.id = tpantec_adq.id_tipo_antecip
left join conciliacao_tipo_cartao_adq tpcartao_adq on
    tpcartao_adq.codigo = cf.tipo_cartao_cod
    and tpcartao_adq.id_adquirente = adq.id
left join conciliacao_tipo_cartao tpcartao on
    tpcartao.id = tpcartao_adq.id_tipo_cartao
left join conciliacao_tipo_lanc_adq tplanc_adq on
    tplanc_adq.codigo = cf.tipo_lancamento_cod
    and tplanc_adq.id_aquirente = adq.id
left join conciliacao_tipo_lanc tplanc on
    tplanc.id = tplanc_adq.id_tipo_lanc
left join conciliacao_tipo_liq_adq tpliq_adq on
    tpliq_adq.codigo = cf.tipo_liquidacao_cod
    and tpliq_adq.id_adquirente = adq.id
left join conciliacao_tipo_liq tpliq on
    tpliq.id = tpliq_adq.id_tipo_liq
left join conciliacao_tipo_transacao_adq tptr_adq on
    tptr_adq.codigo = cf.tipo_transacao_cod
    and tptr_adq.id_adquirente = adq.id
left join conciliacao_tipo_transacao tptr on
    tptr.id = tptr_adq.id_tipo_transacao
left join p_contas p on
    p.n_conta_plc = (case when (cf.event_net_amount >= 0) then codajt.n_conta_plc_e else codajt.n_conta_plc_s end)
left join retorna_ctrl_ag_conta (
    cf.branch_number,
    cf.account_number,
    cf.cod_empresa) ctrl on 1 = 1
where trim(cf.event_type_description) = 'Ajuste' and coalesce(cf.event_net_amount, 0) < 0
and (select count(*) from contas_a_pagar ctp
     where ctp.id_financ_confere = cf.id
     and ctp.cod_emp_mult = cf.cod_empresa
     and ctp.datq_ctp is not null) <> 0
;

/* View: VW_CONCILIACAO_FINANC_ADM, Owner: SYSDBA */
CREATE VIEW VW_CONCILIACAO_FINANC_ADM (DATA, DATE_, REQUEST_DATE, EFFECTED_DATE, PAYMENT_DATE, BANK_SHIPPING_DATE, ID, COD_EMPRESA, ARQUIVO, DATA_ARQUIVO, ESTABLISHMENT_NUMBER, NSU, AUTHORIZATION_NUMBER, TYPE_, TYPE_DESCRIPTION, ACQUIRER_ID, ACQUIRER_NAME, BRAND_ID, BRAND_NAME, EVENT_TYPE, EVENT_TYPE_DESCRIPTION, DESCRIPTION, BANK_RECON_STATUS, BANK_RECON_DESCRIPTION, GROSS_AMOUNT, EVENT_NET_AMOUNT, BATCH_NET_AMOUNT, GROSS_EVENT_AMOUNT, BATCH_GROSS_AMOUNT, TAX, SALE_TAX, CUSTOMER_TAX, INSTALLMENT_NUMBER, INSTALLMENTS_TOTAL, BANK_NUMBER, BANK_NAME, BRANCH_NUMBER, ACCOUNT_NUMBER, IDENTIFICACAO_EMP, CODIGO_CTRL, NOME_CTRL, CODIGO_CTRL_TX, NOME_CTRL_TX, N_CONTA_PLC_TX_CARTAO, N_CONTA_PLC_TARIFA_CARTAO, N_CONTA_PLC, DESC_PLC, COD_CRED, N_DOC_V, N_DOC_C, TP_DOC_V, VALOR_C, VALOR_LIQUIDO, VALOR_ORIGINAL, DATA_REC_C, DATA_VENC_C, STATUS_C, DATQ_C, STATUSQ_C, TAXA_CRED, COD_CLIENTE, NOME_CLIENTE, RAZAO, COD_TERMINAL_ADM, DESC_TERM_ADM, COD_ADM, DESCRICAO_ADM, COD_BANDEIRA_ADM, DESC_BANDEIRA_ADM, PIX_ID, FORM_PAG_COD, FORM_PAG, COD_AJUSTE_COD, COD_AJUSTE, BANDEIRA_COD, BANDEIRA, STATUS_PAG_COD, STATUS_PAG, STATUS_PAG_ST, TIPO_LANCAMENTO_COD, TIPO_LANCAMENTO, TIPO_LIQUIDACAO_COD, TIPO_LIQUIDACAO, TIPO_ANTECIPACAO_COD, TIPO_ANTECIPACAO, TIPO_CARTAO_COD, TIPO_CARTAO, MOTIVO_REJ_COD, MOTIVO_REJ, GRUPO_CARTAO_COD, GRUPO_CARTAO, TIPO_TRANSACAO_COD, TIPO_TRANSACAO, STATUS_TRANSF_COD, STATUS_TRANSF, STATUS_TRANSF_ST, ORIGEM_AJUSTE_COD, ORIGEM_AJUSTE) AS

select case when (cf.payment_date is not null) then cf.payment_date else cf.date_ end data,
cf.date_, cf.request_date, cf.effected_date, cf.payment_date, cf.bank_shipping_date,
cf.id, cf.cod_empresa, cf.arquivo, cf.data_arquivo,
cf.establishment_number,
cf.nsu, cf.authorization_number,
cf.type_, cf.type_description, 
cf.acquirer_id, cf.acquirer_name, 
cf.brand_id, cf.brand_name, 
cf.event_type, cf.event_type_description, 
cf.description,
stpag.id as bank_recon_status,
stpag.descricao as bank_recon_description,
coalesce(cf.gross_amount, 0) gross_amount,
coalesce(cf.event_net_amount, 0) event_net_amount,
coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
case when ((coalesce(cf.event_net_amount, 0) > 0) and (coalesce(cc.valor_c, 0) > 0)) then
       ((1 - (coalesce(cf.event_net_amount, 0) / coalesce(cc.valor_c, 0))) * 100)
     else
       0
end tax,
cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number, 
emp.identificacao_emp, 
ctrl.codigo_ctrl, ctrl.nome_ctrl, 
ctrl2.codigo_ctrl as codigo_ctrl_tx, ctrl2.nome_ctrl as nome_ctrl_tx, 
ctrl2.n_conta_plc_tx_cartao, ctrl2.n_conta_plc_tarifa_cartao, 
cc.n_conta_plc, p.desc_plc, 
cc.cod_cred, cc.n_doc_v, cc.n_doc_c, cc.tp_doc_v, 
cc.valor_c, cc.valor_liquido, cc.valor_original, cc.data_rec_c, cc.data_venc_c, cc.status_c,
cc.datq_c,
case when (cc.datq_c is not null) and (cc.tip_baixa = 'D') then
        'DEVOLUCAO'
     when (cc.datq_c is not null) then
        'QUITADO'
     else
        'ABERTO'
end statusq_c,
case when ((coalesce(cc.valor_liquido, 0) > 0) and (coalesce(cc.valor_c, 0) > 0)) then
        ((1 - (coalesce(cc.valor_liquido, 0) / coalesce(cc.valor_c, 0))) * 100)
     else
        0
end taxa_cred,
coalesce(cc.cod_cliente, 0) cod_cliente,
trim(case when (cc.cod_cliente > 0) then cl.nome_cliente else cc.nome_c end) nome_cliente, 
trim(case when (cc.cod_cliente > 0) then cl.razao else cc.razao end) razao,
cc.cod_terminal_adm, termc.desc_term_adm, cc.cod_adm, adm.descricao_adm, 
cc.cod_bandeira_adm, bande.descricao,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_status vwf
inner join conciliacao_financeiro cf on
    vwf.id = cf.id
    and vwf.installment_number = cf.installment_number
    and vwf.installments_total = cf.installments_total
    and vwf.cod_empresa = cf.cod_empresa
inner join empresa emp on
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
    band_adq.codigo = cf.bandeira_cod
    and band_adq.id_adquirente = adq.id
left join conciliacao_bandeira band on
    band.id = band_adq.id_bandeira
left join conciliacao_cod_ajuste_adq codajt_adq on
    codajt_adq.codigo = cf.cod_ajuste_cod
    and codajt_adq.id_adquirente = adq.id
left join conciliacao_cod_ajuste codajt on
    codajt.id = codajt_adq.id_cod_ajuste
left join conciliacao_form_pag_adq formpag_adq on
    formpag_adq.codigo = cf.form_pag_cod
    and formpag_adq.id_adquirente = adq.id
left join conciliacao_form_pag formpag on
    formpag.id = formpag_adq.id_form_pag
left join conciliacao_grupo_cartao_adq grcartao_adq on
    grcartao_adq.codigo = cf.grupo_cartao_cod
    and grcartao_adq.id_adquirente = cf.acquirer_id
left join conciliacao_grupo_cartao grcartao on
    grcartao.id = grcartao_adq.id_grupo_cartao
left join conciliacao_motivo_rej_adq motrej_adq on
    motrej_adq.codigo = cf.motivo_rej_cod
    and motrej_adq.id_adquirente = adq.id
left join conciliacao_motivo_rej motrej on
    motrej.id = motrej_adq.id_motivo_rej
left join conciliacao_origem_ajuste_adq orig_transf_adq on
    orig_transf_adq.codigo = cf.origem_ajuste_cod
    and orig_transf_adq.id_adquirente = adq.id
left join conciliacao_origem_ajuste orig_transf on
    orig_transf.id = orig_transf_adq.id_origem_ajuste
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
left join conciliacao_status_transf_adq st_transf_adq on
    st_transf_adq.codigo = cf.status_transf_cod
    and st_transf_adq.id_adquirente = adq.id
left join conciliacao_status_transf st_transf on
    st_transf.id = st_transf_adq.id_status_transf
left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
