coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
cf.tax, cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number,
emp.identificacao_emp, 
ctrl.codigo_ctrl, ctrl.nome_ctrl, 
null codigo_ctrl_tx, null nome_ctrl_tx,
null n_conta_plc_tx_cartao, null n_conta_plc_tarifa_cartao,
p.n_conta_plc, p.desc_plc,
null cod_cred, null n_doc_v, null n_doc_c, null tp_doc_v,
null valor_c, null valor_liquido, null valor_original, null data_rec_c, null data_venc_c, null status_c,
(select first 1 lanc.data from lancamentos lanc
 where lanc.id_financ_confere = cf.id
 and lanc.cod_emp_mult = cf.cod_empresa) datq_c,
case when ((select count(*) from lancamentos lanc
            where lanc.id_financ_confere = cf.id
            and lanc.cod_emp_mult = cf.cod_empresa) <> 0) then
       'QUITADO'
     else
       'ABERTO'
end statusq_c,
null taxa_cred,
null cod_cliente, null nome_cliente, null razao,
null cod_terminal_adm, null desc_term_adm, null cod_adm, null descricao_adm,
null cod_bandeira_adm, null descricao,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_status vwf
inner join conciliacao_financeiro cf on
    vwf.id = cf.id
    and vwf.installment_number = cf.installment_number
    and vwf.installments_total = cf.installments_total
    and vwf.cod_empresa = cf.cod_empresa
inner join empresa emp on
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
    band_adq.codigo = cf.bandeira_cod
    and band_adq.id_adquirente = adq.id
left join conciliacao_bandeira band on
    band.id = band_adq.id_bandeira
left join conciliacao_cod_ajuste_adq codajt_adq on
    codajt_adq.codigo = cf.cod_ajuste_cod
    and codajt_adq.id_adquirente = adq.id
left join conciliacao_cod_ajuste codajt on
    codajt.id = codajt_adq.id_cod_ajuste
left join conciliacao_form_pag_adq formpag_adq on
    formpag_adq.codigo = cf.form_pag_cod
    and formpag_adq.id_adquirente = adq.id
left join conciliacao_form_pag formpag on
    formpag.id = formpag_adq.id_form_pag
left join conciliacao_grupo_cartao_adq grcartao_adq on
    grcartao_adq.codigo = cf.grupo_cartao_cod
    and grcartao_adq.id_adquirente = cf.acquirer_id
left join conciliacao_grupo_cartao grcartao on
    grcartao.id = grcartao_adq.id_grupo_cartao
left join conciliacao_motivo_rej_adq motrej_adq on
    motrej_adq.codigo = cf.motivo_rej_cod
    and motrej_adq.id_adquirente = adq.id
left join conciliacao_motivo_rej motrej on
    motrej.id = motrej_adq.id_motivo_rej
left join conciliacao_origem_ajuste_adq orig_transf_adq on
    orig_transf_adq.codigo = cf.origem_ajuste_cod
    and orig_transf_adq.id_adquirente = adq.id
left join conciliacao_origem_ajuste orig_transf on
    orig_transf.id = orig_transf_adq.id_origem_ajuste
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
left join conciliacao_status_transf_adq st_transf_adq on
    st_transf_adq.codigo = cf.status_transf_cod
    and st_transf_adq.id_adquirente = adq.id
left join conciliacao_status_transf st_transf on
    st_transf.id = st_transf_adq.id_status_transf
left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
    tpantec.id = tpantec_adq.id_tipo_antecip
left join conciliacao_tipo_cartao_adq tpcartao_adq on
    tpcartao_adq.codigo = cf.tipo_cartao_cod
    and tpcartao_adq.id_adquirente = adq.id
left join conciliacao_tipo_cartao tpcartao on
    tpcartao.id = tpcartao_adq.id_tipo_cartao
left join conciliacao_tipo_lanc_adq tplanc_adq on
    tplanc_adq.codigo = cf.tipo_lancamento_cod
    and tplanc_adq.id_aquirente = adq.id
left join conciliacao_tipo_lanc tplanc on
    tplanc.id = tplanc_adq.id_tipo_lanc
left join conciliacao_tipo_liq_adq tpliq_adq on
    tpliq_adq.codigo = cf.tipo_liquidacao_cod
    and tpliq_adq.id_adquirente = adq.id
left join conciliacao_tipo_liq tpliq on
    tpliq.id = tpliq_adq.id_tipo_liq
left join conciliacao_tipo_transacao_adq tptr_adq on
    tptr_adq.codigo = cf.tipo_transacao_cod
    and tptr_adq.id_adquirente = adq.id
left join conciliacao_tipo_transacao tptr on
    tptr.id = tptr_adq.id_tipo_transacao
left join p_contas p on
    p.n_conta_plc = (case when (cf.event_net_amount >= 0) then codajt.n_conta_plc_e else codajt.n_conta_plc_s end)
left join retorna_ctrl_ag_conta (
    cf.branch_number,
    cf.account_number,
    cf.cod_empresa) ctrl on 1 = 1
where trim(cf.event_type_description) = 'Ajuste' and coalesce(cf.event_net_amount, 0) >= 0
union
select case when (cf.payment_date is not null) then cf.payment_date else cf.date_ end data,
cf.date_, cf.request_date, cf.effected_date, cf.payment_date, cf.bank_shipping_date,
cf.id, cf.cod_empresa, cf.arquivo, cf.data_arquivo,
cf.establishment_number,
cf.nsu, cf.authorization_number,
cf.type_, cf.type_description, 
cf.acquirer_id, cf.acquirer_name, 
cf.brand_id, cf.brand_name, 
cf.event_type, cf.event_type_description, 
cf.description,
stpag.id as bank_recon_status,
stpag.descricao as bank_recon_description,
coalesce(cf.gross_amount, 0) gross_amount,
coalesce(cf.event_net_amount, 0) event_net_amount,
coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
cf.tax, cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number,
emp.identificacao_emp, 
ctrl.codigo_ctrl, ctrl.nome_ctrl, 
null codigo_ctrl_tx, null  nome_ctrl_tx,
null n_conta_plc_tx_cartao, null n_conta_plc_tarifa_cartao,
p.n_conta_plc, p.desc_plc,
null cod_cred, null n_doc_v, null n_doc_c, null tp_doc_v,
null valor_c, null valor_liquido, null valor_original, null data_rec_c, null data_venc_c, null status_c,
(select first 1 lanc.data from lancamentos lanc
 where lanc.id_financ_confere = cf.id
 and lanc.cod_emp_mult = cf.cod_empresa) datq_c,
case when ((select count(*) from lancamentos lanc
            where lanc.id_financ_confere = cf.id
            and lanc.cod_emp_mult = cf.cod_empresa) <> 0) then
       'QUITADO'
     else
       'ABERTO'
end statusq_c,
null taxa_cred,
null cod_cliente, null nome_cliente, null razao,
null cod_terminal_adm, null desc_term_adm, null cod_adm, null descricao_adm,
null cod_bandeira_adm, null descricao,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_status vwf
inner join conciliacao_financeiro cf on
    vwf.id = cf.id
    and vwf.installment_number = cf.installment_number
    and vwf.installments_total = cf.installments_total
    and vwf.cod_empresa = cf.cod_empresa
inner join empresa emp on
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
    band_adq.codigo = cf.bandeira_cod
    and band_adq.id_adquirente = adq.id
left join conciliacao_bandeira band on
    band.id = band_adq.id_bandeira
left join conciliacao_cod_ajuste_adq codajt_adq on
    codajt_adq.codigo = cf.cod_ajuste_cod
    and codajt_adq.id_adquirente = adq.id
left join conciliacao_cod_ajuste codajt on
    codajt.id = codajt_adq.id_cod_ajuste
left join conciliacao_form_pag_adq formpag_adq on
    formpag_adq.codigo = cf.form_pag_cod
    and formpag_adq.id_adquirente = adq.id
left join conciliacao_form_pag formpag on
    formpag.id = formpag_adq.id_form_pag
left join conciliacao_grupo_cartao_adq grcartao_adq on
    grcartao_adq.codigo = cf.grupo_cartao_cod
    and grcartao_adq.id_adquirente = cf.acquirer_id
left join conciliacao_grupo_cartao grcartao on
    grcartao.id = grcartao_adq.id_grupo_cartao
left join conciliacao_motivo_rej_adq motrej_adq on
    motrej_adq.codigo = cf.motivo_rej_cod
    and motrej_adq.id_adquirente = adq.id
left join conciliacao_motivo_rej motrej on
    motrej.id = motrej_adq.id_motivo_rej
left join conciliacao_origem_ajuste_adq orig_transf_adq on
    orig_transf_adq.codigo = cf.origem_ajuste_cod
    and orig_transf_adq.id_adquirente = adq.id
left join conciliacao_origem_ajuste orig_transf on
    orig_transf.id = orig_transf_adq.id_origem_ajuste
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
left join conciliacao_status_transf_adq st_transf_adq on
    st_transf_adq.codigo = cf.status_transf_cod
    and st_transf_adq.id_adquirente = adq.id
left join conciliacao_status_transf st_transf on
    st_transf.id = st_transf_adq.id_status_transf
left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
    tpantec.id = tpantec_adq.id_tipo_antecip
left join conciliacao_tipo_cartao_adq tpcartao_adq on
    tpcartao_adq.codigo = cf.tipo_cartao_cod
    and tpcartao_adq.id_adquirente = adq.id
left join conciliacao_tipo_cartao tpcartao on
    tpcartao.id = tpcartao_adq.id_tipo_cartao
left join conciliacao_tipo_lanc_adq tplanc_adq on
    tplanc_adq.codigo = cf.tipo_lancamento_cod
    and tplanc_adq.id_aquirente = adq.id
left join conciliacao_tipo_lanc tplanc on
    tplanc.id = tplanc_adq.id_tipo_lanc
left join conciliacao_tipo_liq_adq tpliq_adq on
    tpliq_adq.codigo = cf.tipo_liquidacao_cod
    and tpliq_adq.id_adquirente = adq.id
left join conciliacao_tipo_liq tpliq on
    tpliq.id = tpliq_adq.id_tipo_liq
left join conciliacao_tipo_transacao_adq tptr_adq on
    tptr_adq.codigo = cf.tipo_transacao_cod
    and tptr_adq.id_adquirente = adq.id
left join conciliacao_tipo_transacao tptr on
    tptr.id = tptr_adq.id_tipo_transacao
left join p_contas p on
    p.n_conta_plc = (case when (cf.event_net_amount >= 0) then codajt.n_conta_plc_e else codajt.n_conta_plc_s end)
left join retorna_ctrl_ag_conta (
    cf.branch_number,
    cf.account_number,
    cf.cod_empresa) ctrl on 1 = 1
where trim(cf.event_type_description) = 'Ajuste' and coalesce(cf.event_net_amount, 0) < 0
;

/* View: VW_RPS_NFSE_LEGADO, Owner: SYSDBA */
CREATE VIEW VW_RPS_NFSE_LEGADO (NOME_CLIENTE, NPED, TIPO, ALIQ_ISS, NFS_SERVICO, CNAE_SERV, VL_LIQ, VALORNF, CIDADE, COD_RPS, N_NF, COD_EMPRESA, DATA_FECH, STATUS_NFSE, ISS_RETIDO, CTISS, CTRIBNAC, CTRIBMUN, CNBS, NFSE_NACIONAL, MODELO_NFSE, EMISSAO_RPS, COD_CLIENTE, CODIGO_VERWSNFSE, NFS_SERVICO_TS, IRRF_SERVICO, ISSRET_SERVICO, PISRF_SERVICO, COFINSRF_SERVICO, CSSLRF_SERVICO, BRUTO) AS

--Autorizadas versao nao nacional
select clientes.nome_cliente, pedvenda.nped, pedvenda.tipo, pedvenda_serv.aliq_iss,
       pedvenda_serv.nfs_servico, pedvenda_serv.cnae_serv,
       sum(pedvenda_serv.valor_tot_serv + coalesce(pedvenda_serv.rateio_acresc, 0) - pedvenda_serv.rateio_desc) vl_liq,
       sum(pedvenda_serv.valor_nfse) as valornf, clientes.cidade, pedvenda_serv.cod_rps, pedvenda_serv.n_nf, pedvenda_serv.cod_empresa,
       pedvenda.data_fech, pedvenda_serv.status_nfse, pedvenda_serv.iss_retido, pedvenda_serv.ctiss,
       pedvenda_serv.ctribnac, pedvenda_serv.ctribmun, pedvenda_serv.cnbs, 0 nfse_nacional, pedvenda_serv.modelo_nfse,
       pedvenda_serv.emissao_rps, pedvenda.cod_cliente, pedvenda_serv.codigo_verwsnfse, tipo_servico.nfs_servico nfs_servico_ts,
       sum(pedvenda_serv.irrf_servico) as irrf_servico,
       sum(pedvenda_serv.issret_servico) as issret_servico,
       sum(pedvenda_serv.pisrf_servico) as pisrf_servico,
       sum(pedvenda_serv.cofinsrf_servico) as cofinsrf_servico,
       sum(pedvenda_serv.csslrf_servico) as csslrf_servico,
       sum(pedvenda_serv.valor_b_nfse) as bruto
from pedvenda_serv
  inner join tipo_servico on tipo_servico.cod_servico = pedvenda_serv.cod_servico
  inner join pedvenda on pedvenda_serv.nped = pedvenda.nped and
        pedvenda_serv.tipo = pedvenda.tipo and
        pedvenda_serv.cod_empresa = pedvenda.cod_empresa
  inner join clientes on pedvenda.cod_cliente = clientes.cod_cliente and
        pedvenda.cod_empresa = clientes.cod_empresa
  inner join empresa on empresa.cod_empresa = pedvenda_serv.cod_empresa
where pedvenda.tipo = 'OS' and pedvenda.status_ped = 'FECHADA'
  and pedvenda_serv.valor_tot_serv <> 0 and coalesce(pedvenda_serv.status, '') <> 'CANCELADO' and pedvenda.ativo = 1
  and pedvenda_serv.n_nf is not null and pedvenda_serv.n_nf > 0
  and coalesce(pedvenda_serv.nfse_nacional, 0) <> 1
  and pedvenda_serv.nfse_id is null
group by nome_cliente, nped, tipo, aliq_iss, nfs_servico, cnae_serv, cidade, cod_rps, n_nf, cod_empresa, data_fech, status_nfse, iss_retido, ctiss,
  ctribnac, ctribmun, cnbs, nfse_nacional, modelo_nfse, emissao_rps, cod_cliente, codigo_verwsnfse, nfs_servico_ts
union   
--Nao autorizadas padrao nacional desativado
select clientes.nome_cliente, pedvenda.nped, pedvenda.tipo, iif(cs.value1_f = 1, empresa.aliq_simples_iss, tipo_servico.aliq_iss) aliq_iss,
       tipo_servico.nfs_servico, tipo_servico.cnae_serv,
       sum(pedvenda_serv.valor_tot_serv + coalesce(pedvenda_serv.rateio_acresc, 0) - pedvenda_serv.rateio_desc) vl_liq,
       sum(pedvenda_serv.valor_nfse) as valornf, clientes.cidade, pedvenda_serv.cod_rps, pedvenda_serv.n_nf, pedvenda_serv.cod_empresa,
       pedvenda.data_fech, pedvenda_serv.status_nfse,
       case
         when coalesce(clientes.iss_retido, 0) <> 0 then clientes.iss_retido
         else tipo_servico.iss_retido
       end as iss_retido,
       tipo_servico.ctiss,
       tipo_servico.ctribnac, tipo_servico.ctribmun, tipo_servico.cnbs, 0 nfse_nacional, pedvenda_serv.modelo_nfse,
       pedvenda_serv.emissao_rps, pedvenda.cod_cliente, pedvenda_serv.codigo_verwsnfse, tipo_servico.nfs_servico nfs_servico_ts,
       sum(pedvenda_serv.irrf_servico) as irrf_servico,
       sum(pedvenda_serv.issret_servico) as issret_servico,
       sum(pedvenda_serv.pisrf_servico) as pisrf_servico,
       sum(pedvenda_serv.cofinsrf_servico) as cofinsrf_servico,
       sum(pedvenda_serv.csslrf_servico) as csslrf_servico,
       sum(pedvenda_serv.valor_b_nfse) as bruto
from pedvenda_serv
  inner join tipo_servico on tipo_servico.cod_servico = pedvenda_serv.cod_servico
  inner join pedvenda on pedvenda_serv.nped = pedvenda.nped and
        pedvenda_serv.tipo = pedvenda.tipo and
        pedvenda_serv.cod_empresa = pedvenda.cod_empresa
  inner join clientes on pedvenda.cod_cliente = clientes.cod_cliente and
        pedvenda.cod_empresa = clientes.cod_empresa
  inner join empresa on empresa.cod_empresa = pedvenda_serv.cod_empresa
  left join config_sistema cs on cs.chave = 'nfse_simples_nacional_aliq' and
        cs.cod_empresa = empresa.cod_empresa
  left join config_sistema cn on cn.chave = 'nfse_config' and
        cn.cod_empresa = empresa.cod_empresa
where pedvenda.tipo = 'OS' and pedvenda.status_ped = 'FECHADA'
  and pedvenda_serv.valor_tot_serv <> 0 and coalesce(pedvenda_serv.status, '') <> 'CANCELADO' and pedvenda.ativo = 1
  and coalesce(pedvenda_serv.n_nf, 0) = 0
  and coalesce(pedvenda_serv.nfse_nacional, 0) <> 1
  and coalesce(cn.value1_f, 0) = 0
  and pedvenda_serv.nfse_id is null
group by nome_cliente, nped, tipo, aliq_iss, nfs_servico, cnae_serv, cidade, cod_rps, n_nf, cod_empresa, data_fech, status_nfse, iss_retido, ctiss,
  ctribnac, ctribmun, cnbs, nfse_nacional, modelo_nfse, emissao_rps, cod_cliente, codigo_verwsnfse, nfs_servico_ts
union
--Padrao nacional autorizadas
select clientes.nome_cliente, pedvenda.nped, pedvenda.tipo, pedvenda_serv.aliq_iss,
       null nfs_servico, null cnae_serv,
       sum(pedvenda_serv.valor_tot_serv + coalesce(pedvenda_serv.rateio_acresc, 0) - pedvenda_serv.rateio_desc) vl_liq,
       sum(pedvenda_serv.valor_nfse) as valornf, clientes.cidade, pedvenda_serv.cod_rps, pedvenda_serv.n_nf, pedvenda_serv.cod_empresa,
       pedvenda.data_fech, pedvenda_serv.status_nfse, pedvenda_serv.iss_retido, null ctiss,
       pedvenda_serv.ctribnac, pedvenda_serv.ctribmun, pedvenda_serv.cnbs, pedvenda_serv.nfse_nacional, pedvenda_serv.modelo_nfse,
       pedvenda_serv.emissao_rps, pedvenda.cod_cliente, pedvenda_serv.codigo_verwsnfse, tipo_servico.nfs_servico nfs_servico_ts,
       sum(pedvenda_serv.irrf_servico) as irrf_servico,
       sum(pedvenda_serv.issret_servico) as issret_servico,
       sum(pedvenda_serv.pisrf_servico) as pisrf_servico,
       sum(pedvenda_serv.cofinsrf_servico) as cofinsrf_servico,
       sum(pedvenda_serv.csslrf_servico) as csslrf_servico,
       sum(pedvenda_serv.valor_b_nfse) as bruto
from pedvenda_serv
  inner join tipo_servico on tipo_servico.cod_servico = pedvenda_serv.cod_servico
  inner join pedvenda on pedvenda_serv.nped = pedvenda.nped and
        pedvenda_serv.tipo = pedvenda.tipo and
        pedvenda_serv.cod_empresa = pedvenda.cod_empresa
  inner join clientes on pedvenda.cod_cliente = clientes.cod_cliente and
        pedvenda.cod_empresa = clientes.cod_empresa
  inner join empresa on empresa.cod_empresa = pedvenda_serv.cod_empresa
where pedvenda.tipo = 'OS' and pedvenda.status_ped = 'FECHADA'
  and pedvenda_serv.valor_tot_serv <> 0 and coalesce(pedvenda_serv.status, '') <> 'CANCELADO' and pedvenda.ativo = 1
  and pedvenda_serv.n_nf is not null and pedvenda_serv.n_nf > 0
  and pedvenda_serv.nfse_nacional = 1
  and pedvenda_serv.nfse_id is null
group by nome_cliente, nped, tipo, aliq_iss, nfs_servico, cnae_serv, cidade, cod_rps, n_nf, cod_empresa, data_fech, status_nfse, iss_retido, ctiss,
  ctribnac, ctribmun, cnbs, nfse_nacional, modelo_nfse, emissao_rps, cod_cliente, codigo_verwsnfse, nfs_servico_ts
union   
--Nao autorizadas PADRAO NACIONAL ATIVADO
select clientes.nome_cliente, pedvenda.nped, pedvenda.tipo, iif(cs.value1_f = 1, empresa.aliq_simples_iss, tipo_servico.aliq_iss) aliq_iss,
       null nfs_servico, null cnae_serv,
       sum(pedvenda_serv.valor_tot_serv + coalesce(pedvenda_serv.rateio_acresc, 0) - pedvenda_serv.rateio_desc) vl_liq,
       sum(pedvenda_serv.valor_nfse) as valornf, clientes.cidade, pedvenda_serv.cod_rps, pedvenda_serv.n_nf, pedvenda_serv.cod_empresa,
       pedvenda.data_fech, pedvenda_serv.status_nfse,
       case
         when coalesce(clientes.iss_retido, 0) <> 0 then clientes.iss_retido
         else tipo_servico.iss_retido
       end as iss_retido,
       null ctiss,
       tipo_servico.ctribnac, tipo_servico.ctribmun, tipo_servico.cnbs, 1 nfse_nacional, pedvenda_serv.modelo_nfse,
       pedvenda_serv.emissao_rps, pedvenda.cod_cliente, pedvenda_serv.codigo_verwsnfse, tipo_servico.nfs_servico nfs_servico_ts,
       sum(pedvenda_serv.irrf_servico) as irrf_servico,
       sum(pedvenda_serv.issret_servico) as issret_servico,
       sum(pedvenda_serv.pisrf_servico) as pisrf_servico,
       sum(pedvenda_serv.cofinsrf_servico) as cofinsrf_servico,
       sum(pedvenda_serv.csslrf_servico) as csslrf_servico,
       sum(pedvenda_serv.valor_b_nfse) as bruto
from pedvenda_serv
  inner join tipo_servico on tipo_servico.cod_servico = pedvenda_serv.cod_servico
  inner join pedvenda on pedvenda_serv.nped = pedvenda.nped and
        pedvenda_serv.tipo = pedvenda.tipo and
        pedvenda_serv.cod_empresa = pedvenda.cod_empresa
  inner join clientes on pedvenda.cod_cliente = clientes.cod_cliente and
        pedvenda.cod_empresa = clientes.cod_empresa
  inner join empresa on empresa.cod_empresa = pedvenda_serv.cod_empresa
  left join config_sistema cs on cs.chave = 'nfse_simples_nacional_aliq' and
        cs.cod_empresa = empresa.cod_empresa
  left join config_sistema cn on cn.chave = 'nfse_config' and
        cn.cod_empresa = empresa.cod_empresa and cn.value1_f = 1
where pedvenda.tipo = 'OS' and pedvenda.status_ped = 'FECHADA'
  and pedvenda_serv.valor_tot_serv <> 0 and coalesce(pedvenda_serv.status, '') <> 'CANCELADO' and pedvenda.ativo = 1
  and coalesce(pedvenda_serv.n_nf, 0) = 0
  and coalesce(pedvenda_serv.nfse_nacional, coalesce(cn.value1_f, 0)) = 1
  and pedvenda_serv.nfse_id is null
group by nome_cliente, nped, tipo, aliq_iss, nfs_servico, cnae_serv, cidade, cod_rps, n_nf, cod_empresa, data_fech, status_nfse, iss_retido, ctiss,
  ctribnac, ctribmun, cnbs, nfse_nacional, modelo_nfse, emissao_rps, cod_cliente, codigo_verwsnfse, nfs_servico_ts
;

/* View: VW_CONCILIACAO_PENDENCIAS_CONF, Owner: SYSDBA */
CREATE VIEW VW_CONCILIACAO_PENDENCIAS_CONF (DATA, DATE_, REQUEST_DATE, EFFECTED_DATE, PAYMENT_DATE, BANK_SHIPPING_DATE, ID, COD_EMPRESA, ARQUIVO, DATA_ARQUIVO, ESTABLISHMENT_NUMBER, NSU, AUTHORIZATION_NUMBER, TYPE_, TYPE_DESCRIPTION, ACQUIRER_ID, ACQUIRER_NAME, BRAND_ID, BRAND_NAME, EVENT_TYPE, EVENT_TYPE_DESCRIPTION, DESCRIPTION, BANK_RECON_STATUS, BANK_RECON_DESCRIPTION, GROSS_AMOUNT, EVENT_NET_AMOUNT, BATCH_NET_AMOUNT, GROSS_EVENT_AMOUNT, BATCH_GROSS_AMOUNT, TAX, SALE_TAX, CUSTOMER_TAX, INSTALLMENT_NUMBER, INSTALLMENTS_TOTAL, BANK_NUMBER, BANK_NAME, BRANCH_NUMBER, ACCOUNT_NUMBER, IDENTIFICACAO_EMP, CODIGO_CTRL, NOME_CTRL, CODIGO_CTRL_TX, NOME_CTRL_TX, N_CONTA_PLC_TX_CARTAO, N_CONTA_PLC, DESC_PLC, COD_CRED, N_DOC_V, N_DOC_C, TP_DOC_V, VALOR_C, VALOR_LIQUIDO, VALOR_ORIGINAL, DATA_REC_C, DATA_VENC_C, DATQ_C, STATUS_C, TAXA_CRED, COD_TERMINAL_ADM, DESC_TERM_ADM, COD_ADM, DESCRICAO_ADM, COD_BANDEIRA_ADM, DESC_BANDEIRA_ADM, PIX_ID, FORM_PAG_COD, FORM_PAG, COD_AJUSTE_COD, COD_AJUSTE, BANDEIRA_COD, BANDEIRA, STATUS_PAG_COD, STATUS_PAG, STATUS_PAG_ST, TIPO_LANCAMENTO_COD, TIPO_LANCAMENTO, TIPO_LIQUIDACAO_COD, TIPO_LIQUIDACAO, TIPO_ANTECIPACAO_COD, TIPO_ANTECIPACAO, TIPO_CARTAO_COD, TIPO_CARTAO, MOTIVO_REJ_COD, MOTIVO_REJ, GRUPO_CARTAO_COD, GRUPO_CARTAO, TIPO_TRANSACAO_COD, TIPO_TRANSACAO, STATUS_TRANSF_COD, STATUS_TRANSF, STATUS_TRANSF_ST, ORIGEM_AJUSTE_COD, ORIGEM_AJUSTE) AS

select case when (cf.payment_date is not null) then cf.payment_date else cf.date_ end data,
cf.date_, cf.request_date, cf.effected_date, cf.payment_date, cf.bank_shipping_date,
cf.id, cf.cod_empresa, cf.arquivo, cf.data_arquivo,
cf.establishment_number, cf.nsu, cf.authorization_number,
cf.type_, cf.type_description,
cf.acquirer_id, cf.acquirer_name,
cf.brand_id, cf.brand_name,
cf.event_type, cf.event_type_description,
tplanc.descricao as description,
stpag.id as bank_recon_status,
stpag.descricao as bank_recon_description,
coalesce(cf.gross_amount, 0) gross_amount,
coalesce(cf.event_net_amount, 0) event_net_amount,
coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
cf.tax, cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number,
emp.identificacao_emp,
ctrl.codigo_ctrl, ctrl.nome_ctrl,
ctrl2.codigo_ctrl as codigo_ctrl_tx, ctrl2.nome_ctrl as nome_ctrl_tx, ctrl2.n_conta_plc_tx_cartao,
cc.n_conta_plc, p.desc_plc,
cc.cod_cred, cc.n_doc_v, cc.n_doc_c, cc.tp_doc_v,
cc.valor_c, cc.valor_liquido, cc.valor_original, cc.data_rec_c, cc.data_venc_c, cc.datq_c, cc.status_c,
case when ((coalesce(cc.valor_original, cc.valor_c) > 0) and (coalesce(cc.valor_liquido, 0) > 0) and (coalesce(cc.valor_original, cc.valor_c) <> coalesce(cc.valor_liquido, 0))) then
        (100 - ((coalesce(cc.valor_original, cc.valor_c, 0) / coalesce(cc.valor_c, 0)) * 100))
     else 0
end taxa_cred,
cc.cod_terminal_adm, termc.desc_term_adm, cc.cod_adm, adm.descricao_adm,
cc.cod_bandeira_adm, bande.descricao,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_status vwf
inner join conciliacao_financeiro cf on
    vwf.id = cf.id
    and vwf.installment_number = cf.installment_number
    and vwf.installments_total = cf.installments_total
    and vwf.cod_empresa = cf.cod_empresa
inner join empresa emp on
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
    band_adq.codigo = cf.bandeira_cod
    and band_adq.id_adquirente = adq.id
left join conciliacao_bandeira band on
    band.id = band_adq.id_bandeira
left join conciliacao_cod_ajuste_adq codajt_adq on
    codajt_adq.codigo = cf.cod_ajuste_cod
    and codajt_adq.id_adquirente = adq.id
left join conciliacao_cod_ajuste codajt on
    codajt.id = codajt_adq.id_cod_ajuste
left join conciliacao_form_pag_adq formpag_adq on
    formpag_adq.codigo = cf.form_pag_cod
    and formpag_adq.id_adquirente = adq.id
left join conciliacao_form_pag formpag on
    formpag.id = formpag_adq.id_form_pag
left join conciliacao_grupo_cartao_adq grcartao_adq on
    grcartao_adq.codigo = cf.grupo_cartao_cod
    and grcartao_adq.id_adquirente = cf.acquirer_id
left join conciliacao_grupo_cartao grcartao on
    grcartao.id = grcartao_adq.id_grupo_cartao
left join conciliacao_motivo_rej_adq motrej_adq on
    motrej_adq.codigo = cf.motivo_rej_cod
    and motrej_adq.id_adquirente = adq.id
left join conciliacao_motivo_rej motrej on
    motrej.id = motrej_adq.id_motivo_rej
left join conciliacao_origem_ajuste_adq orig_transf_adq on
    orig_transf_adq.codigo = cf.origem_ajuste_cod
    and orig_transf_adq.id_adquirente = adq.id
left join conciliacao_origem_ajuste orig_transf on
    orig_transf.id = orig_transf_adq.id_origem_ajuste
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
left join conciliacao_status_transf_adq st_transf_adq on
    st_transf_adq.codigo = cf.status_transf_cod
    and st_transf_adq.id_adquirente = adq.id
left join conciliacao_status_transf st_transf on
    st_transf.id = st_transf_adq.id_status_transf
left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
    tpantec.id = tpantec_adq.id_tipo_antecip
left join conciliacao_tipo_cartao_adq tpcartao_adq on
    tpcartao_adq.codigo = cf.tipo_cartao_cod
    and tpcartao_adq.id_adquirente = adq.id
left join conciliacao_tipo_cartao tpcartao on
    tpcartao.id = tpcartao_adq.id_tipo_cartao
left join conciliacao_tipo_lanc_adq tplanc_adq on
    tplanc_adq.codigo = cf.tipo_lancamento_cod
    and tplanc_adq.id_aquirente = adq.id
left join conciliacao_tipo_lanc tplanc on
    tplanc.id = tplanc_adq.id_tipo_lanc
left join conciliacao_tipo_liq_adq tpliq_adq on
    tpliq_adq.codigo = cf.tipo_liquidacao_cod
    and tpliq_adq.id_adquirente = adq.id
left join conciliacao_tipo_liq tpliq on
    tpliq.id = tpliq_adq.id_tipo_liq
left join conciliacao_tipo_transacao_adq tptr_adq on
    tptr_adq.codigo = cf.tipo_transacao_cod
    and tptr_adq.id_adquirente = adq.id
left join conciliacao_tipo_transacao tptr on
    tptr.id = tptr_adq.id_tipo_transacao
left join p_contas p on
    p.n_conta_plc = (case when (cf.event_net_amount >= 0) then codajt.n_conta_plc_e else codajt.n_conta_plc_s end)
left join getcreditos (
    trim(cf.nsu),
    trim(cf.authorization_number),
    iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)),
    cf.cod_empresa) credq on 1 = 1
left join controle_creditos cc on
    cc.cod_cred = credq.cod_cred
    and cc.codigo_emp = credq.codigo_emp
left join terminal_cartao termc on
    termc.cod_term_adm = cc.cod_terminal_adm 
    and termc.cod_empresa = cc.cod_emp_mult 
left join adm_cartao adm on 
    adm.cod_adm = termc.cod_adm 
    and adm.cod_empresa = termc.cod_empresa 
left join bandeiras_cartao bande on
    bande.cod_bandeira = cc.cod_bandeira_adm
    and bande.cod_empresa = cc.cod_emp_mult
left join retorna_ctrl_ag_conta (
    cf.branch_number,
    cf.account_number,
    cf.cod_empresa) ctrl on 1 = 1
left join controles ctrl2 on
    ctrl2.codigo_ctrl = cc.codigo_ctrl
    and ctrl2.codigo_emp = cc.codigo_emp
where
credq.cod_cred <= 0
and ((trim(cf.event_type_description) = 'Venda') or (trim(cf.event_type_description) like 'Antecipa%'))
and cf.pix_id is null
union
select case when (cf.payment_date is not null) then cf.payment_date else cf.date_ end data,
cf.date_, cf.request_date, cf.effected_date, cf.payment_date, cf.bank_shipping_date,
cf.id, cf.cod_empresa, cf.arquivo, cf.data_arquivo,
cf.establishment_number, cf.nsu, cf.authorization_number, 
cf.type_, cf.type_description,
cf.acquirer_id, cf.acquirer_name,
cf.brand_id, cf.brand_name,
cf.event_type, cf.event_type_description,
tplanc.descricao as description,
stpag.id as bank_recon_status,
stpag.descricao as bank_recon_description,
coalesce(cf.gross_amount, 0) gross_amount,
coalesce(cf.event_net_amount, 0) event_net_amount,
coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
cf.tax, cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number,
emp.identificacao_emp,
ctrl.codigo_ctrl, ctrl.nome_ctrl,
ctrl2.codigo_ctrl as codigo_ctrl_tx, ctrl2.nome_ctrl as nome_ctrl_tx, ctrl2.n_conta_plc_tx_cartao,
cc.n_conta_plc, p.desc_plc,
cc.cod_cred, cc.n_doc_v, cc.n_doc_c, cc.tp_doc_v,
cc.valor_c, cc.valor_liquido, cc.valor_original, cc.data_rec_c, cc.data_venc_c, cc.datq_c, cc.status_c,
case when ((coalesce(cc.valor_original, cc.valor_c) > 0) and (coalesce(cc.valor_liquido, 0) > 0) and (coalesce(cc.valor_original, cc.valor_c) <> coalesce(cc.valor_liquido, 0))) then
        (100 - ((coalesce(cc.valor_original, cc.valor_c, 0) / coalesce(cc.valor_c, 0)) * 100))
     else 0
end taxa_cred,
cc.cod_terminal_adm, termc.desc_term_adm, cc.cod_adm, adm.descricao_adm,
cc.cod_bandeira_adm, bande.descricao,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_pix_status vwfp
inner join conciliacao_financeiro cf on
    vwfp.pix_id = cf.pix_id
    and vwfp.cod_empresa = cf.cod_empresa
inner join empresa emp on
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
    band_adq.codigo = cf.bandeira_cod
    and band_adq.id_adquirente = adq.id
left join conciliacao_bandeira band on
    band.id = band_adq.id_bandeira
left join conciliacao_cod_ajuste_adq codajt_adq on
    codajt_adq.codigo = cf.cod_ajuste_cod
    and codajt_adq.id_adquirente = adq.id
left join conciliacao_cod_ajuste codajt on
    codajt.id = codajt_adq.id_cod_ajuste
left join conciliacao_form_pag_adq formpag_adq on
    formpag_adq.codigo = cf.form_pag_cod
    and formpag_adq.id_adquirente = adq.id
left join conciliacao_form_pag formpag on
    formpag.id = formpag_adq.id_form_pag
left join conciliacao_grupo_cartao_adq grcartao_adq on
    grcartao_adq.codigo = cf.grupo_cartao_cod
    and grcartao_adq.id_adquirente = cf.acquirer_id
left join conciliacao_grupo_cartao grcartao on
    grcartao.id = grcartao_adq.id_grupo_cartao
left join conciliacao_motivo_rej_adq motrej_adq on
    motrej_adq.codigo = cf.motivo_rej_cod
    and motrej_adq.id_adquirente = adq.id
left join conciliacao_motivo_rej motrej on
    motrej.id = motrej_adq.id_motivo_rej
left join conciliacao_origem_ajuste_adq orig_transf_adq on
    orig_transf_adq.codigo = cf.origem_ajuste_cod
    and orig_transf_adq.id_adquirente = adq.id
left join conciliacao_origem_ajuste orig_transf on
    orig_transf.id = orig_transf_adq.id_origem_ajuste
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
left join conciliacao_status_transf_adq st_transf_adq on
    st_transf_adq.codigo = cf.status_transf_cod
    and st_transf_adq.id_adquirente = adq.id
left join conciliacao_status_transf st_transf on
    st_transf.id = st_transf_adq.id_status_transf
left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
    tpantec.id = tpantec_adq.id_tipo_antecip
left join conciliacao_tipo_cartao_adq tpcartao_adq on
    tpcartao_adq.codigo = cf.tipo_cartao_cod
    and tpcartao_adq.id_adquirente = adq.id
left join conciliacao_tipo_cartao tpcartao on
    tpcartao.id = tpcartao_adq.id_tipo_cartao
left join conciliacao_tipo_lanc_adq tplanc_adq on
    tplanc_adq.codigo = cf.tipo_lancamento_cod
    and tplanc_adq.id_aquirente = adq.id
left join conciliacao_tipo_lanc tplanc on
    tplanc.id = tplanc_adq.id_tipo_lanc
left join conciliacao_tipo_liq_adq tpliq_adq on
    tpliq_adq.codigo = cf.tipo_liquidacao_cod
    and tpliq_adq.id_adquirente = adq.id
left join conciliacao_tipo_liq tpliq on
    tpliq.id = tpliq_adq.id_tipo_liq
left join conciliacao_tipo_transacao_adq tptr_adq on
    tptr_adq.codigo = cf.tipo_transacao_cod
    and tptr_adq.id_adquirente = adq.id
left join conciliacao_tipo_transacao tptr on
    tptr.id = tptr_adq.id_tipo_transacao
left join p_contas p on
    p.n_conta_plc = (case when (cf.event_net_amount >= 0) then codajt.n_conta_plc_e else codajt.n_conta_plc_s end)
left join getcreditos (
    trim(cf.nsu),
    trim(cf.authorization_number),
    iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)),
    cf.cod_empresa) credq on 1 = 1
left join controle_creditos cc on
    cc.cod_cred = credq.cod_cred
    and cc.codigo_emp = credq.codigo_emp
left join terminal_cartao termc on 
    termc.cod_term_adm = cc.cod_terminal_adm 
    and termc.cod_empresa = cc.cod_emp_mult 
left join adm_cartao adm on 
    adm.cod_adm = termc.cod_adm 
    and adm.cod_empresa = termc.cod_empresa 
left join bandeiras_cartao bande on
    bande.cod_bandeira = cc.cod_bandeira_adm
    and bande.cod_empresa = cc.cod_emp_mult
left join retorna_ctrl_ag_conta (
    cf.branch_number,
    cf.account_number,
    cf.cod_empresa) ctrl on 1 = 1
left join controles ctrl2 on
    ctrl2.codigo_ctrl = cc.codigo_ctrl
    and ctrl2.codigo_emp = cc.codigo_emp
where credq.cod_cred <= 0
and ((trim(cf.event_type_description) = 'Venda') or (trim(cf.event_type_description) like 'Antecipa%'))
and cf.pix_id is not null
union
select case when (cf.payment_date is not null) then cf.payment_date else cf.date_ end data,
cf.date_, cf.request_date, cf.effected_date, cf.payment_date, cf.bank_shipping_date,
cf.id, cf.cod_empresa, cf.arquivo, cf.data_arquivo,
cf.establishment_number, cf.nsu, cf.authorization_number,
cf.type_, cf.type_description,
cf.acquirer_id, cf.acquirer_name,
cf.brand_id, cf.brand_name,
cf.event_type, cf.event_type_description,
tplanc.descricao as description,
stpag.id as bank_recon_status,
stpag.descricao as bank_recon_description,
coalesce(cf.gross_amount, 0) gross_amount,
coalesce(cf.event_net_amount, 0) event_net_amount,
coalesce(cf.batch_net_amount, 0) batch_net_amount,
coalesce(cf.gross_event_amount, 0) gross_event_amount,
coalesce(cf.batch_gross_amount, 0) batch_gross_amount,
cf.tax, cf.sale_tax, cf.customer_tax,
iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)) installment_number,
iif(coalesce(cf.installments_total, 1) = 0, 1, coalesce(cf.installments_total, 1)) installments_total,
cf.bank_number, cf.bank_name, cf.branch_number, cf.account_number,
emp.identificacao_emp,
ctrl.codigo_ctrl, ctrl.nome_ctrl,
ctrl2.codigo_ctrl as codigo_ctrl_tx, ctrl2.nome_ctrl as nome_ctrl_tx, ctrl2.n_conta_plc_tx_cartao,
cc.n_conta_plc, p.desc_plc,
cc.cod_cred, cc.n_doc_v, cc.n_doc_c, cc.tp_doc_v,
cc.valor_c, cc.valor_liquido, cc.valor_original, cc.data_rec_c, cc.data_venc_c, cc.datq_c, cc.status_c,
case when ((coalesce(cc.valor_original, cc.valor_c) > 0) and (coalesce(cc.valor_liquido, 0) > 0) and (coalesce(cc.valor_original, cc.valor_c) <> coalesce(cc.valor_liquido, 0))) then
        (100 - ((coalesce(cc.valor_original, cc.valor_c, 0) / coalesce(cc.valor_c, 0)) * 100))
     else 0
end taxa_cred,
cc.cod_terminal_adm, termc.desc_term_adm, cc.cod_adm, adm.descricao_adm,
cc.cod_bandeira_adm, bande.descricao,
cf.pix_id,
cf.form_pag_cod, formpag.descricao form_pag,
cf.cod_ajuste_cod, codajt.descricao cod_ajuste,
cf.bandeira_cod, band.nome bandeira,
cf.status_pag_cod, stpag.descricao status_pag, stpag_adq.status status_pag_st,
cf.tipo_lancamento_cod, tplanc.descricao tipo_lancamento,
cf.tipo_liquidacao_cod, tpliq.descricao tipo_liquidacao,
cf.tipo_antecipacao_cod, tpantec.descricao tipo_antecipacao,
cf.tipo_cartao_cod, tpcartao.descricao tipo_cartao,
cf.motivo_rej_cod, motrej.descricao motivo_rej,
cf.grupo_cartao_cod, grcartao.descricao grupo_cartao,
cf.tipo_transacao_cod, tptr.descricao tipo_transacao,
cf.status_transf_cod, st_transf.descricao status_trans, st_transf_adq.status status_trans_st,
cf.origem_ajuste_cod, orig_transf.descricao origem_ajuste
from vw_conc_financ_status vwf
inner join conciliacao_financeiro cf on
    vwf.id = cf.id
    and vwf.installment_number = cf.installment_number
    and vwf.installments_total = cf.installments_total
    and vwf.cod_empresa = cf.cod_empresa
inner join empresa emp on
    emp.cod_empresa = cf.cod_empresa
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_band_adq band_adq on
    band_adq.codigo = cf.bandeira_cod
    and band_adq.id_adquirente = adq.id
left join conciliacao_bandeira band on
    band.id = band_adq.id_bandeira
left join conciliacao_cod_ajuste_adq codajt_adq on
    codajt_adq.codigo = cf.cod_ajuste_cod
    and codajt_adq.id_adquirente = adq.id
left join conciliacao_cod_ajuste codajt on
    codajt.id = codajt_adq.id_cod_ajuste
left join conciliacao_form_pag_adq formpag_adq on
    formpag_adq.codigo = cf.form_pag_cod
    and formpag_adq.id_adquirente = adq.id
left join conciliacao_form_pag formpag on
    formpag.id = formpag_adq.id_form_pag
left join conciliacao_grupo_cartao_adq grcartao_adq on
    grcartao_adq.codigo = cf.grupo_cartao_cod
    and grcartao_adq.id_adquirente = cf.acquirer_id
left join conciliacao_grupo_cartao grcartao on
    grcartao.id = grcartao_adq.id_grupo_cartao
left join conciliacao_motivo_rej_adq motrej_adq on
    motrej_adq.codigo = cf.motivo_rej_cod
    and motrej_adq.id_adquirente = adq.id
left join conciliacao_motivo_rej motrej on
    motrej.id = motrej_adq.id_motivo_rej
left join conciliacao_origem_ajuste_adq orig_transf_adq on
    orig_transf_adq.codigo = cf.origem_ajuste_cod
    and orig_transf_adq.id_adquirente = adq.id
left join conciliacao_origem_ajuste orig_transf on
    orig_transf.id = orig_transf_adq.id_origem_ajuste
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
left join conciliacao_status_transf_adq st_transf_adq on
    st_transf_adq.codigo = cf.status_transf_cod
    and st_transf_adq.id_adquirente = adq.id
left join conciliacao_status_transf st_transf on
    st_transf.id = st_transf_adq.id_status_transf
left join conciliacao_tipo_antecip_adq tpantec_adq on
    tpantec_adq.codigo = cf.tipo_antecipacao_cod
    and tpantec_adq.id_adquirente = adq.id
left join conciliacao_tipo_antecip tpantec on
    tpantec.id = tpantec_adq.id_tipo_antecip
left join conciliacao_tipo_cartao_adq tpcartao_adq on
    tpcartao_adq.codigo = cf.tipo_cartao_cod
    and tpcartao_adq.id_adquirente = adq.id
left join conciliacao_tipo_cartao tpcartao on
    tpcartao.id = tpcartao_adq.id_tipo_cartao
left join conciliacao_tipo_lanc_adq tplanc_adq on
    tplanc_adq.codigo = cf.tipo_lancamento_cod
    and tplanc_adq.id_aquirente = adq.id
left join conciliacao_tipo_lanc tplanc on
    tplanc.id = tplanc_adq.id_tipo_lanc
left join conciliacao_tipo_liq_adq tpliq_adq on
    tpliq_adq.codigo = cf.tipo_liquidacao_cod
    and tpliq_adq.id_adquirente = adq.id
left join conciliacao_tipo_liq tpliq on
    tpliq.id = tpliq_adq.id_tipo_liq
left join conciliacao_tipo_transacao_adq tptr_adq on
    tptr_adq.codigo = cf.tipo_transacao_cod
    and tptr_adq.id_adquirente = adq.id
left join conciliacao_tipo_transacao tptr on
    tptr.id = tptr_adq.id_tipo_transacao
left join p_contas p on
    p.n_conta_plc = (case when (cf.event_net_amount >= 0) then codajt.n_conta_plc_e else codajt.n_conta_plc_s end)
left join getcreditos (
    trim(cf.nsu),
    trim(cf.authorization_number),
    iif(coalesce(cf.installment_number, 1) = 0, 1, coalesce(cf.installment_number, 1)),
    cf.cod_empresa) credq on 1 = 1
left join controle_creditos cc on
    cc.cod_cred = credq.cod_cred
    and cc.codigo_emp = credq.codigo_emp
left join terminal_cartao termc on 
    termc.cod_term_adm = cc.cod_terminal_adm 
    and termc.cod_empresa = cc.cod_emp_mult 
left join adm_cartao adm on 
    adm.cod_adm = termc.cod_adm 
    and adm.cod_empresa = termc.cod_empresa 
left join bandeiras_cartao bande on
    bande.cod_bandeira = cc.cod_bandeira_adm
    and bande.cod_empresa = cc.cod_emp_mult
left join retorna_ctrl_ag_conta (
    cf.branch_number,
    cf.account_number,
    cf.cod_empresa) ctrl on 1 = 1
left join controles ctrl2 on
    ctrl2.codigo_ctrl = cc.codigo_ctrl
    and ctrl2.codigo_emp = cc.codigo_emp
where credq.cod_cred <= 0
and trim(cf.event_type_description) in ('Cancelamento', 'Chargeback')
;

/* View: PAGAMENTOS2, Owner: SYSDBA */
CREATE VIEW PAGAMENTOS2 (TP_RECEBIMENTO, ORDEM, TIPO, TIPO2, COD_EMPRESA, COD_EMP_ORIG, COD_EMP_MULT, DATA_CONF, CODIGO_CTRL, NOME_CTRL, VALOR_PAGO, DATA_MOV, DATA_VENC, SEQID, SEQID2, VALOR_PAGO_PROP) AS

-- VIEW EXIBE OS PAGAMENTOS REALIZADOS
-- RELATORIO "PAGAMENTO FINANCEIRO"
    select distinct 'DIRETO', 1, 'PAGAMENTOS',
    case when (ctr1.nome_ctrl is null) then '' else ctr1.nome_ctrl end tipo2,
    (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else ctp.codigo_emp end) cod_empresa,
    ctp.codigo_emp,
    ctp.cod_emp_mult,
    ctp.datq_ctp,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    iif(ctp.datq_ctp is null, 0, coalesce(det.valor, 0)) valordoc, det.data_rec, det.data_venc,
    coalesce(det.codigo, ctp.cod_contrp), coalesce(det.codigo, ctp.cod_contrp),

    case when (coalesce((case when (ctp.lote <= 0) then
                       ctp.valor_ctp
                     else
                       (select sum(coalesce(cp.valor_pago, 0)) from contas_a_pagar cp
                        left join empresa e on cp.codigo_emp = e.cod_empresa
                        where cp.lote = ctp.lote
                        and cp.datq_ctp = ctp.datq_ctp
                        and (case when(e.financeiro_unificado = 'S') then e.codigo_unificadora else cp.codigo_emp end) =
                            (case when(e.financeiro_unificado = 'S') then e.codigo_unificadora else ctp.codigo_emp end))
                end), 0)) <= 0 then
           0
         else
            ((coalesce((case when (ctp.lote <= 0) then
                               ctp.valor_ctp
                             else
                               (select sum(coalesce(cp.valor_pago, 0)) from contas_a_pagar cp
                                where cp.lote = ctp.lote
                                and cp.datq_ctp = ctp.datq_ctp
                                and cp.cod_emp_mult = ctp.cod_emp_mult)
                        end), 0) /
              coalesce((case when (ctp.lote <= 0) then
                               ctp.valor_ctp
                             else
                               (select sum(coalesce(cp.valor_pago, 0)) from contas_a_pagar cp
                                left join empresa e on cp.codigo_emp = e.cod_empresa
                                where cp.lote = ctp.lote
                                and cp.datq_ctp = ctp.datq_ctp
                                and (case when(e.financeiro_unificado = 'S') then e.codigo_unificadora else cp.codigo_emp end) =
                                    (case when(e.financeiro_unificado = 'S') then e.codigo_unificadora else ctp.codigo_emp end))
                        end), 0)) *
              coalesce(det.valor, 0) 
            )
    end valor_pago_prop

    from contas_a_pagar ctp
    left join empresa emp on ctp.codigo_emp = emp.cod_empresa
    inner join det_pagamentos det on
        iif(emp.financeiro_unificado = 'S', det.cod_empresa, det.cod_emp_lote) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, emp.cod_empresa)
        and det.lote = ctp.lote
        and det.data_lote = iif(emp.financeiro_unificado = 'S', ctp.datq_ctp, det.data_lote)
        and det.parcial is null
        and det.renegociacao is null
    left join controles ctr on ctr.codigo_ctrl = det.codigo_ctrl and ctr.codigo_emp = det.cod_empresa
    left join controles ctr1 on ctr1.codigo_ctrl = ctp.codigo_ctrl and ctr1.codigo_emp = ctp.codigo_emp
    where ctp.datq_ctp is not null

    union

    select distinct 'DIRETO', 1, 'PAGAMENTOS',
    case when (ctr1.nome_ctrl is null) then '' else ctr1.nome_ctrl end tipo2,
    (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else ctp.codigo_emp end) cod_empresa,
    ctp.codigo_emp,
    ctp.cod_emp_mult,
    ctp.data_ent_ctp,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    iif(ctp.datq_ctp is null, 0, coalesce(det.valor, 0)) valordoc, det.data_rec, det.data_venc,
    coalesce(det.codigo, ctp.cod_contrp), coalesce(det.codigo, ctp.cod_contrp),

    case when (coalesce((case when (ctp.lote <= 0) then
                       ctp.valor_ctp
                     else
                       (select sum(coalesce(cp.valor_pago, 0)) from contas_a_pagar cp
                        left join empresa e on cp.codigo_emp = e.cod_empresa
                        where cp.lote = ctp.lote
                        and cp.datq_ctp = ctp.datq_ctp
                        and (case when(e.financeiro_unificado = 'S') then e.codigo_unificadora else cp.codigo_emp end) =
                            (case when(e.financeiro_unificado = 'S') then e.codigo_unificadora else ctp.codigo_emp end))
                end), 0)) <= 0 then
           0
         else
            ((coalesce((case when (ctp.lote <= 0) then
                               ctp.valor_ctp
                             else
                               (select sum(coalesce(cp.valor_pago, 0)) from contas_a_pagar cp
                                where cp.lote = ctp.lote
                                and cp.datq_ctp = ctp.datq_ctp
                                and cp.cod_emp_mult = ctp.cod_emp_mult)
                        end), 0) /
              coalesce((case when (ctp.lote <= 0) then
                               ctp.valor_ctp
                             else
                               (select sum(coalesce(cp.valor_pago, 0)) from contas_a_pagar cp
                                left join empresa e on cp.codigo_emp = e.cod_empresa
                                where cp.lote = ctp.lote
                                and cp.datq_ctp = ctp.datq_ctp
                                and (case when(e.financeiro_unificado = 'S') then e.codigo_unificadora else cp.codigo_emp end) =
                                    (case when(e.financeiro_unificado = 'S') then e.codigo_unificadora else ctp.codigo_emp end))
                        end), 0)) *
              coalesce(det.valor, 0) 
            )
    end valor_pago_prop

    from contas_a_pagar ctp
    left join empresa emp on ctp.codigo_emp = emp.cod_empresa
    left join det_pagamentos det on
        iif(emp.financeiro_unificado = 'S', det.cod_empresa, det.cod_emp_lote) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, emp.cod_empresa)
        and det.lote = ctp.lote
        and det.data_lote = iif(emp.financeiro_unificado = 'S', ctp.datq_ctp, det.data_lote)
        and det.parcial is null
        and det.renegociacao is null
    left join controles ctr on ctr.codigo_ctrl = det.codigo_ctrl and ctr.codigo_emp = det.cod_empresa
    left join controles ctr1 on ctr1.codigo_ctrl = ctp.codigo_ctrl and ctr1.codigo_emp = ctp.codigo_emp
    where ctp.datq_ctp is null
;

/* View: DET_RECEBIMENTOS_CH, Owner: SYSDBA */
CREATE VIEW DET_RECEBIMENTOS_CH (CODIGO, COD_EMPRESA, COD_EMP_MULT, COD_EMP_LOTE, CODIGO_CTRL, NOME_CTRL, VALOR, NOME, STATUS, DATA_VENC, HISTORICO, N_CH, DATA_REC, TIPO_DOC_C, N_CONTA_PLC, LOTE, DATA_LOTE) AS

select distinct l.cod_lanc,
    case when (emp.financeiro_unificado = 'S') then emp.codigo_unificadora else l.codigo_emp end codigo_emp,
    l.cod_emp_mult,
    case when (emp.financeiro_unificado = 'S') then emp.codigo_unificadora else l.codigo_emp end codigo_emp,
    
    coalesce((case when (((select count(*) from hist_rec hist where hist.lote_quit = pr.lote_quit and hist.cod_empresa = pr.codigo_emp) > 0)
                    and ((l.historico_l like '%RECIBOS ATENCIPADOS%') or (l.historico_l like '%RECIBOS ANTECIPADOS%'))) then
                     case when (l.tipo_l = 'S') then
                            0
                          else
                            888888
                     end
                   else
                     case when ctr.codigo_ctrl is null then
                            case when coalesce(pr.tip_baixa, '') = 'D' then
                                   666666
                                 else
                                   0
                            end
                          else
                            ctr.codigo_ctrl
                     end
              end),
    0) codigo_ctrl,

    coalesce((case when (((select count(*) from hist_rec hist where hist.lote_quit = pr.lote_quit and hist.cod_empresa = pr.codigo_emp) > 0)
                    and ((l.historico_l like '%RECIBOS ATENCIPADOS%') or (l.historico_l like '%RECIBOS ANTECIPADOS%'))) then
                     case when (l.tipo_l = 'S') then
                            'SEM FORMA'
                          else
                            'RECIBO ANTECIPADO'
                     end
                   else
                     case when ctr.nome_ctrl is null then
                            case when coalesce(pr.tip_baixa, '') = 'D' then
                                   'DEVOLUCAO'
                                 else
                                   'SEM FORMA'
                            end
                          else
                            ctr.nome_ctrl
                     end
              end),
    'SEM FORMA') nome_ctrl,

    case when coalesce(pr.tip_baixa, '') = 'D' then coalesce(pr.valor_ch, 0) else coalesce(l.valor_l, 0) end valor_pago,
    '' nome_c,
    'QUITADO' status,
    l.data,
    l.historico_l,
    l.ndoc_l,
    l.dtreferencia,

    coalesce(case when (ctr.nome_ctrl is null) then 0 else ctr.nome_ctrl end, 'SEM FORMA') tipo_doc_c,

    l.n_conta_plc,
    pr.lote_quit,
    pr.datq_ch from controle_cheque pr
    left join empresa emp on pr.codigo_emp = emp.cod_empresa
    left join lancamentos l on
        l.lote_ent = pr.lote_quit
        and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, l.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp)
        and l.data = pr.datq_ch
        and l.tipo_l = 'E'
    left join controles ctr on
        ctr.codigo_ctrl = l.codigo_ctrl
        and ctr.codigo_emp = l.codigo_emp
    left join CONTROLES ctr1 on
        ctr1.codigo_ctrl = pr.codigo_ctrl
        and ctr1.codigo_emp = pr.codigo_emp
    where coalesce(pr.tip_baixa, '') <> 'C' and pr.datq_ch is not null

    union all

    select distinct pr.codigo_ch,
    case when (emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pr.codigo_emp end codigo_emp,
    pr.cod_emp_mult,
    pr.cod_emp_lote, 

    999999 codigo_ctrl,

    'CONTAS A PAGAR' nome_ctrl,

    coalesce(pr.valor_ch, 0) valor_pago,
    '' nome_c,
    'QUITADO' status,
    pr.datq_ch,
    pr.historico_ch,
    pr.n_doc_v,
    pr.data_rec,

    'CONTAS A PAGAR' historico_l,

    0 n_conta_plc,
    pr.lote_quit,
    pr.datq_ch

    from controle_cheque pr
    left join empresa emp on pr.codigo_emp = emp.cod_empresa
    where pr.tip_baixa = 'C' and pr.datq_ch is not null
;

/* View: FICHAPRODUTOSDETALHADA2, Owner: SYSDBA */
CREATE VIEW FICHAPRODUTOSDETALHADA2 (ORDEM, TIPO, TIPO2, NATUREZA, COD_EMPRESA, EMPRESA, NUMDOC, DATA, DATA_CONFIRM, STATUS, QTDE, VALOR_UNIT, VALOR_TOTAL, ALTERA_ESTOQUE, ALTERA_CUSTO, CUSTO_MEDIO, NITEM_ID, GRUPO_PROD, COD_PROD, NUM_FAB_PROD, DESCR_PROD, COD_GRADE, GRADE, COD_CLIENTE_FORNECEDOR, CLIENTE_FORNECEDOR, TIPO_VND_OS_DEV, TIPO_VENDA, NUM_VENDA, COD_NF, COD_CFOP, CFOP, ALIQ_ICM, BASE_ICM, VALOR_ICM, ALIQ_ST, BASE_ST, VALOR_ST, ALIQ_IPI, BASE_IPI, VALOR_IPI, DATA_ESTOQUE, SEQID) AS

select '4' "Ordem", 'BAL' || ini.TIP_BAL "Tipo", 'BAL' || ini.TIP_BAL "Tipo2",
iif(coalesce(ingr.qtd_dif_bal, ini.qtd_dif_bal) > 0, 'E', 'S') "Natuzeza", ini.cod_empresa "Cod Empresa", emp.nome_emp "Empresa",
0 "Numero", ini.data_cadastro "Data", ini.data_confirm "Data Confirm",
case when (ini.data_confirm is not null) then
 'FECHADA'
else
  '' end,
case when (coalesce(ingr.cod_grade, 0) > 0) then
    abs(coalesce(ingr.qtd_dif_bal, 0))
else
    abs(coalesce(ini.qtd_dif_bal, 0))
end "Quantidade",
0 "Valor Unit", 0 "Valor Total",
case when (ini.data_confirm is not null) then 'S'
     else 'N' end "Altera Estoque",
'N' "Altera Custo", ini.pcust_mc "Custo Med", 0 "Seq ID",
ini.grupo_prod "Grupo", ini.cod_prod "Cod Prod", ini.num_fab_prod "Num Fab",
pr.descr_prod "Descricao",
coalesce(ingr.cod_grade, 0) "Cod. Grade", coalesce(gra.descricao,'SEM GRADE') "Descricao Grade",
0 "Cod Cliente", '' "Cliente/Fornecedor",
'' "Tipo", '' "Tipo Venda", 0 "Num Venda",
0 "Cod NF", 0 "Cod CFOP", '' "CFOP",
0 "Aliq ICM", 0 "Base ICM", 0 "Valor ICM",
0 "Aliq ST", 0 "Base ST", 0 "Valor ST",
0 "Aliq IPI", 0 "Base IPI", 0 "Valor IPI",
case when (ini.data_confirm is not null) then ini.data_confirm
else ini.data_cadastro end "Data Estoque", 0 "Seq Id"
  from estoque_ini ini
left join estoque_ini_grade ingr on ini.grupo_prod = ingr.grupo_prod and ini.cod_prod = ingr.cod_prod and ini.cod_empresa = ingr.cod_empresa and ini.data_cadastro = ingr.data_cadastro
left join grade gra on gra.cod_grade = ingr.cod_grade and gra.cod_empresa = ingr.cod_empresa
left join produtos pr on pr.grupo_prod = ini.grupo_prod and pr.cod_prod = ini.cod_prod and pr.cod_empresa = ini.cod_empresa
inner join empresa emp on emp.cod_empresa = ini.cod_empresa
union all
/*select '4' "Ordem", 'BALG*' "Tipo", 'BALG' "Tipo2",
case when (balp.qtd_dif_bal > 0) then 'E' else 'S' end "Natuzeza", balp.cod_empresa "Cod Empresa", emp.nome_emp "Empresa",
0 "Numero", cast(cast(balp.data_hora_leitura as date) as timestamp) "Data", null "Data Confirm",
'',
case when (coalesce(balpg.cod_grade, 0) > 0) then
  case when (balpg.qtd_dif_bal > 0) then
    coalesce(balpg.qtd_dif_bal, 0)
  else
    coalesce(balpg.qtd_dif_bal, 0) * -1
  end
else
  case when (balp.qtd_dif_bal > 0) then
    coalesce(balp.qtd_dif_bal, 0)
  else
    coalesce(balp.qtd_dif_bal, 0) * -1
  end
end "Quantidade",
0 "Valor Unit", 0 "Valor Total",
'N' "Altera Estoque",
'N' "Altera Custo", balp.prec_cusm_prod "Custo Med", 0 "Seq ID1",
balp.grupo_prod "Grupo", balp.cod_prod "Cod Prod", balp.cod_barra "Num Fab",
pr.descr_prod "Descricao",
coalesce(balpg.cod_grade, 0) "Cod. Grade", coalesce(gra.descricao,'SEM GRADE') "Descricao Grade",
0 "Cod Cliente", '' "Cliente/Fornecedor",
'' "Tipo", '' "Tipo Venda", 0 "Num Venda",
0 "Cod NF", 0 "Cod CFOP", '' "CFOP",
0 "Aliq ICM", 0 "Base ICM", 0 "Valor ICM",
0 "Aliq ST", 0 "Base ST", 0 "Valor ST",
0 "Aliq IPI", 0 "Base IPI", 0 "Valor IPI",
cast(cast(balp.data_hora_leitura as date) as timestamp) "Data Estoque", 0 "Seq Id"
from balanco_produtos balp
left join cod_grade_balanco balpg on balp.grupo_prod = balpg.grupo_prod and balp.cod_prod = balpg.cod_prod and balp.cod_empresa = balpg.cod_empresa
left join grade gra on gra.cod_grade = balpg.cod_grade and gra.cod_empresa = balpg.cod_empresa
inner join produtos pr on pr.grupo_prod = balp.grupo_prod and pr.cod_prod = balp.cod_prod and pr.cod_empresa = balp.cod_empresa
inner join empresa emp on emp.cod_empresa = balp.cod_empresa
union all  */
select 1 "Ordem", 'NF' "Tipo", ('NF'||nf4.natureza_nf) "Tipo2", nf4.natureza_nf "Natureza",
nf4.cod_empresa "Cod Empresa", emp.nome_emp "Empresa", nf4.num_nf "Numero",
/*case when (nf4.natureza_nf = 'E') then nf4.data_ent_saida
     else nf4.data_lanc end "Data",*/
nf4.data_lanc "Data",
nf4.data_lanc "Data Confirm",
upper(trim(NF4.status)),
case when grcomp.QTDE is null then it4.quantidade else grcomp.qtde end "Quantidade",
it4.valor_unitario "Valor Unit", it4.valor_total "Valor Total",
case when (nf4.natureza_nf = 'S') then 'N'
     when (nf4.status = 'Fechada') and (it4.altera_estoque_cfop is null) then 'S'
     when (nf4.status = 'Fechada') and (it4.altera_estoque_cfop <> 'N') then 'S'
     else 'N' end "Altera Estoque",
case when (nf4.natureza_nf = 'S') then 'N'
  when (coalesce(it4.altera_custo_cfop, 'S') = '') then 'S'
  else coalesce(it4.altera_custo_cfop, 'S') end "Altera Custo",
it4.prec_cusm_prod "Custo Med", it4.nitem "N Item/Id",
it4.grupo_prod "Grupo", it4.cod_prod "Cod Prod", pr.num_fab_prod "Num Fab",
case when (it4.cod_grade > 0) then
  case when (trim(nf4.natureza_nf) = 'S') then
    it4.descricao_item||' - '||coalesce(gras.descricao,'')
  else
    it4.descricao_item||' - '||coalesce(gra.descricao,'') end
else
  it4.descricao_item
end  "Descricao",
coalesce(gra.cod_grade,0) "Cod Grade",
case when (trim(nf4.natureza_nf) = 'S') then
     coalesce(gras.descricao, 'SEM GRADE')
     else coalesce(gra.descricao,'SEM GRADE') end "Grade",
nf4.cod_cliente "Cod Cliente", cl.nome_cliente "Cliente/Fornecedor",
'' "Tipo Vnd/OS/DEV", '' "Tipo Venda", 0 "Num Venda",
nf4.cod_nf "Cod NF", it4.codigo_nop "Cod CFOP", nat.descricao_nop "CFOP",
it4.aliq_icm "Aliq ICM", it4.base_icm "Base ICM", it4.valor_icm "Valor ICM",
it4.aliq_icmsub "Aliq ST", it4.base_icmsub "Base ST", it4.valor_icmsub "Valor ST",
it4.aliq_ipi "Aliq IPI", it4.base_ipi "Base IPI", it4.valor_ipi "Valor IPI",
case when (nf4.natureza_nf = 'S') then nf4.data_lanc
    else nf4.data_estoque end  "Data Estoque", nf4.cod_nf "Seq Id"
from notafiscal nf4
inner join notafiscal_item it4 on nf4.cod_nf=it4.cod_nf and nf4.cod_empresa=it4.cod_empresa
inner join empresa emp on emp.cod_empresa = nf4.cod_empresa
left join nat_op nat on nat.codigo_nop = it4.codigo_nop
left join cod_grade_prod_compra grcomp on
it4.grupo_prod = grcomp.grupo_prod and it4.cod_prod = grcomp.cod_prod and it4.cod_empresa = grcomp.cod_empresa and
it4.cod_nf = grcomp.num_nota_nfe and it4.nitem = grcomp.cod_forn_nfe
left join grade gra on grcomp.cod_grade = gra.cod_grade and grcomp.cod_empresa = gra.cod_empresa
left join grade gras on it4.cod_grade = gras.cod_grade and it4.cod_empresa = gras.cod_empresa
inner join produtos pr on it4.grupo_prod = pr.grupo_prod and it4.cod_prod = pr.cod_prod
and it4.cod_empresa = pr.cod_empresa
inner join clientes cl on nf4.cod_cliente=cl.cod_cliente and nf4.cod_empresa=cl.cod_empresa
/*where nf4.natureza_nf = 'E' and (nf4.status = 'Fechada')*/
/*and (it4.altera_estoque_cfop <> 'N' or it4.altera_estoque_cfop is null)*/
/*and*/ where nf4.ativo=1 and upper(trim(nf4.status)) <> 'CANCELADA'
union all
select 1 "Ordem", 'NF' "Tipo", 'NFE' "Tipo2", 'E' "Natureza",
nfe.cod_empresa "Cod Empresa", emp.nome_emp "Empresa", nfe.num_nota_nfe "Numero",
nfe.data_lanc_nfe "Data", nfe.data_lanc_nfe "Data Confirm", 'FECHADA' "Status",
case when grcomp.QTDE is null then infe.quant_item_nfe else grcomp.qtde end "Quantidade",
infe.vlun_item_nfe "Valor Unit", infe.vltot_item_nfe "Valor Total",
'S' "Alterar Estoque", coalesce(nat.calc_custo, 'S') "Altera Custo",
coalesce(infe.prec_cusm_prod, 0) "Custo Med", coalesce(infe.n_item, 0) "N Item/Id",
infe.grupo_prod "Grupo", infe.cod_prod "Cod Prod", infe.num_fab_prod "Num Fab",
case when (grcomp.cod_grade > 0) then
  infe.descprod||' - '||coalesce(gra.descricao,'')
else
  infe.descprod
end  "Descricao",
coalesce(gra.cod_grade,0) "Cod Grade", coalesce(gra.descricao,'SEM GRADE') "Grade",
0 "Cod Cliente", fr.nome "Cliente/Fornecedor",
'' "Tipo Vnd/OS/DEV", '' "Tipo Venda", 0 "Num Venda",
0 "Cod NF", infe.codigo_nop "Cod CFOP", nat.descricao_nop "CFOP",
coalesce(infe.alicm_item_nfe, 0) "Aliq ICM", coalesce(infe.baseicms_it_nfe, 0) "Base ICM", coalesce(infe.icms_it_nfe, 0) "Valor ICM",
0 "Aliq ST", coalesce(infe.bicmsub_nfe, 0) "Base ST", coalesce(infe.icmsub_nfe, 0) "Valor ST",
0 "Aliq IPI", coalesce(infe.baseipi_it_nfe, 0) "Base IPI", coalesce(infe.ipi_item_nfe, 0) "Valor IPI",
nfe.data_lanc_nfe "Data Estoque", nfe.num_nota_nfe "Seq Id"
from nf_entrada nfe
inner join item_nf_entrada infe on infe.num_nota_nfe = nfe.num_nota_nfe and infe.cod_forn_nfe = nfe.cod_forn_nfe and infe.cod_empresa = nfe.cod_empresa
inner join empresa emp on emp.cod_empresa = nfe.cod_empresa
left join nat_op nat on nat.codigo_nop = infe.codigo_nop
left join cod_grade_prod_compra grcomp on
infe.grupo_prod = grcomp.grupo_prod and infe.cod_prod = grcomp.cod_prod and infe.cod_empresa = grcomp.cod_empresa and
infe.num_nota_nfe = grcomp.num_nota_nfe and infe.cod_forn_nfe = grcomp.cod_forn_nfe
left join grade gra on grcomp.cod_grade = gra.cod_grade and grcomp.cod_empresa = gra.cod_empresa
inner join produtos pr on infe.grupo_prod = pr.grupo_prod and infe.cod_prod = pr.cod_prod
and infe.cod_empresa = pr.cod_empresa
inner join fornecedor fr on fr.codigo_f = nfe.cod_forn_nfe and fr.cod_empresa = nfe.cod_empresa
where nfe.status_nfe = 'CONFIRMADA'
and nfe.ativo = 1
union all
select '1' "Ordem", 'NF' "Tipo", 'NFS' "Tipo2", 'S' "Natureza",
nfs.cod_empresa "Cod Empresa", emp.nome_emp "Empresa", nfs.num_nf_vnd "Numero",
nfs.data_ets_vnd "Data", nfs.data_ets_vnd "Data Confirm", 'FECHADA' "Status",
infs.quant_item_vnd "Quantidade",
infs.vlun_item_vnd "Valor Unit", infs.vltot_item_vnd "Valor Total",
'N' "Alterar Estoque", 'N' "Altera Custo",
0 "Custo Med", 0 "N Item/Id",
infs.grupo_prod "Grupo", infs.cod_prod "Cod Prod", infs.num_fab_prod "Num Fab",
infs.desc_prod_nf "Descricao",
0 "Cod Grade", 'SEM GRADE' "Grade",
null "Cod Cliente", cl.nome_cliente "Cliente/Fornecedor",
'' "Tipo Vnd/OS/DEV", '' "Tipo Venda", 0 "Num Venda",
0 "Cod NF", infs.codigo_nop "Cod CFOP", nat.descricao_nop "CFOP",
0 "Aliq ICM", coalesce(infs.baseicms_it, 0) "Base ICM", coalesce(infs.icms_it, 0) "Valor ICM",
0 "Aliq ST", coalesce(infs.bicmsub_vnd, 0) "Base ST", coalesce(infs.icmsub_vnd, 0) "Valor ST",
0 "Aliq IPI", 0 "Base IPI", 0 "Valor IPI",
nfs.data_ets_vnd "Data Estoque", nfs.num_nf_vnd "Seq ID"  from nf_venda nfs
inner join item_nfvenda infs on infs.num_nf_vnd = nfs.num_nf_vnd and infs.cod_empresa = nfs.cod_empresa
inner join empresa emp on emp.cod_empresa = nfs.cod_empresa
inner join clientes cl on cl.cod_cliente = nfs.cod_cliente and cl.cod_empresa = nfs.cod_empresa
left join nat_op nat on nat.codigo_nop = infs.codigo_nop
union all
select 2 "Ordem", 'PDC' "Tipo", 'PDC' "Tipo2", 'E' "Natureza", pi.cod_empresa "Cod Empresa", emp.nome_emp "Empresa",
pd.cod_producao "Numero", pd.data "Data", pd.data_fechamento "Data Confirm",
pd.status,
pi.quantidade "Quantidade",
pi.prec_cus_prod "Custo Unit", (pi.quantidade * pi.prec_cus_prod) "Custo Total",
case when (trim(pd.status) = 'FECHADO') then 'S'
     else 'N' end "Altera Estoque",
'N' "Altera Custo", pi.prec_cusm_prod "Custo Med", pi.nitem "N Item",
pi.grupo_prod "Grupo", pi.cod_prod "Cod Prod", pi.num_fab_prod "Num Fab",
pi.descr_prod "Descricao",
gra.cod_grade "Cod Grade", gra.descricao "Descricao Grade",
0 "Cod Cliente", emp.nome_emp "Cliente/Fornecedor",
'' "Tipo", '' "Tipo Venda", 0 "Num Venda",
0 "Cod NF", 0 "Cod CFOP", '' "CFOP",
0 "Aliq ICM", 0 "Base ICM", 0 "Valor ICM",
0 "Aliq ST", 0 "Base ST", 0 "Valor ST",
0 "Aliq IPI", 0 "Base IPI", 0 "Valor IPI",
case when (pd.data_fechamento is not null) then pd.data_estoque
     else pd.data end "Data Estoque", pd.cod_producao "Seq Id"
from producao pd
inner join producao_item pi on pi.cod_producao = pd.cod_producao and pi.cod_empresa = pd.cod_empresa
inner join empresa emp on emp.cod_empresa = pd.cod_empresa
left join grade gra on gra.cod_grade = pi.cod_grade and gra.cod_empresa = pi.cod_empresa
/*where pd.status = 'FECHADO'*/
union all
select 3 "Ordem", 'DEV' "Tipo", 'DEV' "Tipo2", 'E' "Natureza", dev.cod_empresa "Cod Empresa", emp.nome_emp "Empresa",
dev.sequencia "Numero", dev.data "Data", dev.data "Data Confirm",
'FECHADA', dev.quant "Quantidade",
dev.valor "Valor Unit", (dev.valor * dev.quant) "Valor Total",
case when (coalesce(dev.nf_gerou, '') <> 'S') then 'S' else 'N' end "Altera Estoque",
'N' "Altera Custo", dev.pcust_mc "Custo Med", dev.seqid "Seq ID",
dev.grupo_prod "Grupo", dev.cod_prod "Cod Prod", dev.num_fab_prod "Num Fab",
dev.descricao "Descricao",
coalesce(gra.cod_grade, 0) "Cod. Grade", coalesce(gra.descricao,'SEM GRADE') "Descricao Grade",
cl.cod_cliente "Cod Cliente", cl.nome_cliente "Cliente/Fornecedor",
dev.tipo "Tipo", dev.tipo_venda "Tipo Venda", coalesce(dev.cod_venda, 0) "Num Venda",
coalesce(dev.cod_nf, 0) "Cod NF", 0 "Cod CFOP", '' "CFOP",
0 "Aliq ICM", 0 "Base ICM", 0 "Valor ICM",
0 "Aliq ST", 0 "Base ST", 0 "Valor ST",
0 "Aliq IPI", 0 "Base IPI", 0 "Valor IPI", dev.data_estoque "Data Estoque", dev.sequencia "Seq Id"
from devolucao dev
inner join empresa emp on emp.cod_empresa = dev.cod_empresa
left join grade gra on gra.cod_grade = dev.cod_grade and gra.cod_empresa = dev.cod_empresa
inner join clientes cl on cl.cod_cliente = dev.cod_cliente and cl.cod_empresa = dev.cod_empresa
/*where coalesce(dev.nf_gerou, '') <> 'S'*/
union all
select 1 "Ordem", trim(pv.tipo) "Tipo", trim(pv.tipo) "Tipo2",
case when (trim(pv.tipo) = 'ORC') then '' else 'S' end "Natureza",
ipv.cod_empresa "Cod Empresa", emp.nome_emp "Empresa",
pv.nped "Numero",
pv.data_ped "Data",
pv.data_fech "Data Confirm",
pv.status_ped, ipv.quant_ped_item "Quantidade",
ipv.vlun_ped_item "Valor Unit" , ipv.vltot_ped_item "Valor Total",
case when (trim(pv.tipo) = 'ORC') then 'N'
     when (pv.data_fech is not null) then 'S'
     else 'N' end "Altera Estoque",
'N' "Altera Custo", ipv.pcust_mc "Custo Med", ipv.nitem "N Item",
ipv.grupo_prod "Grupo", ipv.cod_prod "Cod Prod", ipv.num_fab_prod "Num Fab",
case when (ipv.cod_grade > 0) then
  ipv.descr_prod_ped ||' - '||coalesce(gra.descricao,'')
else
  ipv.descr_prod_ped
end "Descricao",
coalesce(gra.cod_grade,0) "Cod Grade", coalesce(gra.descricao,'SEM GRADE') "Grade",
cl.cod_cliente "Cod Cliente", cl.nome_cliente "Cliente/Fornecedor",
case when pv.tipo = 'REQ' then pv.tipv else pv.tipo_os end "Tipo Vnd/OS", '' "Tipo Venda",
0 "Num Venda",
coalesce(ipv.cod_nf, 0) "Cod NF", ipv.codigo_nop "Cod CFOP", nat.descricao_nop "CFOP",
0 "Aliq ICM", 0 "Base ICM", 0 "Valor ICM",
0 "Aliq ST", 0 "Base ST", 0 "Valor ST",
0 "Aliq IPI", 0 "Base IPI", 0 "Valor IPI",
case when (pv.tipo = 'ORC') then pv.data_ped
     when (pv.data_fech is null) then pv.data_ped
     else pv.data_estoque end "Data Estoque",
pv.nped "Seq Id"
from pedvenda pv
inner join pedvenda_prod ipv on ipv.tipo = pv.tipo and ipv.nped = pv.nped and ipv.cod_empresa = pv.cod_empresa
inner join produtos pr on pr.cod_prod = ipv.cod_prod and pr.grupo_prod = ipv.grupo_prod and pr.cod_empresa = ipv.cod_empresa
inner join clientes cl on cl.cod_cliente = pv.cod_cliente and cl.cod_empresa = pv.cod_empresa
inner join empresa emp on emp.cod_empresa = pv.cod_empresa
left join grade gra on gra.cod_grade = ipv.cod_grade and gra.cod_empresa = ipv.cod_empresa
left join nat_op nat on nat.codigo_nop = ipv.codigo_nop
left join tipo_vendas tp on tp.tipo = pv.tipo
and ((trim(tp.tipo) = 'OS' and tp.tipo_os = pv.tipo_os)
  or (trim(tp.tipo) = 'ORC' and tp.sigla = pv.tipo_orc)
  or (tp.sigla = pv.tipv))
where /* pv.status_ped = 'FECHADA' and pv.tipo <> 'ORC'
and */
coalesce(pv.status_ped, '') <> 'CANCELADO'
and ((ipv.status is null) or (ipv.status <> 'CANCELADO')) and pv.ativo = 1
union all
select 2 "Ordem", 'PDC' "Tipo", 'PDC' "Tipo2", 'S' "Natureza", pi.cod_empresa "Cod Empresa", emp.nome_emp "Empresa",
pd.cod_producao "Num Producao", pd.data "Data", pd.data_fechamento "Data Confirm",
pd.status   ,
(coalesce(pi.quantidade_utilizada,0) + coalesce(pi.quantidade_perda,0)) "Quantidade",
pi.prec_cusm_prod "Custo Unit",
((coalesce(pi.quantidade_utilizada,0) + coalesce(pi.quantidade_perda,0)) * pi.prec_cusm_prod) "Custo Total",
case when (trim(pd.status) = 'FECHADO') then 'S'
     else 'N' end "Altera Estoque",
'N' "Altera Custo", pi.prec_cusm_prod "Custo Med", pi.nitem "N Item",
pi.grupo_prod "Grupo", pi.cod_prod "Cod Prod", pi.num_fab_prod "Num Fab.",
pi.descr_prod "Descricao", gra.cod_grade "Cod. Grade", gra.descricao "Descricao Grade",
0 "Cod Cliente", emp.nome_emp "Cliente/Fornecedor",
'' "Tipo", '' "Tipo Venda", 0 "Num Venda",
0 "Cod NF", 0 "Cod CFOP", '' "CFOP",
0 "Aliq ICM", 0 "Base ICM", 0 "Valor ICM",
0 "Aliq ST", 0 "Base ST", 0 "Valor ST",
0 "Aliq IPI", 0 "Base IPI", 0 "Valor IPI",
case when (pd.data_fechamento is not null) then pd.data_estoque
     else pd.data end "Data Estoque", pd.cod_producao "Seq Id"
from producao pd
inner join producao_item_indice pi on pi.cod_producao = pd.cod_producao and pi.cod_empresa = pd.cod_empresa
inner join empresa emp on emp.cod_empresa = pd.cod_empresa
left join grade gra on gra.cod_grade = pi.cod_grade and gra.cod_empresa = pi.cod_empresa
/*where pd.status = 'FECHADO'*/
union all
select case when trim(h.tipor) = 'NF' then 1 when trim(h.tipor) = 'DEV' then 3 when trim(h.tipor) = 'COR' then 4 else 2 end "Ordem",
case when trim(h.tipor) = 'COR' then trim(h.tipor) else trim(h.tipor)||'X' end "Tipo",
case when ((trim(h.tipor) = 'NF') and (h.natureza = 'E')) then
       'NFEX'
     when (trim(h.tipor) = 'NF') then
       'NFSX'
     when trim(h.tipor) = 'COR' then trim(h.tipor) else trim(h.tipor)||'X' end "Tipo2",
h.natureza, h.cod_empresa, emp.nome_emp EMPRESA,
case when (h.numero > 0) then h.numero
     else 0 end "Num NF",
h.data "Data", h.data "Data Confirm", 'FECHADA',
coalesce(h.qtde, 0) "Quantidade", coalesce(h.valor_unit, 0) "Valor Unit", coalesce(h.valor_tot, 0) "Valor Total",
'S' "Altera Estoque",
case when trim(h.tipor) = 'NF' then coalesce(h.alterou_custo, 'S') else coalesce(h.alterou_custo, 'N') end "Altera Custo",
h.custo_med "Custo Med", h.nitem "N Item",
h.grupo_prod "Grupo", h.cod_prod "Cod Prod", pr.num_fab_prod "Num Fab.",
rtrim(pr.descr_prod) || case when coalesce(gra.cod_grade, 0) = 0 then '' else ' - ' || gra.descricao end "Descricao", coalesce(h.cod_grade, 0) "Cod. Grade", coalesce(gra.descricao, 'SEM GRADE') "Descricao Grade",
h.cod_cliente "Cod Cliente", cl.nome_cliente "Cliente/Fornecedor",
'' "Tipo", '' "Tipo Venda", 0 "Num Venda",
coalesce(h.cod_nf , 0)"Cod NF", h.cod_cfop "Cod CFOP", nat.descricao_nop "CFOP",
coalesce(h.aliq_icm, 0) "Aliq ICM", coalesce(h.base_icm, 0) "Base ICM", coalesce(h.valor_icm, 0) "Valor ICM",
coalesce(h.aliq_st, 0) "Aliq ST", coalesce(h.base_st, 0) "Base ST", coalesce(h.valor_st, 0) "Valor ST",
coalesce(h.aliq_ipi, 0) "Aliq IPI", coalesce(h.base_ipi, 0) "Base IPI", coalesce(h.valor_ipi, 0) "Valor IPI", h.data "Data Estoque", h.seqid "Seq Id"
from hist_estoque_diario h
inner join produtos pr on pr.grupo_prod = h.grupo_prod and pr.cod_prod = h.cod_prod and pr.cod_empresa = h.cod_empresa
left join grupos gr on gr.codigo_grup = pr.grupo_prod
left join grade gra on gra.cod_grade = h.cod_grade and gra.cod_empresa = h.cod_empresa
left join cod_grade_prod gp on gp.cod_grade = gra.cod_grade and gp.grupo_prod = pr.grupo_prod and gp.cod_prod = pr.cod_prod and gp.cod_empresa = pr.cod_empresa
left join clientes cl on cl.cod_cliente = h.cod_cliente and cl.cod_empresa = h.cod_empresa
inner join empresa emp on emp.cod_empresa = pr.cod_empresa
left join nat_op nat on nat.codigo_nop = h.cod_cfop
union all
select case when trim(h.tipor) = 'NF' then 1 when trim(h.tipor) = 'DEV' then 3 when trim(h.tipor) = 'COR' then 4 else 2 end "Ordem",
case when trim(h.tipor) = 'COR' then trim(h.tipor) else trim(h.tipor)||'X' end "Tipo",
case when ((trim(h.tipor) = 'NF') and (h.natureza = 'E')) then
       'NFEX'
     when (trim(h.tipor) = 'NF') then
       'NFSX'
     when trim(h.tipor) = 'COR' then trim(h.tipor) else trim(h.tipor)||'X' end "Tipo2",
h.natureza, h.cod_empresa, emp.nome_emp EMPRESA,
case when (h.numero > 0) then h.numero
     else 0 end "Num NF",
h.data "Data", h.data "Data Confirm", 'FECHADA',
coalesce(h.qtde, 0) "Quantidade", coalesce(h.valor_unit, 0) "Valor Unit", coalesce(h.valor_tot, 0) "Valor Total",
'S' "Altera Estoque",
case when trim(h.tipor) = 'NF' then coalesce(h.alterou_custo, 'S') else coalesce(h.alterou_custo, 'N') end "Altera Custo",
h.custo_med "Custo Med", h.nitem "N Item",
h.grupo_prod "Grupo", h.cod_prod "Cod Prod", pr.num_fab_prod "Num Fab.",
rtrim(pr.descr_prod) || case when coalesce(gra.cod_grade, 0) = 0 then '' else ' - ' || gra.descricao end "Descricao", coalesce(h.cod_grade, 0) "Cod. Grade", coalesce(gra.descricao, 'SEM GRADE') "Descricao Grade",
h.cod_cliente "Cod Cliente", cl.nome_cliente "Cliente/Fornecedor",
'' "Tipo", '' "Tipo Venda", 0 "Num Venda",
coalesce(h.cod_nf , 0)"Cod NF", h.cod_cfop "Cod CFOP", nat.descricao_nop "CFOP",
coalesce(h.aliq_icm, 0) "Aliq ICM", coalesce(h.base_icm, 0) "Base ICM", coalesce(h.valor_icm, 0) "Valor ICM",
coalesce(h.aliq_st, 0) "Aliq ST", coalesce(h.base_st, 0) "Base ST", coalesce(h.valor_st, 0) "Valor ST",
coalesce(h.aliq_ipi, 0) "Aliq IPI", coalesce(h.base_ipi, 0) "Base IPI", coalesce(h.valor_ipi, 0) "Valor IPI", h.data "Data Estoque", h.seqid "Seq Id"
from hist_estoque_diario_prod h
inner join produtos pr on pr.grupo_prod = h.grupo_prod and pr.cod_prod = h.cod_prod and pr.cod_empresa = h.cod_empresa
left join grupos gr on gr.codigo_grup = pr.grupo_prod
left join grade gra on gra.cod_grade = h.cod_grade and gra.cod_empresa = h.cod_empresa
left join cod_grade_prod gp on gp.cod_grade = gra.cod_grade and gp.grupo_prod = pr.grupo_prod and gp.cod_prod = pr.cod_prod and gp.cod_empresa = pr.cod_empresa
left join clientes cl on cl.cod_cliente = h.cod_cliente and cl.cod_empresa = h.cod_empresa
inner join empresa emp on emp.cod_empresa = pr.cod_empresa
left join nat_op nat on nat.codigo_nop = h.cod_cfop
where coalesce(h.baixou_est, '') <> 'S'
union all
select 5 "Ordem", 'CP' "Tipo",  'CP' "Tipo2", 'S' "Natureza",
cp.cod_empresa "Cod Empresa", emp.nome_emp "Empresa", cp.cupom "Numero",
cp.data "Data", cp.data "Data Confirm",
case when (trim(cp.status_cp) = '') then 'FECHADO' else upper(trim(cp.status_cp)) end,
cp2.quantidade "Quantidade",
cp2.preco "Valor Unit", cp2.total "Valor Total",
'N' "Altera Estoque", 'N' "Altera Custo", cp2.prec_cusm_prod "Custo Med",
cp2.nitem "N Item", cp2.grupo_prod "Grupo", cp2.cod_prod "Cod Prod", cp2.codbarra "Num Fab",
case when (cp2.cod_grade > 0) then
  cp2.descr_it || ' - '||coalesce(gra.descricao, '')
else
  cp2.descr_it
end "Descricao",
coalesce(gra.cod_grade, 0) "Cod Grade", coalesce(gra.descricao, 'SEM GRADE') "Grade",
cp.cliente "Cod Cliente", cl.nome_cliente "Cliente/Fornecedor",
coalesce(pd.tipv, '') "Tipo Vnd/OS", '' "Tipo Venda", coalesce(pd.nped, 0) "Num Venda",
0 "Cod NF", cp2.codigo_nop "Cod CFOP", nat.descricao_nop "CFOP",
0 "Aliq ICM", 0 "Base ICM", 0 "Valor ICM",
0 "Aliq ST", 0 "Base ST", 0 "Valor ST",
0 "Aliq IPI", 0 "Base IPI", 0 "Valor IPI",
cp.data "Data Estoque", cp.registro "Seq Id"
from cupom cp
inner join cupom2 cp2 on cp2.cod_terminal = cp.cod_terminal and cp2.cod_empresa = cp.cod_empresa
  and cp2.nserieecf = cp.nserieecf and cp2.ordem = cp.registro
inner join empresa emp on emp.cod_empresa = cp.cod_empresa
left join grade gra on cp2.cod_grade = gra.cod_grade and cp2.cod_empresa = gra.cod_empresa
inner join produtos pr on cp2.grupo_prod = pr.grupo_prod and cp2.cod_prod = pr.cod_prod and cp2.cod_empresa = pr.cod_empresa
inner join clientes cl on cp.cliente = cl.cod_cliente and cp.cod_empresa = cl.cod_empresa
left join nat_op nat on nat.codigo_nop = cp2.codigo_nop
left join pedvenda pd on pd.nped = cp.ped and coalesce(pd.nprevenda, 0) = coalesce(cp.prevenda, 0)
  and  coalesce(pd.paf_num_prevenda, 0) = coalesce(cp.paf_num_prevenda, 0) and pd.cod_empresa = cp.cod_empresa
where ((cp2.status_it is null) or (cp2.status_it <> 'CANCELADO'))
union all
select 6 "Ordem", 'NFD' "Tipo", 'NFD' "Tipo2", 'S' "Natureza",
nd.cod_empresa "Cod Empresa", emp.nome_emp "Empresa", nd.numeronota "Numero",
nd.dataemissao "Data", nd.dataemissao "Data Confirm",
upper(trim(nd.status)), ndi.quantid_item "Quantidade",
ndi.vl_un_item "Valor Unit", ndi.vl_tot_item "Valor Total",
'N' "Altera Estoque", 'N' "Altera Custo", ndi.prec_cusm_prod "Custo Med",
ndi.nitem "N Item", ndi.grupo_prod "Grupo", ndi.cod_prod "Cod Prod", ndi.num_fab_prod "Num Fab",
ndi.desc_prod "Descricao", nd.cod_cliente "Cod Cliente", cl.nome_cliente "Cliente/Fornecedor",
0 "Cod Grade", 'SEM GRADE' "Grade",
'' "Tipo Vnd/OS", '' "Tipo Venda", nd.nped "Num Venda",
0 "Cod NF", 0 "Cod CFOP", '' CFOP, 0 "Aliq", ndi.base_icm "Base ICM", ndi.valor_icm "Valor ICM",
0 "Aliq ST", 0 "Base ST", 0 "Valor ST",
0 "Aliq IPI", 0 "Base IPI", 0 "Valor IPI",
nd.dataemissao "Data Estoque", nd.numeronota "Seq Id"
from nf_serie_d_itens ndi
inner join nf_serie_d nd on nd.numeronota = ndi.numeronota and nd.cod_empresa = ndi.cod_empresa
inner join empresa emp on emp.cod_empresa = ndi.cod_empresa
left join clientes cl on cl.cod_cliente = nd.cod_cliente and cl.cod_empresa = nd.cod_empresa
left join estados est on est.codigo_uf = cl.codigo_uf
inner join produtos p on p.grupo_prod = ndi.grupo_prod and p.cod_prod = ndi.cod_prod and p.cod_empresa = ndi.cod_empresa
left join nat_op nt on nt.codigo_nop = p.codigo_nop
left join nbm on nbm.cod_ncm = p.nbm
where ((nd.status <> 'CANCELADA') or (nd.status is null))
union all
select 5 "Ordem", 'NFC' Tipo, 'NFC' "Tipo2", 'S' "Natureza",
nfc.cod_empresa "Cod Empresa", emp.nome_emp "Empresa", coalesce(nfc.num_nf, 0) "Numero",
nfc.data_lanc "Data",
nfc.data_lanc "Data Confirm",
upper(trim(nfc.status)) status,
nfci.qcom "Quantidade", nfci.vuncom "Valor Unit", nfci.vprod "Valor Total",
'N' "Altera Estoque", 'N' "Altera Custo", nfci.prec_cusm_prod "Custo Med",
nfci.nitem "N Item", nfci.grupo_prod "Grupo", nfci.cod_prod "Cod Prod", nfci.num_fab_prod "Num Fab",
case when (nfci.cod_grade > 0) then
  nfci.xprod ||' - '|| coalesce(gra.descricao, '')
else
  nfci.xprod
end "Descricao",
coalesce(gra.cod_grade, 0) "Cod Grade", coalesce(gra.descricao, 'SEM GRADE') "Grade",
nfc.cod_cliente "Cod Cliente", cl.nome_cliente "Cliente/Fornecedor",
'' "Tipo Vnd/OS", '' "Tipo Venda",
case when (coalesce(nfc.ped_origem_num,0) > 0) then
      coalesce(nfc.ped_origem_num, 0)
     else
       coalesce(nfc.ped_destino_num, 0)
end "Num Venda",
coalesce(nfc.cod_nfce, 0) "Cod NF", nfci.cfop "Cod CFOP", nat.descricao_nop "CFOP",
0 "Aliq ICM", 0 "Base ICM", 0 "Valor ICM",
0 "Aliq ST", 0 "Base ST", 0 "Valor ST",
0 "Aliq IPI", 0 "Base IPI", 0 "Valor IPI",
nfc.data_lanc "Data Estoque", nfc.cod_nfce "Seq Id"
from nfce nfc
inner join nfce_item nfci on nfci.cod_nfce = nfc.cod_nfce and nfci.cod_empresa = nfc.cod_empresa
inner join empresa emp on emp.cod_empresa = nfc.cod_empresa
left join nat_op nat on nat.codigo_nop = nfci.cfop
left join grade gra on nfci.cod_grade = gra.cod_grade and nfci.cod_empresa = gra.cod_empresa
inner join produtos pr on nfci.grupo_prod = pr.grupo_prod and nfci.cod_prod = pr.cod_prod and nfci.cod_empresa = pr.cod_empresa
left join clientes cl on nfc.cod_cliente = cl.cod_cliente and nfci.cod_empresa = cl.cod_empresa
where ((upper(trim(nfc.status)) <> 'CANCELADA') or (nfc.status is null))
;

/* View: VENDAS_VAN, Owner: SYSDBA */
CREATE VIEW VENDAS_VAN (NPED, TIPO, COD_EMPRESA, VALOR_TOTAL, GRUPO_PROD, COD_PROD, NUM_FAB_PROD, NITEM, COD_GRADE, QUANT_PED_ITEM, DESCR_PROD_PED, DESCR_PROD_PED2, STATUS, DATA_PED, DATA_FECH, STATUS_PED, VLUN_PED_ITEM, VLTOT_PED_ITEM, TIPV, DESCRICAO_TPV, USAR_CONFERENCIA_PRODUTO, COD_CLIENTE, NOME_CLIENTE, COD_VENDEDOR, NOME_VENDEDOR, NPED_DEST, TIPO_DEST, NITEM_DEST, QUANT_DEST, TIPV_DEST, ORDEM_DEST, DESCRICAO_TPV2, DATA_PED2, DATA_FECH2, STATUS_PED2, COD_CLIENTE2, NOME_CLIENTE2, VLUN_PED_ITEM2, VLTOT_PED_ITEM2, SEQID) AS

select pv.nped, pv.tipo, pv.cod_empresa, pv.valor_total,
pp.grupo_prod, pp.cod_prod, pp.num_fab_prod, pp.nitem, pp.cod_grade, coalesce(pp.quant_ped_item, 0) quant_ped_item,
pp.descr_prod_ped, (pp.descr_prod_ped ||' - '||pp.nitem) descr_prod_ped2, pp.status,
pv.data_ped, pv.data_fech, pv.status_ped, coalesce(pp.vlun_ped_item, 0) vlun_ped_item,
coalesce(pp.vltot_ped_item, 0), pv.tipv, tv.descricao descricao_tpv,
coalesce(tv.usar_conferencia_produto, 'N') usar_conferencia_produto,
pv.cod_cliente, cl.nome_cliente, pv.cod_vendedor, col.nome_vendedor, ppc.nped nped_dest, ppc.tipo tipo_dest,
ppc.nitem nitem_dest, ppc.quant as quant_dest, ppc.tipv tipv_dest, ppc.codigo ordem_dest,
tv2.descricao descricao_tpv2, pv2.data_ped data_ped2, pv2.data_fech data_fech2,
pv2.status_ped status_ped2,  pv2.cod_cliente cod_cliente2, cl2.nome_cliente nome_cliente2,
coalesce(pp2.vlun_ped_item, 0) vlun_ped_item2,
(coalesce(pp2.vlun_ped_item, 0) * coalesce(ppc.quant, 0)) vltot_ped_item2, coalesce(ppc.codigo, 0) seqid from pedvenda pv
inner join pedvenda_prod pp on pp.nped = pv.nped and pp.tipo = pv.tipo and pp.cod_empresa = pv.cod_empresa
inner join tipo_vendas tv on pv.tipo = tv.tipo and (pv.tipv=tv.sigla or (pv.tipo_os= tv.tipo_os))
inner join clientes cl on cl.cod_cliente = pv.cod_cliente and cl.cod_empresa = pv.cod_empresa
inner join colaborador col on col.cod_vendedor = pv.cod_vendedor and col.cod_empresa = pv.cod_empresa
left join pedvenda_prod_conf ppc on ppc.nped_conf = pp.nped and ppc.tipo_conf = pp.tipo
  and ppc.grupo_prod = pp.grupo_prod
  and ppc.cod_prod = pp.cod_prod
  and ppc.cod_grade = pp.cod_grade
  and ((ppc.nitem_conf = pp.nitem) or (ppc.nitem_conf > 0))
  and ppc.cod_empresa = pp.cod_empresa
left join tipo_vendas tv2 on ppc.tipo_conf = tv2.tipo and ppc.tipv = tv2.sigla
left join pedvenda pv2 on pv2.nped = ppc.nped and pv2.tipo = ppc.tipo and pv2.cod_empresa = ppc.cod_empresa
left join pedvenda_prod pp2 on pp2.nped = ppc.nped_conf and pp2.tipo = ppc.tipo_conf and pp2.cod_empresa = ppc.cod_empresa and pp2.nitem = ppc.nitem_conf
left join clientes cl2 on cl2.cod_cliente = pv2.cod_cliente and cl2.cod_empresa = pv2.cod_empresa
;

/* View: KITS_PROD_TOT, Owner: SYSDBA */
CREATE VIEW KITS_PROD_TOT (CODIGO_KIT, COD_EMPRESA, REGRA_PESO_DIM, QUANT_PROD_KIT, PREC_CUS_PROD, PREC_CUSM_PROD, PREC_TAB_PROD, PREC_PUBLICO, PREC_30_PROD, PREC_60_PROD, PREC_90_PROD, PESO_BRUT_PROD, COMPRIMENTO_PROD, LARGURA_PROD, ALTURA_PROD, EST_F, VALOR_TAB_PROKIT, DESCONTO_VALOR, DESCONTO_PERC, VALOR_DESC_TAB_PROKIT) AS

SELECT KITS_PROD_KITS.CODIGO_KIT,
KITS_PROD_KITS.COD_EMPRESA,
COALESCE(KITS_PROD_EC.REGRA_PESO_DIM, '') REGRA_PESO_DIM,
COALESCE(SUM(COALESCE(KITS_PROD_KITS.QUANT_PROD_KIT, 0)), 0) QUANT_PROD_KIT,
COALESCE(SUM(COALESCE(KITS_PROD_KITS.QUANT_PROD_KIT, 0) * COALESCE(PRODUTOS.PREC_CUS_PROD, 0)), 0) PREC_CUS_PROD,
COALESCE(SUM(COALESCE(KITS_PROD_KITS.QUANT_PROD_KIT, 0) * COALESCE(PRODUTOS.PREC_CUSM_PROD, 0)), 0) PREC_CUSM_PROD,
COALESCE(SUM(COALESCE(KITS_PROD_KITS.QUANT_PROD_KIT, 0) * COALESCE(PRODUTOS.PREC_TAB_PROD, 0)), 0) PREC_TAB_PROD,
COALESCE(SUM(COALESCE(KITS_PROD_KITS.QUANT_PROD_KIT, 0) * COALESCE(PRODUTOS.PREC_PUBLICO, 0)), 0) PREC_PUBLICO,
COALESCE(SUM(COALESCE(KITS_PROD_KITS.QUANT_PROD_KIT, 0) * COALESCE(PRODUTOS.PREC_30_PROD, 0)), 0) PREC_30_PROD,
COALESCE(SUM(COALESCE(KITS_PROD_KITS.QUANT_PROD_KIT, 0) * COALESCE(PRODUTOS.PREC_60_PROD, 0)), 0) PREC_60_PROD,
COALESCE(SUM(COALESCE(KITS_PROD_KITS.QUANT_PROD_KIT, 0) * COALESCE(PRODUTOS.PREC_90_PROD, 0)), 0) PREC_90_PROD,
COALESCE(SUM(COALESCE(KITS_PROD_KITS.QUANT_PROD_KIT, 0) * COALESCE(PRODUTOS.PESO_BRUT_PROD, 0)), 0) PESO_BRUT_PROD,
COALESCE(SUM(COALESCE(KITS_PROD_KITS.QUANT_PROD_KIT, 0) * COALESCE(PRODUTOS.COMPRIMENTO_PROD, 0)), 0) COMPRIMENTO_PROD,
COALESCE(SUM(COALESCE(KITS_PROD_KITS.QUANT_PROD_KIT, 0) * COALESCE(PRODUTOS.LARGURA_PROD, 0)), 0) LARGURA_PROD,
COALESCE(SUM(COALESCE(KITS_PROD_KITS.QUANT_PROD_KIT, 0) * COALESCE(PRODUTOS.ALTURA_PROD, 0)), 0) ALTURA_PROD,
COALESCE(SUM(COALESCE(PRODUTOS.EST_F, 0)), 0) EST_F,
(SELECT VALOR_TAB_PROKIT FROM RETORNA_EC_VLTB_PROMKIT(KITS_PROD_KITS.CODIGO_KIT, KITS_PROD_KITS.COD_EMPRESA)) TAB_PRECO_ECOMMERCE,
MAX(COALESCE(KITS_PROD_EC.DESCONTO_VALOR, 0)) DESCONTO_VALOR,
MAX(COALESCE(KITS_PROD_EC.DESCONTO_PERC, 0)) DESCONTO_PERC,
((SELECT VALOR_TAB_PROKIT FROM RETORNA_EC_VLTB_PROMKIT(KITS_PROD_KITS.CODIGO_KIT, KITS_PROD_KITS.COD_EMPRESA)) - SUM(COALESCE(KITS_PROD_KITS.RATEIO_DESC, 0)))  TAB_PRECO_DESC_ECOMMERCE

 FROM KITS_PROD_KITS
LEFT JOIN PRODUTOS ON PRODUTOS.GRUPO_PROD = KITS_PROD_KITS.GRUPO_PROD AND PRODUTOS.COD_PROD = KITS_PROD_KITS.COD_PROD
    AND PRODUTOS.COD_EMPRESA = KITS_PROD_KITS.COD_EMPRESA
LEFT JOIN KITS_PROD_EC ON KITS_PROD_EC.CODIGO_KIT = KITS_PROD_KITS.CODIGO_KIT
    AND KITS_PROD_EC.COD_EMPRESA = KITS_PROD_KITS.COD_EMPRESA
--WHERE KITS_PROD_KITS.CODIGO_KIT = :CODIGO_KIT AND KITS_PROD_KITS.COD_EMPRESA = 1
GROUP BY 1, 2, 3
;

/* View: VW_MDFE_DESCARGA_NFE, Owner: SYSDBA */
CREATE VIEW VW_MDFE_DESCARGA_NFE (COD_MDFE, COD_EMPRESA, CMUNDESCARGA, COD_NF, CHNFE, SEGCODBARRA, PESO_BRUTO_NF, VALOR_TOTAL_NF, INDREENTREGA, ID) AS

select e.cod_mdfe, e.cod_empresa, e.cmundescarga, e.cod_nf, e.chnfe, e.segcodbarra, e.peso_bruto_nf, e.valor_total_nf, e.indreentrega, null id from mdfe_descarga_nfe e
union
select a.cod_mdfe, a.cod_empresa, a.cmundescarga, null cod_nf, a.chnfe, a.segcodbarra, a.peso_bruto_nf, a.valor_total_nf, a.indreentrega, a.id from mdfe_descarga_nfea a
;

/* View: VW_MDFE_DESCARGA_NFE_UN_TR, Owner: SYSDBA */
CREATE VIEW VW_MDFE_DESCARGA_NFE_UN_TR (COD_MDFE, COD_EMPRESA, CMUNDESCARGA, COD_NF, SEQID, TPUNIDTRANSP, IDUNIDTRANSP, LACUNIDTRANSP_LACRES, QTDRAT, ID, DESCARGA_ID) AS

select u.cod_mdfe, u.cod_empresa, u.cmundescarga, u.cod_nf, u.seqid, u.tpunidtransp,  u.idunidtransp,  u.lacunidtransp_lacres, u.qtdrat, null id, null descarga_id from mdfe_descarga_nfe_un_tr u
union
select a.cod_mdfe, ua.cod_empresa, a.cmundescarga, null cod_nf, null seqid, ua.tpunidtransp,  ua.idunidtransp,  ua.lacunidtransp_lacres, ua.qtdrat, ua.id, ua.descarga_id from mdfe_descarga_nfea_un_tr ua
inner join mdfe_descarga_nfea a on a.id = ua.descarga_id and a.cod_empresa = ua.cod_empresa
;

/* View: VW_MDFE_DESCARGA_NFE_UN_TR_CRG, Owner: SYSDBA */
CREATE VIEW VW_MDFE_DESCARGA_NFE_UN_TR_CRG (COD_MDFE, COD_EMPRESA, CMUNDESCARGA, COD_NF, SEQID, SEQID_CARGA, TPUNIDCARGA, IDUNIDCARGA, LACUNIDCARGA_LACRES, QTDRAT, ID, UNTR_ID) AS

select c.cod_mdfe, c.cod_empresa, c.cmundescarga, c.cod_nf, c.seqid, c.seqid_carga, c.tpunidcarga, c.idunidcarga, c.lacunidcarga_lacres, c.qtdrat, null id, null untr_id from mdfe_descarga_nfe_un_tr_carga c
union
select a.cod_mdfe, ca.cod_empresa, a.cmundescarga, null cod_nf, null seqid, null seqid_carga, ca.tpunidcarga, ca.idunidcarga, ca.lacunidcarga_lacres, ca.qtdrat, ca.id, ca.untr_id from mdfe_descarga_nfea_un_tr_carga ca
inner join mdfe_descarga_nfea_un_tr ua on ua.id = ca.untr_id and ua.cod_empresa = ca.cod_empresa
inner join mdfe_descarga_nfea a on a.id = ua.descarga_id and a.cod_empresa = ua.cod_empresa
;

/* View: PROD_SERV_EMVENDAS_FAIXA_DESC, Owner: SYSDBA */
CREATE VIEW PROD_SERV_EMVENDAS_FAIXA_DESC (COD_EMPRESA, DATA_FECH, NPED, TIPO, NITEM, PROD_SERV, GRUPOP_CODSERV, COD_PROD, QUANT_PED_ITEM, VLUN_ORIG, VLUN_PED_ITEM, VLTOT_PED_ITEM, VLTOTLIQ_PED_ITEM, RATEIO_DESC, RATEIO_ACRESC, PCUST_MC, DESCR_ITEM_PED, PERC_DESC_ITEM, COD_REGRA_FAIXADESC, DESCR_REGRA_FAIXADESC, TIPO_REGRA_FAIXADESC, PERC_DESC_REGRA_FAIXADESC, COMISS_PROD, COMISS_PROD_GER, PERC_DESC, PERC_COMISS, N_NF, DESCRICAO, SIGLA, TIPO_OS, NOME_VENDEDOR, COD_VENDEDOR, COL_COD_VENDEDOR, PC_VEND_SERV, PC_VEND_PROD, COD_FUNCAO, DESC_FUNCAO, VENDA) AS

select v.cod_empresa,  v.data_fech, pp.nped,pp.tipo,pp.nitem,'P' as prod_serv,
pp.grupo_prod,pp.cod_prod,
coalesce(pp.quant_ped_item,0) as quant_ped_item,
coalesce(pp.vlun_orig, 0) vlun_orig,
coalesce(pp.vlun_ped_item,0) as vlun_ped_item,
coalesce(pp.vltot_ped_item,0) as vltot_ped_item,
(coalesce(pp.vltot_ped_item, 0) - coalesce(pp.rateio_desc, 0) + coalesce(pp.rateio_acresc, 0)) vltotliq_ped_item,
coalesce(pp.rateio_desc,0) as rateio_desc,
coalesce(pp.rateio_acresc,0) as rateio_acresc,
coalesce(pp.pcust_mc,0) as pcust_mc,
pp.descr_prod_ped,
round((pp.rateio_desc / pp.vltot_ped_item) * 100, 2) perc_desc_item,
comissao.icodigo_regra,
comissao.idescricao_regra,
comissao.itipo_regra,
comissao.ipercentual_regra,
comissao.ivalor_comissao as comiss_prod,
0 as comiss_prod_ger,
comissao.ipercentual_desc as perc_desc,
comissao.ipercentual_regra as perc_comiss,
coalesce(pp.n_nf,0) as n_nf,
tv.descricao,tv.sigla,tv.tipo_os,c.nome_vendedor,c.cod_vendedor,
pp.col_cod_vendedor,c.pc_vend_serv, c.PC_VEND_PROD,f.cod_funcao,f.desc_funcao,tv.venda
from  tipo_vendas tv
inner join pedvenda v on v.tipo=tv.tipo and (v.tipv=tv.sigla or (v.tipo_os=tv.tipo_os))
inner join pedvenda_prod pp on v.tipo=pp.tipo and v.nped=pp.nped and v.cod_empresa=pp.cod_empresa
inner join produtos pr on pr.grupo_prod = pp.grupo_prod and pr.cod_prod = pp.cod_prod and pr.cod_empresa = pp.cod_empresa
inner join grupos g on pp.grupo_prod=g.codigo_grup
inner join colaborador c on pp.cod_vendedor=c.cod_vendedor and pp.cod_empresa=c.cod_empresa
inner join funcoes f on c.cod_funcao=f.cod_funcao
left join retorna_comissao_faixadesc(
    pr.cod_comissao_faixa_desc,
    pr.cod_empresa,
    round(case when (coalesce(pp.vlun_orig, 0) * coalesce(pp.quant_ped_item, 0) > (coalesce(pp.vltot_ped_item, 0) - coalesce(pp.rateio_desc, 0) + coalesce(pp.rateio_acresc, 0))) then
                   abs(1 - (((coalesce(pp.vltot_ped_item, 0) - coalesce(pp.rateio_desc, 0) + coalesce(pp.rateio_acresc, 0))) / (coalesce(pp.vlun_orig, 0) * coalesce(pp.quant_ped_item, 0)))) * 100
               else
                     0
          end,
    2),
    coalesce(pp.vltot_ped_item, 0) - coalesce(pp.rateio_desc, 0) + coalesce(pp.rateio_acresc, 0)) comissao on 1 = 1
where v.status_ped='FECHADA' and v.ativo=1 and (pp.status<>'CANCELADO' or (pp.status is null))
;

/* View: DEVOLUCAO_TOT, Owner: SYSDBA */
CREATE VIEW DEVOLUCAO_TOT (TIPO, TIPO_DEV, NDEV, DATA, COD_CLIENTE, COD_EMPRESA, COD_VENDEDOR, VALOR_DEV, QUANT_DEV) AS

  select 'DEV' as tipo,
  dev.tipo tipo_dev,
  dev.sequencia,
  dev.data,
  dev.cod_cliente,
  dev.cod_empresa,
  (select first 1 devolucao.cod_vendedor from devolucao where devolucao.sequencia = dev.sequencia and devolucao.cod_empresa = dev.cod_empresa) cod_vendedor,
  sum((-1) * case when (coalesce(dev.valor_tot, 0) > 0) then coalesce(dev.valor_tot, 0) else coalesce((dev.valor * dev.quant), 0) end) valor_dev,
  count(distinct(dev.sequencia)) quant_dev from devolucao dev
  group by 1, 2, 3, 4, 5, 6
;

/* View: VW_FLUXO_CAIXA, Owner: SYSDBA */
CREATE VIEW VW_FLUXO_CAIXA (TIPO_DOC, DATA_VENC, DATA_VENC_ATU, HISTORICO, VALOR_RECEBER, VALOR_PAGAR, COD_EMPRESA, CODIGO_CTRL, N_DOC, NOME_CTRL, NOME_CLIFOR, DATA_EXTENSO) AS

----------------------------------CREDITOS-------------------------------------
select 'CTR',
cr.data_venc_c,
(select po_data from sp_proximo_diautil(((select po_data from sp_proximo_diautil(cr.data_venc_c)) + (coalesce(ctr.dias_ent_fluxo, 0))))),
cr.historico_c,
cr.valor_c,
0.00,
cr.codigo_emp,
cr.codigo_ctrl,
cr.n_doc_c,
ctr.nome_ctrl,
cr.nome_c,


(select EXTRACT(DAY FROM ((select po_data from sp_proximo_diautil(((select po_data from sp_proximo_diautil(cr.data_venc_c)) + (coalesce(ctr.dias_ent_fluxo, 0))))))) ||' '||
trim(CASE EXTRACT(MONTH FROM (((select po_data from sp_proximo_diautil(((select po_data from sp_proximo_diautil(cr.data_venc_c)) + (coalesce(ctr.dias_ent_fluxo, 0))))))))
        WHEN 1 THEN ' DE JANEIRO DE '
        WHEN 2 THEN ' DE FEVEREIRO DE '
        WHEN 3 THEN ' DE MARCO DE '
        WHEN 4 THEN ' DE ABRIL DE '
        WHEN 5 THEN ' DE MAIO DE '
        WHEN 6 THEN ' DE JUNHO DE '
        WHEN 7 THEN ' DE JULHO DE '
        WHEN 8 THEN ' DE AGOSTO DE '
        WHEN 9 THEN ' DE SETEMBRO DE '
        WHEN 10 THEN ' DE OUTRUBRO DE '
        WHEN 11 THEN ' DE NOVEMBRO DE '
        WHEN 12 THEN ' DE DEZEMBRO DE '
      END) || ' '|| trim(EXTRACT(YEAR FROM (((select po_data from sp_proximo_diautil(((select po_data from sp_proximo_diautil(cr.data_venc_c)) + (coalesce(ctr.dias_ent_fluxo, 0)))))))))FROM RDB$DATABASE)

from controle_creditos cr
inner join controles ctr on cr.codigo_ctrl = ctr.codigo_ctrl and cr.codigo_emp = ctr.codigo_emp
where  (cr.datq_c is null)
-----------------------------------CHEQUES--------------------------------------
union
select 'CHQ',
ch.data_venc,
(select po_data from sp_proximo_diautil(((select po_data from sp_proximo_diautil(ch.data_venc))))),--data_venc,
ch.historico_ch,
ch.valor_ch,
0.00,
ch.codigo_emp,
ch.codigo_ctrl,
ch.n_ch,
ctr2.nome_ctrl,
ch.nome_ch,

(select EXTRACT(DAY FROM ((select po_data from sp_proximo_diautil(((select po_data from sp_proximo_diautil(ch.data_venc))))))) ||' '||
trim(CASE EXTRACT(MONTH FROM (((select po_data from sp_proximo_diautil(((select po_data from sp_proximo_diautil(ch.data_venc))))))))
        WHEN 1 THEN ' DE JANEIRO DE '
        WHEN 2 THEN ' DE FEVEREIRO DE '
        WHEN 3 THEN ' DE MARCO DE '
        WHEN 4 THEN ' DE ABRIL DE '
        WHEN 5 THEN ' DE MAIO DE '
        WHEN 6 THEN ' DE JUNHO DE '
        WHEN 7 THEN ' DE JULHO DE '
        WHEN 8 THEN ' DE AGOSTO DE '
        WHEN 9 THEN ' DE SETEMBRO DE '
        WHEN 10 THEN ' DE OUTRUBRO DE '
        WHEN 11 THEN ' DE NOVEMBRO DE '
        WHEN 12 THEN ' DE DEZEMBRO DE '
      END) || ' '|| trim(EXTRACT(YEAR FROM (((select po_data from sp_proximo_diautil(((select po_data from sp_proximo_diautil(ch.data_venc)))))))))FROM RDB$DATABASE)

from controle_cheque ch
inner join controles ctr2 on ch.codigo_ctrl = ctr2.codigo_ctrl and ch.codigo_ctrl = ctr2.codigo_emp
where (ch.datq_ch is null)

-----------------------------------------CONTAS A PAGAR-------------------------------------
union
select 'CTP',
pg.data_venc_ctp,
(select po_data from sp_proximo_diautil(((select po_data from sp_proximo_diautil(pg.data_venc_ctp))))),--pg.data_venc_ctp,
pg.historico_ctp,
0.00,
case when (coalesce(pg.valor_pago, 0) > 0) then coalesce(pg.valor_pago, 0) else coalesce(pg.valor_ctp, 0) end,
pg.codigo_emp,
pg.codigo_ctrl,
pg.n_doc_ctp,
ctr3.nome_ctrl,
pg.nome_for_ctp,


(select EXTRACT(DAY FROM ((select po_data from sp_proximo_diautil(((select po_data from sp_proximo_diautil(pg.data_venc_ctp))))))) ||' '||
trim(CASE EXTRACT(MONTH FROM (((select po_data from sp_proximo_diautil(((select po_data from sp_proximo_diautil(pg.data_venc_ctp))))))))
        WHEN 1 THEN ' DE JANEIRO DE '
        WHEN 2 THEN ' DE FEVEREIRO DE '
        WHEN 3 THEN ' DE MARCO DE '
        WHEN 4 THEN ' DE ABRIL DE '
        WHEN 5 THEN ' DE MAIO DE '
        WHEN 6 THEN ' DE JUNHO DE '
        WHEN 7 THEN ' DE JULHO DE '
        WHEN 8 THEN ' DE AGOSTO DE '
        WHEN 9 THEN ' DE SETEMBRO DE '
        WHEN 10 THEN ' DE OUTRUBRO DE '
        WHEN 11 THEN ' DE NOVEMBRO DE '
        WHEN 12 THEN ' DE DEZEMBRO DE '
      END) || ' '|| trim(EXTRACT(YEAR FROM (((select po_data from sp_proximo_diautil(((select po_data from sp_proximo_diautil(pg.data_venc_ctp)))))))))FROM RDB$DATABASE)

from contas_a_pagar pg
inner join controles ctr3 on pg.codigo_ctrl = ctr3.codigo_ctrl and pg.codigo_emp = ctr3.codigo_emp
where (pg.datq_ctp is null)
;

/* View: PEDVENDA_PROD_FATOR, Owner: SYSDBA */
CREATE VIEW PEDVENDA_PROD_FATOR (NPED, TIPO, GRUPO_PROD, COD_PROD, NITEM, COD_EMPRESA, COD_GRADE, CODIGO_NOP, QCOM, VUNCOM, VPROD, UCOM, UVND, VPRODNF, UVND_FATOR, PARIDADE, QVND, VVND, VVNDNF) AS

select D.NPED, D.TIPO, D.GRUPO_PROD, D.COD_PROD, D.NITEM, D.COD_EMPRESA, D.COD_GRADE, D.CODIGO_NOP, D.QCOM, D.VUNCOM,
       D.VPROD, D.UCOM, D.UVND, D.VPRODNF, D.UVND_FATOR, D.PARIDADE, D.QVND,
       (D.VPROD / D.QVND) VVND,
       (D.VPRODNF / D.QVND) VVNDNF
from (select C.NPED, C.TIPO, C.GRUPO_PROD, C.COD_PROD, C.NITEM, C.COD_EMPRESA, C.COD_GRADE, C.CODIGO_NOP, C.QCOM,
             C.VUNCOM, C.VPROD, C.UCOM, C.UVND, C.VPRODNF, C.UVND_FATOR,
             case
               when C.UVND_FATOR > 1 then (select RESULTADO
                                           from FLOATTOSTR(C.UVND_FATOR, 4)) || ' ' || C.UVND || ' = 1 ' || C.UCOM
               when C.UVND_FATOR > 0 then '1 ' || C.UVND || ' = ' ||(select RESULTADO
                                                                    from FLOATTOSTR(1 / C.UVND_FATOR, 4)) || ' ' || C.UCOM
               else '1 ' || C.UVND || ' = 1 ' || C.UCOM
             end PARIDADE,
             (C.QCOM * C.UVND_FATOR) QVND
      from (select PP.NPED, PP.TIPO, PP.GRUPO_PROD, PP.COD_PROD, PP.NITEM, PP.COD_EMPRESA, PP.COD_GRADE, PP.CODIGO_NOP,
                   PP.QUANT_PED_ITEM QCOM, PP.VLUN_PED_ITEM VUNCOM, PP.VLTOT_PED_ITEM VPROD, PP.UNIDADE UCOM,
                   coalesce(PP.UNIDADE_CONV, PP.UNIDADE) UVND, PP.VLTOT_PED_NF VPRODNF,
                   case
                     when PP.OPERACAO_CONV = 'D' then 1 / PP.FATOR_CONV
                     when PP.OPERACAO_CONV = 'M' then 1 * PP.FATOR_CONV
                     else 1
                   end UVND_FATOR
            from PEDVENDA_PROD PP
            order by PP.NPED desc, PP.NITEM desc) as C) as D 
;

/* View: CODIGO_FORNECEDOR_VW, Owner: SYSDBA */
CREATE VIEW CODIGO_FORNECEDOR_VW (SEQID, COD_EMPRESA, COD_FORNECEDOR, CPFCGC, GRUPO_PROD, COD_PROD, NUM_FAB_FORNECEDOR, ATIVO, DATA_CADASTRO, DATA_MODIFICACAO, COD_GRADE, TABELA) AS

select 0, PRODUTOS_FORN_NFE2.COD_EMPRESA,
       0 COD_FORNECEDOR, PRODUTOS_FORN_NFE2.CPFCGC,
       PRODUTOS_FORN_NFE2.GRUPO_PROD, PRODUTOS_FORN_NFE2.COD_PROD, PRODUTOS_FORN_NFE2.NUM_FAB_FORNECEDOR,
       PRODUTOS_FORN_NFE2.ATIVO, PRODUTOS_FORN_NFE2.DATA_CADASTRO, PRODUTOS_FORN_NFE2.DATA_MODIFICACAO,
       PRODUTOS_FORN_NFE2.COD_GRADE, 'PRODUTOS_FORN_NFE2' TABELA
from PRODUTOS_FORN_NFE2
INNER JOIN PRODUTOS ON PRODUTOS.GRUPO_PROD = PRODUTOS_FORN_NFE2.GRUPO_PROD
    AND PRODUTOS.COD_PROD = PRODUTOS_FORN_NFE2.COD_PROD
    AND PRODUTOS.COD_EMPRESA = PRODUTOS_FORN_NFE2.COD_EMPRESA
WHERE PRODUTOS.ATIVO <> 99
union
select PRODUTOS_FORN_NFE.SEQID, PRODUTOS_FORN_NFE.COD_EMPRESA,
       PRODUTOS_FORN_NFE.COD_FORNECEDOR, CLIENTES.CPFCGC,
       PRODUTOS_FORN_NFE.GRUPO_PROD, PRODUTOS_FORN_NFE.COD_PROD, PRODUTOS_FORN_NFE.NUM_FAB_FORNECEDOR,
       PRODUTOS_FORN_NFE.ATIVO, PRODUTOS_FORN_NFE.DATA_CADASTRO, PRODUTOS_FORN_NFE.DATA_MODIFICACAO,
       PRODUTOS_FORN_NFE.COD_GRADE, 'PRODUTOS_FORN_NFE' TABELA
from PRODUTOS_FORN_NFE
INNER JOIN CLIENTES ON CLIENTES.COD_CLIENTE = PRODUTOS_FORN_NFE.COD_FORNECEDOR
    AND CLIENTES.COD_EMPRESA = PRODUTOS_FORN_NFE.COD_EMPRESA
INNER JOIN PRODUTOS ON PRODUTOS.GRUPO_PROD = PRODUTOS_FORN_NFE.GRUPO_PROD
    AND PRODUTOS.COD_PROD = PRODUTOS_FORN_NFE.COD_PROD
    AND PRODUTOS.COD_EMPRESA = PRODUTOS_FORN_NFE.COD_EMPRESA
WHERE PRODUTOS.ATIVO <> 99
union
select 0 SEQID, CODIGO_FORNECEDOR.COD_EMPRESA,
       CODIGO_FORNECEDOR.COD_FORNECEDOR, CLIENTES.CPFCGC,
       CODIGO_FORNECEDOR.GRUPO_PROD, CODIGO_FORNECEDOR.COD_PROD, cast(CODIGO_FORNECEDOR.NUM_FAB_FORNECEDOR as varchar(60)),
       CODIGO_FORNECEDOR.ATIVO, CODIGO_FORNECEDOR.DATA_CADASTRO, CODIGO_FORNECEDOR.DATA_MODIFICACAO,
       CODIGO_FORNECEDOR.COD_GRADE, 'CODIGO_FORNECEDOR' TABELA
from CODIGO_FORNECEDOR
INNER JOIN CLIENTES ON CLIENTES.COD_CLIENTE = CODIGO_FORNECEDOR.COD_FORNECEDOR
    AND CLIENTES.COD_EMPRESA = CODIGO_FORNECEDOR.COD_EMPRESA
INNER JOIN PRODUTOS ON PRODUTOS.GRUPO_PROD = CODIGO_FORNECEDOR.GRUPO_PROD
    AND PRODUTOS.COD_PROD = CODIGO_FORNECEDOR.COD_PROD
    AND PRODUTOS.COD_EMPRESA = CODIGO_FORNECEDOR.COD_EMPRESA
WHERE PRODUTOS.ATIVO <> 99
;

/* View: RECIBO_PROG_FID, Owner: SYSDBA */
CREATE VIEW RECIBO_PROG_FID (CODIGO, COD_EMPRESA, COD_TAXA_PROG_FID, COD_CLIENTE, TIPO, DESCRICAO, VALOR_OP, DATA, PONTOS, NDOC, TIPODOC, DATA_VENC_PROG, PERC_PROG_FID, VALOR, NOME_CLIENTE, RAZAO, CPFCGC, SIGLA_UF, CIDADE, BAIRRO, ENDERECO, COMPLEMENTO, NUM_END_CLIENTE, CEP, IDENTIFICACAO_EMP, CGC_EMP, ESTADO_EMP, CIDADE_EMP, BAIRRO_EMP, ENDERECO_EMP, COMPLEMENTO_EMP, NUMERO_END, CEP_EMP, VALE) AS

SELECT CP.CODIGO, CP.COD_EMPRESA,
CP.COD_TAXA_PROG_FID, CP.COD_CLIENTE, CP.TIPO, CP.DESCRICAO, CP.VALOR_OP, CP.DATA,
CP.PONTOS, CP.NDOC, CP.TIPODOC, CP.DATA_VENC_PROG, CP.PERC_PROG_FID, CP.VALOR,
CL.NOME_CLIENTE, CL.RAZAO, CL.CPFCGC, EST.SIGLA_UF, CL.CIDADE, CL.BAIRRO, CL.ENDERECO, CL.COMPLEMENTO, CL.NUM_END_CLIENTE, CL.CEP,
EMP.IDENTIFICACAO_EMP, EMP.CGC_EMP, EMP.ESTADO_EMP, EMP.CIDADE_EMP, EMP.BAIRRO_EMP, EMP.ENDRECO_EMP, EMP.COMPLEMENTO_EMP, EMP.NUMERO_END, EMP.CEP_EMP,
CP.VALE
FROM CONTA_CORRENTE_PROG_FIDELIDADE CP
INNER JOIN EMPRESA EMP ON EMP.COD_EMPRESA = CP.COD_EMPRESA 
INNER JOIN CLIENTES CL ON CL.COD_CLIENTE = CP.COD_CLIENTE AND CL.COD_EMPRESA = CP.COD_EMPRESA
LEFT JOIN ESTADOS EST ON EST.CODIGO_UF = CL.CODIGO_UF
;

/* View: VW_CLIENTES_DEST, Owner: SYSDBA */
CREATE VIEW VW_CLIENTES_DEST (COD_CLIENTE, COD_EMPRESA, DEST_SEQID, TIPO_END, NOME_CLIENTE, RAZAO, CPFCGC, INSC_EST, INDIEDEST, IDESTRANGEIRO, ISUF, IM, LOGRADOURO, NUMERO, BAIRRO, CEP, COMPLEMENTO, CIDADE, UF, TELEFONE, EMAIL, LOCALIDADE, SETOR, COD_CIDADE, COD_LOCALIDADE, CMUN, CPAIS, XPAIS, ZFM_ALC, ATIVO) AS

/*view enderecos cliente*/
select CL.COD_CLIENTE, CL.COD_EMPRESA, 0 DEST_SEQID, 'Principal' TIPO_END, CL.NOME_CLIENTE, CL.RAZAO, CL.CPFCGC,
       CL.INSC_EST, CL.NFE_INDIEDEST, CL.NFE_IDESTRANGEIRO, cl.ISUF, CL.INSC_MUNICIPAL IM, CL.ENDERECO LOGRADOURO,
       CL.NUM_END_CLIENTE NUMERO, CL.BAIRRO BAIRRO, CL.CEP, CL.COMPLEMENTO, CL.CIDADE, ES.SIGLA_UF UF,
       CL.FONE_CLIENTE TELEFONE, CL.EMAIL, LOC.LOCALIDADE, SR.SETOR, CL.COD_CIDADE, CL.COD_LOCALIDADE,
       CI.IBGE_COD_CIDADE CMUN, CL.COD_PAIS CPAIS, PA.NOME_PAIS XPAIS, IBGE.ZFM_ALC, CL.ATIVO
from CLIENTES CL
left join CIDADES CI on CI.COD_CIDADE = CL.COD_CIDADE
left join CIDADES_IBGE IBGE ON IBGE.CODIGO_MUN_IBGE = CI.IBGE_COD_CIDADE
left join PAISES PA on PA.COD_PAIS = CL.COD_PAIS
left join LOCALIDADE LOC on LOC.COD_LOCALIDADE = CL.COD_LOCALIDADE and
      LOC.COD_EMPRESA = CL.COD_EMPRESA
left join SETOR SR on SR.COD_SETOR = LOC.COD_SETOR and
      SR.COD_EMPRESA = LOC.COD_EMPRESA
left join ESTADOS ES on ES.CODIGO_UF = CL.CODIGO_UF
union
select distinct CL.COD_CLIENTE, CL.COD_EMPRESA, AD.SEQID DEST_SEQID, AD.TIPO TIPO_END, CL.NOME_CLIENTE, CL.RAZAO,
                CL.CPFCGC, AD.INSC_EST, AD.INDIEDEST, AD.IDESTRANGEIRO, AD.ISUF, AD.IM, AD.XLGR LOGRADOURO,
                AD.NRO NUMERO, AD.XBAIRRO BAIRRO, AD.CEP, AD.XCPL COMPLEMENTO, AD.XMUN CIDADE, AD.UF, AD.FONE TELEFONE,
                AD.EMAIL, LOC.LOCALIDADE, SR.SETOR, AD.COD_CIDADE, AD.COD_LOCALIDADE, AD.CMUN, AD.CPAIS, AD.XPAIS,
                IBGE.ZFM_ALC, AD.ATIVO
from CLIENTES CL
inner join CLIENTES_END_DOC_ADD AD on AD.COD_CLIENTE = CL.COD_CLIENTE and
      AD.COD_EMPRESA = CL.COD_EMPRESA
left join CIDADES_IBGE IBGE ON IBGE.CODIGO_MUN_IBGE = AD.CMUN
left join LOCALIDADE LOC on LOC.COD_LOCALIDADE = AD.COD_LOCALIDADE and
      LOC.COD_EMPRESA = CL.COD_EMPRESA
left join SETOR SR on SR.COD_SETOR = LOC.COD_SETOR and
      SR.COD_EMPRESA = LOC.COD_EMPRESA
left join ESTADOS ES on ES.CODIGO_UF = CL.CODIGO_UF
order by 1, 2, 3
;

/* View: SUGESTAOCOMPRAITENS, Owner: SYSDBA */
CREATE VIEW SUGESTAOCOMPRAITENS (COD_SUGESTAO, COD_EMPRESA, COD_EMP_MULT, GRUPO_PROD, COD_PROD, COD_GRADE, QTD_TRANSF, SUGESTAOCOMPRA, ESTOQUE_ATUAL, QTD_PEND, CLASSESPROD, MEDIAMES, ATIVO) AS

select COD_SUGESTAO, COD_EMPRESA, COD_EMPRESA AS COD_EMP_MULT,
GRUPO_PROD, COD_PROD, COD_GRADE,
QTD_TRANSF, SUGESTAOCOMPRA, ESTOQUE_ATUAL, QTD_PEND, CLASSESPROD, MEDIAMES, ATIVO from SUGESTAOCOMPRAIT
UNION ALL
select COD_SUGESTAO, COD_EMPRESA, COD_EMP_MULT,
GRUPO_PROD, COD_PROD, COD_GRADE,
QTD_TRANSF, SUGESTAOCOMPRA, ESTOQUE_ATUAL, QTD_PEND, CLASSESPROD, MEDIAMES, ATIVO from SUGESTAOCOMPRAIT2
;

/* View: CADTABELA, Owner: SYSDBA */
CREATE VIEW CADTABELA (COD_PROMOCAO, COD_EMPRESA, DESCR_PROMOCAO) AS

SELECT PROMOCAO.COD_PROMOCAO, PROMOCAO.COD_EMPRESA,
PROMOCAO.DESCR_PROMOCAO FROM PROMOCAO
INNER JOIN TIPO_PRECO ON TIPO_PRECO.COD_TPPRECO = PROMOCAO.COD_TPPRECO
    AND TIPO_PRECO.COD_EMPRESA = PROMOCAO.COD_EMPRESA AND TIPO_PRECO.TIPO = 'T'
WHERE PROMOCAO.ATIVO = 1 AND PROMOCAO.COD_PROMOCAO > 0
;

/* View: CADPROMOCAO, Owner: SYSDBA */
CREATE VIEW CADPROMOCAO (COD_PROMOCAO, COD_EMPRESA, DESCR_PROMOCAO, ORDEM, DATA_INI, DATA_FIM, HORA_INI, HORA_FIM) AS

SELECT PROMOCAO.COD_PROMOCAO, PROMOCAO.COD_EMPRESA,
PROMOCAO.DESCR_PROMOCAO, PROMOCAO.ORDEM,
PROMOCAO.DATA_INI, PROMOCAO.DATA_FIM,
PROMOCAO.HORA_INI, PROMOCAO.HORA_FIM FROM PROMOCAO
INNER JOIN TIPO_PRECO ON TIPO_PRECO.COD_TPPRECO = PROMOCAO.COD_TPPRECO
    AND TIPO_PRECO.COD_EMPRESA = PROMOCAO.COD_EMPRESA AND TIPO_PRECO.TIPO = 'P'
WHERE PROMOCAO.ATIVO = 1
;

/* View: CREDITOSCHEQUE, Owner: SYSDBA */
CREATE VIEW CREDITOSCHEQUE (LOTE, CODIGO, CODIGO_EMP, COD_EMP_MULT, HISTORICO, VALOR, COD_CLIENTE, CLIENTE, TIPO_DOC) AS

select baixa_creditos.lote_quit, baixa_creditos.cod_cred,
baixa_creditos.codigo_emp, baixa_creditos.cod_emp_mult,
baixa_creditos.historico_c, baixa_creditos.valor_quitado,
baixa_creditos.cod_cliente, baixa_creditos.nome_c,
controles.nome_ctrl from baixa_creditos
inner join controles on controles.codigo_ctrl = baixa_creditos.codigo_ctrl and controles.codigo_emp = baixa_creditos.codigo_emp
inner join baixa_creditos bx on
    bx.cod_cred = baixa_creditos.cod_cred and bx.codigo_emp = baixa_creditos.codigo_emp

union

select controle_cheque.lote_quit, controle_cheque.codigo_ch,
controle_cheque.codigo_emp, controle_cheque.cod_emp_mult,
controle_cheque.historico_ch, controle_cheque.valor_ch,
controle_cheque.cod_cliente, controle_cheque.nome_ch,
controles.nome_ctrl from controle_cheque
inner join controles on controles.codigo_ctrl = controle_cheque.codigo_ctrl and controles.codigo_emp = controle_cheque.codigo_emp

inner join controle_cheque ch on
    ch.codigo_ch = controle_cheque.codigo_ch and ch.codigo_emp = controle_cheque.codigo_emp
;

/* View: SERVICOS_EMP, Owner: SYSDBA */
CREATE VIEW SERVICOS_EMP (COD_SERVICO, COD_EMPRESA, VALOR_SERVICO, DESC_SERVICO, SHONDA, ALTCOD, DATA_CAD_TIPO, DATA_MOD_TIPO, STIPO, TMO, ALIQ_ISS, ATIVO, COD_ESPE_SEG, CODIGO_NOP, TMOSERVSIMULT, ALT_DESC, SERV_PROP_TERC, ISENTO_SERV, N_INCIDENCIA_SERV, ARREDONDAR_TRUNCAR, CLASSE_SERV, CLASSE_QTD, CLASSE_POP, CLASSE_ATL, DMD) AS

SELECT
TIPO_SERVICO.COD_SERVICO,
TIPO_SERVICO_EMPRESA.COD_EMPRESA,
TIPO_SERVICO.VALOR_SERVICO,
TIPO_SERVICO.DESC_SERVICO,
TIPO_SERVICO.SHONDA,
TIPO_SERVICO.ALTCOD,
TIPO_SERVICO.DATA_CAD_TIPO,
TIPO_SERVICO.DATA_MOD_TIPO,
TIPO_SERVICO.STIPO,
TIPO_SERVICO.TMO,
TIPO_SERVICO.ALIQ_ISS,
TIPO_SERVICO.ATIVO,
TIPO_SERVICO.COD_ESPE_SEG,
TIPO_SERVICO.CODIGO_NOP,
TIPO_SERVICO.TMOSERVSIMULT,
TIPO_SERVICO.ALT_DESC,
TIPO_SERVICO.SERV_PROP_TERC,
TIPO_SERVICO.ISENTO_SERV,
TIPO_SERVICO.N_INCIDENCIA_SERV,
TIPO_SERVICO.ARREDONDAR_TRUNCAR,
TIPO_SERVICO.CLASSE_SERV,
TIPO_SERVICO.CLASSE_QTD,
TIPO_SERVICO.CLASSE_POP,
TIPO_SERVICO.CLASSE_ATL,
TIPO_SERVICO.DMD
FROM TIPO_SERVICO
LEFT JOIN TIPO_SERVICO_EMPRESA ON
    TIPO_SERVICO_EMPRESA.COD_SERVICO = TIPO_SERVICO.COD_SERVICO
;

/* View: VW_RPS_NFSE, Owner: SYSDBA */
CREATE VIEW VW_RPS_NFSE (NOME_CLIENTE, NPED, TIPO, ALIQ_ISS, NFS_SERVICO, CNAE_SERV, VL_LIQ, VALORNF, CIDADE, COD_RPS, N_NF, COD_EMPRESA, DATA_FECH, STATUS_NFSE, ISS_RETIDO, CTISS, CTRIBNAC, CTRIBMUN, CNBS, NFSE_NACIONAL, MODELO_NFSE, EMISSAO_RPS, COD_CLIENTE, CODIGO_VERWSNFSE, NFS_SERVICO_TS, IRRF_SERVICO, ISSRET_SERVICO, PISRF_SERVICO, COFINSRF_SERVICO, CSSLRF_SERVICO, BRUTO) AS

--Autorizadas versao nao nacional
select clientes.nome_cliente, pedvenda.nped, pedvenda.tipo, pedvenda_serv.aliq_iss,
       pedvenda_serv.nfs_servico, pedvenda_serv.cnae_serv,
       sum(pedvenda_serv.valor_tot_serv + coalesce(pedvenda_serv.rateio_acresc, 0) - pedvenda_serv.rateio_desc) vl_liq,
       sum(pedvenda_serv.valor_nfse) as valornf, clientes.cidade, pedvenda_serv.cod_rps, pedvenda_serv.n_nf, pedvenda_serv.cod_empresa,
       pedvenda.data_fech, pedvenda_serv.status_nfse, pedvenda_serv.iss_retido, pedvenda_serv.ctiss,
       pedvenda_serv.ctribnac, pedvenda_serv.ctribmun, pedvenda_serv.cnbs, 0 nfse_nacional, pedvenda_serv.modelo_nfse,
       pedvenda_serv.emissao_rps, pedvenda.cod_cliente, pedvenda_serv.codigo_verwsnfse, tipo_servico.nfs_servico nfs_servico_ts,
       sum(pedvenda_serv.irrf_servico) as irrf_servico,
       sum(pedvenda_serv.issret_servico) as issret_servico,
       sum(pedvenda_serv.pisrf_servico) as pisrf_servico,
       sum(pedvenda_serv.cofinsrf_servico) as cofinsrf_servico,
       sum(pedvenda_serv.csslrf_servico) as csslrf_servico,
       sum(pedvenda_serv.valor_b_nfse) as bruto
from pedvenda_serv
  inner join tipo_servico on tipo_servico.cod_servico = pedvenda_serv.cod_servico
  inner join pedvenda on pedvenda_serv.nped = pedvenda.nped and
        pedvenda_serv.tipo = pedvenda.tipo and
        pedvenda_serv.cod_empresa = pedvenda.cod_empresa
  inner join clientes on pedvenda.cod_cliente = clientes.cod_cliente and
        pedvenda.cod_empresa = clientes.cod_empresa
  inner join empresa on empresa.cod_empresa = pedvenda_serv.cod_empresa
where pedvenda.tipo = 'OS' and pedvenda.status_ped = 'FECHADA'
  and pedvenda_serv.valor_tot_serv <> 0 and coalesce(pedvenda_serv.status, '') <> 'CANCELADO' and pedvenda.ativo = 1
  and pedvenda_serv.n_nf is not null and pedvenda_serv.n_nf > 0
  and coalesce(pedvenda_serv.nfse_nacional, 0) <> 1
group by nome_cliente, nped, tipo, aliq_iss, nfs_servico, cnae_serv, cidade, cod_rps, n_nf, cod_empresa, data_fech, status_nfse, iss_retido, ctiss,
  ctribnac, ctribmun, cnbs, nfse_nacional, modelo_nfse, emissao_rps, cod_cliente, codigo_verwsnfse, nfs_servico_ts
union   
--Nao autorizadas padrao nacional desativado
select clientes.nome_cliente, pedvenda.nped, pedvenda.tipo, iif(cs.value1_f = 1, empresa.aliq_simples_iss, tipo_servico.aliq_iss) aliq_iss,
       tipo_servico.nfs_servico, tipo_servico.cnae_serv,
       sum(pedvenda_serv.valor_tot_serv + coalesce(pedvenda_serv.rateio_acresc, 0) - pedvenda_serv.rateio_desc) vl_liq,
       sum(pedvenda_serv.valor_nfse) as valornf, clientes.cidade, pedvenda_serv.cod_rps, pedvenda_serv.n_nf, pedvenda_serv.cod_empresa,
       pedvenda.data_fech, pedvenda_serv.status_nfse,
       case
         when coalesce(clientes.iss_retido, 0) <> 0 then clientes.iss_retido
         else tipo_servico.iss_retido
       end as iss_retido,
       tipo_servico.ctiss,
       tipo_servico.ctribnac, tipo_servico.ctribmun, tipo_servico.cnbs, 0 nfse_nacional, pedvenda_serv.modelo_nfse,
       pedvenda_serv.emissao_rps, pedvenda.cod_cliente, pedvenda_serv.codigo_verwsnfse, tipo_servico.nfs_servico nfs_servico_ts,
       sum(pedvenda_serv.irrf_servico) as irrf_servico,
       sum(pedvenda_serv.issret_servico) as issret_servico,
       sum(pedvenda_serv.pisrf_servico) as pisrf_servico,
       sum(pedvenda_serv.cofinsrf_servico) as cofinsrf_servico,
       sum(pedvenda_serv.csslrf_servico) as csslrf_servico,
       sum(pedvenda_serv.valor_b_nfse) as bruto
from pedvenda_serv
  inner join tipo_servico on tipo_servico.cod_servico = pedvenda_serv.cod_servico
  inner join pedvenda on pedvenda_serv.nped = pedvenda.nped and
        pedvenda_serv.tipo = pedvenda.tipo and
        pedvenda_serv.cod_empresa = pedvenda.cod_empresa
  inner join clientes on pedvenda.cod_cliente = clientes.cod_cliente and
        pedvenda.cod_empresa = clientes.cod_empresa
  inner join empresa on empresa.cod_empresa = pedvenda_serv.cod_empresa
  left join config_sistema cs on cs.chave = 'nfse_simples_nacional_aliq' and
        cs.cod_empresa = empresa.cod_empresa
  left join config_sistema cn on cn.chave = 'nfse_config' and
        cn.cod_empresa = empresa.cod_empresa
where pedvenda.tipo = 'OS' and pedvenda.status_ped = 'FECHADA'
  and pedvenda_serv.valor_tot_serv <> 0 and coalesce(pedvenda_serv.status, '') <> 'CANCELADO' and pedvenda.ativo = 1
  and coalesce(pedvenda_serv.n_nf, 0) = 0
  and coalesce(pedvenda_serv.nfse_nacional, 0) <> 1
  and coalesce(cn.value1_f, 0) = 0
group by nome_cliente, nped, tipo, aliq_iss, nfs_servico, cnae_serv, cidade, cod_rps, n_nf, cod_empresa, data_fech, status_nfse, iss_retido, ctiss,
  ctribnac, ctribmun, cnbs, nfse_nacional, modelo_nfse, emissao_rps, cod_cliente, codigo_verwsnfse, nfs_servico_ts
union
--Padrao nacional autorizadas
select clientes.nome_cliente, pedvenda.nped, pedvenda.tipo, pedvenda_serv.aliq_iss,
       null nfs_servico, null cnae_serv,
       sum(pedvenda_serv.valor_tot_serv + coalesce(pedvenda_serv.rateio_acresc, 0) - pedvenda_serv.rateio_desc) vl_liq,
       sum(pedvenda_serv.valor_nfse) as valornf, clientes.cidade, pedvenda_serv.cod_rps, pedvenda_serv.n_nf, pedvenda_serv.cod_empresa,
       pedvenda.data_fech, pedvenda_serv.status_nfse, pedvenda_serv.iss_retido, null ctiss,
       pedvenda_serv.ctribnac, pedvenda_serv.ctribmun, pedvenda_serv.cnbs, pedvenda_serv.nfse_nacional, pedvenda_serv.modelo_nfse,
       pedvenda_serv.emissao_rps, pedvenda.cod_cliente, pedvenda_serv.codigo_verwsnfse, tipo_servico.nfs_servico nfs_servico_ts,
       sum(pedvenda_serv.irrf_servico) as irrf_servico,
       sum(pedvenda_serv.issret_servico) as issret_servico,
       sum(pedvenda_serv.pisrf_servico) as pisrf_servico,
       sum(pedvenda_serv.cofinsrf_servico) as cofinsrf_servico,
       sum(pedvenda_serv.csslrf_servico) as csslrf_servico,
       sum(pedvenda_serv.valor_b_nfse) as bruto
from pedvenda_serv
  inner join tipo_servico on tipo_servico.cod_servico = pedvenda_serv.cod_servico
  inner join pedvenda on pedvenda_serv.nped = pedvenda.nped and
        pedvenda_serv.tipo = pedvenda.tipo and
        pedvenda_serv.cod_empresa = pedvenda.cod_empresa
  inner join clientes on pedvenda.cod_cliente = clientes.cod_cliente and
        pedvenda.cod_empresa = clientes.cod_empresa
  inner join empresa on empresa.cod_empresa = pedvenda_serv.cod_empresa
where pedvenda.tipo = 'OS' and pedvenda.status_ped = 'FECHADA'
  and pedvenda_serv.valor_tot_serv <> 0 and coalesce(pedvenda_serv.status, '') <> 'CANCELADO' and pedvenda.ativo = 1
  and pedvenda_serv.n_nf is not null and pedvenda_serv.n_nf > 0
  and pedvenda_serv.nfse_nacional = 1
group by nome_cliente, nped, tipo, aliq_iss, nfs_servico, cnae_serv, cidade, cod_rps, n_nf, cod_empresa, data_fech, status_nfse, iss_retido, ctiss,
  ctribnac, ctribmun, cnbs, nfse_nacional, modelo_nfse, emissao_rps, cod_cliente, codigo_verwsnfse, nfs_servico_ts
union   
--Nao autorizadas PADRAO NACIONAL ATIVADO
select clientes.nome_cliente, pedvenda.nped, pedvenda.tipo, iif(cs.value1_f = 1, empresa.aliq_simples_iss, tipo_servico.aliq_iss) aliq_iss,
       null nfs_servico, null cnae_serv,
       sum(pedvenda_serv.valor_tot_serv + coalesce(pedvenda_serv.rateio_acresc, 0) - pedvenda_serv.rateio_desc) vl_liq,
       sum(pedvenda_serv.valor_nfse) as valornf, clientes.cidade, pedvenda_serv.cod_rps, pedvenda_serv.n_nf, pedvenda_serv.cod_empresa,
       pedvenda.data_fech, pedvenda_serv.status_nfse,
       case
         when coalesce(clientes.iss_retido, 0) <> 0 then clientes.iss_retido
         else tipo_servico.iss_retido
       end as iss_retido,
       null ctiss,
       tipo_servico.ctribnac, tipo_servico.ctribmun, tipo_servico.cnbs, 1 nfse_nacional, pedvenda_serv.modelo_nfse,
       pedvenda_serv.emissao_rps, pedvenda.cod_cliente, pedvenda_serv.codigo_verwsnfse, tipo_servico.nfs_servico nfs_servico_ts,
       sum(pedvenda_serv.irrf_servico) as irrf_servico,
       sum(pedvenda_serv.issret_servico) as issret_servico,
       sum(pedvenda_serv.pisrf_servico) as pisrf_servico,
       sum(pedvenda_serv.cofinsrf_servico) as cofinsrf_servico,
       sum(pedvenda_serv.csslrf_servico) as csslrf_servico,
       sum(pedvenda_serv.valor_b_nfse) as bruto
from pedvenda_serv
  inner join tipo_servico on tipo_servico.cod_servico = pedvenda_serv.cod_servico
  inner join pedvenda on pedvenda_serv.nped = pedvenda.nped and
        pedvenda_serv.tipo = pedvenda.tipo and
        pedvenda_serv.cod_empresa = pedvenda.cod_empresa
  inner join clientes on pedvenda.cod_cliente = clientes.cod_cliente and
        pedvenda.cod_empresa = clientes.cod_empresa
  inner join empresa on empresa.cod_empresa = pedvenda_serv.cod_empresa
  left join config_sistema cs on cs.chave = 'nfse_simples_nacional_aliq' and
        cs.cod_empresa = empresa.cod_empresa
  left join config_sistema cn on cn.chave = 'nfse_config' and
        cn.cod_empresa = empresa.cod_empresa and cn.value1_f = 1
where pedvenda.tipo = 'OS' and pedvenda.status_ped = 'FECHADA'
  and pedvenda_serv.valor_tot_serv <> 0 and coalesce(pedvenda_serv.status, '') <> 'CANCELADO' and pedvenda.ativo = 1
  and coalesce(pedvenda_serv.n_nf, 0) = 0
  and coalesce(pedvenda_serv.nfse_nacional, coalesce(cn.value1_f, 0)) = 1
group by nome_cliente, nped, tipo, aliq_iss, nfs_servico, cnae_serv, cidade, cod_rps, n_nf, cod_empresa, data_fech, status_nfse, iss_retido, ctiss,
  ctribnac, ctribmun, cnbs, nfse_nacional, modelo_nfse, emissao_rps, cod_cliente, codigo_verwsnfse, nfs_servico_ts
;

/* View: DADOS_RECEBIMENTO, Owner: SYSDBA */
CREATE VIEW DADOS_RECEBIMENTO (SEQFORM, NREQUISICAO, NDOC, TPDOCS, COD_EMPRESA, DATA_MOV, DATA_VENC, CODIGO_CTRL, NOME_CTRL, VALORDOC) AS

select fp.seqform, fp.nrequisicao, fp.ndoc, fp.tpdocs, fp.cod_empresa, fp.data_mov, fp.data_venc,
case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
coalesce(fp.valordoc, 0) valordoc
from formpagamento fp
left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
where fp.recibo is null
union
select fp.seqform, fp.nrequisicao, fp.ndoc, fp.tpdocs, fp.cod_empresa, fp.data_mov, fp.data_venc,
case when (select first 1 ctrl.nome_ctrl from controles ctrl
    inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
    where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend ='REC' order by rc.valordoc asc) is null then
        0
    else
       (select first 1 ctrl.codigo_ctrl from controles ctrl
        inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
        where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend ='REC' order by rc.valordoc asc)
end as codigo_ctrl,
'RECIBO ANTECIPADO' nome_ctrl,
coalesce(fp.valordoc, 0) valordoc
from formpagamento fp
where (not fp.recibo is null)
union
select fp.seqform, fp.rec_numvend, fp.ndoc, fp.rec_tipvend, fp.cod_empresa, fp.data_mov, fp.data_venc,
case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
'TROCO' nome_ctrl,
coalesce(fp.valordoc, 0) valordoc
from formpagamento fp
left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
where fp.tpdocs = 'TRC'
order by 1
;

/* View: MAPA_DESP_ANAL, Owner: SYSDBA */
CREATE VIEW MAPA_DESP_ANAL (TPDTQUIT_DTREF, N_CONTA_PLC, VALOR_L, DESC_GR, TIPO_GR, HISTORICO_L, DATA_REL, DATA, DTREFERENCIA, GRUP_CT, COD_LANC, MES_MAPA, DESC_P, VALOR_CONTABIL, MES_MAPA_REF, DESC_DEP, DESC_SUB_CT, CODIGO_EMP, COD_EMP_MULT, IDENTIFICACAO_EMP, CGC_EMP, FINANCEIRO_UNIFICADO, CODIGO_UNIFICADORA, COD_CTA, NOME_CTA) AS

select
    1 tpdtquit_dtref,
    mapa_desp.n_conta_plc,
    mapa_desp.valor_l,
    mapa_desp.desc_gr,
    mapa_desp.tipo_gr,
    mapa_desp.historico_l,
    mapa_desp.data, 
    mapa_desp.data,
    mapa_desp.dtreferencia,
    mapa_desp.grup_ct,
    mapa_desp.cod_lanc,
    mapa_desp.mes_mapa,
    mapa_desp.desc_p,
    mapa_desp.valor_contabil,
    mapa_desp.mes_mapa_ref,
    depart_ct.desc_dep,
    sub_grup_ct.desc_sub_ct,
    mapa_desp.codigo_emp,
    mapa_desp.cod_emp_mult,
    empresa.identificacao_emp,
    empresa.cgc_emp,
    empresa.financeiro_unificado,
    empresa.codigo_unificadora,
    p_contas_contabil.cod_cta,
    p_contas_contabil.nome_cta
    from mapa_desp
    inner join grupos_ct on grupos_ct.grup_ct = mapa_desp.grup_ct
    inner join depart_ct on depart_ct.cod_dep = mapa_desp.cod_dep
    inner join sub_grup_ct on sub_grup_ct.cod_sub_ct = mapa_desp.cd_subgrupo
    inner join empresa on empresa.cod_empresa = mapa_desp.cod_emp_mult
    inner join p_contas on p_contas.n_conta_plc = mapa_desp.n_conta_plc
    left join p_contas_contabil on p_contas_contabil.cod_cta = p_contas.cod_cta_contabil and p_contas_contabil.cod_empresa = empresa.cod_empresa
    
    union
    
    select
    2 tpdtquit_dtref,
    mapa_desp.n_conta_plc,
    mapa_desp.valor_l,
    mapa_desp.desc_gr,
    mapa_desp.tipo_gr,
    mapa_desp.historico_l,
    mapa_desp.dtreferencia,
    mapa_desp.data,
    mapa_desp.dtreferencia,
    mapa_desp.grup_ct,
    mapa_desp.cod_lanc,
    mapa_desp.mes_mapa,
    mapa_desp.desc_p,
    mapa_desp.valor_contabil,
    mapa_desp.mes_mapa_ref,
    depart_ct.desc_dep,
    sub_grup_ct.desc_sub_ct,
    mapa_desp.codigo_emp,
    mapa_desp.cod_emp_mult,
    empresa.identificacao_emp,
    empresa.cgc_emp,
    empresa.financeiro_unificado,
    empresa.codigo_unificadora,
    p_contas_contabil.cod_cta,
    p_contas_contabil.nome_cta
    from mapa_desp
    inner join grupos_ct on grupos_ct.grup_ct = mapa_desp.grup_ct
    inner join depart_ct on depart_ct.cod_dep = mapa_desp.cod_dep
    inner join sub_grup_ct on sub_grup_ct.cod_sub_ct = mapa_desp.cd_subgrupo
    inner join empresa on empresa.cod_empresa = mapa_desp.cod_emp_mult
    inner join p_contas on p_contas.n_conta_plc = mapa_desp.n_conta_plc
    left join p_contas_contabil on p_contas_contabil.cod_cta = p_contas.cod_cta_contabil and p_contas_contabil.cod_empresa = empresa.cod_empresa
;

/* View: ENTRADASMESESV, Owner: SYSDBA */
CREATE VIEW ENTRADASMESESV (COD_NF, NUM_NOTA, CHASSI, DATA_CH_NOTA, DESCRICAO_VERSAO, COR, ANO_FAB, ANO_MOD, CUSTO, COD_EMPRESA, COD_ESTMOTO, COD_NF_DEV, NITEM_DEV, TIPV_VEICULO, STATUS_USO) AS

select 0, it.num_nota,it.chassi_c,et.data_ch_nota, substr(it.descricao_versao, 1, 25),
it.cor,it.ano_fab,it.ano_mod,((et.valor_tot_nota/et.qtde_motos_nota)+it.piscofins),et.cod_empresa,
0, 0, 0, nt.tipv_veiculo,cast (et.tipo_entrada as char(10))
from ent_moto et
inner join ent_moto_itens it on it.num_nota = et.num_nota and it.cod_fornecedor = et.cod_fornecedor and it.cod_empresa = et.cod_empresa
inner join nat_op nt on nt.codigo_nop = et.cod_fisc_nota
where et.ativo = 1 --and coalesce(nt.compra, '') <> 'N'
union
select nf4.cod_nf,nf4.num_nf,it4.chassi,nf4.data_lanc,substr(it4.descricao_item,1,25),
itv4.cor,itv4.ano_fab,itv4.ano_mod,it4.prec_cusm_prod,nf4.cod_empresa,
it4.cod_estmoto,it4.cod_nf_dev, it4.nitem_dev, nt.tipv_veiculo, itv4.tipo_venda
from notafiscal nf4
inner join notafiscal_item it4 on nf4.cod_nf=it4.cod_nf and nf4.cod_empresa=it4.cod_empresa
inner join notafiscal_item_veiculo itv4 on it4.cod_nf=itv4.cod_nf and it4.cod_empresa = itv4.cod_empresa and it4.chassi = itv4.chassi
inner join nat_op nt on nt.codigo_nop = it4.codigo_nop
where nf4.natureza_nf='E' and (nf4.status = 'Fechada')
--and coalesce(nt.compra, '') <> 'N'
and nf4.tipo_nf = 'V' and nf4.ativo=1
;

/* View: VALOR_VENC_MIN, Owner: SYSDBA */
CREATE VIEW VALOR_VENC_MIN (NPED, TIPO, COD_EMPRESA, DATA) AS

SELECT FIRST 1 NREQUISICAO NPED,
TPDOCS TIPO,
COD_EMPRESA COD_EMPRESA,
DATA_VENC DATA_VENC FROM FORMPAGAMENTO
;

/* View: TP_RECCONTAB, Owner: SYSDBA */
CREATE VIEW TP_RECCONTAB (TIPO, NUM_NF, SERIE, TIPO_PED, NPED, NOME_CTRL, DATA_LANC, VALOR, CFOP, FATURAMENTO, SEQFORM, N_DOC, N_NF_SERV, N_CUPOM, COD_EMPRESA, CLIENTE, VALOR_NF_SERV, NRECIBO) AS

select 'NFPR' as tipo,nf.num_nf,nf.serie,pd.tipo as tipo_ped,pd.nped,ctrl.nome_contabil,nf.data_lanc,
fr.valor_contabil,nf.codigo_nop,nat.faturamento,fr.seqform,fr.ndoc,cast(pd.num_nfeext as integer),0,nf.cod_empresa,fr.cliente,pd.valor_nfext,fr.REC_NUMVEND
from notafiscal nf
left join pedvenda pd on nf.num_nf = pd.num_nf and nf.serie = pd.serie_nf and nf.cod_empresa = pd.cod_empresa
left join formpagamento fr on pd.tipo = fr.tpdocs and pd.nped = fr.nrequisicao and fr.recibo is null
left join controles ctrl on fr.cod_controle = ctrl.codigo_ctrl and fr.cod_empresa = ctrl.codigo_emp
left join nat_op nat on nat.codigo_nop = nf.codigo_nop
where (pd.tipo <> 'MOT' and pd.tipo <> 'ORC') and  nf.data_lanc >= '02/01/2011'
and (not ctrl.nome_contabil is null) and  nf.natureza_nf = 'S'
and ((nf.modelo_nf = '55' and coalesce(nf.situacao_nfe,'') = 'Autorizada')
or (nf.emissao_propria = 'S' and nf.modelo_nf <> '55'))
/* and nf.status = 'Fechada' */
union
select 'RECR' as tipo,nf.num_nf,nf.serie,pd.tipo as tipo_ped,pd.nped,
case when (select first 1 ctrl.nome_contabil from controles ctrl
           inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
           where rc.nrequisicao = fr.rec_numvend and rc.cod_empresa = fr.cod_empresa and rc.tpdocs ='REC'
           order by valordoc asc) is null then
             ctrl.nome_contabil
           else
             (select first 1 ctrl.nome_contabil from controles ctrl
             inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
             where rc.nrequisicao = fr.rec_numvend and rc.cod_empresa = fr.cod_empresa and rc.tpdocs ='REC'
             order by valordoc asc) end as nome_contabil,
nf.data_lanc,fr.valor_contabil,nf.codigo_nop,nat.faturamento,fr.seqform,fr.ndoc,cast(pd.num_nfeext as integer),0,nf.cod_empresa,fr.cliente,pd.valor_nfext,fr.REC_NUMVEND
from notafiscal nf
inner join pedvenda pd on nf.num_nf = pd.num_nf and nf.serie = pd.serie_nf and nf.cod_empresa = pd.cod_empresa
inner join formpagamento fr on pd.tipo = fr.tpdocs and pd.nped = fr.nrequisicao and (not fr.recibo is null)
inner join controles ctrl on fr.cod_controle = ctrl.codigo_ctrl and fr.cod_empresa = ctrl.codigo_emp
left join nat_op nat on nat.codigo_nop = nf.codigo_nop
where (pd.tipo <> 'MOT' and pd.tipo <> 'ORC') and  nf.data_lanc >= '04/01/2011'
and nf.natureza_nf = 'S' and
((nf.modelo_nf = '55' and coalesce(nf.situacao_nfe,'') = 'Autorizada')
or (nf.emissao_propria = 'S' and nf.modelo_nf <> '55'))
/*and nf.status = 'Fechada'*/
union
select 'NFMM' as tipo,nf.num_nf,nf.serie,'MOT' as tipo_ped,nf.n_comando as nped,ctrl.nome_contabil,nf.data_lanc,
fr.valor_contabil,nf.codigo_nop,nat.faturamento,fr.seqform,fr.ndoc,0,0,nf.cod_empresa,fr.cliente,0,0
from notafiscal nf
left join formpagamento fr on fr.tpdocs = 'MOT' and fr.nrequisicao = nf.n_comando
left join controles ctrl on fr.cod_controle = ctrl.codigo_ctrl and fr.cod_empresa = ctrl.codigo_emp
left join nat_op nat on nat.codigo_nop = nf.codigo_nop
where nf.data_lanc >= '02/01/2011'
and (not ctrl.nome_contabil is null) and (not nf.n_comando is null) and (fr.recibo is null)
and nf.natureza_nf = 'S' and
((nf.modelo_nf = '55' and coalesce(nf.situacao_nfe,'') = 'Autorizada')
or (nf.emissao_propria = 'S' and nf.modelo_nf <> '55'))
/*nf.status = 'Fechada'*/
union
select 'RECM' as tipo,nf.num_nf,nf.serie,'MOT' as tipo_ped,nf.n_comando,
case when (select first 1 ctrl.nome_contabil from controles ctrl
          inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
          where rc.nrequisicao = fr.rec_numvend and rc.cod_empresa = fr.cod_empresa and rc.tpdocs ='REC' order by valordoc asc) is null then
            ctrl.nome_contabil
          else
            (select first 1 ctrl.nome_contabil from controles ctrl
            inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
            where rc.nrequisicao = fr.rec_numvend and rc.cod_empresa = fr.cod_empresa and
            rc.tpdocs ='REC' order by valordoc asc) end as nome_contabil,
nf.data_lanc, fr.valor_contabil,nf.codigo_nop,nat.faturamento,fr.seqform,fr.ndoc,0,0,nf.cod_empresa,fr.cliente,0,fr.REC_NUMVEND
from notafiscal nf
inner join formpagamento fr on fr.tpdocs = 'MOT' and NF.n_comando = fr.nrequisicao and (not fr.recibo is null)
inner join controles ctrl on fr.cod_controle = ctrl.codigo_ctrl and fr.cod_empresa = ctrl.codigo_emp
left join nat_op nat on nat.codigo_nop = nf.codigo_nop
where (not nf.n_comando is null) and  nf.data_lanc >= '02/01/2011'
and nf.natureza_nf = 'S' and
((nf.modelo_nf = '55' and coalesce(nf.situacao_nfe,'') = 'Autorizada')
or (nf.emissao_propria = 'S' and nf.modelo_nf <> '55'))
/*nf.status = 'Fechada'*/
union
select 'RCCP' as tipo,0 as num_nf,0,pd.tipo as tipo_ped,pd.nped,ctrl.nome_contabil,
case when pd.ncupom is null then pd.data_nfext else pd.data_cupom end as data_cupomnf,
fr.valor_contabil,0,'S',fr.seqform,fr.ndoc,cast(pd.num_nfeext as integer),pd.ncupom,pd.cod_empresa,fr.cliente,pd.valor_nfext,fr.REC_NUMVEND
from pedvenda pd
left join formpagamento fr on pd.tipo = fr.tpdocs and pd.nped = fr.nrequisicao and fr.recibo is null
left join controles ctrl on fr.cod_controle = ctrl.codigo_ctrl and fr.cod_empresa = ctrl.codigo_emp
where (pd.tipo <> 'MOT' and pd.tipo <> 'ORC') and  pd.data_fech >= '02/01/2011' /*and (pd.num_nf is null or pd.num_nf = 0)*/
and (not ctrl.nome_contabil is null) and pd.valor_total <> 0
and ((pd.ncupom <> 0 and (not pd.ncupom is null)) /*or
(pd.num_nfeext <> 0 and (not pd.num_nfeext is null))*/)
union
select 'RCRC' as tipo,0 as num_nf,'0',pd.tipo as tipo_ped,pd.nped,
case when (select first 1 ctrl.nome_contabil from controles ctrl
          inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
          where rc.nrequisicao = fr.rec_numvend and rc.cod_empresa = fr.cod_empresa and
          rc.tpdocs ='REC' order by valordoc asc) is null then
            ctrl.nome_contabil
          else
            (select first 1 ctrl.nome_contabil from controles ctrl
            inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
            where rc.nrequisicao = fr.rec_numvend and rc.cod_empresa = fr.cod_empresa and
            rc.tpdocs ='REC' order by valordoc asc) end as nome_contabil,
case when pd.ncupom is null then
         pd.data_nfext
     else
         pd.data_cupom end as data_cupomnf,
fr.valor_contabil,0,'S',fr.seqform,fr.ndoc,cast(pd.num_nfeext as integer),pd.ncupom,pd.cod_empresa,fr.cliente,pd.valor_nfext,fr.REC_NUMVEND
from pedvenda pd
inner join formpagamento fr on pd.tipo = fr.tpdocs and pd.nped = fr.nrequisicao and (not fr.recibo is null)
inner join controles ctrl on fr.cod_controle = ctrl.codigo_ctrl and fr.cod_empresa = ctrl.codigo_emp
where (pd.tipo <> 'MOT' and pd.tipo <> 'ORC') and  pd.data_fech >= '04/01/2011'
/*and (pd.num_nf is null or pd.num_nf = 0)*/ and pd.valor_total <> 0
and ((pd.ncupom <> 0 and (not pd.ncupom is null)) /*or
(pd.num_nfeext <> 0 and (not pd.num_nfeext is null))*/)
union
select 'NFSE' as tipo,0 as num_nf,0,pd.tipo as tipo_ped,pd.nped,ctrl.nome_contabil,
case when pd.ncupom is null then pd.data_nfext else pd.data_cupom end as data_cupomnf,
fr.valor_contabil,0,'S',fr.seqform,fr.ndoc,cast(pd.num_nfeext as integer),pd.ncupom,pd.cod_empresa,fr.cliente,
(coalesce(pd.valor_nfext,0)+coalesce((select sum(coalesce(ps.irrf_servico,0)+coalesce(ps.pisrf_servico,0)+
coalesce(ps.cofinsrf_servico,0)+coalesce(ps.csslrf_servico,0)) from pedvenda_serv ps
where ps.nped = pd.nped and ps.tipo = pd.tipo and ps.cod_empresa = pd.cod_empresa),0)) as valor_nfext,fr.REC_NUMVEND
from pedvenda pd
left join formpagamento fr on pd.tipo = fr.tpdocs and pd.nped = fr.nrequisicao and fr.recibo is null
left join controles ctrl on fr.cod_controle = ctrl.codigo_ctrl and fr.cod_empresa = ctrl.codigo_emp
where (pd.tipo <> 'MOT' and pd.tipo <> 'ORC') and  pd.data_fech >= '02/01/2011' and (pd.num_nf is null or pd.num_nf = 0)
and (not ctrl.nome_contabil is null) and pd.valor_total <> 0
and (pd.ncupom = 0 or (pd.ncupom is null)) and (pd.num_nfeext <> 0 and (not pd.num_nfeext is null))
union
select 'NFSR' as tipo,0 as num_nf,'0',pd.tipo as tipo_ped,pd.nped,
case when (select first 1 ctrl.nome_contabil from controles ctrl inner join formpagamento rc
        on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
        where rc.nrequisicao = fr.rec_numvend and rc.cod_empresa = fr.cod_empresa and
        rc.tpdocs ='REC' order by valordoc asc) is null then
            ctrl.nome_contabil
     else
        (select first 1 ctrl.nome_contabil from controles ctrl
        inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
        where rc.nrequisicao = fr.rec_numvend and rc.cod_empresa = fr.cod_empresa and
        rc.tpdocs ='REC' order by valordoc asc) end as nome_contabil,
case when pd.ncupom is null then
        pd.data_nfext
     else
        pd.data_cupom end as data_cupomnf,
fr.valor_contabil,0,'S',fr.seqform,fr.ndoc,cast(pd.num_nfeext as integer),pd.ncupom,pd.cod_empresa,fr.cliente,(coalesce(pd.valor_nfext,0)+coalesce((select sum(coalesce(ps.irrf_servico,0)+coalesce(ps.pisrf_servico,0)+
coalesce(ps.cofinsrf_servico,0)+coalesce(ps.csslrf_servico,0)) from pedvenda_serv ps
where ps.nped = pd.nped and ps.tipo = pd.tipo and ps.cod_empresa = pd.cod_empresa),0)) as valor_nfext,fr.REC_NUMVEND
from pedvenda pd
inner join formpagamento fr on pd.tipo = fr.tpdocs and pd.nped = fr.nrequisicao and (not fr.recibo is null)
inner join controles ctrl on fr.cod_controle = ctrl.codigo_ctrl and fr.cod_empresa = ctrl.codigo_emp
where (pd.tipo <> 'MOT' and pd.tipo <> 'ORC') and  pd.data_fech >= '04/01/2011'
and (pd.num_nf is null or pd.num_nf = 0) and pd.valor_total <> 0
and (pd.ncupom = 0 or (pd.ncupom is null)) and
(pd.num_nfeext <> 0 and (not pd.num_nfeext is null))
;

/* View: TP_RECFINCONTAB, Owner: SYSDBA */
CREATE VIEW TP_RECFINCONTAB (NOME_CTRL, NUM_NF, DATA_LANC, NCUPOM, N_NF_SERV, DATA_NF_SERV, VALOR_NF_SERV, NOME_CLIENTE, N_DOC, NOME_TERC, VALOR_DOC, HISTORICO_BAIXA, DATA_BAIXA, NRECIBO, COD_EMPRESA, SEQCREDITO, DATA_REAL_BX, DATA_VENC, TP_BAIXA) AS

/* direto dos creditos para o pedvenda */
select ctrl.nome_contabil,pd.num_nf,pd.data_nf,pd.ncupom,cast(pd.num_nfeext as integer),pd.data_nfext,pd.valor_nfext,
cr.nome_c,cr.n_doc_c,cr.nome_terc,cr.valor_c,(select first 1 l.historico_l from
lancamentos l where l.lote_ent = cr.lote_quit and l.codigo_emp = cr.codigo_emp order by l.lote_ent desc) as historico_baixa,
cr.datq_c,0 as nrecibo,cr.codigo_emp,cr.cod_cred,cr.data_baixa,cr.data_venc_c,coalesce(cr.tip_baixa,'') from controle_creditos cr
inner join pedvenda pd on rtrim(cr.tp_doc_v) = rtrim(pd.tipo) and cr.N_DOC_V =
pd.nped and cr.codigo_emp = pd.cod_empresa
inner join controles ctrl on cr.codigo_ctrl = ctrl.codigo_ctrl and cr.codigo_emp = ctrl.codigo_emp
where
cr.data_venc_c >= '01/01/2011' and (not cr.datq_c is null) and rtrim(cr.tp_doc_v) in ('OS','REQ')
union
select ctrl.nome_contabil,pd.num_nota_v,pd.data_ven,0 as ncupom,0 as num_nfeext,null as data_nfext,0 as valor_nfext,
cr.nome_c,cr.n_doc_c,cr.nome_terc,cr.valor_c,(select first 1 l.historico_l from
lancamentos l where l.lote_ent = cr.lote_quit and l.codigo_emp = cr.codigo_emp order by l.lote_ent desc) as historico_baixa,
cr.datq_c,0 as nrecibo,cr.codigo_emp,cr.cod_cred,cr.data_baixa,cr.data_venc_c,coalesce(cr.tip_baixa,'') from controle_creditos cr
inner join com_fat pd on cr.N_DOC_V = pd.n_comando and cr.codigo_emp = pd.cod_empresa
inner join controles ctrl on cr.codigo_ctrl = ctrl.codigo_ctrl and cr.codigo_emp = ctrl.codigo_emp
where
cr.data_venc_c >= '01/01/2011' and (not cr.datq_c is null) and rtrim(cr.tp_doc_v) = 'MOT'
and ((not pd.num_nota_v is null) or pd.num_nota_v <> 0)
union
select ctrl.nome_contabil,pd.num_nf,pd.data_nf,pd.ncupom,cast(pd.num_nfeext as integer),pd.data_nfext,pd.valor_nfext,
cr.nome_ch,cr.n_ch,cr.nome_terc,cr.valor_ch,(select first 1 l.historico_l from
lancamentos l where l.lote_ent = cr.lote_quit and l.codigo_emp = cr.codigo_emp order by l.lote_ent desc) as historico_baixa,
cr.datq_ch,0 as nrecibo,cr.codigo_emp,cr.codigo_ch,cr.datq_ch,cr.data_venc,coalesce(cr.tip_baixa,'') from controle_cheque cr
inner join pedvenda pd on rtrim(cr.tp_doc_v) = rtrim(pd.tipo) and cr.N_DOC_V =
pd.nped and cr.codigo_emp = pd.cod_empresa
inner join controles ctrl on cr.codigo_ctrl = ctrl.codigo_ctrl and cr.codigo_emp = ctrl.codigo_emp
where
cr.data_venc >= '01/01/2011' and (not cr.datq_ch is null) and rtrim(cr.tp_doc_v) in ('OS','REQ')
union
select ctrl.nome_contabil,pd.num_nota_v,pd.data_ven,0 as ncupom,0 as num_nfeext,null as data_nfext,0 as valor_nfext,
cr.nome_ch,cr.n_ch,cr.nome_terc,cr.valor_ch,(select first 1 l.historico_l from
lancamentos l where l.lote_ent = cr.lote_quit and l.codigo_emp = cr.codigo_emp order by l.lote_ent desc) as historico_baixa,
cr.datq_ch,0 as nrecibo,cr.codigo_emp,cr.codigo_ch,cr.datq_ch,cr.data_venc,coalesce(cr.tip_baixa,'') from controle_cheque cr
inner join com_fat pd on cr.N_DOC_V = pd.n_comando and cr.codigo_emp = pd.cod_empresa
inner join controles ctrl on cr.codigo_ctrl = ctrl.codigo_ctrl and cr.codigo_emp = ctrl.codigo_emp
where
cr.data_venc >= '01/01/2011' and (not cr.datq_ch is null) and rtrim(cr.tp_doc_v) = 'MOT'
and ((not pd.num_nota_v is null) or pd.num_nota_v <> 0)
union
select ctrl.nome_contabil,
case when (select first 1 pd.num_nf from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) is null then
(select first 1 pd.num_nota_v from hist_rec h inner join com_fat pd on
h.ndocant = pd.n_comando and h.cod_empresa = pd.cod_empresa and pd.situacao_nfe = 'Autorizada' where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc)
else
(select first 1 pd.num_nf from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) end  as num_nf,
case when (select first 1 pd.data_nf from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) is null then
(select first 1 pd.data_ven from hist_rec h inner join com_fat pd on
h.ndocant = pd.n_comando and h.cod_empresa = pd.cod_empresa and pd.situacao_nfe = 'Autorizada' where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) else
(select first 1 pd.data_nf from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) end as data_nf,
(select first 1 pd.ncupom from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) as ncupom,
cast((select first 1 pd.num_nfeext from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) as integer) as num_nfeext,
(select first 1 pd.data_nfext from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) as data_nfext,
(select first 1 pd.valor_nfext from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) as valor_nfext,
cr.nome_ch,cr.n_ch,cr.nome_terc,cr.valor_ch,(select first 1 l.historico_l from
lancamentos l where l.lote_ent = cr.lote_quit and l.codigo_emp = cr.codigo_emp order by l.lote_ent desc) as historico_baixa,cr.datq_ch,
cr.n_doc_v as nrecibo,cr.codigo_emp,cr.codigo_ch,cr.datq_ch,cr.data_venc,coalesce(cr.tip_baixa,'')
from controle_cheque cr inner join controles ctrl on cr.codigo_ctrl = ctrl.codigo_ctrl and cr.codigo_emp = ctrl.codigo_emp
where cr.data_venc >= '01/01/2011' and (not cr.datq_ch is null) and rtrim(cr.TP_DOC_V) = 'REC' and
(cr.tip_baixa is null or cr.tip_baixa = '')
union
select ctrl.nome_contabil,
case when (select first 1 pd.num_nf from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) is null then
(select first 1 pd.num_nota_v from hist_rec h inner join com_fat pd on
h.ndocant = pd.n_comando and h.cod_empresa = pd.cod_empresa and pd.situacao_nfe = 'Autorizada' where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc)
else
(select first 1 pd.num_nf from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) end  as num_nf,
case when (select first 1 pd.data_nf from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) is null then
(select first 1 pd.data_ven from hist_rec h inner join com_fat pd on
h.ndocant = pd.n_comando and h.cod_empresa = pd.cod_empresa and pd.situacao_nfe = 'Autorizada' where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) else
(select first 1 pd.data_nf from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) end as data_nf,
(select first 1 pd.ncupom from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) as ncupom,
cast((select first 1 pd.num_nfeext from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) as integer) as num_nfeext,
(select first 1 pd.data_nfext from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) as data_nfext,
(select first 1 pd.valor_nfext from hist_rec h inner join pedvenda pd on h.tp_doc_baixa = pd.tipo
and h.ndocant = pd.nped and h.cod_empresa = pd.cod_empresa where h.nrecibo = cr.N_DOC_V
and h.cod_empresa = cr.codigo_emp order by valor_baixa desc) as valor_nfext,
cr.nome_c,cr.n_doc_c,cr.nome_terc,cr.valor_c,(select first 1 l.historico_l from
lancamentos l where l.lote_ent = cr.lote_quit and l.codigo_emp = cr.codigo_emp order by l.lote_ent desc) as historico_baixa,cr.datq_c,
cr.n_doc_v as nrecibo,cr.codigo_emp,cr.cod_cred,cr.data_baixa,cr.data_venc_c,coalesce(cr.tip_baixa,'')
from controle_creditos cr inner join controles ctrl on cr.codigo_ctrl = ctrl.codigo_ctrl and cr.codigo_emp = ctrl.codigo_emp
where cr.data_venc_c >= '01/01/2011' and (not cr.datq_c is null) and rtrim(cr.TP_DOC_V) = 'REC'
and (cr.tip_baixa is null or cr.tip_baixa = '')
;

/* View: RECEBIMENTOS3, Owner: SYSDBA */
CREATE VIEW RECEBIMENTOS3 (COD_EMPRESA, COD_EMP_MULT, DATA, VALOR, MULT_MEDIA, PONDERACAO, TIPO) AS

SELECT (CASE WHEN(EMP.FINANCEIRO_UNIFICADO = 'S') THEN EMP.CODIGO_UNIFICADORA ELSE FP.COD_EMPRESA END) COD_EMPRESA,
FP.COD_EMPRESA,
FP.DATA_MOV, SUM(COALESCE(FP.VALORDOC, 0)) AS VALOR,
0 MULT_MEDIA, 0 PONDERACAO, 'VALORVENDA' TIPO FROM FORMPAGAMENTO FP
INNER JOIN EMPRESA EMP ON FP.COD_EMPRESA = EMP.COD_EMPRESA
WHERE (TIPDOC = 'N' OR (DATA_VENC-DATA_MOV) <= 5)
AND TPDOCS <> 'PRE'
GROUP BY 1, 2, 3
UNION
SELECT (CASE WHEN(EMP.FINANCEIRO_UNIFICADO = 'S') THEN EMP.CODIGO_UNIFICADORA ELSE FP.COD_EMPRESA END) COD_EMPRESA,
FP.COD_EMPRESA,
FP.DATA_MOV, SUM(COALESCE(FP.VALORDOC, 0)) AS VALORVENDA,
SUM((FP.DATA_VENC-FP.DATA_MOV) * COALESCE(FP.VALORDOC, 0)) AS MULT_MEDIA, 0 PONDERACAO, 'VALORVENDA1' FROM FORMPAGAMENTO FP
INNER JOIN EMPRESA EMP ON FP.COD_EMPRESA = EMP.COD_EMPRESA
WHERE (FP.TIPDOC <> 'N' AND (FP.DATA_VENC-FP.DATA_MOV) > 5)
AND FP.TPDOCS <> 'PRE'
GROUP BY 1, 2, 3
UNION
SELECT
CRED.CODIGO_EMP,
CRED.COD_EMP_MULT, CRED.DATA_REC,
SUM(COALESCE(CRED.VALOR,0)) AS VALORVENDA,
SUM((CRED.DATA_VENC-CRED.DATA_REC) * COALESCE(CRED.VALOR, 0)) AS MULT_MEDIA,
0 PONDERACAO,  'VALORVENDA2' FROM CRED_JUR CRED
INNER JOIN CONTROLES CTRL ON CRED.CONTROLE = CTRL.CODIGO_CTRL AND CRED.CODIGO_EMP = CTRL.CODIGO_EMP
WHERE (CRED.DATA_VENC-CRED.DATA_REC) > 5 AND COALESCE(CTRL.ENTRA_PMV,'') <> 'N'
GROUP BY 1, 2, 3
UNION
SELECT
VND.COD_EMPRESA,
VND.COD_EMP_MULT,
VND.DATA_VENDA, SUM(COALESCE(VND.VALOR_VENDA, 0)) AS VALORVENDA, 0 MULT_MEDIA, 0 PONDERACAO,
'VENDAG' FROM VENDAS_GERAIS VND
LEFT JOIN EMPRESA EMP ON VND.COD_EMPRESA = EMP.COD_EMPRESA
WHERE VENDA = 'S'
GROUP BY 1, 2, 3
UNION
SELECT (CASE WHEN(EMP.FINANCEIRO_UNIFICADO = 'S') THEN EMP.CODIGO_UNIFICADORA ELSE CR.CODIGO_EMP END) COD_EMPRESA,
CR.COD_EMP_MULT, CR.DATQ_C, SUM(COALESCE(CR.VALOR_C, 0)) AS VALORATRASO,
(SUM((CR.DATQ_C-CR.DATA_VENC_C))/COUNT(*)) AS MULT_MEDIA,
((SUM((CR.DATQ_C-CR.DATA_VENC_C))/COUNT(*)) * SUM(COALESCE(CR.VALOR_C, 0))) AS PONDERACAO,
'PONDERACAO' FROM CONTROLE_CREDITOS CR
LEFT JOIN EMPRESA EMP ON CR.CODIGO_CTRL = EMP.COD_EMPRESA
INNER JOIN CONTROLES CTRL ON CR.CODIGO_CTRL = CTRL.CODIGO_CTRL AND CR.CODIGO_EMP = CTRL.CODIGO_EMP
WHERE (CR.DATQ_C-CR.DATA_VENC_C) > 1
AND CTRL.COMPSALDO = 'S'
GROUP BY 1, 2, 3
;

/* View: RECEBIMENTOS, Owner: SYSDBA */
CREATE VIEW RECEBIMENTOS (COD_EMPRESA, COD_EMP_ORIG, COD_EMP_MULT, COD_CLIENTE, NOME_CLIENTE, CPFCGC_CLIENTE, TP_REL, TP_DOC, TP_RECEBIMENTO, TP_RECEBIMENTO2, ORDEM, COD_TIPO, TIPO, COD_CRED, NUM_DOC, NUM_DOC2, DATA_DOC, DATA_CONF, VALOR_A_RECEBER, OBS_CXL, LOTEREC, OP_CXL, COD_US, DATA_MOV, HISTORICO, VALOR_PAGO, DATA_VENC, TERCEIROS, CODIGO_CTRL, NOME_CTRL, NUM_RECIBO, VALOR_RECIBO, NCUPOM, NUM_NF, PARCELA, SEQID, SEQID2, VENDA, TIPV, TIPO_DOC, QTDE_PREST) AS

-- VIEW EXIBE OS RECEBIMENTOS DAS VENDAS (REQUISICAO, ORDEM DE SERVICO, COMANDOS), RECIBO ANTECIPADOS E  CREDIARIO (CREDITOS/CHEQUES)
-- RELATORIO "RECEBIMENTO FINANCEIRO"
    --- REQ, OS
    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else rq.cod_empresa end) cod_empresa,
    rq.cod_empresa,
    rq.cod_empresa,
    coalesce(rq.cod_cliente, 0) cod_cliente, cl.nome_cliente, cl.cpfcgc,
    'SAIDAS' tp_rel, rq.tipo tp_doc, 'DIRETO' tp_recebimento, 'DIRETO' tp_recebimento2,
    1 ordem, 0 cod_tipo, rq.tipo, 0 cod_cred, coalesce(rq.nped, 0) as Num_doc, coalesce(fp.ndoc, coalesce(rq.nped, 0), 0) Num_doc2, rq.data_ped as data_doc,
    rq.data_fech as data_Conf, coalesce(rq.valor_total, 0) as valor_total, rq.obs_cxl_rq, rq.nped as loterec,
    coalesce(rq.op_cxl, 0) op_cxl, rq.cod_vendedor,
    fp.data_mov, fp.historico, coalesce(fp.valordoc, 0) valordoc, fp.data_venc, fp.terceiros,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    case when (rec.num_rec_dep <> '') then rec.num_rec_dep else coalesce(fp.rec_numvend,0) end as num_recibo, 0 as valor_recibo,
    coalesce(rq.num_nfce, 0) ncupom, coalesce(rq.num_nf, 0) num_nf,
    case when (fp.nrequisicao > 0) then coalesce(fp.nparcela, 0) else 0 end nparcela,
    coalesce(fp.seqform, rq.nped), coalesce(fp.seqform, rq.nped), coalesce(tp.venda, 'S') venda,
    case when(rq.tipo = 'REQ') then tp.sigla else tp.tipo_os end tipv, rq.tipo as tipo_doc,
    1 qtde_prest

    from pedvenda rq
    left join empresa emp on rq.cod_empresa = emp.cod_empresa
    left join tipo_vendas tp on tp.tipo = rq.tipo and (tp.sigla = rq.tipv or (tp.tipo_os = rq.tipo_os))
    left join clientes cl on cl.cod_cliente = rq.cod_cliente and cl.cod_empresa = rq.cod_empresa
    left join formpagamento fp on fp.nrequisicao = rq.nped and fp.tpdocs = rq.tipo and fp.cod_empresa = rq.cod_empresa and fp.recibo is null
    left join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where coalesce(trim(rq.status_ped), '') = 'FECHADA' and rq.tipo in ('REQ', 'OS')

    union
    
    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else rq.cod_empresa end) cod_empresa,
    rq.cod_empresa,
    rq.cod_empresa,
    coalesce(rq.cod_cliente, 0) cod_cliente, cl.nome_cliente, cl.cpfcgc,
    'SAIDAS' tp_rel, rq.tipo tp_doc, 'RECIBO' tp_recebimento, 'RECIBO' tp_recebimento2, 1 ordem, 0 cod_tipo, rq.tipo,
    0 cod_cred, coalesce(rq.nped, 0) as Num_doc, coalesce(fp.ndoc, coalesce(rq.nped, 0), 0) Num_doc2, rq.data_ped as data_doc,
    rq.data_fech as data_Conf, coalesce(rq.valor_total, 0) as valor_total, rq.obs_cxl_rq, rq.nped as loterec,
    coalesce(rq.op_cxl, 0) op_cxl, rq.cod_vendedor,
    fp.data_mov, fp.historico,  coalesce(fp.valordoc, 0) valordoc,
    fp.data_venc, fp.terceiros,
    case when (select first 1 ctrl.nome_ctrl from controles ctrl
    inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
    where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend ='REC' order by rc.valordoc asc) is null then
        0
    else
       (select first 1 ctrl.codigo_ctrl from controles ctrl
        inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
        where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend ='REC' order by rc.valordoc asc)
    end as codigo_ctrl,
    case when (select first 1 ctrl.nome_ctrl from controles ctrl
    inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
    where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend ='REC' order by rc.valordoc asc) is null then
        'SEM FORMA'
    else
        (select first 1 ctrl.nome_ctrl from controles ctrl
        inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
        where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend ='REC' order by rc.valordoc asc)
    end as nome_ctrl,
    case when (rec.num_rec_dep <> '') then rec.num_rec_dep else coalesce(fp.rec_numvend,0) end num_recibo,
    coalesce((select sum(rc.valor_orig) from recibos rc where rc.nrecibo = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa), 0) as valor_recibo,
    coalesce(rq.num_nfce, 0) ncupom, coalesce(rq.num_nf, 0) num_nf,
    case when (fp.nrequisicao > 0) then coalesce(fp.nparcela, 0) else 0 end nparcela,
    coalesce(fp.seqform, rq.nped), coalesce(fp.seqform, rq.nped), coalesce(tp.venda, 'S') venda,
    case when(rq.tipo = 'REQ') then tp.sigla else tp.tipo_os end tipv, rq.tipo as tipo_doc,
    1 qtde_prest

    from pedvenda rq
    left join empresa emp on rq.cod_empresa = emp.cod_empresa
    left join tipo_vendas tp on tp.tipo = rq.tipo and (tp.sigla = rq.tipv or (tp.tipo_os = rq.tipo_os))
    left join clientes cl on cl.cod_cliente = rq.cod_cliente and cl.cod_empresa = rq.cod_empresa
    inner join formpagamento fp on fp.nrequisicao = rq.nped and fp.tpdocs = rq.tipo and fp.cod_empresa = rq.cod_empresa and (not fp.recibo is null)
    left join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa
    where coalesce(trim(rq.status_ped), '') = 'FECHADA' and rq.tipo in ('REQ', 'OS')
    
    union
    
    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else rq.cod_empresa end) cod_empresa,
    rq.cod_empresa,
    rq.cod_empresa,
    coalesce(rq.cod_cliente, 0) cod_cliente, cl.nome_cliente, cl.cpfcgc,
    'SAIDAS' tp_rel, rq.tipo tp_doc, 'TROCO' tp_recebimento, 'TROCO' tp_recebimento2, 1 ordem, 0 cod_tipo, rq.tipo,
    0 cod_cred, coalesce(rq.nped, 0) as Num_doc, coalesce(fp.ndoc, coalesce(rq.nped, 0), 0) Num_doc2, rq.data_ped as data_doc,
    rq.data_fech as data_Conf, coalesce(rq.valor_total, 0) as valor_total, rq.obs_cxl_rq, rq.nped as loterec,
    coalesce(rq.op_cxl, 0) op_cxl, rq.cod_vendedor,
    fp.data_mov, fp.historico, coalesce(fp.valordoc, 0) valordoc, fp.data_venc, fp.terceiros,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    case when (rec.num_rec_dep <> '') then rec.num_rec_dep else coalesce(fp.rec_numvend,0) end num_recibo, 0 as valor_recibo,
    coalesce(rq.num_nfce, 0) ncupom, coalesce(rq.num_nf, 0) num_nf,
    case when (fp.nrequisicao > 0) then coalesce(fp.nparcela, 0) else 0 end nparcela,
    coalesce(fp.seqform, rq.nped), coalesce(fp.seqform, rq.nped),  coalesce(tp.venda, 'S') venda,
    case when(rq.tipo = 'REQ') then tp.sigla else tp.tipo_os end tipv, rq.tipo as tipo_doc,
    1 qtde_prest

    from pedvenda rq
    left join empresa emp on rq.cod_empresa = emp.cod_empresa
    left join tipo_vendas tp on tp.tipo = rq.tipo and (tp.sigla = rq.tipv or (tp.tipo_os = rq.tipo_os))
    left join clientes cl on cl.cod_cliente = rq.cod_cliente and cl.cod_empresa = rq.cod_empresa
    inner join formpagamento fp on fp.rec_numvend = rq.nped and fp.rec_tipvend = rq.tipo and fp.cod_empresa = rq.cod_empresa and fp.tpdocs = 'TRC'
    left join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where coalesce(trim(rq.status_ped), '') = 'FECHADA' and rq.tipo in ('REQ', 'OS')
    
    union
    
    --- CF
    
    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else mt.cod_empresa end) cod_empresa,
    mt.cod_empresa,
    mt.cod_empresa,
    coalesce(mt.clientes_v, 0) clientes_v, cl.nome_cliente, cl.cpfcgc,
    'SAIDAS' tp_rel, 'MOT' tp_doc, 'DIRETO' tp_recebimento, 'DIRETO' tp_recebimento2, 1 ordem, 0 cod_tipo, 'MOT' as tipo,
    0 cod_cred, coalesce(mt.n_comando, 0) as Num_doc, coalesce(fp.ndoc, coalesce(mt.n_comando, 0), 0) Num_doc2, mt.data_ven as Data_Doc,
    mt.data_fech as Data_Conf, coalesce(mt.valor_a_rec, 0) as valor_total, ' ' as obs_cxl_rq, mt.n_comando as loterec,
    coalesce(mt.op_cxl, 0) op_cxl, mt.covend_v,
    fp.data_mov, fp.historico, coalesce(fp.valordoc, 0), fp.data_venc, fp.terceiros,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    case when (rec.num_rec_dep <> '') then rec.num_rec_dep else coalesce(fp.rec_numvend,0) end num_recibo, 0 as valor_recibo,
    0 ncupom, coalesce(mt.num_nota_v, 0) num_nf,
    case when (fp.nrequisicao > 0) then coalesce(fp.nparcela, 0) else 0 end nparcela,
    coalesce(fp.seqform, mt.n_comando), coalesce(fp.seqform, mt.n_comando), coalesce(tp.venda, 'S') venda,
    tp.tipo_os, 'MOT' as tipo_doc, 1 qtde_prest from com_fat mt
    left join empresa emp on mt.cod_empresa = emp.cod_empresa
    left join tipo_vendas tp on tp.tipo = 'VEI' and tp.tipo_os = mt.tipo_v
    left join clientes cl on cl.cod_cliente = mt.clientes_v and cl.cod_empresa = mt.cod_empresa
    left join formpagamento fp on fp.nrequisicao = mt.n_comando and fp.tpdocs = 'MOT' and fp.cod_empresa = mt.cod_empresa  and fp.recibo is null
    left join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where (coalesce(trim(mt.status_v), '') = 'FECHADO') and mt.natureza = 'S'

    union
    
    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else mt.cod_empresa end) cod_empresa,
    mt.cod_empresa,
    mt.cod_empresa,
    coalesce(mt.clientes_v, 0) clientes_v, cl.nome_cliente, cl.cpfcgc,
    'SAIDAS' tp_rel, 'MOT' tp_doc, 'RECIBO' tp_recebimento, 'RECIBO' tp_recebimento2, 1 ordem, 0 cod_tipo, 'MOT' as tipo,
    0 cod_cred, coalesce(mt.n_comando, 0) as Num_doc, coalesce(fp.ndoc, coalesce(mt.n_comando, 0), 0) Num_doc2, mt.data_ven as Data_Doc,
    mt.data_fech as Data_Conf, coalesce(mt.valor_a_rec, 0) as valor_total, ' ' as obs_cxl_rq, mt.n_comando as loterec,
    coalesce(mt.op_cxl, 0) op_cxl, mt.covend_v,
    fp.data_mov, fp.historico, coalesce(fp.valordoc, 0) valordoc,
    fp.data_venc, fp.terceiros,
    case when (select first 1 ctrl.nome_ctrl from controles ctrl
    inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
    where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend = 'REC' order by rc.valordoc asc) is null then
        0
    else
       (select first 1 ctrl.codigo_ctrl from controles ctrl
       inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
       where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend = 'REC' order by rc.valordoc asc)
    end as codigo_ctrl,
    case when (select first 1 ctrl.nome_ctrl from controles ctrl
    inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
    where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend = 'REC' order by rc.valordoc asc) is null then
        'SEM FORMA'
    else
       (select first 1 ctrl.nome_ctrl from controles ctrl
        inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
        where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend = 'REC' order by rc.valordoc asc)
    end as  nome_ctrl,
    case when (rec.num_rec_dep <> '') then rec.num_rec_dep else coalesce(fp.rec_numvend,0) end num_recibo,
    coalesce((select sum(rc.valor_orig) from recibos rc where rc.nrecibo = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa), 0) as valor_recibo,
    0 ncupom, coalesce(mt.num_nota_v, 0) num_nf,
    case when (fp.nrequisicao > 0) then coalesce(fp.nparcela, 0) else 0 end nparcela,
    coalesce(fp.seqform, mt.n_comando), coalesce(fp.seqform, mt.n_comando),  coalesce(tp.venda, 'S') venda,
    tp.tipo_os, 'MOT' as tipo_doc, 1 qtde_prest from com_fat mt
    left join empresa emp on mt.cod_empresa = emp.cod_empresa
    left join tipo_vendas tp on tp.tipo = 'VEI' and tp.tipo_os = mt.tipo_v
    left join clientes cl on cl.cod_cliente = mt.clientes_v and cl.cod_empresa = mt.cod_empresa
    inner join formpagamento fp on fp.nrequisicao = mt.n_comando and fp.tpdocs = 'MOT' and fp.cod_empresa = mt.cod_empresa and (not fp.recibo is null)
    left join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where (coalesce(trim(mt.status_v), '') = 'FECHADO') and mt.natureza = 'S'
    
    union
    
    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else mt.cod_empresa end) cod_empresa,
    mt.cod_empresa,
    mt.cod_empresa,
    coalesce(mt.clientes_v, 0) clientes_v, cl.nome_cliente, cl.cpfcgc,
    'SAIDAS' tp_rel, 'MOT' tp_doc, 'TROCO' tp_recebimento, 'TROCO' tp_recebimento2, 1 ordem, 0 cod_tipo, 'MOT' as tipo,
    0 cod_cred, coalesce(mt.n_comando, 0) as Num_doc, coalesce(fp.ndoc, coalesce(mt.n_comando, 0), 0) Num_doc2, mt.data_ven as Data_Doc,
    mt.data_fech as Data_Conf, coalesce(mt.valor_a_rec, 0) as valor_total, ' ' as obs_cxl_rq, mt.n_comando as loterec,
    coalesce(mt.op_cxl, 0) op_cxl, mt.covend_v,
    fp.data_mov, fp.historico, coalesce(fp.valordoc, 0), fp.data_venc, fp.terceiros,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    case when (rec.num_rec_dep <> '') then rec.num_rec_dep else coalesce(fp.rec_numvend,0) end num_recibo, 0 as valor_recibo,
    0 ncupom, coalesce(mt.num_nota_v, 0) num_nf,
    case when (fp.nrequisicao > 0) then coalesce(fp.nparcela, 0) else 0 end nparcela,
    coalesce(fp.seqform, mt.n_comando), coalesce(fp.seqform, mt.n_comando),  coalesce(tp.venda, 'S') venda,
    tp.tipo_os, 'MOT' as tipo_doc, 1 qtde_prest from com_fat mt
    left join empresa emp on mt.cod_empresa = emp.cod_empresa
    left join tipo_vendas tp on tp.tipo = 'VEI' and tp.tipo_os = mt.tipo_v
    left join clientes cl on cl.cod_cliente = mt.clientes_v and cl.cod_empresa = mt.cod_empresa
    inner join formpagamento fp on fp.rec_numvend = mt.n_comando and fp.rec_tipvend = 'MOT' and fp.cod_empresa = mt.cod_empresa and fp.tpdocs = 'TRC'
    left join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where (coalesce(trim(mt.status_v), '') = 'FECHADO') and mt.natureza = 'S'

    -- Cred

    union
    
    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pr.codigo_emp end) cod_empresa,
    pr.codigo_emp,
    pr.cod_emp_mult,
    coalesce(pr.cod_cliente, 0) cod_cliente,
    case when (cl.nome_cliente is null) then pr.nome_c else cl.nome_cliente end nome_cliente,
    case when (cl.cpfcgc is null) then pr.cpfcgc else cl.cpfcgc end cpfcgc,
    'CREDIARIO' tp_rel, 'CC' tp_doc, 'CREDIARIO' tp_recebimento,
    coalesce((case
        when (((select count(*) from hist_rec hist where hist.lote_quit = pr.lote_quit and hist.cod_empresa = pr.codigo_emp) > 0)
            and ((l.historico_l like '%RECIBOS ATENCIPADOS%') or (l.historico_l like '%RECIBOS ANTECIPADOS%'))) then
                'RECIBO'
        when coalesce(pr.tip_baixa, '') = 'D' then
                'DEVOLUCAO'
        else
                'DIRETO'
        end),
    'DIRETO') tp_recebimento2, 3 ordem,
    case when (ctr1.codigo_ctrl is null) then 0 else ctr1.codigo_ctrl end cod_tipo,
    case when (ctr1.nome_ctrl is null) then pr.tipo_doc_c else ctr1.nome_ctrl end tipo,
    coalesce(pr.seq_bxcred, 0) cod_cred, coalesce(pr.n_doc_c, 0) Num_doc, coalesce(l.ndoc_l, coalesce(pr.n_doc_c, 0)) Num_doc2, pr.data_venc_c as Data_Doc,
    pr.datq_c as Data_Conf,
    coalesce(pr.valor_quitado, 0) as valor_total, ' ' as obs_cxl_rq, coalesce(pr.lote_quit, pr.seq_bxcred) as loterec,
    coalesce(pr.op_cxl, 0) op_cxl, pr.codigo_vend, l.data, l.historico_l,

    case when(l.tipo_l = 'S') then
           (coalesce(l.valor_l, 0) * -1)
         else
           case when (coalesce(l.valor_l, 0)) <= 0 then
                  case when coalesce(pr.tip_baixa, '') = 'D' then
                        coalesce(pr.valor_quitado, 0)
                       else
                         coalesce(l.valor_l, 0)
                  end
                else
                  coalesce(l.valor_l, 0)
           end
    end valor_pago,

    l.data, ' ' terceiros,

    coalesce((case when (((select count(*) from hist_rec hist where hist.lote_quit = pr.lote_quit and hist.cod_empresa = pr.codigo_emp) > 0)
                    and ((l.historico_l like '%RECIBOS ATENCIPADOS%') or (l.historico_l like '%RECIBOS ANTECIPADOS%'))) then
                     case when (l.tipo_l = 'S') then
                            0
                          else
                            case when (ctr.codigo_ctrl is null) then 0 else ctr.codigo_ctrl end
                     end
                   else
                     case when ctr.codigo_ctrl is null then
                            case when coalesce(pr.tip_baixa, '') = 'D' then
                                   case when (ctr1.codigo_ctrl is null) then 0 else ctr1.codigo_ctrl end
                                 else
                                   0
                            end
                          else
                            ctr.codigo_ctrl
                     end
              end),
    0) codigo_ctrl,
    
    coalesce((case when (((select count(*) from hist_rec hist where hist.lote_quit = pr.lote_quit and hist.cod_empresa = pr.codigo_emp) > 0)
                    and ((l.historico_l like '%RECIBOS ATENCIPADOS%') or (l.historico_l like '%RECIBOS ANTECIPADOS%'))) then
                     case when (l.tipo_l = 'S') then
                            'SEM FORMA'
                          else
                            case when (ctr.nome_ctrl is null) then 0 else ctr.nome_ctrl end
                     end
                   else
                     case when ctr.nome_ctrl is null then
                            case when coalesce(pr.tip_baixa, '') = 'D' then
                                   case when (ctr1.nome_ctrl is null) then 0 else ctr1.nome_ctrl end
                                 else
                                   'SEM FORMA'
                            end
                          else
                            ctr.nome_ctrl
                     end
              end),
    'SEM FORMA') nome_ctrl,

    0 as num_recibo, 0 as valor_recibo,

    coalesce((
    case when(trim(pr.tp_doc_v) = 'MOT') then
            0
         else
            (select coalesce(pd.num_nfce, 0) from pedvenda pd        
             where pd.nped = pr.n_doc_v and pd.tipo = pr.tp_doc_v and pd.cod_empresa = pr.codigo_emp)
    end), 0) ncupom,

    coalesce((case when(trim(pr.tp_doc_v) = 'MOT') then
        (select coalesce(cf.num_nota_v, 0) from com_fat cf
        where cf.n_comando = pr.n_doc_v and cf.cod_empresa = pr.codigo_emp)
    else
        (select coalesce(pd.num_nf, 0) from pedvenda pd
        where pd.nped = pr.n_doc_v and pd.tipo = pr.tp_doc_v and pd.cod_empresa = pr.codigo_emp)
    end), 0) num_nf,


    case when(cc.cod_cred > 0) then coalesce(cc.nparcela, 0) else 0 end nparcela, pr.seq_bxcred, coalesce(l.cod_lanc, pr.seq_bxcred),

    coalesce((case when(trim(pr.tp_doc_v) = 'MOT') then
    (select coalesce(tp.venda, 'S') venda from com_fat cf left join tipo_vendas tp on tp.tipo = 'VEI' and tp.tipo_os = cf.tipo_v
    where cf.n_comando = pr.n_doc_v and cf.cod_empresa = pr.codigo_emp)
    else (select coalesce(tp.venda, 'S') venda from pedvenda pd left join tipo_vendas tp on tp.tipo = pd.tipo and (tp.sigla = pd.tipv or (tp.tipo_os = pd.tipo_os))
    where pd.nped = pr.n_doc_v and pd.tipo = pr.tp_doc_v and pd.cod_empresa = pr.codigo_emp)
    end), 'S') venda,

    case when(trim(pr.tp_doc_v) = 'MOT') then
    (select tp.tipo_os from com_fat cf left join tipo_vendas tp on tp.tipo = 'VEI' and tp.tipo_os = cf.tipo_v
    where cf.n_comando = pr.n_doc_v and cf.cod_empresa = pr.codigo_emp)
    when(trim(pr.tp_doc_v) = 'OS') then
    (select tp.tipo_os from pedvenda pd left join tipo_vendas tp on tp.tipo = pd.tipo and (tp.sigla = pd.tipv or (tp.tipo_os = pd.tipo_os))
    where pd.nped = pr.n_doc_v and pd.tipo = pr.tp_doc_v and pd.cod_empresa = pr.codigo_emp)
    else
    (select tp.sigla from pedvenda pd left join tipo_vendas tp on tp.tipo = pd.tipo and (tp.sigla = pd.tipv or (tp.tipo_os = pd.tipo_os))
    where pd.nped = pr.n_doc_v and pd.tipo = pr.tp_doc_v and pd.cod_empresa = pr.codigo_emp)
    end tipv,
    pr.tp_doc_v as tipo_doc,
    coalesce((case when ((select count(*) from baixa_creditos bc
                          where bc.lote_quit = pr.lote_quit
                          and bc.datq_c = iif(emp.financeiro_unificado = 'S', pr.datq_c, bc.datq_c)
                          and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, bc.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp)) = 0) then
        1
    else
        (select count(*) from baixa_creditos bc
         where bc.lote_quit = pr.lote_quit
         and bc.datq_c = iif(emp.financeiro_unificado = 'S', pr.datq_c, bc.datq_c)
         and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, bc.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp))
    end), 1) qtde_prest

    from baixa_creditos pr
    left join empresa emp on pr.codigo_emp = emp.cod_empresa
    left join clientes cl on cl.cod_cliente = pr.cod_cliente and cl.cod_empresa = pr.cod_emp_mult
    left join controle_creditos cc on cc.cod_cred = pr.cod_cred and cc.codigo_emp = pr.codigo_emp
    left join lancamentos l on
        l.lote_ent = pr.lote_quit
        and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, l.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp)
        and l.data = pr.datq_c
        and l.tipo_l = 'E'
    left join CONTROLES ctr on ctr.codigo_ctrl = l.codigo_ctrl and ctr.codigo_emp = l.codigo_emp
    left join CONTROLES ctr1 on ctr1.codigo_ctrl = pr.codigo_ctrl and ctr1.codigo_emp = pr.codigo_emp
    where coalesce(pr.tip_baixa, '') <> 'C' and pr.datq_c is not null

    union

    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pr.codigo_emp end) cod_empresa,
    pr.codigo_emp,
    pr.cod_emp_mult,
    coalesce(pr.cod_cliente, 0) cod_cliente,
    case when (cl.nome_cliente is null) then pr.nome_c else cl.nome_cliente end nome_cliente,
    case when (cl.cpfcgc is null) then pr.cpfcgc else cl.cpfcgc end cpfcgc_cliente,
    'CREDIARIO' tp_rel, 'CC' tp_doc, 'CREDIARIO' tp_recebimento, 'DIRETO' tp_recebimento2, 3 ordem,
    case when (ctr1.codigo_ctrl is null) then 0 else ctr1.codigo_ctrl end cod_tipo,
    case when (ctr1.nome_ctrl is null) then pr.tipo_doc_c else ctr1.nome_ctrl end tipo,
    coalesce(pr.seq_bxcred, 0) cod_cred, coalesce(pr.n_doc_c, 0) Num_doc, coalesce(pr.lote, 0) Num_doc2, pr.data_venc_c as Data_Doc,
    pr.datq_c as Data_Conf,
    coalesce(pr.valor_quitado, 0) as valor_total, ' ' as obs_cxl_rq, coalesce(pr.lote_quit, pr.seq_bxcred) as loterec,
    coalesce(pr.op_cxl, 0) op_cxl, pr.codigo_vend,
    pr.datq_c, ('LOTE CTP ' || pr.lote) historico_ctp,
    coalesce(pr.valor_quitado, 0) valor_pago,
    pr.datq_c, ' ' terceiros,
    999999 codigo_ctrl, 'CONTAS A PAGAR' nome_ctrl,
    0 as num_recibo, 0 as valor_recibo,

    coalesce((
    case when(trim(pr.tp_doc_v) = 'MOT') then
            0
         else
            (select coalesce(pd.num_nfce, 0) from pedvenda pd
             where pd.nped = pr.n_doc_v and pd.tipo = pr.tp_doc_v and pd.cod_empresa = pr.codigo_emp)
    end), 0) ncupom,

    coalesce((case when(trim(pr.tp_doc_v) = 'MOT') then
        (select coalesce(cf.num_nota_v, 0) from com_fat cf
        where cf.n_comando = pr.n_doc_v and cf.cod_empresa = pr.codigo_emp)
    else
        (select coalesce(pd.num_nf, 0) from pedvenda pd
        where pd.nped = pr.n_doc_v and pd.tipo = pr.tp_doc_v and pd.cod_empresa = pr.codigo_emp)
    end), 0) num_nf,


    case when(cc.cod_cred > 0) then coalesce(cc.nparcela, 0) else 0 end nparcela, pr.seq_bxcred, coalesce(pr.seq_bxcred, 0),

    coalesce((case when(trim(pr.tp_doc_v) = 'MOT') then
    (select coalesce(tp.venda, 'S') venda from com_fat cf left join tipo_vendas tp on tp.tipo = 'VEI' and tp.tipo_os = cf.tipo_v
    where cf.n_comando = pr.n_doc_v and cf.cod_empresa = pr.codigo_emp)
    else (select coalesce(tp.venda, 'S') venda from pedvenda pd left join tipo_vendas tp on tp.tipo = pd.tipo and (tp.sigla = pd.tipv or (tp.tipo_os = pd.tipo_os))
    where pd.nped = pr.n_doc_v and pd.tipo = pr.tp_doc_v and pd.cod_empresa = pr.codigo_emp)
    end), 'S') venda,

    case when(trim(pr.tp_doc_v) = 'MOT') then
    (select tp.tipo_os from com_fat cf left join tipo_vendas tp on tp.tipo = 'VEI' and tp.tipo_os = cf.tipo_v
    where cf.n_comando = pr.n_doc_v and cf.cod_empresa = pr.codigo_emp)
    when(trim(pr.tp_doc_v) = 'OS') then
    (select tp.tipo_os from pedvenda pd left join tipo_vendas tp on tp.tipo = pd.tipo and (tp.sigla = pd.tipv or (tp.tipo_os = pd.tipo_os))
    where pd.nped = pr.n_doc_v and pd.tipo = pr.tp_doc_v and pd.cod_empresa = pr.codigo_emp)
    else
    (select tp.sigla from pedvenda pd left join tipo_vendas tp on tp.tipo = pd.tipo and (tp.sigla = pd.tipv or (tp.tipo_os = pd.tipo_os))
    where pd.nped = pr.n_doc_v and pd.tipo = pr.tp_doc_v and pd.cod_empresa = pr.codigo_emp)
    end tipv,
    pr.tp_doc_v as tipo_doc,
    coalesce((case when ((select count(*) from baixa_creditos bc
                          where bc.lote_quit = pr.lote_quit
                          and bc.datq_c = iif(emp.financeiro_unificado = 'S', pr.datq_c, bc.datq_c)
                          and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, bc.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp)) = 0) then
        1
    else
        (select count(*) from baixa_creditos bc
         where bc.lote_quit = pr.lote_quit
         and bc.datq_c = iif(emp.financeiro_unificado = 'S', pr.datq_c, bc.datq_c)
         and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, bc.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp))
    end), 1) qtde_prest

    from baixa_creditos pr
    left join empresa emp on pr.codigo_emp = emp.cod_empresa
    left join clientes cl on cl.cod_cliente = pr.cod_cliente and cl.cod_empresa = pr.cod_emp_mult
    left join controle_creditos cc on cc.cod_cred = pr.cod_cred and cc.codigo_emp = pr.codigo_emp
    left join CONTROLES ctr1 on ctr1.codigo_ctrl = pr.codigo_ctrl and ctr1.codigo_emp = pr.codigo_emp
    where pr.tip_baixa = 'C' and pr.datq_c is not null

