    rq.data_rec as data_Conf, coalesce(rq.valor_orig, 0) as valor_total,
    (trim(rq.referencia1) || ascii_char(13) || ascii_char(10) ||
    trim(rq.referencia2) || ascii_char(13) || ascii_char(10) ||
    trim(rq.referencia3) || ascii_char(13) || ascii_char(10) ||
    trim(rq.referencia4)) referencia, rq.nrecibo as loterec,
    coalesce(rq.op_cxl, 0) op_cxl, rq.cod_us,
    fp.data_mov, fp.historico, coalesce(fp.valordoc, 0) valordoc, fp.data_venc, fp.terceiros,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    case when (rq.num_rec_dep <> '') then rq.num_rec_dep else coalesce(fp.rec_numvend,0) end as num_recibo, 0 as valor_recibo,
    0 ncupom, 0 num_nf,
    case when (fp.nrequisicao > 0) then coalesce(fp.nparcela, 0) else 0 end nparcela,
    coalesce(fp.seqform, rq.nrecibo), coalesce(fp.seqform, rq.nrecibo), 'N' venda, '' tipv, 'REC' as tipo_doc,
    1 qtde_prest
    
    from recibos rq
    left join empresa emp on rq.cod_empresa = emp.cod_empresa
    left join clientes cl on cl.cod_cliente = rq.cod_devedor and cl.cod_empresa = rq.cod_empresa
    inner join formpagamento fp on fp.rec_numvend = rq.nrecibo and fp.rec_tipvend = 'REC' and fp.cod_empresa = rq.cod_empresa and fp.tpdocs = 'TRC'
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where rq.recant = 'S'
;

/* View: VW_CONCILIACAO_CRED_DIV_DTVALOR, Owner: SYSDBA */
CREATE VIEW VW_CONCILIACAO_CRED_DIV_DTVALOR (DATA, DATE_, REQUEST_DATE, EFFECTED_DATE, PAYMENT_DATE, BANK_SHIPPING_DATE, ARQUIVO, DATA_ARQUIVO, ID, COD_CRED, CODIGO_EMP, COD_EMP_MULT, DATA_REC_C, DATA_VENC_C, N_DOCNSU_ADM, N_AUT_CART, NPARCELA, QTDE_PARC, CODIGO_CTRL, NOME_CTRL, N_DOC_V, N_DOC_C, TP_DOC_V, VALOR_C, VALOR_LIQUIDO, VALOR_ORIGINAL, DATQ_C, STATUS_C, TAXA_CRED, COD_CLIENTE, NOME_CLIENTE, COD_TERMINAL_ADM, DESC_TERM_ADM, COD_ADM, DESCRICAO_ADM, COD_BANDEIRA_ADM, DESC_BANCEIRA_ADM, NOME_C, IDENTIFICACAO_EMP) AS

select case when (cf.payment_date is not null) then cf.payment_date else cf.date_ end data,
cf.date_, cf.request_date, cf.effected_date, cf.payment_date, cf.bank_shipping_date,
cf.arquivo, cf.data_arquivo,
cf.id, cc.cod_cred, cc.codigo_emp, cc.cod_emp_mult,
cc.data_rec_c, cc.data_venc_c, 
cc.n_docnsu_adm, cc.n_aut_cart, 
cc.nparcela, cc.qtde_parc, 
cc.codigo_ctrl, ctrl.nome_ctrl, 
cc.n_doc_v, cc.n_doc_c, cc.tp_doc_v, 
cc.valor_c, cc.valor_liquido, cc.valor_original,
cc.datq_c, cc.status_c,
case when ((coalesce(cc.valor_original, cc.valor_c) > 0) and (coalesce(cc.valor_liquido, 0) > 0) and (coalesce(cc.valor_original, cc.valor_c) <> coalesce(cc.valor_liquido, 0))) then
        (100 - ((coalesce(cc.valor_original, cc.valor_c, 0) / coalesce(cc.valor_c, 0)) * 100))
     else 0
end taxa_cred,
coalesce(cc.cod_cliente, 0) cod_cliente, 
trim(case when (cc.cod_cliente > 0) then cl.nome_cliente else cc.nome_c end) nome_cliente, 
cc.cod_terminal_adm, termc.desc_term_adm, cc.cod_adm, adm.descricao_adm, 
cc.cod_bandeira_adm, band.descricao, 
cc.nome_c, emp.identificacao_emp from controle_creditos cc 
left join clientes cl on 
    cl.cod_cliente = cc.cod_cliente 
    and cl.cod_empresa = cc.cod_emp_mult 
inner join vw_conc_financ_status wcf on
    wcf.nsu = cc.n_docnsu_adm
    and coalesce(wcf.installment_number, 1) = coalesce(cc.nparcela, 1)
    and wcf.cod_empresa = cc.cod_emp_mult
inner join conciliacao_financeiro cf on
    cf.id = wcf.id
    and cf.installment_number = wcf.installment_number
    and cf.installments_total = wcf.installments_total
    and cf.cod_empresa = wcf.cod_empresa
inner join empresa emp on 
    emp.cod_empresa = cc.cod_emp_mult 
inner join controles ctrl on 
   ctrl.codigo_ctrl = cc.codigo_ctrl 
    and ctrl.codigo_emp = cc.cod_emp_mult 
    and ctrl.tp_plano = 'C' 
left join terminal_cartao termc on 
    termc.cod_term_adm = cc.cod_terminal_adm 
    and termc.cod_empresa = cc.cod_emp_mult 
left join adm_cartao adm on 
    adm.cod_adm = termc.cod_adm 
    and adm.cod_empresa = termc.cod_empresa 
left join bandeiras_cartao band on 
    band.cod_bandeira = cc.cod_bandeira_adm 
   and band.cod_empresa = cc.cod_emp_mult 
left join conciliacao_adquirente adq on
    adq.id = cf.acquirer_id
left join conciliacao_status_pag_adq stpag_adq on
    stpag_adq.codigo = cf.status_pag_cod
    and stpag_adq.id_adquirente = adq.id
left join conciliacao_status_pag stpag on
    stpag.id = stpag_adq.id_status_pag
where cc.datq_c is null
and cc.data_venc_c is not null 
and cc.data_venc_c < cf.payment_date  
and coalesce(cc.n_docnsu_adm, '') <> '' 
and coalesce(cc.n_aut_cart, '') <> ''
;

/* View: RECEBIMENTOS2, Owner: SYSDBA */
CREATE VIEW RECEBIMENTOS2 (TP_RECEBIMENTO, ORDEM, ORDEM2, NUMDOC, TIPO, TIPO2, VALORDOC, COD_EMPRESA, COD_EMP_ORIG, COD_EMP_MULT, DATA_CONF, CODIGO_CTRL, NOME_CTRL, FORMPAG, VALOR_PAGO, VALORRATEIO, VALOR_PAGO_VISTA, DATA_MOV, DATA_VENC, SEQID, SEQID2) AS

-- VIEW EXIBE OS RECEBIMENTOS DETALHADOS DAS VENDAS (REQUISICAO, ORDEM DE SERVICO, COMANDOS), RECIBO ANTECIPADOS E  CREDIARIO (CREDITOS/CHEQUES)
-- RELATORIO "RECEBIMENTO FINANCEIRO"
--- REQ, OS
select 'DIRETO', 1, case when (rq.tipo = 'REQ') then 2 else 3 end ordem2, rq.nped, rq.tipo, rq.tipo, coalesce(rq.valor_total, 0) valor_total,
(case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else rq.cod_empresa end) cod_empresa,
rq.cod_empresa,
rq.cod_empresa,
rq.data_fech,
case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end formpag,
coalesce(fp.valordoc, 0) valordoc,
coalesce(fp.valordoc, 0) valorrateio,
case when (ctr.docs = 'N') then coalesce(fp.valordoc, 0) else 0 end valor_pago_vista,

fp.data_mov, fp.data_venc,
coalesce(fp.seqform, rq.nped), coalesce(fp.seqform, rq.nped)
from pedvenda rq
left join empresa emp on rq.cod_empresa = emp.cod_empresa
left join formpagamento fp on fp.nrequisicao = rq.nped and fp.tpdocs = rq.tipo and fp.cod_empresa = rq.cod_empresa and fp.recibo is null
left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
where coalesce(trim(rq.status_ped), '') = 'FECHADA' and rq.tipo in ('REQ', 'OS')

union all

select 'RECIBO', 1, case when (rq.tipo = 'REQ') then 2 else 3 end ordem2, rq.nped, rq.tipo, rq.tipo, coalesce(rq.valor_total, 0) valor_total,
(case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else rq.cod_empresa end) cod_empresa,
rq.cod_empresa,
rq.cod_empresa,
rq.data_fech,
case when (select first 1 ctrl.nome_ctrl from controles ctrl
inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend ='REC' order by rc.valordoc asc) is null then
    0
else (select first 1 ctrl.codigo_ctrl from controles ctrl
    inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
    where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend ='REC' order by rc.valordoc asc)
end as codigo_ctrl,
case when (select first 1 ctrl.nome_ctrl from controles ctrl
inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend ='REC' order by rc.valordoc asc) is null then
    'SEM FORMA'
else
    (select first 1 ctrl.nome_ctrl from controles ctrl
    inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
    where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend ='REC' order by rc.valordoc asc)
end as nome_ctrl,
'RECIBO' formpag,
coalesce(fp.valordoc, 0) valordoc,
coalesce(fp.valordoc, 0) valorrateio,
0 valor_pago_vista,
fp.data_mov, fp.data_venc, coalesce(fp.seqform, rq.nped), coalesce(fp.seqform, rq.nped)

from pedvenda rq
left join empresa emp on rq.cod_empresa = emp.cod_empresa
inner join formpagamento fp on fp.nrequisicao = rq.nped and fp.tpdocs = rq.tipo and fp.cod_empresa = rq.cod_empresa and (not fp.recibo is null)
left join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa
where coalesce(trim(rq.status_ped), '') = 'FECHADA' and rq.tipo in ('REQ', 'OS')

union all

select 'TROCO', 1, case when (rq.tipo = 'REQ') then 2 else 3 end ordem2, rq.nped, rq.tipo, rq.tipo, coalesce(rq.valor_total, 0) valor_total,
(case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else rq.cod_empresa end) cod_empresa,
rq.cod_empresa,
rq.cod_empresa,
rq.data_fech,
case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end formpag,
coalesce(fp.valordoc, 0) valordoc,
coalesce(fp.valordoc, 0) valorrateio,
case when (ctr.docs = 'N') then coalesce(fp.valordoc, 0) else 0 end valor_pago_vista,
fp.data_mov, fp.data_venc, coalesce(fp.seqform, rq.nped), coalesce(fp.seqform, rq.nped)
from pedvenda rq
left join empresa emp on rq.cod_empresa = emp.cod_empresa
inner join formpagamento fp on fp.rec_numvend = rq.nped and fp.rec_tipvend = rq.tipo and fp.cod_empresa = rq.cod_empresa and fp.tpdocs = 'TRC'
left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
where coalesce(trim(rq.status_ped), '') = 'FECHADA' and rq.tipo in ('REQ', 'OS')

union all

--- CF

select 'DIRETO', 1, 1, mt.n_comando, 'MOT',  'MOT', coalesce(mt.valor_a_rec, 0) valor_a_rec,
(case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else mt.cod_empresa end) cod_empresa,
mt.cod_empresa,
mt.cod_empresa,
mt.data_fech,
case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end formpag,
coalesce(fp.valordoc, 0) valordoc,
coalesce(fp.valordoc, 0) valorrateio,
case when (ctr.docs = 'N') then coalesce(fp.valordoc, 0) else 0 end valor_pago_vista,
fp.data_mov, fp.data_venc,
coalesce(fp.seqform, mt.n_comando), coalesce(fp.seqform, mt.n_comando) from com_fat mt
left join empresa emp on mt.cod_empresa = emp.cod_empresa
left join formpagamento fp on fp.nrequisicao = mt.n_comando and fp.tpdocs = 'MOT' and fp.cod_empresa = mt.cod_empresa  and fp.recibo is null
inner join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
where (coalesce(trim(mt.status_v), '') = 'FECHADO') and mt.natureza = 'S'

union all

select 'RECIBO', 1, 1, mt.n_comando, 'MOT',  'MOT', coalesce(mt.valor_a_rec, 0) valor_a_rec,
(case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else mt.cod_empresa end) cod_empresa,
mt.cod_empresa,
mt.cod_empresa,
mt.data_fech,
case when (select first 1 ctrl.nome_ctrl from controles ctrl
inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend = 'REC' order by rc.valordoc asc) is null then
    0
else (select first 1 ctrl.codigo_ctrl from controles ctrl
    inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
    where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend = 'REC' order by rc.valordoc asc)
end as codigo_ctrl,
case when (select first 1 ctrl.nome_ctrl from controles ctrl
inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend = 'REC' order by rc.valordoc asc) is null then
    'SEM FORMA'
else
    (select first 1 ctrl.nome_ctrl from controles ctrl
    inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
    where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend = 'REC' order by rc.valordoc asc)
end as nome_ctrl,
'RECIBO' formpag,
coalesce(fp.valordoc, 0) valordoc,
coalesce(fp.valordoc, 0) valorrateio,
0 valor_pago_vista,
fp.data_mov, fp.data_venc,
coalesce(fp.seqform, mt.n_comando), coalesce(fp.seqform, mt.n_comando) from com_fat mt
left join empresa emp on mt.cod_empresa = emp.cod_empresa
inner join formpagamento fp on fp.nrequisicao = mt.n_comando and fp.tpdocs = 'MOT' and fp.cod_empresa = mt.cod_empresa and (not fp.recibo is null)
left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
where (coalesce(trim(mt.status_v), '') = 'FECHADO') and mt.natureza = 'S'

union all

select 'TROCO', 1, 1, mt.n_comando, 'MOT',  'MOT', coalesce(mt.valor_a_rec, 0) valor_a_rec,
(case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else mt.cod_empresa end) cod_empresa,
mt.cod_empresa,
mt.cod_empresa,
mt.data_fech,
case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end formpag,
coalesce(fp.valordoc, 0) valordoc,
coalesce(fp.valordoc, 0) valorrateio,
case when (ctr.docs = 'N') then coalesce(fp.valordoc, 0) else 0 end valor_pago_vista,
fp.data_mov, fp.data_venc,
coalesce(fp.seqform, mt.n_comando), coalesce(fp.seqform, mt.n_comando)
from com_fat mt
left join empresa emp on mt.cod_empresa = emp.cod_empresa
inner join formpagamento fp on fp.rec_numvend = mt.n_comando and fp.rec_tipvend = 'MOT' and fp.cod_empresa = mt.cod_empresa and fp.tpdocs = 'TRC'
left join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa
left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
where (coalesce(trim(mt.status_v), '') = 'FECHADO') and mt.natureza = 'S'

-- Cred

union all

select coalesce((case when (((select count(*) from hist_rec hist where hist.lote_quit = pr.lote_quit and hist.cod_empresa = pr.codigo_emp) > 0)
                            and ((l.historico_l like '%RECIBOS ATENCIPADOS%') or (l.historico_l like '%RECIBOS ANTECIPADOS%'))) then
                        'RECIBO'
                      when coalesce(pr.tip_baixa, '') = 'D' then
                        'DEVOLUCAO'
                      else
                        'DIRETO'
end), 'DIRETO'),
3, 5, pr.seq_bxcred, 'CREDIARIO', case when (ctr1.nome_ctrl is null) then pr.tipo_doc_c else ctr1.nome_ctrl end tipo2, coalesce(pr.valor_quitado, 0) as valor_total,
(case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pr.codigo_emp end) cod_empresa,
pr.codigo_emp,
pr.cod_emp_mult,
pr.datq_c,

coalesce((case when (((select count(*) from hist_rec hist where hist.lote_quit = pr.lote_quit and hist.cod_empresa = pr.codigo_emp) > 0)
                and ((l.historico_l like '%RECIBOS ATENCIPADOS%') or (l.historico_l like '%RECIBOS ANTECIPADOS%'))) then
                 case when (l.tipo_l = 'S') then
                        0
                      else
                        case when (ctr.codigo_ctrl is null) then 0 else ctr.codigo_ctrl end
                 end
               else
                 case when ctr.codigo_ctrl is null then
                        case when coalesce(pr.tip_baixa, '') = 'D' then
                               case when (ctr1.codigo_ctrl is null) then 0 else ctr1.codigo_ctrl end
                             else
                               0
                        end
                      else
                        ctr.codigo_ctrl
                 end
          end),
0) codigo_ctrl,

coalesce((case when (((select count(*) from hist_rec hist where hist.lote_quit = pr.lote_quit and hist.cod_empresa = pr.codigo_emp) > 0)
                and ((l.historico_l like '%RECIBOS ATENCIPADOS%') or (l.historico_l like '%RECIBOS ANTECIPADOS%'))) then
                 case when (l.tipo_l = 'S') then
                        'SEM FORMA'
                      else
                        case when (ctr.nome_ctrl is null) then 0 else ctr.nome_ctrl end
                 end
               else
                 case when ctr.nome_ctrl is null then
                        case when coalesce(pr.tip_baixa, '') = 'D' then
                               case when (ctr1.nome_ctrl is null) then 0 else ctr1.nome_ctrl end
                             else
                               'SEM FORMA'
                        end
                      else
                        ctr.nome_ctrl
                 end
          end),
'SEM FORMA') nome_ctrl,

coalesce((case when (((select count(*) from hist_rec hist where hist.lote_quit = pr.lote_quit and hist.cod_empresa = pr.codigo_emp) > 0)
                and ((l.historico_l like '%RECIBOS ATENCIPADOS%') or (l.historico_l like '%RECIBOS ANTECIPADOS%'))) then
                 case when (l.tipo_l = 'S') then
                        'SEM FORMA'
                      else
                        'RECIBO'
                 end
               else
                 case when ctr.nome_ctrl is null then
                        case when coalesce(pr.tip_baixa, '') = 'D' then
                               'DEVOLUCAO'
                             else
                               'SEM FORMA'
                        end
                      else
                        ctr.nome_ctrl
                 end
          end),
'SEM FORMA') formpag,

case when(l.tipo_l = 'S') then
       (coalesce(l.valor_l, 0) * -1)
     else
       case when (coalesce(l.valor_l, 0)) <= 0 then
              case when coalesce(pr.tip_baixa, '') = 'D' then
                    coalesce(pr.valor_quitado, 0)
                   else
                     coalesce(l.valor_l, 0)
              end
            else
              coalesce(l.valor_l, 0)
       end
end valor_pago,

case when (coalesce((select count(*) from baixa_creditos pr1
                    where pr1.lote_quit = pr.lote_quit
                    and pr1.datq_c = iif(emp.financeiro_unificado = 'S', pr.datq_c, pr1.datq_c)
                    and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr1.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp)), 0) > 1) then
       (case when(l.tipo_l = 'S') then
               (coalesce(l.valor_l, 0) * -1)
             else
               case when (coalesce(l.valor_l, 0)) <= 0 then
                      case when coalesce(pr.tip_baixa, '') = 'D' then
                            coalesce(pr.valor_quitado, 0)
                           else
                             coalesce(l.valor_l, 0)
                      end
                    else
                      coalesce(l.valor_l, 0)
               end
        end /
        coalesce((select count(*) from baixa_creditos pr1
                  where pr1.lote_quit = pr.lote_quit
                  and pr1.datq_c = iif(emp.financeiro_unificado = 'S', pr.datq_c, pr1.datq_c)
                  and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr1.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp)), 0)
       )
     else
        case when(l.tipo_l = 'S') then
               (coalesce(l.valor_l, 0) * -1)
             else
               case when (coalesce(l.valor_l, 0)) <= 0 then
                      case when coalesce(pr.tip_baixa, '') = 'D' then
                            coalesce(pr.valor_quitado, 0)
                           else
                             coalesce(l.valor_l, 0)
                      end
                    else
                      coalesce(l.valor_l, 0)
               end
        end
end valorrateio,
case when (((select count(*) from hist_rec hist
             where hist.lote_quit = pr.lote_quit
             and hist.cod_empresa = pr.codigo_emp) > 0)
             and ((l.historico_l like '%RECIBOS ATENCIPADOS%') or (l.historico_l like '%RECIBOS ANTECIPADOS%'))) then
       0
     when coalesce(pr.tip_baixa, '') = 'D' then
       0
     else
       case when (ctr.docs = 'N') then
              case when(l.tipo_l = 'S') then
                     (coalesce(l.valor_l, 0) * -1)
                   else
                     case when (coalesce(l.valor_l, 0)) <= 0 then
                            case when coalesce(pr.tip_baixa, '') = 'D' then
                                   coalesce(pr.valor_quitado, 0)
                                 else
                                   coalesce(l.valor_l, 0)
                            end
                          else
                            coalesce(l.valor_l, 0)
                     end
              end
            else
              0
       end
end valor_pago_vista,
pr.datq_c, pr.data_venc_c,
coalesce(l.cod_lanc, pr.seq_bxcred), 0
from baixa_creditos pr
left join empresa emp on pr.codigo_emp = emp.cod_empresa
