/* View: VW_CONCILIACAO_PENDENCIAS_CRED, Owner: SYSDBA */
CREATE VIEW VW_CONCILIACAO_PENDENCIAS_CRED (COD_CRED, CODIGO_EMP, COD_EMP_MULT, DATA_REC_C, DATA_VENC_C, N_DOCNSU_ADM, N_AUT_CART, NPARCELA, QTDE_PARC, CODIGO_CTRL, NOME_CTRL, N_DOC_V, N_DOC_C, TP_DOC_V, VALOR_C, VALOR_LIQUIDO, VALOR_ORIGINAL, DATQ_C, STATUS_C, TAXA_CRED, COD_CLIENTE, NOME_CLIENTE, COD_TERMINAL_ADM, DESC_TERM_ADM, COD_ADM, DESCRICAO_ADM, COD_BANDEIRA_ADM, DESC_BANDEIRA_ADM, NOME_C, IDENTIFICACAO_EMP) AS

select cc.cod_cred, cc.codigo_emp, cc.cod_emp_mult, 
cc.data_rec_c, cc.data_venc_c, 
cc.n_docnsu_adm, cc.n_aut_cart, 
cc.nparcela, cc.qtde_parc, 
cc.codigo_ctrl, ctrl.nome_ctrl, 
cc.n_doc_v, cc.n_doc_c, cc.tp_doc_v, 
coalesce(cc.valor_c, 0) valor_c,
coalesce(cc.valor_liquido, 0) valor_liquido,
coalesce(cc.valor_original, 0) valor_original,
cc.datq_c, cc.status_c,
case when ((coalesce(cc.valor_original, cc.valor_c) > 0) and (coalesce(cc.valor_liquido, 0) > 0) and (coalesce(cc.valor_original, cc.valor_c) <> coalesce(cc.valor_liquido, 0))) then
        (100 - ((coalesce(cc.valor_original, cc.valor_c, 0) / coalesce(cc.valor_c, 0)) * 100))
     else 0
end taxa_cred,
coalesce(cc.cod_cliente, 0) cod_cliente,
trim(case when (cc.cod_cliente > 0) then cl.nome_cliente else cc.nome_c end) nome_cliente, 
cc.cod_terminal_adm, termc.desc_term_adm, cc.cod_adm, adm.descricao_adm, 
cc.cod_bandeira_adm, band.descricao, 
cc.nome_c, emp.identificacao_emp from controle_creditos cc 
left join clientes cl on 
    cl.cod_cliente = cc.cod_cliente 
    and cl.cod_empresa = cc.cod_emp_mult 
inner join empresa emp on 
    emp.cod_empresa = cc.cod_emp_mult 
inner join controles ctrl on 
   ctrl.codigo_ctrl = cc.codigo_ctrl 
    and ctrl.codigo_emp = cc.cod_emp_mult 
    and ctrl.tp_plano = 'C' 
left join terminal_cartao termc on 
    termc.cod_term_adm = cc.cod_terminal_adm
    and termc.cod_empresa = cc.cod_emp_mult
left join adm_cartao adm on
    adm.cod_adm = termc.cod_adm
    and adm.cod_empresa = termc.cod_empresa
left join bandeiras_cartao band on
    band.cod_bandeira = cc.cod_bandeira_adm
   and band.cod_empresa = cc.cod_emp_mult
where cc.datq_c is null
and coalesce(cc.n_docnsu_adm, '') <> ''
and coalesce(cc.n_aut_cart, '') <> ''
and (select result from retorna_pend_confere (cc.n_docnsu_adm, cc.n_aut_cart, cc.nparcela, cc.cod_emp_mult)) = 0
union
select cc.cod_cred, cc.codigo_emp, cc.cod_emp_mult,
cc.data_rec_c, cc.data_venc_c,
cc.n_docnsu_adm, cc.n_aut_cart,
cc.nparcela, cc.qtde_parc,
cc.codigo_ctrl, ctrl.nome_ctrl,
cc.n_doc_v, cc.n_doc_c, cc.tp_doc_v,
coalesce(cc.valor_c, 0) valor_c,
coalesce(cc.valor_liquido, 0) valor_liquido,
coalesce(cc.valor_original, 0) valor_original,
cc.datq_c, cc.status_c,
case when ((coalesce(cc.valor_original, cc.valor_c) > 0) and (coalesce(cc.valor_liquido, 0) > 0) and (coalesce(cc.valor_original, cc.valor_c) <> coalesce(cc.valor_liquido, 0))) then
        (100 - ((coalesce(cc.valor_original, cc.valor_c, 0) / coalesce(cc.valor_c, 0)) * 100))
     else 0
end taxa_cred,
coalesce(cc.cod_cliente, 0) cod_cliente,
trim(case when (cc.cod_cliente > 0) then cl.nome_cliente else cc.nome_c end) nome_cliente,
cc.cod_terminal_adm, termc.desc_term_adm, cc.cod_adm, adm.descricao_adm,
cc.cod_bandeira_adm, band.descricao, 
cc.nome_c, emp.identificacao_emp from controle_creditos cc 
left join clientes cl on 
    cl.cod_cliente = cc.cod_cliente 
    and cl.cod_empresa = cc.cod_emp_mult 
inner join empresa emp on 
    emp.cod_empresa = cc.cod_emp_mult 
inner join controles ctrl on 
    ctrl.codigo_ctrl = cc.codigo_ctrl 
    and ctrl.codigo_emp = cc.cod_emp_mult 
    and ctrl.tp_plano = 'C' 
left join terminal_cartao termc on 
    termc.cod_term_adm = cc.cod_terminal_adm 
    and termc.cod_empresa = cc.cod_emp_mult 
left join adm_cartao adm on 
    adm.cod_adm = termc.cod_adm 
    and adm.cod_empresa = termc.cod_empresa 
left join bandeiras_cartao band on 
    band.cod_bandeira = cc.cod_bandeira_adm 
    and band.cod_empresa = cc.cod_emp_mult 
where cc.datq_c is null
and coalesce(cc.n_docnsu_adm, '') = ''
and coalesce(cc.n_aut_cart, '') = ''
;

/* View: FOTOS_EMP, Owner: SYSDBA */
CREATE VIEW FOTOS_EMP (CODIGO, COD_EMPRESA, FOTO, USAR_LOGO) AS

select fotos.codigo, fotos.cod_empresa, fotos.foto, empresa.usar_logo from fotos
inner join empresa on empresa.cod_empresa = fotos.cod_empresa
where fotos.codigo = 0
and fotos.tipo = 3
;

/* View: DADOS_PLANO, Owner: SYSDBA */
CREATE VIEW DADOS_PLANO (NPED, TIPO, COD_EMPRESA, SEQPLANO, TEXTO_PLANO, DATA_VENC, VALOR_DOC) AS

select nrequisicao, tpdocs, cod_empresa, seqplano, texto_plano, data_venc, valordoc from plano_pag
where valordoc > 0
;

/* View: DADOS_FORMAPAG, Owner: SYSDBA */
CREATE VIEW DADOS_FORMAPAG (NREQUISICAO, NDOC, TPDOCS, COD_EMPRESA, VALORDOC, DATA_VENC) AS

select fp.nrequisicao, fp.ndoc, fp.tpdocs, fp.cod_empresa, fp.valordoc, fp.data_venc from formpagamento fp
where fp.tipdoc <> 'N'
and fp.valordoc > 0
and fp.ativo = 1
union
select fp.rec_numvend, fp.ndoc, fp.rec_tipvend, fp.cod_empresa, fp.valordoc, fp.data_venc from formpagamento fp
where fp.tpdocs <> 'LCS'
and fp.tipdoc <> 'N'
and fp.valordoc > 0
and fp.ativo = 1
;

/* View: DADOS_MIN_ENTREGA, Owner: SYSDBA */
CREATE VIEW DADOS_MIN_ENTREGA (NPED, TIPO, COD_EMPRESA, DEST_SEQID_ENTRG, NOME_CLIENTE, NOME_RECEB, END_RECEB, BAIRRO_RECEB, CIDA_RECEB, CEP_RECEB, FONE_RECEB) AS

select pedvenda.nped, pedvenda.tipo, pedvenda.cod_empresa,
pedvenda.dest_seqid_entrg,
case when (pedvenda.dest_seqid_entrg is not null) then
        vw_clientes_dest.nome_cliente
     else
        clientes.nome_cliente
end nome_cliente,
case when (pedvenda.dest_seqid_entrg is not null) then
        vw_clientes_dest.nome_cliente
     else
        pedvenda.nome_receb
end nome_receb,
case when (pedvenda.dest_seqid_entrg is not null) then
        trim(coalesce(vw_clientes_dest.logradouro, '')) ||
        case when (trim(coalesce(vw_clientes_dest.numero, '')) <> '') then ', ' || trim(coalesce(vw_clientes_dest.numero, '')) else '' end ||
        case when (trim(coalesce(vw_clientes_dest.complemento, '')) <> '') then ', ' || trim(coalesce(vw_clientes_dest.complemento, '')) else '' end
     else
        pedvenda.end_receb
end end_receb,
case when (pedvenda.dest_seqid_entrg is not null) then
        vw_clientes_dest.bairro
     else
        pedvenda.bairro_receb
end bairro_receb,
case when (pedvenda.dest_seqid_entrg is not null) then
         vw_clientes_dest.cidade
     else
        pedvenda.cida_receb
end cida_receb,
case when (pedvenda.dest_seqid_entrg is not null) then
    vw_clientes_dest.cep
else
    pedvenda.cep_receb
end cep_receb,
case when (pedvenda.dest_seqid_entrg is not null) then
    vw_clientes_dest.telefone
else
    pedvenda.fone_receb
end fone_receb
 from pedvenda
inner join clientes on clientes.cod_cliente = pedvenda.cod_cliente
    and clientes.cod_empresa = pedvenda.cod_empresa
left join vw_clientes_dest on vw_clientes_dest.cod_cliente = pedvenda.cod_cliente
    and vw_clientes_dest.cod_empresa = pedvenda.cod_empresa
    and vw_clientes_dest.dest_seqid = pedvenda.dest_seqid_entrg
;

/* View: PEDVENDA_DAV, Owner: SYSDBA */
CREATE VIEW PEDVENDA_DAV (NPED, TIPO, COD_EMPRESA, IDENTIFICACAO_EMP, NOME_EMP, FANTASIA_EMP, CGC_EMP, IE_EMP, TELEFONE_EMP, EMAIL_EMP, ENDERECO_COMPL_EMP, ENDERECO_EMP, CEP_EMP, NUMERO_END_EMP, COMPLEMENTO_END_EMP, BAIRRO_EMP, CIDADE_EMP, ESTADO_EMP, COD_CLIENTE, NOME_CLIENTE, RAZAO_CLIENTE, CPFCGC, INSC_EST, FONE_CLIENTE, FONE_CELULAR, EMAIL, ENDERECO_COMPL, ENDERECO, CEP, BAIRRO, CIDADE, ESTADO, COMPLEMENTO, NUM_END_CLIENTE, CONTATO, COD_CLI_FAT, NOME_CLI_FAT, RAZAO_CLI_FAT, CPFCGC_CLI_FAT, INSC_EST_CLI_FAT, FONE_CLI_FAT, FONE_CELULAR_CLI_FAT, EMAIL_CLI_FAT, ENDERECO_COMPL_CLI_FAT, ENDERECO_CLI_FAT, CEP_CLI_FAT, BAIRRO_CLI_FAT, CIDADE_CLI_FAT, ESTADO_CLI_FAT, COMPLEMENTO_CLI_FAT, NUM_END_CLI_FAT, CONTATO_CLI_FAT, DESC_COND_PAG, VALOR_TOTAL, TOT_PROD, TOT_SERV, TOT_PROD_TERC, TOT_SERV_TERC, OBS_PED, OBS_RED_OS, GRUPO_PROD, COD_PROD, NUM_FAB_PROD, STATUS, COD_GRADE, GRADE, STATUS_PED, NPREVENDA, NOME_RECEB, FONE_RECEB, CEP_RECEB, END_RECEB, BAIRRO_RECEB, CIDA_RECEB, DATA_FECH, HORAFECHAMENTO, MINFECHAMENTO, QUANTIDADE, VL_UNITARIO, VL_TOTAL_ITEM, APLICACAO_PROD, UNIDADE, RATEIO_DESC, RATEIO_ACRESC, PROD_SERV, COD_TECNICO_MECAN, NOME_TECNICO_MECAN, COD_TECNICO_MECAN2, NOME_TECNICO_MECAN2, COD_VEICULO, CHASSI, PLACA, COMBUST_VEIC, KM_V, COD_SERVICO, ORIGEM_SERVICO, APARELHO_PED, NCM, ORDEM, NITEM, COD_EQUIP, DATA_PED, CODIGO, CIDA_AVL, ESTA_AVL, BAIRRO_AVL, CEP_AVL, NOME_CLI_ORC, HORAABERTURA, MINABERTURA, CEP_DEST, LOGRADOURO_DEST, BAIRRO_DEST, CIDADE_DEST, ESTADO_DEST, COMPLEMENTO_DEST, DEST_SEQID, LOCACAO_PROD, LOCACAO_PROD_1, LOC_DEP, SELOS_REM, SELOS_COL, LACRES_REM, LACRES_COL, OBS_LIVRO_REG, CODIGO_KIT, DESCRICAO_KIT, VALOR_KIT, VALOR_UN_KIT, RATEIO_ACRESC_KIT, RATEIO_DESC_KIT, MARCA_P, DESCRICAO, QUANT_PED_ITEM, QUANT_SERV_PED, ACRESCIMO_TOT, DESCONTO_TOT, CANCELADO, PESO_BRUT_TOT, DATA, ANO_FAB, COR, MARCA_V, MODELO_V, PLACA_V, RENAVAM, COD_VENDEDOR, NOME_VENDEDOR, RG_VENDEDOR, CPF_VENDEDOR, USAR_LOGO, TIPO_OS, DESCRICAO_TV, ID_KIT, QUANT_KIT, PESO_BRUT_PROD, END_AVL, VALOR_KIT_LIQ, VALOR_UN_KIT_LIQ, ACRESC_ITEM_PROD_TOT, DESC_ITEM_PROD_TOT, ACRESC_ITEM_SERV_TOT, DESC_ITEM_SERV_TOT, COD_US_FECH, NOME_US_FECH, SELOS_COL1, SELOS_COL2, SELOS_REM1, SELOS_REM2, LACRES_COL1, LACRES_COL2, LACRES_REM1, LACRES_REM2, OBS_TPVENDA1, OBS_TPVENDA2, OBS_TPVENDA, ESTADO_VEIC, DEFEITO, ACESSORIOS, OBS_OS, CODIGO_FOTO, FOTO, CODIGO_FOTO_EMP, FOTO_EMP) AS

SELECT PEDVENDA.NPED, PEDVENDA.TIPO, PEDVENDA.COD_EMPRESA,
 EMPRESA.IDENTIFICACAO_EMP, EMPRESA.NOME_EMP, EMPRESA.FANTASIA_EMP, EMPRESA.CGC_EMP, EMPRESA.IE_EMP,
 EMPRESA.TELEFONE_EMP, EMPRESA.EMAIL_EMP,
 (coalesce(EMPRESA.ENDRECO_EMP, '') ||
    iif(coalesce(EMPRESA.NUMERO_END, 0) > 0, ', N: ' || coalesce(EMPRESA.NUMERO_END, 0), '') ||
    iif((trim(coalesce(EMPRESA.COMPLEMENTO_EMP, '')) <> ''), ', ' || trim(coalesce(EMPRESA.COMPLEMENTO_EMP, '')), '') ||
    iif(trim(coalesce(EMPRESA.CEP_EMP, '')) <> '', ', ' || trim(coalesce(EMPRESA.CEP_EMP, '')), '') ||
    iif(trim(coalesce(EMPRESA.BAIRRO_EMP, '')) <> '', ', ' || trim(coalesce(EMPRESA.BAIRRO_EMP, '')), '') ||
    iif(trim(coalesce(EMPRESA.CIDADE_EMP, '')) <> '', ', ' || trim(coalesce(EMPRESA.CIDADE_EMP, '')), '') ||
    iif(trim(coalesce(ESTEMP.SIGLA_UF, '')) <> '', ', ' || trim(coalesce(ESTEMP.SIGLA_UF, '')), '')
 ) ENDERECO_COMPL_EMP,
 EMPRESA.ENDRECO_EMP, EMPRESA.CEP_EMP, EMPRESA.NUMERO_END, EMPRESA.COMPLEMENTO_EMP,
 EMPRESA.BAIRRO_EMP, EMPRESA.CIDADE_EMP, ESTEMP.SIGLA_UF ESTADO_EMP,


 CLIENTES.COD_CLIENTE, CLIENTES.NOME_CLIENTE, CLIENTES.RAZAO, CLIENTES.CPFCGC, CLIENTES.INSC_EST,
 CLIENTES.FONE_CLIENTE, CLIENTES.FONE_CELULAR, CLIENTES.EMAIL,
 (coalesce(CLIENTES.ENDERECO, '') ||
    iif(trim(coalesce(CLIENTES.NUM_END_CLIENTE, '')) <> '', ', N: ' || trim(coalesce(CLIENTES.NUM_END_CLIENTE, '')), '') ||
    iif((trim(coalesce(CLIENTES.COMPLEMENTO, '')) <> ''), ', ' || trim(coalesce(CLIENTES.COMPLEMENTO, '')), '') ||
    iif(trim(coalesce(CLIENTES.CEP, '')) <> '', ', ' || trim(coalesce(CLIENTES.CEP, '')), '') ||
    iif(trim(coalesce(BAICL.NOME_BAIRRO, '')) <> '', ', ' || trim(coalesce(BAICL.NOME_BAIRRO, '')), '') ||
    iif(trim(coalesce(CIDCL.NOME_CIDADE, '')) <> '', ', ' || trim(coalesce(CIDCL.NOME_CIDADE, '')), '') ||
    iif(trim(coalesce(ESTCL.SIGLA_UF, '')) <> '', ', ' || trim(coalesce(ESTCL.SIGLA_UF, '')), '')
 ) ENDERECO_COMPL_CL,
 CLIENTES.ENDERECO, CLIENTES.CEP, BAICL.NOME_BAIRRO, CIDCL.NOME_CIDADE, ESTCL.SIGLA_UF ESTADO,
 CLIENTES.COMPLEMENTO, CLIENTES.NUM_END_CLIENTE, CLIENTES.CONTATO,


 CLIFAT.COD_CLIENTE AS COD_CLI_FAT, CLIFAT.NOME_CLIENTE AS NOME_CLI_FAT, CLIFAT.RAZAO AS RAZAO_CLI_FAT, CLIFAT.CPFCGC AS CPFCGC_CLI_FAT, CLIFAT.INSC_EST AS INSC_EST_CLI_FAT,
 CLIFAT.FONE_CLIENTE AS FONE_CLIENTE_CLI_FAT, CLIFAT.FONE_CELULAR AS FONE_CELULAR_CLI_FAT, CLIFAT.EMAIL AS EMAIL_CLI_FAT,
 (coalesce(CLIFAT.ENDERECO, '') ||
    iif(trim(coalesce(CLIFAT.NUM_END_CLIENTE, '')) <> '', ', N: ' || trim(coalesce(CLIFAT.NUM_END_CLIENTE, '')), '') ||
    iif((trim(coalesce(CLIFAT.COMPLEMENTO, '')) <> ''), ', ' || trim(coalesce(CLIFAT.COMPLEMENTO, '')), '') ||
    iif(trim(coalesce(CLIFAT.CEP, '')) <> '', ', ' || trim(coalesce(CLIFAT.CEP, '')), '') ||
    iif(trim(coalesce(BAICLFAT.NOME_BAIRRO, '')) <> '', ', ' || trim(coalesce(BAICLFAT.NOME_BAIRRO, '')), '') ||
    iif(trim(coalesce(CIDCLFAT.NOME_CIDADE, '')) <> '', ', ' || trim(coalesce(CIDCLFAT.NOME_CIDADE, '')), '') ||
    iif(trim(coalesce(ESTCLFAT.SIGLA_UF, '')) <> '', ', ' || trim(coalesce(ESTCLFAT.SIGLA_UF, '')), '')
 ) ENDERECO_COMPL_CLI_FAT,
 CLIFAT.ENDERECO AS ENDERECO_CLI_FAT, CLIFAT.CEP AS CEP_CLI_FAT, BAICLFAT.NOME_BAIRRO AS NOME_BAIRRO_CLI_FAT, CIDCLFAT.NOME_CIDADE AS NOME_CIDADE_CLI_FAT, ESTCLFAT.SIGLA_UF ESTADO_CLI_FAT,
 CLIFAT.COMPLEMENTO AS COMPLEMENTO_CLI_FAT, CLIFAT.NUM_END_CLIENTE AS NUM_END_CLI_FAT, CLIFAT.CONTATO AS CONTATO_CLI_FAT,


 COND_PAG.DESC_COND_PAG,
 PEDVENDA.VALOR_TOTAL, PEDVENDA.TOT_PROD, PEDVENDA.TOT_SERV, PEDVENDA.TOT_PROD_TERC, PEDVENDA.TOT_SERV_TERC,
 PEDVENDA.OBS_PED, PEDVENDA.OBS_RED_OS, 
 ORCAMENTO4.GRUPO_PROD, ORCAMENTO4.COD_PROD, ORCAMENTO4.NUM_FAB_PROD,  ORCAMENTO4.STATUS, ORCAMENTO4.COD_GRADE, GRADE.DESCRICAO,
 PEDVENDA.STATUS_PED, PEDVENDA.NPREVENDA,
 PEDVENDA.NOME_RECEB, PEDVENDA.FONE_RECEB, PEDVENDA.CEP_RECEB, PEDVENDA.END_RECEB, PEDVENDA.BAIRRO_RECEB, PEDVENDA.CIDA_RECEB,
 PEDVENDA.DATA_FECH, PEDVENDA.HORAFECHAMENTO, PEDVENDA.MINFECHAMENTO,
 CASE WHEN (TRIM(COALESCE(ORCAMENTO4.UNIDADE_CONV, '')) = '') THEN
        ORCAMENTO4.QUANTIDADE
      WHEN (TRIM(COALESCE(ORCAMENTO4.UNIDADE, '')) = TRIM(COALESCE(ORCAMENTO4.UNIDADE_CONV, ''))) THEN
        ORCAMENTO4.QUANTIDADE
      WHEN ((COALESCE(ORCAMENTO4.OPERACAO_CONV, '') = 'M') AND (COALESCE(ORCAMENTO4.FATOR_CONV, 0) > 0)) THEN
        ORCAMENTO4.QUANTIDADE_CONV
      WHEN ((COALESCE(ORCAMENTO4.OPERACAO_CONV, '') = 'D') AND (COALESCE(ORCAMENTO4.FATOR_CONV, 0) > 0)) THEN
        ORCAMENTO4.QUANTIDADE_CONV
      ELSE
        ORCAMENTO4.QUANTIDADE
 END QUANTIDADE,
 CASE WHEN (TRIM(COALESCE(ORCAMENTO4.UNIDADE_CONV, '')) = '') THEN
        ORCAMENTO4.VL_UNITARIO
      WHEN (TRIM(COALESCE(ORCAMENTO4.UNIDADE, '')) = TRIM(COALESCE(ORCAMENTO4.UNIDADE_CONV, ''))) THEN
        ORCAMENTO4.VL_UNITARIO
      WHEN ((COALESCE(ORCAMENTO4.OPERACAO_CONV, '') = 'M') AND (COALESCE(ORCAMENTO4.FATOR_CONV, 0) > 0)) THEN
        ORCAMENTO4.VL_UNITARIO_CONV
      WHEN ((COALESCE(ORCAMENTO4.OPERACAO_CONV, '') = 'D') AND (COALESCE(ORCAMENTO4.FATOR_CONV, 0) > 0)) THEN
        ORCAMENTO4.VL_UNITARIO_CONV
      ELSE
        ORCAMENTO4.VL_UNITARIO
 END VL_UNITARIO,
 ORCAMENTO4.VL_TOTAL_ITEM, PRODUTOS.APLICACAO_PROD,
 IIF(TRIM(COALESCE(ORCAMENTO4.UNIDADE_CONV, '')) <> '',
    TRIM(COALESCE(ORCAMENTO4.UNIDADE_CONV, '')),
    TRIM(COALESCE(ORCAMENTO4.UNIDADE, ''))) UNIDADE,
 ORCAMENTO4.RATEIO_DESC, ORCAMENTO4.RATEIO_ACRESC, ORCAMENTO4.PROD_SERV,
 ORCAMENTO4.COD_TECNICO_MECAN, ORCAMENTO4.NOME_TECNICO_MECAN, ORCAMENTO4.COD_TECNICO_MECAN2, ORCAMENTO4.NOME_TECNICO_MECAN2,
 DADOS_VEICULO.CODIGO, DADOS_VEICULO.CHASSI, DADOS_VEICULO.PLACA, PEDVENDA.COMBUST_VEIC, PEDVENDA.KM_V, ORCAMENTO4.COD_SERVICO, ORCAMENTO4.ORIGEM_SERVICO, PEDVENDA.APARELHO_PED,
 ORCAMENTO4.NCM, ORCAMENTO4.ORDEM, ORCAMENTO4.NITEM,
 PEDVENDA.COD_EQUIP, PEDVENDA.DATA_PED, FOTOS.CODIGO, PEDVENDA.CIDA_AVL, PEDVENDA.ESTA_AVL, PEDVENDA.BAIRRO_AVL, PEDVENDA.CEP_AVL,
 PEDVENDA.NOME_CLI_ORC, PEDVENDA.HORAABERTURA, PEDVENDA.MINABERTURA,
 VW_CLIENTES_DEST.CEP, VW_CLIENTES_DEST.LOGRADOURO, VW_CLIENTES_DEST.BAIRRO, VW_CLIENTES_DEST.CIDADE, VW_CLIENTES_DEST.UF, VW_CLIENTES_DEST.COMPLEMENTO, PEDVENDA.DEST_SEQID,
 PRODUTOS.LOCACAO_PROD, PRODUTOS.LOCACAO_PROD_1, PRODUTOS.LOC_DEP,
 PEDVENDA_ATIVIDADES_REPARP.SELOS_REM, PEDVENDA_ATIVIDADES_REPARP.SELOS_COL, PEDVENDA_ATIVIDADES_REPARP.LACRES_REM, PEDVENDA_ATIVIDADES_REPARP.LACRES_COL,
 PEDVENDA.OBS_LIVRO_REG, ORCAMENTO4.CODIGO_KIT, ORCAMENTO4.DESCRICA0_KIT, ORCAMENTO4.VALOR_KIT, ORCAMENTO4.VALOR_UN_KIT, ORCAMENTO4.RATEIO_ACRESC_KIT, ORCAMENTO4.RATEIO_DESC_KIT,
 ORCAMENTO4.MARCA_P, ORCAMENTO4.DESCRICAO, TOTAIS_PEDVENDA.QUANT_PED_ITEM, TOTAIS_PEDVENDA.QUANT_SERV_PED,
 TOTAIS_PEDVENDA.ACRESCIMO, TOTAIS_PEDVENDA.DESCONTO, TOTAIS_PEDVENDA.CANCELADO, TOTAIS_PEDVENDA.PESO_BRUT_PROD, VALOR_VENC_MIN.DATA,
 DADOS_VEICULO.ANOFAB, DADOS_VEICULO.COR, DADOS_VEICULO.MARCA, DADOS_VEICULO.MODELO, DADOS_VEICULO.PLACA, DADOS_VEICULO.RENAVAM,
 COLABORADOR.COD_VENDEDOR, COLABORADOR.NOME_VENDEDOR, COLABORADOR.RG_VENDEDOR, COLABORADOR.CPF_VENDEDOR, FOTOS_EMP.USAR_LOGO, PEDVENDA.TIPO_OS, TIPO_VENDAS.DESCRICAO,
 ORCAMENTO4.ID_KIT, TOTAIS_PEDVENDA.QUANT_KIT, PRODUTOS.PESO_BRUT_PROD, PEDVENDA.END_AVL,
 ORCAMENTO4.VALOR_KIT_LIQ, ORCAMENTO4.VALOR_UN_KIT_LIQ, TOTAIS_PEDVENDA.ACRESC_ITEM_PROD, TOTAIS_PEDVENDA.DESC_ITEM_PROD, TOTAIS_PEDVENDA.ACRESC_ITEM_SERV,
 TOTAIS_PEDVENDA.DESC_ITEM_SERV, PEDVENDA.COD_US_FECH, COLABORADOR_1.NOME_VENDEDOR,
 PEDVENDA_ATIVIDADES_REPARP.SELOS_COL1, PEDVENDA_ATIVIDADES_REPARP.SELOS_COL2, PEDVENDA_ATIVIDADES_REPARP.SELOS_REM1, PEDVENDA_ATIVIDADES_REPARP.SELOS_REM2,
 PEDVENDA_ATIVIDADES_REPARP.LACRES_COL1, PEDVENDA_ATIVIDADES_REPARP.LACRES_COL2, PEDVENDA_ATIVIDADES_REPARP.LACRES_REM1, PEDVENDA_ATIVIDADES_REPARP.LACRES_REM2,
 PEDVENDA_ATIVIDADES_REPARP.OBS_TPVENDA1, PEDVENDA_ATIVIDADES_REPARP.OBS_TPVENDA2, PEDVENDA_ATIVIDADES_REPARP.OBS_TPVENDA, PEDVENDA.ESTADO_VEIC, PEDVENDA.DEFEITO,
 PEDVENDA.ACESSORIOS, PEDVENDA.OBS_OS, FOTOS.CODIGO, FOTOS.FOTO, FOTOS_EMP.CODIGO, FOTOS_EMP.FOTO

 FROM PEDVENDA
 LEFT JOIN TOTAIS_PEDVENDA ON TOTAIS_PEDVENDA.NPED=PEDVENDA.NPED AND TOTAIS_PEDVENDA.TIPO=PEDVENDA.TIPO AND TOTAIS_PEDVENDA.COD_EMPRESA=PEDVENDA.COD_EMPRESA
 LEFT JOIN PEDVENDA_ATIVIDADES_REPARP ON PEDVENDA_ATIVIDADES_REPARP.NPED=PEDVENDA.NPED AND PEDVENDA_ATIVIDADES_REPARP.TIPO=PEDVENDA.TIPO AND PEDVENDA_ATIVIDADES_REPARP.COD_EMPRESA=PEDVENDA.COD_EMPRESA

 LEFT JOIN CLIENTES ON PEDVENDA.COD_CLIENTE=CLIENTES.COD_CLIENTE AND PEDVENDA.COD_EMPRESA=CLIENTES.COD_EMPRESA
 LEFT JOIN CIDADES CIDCL ON CIDCL.COD_CIDADE=CLIENTES.COD_CIDADE
 LEFT JOIN BAIRROS BAICL ON BAICL.COD_BAIRRO=CLIENTES.COD_BAIRRO
 LEFT JOIN ESTADOS ESTCL ON ESTCL.CODIGO_UF=CLIENTES.CODIGO_UF
 LEFT JOIN VW_CLIENTES_DEST ON PEDVENDA.COD_CLIENTE=VW_CLIENTES_DEST.COD_CLIENTE AND PEDVENDA.COD_EMPRESA=VW_CLIENTES_DEST.COD_EMPRESA AND PEDVENDA.DEST_SEQID=VW_CLIENTES_DEST.DEST_SEQID

 LEFT JOIN CLIENTES CLIFAT ON PEDVENDA.COD_CLI_FAT=CLIFAT.COD_CLIENTE AND PEDVENDA.COD_EMPRESA=CLIFAT.COD_EMPRESA
 LEFT JOIN CIDADES CIDCLFAT ON CIDCLFAT.COD_CIDADE=CLIFAT.COD_CIDADE
 LEFT JOIN BAIRROS BAICLFAT ON BAICLFAT.COD_BAIRRO=CLIFAT.COD_BAIRRO
 LEFT JOIN ESTADOS ESTCLFAT ON ESTCLFAT.CODIGO_UF=CLIFAT.CODIGO_UF

 LEFT JOIN EMPRESA ON PEDVENDA.COD_EMPRESA=EMPRESA.COD_EMPRESA
 LEFT JOIN ESTADOS ESTEMP ON ESTEMP.CODIGO_UF=EMPRESA.UF_EMP
 LEFT JOIN COND_PAG ON PEDVENDA.COD_COND_PAG=COND_PAG.COD_COND_PAG
 LEFT JOIN COLABORADOR ON PEDVENDA.COD_VENDEDOR=COLABORADOR.COD_VENDEDOR AND PEDVENDA.COD_EMPRESA=COLABORADOR.COD_EMPRESA
 LEFT JOIN ORCAMENTO4 ON PEDVENDA.NPED=ORCAMENTO4.NPED AND PEDVENDA.COD_EMPRESA=ORCAMENTO4.COD_EMPRESA AND PEDVENDA.TIPO=ORCAMENTO4.TIPO

 LEFT JOIN VALOR_VENC_MIN ON PEDVENDA.NPED=VALOR_VENC_MIN.NPED AND PEDVENDA.COD_EMPRESA=VALOR_VENC_MIN.COD_EMPRESA AND PEDVENDA.TIPO=VALOR_VENC_MIN.TIPO
 LEFT JOIN DADOS_VEICULO ON PEDVENDA.NPED=DADOS_VEICULO.NPED AND PEDVENDA.COD_EMPRESA=DADOS_VEICULO.COD_EMPRESA AND PEDVENDA.TIPO=DADOS_VEICULO.TIPO
 LEFT JOIN FOTOS_EMP ON PEDVENDA.COD_EMPRESA=FOTOS_EMP.COD_EMPRESA
 LEFT JOIN TIPO_VENDAS ON PEDVENDA.TIPO=TIPO_VENDAS.TIPO AND PEDVENDA.TIPV=TIPO_VENDAS.SIGLA
 LEFT JOIN COLABORADOR COLABORADOR_1 ON PEDVENDA.COD_EMPRESA=COLABORADOR_1.COD_EMPRESA AND PEDVENDA.COD_US_FECH=COLABORADOR_1.COD_VENDEDOR
 LEFT JOIN GRADE ON ORCAMENTO4.COD_EMPRESA=GRADE.COD_EMPRESA AND ORCAMENTO4.COD_GRADE=GRADE.COD_GRADE
 LEFT JOIN PRODUTOS ON ORCAMENTO4.GRUPO_PROD=PRODUTOS.GRUPO_PROD AND ORCAMENTO4.COD_EMPRESA=PRODUTOS.COD_EMPRESA AND ORCAMENTO4.COD_PROD=PRODUTOS.COD_PROD
 LEFT JOIN FOTOS ON ORCAMENTO4.NPED=FOTOS.CODIGO AND ORCAMENTO4.COD_EMPRESA=FOTOS.COD_EMPRESA AND ORCAMENTO4.GRUPO_PROD=FOTOS.GRUPO_PROD AND ORCAMENTO4.COD_PROD=FOTOS.COD_PROD AND ORCAMENTO4.COD_GRADE=FOTOS.COD_GRADE AND ORCAMENTO4.TIPO_FOTO=FOTOS.TIPO
;

/* View: PEDVENDA_ATIVIDADES_REPARP, Owner: SYSDBA */
CREATE VIEW PEDVENDA_ATIVIDADES_REPARP (NPED, TIPO, COD_EMPRESA, ESTADO_VEIC, DEFEITO, ACESSORIOS, OBS_OS, SELOS_COL, SELOS_REM, LACRES_COL, LACRES_REM, OBS_TPVENDA, ESTADO_VEIC1, ESTADO_VEIC2, DEFEITO1, DEFEITO2, ACESSORIOS1, ACESSORIOS2, OBS_OS1, OBS_OS2, SELOS_COL1, SELOS_COL2, SELOS_REM1, SELOS_REM2, LACRES_COL1, LACRES_COL2, LACRES_REM1, LACRES_REM2, OBS_TPVENDA1, OBS_TPVENDA2) AS

select nped, tipo, cod_empresa,
cast(substring(estado_veic from 1 for 400) as varchar(400)) estado_veic,
cast(substring(defeito from 1 for 400) as varchar(400)) defeito,
cast(substring(acessorios from 1 for 400) as varchar(400)) acessorios,
cast(substring(obs_os from 1 for 400) as varchar(400)) obs_os,
cast(substring(selos_col from 1 for 400) as varchar(400)) selos_col,
cast(substring(selos_rem from 1 for 400) as varchar(400)) selos_rem,
cast(substring(lacres_col from 1 for 400) as varchar(400)) lacres_col,
cast(substring(lacres_rem from 1 for 400) as varchar(400)) lacres_rem,
cast(substring(obs_tpvenda from 1 for 400) as varchar(400)) obs_tpvenda,
cast(substring(estado_veic from 1 for 200) as varchar(200)) estado_veic1,
cast(substring(estado_veic from 201 for 200) as varchar(200)) estado_veic2,
cast(substring(defeito from 1 for 200) as varchar(200)) defeito1,
cast(substring(defeito from 201 for 200) as varchar(200)) defeito2,
cast(substring(acessorios from 1 for 200) as varchar(200)) acessorios1,
cast(substring(acessorios from 201 for 200) as varchar(200)) acessorios2,
cast(substring(obs_os from 1 for 200) as varchar(200)) obs_os1,
cast(substring(obs_os from 201 for 200) as varchar(200)) obs_os2,
cast(substring(selos_col from 1 for 200) as varchar(200)) selos_col1,
cast(substring(selos_col from 201 for 200) as varchar(200)) selos_col2,
cast(substring(selos_rem from 1 for 200) as varchar(200)) selos_rem1,
cast(substring(selos_rem from 201 for 200) as varchar(200)) selos_rem2,
cast(substring(lacres_col from 1 for 200) as varchar(200)) lacres_col1,
cast(substring(lacres_col from 201 for 200) as varchar(200)) lacres_col2,
cast(substring(lacres_rem from 1 for 200) as varchar(200)) lacres_rem1,
cast(substring(lacres_rem from 201 for 200) as varchar(200)) lacres_rem2,
cast(substring(obs_tpvenda from 1 for 200) as varchar(200)) obs_tpvenda1,
cast(substring(obs_tpvenda from 201 for 200) as varchar(200)) obs_tpvenda2 from pedvenda
;

/* View: PEDVENDA_FOTOS_PROD, Owner: SYSDBA */
CREATE VIEW PEDVENDA_FOTOS_PROD (NPED, TIPO, COD_EMPRESA, GRUPO_PROD, COD_PROD, COD_GRADE) AS

select first 1 codigo as nped,
case when (tipo = -1000) then 'REQ'
     when (tipo = -1001) then 'OS'
     else 'ORC'
end tipo,
cod_empresa,
grupo_prod,
cod_prod,
cod_grade from fotos
where tipo = iif(trim(tipo) = 'REQ', -1000, iif(trim(tipo) = 'OS', -1001, -1002))
;

/* View: DADOS_VEICULO, Owner: SYSDBA */
CREATE VIEW DADOS_VEICULO (NPED, TIPO, COD_EMPRESA, CHASSI, PLACA, CODIGO, MODELO, MARCA, COR, ANOFAB, ANOMOD, RENAVAM, KM_V) AS

select pv.nped, pv.tipo, pv.cod_empresa,
ret.ichassi, ret.iplaca, ret.icodigo,
case when (v.modelo > 0) then t.descricao else v.descmodelo end descmodelo,
case when (v.cod_marca > 0) then m.descricao_marca else v.marca_v end marca_v,
case when (v.cod_cor > 0) then c.descricao_cor else v.cor end cor,
v.anofab, v.anomod, v.renavam, v.km_v
from pedvenda pv
left join retorna_veiculo (pv.chassi, pv.placa, pv.cod_veiculo, pv.cod_empresa) ret on 1 = 1
left join veiculos v on v.placa = ret.iplaca and v.chassi = ret.ichassi and v.codigo = ret.icodigo and v.cod_empresa = ret.icod_empresa
left join tipmodelo t on t.codigo = v.modelo and t.cod_empresa = v.cod_empresa
left join marca_prod m on m.cod_marca = v.cod_marca
left join codigo_corfab c on c.cod_cor = v.cod_cor
;

/* View: TOTAIS_PEDVENDA, Owner: SYSDBA */
CREATE VIEW TOTAIS_PEDVENDA (NPED, TIPO, COD_EMPRESA, QUANT_PED_ITEM, QUANT_SERV_PED, QUANT_KIT, QUANT_PROD, QUANT_PROD_TERC, QUANT_SERV, QUANT_SERV_TERC, TOT_PROD, TOT_SERV, TOT_PROD_TERC, TOT_SERV_TERC, ACRESC_ITEM_PROD, DESC_ITEM_PROD, ACRESC_ITEM_SERV, DESC_ITEM_SERV, VALOR_TOTAL, VALOR_BRUTO, ACRESCIMO, DESCONTO, CANCELADO, PESO_BRUT_PROD) AS

select
  pedvenda.nped,
  pedvenda.tipo,
  pedvenda.cod_empresa,
  coalesce(
   coalesce((select sum(case when (trim(coalesce(pp.unidade_conv, '')) = '') then
                           coalesce(pp.quant_ped_item, 0)
                         when (trim(coalesce(pp.unidade, '')) = trim(coalesce(pp.unidade_conv, ''))) then
                           coalesce(pp.quant_ped_item, 0)
                         when ((coalesce(pp.operacao_conv, '') = 'M') AND (coalesce(pp.fator_conv, 0) > 0)) then
                           (coalesce(pp.quant_ped_item, 0) * coalesce(pp.fator_conv, 0))
                         when ((coalesce(pp.operacao_conv, '') = 'D') AND (coalesce(pp.fator_conv, 0) > 0)) then
                           (coalesce(pp.quant_ped_item, 0) / coalesce(pp.fator_conv, 0))
                         else
                           coalesce(pp.quant_ped_item, 0)
                        end) from pedvenda_prod pp
             where pp.nped = pedvenda.nped
             and pp.tipo = pedvenda.tipo
             and pp.cod_empresa = pedvenda.cod_empresa
             and coalesce(pp.status, '') = ''), 0) +
   coalesce((select sum(coalesce(ppt.qtde, 0)) from pedvenda_prod_terc ppt
             where ppt.nped = pedvenda.nped
             and ppt.tipo = pedvenda.tipo
             and ppt.cod_empresa = pedvenda.cod_empresa), 0),
  0) quant_ped_item,

  coalesce(
   coalesce((select sum(coalesce(ps.quant_serv_ped, 0)) from pedvenda_serv ps
             where ps.nped = pedvenda.nped
             and ps.tipo = pedvenda.tipo
             and ps.cod_empresa = pedvenda.cod_empresa
             and coalesce(ps.status, '') = ''), 0) +
   coalesce((select count(*) from pedvenda_serv_terc pst
             where pst.nped = pedvenda.nped
             and pst.tipo = pedvenda.tipo
             and pst.cod_empresa = pedvenda.cod_empresa), 0),
  0) quant_serv_ped,

  coalesce((select coalesce(qtde, 0) from retorna_qtde_kit(pedvenda.nped, pedvenda.tipo, pedvenda.cod_empresa)), 0) quant_kit,


  coalesce((select sum(case when (trim(coalesce(pp.unidade_conv, '')) = '') then
                           coalesce(pp.quant_ped_item, 0)
                         when (trim(coalesce(pp.unidade, '')) = trim(coalesce(pp.unidade_conv, ''))) then
                           coalesce(pp.quant_ped_item, 0)
                         when ((coalesce(pp.operacao_conv, '') = 'M') AND (coalesce(pp.fator_conv, 0) > 0)) then
                           (coalesce(pp.quant_ped_item, 0) * coalesce(pp.fator_conv, 0))
                         when ((coalesce(pp.operacao_conv, '') = 'D') AND (coalesce(pp.fator_conv, 0) > 0)) then
                           (coalesce(pp.quant_ped_item, 0) / coalesce(pp.fator_conv, 0))
                         else
                           coalesce(pp.quant_ped_item, 0)
                        end) from pedvenda_prod pp
             where pp.nped = pedvenda.nped
             and pp.tipo = pedvenda.tipo
             and pp.cod_empresa = pedvenda.cod_empresa
             and coalesce(pp.status, '') = ''),
  0) quant_prod,

  coalesce((select sum(coalesce(ppt.qtde, 0)) from pedvenda_prod_terc ppt
             where ppt.nped = pedvenda.nped
             and ppt.tipo = pedvenda.tipo
             and ppt.cod_empresa = pedvenda.cod_empresa),
  0) quant_prod_terc,

  coalesce((select sum(coalesce(ps.quant_serv_ped, 0)) from pedvenda_serv ps
             where ps.nped = pedvenda.nped
             and ps.tipo = pedvenda.tipo
             and ps.cod_empresa = pedvenda.cod_empresa
             and coalesce(ps.status, '') = ''),
  0) quant_serv,

  coalesce((select count(*) from pedvenda_serv_terc pst
             where pst.nped = pedvenda.nped
             and pst.tipo = pedvenda.tipo
             and pst.cod_empresa = pedvenda.cod_empresa),
  0) quant_serv_terc,

  coalesce(pedvenda.tot_prod, 0) TOT_PROD,
  coalesce(pedvenda.tot_serv, 0) TOT_SERV,
  coalesce(pedvenda.tot_prod_terc, 0) TOT_PROD_TERC,
  coalesce(pedvenda.tot_serv_terc, 0) TOT_SERV_TERC,

  coalesce((select sum(coalesce(pp.rateio_acresc, 0)) from pedvenda_prod pp
           where pp.nped = pedvenda.nped
           and pp.tipo = pedvenda.tipo
           and pp.cod_empresa = pedvenda.cod_empresa
           and coalesce(pp.status, '') = ''), 0) ACRESC_ITEM_PROD,

  coalesce((select sum(coalesce(pp.rateio_desc, 0)) from pedvenda_prod pp
           where pp.nped = pedvenda.nped
           and pp.tipo = pedvenda.tipo
           and pp.cod_empresa = pedvenda.cod_empresa
           and coalesce(pp.status, '') = ''), 0) DESC_ITEM_PROD,

  coalesce((select sum(coalesce(ps.rateio_acresc, 0)) from pedvenda_serv ps
           where ps.nped = pedvenda.nped
           and ps.tipo = pedvenda.tipo
           and ps.cod_empresa = pedvenda.cod_empresa
           and coalesce(ps.status, '') = ''), 0) ACRESC_ITEM_SERV,

  coalesce((select sum(coalesce(ps.rateio_desc, 0)) from pedvenda_serv ps
           where ps.nped = pedvenda.nped
           and ps.tipo = pedvenda.tipo
           and ps.cod_empresa = pedvenda.cod_empresa
           and coalesce(ps.status, '') = ''), 0) DESC_ITEM_SERV,

  coalesce(pedvenda.valor_total, 0) VALOR_TOTAL,
  (coalesce(pedvenda.tot_prod, 0) + coalesce(pedvenda.tot_serv, 0) + coalesce(pedvenda.tot_prod_terc, 0) + coalesce(pedvenda.tot_serv_terc, 0)) VALOR_BRUTO,

  (coalesce((select sum(coalesce(pp.rateio_acresc, 0)) from pedvenda_prod pp
    where pp.nped = pedvenda.nped
    and pp.tipo = pedvenda.tipo
    and pp.cod_empresa = pedvenda.cod_empresa
    and coalesce(pp.status, '') = ''), 0) +
    coalesce((select sum(coalesce(ps.rateio_acresc, 0)) from pedvenda_serv ps
    where ps.nped = pedvenda.nped
    and ps.tipo = pedvenda.tipo
    and ps.cod_empresa = pedvenda.cod_empresa
    and coalesce(ps.status, '') = ''), 0)) acrescimo,

   (coalesce((select sum(coalesce(pp.rateio_desc, 0)) from pedvenda_prod pp
    where pp.nped = pedvenda.nped
    and pp.tipo = pedvenda.tipo
    and pp.cod_empresa = pedvenda.cod_empresa
    and coalesce(pp.status, '') = ''), 0) +
    coalesce((select sum(coalesce(ps.rateio_desc, 0)) from pedvenda_serv ps
    where ps.nped = pedvenda.nped
    and ps.tipo = pedvenda.tipo
    and ps.cod_empresa = pedvenda.cod_empresa
    and coalesce(ps.status, '') = ''), 0)) desconto,

   (coalesce((select sum(coalesce(pp.vltot_ped_item, 0)) from pedvenda_prod pp
    where pp.nped = pedvenda.nped
    and pp.tipo = pedvenda.tipo
    and pp.cod_empresa = pedvenda.cod_empresa
    and coalesce(pp.status, '') = 'CANCELADO'), 0) +
    coalesce((select sum(coalesce(ps.valor_tot_serv, 0)) from pedvenda_serv ps
    where ps.nped = pedvenda.nped
    and ps.tipo = pedvenda.tipo
    and ps.cod_empresa = pedvenda.cod_empresa
    and coalesce(ps.status, '') = 'CANCELADO'), 0)) cancelado,

   (coalesce((select sum(coalesce(pr.peso_brut_prod, 0) * coalesce(pp.quant_ped_item, 0)) from pedvenda_prod pp
    inner join produtos pr on pr.grupo_prod = pp.grupo_prod and pr.cod_prod = pp.cod_prod and pr.cod_empresa = pp.cod_empresa
    where pp.nped = pedvenda.nped
    and pp.tipo = pedvenda.tipo
    and pp.cod_empresa = pedvenda.cod_empresa
    and coalesce(pp.status, '') = ''), 0)) peso_brut_prod
     from pedvenda
;

/* View: MOVPRODSERVCOMCUSTO, Owner: SYSDBA */
CREATE VIEW MOVPRODSERVCOMCUSTO (TIPOPS, TIPO, STATUS_PED, VALOR_TOTAL, COD_CLIENTE, NOME_CLIENTE, DATA_PED, DATA_FECH, NPED, COD_PROD, GRUPOOUSEDRV, COD_EMPRESA, NUM_FAB_PROD, QTDE, VL_UNIT, DESCR, RATEIO_DESC, RATEIO_ACRESC, ACRESC_ITEM, DESC_ITEM, DAV_ORIGEM, NPED_ORIGEM, TIPO_ORIGEM, STATUS_ITEM, CUSTO_ULTIMO, CUSTO_MEDIO, TIPO_OS, TIPV) AS

select 'P' tipops ,p.tipo,p.status_ped,p.valor_total,c.cod_cliente,c.nome_cliente,p.data_ped,p.data_fech,pp.nped,pp.cod_prod,
    pp.grupo_prod grupoOuServ,pp.cod_empresa, pp.num_fab_prod,
     pp.quant_ped_item qtde, pp.vlun_ped_item vl_unit,pp.descr_prod_ped descr,
     pp.rateio_desc,pp.rateio_acresc,pp.acresc_item, pp.desc_item,
     pp.dav_origem,pp.nped_origem,pp.tipo_origem,pp.status,pp.pcust_c, pp.pcust_mc,p.tipo_os,p.tipv
     from pedvenda_prod pp
     inner join pedvenda p on p.nped = pp.nped and p.cod_empresa = pp.cod_empresa and pp.tipo = p.tipo
     inner join clientes c on c.cod_cliente = p.cod_cliente and c.cod_empresa = p.cod_empresa
     where p.ativo = 1
     union
     select 'S' tipops,p.tipo,p.status_ped,p.valor_total,c.cod_cliente,c.nome_cliente,p.data_ped,p.data_fech,
     ps.nped, ps.cod_servico cod_prod, ps.cod_servico grupoOuServ,
     ps.cod_empresa, ps.cod_servico num_fab_prod, ps.quant_serv_ped qtde,ps.valor_un_serv vl_unit,
     ps.desc_serv_ped descr,
     ps.rateio_desc,ps.rateio_acresc,ps.acresc_item, ps.desc_item,
     ps.dav_origem,ps.nped_origem,ps.tipo_origem,ps.status, 0, 0,p.tipo_os,p.tipv
     from pedvenda_serv ps
     inner join pedvenda p on p.nped = ps.nped and p.cod_empresa = ps.cod_empresa and ps.tipo = p.tipo
     inner join clientes c on c.cod_cliente = p.cod_cliente and c.cod_empresa = p.cod_empresa
     where p.ativo = 1
;

/* View: VW_NFCE_MOVIMENTO, Owner: SYSDBA */
CREATE VIEW VW_NFCE_MOVIMENTO (ID, COD_EMISSOR, OPERADOR, DIA_MOV, DIA_FECH, TIPO, TPAG, XPAG, VPAG, COD_CONTROLE, NOME_CTRL, COD_EMPRESA, MOV_SEQ, COD_NFCE, STATUS, SITUACAO_NFCE, TPEMIS, VNF, VPROD, VDESC, VSEG, VFRETE, VOUTRO) AS

select mov.id,  mov.cod_emissor, mov.operador, mov.dia_mov,  mov.dia_fech, 'NFC-e',
pag.tpag, xpag.xpag, coalesce(pag.vpag, 0) vpag, ctrl.codigo_ctrl, ctrl.nome_ctrl,
mov.cod_empresa, nfc.mov_seq, nfc.cod_nfce, coalesce(nfc.status, '') status,
coalesce(nfc.situacao_nfce, '') situacao_nfce, nfc.tpemis, coalesce(nfc.vnf, 0) vnf,
coalesce(nfc.vprod, 0) vprod, coalesce(nfc.vdesc, 0) vdesc, coalesce(nfc.vseg, 0) vseg,
coalesce(nfc.vfrete, 0) vfrete, coalesce(nfc.voutro, 0) voutro
from nfce_movimento mov
inner join nfce nfc on nfc.mov_id = mov.id and nfc.cod_empresa = mov.cod_empresa and nfc.ativo = 1
left join nfce_pagamento pag on pag.cod_nfce = nfc.cod_nfce and pag.cod_empresa = nfc.cod_empresa
left join sp_nfce_tab_tpag(pag.tpag) xpag on 1 = 1
left join controles ctrl on ctrl.codigo_ctrl = pag.cod_controle and ctrl.codigo_emp = pag.cod_empresa
union all
select mov.id,  mov.cod_emissor, mov.operador, mov.dia_mov,  mov.dia_fech, lanc.historico,
xpag.tpag, xpag.xpag, coalesce(lanc.valor, 0) valor, 1, ctrl.nome_ctrl, mov.cod_empresa, lanc.mov_seq,
null, null, null, null, 0, 0, 0, 0, 0, 0
from nfce_movimento mov
inner join nfce_movimento_lanc lanc on lanc.mov_id = mov.id and lanc.cod_empresa = mov.cod_empresa
left join sp_nfce_tab_tpag(1) xpag on 1 = 1
left join controles ctrl on ctrl.codigo_ctrl = 1 and ctrl.codigo_emp = lanc.cod_empresa
;

/* View: VW_CONTRATOS_CL, Owner: SYSDBA */
CREATE VIEW VW_CONTRATOS_CL (COD_GERADOR, COD_EMPRESA, NPED, TIPO, DATA_PED, DATA_FECH, DATVENC, VALOR_TOTAL, TOT_ACRESCIMO, TOT_DESCONTO, TOT_PROD, TOT_SERV, TOT_PROD_TERC, TOT_SERV_TERC, TOT_FORMPAG, TOT_BOLETAS, STATUS_PED, TIPO_OS, GERAR_NFS, GERAR_NF, GERAR_REC_LOC, GERAR_BOLETO, COD_RPS, NUM_NFS, SERIE_NFS, DATA_NFS, SITUACAO_NFS, DESCRICAOERRO_NFS, DATA_EMAIL_NFS, DATA_WHATSAPP_NFS, COD_NF, NUM_NF, SERIE_NF, DATA_NF, SITUACAO_NF, DESCRICAOERRO_NF, DATA_EMAIL_NF, DATA_WHATSAPP_NF, COD_CONTRATO, DESCR_CONTRATO, COD_CLIENTE, NOME_CLIENTE, RAZAO, CPFCGC, FONE_CLIENTE, FONE_CELULAR, EMAIL, CODIGO_UF, SIGLA_UF, COD_CIDADE, NOME_CIDADE, COD_BAIRRO, NOME_BAIRRO, CEP, ENDERECO, NUM_END_CLIENTE, N_SEQ_BOL, NOSSO_NUMERO_BANCO, DATA_REMESSA, COD_COBREBEM, COD_CONTROLE_CX, DATA_EMAIL_BOL, DATA_WHATSAPP_BOL, DATA_EMAIL_REC, DATA_WHATSAPP_REC, LOCACAO, FATURA_VINDI_ID, PEND_NFS, PEND_NF, PEND_REC_LOC, PEND_BOLETO) AS

SELECT PEDVENDA.COD_GERADOR, PEDVENDA.COD_EMPRESA,
PEDVENDA.NPED, PEDVENDA.TIPO, PEDVENDA.DATA_PED, PEDVENDA.DATA_FECH, PEDVENDA.DATVENC,
COALESCE(PEDVENDA.VALOR_TOTAL, 0) VALOR_TOTAL,
(COALESCE((SELECT SUM(COALESCE(PEDVENDA_PROD.RATEIO_ACRESC, 0)) FROM PEDVENDA_PROD
                   WHERE PEDVENDA_PROD.NPED = PEDVENDA.NPED
                   AND PEDVENDA_PROD.TIPO = PEDVENDA.TIPO
                   AND PEDVENDA_PROD.COD_EMPRESA = PEDVENDA.COD_EMPRESA
                   AND COALESCE(PEDVENDA_PROD.STATUS, '') <> 'CANCELADO'), 0) +
 COALESCE((SELECT SUM(COALESCE(PEDVENDA_SERV.RATEIO_ACRESC, 0)) FROM PEDVENDA_SERV
           WHERE PEDVENDA_SERV.NPED = PEDVENDA.NPED
           AND PEDVENDA_SERV.TIPO = PEDVENDA.TIPO
           AND PEDVENDA_SERV.COD_EMPRESA = PEDVENDA.COD_EMPRESA
           AND COALESCE(PEDVENDA_SERV.STATUS, '') <> 'CANCELADO'), 0)
 ) TOT_ACRESCIMO,
(COALESCE((SELECT SUM(COALESCE(PEDVENDA_PROD.RATEIO_DESC, 0)) FROM PEDVENDA_PROD
           WHERE PEDVENDA_PROD.NPED = PEDVENDA.NPED
           AND PEDVENDA_PROD.TIPO = PEDVENDA.TIPO
           AND PEDVENDA_PROD.COD_EMPRESA = PEDVENDA.COD_EMPRESA
           AND COALESCE(PEDVENDA_PROD.STATUS, '') <> 'CANCELADO'), 0) +
 COALESCE((SELECT SUM(COALESCE(PEDVENDA_SERV.RATEIO_DESC, 0)) FROM PEDVENDA_SERV
           WHERE PEDVENDA_SERV.NPED = PEDVENDA.NPED
           AND PEDVENDA_SERV.TIPO = PEDVENDA.TIPO
           AND PEDVENDA_SERV.COD_EMPRESA = PEDVENDA.COD_EMPRESA
           AND COALESCE(PEDVENDA_SERV.STATUS, '') <> 'CANCELADO'), 0)
 ) TOT_DESCONTO,
COALESCE(PEDVENDA.TOT_PROD, 0) TOT_PROD,
COALESCE(PEDVENDA.TOT_SERV, 0) TOT_SERV,
COALESCE(PEDVENDA.TOT_PROD_TERC, 0) TOT_PROD_TERC,
COALESCE(PEDVENDA.TOT_SERV_TERC, 0) TOT_SERV_TERC,
COALESCE(RETORNA_CONTRATOS.TOT_FORMPAG, 0) TOT_FORMPAG,
COALESCE(RETORNA_CONTRATOS.TOT_BOLETAS, 0) TOT_BOLETAS,
PEDVENDA.STATUS_PED, PEDVENDA.TIPO_OS, 
RETORNA_CONTRATOS.GERAR_NFS,
RETORNA_CONTRATOS.GERAR_NF,
RETORNA_CONTRATOS.GERAR_REC_LOC,
RETORNA_CONTRATOS.GERAR_BOLETO,
RETORNA_CONTRATOS.COD_RPS, RETORNA_CONTRATOS.NUM_NFS, RETORNA_CONTRATOS.SERIE_NFS,
RETORNA_CONTRATOS.DATA_NFS, RETORNA_CONTRATOS.SITUACAO_NFS, RETORNA_CONTRATOS.DESCRICAOERRO_NFS,
RETORNA_CONTRATOS.DATA_EMAIL_NFS, RETORNA_CONTRATOS.DATA_WHATSAPP_NFS,
RETORNA_CONTRATOS.COD_NF, RETORNA_CONTRATOS.NUM_NF, RETORNA_CONTRATOS.SERIE_NF,
RETORNA_CONTRATOS.DATA_NF, RETORNA_CONTRATOS.SITUACAO_NF, RETORNA_CONTRATOS.DESCRICAOERRO_NF,
RETORNA_CONTRATOS.DATA_EMAIL_NF, RETORNA_CONTRATOS.DATA_WHATSAPP_NF,
RETORNA_CONTRATOS.COD_CONTRATO, RETORNA_CONTRATOS.DESCR_CONTRATO, 
PEDVENDA.COD_CLIENTE, CLIENTES.NOME_CLIENTE, CLIENTES.RAZAO,
CLIENTES.CPFCGC, CLIENTES.FONE_CLIENTE, CLIENTES.FONE_CELULAR, CLIENTES.EMAIL,
CLIENTES.CODIGO_UF, ESTADOS.SIGLA_UF,
CLIENTES.COD_CIDADE, CIDADES.NOME_CIDADE,
CLIENTES.COD_BAIRRO, BAIRROS.NOME_BAIRRO,
CLIENTES.CEP, CLIENTES.ENDERECO, CLIENTES.NUM_END_CLIENTE,
RETORNA_CONTRATOS.N_SEQ_BOL, RETORNA_CONTRATOS.NOSSO_NUMERO_BANCO, RETORNA_CONTRATOS.DATA_REMESSA,
RETORNA_CONTRATOS.COD_COBREBEM, RETORNA_CONTRATOS.COD_CONTROLE_CX,
RETORNA_CONTRATOS.DATA_EMAIL_BOL, RETORNA_CONTRATOS.DATA_WHATSAPP_BOL,
RETORNA_CONTRATOS.DATA_EMAIL_REC, RETORNA_CONTRATOS.DATA_WHATSAPP_REC,
EXISTE_LOCACAO.RESULT, PEDVENDA.FATURA_VINDI_ID,
CASE WHEN ((COALESCE(RETORNA_CONTRATOS.GERAR_NFS, 'N') = 'S') and (COALESCE(PEDVENDA.TOT_SERV, 0) > 0) and (COALESCE(RETORNA_CONTRATOS.NUM_NFS, '') = '')) then
       'S'
     ELSE
       'N'
END PEND_NFS,
CASE WHEN ((COALESCE(RETORNA_CONTRATOS.GERAR_NF, 'N') = 'S') and (COALESCE(PEDVENDA.TOT_PROD, 0) > 0) and (COALESCE(RETORNA_CONTRATOS.NUM_NF, 0) <= 0)) then
       'S'
     ELSE
       'N'
END PEND_NF,
'N' PEND_REC_LOC,
CASE WHEN ((COALESCE(RETORNA_CONTRATOS.GERAR_BOLETO, 'N') = 'S') and (COALESCE(RETORNA_CONTRATOS.TOT_BOLETAS, 0) > 0) and (COALESCE(retorna_contratos.N_SEQ_BOL, '') = '')) then
        'S'
     ELSE
       'N'
END PEND_BOLETO
 FROM PEDVENDA
INNER JOIN CLIENTES ON
    CLIENTES.COD_CLIENTE = PEDVENDA.COD_CLIENTE
    AND CLIENTES.COD_EMPRESA = PEDVENDA.COD_EMPRESA
LEFT JOIN CIDADES ON CIDADES.COD_CIDADE = CLIENTES.COD_CIDADE
LEFT JOIN ESTADOS ON ESTADOS.CODIGO_UF = CLIENTES.CODIGO_UF
LEFT JOIN BAIRROS ON BAIRROS.COD_BAIRRO = CLIENTES.COD_BAIRRO
LEFT JOIN RETORNA_CONTRATOS (
    PEDVENDA.NPED,
    PEDVENDA.TIPO,
    PEDVENDA.COD_EMPRESA) ON 1 = 1
LEFT JOIN EXISTE_LOCACAO (
    PEDVENDA.NPED,
    PEDVENDA.TIPO,
    PEDVENDA.COD_EMPRESA) ON 1 = 1
;

/* View: RESUMO_FINANCEIRO, Owner: SYSDBA */
CREATE VIEW RESUMO_FINANCEIRO (TPDTQUIT_DTREF, TIPO_DESP, TIPO, COD_EMPRESA, COD_EMP_MULT, N_CONTA_PLC, DTQUIT_DTREF, NDOC, VALOR, HISTORICO, DATA, COD_LANC, VALOR_PAGO, DESC_PADR, DESC_SUB_CT, FORNECEDOR, NOME_CTRL, EXIBIR_RESUMO_FINANCEIRO, ATIVO, ORDEM, DESC_GR, DESC_DEP) AS

-- VIEW EXIBE OS PAGAMENTOS DESPESAS E PAGAMENTOS FORNECEDOR 
-- RELATORIO "RESUMO FINANCEIRO" EXIBIDO NA PARTE DAS DESPESAS
SELECT 1, 'LANC', 'DESPLANC',
(CASE WHEN(EMP.FINANCEIRO_UNIFICADO = 'S') THEN EMP.CODIGO_UNIFICADORA ELSE L.CODIGO_EMP END),
L.COD_EMP_MULT,
L.N_CONTA_PLC, L.DATQ_L, L.NDOC_L, L.VALOR_L, L.HISTORICO_L, L.DATA, L.COD_LANC, L.VALOR_L,
CASE WHEN TRIM(COALESCE(P.DESC_PADR, '')) = '' THEN P.DESC_PLC ELSE P.DESC_PADR END DESC_PADR,
S.DESC_SUB_CT, P.TIPO_CTP, CC.NOME_CTRL,
COALESCE(CC.EXIBIR_RESUMO_FINANCEIRO, 'S') EXIBIR_RESUMO_FINANCEIRO,
P.ATIVO, 1 ORDEM, C.DESC_GR, CT.DESC_DEP FROM P_CONTAS P
INNER JOIN GRUPOS_CT C ON P.GRUP_CT = C.GRUP_CT AND C.TIPO_GR = 'S'
LEFT JOIN SUB_GRUP_CT S ON P.COD_SUB_CT = S.COD_SUB_CT
INNER JOIN LANCAMENTOS L ON P.N_CONTA_PLC = L.N_CONTA_PLC
INNER JOIN EMPRESA EMP ON L.CODIGO_EMP = EMP.COD_EMPRESA
INNER JOIN CONTROLES CC ON L.CODIGO_CTRL = CC.CODIGO_CTRL AND L.CODIGO_EMP = CC.CODIGO_EMP
LEFT JOIN DEPART_CT CT ON CT.COD_DEP = C.COD_DEP
WHERE --L.DATQ_L >= :VDAT1 AND L.DATQ_L <= :VDAT2 AND L.CODIGO_EMP = 5
L.LOTE IS NULL AND COALESCE(P.TIPO_CTP, '') <> 'F'
UNION
SELECT 2, 'LANC', 'DESPLANC',
(CASE WHEN(EMP.FINANCEIRO_UNIFICADO = 'S') THEN EMP.CODIGO_UNIFICADORA ELSE L.CODIGO_EMP END),
L.COD_EMP_MULT,
L.N_CONTA_PLC, L.DTREFERENCIA, L.NDOC_L, L.VALOR_L, L.HISTORICO_L, L.DATA, L.COD_LANC, L.VALOR_L,
CASE WHEN TRIM(COALESCE(P.DESC_PADR, '')) = '' THEN P.DESC_PLC ELSE P.DESC_PADR END DESC_PADR,
S.DESC_SUB_CT, P.TIPO_CTP, CC.NOME_CTRL,
COALESCE(CC.EXIBIR_RESUMO_FINANCEIRO, 'S') EXIBIR_RESUMO_FINANCEIRO,
P.ATIVO, 1 ORDEM, C.DESC_GR, CT.DESC_DEP FROM P_CONTAS P
INNER JOIN GRUPOS_CT C ON P.GRUP_CT = C.GRUP_CT AND C.TIPO_GR = 'S'
LEFT JOIN SUB_GRUP_CT S ON P.COD_SUB_CT = S.COD_SUB_CT
INNER JOIN LANCAMENTOS L ON P.N_CONTA_PLC = L.N_CONTA_PLC
INNER JOIN EMPRESA EMP ON L.CODIGO_EMP = EMP.COD_EMPRESA
INNER JOIN CONTROLES CC ON L.CODIGO_CTRL = CC.CODIGO_CTRL AND L.CODIGO_EMP = CC.CODIGO_EMP
LEFT JOIN DEPART_CT CT ON CT.COD_DEP = C.COD_DEP
WHERE -- L.DTREFERENCIA >= :VDAT1 AND L.DTREFERENCIA <= :VDAT2 AND L.CODIGO_EMP = 5
L.LOTE IS NULL AND COALESCE(P.TIPO_CTP, '') <> 'F'
UNION
SELECT 1, 'CTP', 'DESPCTP',
(CASE WHEN(EMP.FINANCEIRO_UNIFICADO = 'S') THEN EMP.CODIGO_UNIFICADORA ELSE CTR.CODIGO_EMP END),
CTR.COD_EMP_MULT,
CTR.N_CONTA_PLC, CTR.DATQ_CTP, CTR.N_DOC_CTP, CTR.VALOR_CTP,
TRIM(CTR.HISTORICO_CTP) || ' - '|| TRIM(CTR.NOME_FOR_CTP),
CTR.DATQ_CTP, CTR.COD_CONTRP, CTR.VALOR_PAGO,
CASE WHEN TRIM(COALESCE(P.DESC_PADR, '')) = '' THEN P.DESC_PLC ELSE P.DESC_PADR END DESC_PADR,
S.DESC_SUB_CT, P.TIPO_CTP, CC.NOME_CTRL,
COALESCE(CC.EXIBIR_RESUMO_FINANCEIRO, 'S') EXIBIR_RESUMO_FINANCEIRO,
P.ATIVO, 1 ORDEM, C.DESC_GR, CT.DESC_DEP FROM P_CONTAS P
INNER JOIN GRUPOS_CT C ON P.GRUP_CT = C.GRUP_CT AND C.TIPO_GR = 'S'
LEFT JOIN SUB_GRUP_CT S ON P.COD_SUB_CT = S.COD_SUB_CT
LEFT JOIN CONTAS_A_PAGAR CTR ON P.N_CONTA_PLC = CTR.N_CONTA_PLC
LEFT JOIN EMPRESA EMP ON CTR.CODIGO_EMP = EMP.COD_EMPRESA
LEFT JOIN CONTROLES CC ON CTR.CODIGO_CTRL = CC.CODIGO_CTRL AND CTR.CODIGO_EMP = CC.CODIGO_EMP
LEFT JOIN DEPART_CT CT ON CT.COD_DEP = C.COD_DEP
WHERE -- CTR.DATQ_CTP >= :VDAT1 AND CTR.DATQ_CTP <= :VDAT2 AND CTR.CODIGO_EMP = 5
CTR.LOTE IS NOT NULL AND COALESCE(P.TIPO_CTP, '') <> 'F'
UNION
SELECT 2, 'CTP', 'DESPCTP',
(CASE WHEN(EMP.FINANCEIRO_UNIFICADO = 'S') THEN EMP.CODIGO_UNIFICADORA ELSE CTR.CODIGO_EMP END),
CTR.COD_EMP_MULT,
CTR.N_CONTA_PLC, CTR.DTREFERENCIA, CTR.N_DOC_CTP, CTR.VALOR_CTP,
TRIM(CTR.HISTORICO_CTP) || ' - ' || TRIM(CTR.NOME_FOR_CTP),
CTR.DATQ_CTP, CTR.COD_CONTRP, CTR.VALOR_PAGO,
CASE WHEN TRIM(COALESCE(P.DESC_PADR, '')) = '' THEN P.DESC_PLC ELSE P.DESC_PADR END DESC_PADR,
S.DESC_SUB_CT, P.TIPO_CTP, CC.NOME_CTRL,
COALESCE(CC.EXIBIR_RESUMO_FINANCEIRO, 'S') EXIBIR_RESUMO_FINANCEIRO,
P.ATIVO, 1 ORDEM, C.DESC_GR, CT.DESC_DEP FROM P_CONTAS P
INNER JOIN GRUPOS_CT C ON P.GRUP_CT = C.GRUP_CT AND C.TIPO_GR = 'S'
LEFT JOIN SUB_GRUP_CT S ON P.COD_SUB_CT = S.COD_SUB_CT
INNER JOIN CONTAS_A_PAGAR CTR ON P.N_CONTA_PLC = CTR.N_CONTA_PLC
INNER JOIN EMPRESA EMP ON CTR.CODIGO_EMP = EMP.COD_EMPRESA
INNER JOIN CONTROLES CC ON CTR.CODIGO_CTRL = CC.CODIGO_CTRL AND CTR.CODIGO_EMP = CC.CODIGO_EMP
LEFT JOIN DEPART_CT CT ON CT.COD_DEP = C.COD_DEP
WHERE -- CTR.DTREFERENCIA >= :VDAT1 AND CTR.DTREFERENCIA <= :VDAT2 AND CTR.CODIGO_EMP = 5
CTR.LOTE IS NOT NULL AND COALESCE(P.TIPO_CTP, '') <> 'F'
UNION
SELECT 1, 'LANC', 'DESPLANCFOR',
(CASE WHEN(EMP.FINANCEIRO_UNIFICADO = 'S') THEN EMP.CODIGO_UNIFICADORA ELSE L.CODIGO_EMP END),
L.COD_EMP_MULT,
L.N_CONTA_PLC, L.DATQ_L, L.NDOC_L, L.VALOR_L, L.HISTORICO_L, L.DATA, L.COD_LANC, L.VALOR_L,
CASE WHEN TRIM(COALESCE(P.DESC_PADR, '')) = '' THEN P.DESC_PLC ELSE P.DESC_PADR END DESC_PADR,
'PAGAMENTOS FORNECEDOR', P.TIPO_CTP, CC.NOME_CTRL,
COALESCE(CC.EXIBIR_RESUMO_FINANCEIRO, 'S') EXIBIR_RESUMO_FINANCEIRO,
P.ATIVO, 2 ORDEM, C.DESC_GR, CT.DESC_DEP FROM P_CONTAS P
INNER JOIN GRUPOS_CT C ON P.GRUP_CT = C.GRUP_CT
LEFT JOIN SUB_GRUP_CT S ON P.COD_SUB_CT = S.COD_SUB_CT
INNER JOIN LANCAMENTOS L ON P.N_CONTA_PLC = L.N_CONTA_PLC
INNER JOIN EMPRESA EMP ON L.CODIGO_EMP = EMP.COD_EMPRESA
INNER JOIN CONTROLES CC ON L.CODIGO_CTRL = CC.CODIGO_CTRL AND L.CODIGO_EMP = CC.CODIGO_EMP
LEFT JOIN DEPART_CT CT ON CT.COD_DEP = C.COD_DEP
WHERE --L.DATQ_L >= :VDAT1 AND L.DATQ_L <= :VDAT2 AND L.CODIGO_EMP = 5
L.LOTE IS NULL AND P.TIPO_CTP = 'F'
UNION
SELECT 2, 'LANC', 'DESPLANCFOR',
(CASE WHEN(EMP.FINANCEIRO_UNIFICADO = 'S') THEN EMP.CODIGO_UNIFICADORA ELSE L.CODIGO_EMP END),
L.COD_EMP_MULT,
L.N_CONTA_PLC, L.DTREFERENCIA, L.NDOC_L, L.VALOR_L, L.HISTORICO_L, L.DATA, L.COD_LANC, L.VALOR_L,
CASE WHEN TRIM(COALESCE(P.DESC_PADR, '')) = '' THEN P.DESC_PLC ELSE P.DESC_PADR END DESC_PADR,
'PAGAMENTOS FORNECEDOR', P.TIPO_CTP, CC.NOME_CTRL,
COALESCE(CC.EXIBIR_RESUMO_FINANCEIRO, 'S') EXIBIR_RESUMO_FINANCEIRO,
P.ATIVO, 2 ORDEM, C.DESC_GR, CT.DESC_DEP FROM P_CONTAS P
INNER JOIN GRUPOS_CT C ON P.GRUP_CT = C.GRUP_CT
LEFT JOIN SUB_GRUP_CT S ON P.COD_SUB_CT = S.COD_SUB_CT
INNER JOIN LANCAMENTOS L ON P.N_CONTA_PLC = L.N_CONTA_PLC
INNER JOIN EMPRESA EMP ON L.CODIGO_EMP = EMP.COD_EMPRESA
INNER JOIN CONTROLES CC ON L.CODIGO_CTRL = CC.CODIGO_CTRL AND L.CODIGO_EMP = CC.CODIGO_EMP
LEFT JOIN DEPART_CT CT ON CT.COD_DEP = C.COD_DEP
WHERE -- L.DTREFERENCIA >= :VDAT1 AND L.DTREFERENCIA <= :VDAT2 AND L.CODIGO_EMP = 5
L.LOTE IS NULL AND P.TIPO_CTP = 'F'
UNION
SELECT 1, 'CTP', 'DESPCTPFOR',
(CASE WHEN(EMP.FINANCEIRO_UNIFICADO = 'S') THEN EMP.CODIGO_UNIFICADORA ELSE CTR.CODIGO_EMP END),
CTR.COD_EMP_MULT,
CTR.N_CONTA_PLC, CTR.DATQ_CTP, CTR.N_DOC_CTP, CTR.VALOR_CTP,
TRIM(CTR.HISTORICO_CTP) || ' - ' || TRIM(CTR.NOME_FOR_CTP),
CTR.DATQ_CTP, CTR.COD_CONTRP, CTR.VALOR_PAGO,
CASE WHEN TRIM(COALESCE(P.DESC_PADR, '')) = '' THEN P.DESC_PLC ELSE P.DESC_PADR END DESC_PADR,
'PAGAMENTOS FORNECEDOR', P.TIPO_CTP, CC.NOME_CTRL,
COALESCE(CC.EXIBIR_RESUMO_FINANCEIRO, 'S') EXIBIR_RESUMO_FINANCEIRO,
P.ATIVO, 2 ORDEM, C.DESC_GR, CT.DESC_DEP FROM P_CONTAS P
INNER JOIN GRUPOS_CT C ON P.GRUP_CT = C.GRUP_CT
LEFT JOIN SUB_GRUP_CT S ON P.COD_SUB_CT = S.COD_SUB_CT
INNER JOIN CONTAS_A_PAGAR CTR ON P.N_CONTA_PLC = CTR.N_CONTA_PLC
INNER JOIN EMPRESA EMP ON CTR.CODIGO_EMP = EMP.COD_EMPRESA
INNER JOIN CONTROLES CC ON CTR.CODIGO_CTRL = CC.CODIGO_CTRL AND CTR.CODIGO_EMP = CC.CODIGO_EMP
LEFT JOIN DEPART_CT CT ON CT.COD_DEP = C.COD_DEP
WHERE -- CTR.DATQ_CTP >= :VDAT1 AND CTR.DATQ_CTP <= :VDAT2 AND CTR.CODIGO_EMP = 5
CTR.LOTE IS NOT NULL AND P.TIPO_CTP = 'F'
UNION
SELECT 2, 'CTP', 'DESPCTPFOR',
(CASE WHEN(EMP.FINANCEIRO_UNIFICADO = 'S') THEN EMP.CODIGO_UNIFICADORA ELSE CTR.CODIGO_EMP END),
CTR.COD_EMP_MULT,
CTR.N_CONTA_PLC, CTR.DTREFERENCIA, CTR.N_DOC_CTP, CTR.VALOR_CTP,
TRIM(CTR.HISTORICO_CTP) || ' - ' || TRIM(CTR.NOME_FOR_CTP),
CTR.DATQ_CTP, CTR.COD_CONTRP, CTR.VALOR_PAGO,
CASE WHEN TRIM(COALESCE(P.DESC_PADR, '')) = '' THEN P.DESC_PLC ELSE P.DESC_PADR END DESC_PADR,
'PAGAMENTOS FORNECEDOR', P.TIPO_CTP, CC.NOME_CTRL,
COALESCE(CC.EXIBIR_RESUMO_FINANCEIRO, 'S') EXIBIR_RESUMO_FINANCEIRO,
P.ATIVO, 2 ORDEM, C.DESC_GR, CT.DESC_DEP FROM P_CONTAS P
INNER JOIN GRUPOS_CT C ON P.GRUP_CT = C.GRUP_CT
LEFT JOIN SUB_GRUP_CT S ON P.COD_SUB_CT = S.COD_SUB_CT
INNER JOIN CONTAS_A_PAGAR CTR ON P.N_CONTA_PLC = CTR.N_CONTA_PLC
INNER JOIN EMPRESA EMP ON CTR.CODIGO_EMP = EMP.COD_EMPRESA
INNER JOIN CONTROLES CC ON CTR.CODIGO_CTRL = CC.CODIGO_CTRL AND CTR.CODIGO_EMP = CC.CODIGO_EMP
LEFT JOIN DEPART_CT CT ON CT.COD_DEP = C.COD_DEP
WHERE -- CTR.DTREFERENCIA >= :VDAT1 AND CTR.DTREFERENCIA <= :VDAT2 AND CTR.CODIGO_EMP = 5
CTR.LOTE IS NOT NULL AND P.TIPO_CTP = 'F'
;

/* View: ENTRADASSAIDASDIVERAS, Owner: SYSDBA */
CREATE VIEW ENTRADASSAIDASDIVERAS (TPDTQUIT_DTREF, E_S, COD_LANC, LOTE, COD_EMPRESA, COD_EMP_MULT, N_CONTA_PLC, DESC_PLC, DESC_REL, COD_CONTRLE, NOME_CTRL, DOCS, DATA, VALOR, HISTORICO, TIPO_CTP) AS

-- VIEW EXIBE OS LANCAMENTOS AVULSOS REALIZADOS
-- RELATORIO "RESUMO FINANCEIRO" EXIBIDO NO GRUPO ENTRADAS/SAIDAS DIVERSAS
    select 1, lanc.tipo_l, lanc.cod_lanc,
    (case when (coalesce(lanc.lote, 0) > 0) then lanc.lote else (case when (lanc.lote_quit >0) then lanc.lote_quit else lanc.lote_ent end) end),
    lanc.codigo_emp, lanc.cod_emp_mult, lanc.n_conta_plc, plano.desc_plc, rel.descricao desc_rel,
    lanc.codigo_ctrl, ctr.nome_ctrl, ctr.docs,
    lanc.data, lanc.valor_l, lanc.historico_l, plano.tipo_ctp from lancamentos lanc
    inner join p_contas plano on plano.n_conta_plc = lanc.n_conta_plc
    inner join p_contas_rel rel on rel.codigo = plano.cod_conta_rel
    inner join grupos_ct c on plano.grup_ct = c.grup_ct
    left join CONTROLES ctr on lanc.codigo_ctrl = ctr.codigo_ctrl and lanc.codigo_emp = ctr.codigo_emp
    where lanc.tipo_l = 'E'
    and rel.descricao <> 'CORRECAO DE SALDO' -- and plano.tipo_ctp in ('E', 'T', 'O')
    and ctr.docs = 'N'
    and (select count(*) from baixa_creditos bx where bx.lote_quit = lanc.lote_ent and bx.codigo_emp = lanc.codigo_emp/* and bx.datq_c = lanc.data*/) = 0
    and (select count(*) from controle_creditos cc where cc.lote_quit = lanc.lote_ent and cc.codigo_emp = lanc.codigo_emp/* and cc.datq_c = lanc.data*/) = 0
    and (select count(*) from controle_cheque ch where ch.lote_quit = lanc.lote_ent and ch.codigo_emp = lanc.codigo_emp/* and ch.datq_ch = lanc.data*/) = 0

    union

    select 2, lanc.tipo_l, lanc.cod_lanc,
    (case when (coalesce(lanc.lote, 0) > 0) then lanc.lote else (case when (lanc.lote_quit >0) then lanc.lote_quit else lanc.lote_ent end) end),
    lanc.codigo_emp, lanc.cod_emp_mult, lanc.n_conta_plc, plano.desc_plc, rel.descricao desc_rel,
    lanc.codigo_ctrl, ctr.nome_ctrl, ctr.docs,
    lanc.dtreferencia, lanc.valor_l, lanc.historico_l, plano.tipo_ctp from lancamentos lanc
    inner join p_contas plano on plano.n_conta_plc = lanc.n_conta_plc
    inner join p_contas_rel rel on rel.codigo = plano.cod_conta_rel
    inner join grupos_ct c on plano.grup_ct = c.grup_ct
    left join CONTROLES ctr on lanc.codigo_ctrl = ctr.codigo_ctrl and lanc.codigo_emp = ctr.codigo_emp
    where lanc.tipo_l = 'E'
    and rel.descricao <> 'CORRECAO DE SALDO' -- and plano.tipo_ctp in ('E', 'T', 'O')
    and ctr.docs = 'N'
    and (select count(*) from baixa_creditos bx where bx.lote_quit = lanc.lote_ent and bx.codigo_emp = lanc.codigo_emp/* and bx.datq_c = lanc.data*/) = 0
    and (select count(*) from controle_creditos cc where cc.lote_quit = lanc.lote_ent and cc.codigo_emp = lanc.codigo_emp/* and cc.datq_c = lanc.data*/) = 0
    and (select count(*) from controle_cheque ch where ch.lote_quit = lanc.lote_ent and ch.codigo_emp = lanc.codigo_emp/* and ch.datq_ch = lanc.data*/) = 0

    union

    select 1, lanc.tipo_l, lanc.cod_lanc,
    (case when (coalesce(lanc.lote, 0) > 0) then lanc.lote else (case when (lanc.lote_quit >0) then lanc.lote_quit else lanc.lote_ent end) end),
    lanc.codigo_emp, lanc.cod_emp_mult, lanc.n_conta_plc, plano.desc_plc, rel.descricao desc_rel,
    lanc.codigo_ctrl, ctr.nome_ctrl, ctr.docs,
    lanc.data, (- lanc.valor_l) valor_l, lanc.historico_l, plano.tipo_ctp from lancamentos lanc
    left join empresa emp on lanc.codigo_emp = emp.cod_empresa
    inner join p_contas plano on plano.n_conta_plc = lanc.n_conta_plc
    inner join p_contas_rel rel on rel.codigo = plano.cod_conta_rel
    inner join grupos_ct c on plano.grup_ct = c.grup_ct and coalesce(c.tipo_gr, '') <> 'S'
    left join CONTROLES ctr on lanc.codigo_ctrl = ctr.codigo_ctrl and lanc.codigo_emp = ctr.codigo_emp
    where lanc.tipo_l = 'S'
    and rel.descricao <> 'CORRECAO DE SALDO' -- and plano.tipo_ctp in ('O')
    and ctr.docs = 'N'
    and (select count(*) from formpagamento fp
        left join lanccxl cxl on cxl.cod_lancxl = fp.nrequisicao and cxl.codigo_emp = fp.cod_empresa and fp.tpdocs = 'LCS'
        inner join p_contas p on p.n_conta_plc = lanc.n_conta_plc
        inner join grupos_ct c on p.grup_ct = c.grup_ct
        left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
        where fp.n_processamento = lanc.cod_lanc
        and fp.cod_empresa = (case when(emp.financeiro_unificado = 'S') then lanc.cod_emp_mult else lanc.codigo_emp end)
        and coalesce(p.tipo_ctp, '') <> 'F' and c.tipo_gr <> 'S'
        and cxl.tipo_lanc_cxl = 'S' and cxl.refrecibo = 'S') = 0

    and lanc.lote is null

    union

    select 2, lanc.tipo_l, lanc.cod_lanc,
    (case when (coalesce(lanc.lote, 0) > 0) then lanc.lote else (case when (lanc.lote_quit >0) then lanc.lote_quit else lanc.lote_ent end) end),
    lanc.codigo_emp, lanc.cod_emp_mult, lanc.n_conta_plc, plano.desc_plc, rel.descricao desc_rel,
    lanc.codigo_ctrl, ctr.nome_ctrl, ctr.docs,
    lanc.dtreferencia, (- lanc.valor_l) valor_l, lanc.historico_l, plano.tipo_ctp from lancamentos lanc
    left join empresa emp on lanc.codigo_emp = emp.cod_empresa
    inner join p_contas plano on plano.n_conta_plc = lanc.n_conta_plc
    inner join p_contas_rel rel on rel.codigo = plano.cod_conta_rel
    inner join grupos_ct c on plano.grup_ct = c.grup_ct and coalesce(c.tipo_gr, '') <> 'S'
    left join CONTROLES ctr on lanc.codigo_ctrl = ctr.codigo_ctrl and lanc.codigo_emp = ctr.codigo_emp
    where lanc.tipo_l = 'S'
    and rel.descricao <> 'CORRECAO DE SALDO' -- and plano.tipo_ctp in ('O')
    and ctr.docs = 'N'
    and (select count(*) from formpagamento fp
        left join lanccxl cxl on cxl.cod_lancxl = fp.nrequisicao and cxl.codigo_emp = fp.cod_empresa and fp.tpdocs = 'LCS'
        inner join p_contas p on p.n_conta_plc = lanc.n_conta_plc
        inner join grupos_ct c on p.grup_ct = c.grup_ct
        left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
        where fp.n_processamento = lanc.cod_lanc
        and fp.cod_empresa = (case when(emp.financeiro_unificado = 'S') then lanc.cod_emp_mult else lanc.codigo_emp end)
        and coalesce(p.tipo_ctp, '') <> 'F' and c.tipo_gr <> 'S'
        and cxl.tipo_lanc_cxl = 'S' and cxl.refrecibo = 'S') = 0

    and lanc.lote is null

    union

    select 1, 'S',
    coalesce((select first 1 lanc.cod_lanc from lancamentos lanc where lanc.lote = ctp.lote and lanc.codigo_emp = ctp.codigo_emp), 0) cod_lanc,
    ctp.lote,
    ctp.codigo_emp, ctp.cod_emp_mult, ctp.n_conta_plc, plano.desc_plc, rel.descricao desc_rel,
    ctp.codigo_ctrl, ctr.nome_ctrl, ctr.docs,
    ctp.datq_ctp, (- ctp.valor_ctp) valor_ctp,
    trim(coalesce(ctp.historico_ctp, '')) || ' - ' || trim(coalesce(ctp.nome_for_ctp, '')),
    plano.tipo_ctp from p_contas plano
    inner join p_contas_rel rel on rel.codigo = plano.cod_conta_rel
    inner join grupos_ct c on plano.grup_ct = c.grup_ct and coalesce(c.tipo_gr, '') <> 'S'
    left join sub_grup_ct s on plano.cod_sub_ct = s.cod_sub_ct
    inner join contas_a_pagar ctp on plano.n_conta_plc = ctp.n_conta_plc
    inner join controles ctr on ctp.codigo_ctrl = ctr.codigo_ctrl and ctp.codigo_emp = ctr.codigo_emp
    where rel.descricao <> 'CORRECAO DE SALDO' -- plano.tipo_ctp in ('O')
    and ctp.lote is not null

    union

    select 2, 'S',
    coalesce((select first 1 lanc.cod_lanc from lancamentos lanc where lanc.lote = ctp.lote and lanc.codigo_emp = ctp.codigo_emp), 0) cod_lanc,
    ctp.lote,
    ctp.codigo_emp, ctp.cod_emp_mult, ctp.n_conta_plc, plano.desc_plc, rel.descricao desc_rel,
    ctp.codigo_ctrl, ctr.nome_ctrl, ctr.docs,
    ctp.dtreferencia, (- ctp.valor_ctp) valor_ctp,
    trim(coalesce(ctp.historico_ctp, '')) || ' - ' || trim(coalesce(ctp.nome_for_ctp, '')), plano.tipo_ctp from p_contas plano
    inner join p_contas_rel rel on rel.codigo = plano.cod_conta_rel
    inner join grupos_ct c on plano.grup_ct = c.grup_ct and coalesce(c.tipo_gr, '') <> 'S'
    left join sub_grup_ct s on plano.cod_sub_ct = s.cod_sub_ct
    inner join contas_a_pagar ctp on plano.n_conta_plc = ctp.n_conta_plc
    inner join controles ctr on ctp.codigo_ctrl = ctr.codigo_ctrl and ctp.codigo_emp = ctr.codigo_emp
    where rel.descricao <> 'CORRECAO DE SALDO' -- plano.tipo_ctp in ('O')
    and ctp.lote is not null

    union

    -- CORRECAO SALDO
    select 1, lanc.tipo_l, lanc.cod_lanc,
    (case when (coalesce(lanc.lote, 0) > 0) then lanc.lote else (case when (lanc.lote_quit >0) then lanc.lote_quit else lanc.lote_ent end) end),
    lanc.codigo_emp, lanc.cod_emp_mult, lanc.n_conta_plc, plano.desc_plc, rel.descricao desc_rel,
    lanc.codigo_ctrl, ctr.nome_ctrl, ctr.docs,
    lanc.data, case when (lanc.tipo_l = 'S') then (- lanc.valor_l) else lanc.valor_l end, lanc.historico_l,
    plano.tipo_ctp from lancamentos lanc
    inner join p_contas plano on plano.n_conta_plc = lanc.n_conta_plc
    inner join p_contas_rel rel on rel.codigo = plano.cod_conta_rel
    inner join grupos_ct c on plano.grup_ct = c.grup_ct 
    left join CONTROLES ctr on lanc.codigo_ctrl = ctr.codigo_ctrl and lanc.codigo_emp = ctr.codigo_emp
    where lanc.tipo_l = 'E'
    and rel.descricao = 'CORRECAO DE SALDO' -- and plano.tipo_ctp in ('Z')
    and (select count(*) from baixa_creditos bx where bx.lote_quit = lanc.lote_ent and bx.codigo_emp = lanc.codigo_emp/* and bx.datq_c = lanc.data*/) = 0
    and (select count(*) from controle_creditos cc where cc.lote_quit = lanc.lote_ent and cc.codigo_emp = lanc.codigo_emp/* and cc.datq_c = lanc.data*/) = 0
    and (select count(*) from controle_cheque ch where ch.lote_quit = lanc.lote_ent and ch.codigo_emp = lanc.codigo_emp/* and ch.datq_ch = lanc.data*/) = 0

    union

