    lanc.dtreferencia, case when (lanc.tipo_l = 'S') then (- lanc.valor_l) else lanc.valor_l end, lanc.historico_l,
    plano.tipo_ctp from lancamentos lanc
    inner join p_contas plano on plano.n_conta_plc = lanc.n_conta_plc
    inner join p_contas_rel rel on rel.codigo = plano.cod_conta_rel
    inner join grupos_ct c on plano.grup_ct = c.grup_ct 
    left join CONTROLES ctr on lanc.codigo_ctrl = ctr.codigo_ctrl and lanc.codigo_emp = ctr.codigo_emp
    where lanc.tipo_l = 'E'
    and rel.descricao = 'CORRECAO DE SALDO' -- and plano.tipo_ctp in ('Z')
    and (select count(*) from baixa_creditos bx where bx.lote_quit = lanc.lote_ent and bx.codigo_emp = lanc.codigo_emp/* and bx.datq_c = lanc.data*/) = 0
    and (select count(*) from controle_creditos cc where cc.lote_quit = lanc.lote_ent and cc.codigo_emp = lanc.codigo_emp/* and cc.datq_c = lanc.data*/) = 0
    and (select count(*) from controle_cheque ch where ch.lote_quit = lanc.lote_ent and ch.codigo_emp = lanc.codigo_emp/* and ch.datq_ch = lanc.data*/) = 0

    union

    select 1, lanc.tipo_l, lanc.cod_lanc,
    (case when (coalesce(lanc.lote, 0) > 0) then lanc.lote else (case when (lanc.lote_quit >0) then lanc.lote_quit else lanc.lote_ent end) end),
    lanc.codigo_emp, lanc.cod_emp_mult, lanc.n_conta_plc, plano.desc_plc, rel.descricao desc_rel,
    lanc.codigo_ctrl, ctr.nome_ctrl, ctr.docs,
    lanc.data, case when (lanc.tipo_l = 'S') then (- lanc.valor_l) else lanc.valor_l end, lanc.historico_l,
    plano.tipo_ctp from lancamentos lanc
    left join empresa emp on lanc.codigo_emp = emp.cod_empresa
    inner join p_contas plano on plano.n_conta_plc = lanc.n_conta_plc
    inner join p_contas_rel rel on rel.codigo = plano.cod_conta_rel
    inner join grupos_ct c on plano.grup_ct = c.grup_ct and coalesce(c.tipo_gr, '') <> 'S'
    left join CONTROLES ctr on lanc.codigo_ctrl = ctr.codigo_ctrl and lanc.codigo_emp = ctr.codigo_emp
    where lanc.tipo_l = 'S'
    and rel.descricao = 'CORRECAO DE SALDO' -- and plano.tipo_ctp in ('Z')
    and (select count(*) from formpagamento fp
        left join lanccxl cxl on cxl.cod_lancxl = fp.nrequisicao and cxl.codigo_emp = fp.cod_empresa and fp.tpdocs = 'LCS'
        inner join p_contas p on p.n_conta_plc = lanc.n_conta_plc
        inner join grupos_ct c on p.grup_ct = c.grup_ct
        left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
        where fp.n_processamento = lanc.cod_lanc
        and fp.cod_empresa = (case when(emp.financeiro_unificado = 'S') then lanc.cod_emp_mult else lanc.codigo_emp end)
        and coalesce(p.tipo_ctp, '') <> 'F' and c.tipo_gr <> 'S'
        and cxl.tipo_lanc_cxl = 'S' and cxl.refrecibo = 'S') = 0

    union

    select 2, lanc.tipo_l, lanc.cod_lanc,
    (case when (coalesce(lanc.lote, 0) > 0) then lanc.lote else (case when (lanc.lote_quit >0) then lanc.lote_quit else lanc.lote_ent end) end),
    lanc.codigo_emp, lanc.cod_emp_mult, lanc.n_conta_plc, plano.desc_plc, rel.descricao desc_rel,
    lanc.codigo_ctrl, ctr.nome_ctrl, ctr.docs,
    lanc.dtreferencia, case when (lanc.tipo_l = 'S') then (- lanc.valor_l) else lanc.valor_l end, lanc.historico_l,
    plano.tipo_ctp from lancamentos lanc
    left join empresa emp on lanc.codigo_emp = emp.cod_empresa
    inner join p_contas plano on plano.n_conta_plc = lanc.n_conta_plc
    inner join p_contas_rel rel on rel.codigo = plano.cod_conta_rel
    inner join grupos_ct c on plano.grup_ct = c.grup_ct and coalesce(c.tipo_gr, '') <> 'S'
    left join CONTROLES ctr on lanc.codigo_ctrl = ctr.codigo_ctrl and lanc.codigo_emp = ctr.codigo_emp
    where lanc.tipo_l = 'S'
    and rel.descricao = 'CORRECAO DE SALDO' -- and plano.tipo_ctp in ('Z')
    and (select count(*) from formpagamento fp
        left join lanccxl cxl on cxl.cod_lancxl = fp.nrequisicao and cxl.codigo_emp = fp.cod_empresa and fp.tpdocs = 'LCS'
        inner join p_contas p on p.n_conta_plc = lanc.n_conta_plc
        inner join grupos_ct c on p.grup_ct = c.grup_ct
        left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
        where fp.n_processamento = lanc.cod_lanc
        and fp.cod_empresa = (case when(emp.financeiro_unificado = 'S') then lanc.cod_emp_mult else lanc.codigo_emp end)
        and coalesce(p.tipo_ctp, '') <> 'F' and c.tipo_gr <> 'S'
        and cxl.tipo_lanc_cxl = 'S' and cxl.refrecibo = 'S') = 0
;

/* View: RECEBIMENTOS4, Owner: SYSDBA */
CREATE VIEW RECEBIMENTOS4 (TPDTQUIT_DTREF, ORDEM, TIPO, TIPO2, COD_EMPRESA, COD_EMP_MULT, DATA_CONF, CODIGO_CTRL, NOME_CTRL, EXIBIR_RESUMO_FINANCEIRO, DOCS, DOCS2, DOCS3, VALOR_PAGO, SEQID, SEQID2, HISTORICO, HISTORICO2, QTDE_PREST, CODIGO, TIPO_LOTE, LOTE, TIPO_LANC, COD_LANC, NREQUISICAO, TIP_BAIXA) AS

-- VIEW EXIBE OS RECEBIMENTOS A VISTA E RECEBIMENTOS DO CREDIARIO (CREDITOS/CHEQUES)
-- RELATORIO "RESUMO FINANCEIRO" EXIBIDO NA PARTE DOS RECEBIMENTOS
    select 1, 1, fp.tpdocs, fp.tpdocs,
    (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else lanc.codigo_emp end) cod_empresa,
    lanc.cod_emp_mult, lanc.data,
    case when ctr.nome_ctrl is null then 0 else lanc.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    coalesce(ctr.exibir_resumo_financeiro, 'S') exibir_resumo_financeiro,
    case when ctr.nome_ctrl is null then 'N' else ctr.docs end docs, ctr.docs docs2, ctr.docs docs3,
    coalesce(fp.valordoc, 0) valordoc,
    coalesce(fp.seqform, fp.nrequisicao), coalesce(fp.seqform, fp.nrequisicao),
    trim(lanc.historico_l) ||' - ' || trim(fp.cliente), trim(lanc.historico_l),
    1 qtde_prest, lanc.cod_lanc,
    'LOTE', (case when (lanc.lote_quit >0) then lanc.lote_quit else lanc.lote_ent end),
    'LANC', lanc.cod_lanc,
    fp.nrequisicao, null tip_baixa
    from lancamentos lanc
    left join empresa emp on lanc.codigo_emp = emp.cod_empresa
    inner join formpagamento fp on
        fp.n_processamento = lanc.cod_lanc
        and fp.cod_empresa = (case when(emp.financeiro_unificado = 'S') then lanc.cod_emp_mult else lanc.codigo_emp end)
    left join lanccxl cxl on cxl.cod_lancxl = fp.nrequisicao and cxl.codigo_emp = fp.cod_empresa and fp.tpdocs = 'LCS'
    inner join p_contas p on p.n_conta_plc = lanc.n_conta_plc
    inner join grupos_ct c on p.grup_ct = c.grup_ct
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where coalesce(p.tipo_ctp, '') <> 'F' and c.tipo_gr <> 'S' and coalesce(cxl.cod_lancxl, 0) = 0

    union
    
    select 2, 1, fp.tpdocs, fp.tpdocs,
    (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else lanc.codigo_emp end) cod_empresa,
    lanc.cod_emp_mult, lanc.dtreferencia,
    case when ctr.nome_ctrl is null then 0 else lanc.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    coalesce(ctr.exibir_resumo_financeiro, 'S') exibir_resumo_financeiro,
    case when ctr.nome_ctrl is null then 'N' else ctr.docs end docs, ctr.docs docs2, ctr.docs docs3,
    coalesce(fp.valordoc, 0) valordoc,
    coalesce(fp.seqform, fp.nrequisicao), coalesce(fp.seqform, fp.nrequisicao),
    trim(lanc.historico_l) ||' - ' || trim(fp.cliente), trim(lanc.historico_l),
    1 qtde_prest, lanc.cod_lanc,
    'LOTE', (case when (lanc.lote_quit >0) then lanc.lote_quit else lanc.lote_ent end),
    'LANC', lanc.cod_lanc,
    fp.nrequisicao, null tip_baixa
    from lancamentos lanc
    left join empresa emp on lanc.codigo_emp = emp.cod_empresa
    inner join formpagamento fp on
        fp.n_processamento = lanc.cod_lanc
        and fp.cod_empresa = (case when(emp.financeiro_unificado = 'S') then lanc.cod_emp_mult else lanc.codigo_emp end)
    left join lanccxl cxl on cxl.cod_lancxl = fp.nrequisicao and cxl.codigo_emp = fp.cod_empresa and fp.tpdocs = 'LCS'
    inner join p_contas p on p.n_conta_plc = lanc.n_conta_plc
    inner join grupos_ct c on p.grup_ct = c.grup_ct
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where coalesce(p.tipo_ctp, '') <> 'F' and c.tipo_gr <> 'S' and coalesce(cxl.cod_lancxl, 0) = 0

    union

    select 1, 1, fp.tpdocs, fp.tpdocs,
    (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else lanc.codigo_emp end) cod_empresa,
    lanc.cod_emp_mult, lanc.data,
    case when ctr.nome_ctrl is null then 0 else lanc.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    coalesce(ctr.exibir_resumo_financeiro, 'S') exibir_resumo_financeiro,
    case when ctr.nome_ctrl is null then 'N' else ctr.docs end docs, ctr.docs docs2, ctr.docs docs3,
    coalesce(fp.valordoc, 0) valordoc,
    coalesce(fp.seqform, fp.nrequisicao), coalesce(fp.seqform, fp.nrequisicao),
    trim(lanc.historico_l) ||' - ' || trim(fp.cliente), trim(lanc.historico_l),
    1 qtde_prest, lanc.cod_lanc,
    'LOTE', (case when (lanc.lote_quit >0) then lanc.lote_quit else lanc.lote_ent end),
    'LANC', lanc.cod_lanc,
    fp.nrequisicao, null tip_baixa
    from lancamentos lanc
    left join empresa emp on lanc.codigo_emp = emp.cod_empresa
    inner join formpagamento fp on
        fp.n_processamento = lanc.cod_lanc
        and fp.cod_empresa = (case when(emp.financeiro_unificado = 'S') then lanc.cod_emp_mult else lanc.codigo_emp end)
    left join lanccxl cxl on cxl.cod_lancxl = fp.nrequisicao and cxl.codigo_emp = fp.cod_empresa and fp.tpdocs = 'LCS'
    inner join p_contas p on p.n_conta_plc = lanc.n_conta_plc
    inner join grupos_ct c on p.grup_ct = c.grup_ct
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where coalesce(p.tipo_ctp, '') <> 'F' and c.tipo_gr <> 'S'
    and cxl.tipo_lanc_cxl = 'S' and cxl.refrecibo = 'S'

    union

    select 2, 1, fp.tpdocs, fp.tpdocs,
    (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else lanc.codigo_emp end) cod_empresa,
    lanc.cod_emp_mult, lanc.dtreferencia,
    case when ctr.nome_ctrl is null then 0 else lanc.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    coalesce(ctr.exibir_resumo_financeiro, 'S') exibir_resumo_financeiro,
    case when ctr.nome_ctrl is null then 'N' else ctr.docs end docs, ctr.docs docs2, ctr.docs docs3,
    coalesce(fp.valordoc, 0) valordoc,
    coalesce(fp.seqform, fp.nrequisicao), coalesce(fp.seqform, fp.nrequisicao),
    trim(lanc.historico_l) ||' - ' || trim(fp.cliente), trim(lanc.historico_l),
    1 qtde_prest, lanc.cod_lanc,
    'LOTE', (case when (lanc.lote_quit >0) then lanc.lote_quit else lanc.lote_ent end),
    'LANC', lanc.cod_lanc,
    fp.nrequisicao, null tip_baixa
    from lancamentos lanc
    left join empresa emp on lanc.codigo_emp = emp.cod_empresa
    inner join formpagamento fp on
        fp.n_processamento = lanc.cod_lanc
        and fp.cod_empresa = (case when(emp.financeiro_unificado = 'S') then lanc.cod_emp_mult else lanc.codigo_emp end)
    left join lanccxl cxl on cxl.cod_lancxl = fp.nrequisicao and cxl.codigo_emp = fp.cod_empresa and fp.tpdocs = 'LCS'
    inner join p_contas p on p.n_conta_plc = lanc.n_conta_plc
    inner join grupos_ct c on p.grup_ct = c.grup_ct
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where coalesce(p.tipo_ctp, '') <> 'F' and c.tipo_gr <> 'S'
    and cxl.tipo_lanc_cxl = 'S' and cxl.refrecibo = 'S'

    -- Cred
    
    union
    
    select 0, 2, 'CREDIARIO', case when (ctr1.nome_ctrl is null) then pr.tipo_doc_c else ctr1.nome_ctrl end tipo2,
    (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pr.codigo_emp end) cod_empresa,
    pr.cod_emp_mult, pr.datq_c,
    case when(pr.tip_baixa = 'C') then ctr1.codigo_ctrl else case when ctr.codigo_ctrl is null then 0 else ctr.codigo_ctrl end end codigo_ctrl,
    case when(pr.tip_baixa = 'C') then ctr1.nome_ctrl else case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end end nome_ctrl,
    coalesce(ctr.exibir_resumo_financeiro, 'S') exibir_resumo_financeiro,
    'N' docs, case when(pr.tip_baixa = 'C') then 'S2' else ctr.docs end docs2, case when(pr.tip_baixa = 'C') then 'N' else ctr.docs end docs3,
    case when(pr.tip_baixa = 'C') then pr.valor_quitado else case when(l.tipo_l = 'S') then (coalesce(l.valor_l, 0) * -1) else coalesce(l.valor_l, 0) end end valor_pago,
    coalesce(l.cod_lanc, pr.seq_bxcred), 0,
    trim(pr.historico_c) ||' - '|| trim(pr.nome_c), coalesce(trim(l.historico_l), coalesce(trim(pr.historico_c) , '')),
    coalesce((case when ((select count(*) from baixa_creditos bc
                          where bc.lote_quit = pr.lote_quit
                          and bc.datq_c = iif(emp.financeiro_unificado = 'S', pr.datq_c, bc.datq_c)
                          and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, bc.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp)) = 0) then
        1
    else
        (select count(*) from baixa_creditos bc
         where bc.lote_quit = pr.lote_quit
         and bc.datq_c = iif(emp.financeiro_unificado = 'S', pr.datq_c, bc.datq_c)
         and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, bc.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp))
    end), 1) qtde_prest, pr.SEQ_BXCRED,
    case when(pr.tip_baixa = 'C') then 'LOTE PG' else 'LOTE' end,
    case when(pr.tip_baixa = 'C') then pr.lote else pr.lote_quit end,
    case when(pr.tip_baixa = 'C') then 'CRED' else 'LANC' end,
    case when(pr.tip_baixa = 'C') then pr.seq_bxcred else l.cod_lanc end cod_lanc,
    0, pr.tip_baixa
    from baixa_creditos pr
    left join empresa emp on pr.codigo_emp = emp.cod_empresa
    left join controle_creditos cc on cc.cod_cred = pr.cod_cred and cc.codigo_emp = pr.codigo_emp
    left join lancamentos l on
        l.lote_ent = pr.lote_quit
        and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, l.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp)
        and l.data = pr.datq_c
    left join CONTROLES ctr on ctr.codigo_ctrl = l.codigo_ctrl and ctr.codigo_emp = l.codigo_emp
    left join CONTROLES ctr1 on ctr1.codigo_ctrl = pr.codigo_ctrl and ctr1.codigo_emp = pr.codigo_emp
    where pr.datq_c is not null
    
    union
    
    select 0, 2, 'CREDIARIO', case when (ctr1.nome_ctrl is null) then pr.tipo_doc_c else ctr1.nome_ctrl end tipo2,
    (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pr.codigo_emp end) cod_empresa,
    pr.cod_emp_mult, pr.data_rec_c,
    case when ctr.codigo_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    coalesce(ctr.exibir_resumo_financeiro, 'S') exibir_resumo_financeiro,
    'N' docs, ctr.docs docs2, ctr.docs docs3,
    case when(l.tipo_l = 'S') then (coalesce(l.valor_l, 0) * -1) else coalesce(l.valor_l, 0) end valor_pago,
    coalesce(l.cod_lanc, pr.seq_bxcred), 0,
    trim(pr.historico_c) ||' - '|| trim(pr.nome_c), coalesce(trim(l.historico_l), coalesce(trim(pr.historico_c) , '')),
    coalesce((case when ((select count(*) from baixa_creditos bc
                          where bc.lote_quit = pr.lote_quit
                          and bc.datq_c = iif(emp.financeiro_unificado = 'S', pr.datq_c, bc.datq_c)
                          and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, bc.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp)) = 0) then
        1
    else
        (select count(*) from baixa_creditos bc
         where bc.lote_quit = pr.lote_quit
         and bc.datq_c = iif(emp.financeiro_unificado = 'S', pr.datq_c, bc.datq_c)
         and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, bc.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp))
    end), 1) qtde_prest, pr.SEQ_BXCRED,
    'LOTE', pr.lote_quit,
    'LANC', l.cod_lanc,
    0, pr.tip_baixa
    from baixa_creditos pr
    left join empresa emp on pr.codigo_emp = emp.cod_empresa
    left join clientes cl on cl.cod_cliente = pr.cod_cliente and cl.cod_empresa = pr.codigo_emp
    left join controle_creditos cc on cc.cod_cred = pr.cod_cred and cc.codigo_emp = pr.codigo_emp
    left join lancamentos l on
        l.lote_ent = pr.lote_quit
        and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, l.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp)
        and l.data = pr.data_rec_c
    left join CONTROLES ctr on ctr.codigo_ctrl = l.codigo_ctrl and ctr.codigo_emp = l.codigo_emp
    left join CONTROLES ctr1 on ctr1.codigo_ctrl = pr.codigo_ctrl and ctr1.codigo_emp = pr.codigo_emp
    where pr.datq_c is null
    
    union
    
    select 0, 2, 'CREDIARIO', case when (ctr1.nome_ctrl is null) then '' else ctr1.nome_ctrl end tipo2,
    (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pr.codigo_emp end) cod_empresa,
    pr.cod_emp_mult, pr.data_rec_c,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    coalesce(ctr.exibir_resumo_financeiro, 'S') exibir_resumo_financeiro,
    'N' docs, ctr.docs docs2, ctr.docs docs3,
    case when(l.tipo_l = 'S') then (coalesce(l.valor_l, 0) * -1) else coalesce(l.valor_l, 0) end valor_pago,
    coalesce(l.cod_lanc, pr.cod_cred), 0,
    trim(pr.historico_c) || ' - '|| trim(pr.nome_c), coalesce(trim(l.historico_l), coalesce(trim(pr.historico_c) , '')),
    1 qtde_prest, pr.cod_cred,
    'LOTE', pr.lote_quit,
    'LANC', l.cod_lanc,
    0, pr.tip_baixa
    from controle_creditos pr
    left join empresa emp on pr.codigo_emp = emp.cod_empresa
    left join lancamentos l on
        l.lote_ent = pr.lote_quit
        and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, l.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp)
        and l.data = pr.data_rec_c
    left join CONTROLES ctr on ctr.codigo_ctrl = l.codigo_ctrl and ctr.codigo_emp = l.codigo_emp
    left join CONTROLES ctr1 on ctr1.codigo_ctrl = pr.codigo_ctrl and ctr1.codigo_emp = pr.codigo_emp
    where coalesce(pr.status_c, '') = '' and pr.datq_c is null
    
    union
    
    select 0, 2, 'CREDIARIO', case when (ctr1.nome_ctrl is null) then '' else ctr1.nome_ctrl end tipo2,
    (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pr.codigo_emp end) cod_empresa,
    pr.cod_emp_mult, pr.datq_ch,
    case when(pr.tip_baixa = 'C') then ctr1.codigo_ctrl else case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end end codigo_ctrl,
    case when(pr.tip_baixa = 'C') then ctr1.nome_ctrl else case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end end nome_ctrl,
    coalesce(ctr.exibir_resumo_financeiro, 'S') exibir_resumo_financeiro,
    'N' docs, case when(pr.tip_baixa = 'C') then 'S1' else ctr.docs end docs2, case when(pr.tip_baixa = 'C') then 'N' else ctr.docs end docs3,
    case when(pr.tip_baixa = 'C') then pr.valor_ch else case when(l.tipo_l = 'S') then (coalesce(l.valor_l, 0) * -1) else coalesce(l.valor_l, 0) end end valor_pago,
    coalesce(l.cod_lanc, pr.codigo_ch), 0,
    trim(pr.historico_ch) || ' - '|| trim(pr.nome_ch), coalesce(trim(l.historico_l), coalesce(trim(pr.historico_ch) , '')),
    coalesce((case when ((select count(*) from controle_cheque ch
                          where ch.lote_quit = pr.lote_quit
                          and ch.datq_ch = iif(emp.financeiro_unificado = 'S', pr.datq_ch, ch.datq_ch)
                          and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, ch.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp)) = 0) then
      1
    else
      (select count(*) from controle_cheque ch
       where ch.lote_quit = pr.lote_quit
       and ch.datq_ch = iif(emp.financeiro_unificado = 'S', pr.datq_ch, ch.datq_ch)
       and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, ch.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp))
    end), 1) qtde_prest, pr.codigo_ch,
    case when(pr.tip_baixa = 'C') then 'LOTE PG' else 'LOTE' end,
    case when(pr.tip_baixa = 'C') then pr.lote else pr.lote_quit end,
    case when(pr.tip_baixa = 'C') then 'CHQ' else 'LANC' end,
    case when(pr.tip_baixa = 'C') then pr.codigo_ch else l.cod_lanc end cod_lanc,
    0, pr.tip_baixa
    from controle_cheque pr
    left join empresa emp on pr.codigo_emp = emp.cod_empresa
    left join clientes cl on cl.cod_cliente = pr.cod_cliente and cl.cod_empresa = pr.codigo_emp
    left join lancamentos l on
        l.lote_ent = pr.lote_quit
        and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, l.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp)
        and l.data = pr.datq_ch
    left join CONTROLES ctr on ctr.codigo_ctrl = l.codigo_ctrl and ctr.codigo_emp = l.codigo_emp
    left join CONTROLES ctr1 on ctr1.codigo_ctrl = pr.codigo_ctrl and ctr1.codigo_emp = pr.codigo_emp
    where pr.status_ch is not null and pr.datq_ch is not null
    
    union
    
    select 0, 2, 'CREDIARIO', case when (ctr1.nome_ctrl is null) then '' else ctr1.nome_ctrl end tipo2,
    (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pr.codigo_emp end) cod_empresa,
    pr.cod_emp_mult, pr.data_rec,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    coalesce(ctr.exibir_resumo_financeiro, 'S') exibir_resumo_financeiro,
    'N' docs, ctr.docs docs2, ctr.docs docs3,
    case when(l.tipo_l = 'S') then (coalesce(l.valor_l, 0) * -1) else coalesce(l.valor_l, 0) end valor_pago,
    coalesce(l.cod_lanc, pr.codigo_ch), 0,
    trim(pr.historico_ch) || ' - '|| trim(pr.nome_ch), coalesce(trim(l.historico_l), coalesce(trim(pr.historico_ch) , '')),
    1 qtde_prest, pr.codigo_ch,
    'LOTE', pr.lote_quit,
    'LANC', l.cod_lanc,
    0, pr.tip_baixa
    from controle_cheque pr
    left join empresa emp on pr.codigo_emp = emp.cod_empresa
    left join clientes cl on cl.cod_cliente = pr.cod_cliente and cl.cod_empresa = pr.codigo_emp
    left join lancamentos l on
        l.lote_ent = pr.lote_quit
        and iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, l.codigo_emp) = iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, pr.codigo_emp)
        and l.data = pr.data_rec
    left join CONTROLES ctr on ctr.codigo_ctrl = l.codigo_ctrl and ctr.codigo_emp = l.codigo_emp
    left join CONTROLES ctr1 on ctr1.codigo_ctrl = pr.codigo_ctrl and ctr1.codigo_emp = pr.codigo_emp
    where coalesce(pr.status_ch, '') = '' and pr.datq_ch is null
;

/* View: VW_INV_TIPO74, Owner: SYSDBA */
CREATE VIEW VW_INV_TIPO74 (DATA_INV, COD_EMPRESA, GRUPO_PROD, COD_PROD, QUANTIDADE, VALOR_PROD, VALOR_TOTAL, VALOR_TOTAL_R, CODIGO_POSSE, COD_CLIENTE, CNPJ_POSSE, INSCR_POSSE, UF_POSSE, CHASSI_MT, VALOR_ICMS, VALOR_PIS, VALOR_COFINS, ID) AS

select I.DATA_INV, I.COD_EMPRESA, I.GRUPO_PROD, I.COD_PROD, I.POSSE_QTDE QUANTIDADE,
       (I.POSSE_TOTAL / I.POSSE_QTDE) VALOR_PROD, I.POSSE_TOTAL VALOR_TOTAL, round(I.POSSE_TOTAL, 2) VALOR_TOTAL_R,
       I.CODIGO_POSSE, I.COD_CLIENTE, I.CNPJ_POSSE, I.INSCR_POSSE, I.UF_POSSE,
       iif(trim(I7.CHASSI_MT) = '', null, I7.CHASSI_MT) CHASSI_MT, I7.VALOR_ICMS, I7.VALOR_PIS, I7.VALOR_COFINS, I7.ID
from (select INV.DATA_INV, INV.COD_EMPRESA, INV.GRUPO_PROD, INV.COD_PROD,
             iif(IP.ID is null, 0, iif(IP.IND_PROP = 0, 0, iif(IP.IND_PROP = 1, 1, 2))) CODIGO_POSSE, IP.COD_CLIENTE,
             CL.CPFCGC CNPJ_POSSE, CL.INSC_EST INSCR_POSSE, ES.SIGLA_UF UF_POSSE,
             sum(iif(IP.ID is null, INV.QUANTIDADE, IP.QTDE)) POSSE_QTDE,
             sum(iif(IP.ID is null, INV.VALOR_PROD * INV.QUANTIDADE, IP.VALOR * IP.QTDE)) POSSE_TOTAL
      from INV_TIPO74 INV
        left join INV_TIPO74_POSSE IP on IP.INV_ID = INV.ID and
              IP.COD_EMPRESA = INV.COD_EMPRESA
        left join CLIENTES CL on CL.COD_CLIENTE = IP.COD_CLIENTE and
              CL.COD_EMPRESA = IP.COD_EMPRESA
        left join ESTADOS ES on ES.CODIGO_UF = CL.CODIGO_UF
      group by 1, 2, 3, 4, 5, 6, 7, 8, 9) as I
  inner join INV_TIPO74 I7 on I7.DATA_INV = I.DATA_INV and
        I7.COD_EMPRESA = I.COD_EMPRESA and
        I7.GRUPO_PROD = I.GRUPO_PROD and
        I7.COD_PROD = I.COD_PROD
;

/* View: ITENS_PRSEV, Owner: SYSDBA */
CREATE VIEW ITENS_PRSEV (NPED, TIPO, COD_EMPRESA, ORDEM, TIP, NITEM, NUM_FAB_PROD, DESCR_PROD_PED, QUANT_PED_ITEM, RATEIO_ACRESC, RATEIO_DESC, VLUN_PED_ITEM, VLTOT_PED_ITEM) AS

select nped,  tipo, cod_empresa,
1 ordem, 'P' tip,
(select result from strzero(nitem, 3)) nitem,
num_fab_prod, descr_prod_ped,
quant_ped_item, rateio_acresc,  rateio_desc, vlun_ped_item, vltot_ped_item from pedvenda_prod
where (status<>'CANCELADO' or status is null)
union all
select nped,  tipo, cod_empresa,
2 ordem, 'S' tip,
(select result from strzero(nitem, 3)) nitem,
cod_servico num_fab_prod, desc_serv_ped,
quant_serv_ped, rateio_acresc, rateio_desc, valor_un_serv, valor_tot_serv from pedvenda_serv
where (status<>'CANCELADO' or status is null)
union all
select nped,  tipo, cod_empresa,
3 ordem, 'PT' tip,
(select result from strzero(seqid, 3)) nitem,
'' num_fab_prod, descricao desc_serv_ped,
qtde quant_serv_ped, 0 rateio_acresc, 0 rateio_desc, vl_unit valor_un_serv, vl_total valor_tot_serv from pedvenda_prod_terc

union all
select nped,  tipo, cod_empresa,
4 ordem, 'ST' tip,
(select result from strzero(seqid, 3)) nitem,
'' num_fab_prod, descr_servt,
1 quant_serv_ped, 0 rateio_acresc, 0 rateio_desc, vl_servt valor_un_serv, vl_servt valor_tot_serv from pedvenda_serv_terc

order by 1, 3
;

/* View: CREDIARIO_ABERTO, Owner: SYSDBA */
CREATE VIEW CREDIARIO_ABERTO (COD_CLIENTE, COD_EMPRESA, N_DOC_V, N_DOC_C, NPARCELA, DATA_REC_C, DATA_VENC_C, CODIGO_CTRL, NOME_CTRL, TIPO_DOC_C, TP_DOC_V, VALOR_C, VALOR_CORR, STATUS_C, HISTORICO, OBS_C) AS

select cc.cod_cliente, cc.codigo_emp, cc.n_doc_v, cc.n_doc_c, cc.nparcela, cc.data_rec_c, cc.data_venc_c, cc.codigo_ctrl, ctr.nome_ctrl,
  cc.tipo_doc_c, cc.tp_doc_v, cc.valor_c, cc.valor_corr, cc.status_c, cc.historico_c, cc.obs_c from controle_creditos cc
  inner join controles ctr on ctr.codigo_ctrl = cc.codigo_ctrl and ctr.codigo_emp = cc.codigo_emp
where (cc.status_c = '' or cc.status_c is null)
union
select ch.cod_cliente, ch.codigo_emp, ch.n_doc_v, ch.n_ch, 1 nparcela, ch.data_rec, ch.data_venc, ch.codigo_ctrl, ctr.nome_ctrl,
'' tipo_doc_c, ch.tp_doc_v, ch.valor_ch, ch.valor_corr, ch.status_ch, ch.historico_ch, ch.obs_ch from controle_cheque ch
inner join controles ctr on ctr.codigo_ctrl = ch.codigo_ctrl and ctr.codigo_emp = ch.codigo_emp
where (ch.status_ch = '' or ch.status_ch is null)
;

/* View: VW_PRODUTOS_EC, Owner: SYSDBA */
CREATE VIEW VW_PRODUTOS_EC (TIPO, GRUPO_PROD, COD_PROD, COD_EMPRESA, ATIVO, NUM_FAB_PROD, DESCR_PROD_RES, DESCR_PROD_COMPL, SINC_ECOMMERCE, ID_COMMERCE, DISPONIVEL, PROMOCIONAL, FRETE_GRATIS, LANCAMENTO, DESTAQUE, VARIACAO, TERMOS_ACEITE, COMPREJUNTO, VIRTUAL, ENV_COMERCIO_ABERTO, ID_COMERCIO_ABERTO, DESCRICAO_MARCA, LISTA_IMAGENS, URL_IMAGENS, LISTA_IMAGENS_GRADE, URL_IMAGENS_GRADE, REFERENCE, COM_GRADE, COD_GRADE, GRADE1, GRADE2, EST_DISP, EST_DISP_GRADE, EST_MINIMO, MANUAL_EST_DISP, MANUAL_EST_DISP_GRADE, MANUAL_EST_MINIMO, API, API_PRECO_TABELA, PRECO_TABELA, DESCRICAOPROMOCAO, VALORPROMOCAO, DATAINICIOPROMOCAO, DATAFIMPROMOCAO, HORAINICIOPROMOCAO, HORAFIMPROMOCAO, PRECO_A_COMBINAR_EC, PRECO_A_COMBINAR_CA, SEQID_CA) AS

select
  0 TIPO,
--DADOS DO PRODUTO
  PEC.GRUPO_PROD, PEC.COD_PROD, PEC.COD_EMPRESA, PR.ATIVO, PR.NUM_FAB_PROD,
  coalesce(PEC.DESCR_PROD_RES, PR.DESCR_PROD) DESCR_PROD_RES, PEC.DESCR_PROD_COMPL,

  CASE WHEN (PECG.COD_GRADE > 0) THEN
         CASE WHEN (PEC.SINC_ECOMMERCE = 'S') AND (PECG.SINC_ECOMMERCE = 'S') THEN
                'S'
              ELSE
                'N'
         END
       ELSE
         COALESCE(PEC.SINC_ECOMMERCE, 'N')
  END SINC_ECOMMERCE,
  PEC.ID_COMMERCE,
  PEC.DISPONIVEL, PEC.PROMOCIONAL, PEC.FRETE_GRATIS, PEC.LANCAMENTO, PEC.DESTAQUE, PEC.VARIACAO,
  PEC.TERMOS_ACEITE, PEC.COMPREJUNTO, PEC.VIRTUAL,
  PEC.ENV_COMERCIO_ABERTO, COALESCE(PECG.ID_COMERCIO_ABERTO, PEC.ID_COMERCIO_ABERTO) ID_COMERCIO_ABERTO,
  MARCA_PROD.DESCRICAO_MARCA,
  PIP.LISTA_IMAGENS, PIP.URL_IMAGENS, PIG.LISTA_IMAGENS as LISTA_IMAGENS_GRADE,
  PIG.URL_IMAGENS as URL_IMAGENS_GRADE,
  (select first 1 CB.COD_BARRA from COD_BARRA CB
   where CB.GRUPO_PROD = PEC.GRUPO_PROD
   and CB.COD_PROD = PEC.COD_PROD
   and coalesce(CB.COD_GRADE, 0) = 0
   and CB.COD_EMPRESA = PEC.COD_EMPRESA
   and CB.COD_BARRA <> (CB.GRUPO_PROD || CB.COD_PROD)) as REFERENCE,
--DADOS GRADE
  CASE WHEN ((SELECT COUNT(*) FROM COD_GRADE_PROD
  WHERE COD_GRADE_PROD.GRUPO_PROD = PEC.GRUPO_PROD
  AND COD_GRADE_PROD.COD_PROD = PEC.COD_PROD
  AND COD_GRADE_PROD.COD_GRADE > 0
  AND COD_GRADE_PROD.COD_EMPRESA = PEC.COD_EMPRESA) > 0) then '1' else '0' end COM_GRADE,
  coalesce(PECG.COD_GRADE, 0) COD_GRADE,
  iif(coalesce(GRADE.DESCRICAO_EC, '') <> '', GRADE.DESCRICAO_EC, GRADE.DESCRICAO) GRADE1,
  iif(coalesce(GRADE.DESCRICAO_EC1, '') <> '', GRADE.DESCRICAO_EC1, GRADE.DESCRICAO_EC1) GRADE2,
--ESTOQUE FISICO
  coalesce((select trunc(coalesce(ESTOQUE, 0)) from GETESTOQUEDISPONIVEL
    (PEC.GRUPO_PROD, PEC.COD_PROD, 0, PEC.COD_EMPRESA, 0, '', 0, 0)), 0) EST_DISP,
  coalesce((select trunc(coalesce(ESTOQUE, 0)) from GETESTOQUEDISPONIVEL
    (PECG.GRUPO_PROD, PECG.COD_PROD, PECG.COD_GRADE, PECG.COD_EMPRESA, 0, '', 0, 0)), 0) EST_DISP_GRADE,
  coalesce(PR.N_MIN_PROD, 0) EST_MINIMO,
--ESTOQUE MANUAL
  coalesce(PEC.ESTOQUE_EC, 0) MANUAL_EST_DISP,
  coalesce(PECG.ESTOQUE_EC, 0) MANUAL_EST_DISP_GRADE,
  coalesce(PEC.ESTOQUE_MIN_EC, 0) MANUAL_EST_MINIMO,
-- PRECO CONFIG_API
  CONFIG_API.API,
  (select first 1 PMP.VALOR_PROMOCAO
  from PROMOCAO_PRODUTO PMP
    inner join PROMOCAO PM on PM.COD_PROMOCAO = PMP.COD_PROMOCAO and
          PM.COD_EMPRESA = PMP.COD_EMPRESA and
          PM.ATIVO = 1
    left join TIPO_PRECO TP on TP.COD_TPPRECO = PMP.COD_TPPRECO and
          TP.COD_EMPRESA = PMP.COD_EMPRESA
  where PMP.GRUPO_PROD = PR.GRUPO_PROD and
        PMP.COD_PROD = PR.COD_PROD and
        PMP.COD_EMPRESA = PR.COD_EMPRESA and
        PMP.COD_PROMOCAO = CONFIG_API.COD_TAB_PRECO) API_PRECO_TABELA,
--PRECO PADRAO PRODUTO
  PR.PREC_TAB_PROD as PRECO_TABELA,
--DESCRICAO PROMOCAO COMERCIO ABERTO
  (select first 1 PM.DESCR_PROMOCAO
  from PROMOCAO_PRODUTO PMP
    inner join PROMOCAO PM on PM.COD_PROMOCAO = PMP.COD_PROMOCAO and
          PM.COD_EMPRESA = PMP.COD_EMPRESA and
          PM.ATIVO = 1
    inner join PROMOCAO_ORDEM_CA PMOCA on PMOCA.COD_PROMOCAO = PMP.COD_PROMOCAO and
          PMOCA.COD_EMPRESA = PMP.COD_EMPRESA
    left join TIPO_PRECO TP on TP.COD_TPPRECO = PMP.COD_TPPRECO and
          TP.COD_EMPRESA = PMP.COD_EMPRESA
    left join SP_CURRENT_TS(PMP.COD_EMPRESA) CD on 1=1
  where PMP.GRUPO_PROD = PR.GRUPO_PROD and
        PMP.COD_PROD = PR.COD_PROD and
        PMP.COD_EMPRESA = PR.COD_EMPRESA and
        CD.CURRENT_D  >= coalesce(PMP.DATA_INI, PM.DATA_INI) and
        CD.CURRENT_D <= coalesce(PMP.DATA_FIM, PM.DATA_FIM)
  order by PMOCA.ORDEM) DESCRICAOPROMOCAO,
-- VALOR PROMOCAO COMERCIO ABERTO
  (select first 1 iif((PMP.PORCENTAGEM > 0),
                      (PR.PREC_TAB_PROD - (round(PR.PREC_TAB_PROD * PMP.PORCENTAGEM) / 100)),
                       PMP.VALOR_PROMOCAO)
  from PROMOCAO_PRODUTO PMP
    inner join PROMOCAO PM on PM.COD_PROMOCAO = PMP.COD_PROMOCAO and
          PM.COD_EMPRESA = PMP.COD_EMPRESA and
          PM.ATIVO = 1
    inner join PROMOCAO_ORDEM_CA PMOCA on PMOCA.COD_PROMOCAO = PMP.COD_PROMOCAO and
          PMOCA.COD_EMPRESA = PMP.COD_EMPRESA
    left join TIPO_PRECO TP on TP.COD_TPPRECO = PMP.COD_TPPRECO and
          TP.COD_EMPRESA = PMP.COD_EMPRESA
    left join SP_CURRENT_TS(PMP.COD_EMPRESA) CD on 1=1
  where PMP.GRUPO_PROD = PR.GRUPO_PROD and
        PMP.COD_PROD = PR.COD_PROD and
        PMP.COD_EMPRESA = PR.COD_EMPRESA and
        CD.CURRENT_D >= coalesce(PMP.DATA_INI, PM.DATA_INI) and
        CD.CURRENT_D <= coalesce(PMP.DATA_FIM, PM.DATA_FIM)
  order by PMOCA.ORDEM) VALORPROMOCAO,
--DATA INICIAL PROMOCAO
  (select first 1 coalesce(PMP.DATA_INI, PM.DATA_INI)
  from PROMOCAO_PRODUTO PMP
    inner join PROMOCAO PM on PM.COD_PROMOCAO = PMP.COD_PROMOCAO and
          PM.COD_EMPRESA = PMP.COD_EMPRESA and
          PM.ATIVO = 1
    inner join PROMOCAO_ORDEM_CA PMOCA on PMOCA.COD_PROMOCAO = PMP.COD_PROMOCAO and
          PMOCA.COD_EMPRESA = PMP.COD_EMPRESA
    left join TIPO_PRECO TP on TP.COD_TPPRECO = PMP.COD_TPPRECO and
          TP.COD_EMPRESA = PMP.COD_EMPRESA
    left join SP_CURRENT_TS(PMP.COD_EMPRESA) CD on 1=1
  where PMP.GRUPO_PROD = PR.GRUPO_PROD and
        PMP.COD_PROD = PR.COD_PROD and
        PMP.COD_EMPRESA = PR.COD_EMPRESA and
        CD.CURRENT_D >= coalesce(PMP.DATA_INI, PM.DATA_INI) and
        CD.CURRENT_D <= coalesce(PMP.DATA_FIM, PM.DATA_FIM)
  order by PMOCA.ORDEM) DATAINICIOPROMOCAO,
--DATA FINAL PROMOCAO
  (select first 1 coalesce(PMP.DATA_FIM, PM.DATA_FIM)
  from PROMOCAO_PRODUTO PMP
    inner join PROMOCAO PM on PM.COD_PROMOCAO = PMP.COD_PROMOCAO and
          PM.COD_EMPRESA = PMP.COD_EMPRESA and
          PM.ATIVO = 1
    inner join PROMOCAO_ORDEM_CA PMOCA on PMOCA.COD_PROMOCAO = PMP.COD_PROMOCAO and
          PMOCA.COD_EMPRESA = PMP.COD_EMPRESA
    left join TIPO_PRECO TP on TP.COD_TPPRECO = PMP.COD_TPPRECO and
          TP.COD_EMPRESA = PMP.COD_EMPRESA
    left join SP_CURRENT_TS(PMP.COD_EMPRESA) CD on 1=1
  where PMP.GRUPO_PROD = PR.GRUPO_PROD and
        PMP.COD_PROD = PR.COD_PROD and
        PMP.COD_EMPRESA = PR.COD_EMPRESA and
        CD.CURRENT_D >= coalesce(PMP.DATA_INI, PM.DATA_INI) and
        CD.CURRENT_D <= coalesce(PMP.DATA_FIM, PM.DATA_FIM)
  order by PMOCA.ORDEM) DATAFIMPROMOCAO,
--HORA INICIAL PROMOCAO
  (select first 1 coalesce(PMP.HORA_INI, PM.HORA_INI)
  from PROMOCAO_PRODUTO PMP
    inner join PROMOCAO PM on PM.COD_PROMOCAO = PMP.COD_PROMOCAO and
          PM.COD_EMPRESA = PMP.COD_EMPRESA and
          PM.ATIVO = 1
    inner join PROMOCAO_ORDEM_CA PMOCA on PMOCA.COD_PROMOCAO = PMP.COD_PROMOCAO and
          PMOCA.COD_EMPRESA = PMP.COD_EMPRESA
    left join TIPO_PRECO TP on TP.COD_TPPRECO = PMP.COD_TPPRECO and
          TP.COD_EMPRESA = PMP.COD_EMPRESA
    left join SP_CURRENT_TS(PMP.COD_EMPRESA) CD on 1=1
  where PMP.GRUPO_PROD = PR.GRUPO_PROD and
        PMP.COD_PROD = PR.COD_PROD and
        PMP.COD_EMPRESA = PR.COD_EMPRESA and
        CD.CURRENT_D >= coalesce(PMP.DATA_INI, PM.DATA_INI) and
        CD.CURRENT_D <= coalesce(PMP.DATA_FIM, PM.DATA_FIM)
  order by PMOCA.ORDEM) HORAINICIOPROMOCAO,
--HORA FINAL PROMOCAO
  (select first 1 coalesce(PMP.HORA_FIM, PM.HORA_FIM)
  from PROMOCAO_PRODUTO PMP
    inner join PROMOCAO PM on PM.COD_PROMOCAO = PMP.COD_PROMOCAO and
          PM.COD_EMPRESA = PMP.COD_EMPRESA and
          PM.ATIVO = 1
    inner join PROMOCAO_ORDEM_CA PMOCA on PMOCA.COD_PROMOCAO = PMP.COD_PROMOCAO and
          PMOCA.COD_EMPRESA = PMP.COD_EMPRESA
    left join TIPO_PRECO TP on TP.COD_TPPRECO = PMP.COD_TPPRECO and
          TP.COD_EMPRESA = PMP.COD_EMPRESA
    left join SP_CURRENT_TS(PMP.COD_EMPRESA) CD on 1=1
  where PMP.GRUPO_PROD = PR.GRUPO_PROD and
        PMP.COD_PROD = PR.COD_PROD and
        PMP.COD_EMPRESA = PR.COD_EMPRESA and
        CD.CURRENT_D >= coalesce(PMP.DATA_INI, PM.DATA_INI) and
        CD.CURRENT_D <= coalesce(PMP.DATA_FIM, PM.DATA_FIM)
  order by PMOCA.ORDEM) HORAFIMPROMOCAO,
-- PRECO_A_COMBINAR_CA
  PEC.PRECO_A_COMBINAR_EC,
  PEC.PRECO_A_COMBINAR_CA,
--SEQIDS
  coalesce(PECG.SEQID_CA, PEC.SEQID_CA)  SEQID_CA
from PRODUTOS_EC PEC
  inner join PRODUTOS PR on PEC.GRUPO_PROD = PR.GRUPO_PROD and
        PEC.COD_PROD = PR.COD_PROD and
        PEC.COD_EMPRESA = PR.COD_EMPRESA
  left join PRODUTOS_EC_GRADE PECG on PECG.GRUPO_PROD = PEC.GRUPO_PROD and
        PECG.COD_PROD = PEC.COD_PROD and
        PECG.COD_EMPRESA = PEC.COD_EMPRESA
  left join PRODUTOS_IMAGENS PIP on PIP.GRUPO_PROD = PEC.GRUPO_PROD and
        PIP.COD_PROD = PEC.COD_PROD and
        PIP.COD_GRADE = 0 and
        PIP.COD_EMPRESA = PEC.COD_EMPRESA
  left join PRODUTOS_IMAGENS PIG on PIG.GRUPO_PROD = PECG.GRUPO_PROD and
        PIG.COD_PROD = PECG.COD_PROD and
        PIG.COD_GRADE = PECG.COD_GRADE and
        PIG.COD_EMPRESA = PECG.COD_EMPRESA
  left join GRADE on GRADE.COD_GRADE = PECG.COD_GRADE and
        GRADE.COD_EMPRESA = PECG.COD_EMPRESA and
        GRADE.COD_GRADE > 0
  left join CATEGORIA on CATEGORIA.COD_CATEGORIA = PEC.COD_CATEGORIA AND CATEGORIA.COD_EMPRESA = PEC.COD_EMPRESA
  left join MARCA_PROD on MARCA_PROD.COD_MARCA = PR.COD_MARCA
  left join CONFIG_API on CONFIG_API.COD_EMPRESA = PEC.COD_EMPRESA
UNION
select 1 TIPO, TS.COD_SERVICO GRUPO_PROD, 'SERV' COD_PROD, coalesce(TS.COD_EMPRESA, EMP.COD_EMPRESA) COD_EMPRESA,
       TS.ATIVO, null NUM_FAB_PROD, TS.DESC_SERV_RES DESCR_PROD_RES, TS.DESC_SERV_COMPL DESCR_PROD_COMPL,
       null SINC_ECOMMERCE, null ID_COMMERCE,
       null DISPONIVEL, null PROMOCIONAL, null FRETE_GRATIS, null LANCAMENTO, null DESTAQUE, null VARIACAO,
       null TERMOS_ACEITE, null COMPREJUNTO, null VIRTUAL,
       TS.ENV_COMERCIO_ABERTO, TS.ID_COMERCIO_ABERTO, null DESCRICAO_MARCA, null LISTA_IMAGENS, null URL_IMAGENS,
       null LISTA_IMAGENS_GRADE, null URL_IMAGENS_GRADE, cast(TS.COD_SERVICO as varchar(20)) REFERENCE, 0 COM_GRADE,
       0 COD_GRADE, null GRADE1, null GRADE2, 100 EST_DISP, 100 EST_DISP_GRADE, 100 EST_MINIMO, 100 MANUAL_EST_DISP,
       100 MANUAL_EST_DISP_GRADE, 100 MANUAL_EST_MINIMO, 'COMERCIOABERTO' API, TS.VALOR_SERVICO API_PRECO_TABELA,
       TS.VALOR_SERVICO PRECO_TABELA, null DESCRICAOPROMOCAO, null VALORPROMOCAO, null DATAINICIOPROMOCAO,
       null DATAFIMPROMOCAO, null HORAINICIOPROMOCAO, null HORAFIMPROMOCAO,
       null PRECO_A_COMBINAR_EC, TS.PRECO_A_COMBINAR_CA, TS.SEQID_CA
from EMPRESA EMP
  left join TIPO_SERVICO TS on coalesce(TS.COD_EMPRESA, EMP.COD_EMPRESA) = EMP.COD_EMPRESA
where TS.SEQID_CA > 0
;

/* View: FILA_VEICULOS, Owner: SYSDBA */
CREATE VIEW FILA_VEICULOS (ORDEM_TPV, ORDEM_CLI, TPV, CODIGO, COD_EMPRESA, COD_MODELO, ANO_FAB, ANO_MOD, ORDEM, COD_COR, COD_VENDEDOR, COD_CLIENTE, NOME_RES, FONE_RES, DATA_RES, HORA_RES, STATUS_RES, OBS_RES, TIPO_RES, SIT_RES, STATUS_AVARIAS, NOME_VENDEDOR, DESCRICAO, MARCA, CILINDRADA, DESCRICAO_COR, STATUS_DEMONST, COD_ESTMOTO, CHASSI_C, PLACA, NUM_NOTA, DATA_CH_NOTA, DATA_TRANS_NOTA, GRUPO_COTA_RD, POSICAO, STATUS_ESTOQUE, STATUS_CANC, STATUS_TRANSDEP, STATUS_USO, TIPV_VEICULO, DATA_VENC_RES, HORA_VENC_RES, DATA_ASSEMBLEIA, US_CAD, DATA_CAD, HORA_CAD, US_EDIT, DATA_EDIT, HORA_EDIT, OBS_ITEMEST, PREV_CHEG, STATUS_RENOV_RES, QTDE_RENOV_RES, ORDTIPO) AS

SELECT 1 ORDEM_EMP, CASE WHEN(TRIM(EST.NOME_RES) <> '') THEN 1 ELSE 2 END ORDEM_CLI,
'LOJA' TPV, EST.COD_FILA_RES CODIGO, EST.COD_EMPRESA, EST.VERSAOEST,
EST.ANO_FABEST, EST.ANO_MODEST, 0 ORDEM,
EST.COD_COR, EST.VENDEDOR_RES, EST.COD_CLIENTE,
CASE WHEN (EST.COD_CLIENTE > 0) THEN CL.NOME_CLIENTE ELSE EST.NOME_RES END NOME_RES,
EST.FONE_RES, EST.DATA_RES,
EST.HORA_RES, COALESCE(EST.STATUS_RES, 'N') STATUS_RES,
CAST(SUBSTRING(TRIM(EST.OBS_RES) FROM 1 FOR 15) AS VARCHAR(15)) OBS_RES, EST.TIPO_RES, EST.SIT_RES,
COALESCE(EST.STATUS_AVARIAS, 'N') STATUS_AVARIAS, VN.NOME_VENDEDOR,
TP.DESCRICAO, TP.MARCA_DESC MARCA, TP.CILINDRADA, COR.DESCRICAO_COR,
COALESCE(EST.STATUS_DEMONST, 'N') STATUS_DEMONST, EST.CODIGO COD_ESTMOTO, EST.CHASSI_C, EST.PLACAEST,
EST.NUM_NOTA, EST.DATA_CH_NOTA, EST.DATA_TRANS_NOTA, EST.GRUPO_COTA_RD,
EST.POSICAO, EST.STATUS_ESTOQUE, EST.STATUS_CANC, EST.STATUS_TRANSDEP, EST.STATUS_USO,
EST.TIPV_VEICULO, EST.DATA_VENC_RES, EST.HORA_VENC_RES, EST.DATA_ASSEMBLEIA,
EST.US_CAD, EST.DATA_CAD, EST.HORA_CAD, EST.VENDEDOR_RES, EST.DATA_RES, EST.HORA_RES,
SUBSTRING(TRIM(EST.OBS_ITEMEST) FROM 1 FOR 15) OBS_ITEMEST, NULL PREV_CHEG, EST.STATUS_RENOV_RES, EST.QTDE_RENOV_RES, TP.ORDTIPO
FROM EST_MOTO EST
LEFT JOIN CLIENTES CL ON CL.COD_CLIENTE = EST.COD_CLIENTE AND CL.COD_EMPRESA = EST.COD_EMPRESA
LEFT JOIN COLABORADOR VN ON VN.COD_VENDEDOR = EST.VENDEDOR_RES AND VN.COD_EMPRESA = EST.COD_EMPRESA AND VN.ATIVO = 1
LEFT JOIN TIPMODELO TP ON TP.CODIGO = EST.VERSAOEST AND TP.COD_EMPRESA = EST.COD_EMPRESA
LEFT JOIN CODIGO_CORFAB COR ON COR.COD_COR = EST.COD_COR
WHERE (TRIM(COALESCE(EST.POSICAO, 'VIVO')) = 'VIVO')
AND (COALESCE(EST.STATUS_DEMONST, 'N') <> 'S')
UNION
SELECT 1 ORDEM_TPV, CASE WHEN(TRIM(EST.NOME_RES) <> '') THEN 1 ELSE 2 END ORDEM_CLI,
'DEMONSTRACAO' TPV, EST.COD_FILA_RES CODIGO, EST.COD_EMPRESA, EST.VERSAOEST,
EST.ANO_FABEST, EST.ANO_MODEST, 0 ORDEM,
EST.COD_COR, EST.VENDEDOR_RES, EST.COD_CLIENTE,
CASE WHEN (EST.COD_CLIENTE > 0) THEN CL.NOME_CLIENTE ELSE EST.NOME_RES END NOME_RES,
EST.FONE_RES, EST.DATA_RES,
EST.HORA_RES, COALESCE(EST.STATUS_RES, 'N') STATUS_RES,
CAST(SUBSTRING(TRIM(EST.OBS_RES) FROM 1 FOR 15) AS VARCHAR(15)) OBS_RES, EST.TIPO_RES, EST.SIT_RES,
COALESCE(EST.STATUS_AVARIAS, 'N') STATUS_AVARIAS, VN.NOME_VENDEDOR,
TP.DESCRICAO, TP.MARCA_DESC MARCA, TP.CILINDRADA, COR.DESCRICAO_COR,
COALESCE(EST.STATUS_DEMONST, 'N') STATUS_DEMONST, EST.CODIGO COD_ESTMOTO, EST.CHASSI_C, EST.PLACAEST,
EST.NUM_NOTA, EST.DATA_CH_NOTA, EST.DATA_TRANS_NOTA, EST.GRUPO_COTA_RD,
EST.POSICAO, EST.STATUS_ESTOQUE, EST.STATUS_CANC, EST.STATUS_TRANSDEP, EST.STATUS_USO,
EST.TIPV_VEICULO, EST.DATA_VENC_RES, EST.HORA_VENC_RES, EST.DATA_ASSEMBLEIA,
EST.US_CAD, EST.DATA_CAD, EST.HORA_CAD, EST.VENDEDOR_RES, EST.DATA_RES, EST.HORA_RES,
SUBSTRING(TRIM(EST.OBS_ITEMEST) FROM 1 FOR 15) OBS_ITEMEST, NULL PREV_CHEG, EST.STATUS_RENOV_RES, EST.QTDE_RENOV_RES, TP.ORDTIPO
FROM EST_MOTO EST
LEFT JOIN CLIENTES CL ON CL.COD_CLIENTE = EST.COD_CLIENTE AND CL.COD_EMPRESA = EST.COD_EMPRESA
LEFT JOIN COLABORADOR VN ON VN.COD_VENDEDOR = EST.VENDEDOR_RES AND VN.COD_EMPRESA = EST.COD_EMPRESA AND VN.ATIVO = 1
LEFT JOIN TIPMODELO TP ON TP.CODIGO = EST.VERSAOEST AND TP.COD_EMPRESA = EST.COD_EMPRESA
LEFT JOIN CODIGO_CORFAB COR ON COR.COD_COR = EST.COD_COR
WHERE (TRIM(COALESCE(EST.POSICAO, 'VIVO')) = 'VIVO')
AND (COALESCE(EST.STATUS_DEMONST, 'N') = 'S')
UNION
SELECT 2 ORDEM_TPV, CASE WHEN(TRIM(EST.NOME_RES) <> '') THEN 1 ELSE 2 END ORDEM_CLI,
'DEPOSITO' TPV, EST.COD_FILA_RES CODIGO, EST.COD_EMPRESA, EST.VERSAOEST,
EST.ANO_FABEST, EST.ANO_MODEST, 0 ORDEM,
EST.COD_COR, EST.VENDEDOR_RES, EST.COD_CLIENTE,
CASE WHEN (EST.COD_CLIENTE > 0) THEN CL.NOME_CLIENTE ELSE EST.NOME_RES END NOME_RES,
EST.FONE_RES, EST.DATA_RES,
EST.HORA_RES, COALESCE(EST.STATUS_RES, 'N') STATUS_RES,
CAST(SUBSTRING(TRIM(EST.OBS_RES) FROM 1 FOR 15) AS VARCHAR(15)) OBS_RES, EST.TIPO_RES, EST.SIT_RES,
COALESCE(EST.STATUS_AVARIAS, 'N') STATUS_AVARIAS, VN.NOME_VENDEDOR,
TP.DESCRICAO, TP.MARCA_DESC MARCA, TP.CILINDRADA, COR.DESCRICAO_COR,
COALESCE(EST.STATUS_DEMONST, 'N') STATUS_DEMONST, EST.CODIGO COD_ESTMOTO, EST.CHASSI_C, EST.PLACAEST,
EST.NUM_NOTA, EST.DATA_CH_NOTA, EST.DATA_TRANS_NOTA, EST.GRUPO_COTA_RD,
EST.POSICAO, EST.STATUS_ESTOQUE, EST.STATUS_CANC, EST.STATUS_TRANSDEP, EST.STATUS_USO,
EST.TIPV_VEICULO, EST.DATA_VENC_RES, EST.HORA_VENC_RES, EST.DATA_ASSEMBLEIA,
EST.US_CAD, EST.DATA_CAD, EST.HORA_CAD, EST.VENDEDOR_RES, EST.DATA_RES, EST.HORA_RES,
SUBSTRING(TRIM(EST.OBS_ITEMEST) FROM 1 FOR 15) OBS_ITEMEST, NULL PREV_CHEG, EST.STATUS_RENOV_RES, EST.QTDE_RENOV_RES, TP.ORDTIPO
FROM EST_MOTO EST
LEFT JOIN CLIENTES CL ON CL.COD_CLIENTE = EST.COD_CLIENTE AND CL.COD_EMPRESA = EST.COD_EMPRESA
LEFT JOIN COLABORADOR VN ON VN.COD_VENDEDOR = EST.VENDEDOR_RES AND VN.COD_EMPRESA = EST.COD_EMPRESA AND VN.ATIVO = 1
LEFT JOIN TIPMODELO TP ON TP.CODIGO = EST.VERSAOEST AND TP.COD_EMPRESA = EST.COD_EMPRESA
LEFT JOIN CODIGO_CORFAB COR ON COR.COD_COR = EST.COD_COR
INNER JOIN EMPRESA EMP ON EMP.COD_EMPRESA = EST.COD_EMPRESA
WHERE (TRIM(COALESCE(EST.POSICAO, 'VIVO')) = 'MORTO')
AND ((COALESCE(EST.STATUS_TRANSDEP, 'N') = 'S') AND (EST.DATA_TRANS_RET IS NULL))
AND (TRIM(COALESCE(EMP.CONS_DEPOSITO_ESTOQUE, 'N')) = 'S')
UNION
SELECT 3 ORDEM_TPV, CASE WHEN(TRIM(EST.NOME_RES) <> '') THEN 1 ELSE 2 END ORDEM_CLI,
'TRANSITO' TPV, EST.COD_FILA_RES CODIGO, EST.COD_EMPRESA, EST.VERSAOEST,
EST.ANO_FABEST, EST.ANO_MODEST, 0 ORDEM,
EST.COD_COR, EST.VENDEDOR_RES, EST.COD_CLIENTE,
CASE WHEN (EST.COD_CLIENTE > 0) THEN CL.NOME_CLIENTE ELSE EST.NOME_RES END NOME_RES,
EST.FONE_RES, EST.DATA_RES,
EST.HORA_RES, COALESCE(EST.STATUS_RES, 'N') STATUS_RES,
CAST(SUBSTRING(TRIM(EST.OBS_RES) FROM 1 FOR 15) AS VARCHAR(15)) OBS_RES, EST.TIPO_RES, EST.SIT_RES,
COALESCE(EST.STATUS_AVARIAS, 'N') STATUS_AVARIAS, VN.NOME_VENDEDOR,
TP.DESCRICAO, TP.MARCA_DESC MARCA, TP.CILINDRADA, COR.DESCRICAO_COR,
COALESCE(EST.STATUS_DEMONST, 'N') STATUS_DEMONST , EST.CODIGO COD_ESTMOTO, EST.CHASSI_C, EST.PLACAEST,
EST.NUM_NOTA, EST.DATA_CH_NOTA, EST.DATA_TRANS_NOTA, EST.GRUPO_COTA_RD,
EST.POSICAO, EST.STATUS_ESTOQUE, EST.STATUS_CANC, EST.STATUS_TRANSDEP, COALESCE(EST.STATUS_USO, 'N') STATUS_USO,
EST.TIPV_VEICULO, EST.DATA_VENC_RES, EST.HORA_VENC_RES, EST.DATA_ASSEMBLEIA,
EST.US_CAD, EST.DATA_CAD, EST.HORA_CAD, EST.VENDEDOR_RES, EST.DATA_RES, EST.HORA_RES,
SUBSTRING(TRIM(EST.OBS_ITEMEST) FROM 1 FOR 15) OBS_ITEMEST, NULL PREV_CHEG, EST.STATUS_RENOV_RES, EST.QTDE_RENOV_RES, TP.ORDTIPO
FROM EST_MOTO EST
LEFT JOIN CLIENTES CL ON CL.COD_CLIENTE = EST.COD_CLIENTE AND CL.COD_EMPRESA = EST.COD_EMPRESA
LEFT JOIN COLABORADOR VN ON VN.COD_VENDEDOR = EST.VENDEDOR_RES AND VN.COD_EMPRESA = EST.COD_EMPRESA AND VN.ATIVO = 1
LEFT JOIN TIPMODELO TP ON TP.CODIGO = EST.VERSAOEST AND TP.COD_EMPRESA = EST.COD_EMPRESA
LEFT JOIN CODIGO_CORFAB COR ON COR.COD_COR = EST.COD_COR
WHERE (TRIM(COALESCE(EST.POSICAO, 'VIVO')) = 'TRANSITO')
UNION
SELECT CASE WHEN (TRIM(FL.PREV_CHEG) <> '') THEN 4 ELSE 5 END ORDEM_TPV, CASE WHEN(TRIM(FL.NOME_RES) <> '') THEN 1 ELSE 2 END ORDEM_CLI,
'FILA' TPV ,FL.CODIGO, FL.COD_EMPRESA, FL.COD_MODELO,
FL.ANO_FAB, FL.ANO_MOD, FL.ORDEM,
FL.COD_COR, FL.COD_VENDEDOR, FL.COD_CLIENTE,
CASE WHEN (FL.COD_CLIENTE > 0) THEN CL.NOME_CLIENTE ELSE FL.NOME_RES END NOME_RES,
FL.FONE_RES, FL.DATA_RES,
FL.HORA_RES, CASE WHEN (FL.COD_VENDEDOR > 0) THEN 'S' ELSE COALESCE(FL.STATUS_RES, 'N') END STATUS_RES,
CAST(SUBSTRING(TRIM(FL.OBS_RES) FROM 1 FOR 15) AS VARCHAR(15)) OBS_RES, FL.TIPO_RES, FL.SIT_RES,
COALESCE(FL.STATUS_AVARIAS, 'N') STATUS_AVARIAS, VN.NOME_VENDEDOR,
TP.DESCRICAO, TP.MARCA_DESC MARCA,  TP.CILINDRADA, COR.DESCRICAO_COR,
'N' STATUS_DEMONST, 0 COD_ESTMOTO, NULL CHASSI_C, NULL PLACA,
FL.PREV_CHEG NUM_NOTA, NULL DATA_CH_NOTA, NULL DATA_TRANS_NOTA, FL.GRUPO_COTA_RD,
'FILA' POSICAO, 'N' STATUS_ESTOQUE, 'N' STATUS_CANC, 'N' STATUS_TRANSDEP, '' STATUS_USO,
NULL TIPV_VEICULO,FL.DATA_VENC_RES, FL.HORA_VENC_RES, FL.DATA_ASSEMBLEIA,
FL.US_CAD, FL.DATA_CAD, FL.HORA_CAD, FL.US_EDIT, FL.DATA_EDIT, FL.HORA_EDIT,
SUBSTRING(TRIM(FL.OBS_ITEMEST) FROM 1 FOR 15) OBS_ITEMEST, FL.PREV_CHEG, FL.STATUS_RENOV_RES, FL.QTDE_RENOV_RES, TP.ORDTIPO
FROM FILA_RESERVA_VEIC FL
LEFT JOIN CLIENTES CL ON CL.COD_CLIENTE = FL.COD_CLIENTE AND CL.COD_EMPRESA = FL.COD_EMPRESA
LEFT JOIN COLABORADOR VN ON VN.COD_VENDEDOR = FL.COD_VENDEDOR AND VN.COD_EMPRESA = FL.COD_EMPRESA AND VN.ATIVO = 1
LEFT JOIN TIPMODELO TP ON TP.CODIGO = FL.COD_MODELO AND TP.COD_EMPRESA = FL.COD_EMPRESA
LEFT JOIN CODIGO_CORFAB COR ON COR.COD_COR = FL.COD_COR
WHERE (TRIM(COALESCE(FL.STATUS_RES, 'N')) = 'N') AND FL.ATIVO = 1
;

/* View: MAPA_DESP, Owner: SYSDBA */
CREATE VIEW MAPA_DESP (N_CONTA_PLC, DESC_PLC, VALOR_L, DESC_GR, TIPO_GR, HISTORICO_L, DATA, GRUP_CT, COD_LANC, COD_DEP, MES_MAPA, DESC_P, CD_SUBGRUPO, DESC_SUBGRUPO, ORDEM_SUBGRUPO, DTREFERENCIA, CODIGO_EMP, COD_EMP_MULT, VALOR_CONTABIL, MES_MAPA_REF) AS

select p.n_conta_plc,p.desc_plc,l.valor_l,c.desc_gr,c.tipo_gr,
       l.historico_l,l.data,p.grup_ct,l.cod_lanc,c.cod_dep,extract(month from l.data),p.desc_padr,p.COD_SUB_CT,sg.DESC_SUB_CT,
       sg.ORDEM_SUB_CT,l.DTREFERENCIA,l.codigo_emp,l.cod_emp_mult,l.vl_contabil,extract(month from l.DTREFERENCIA)
       from Lancamentos l RIGHT JOIN p_contas p ON l.n_conta_plc = p.n_conta_plc and l.lote is null
       INNER JOIN GRUPOS_CT c on
       p.grup_ct = c.grup_ct and (c.tipo_gr = 'S' or (c.desc_gr like '%INVEST%')) INNER JOIN SUB_GRUP_CT sg
       on p.COD_SUB_CT = sg.COD_SUB_CT where p.ativo = 1
union
select P.n_conta_plc,p.desc_plc,
       case when coalesce(ctr.valor_pago,0) = 0 then ctr.valor_ctp else ctr.valor_pago end valor_pago,c.desc_gr,c.tipo_gr,ctr.historico_ctp,
       ctr.datq_ctp,p.grup_ct,ctr.cod_contrp,c.cod_dep,extract(month from ctr.datq_ctp),p.desc_padr,
       p.COD_SUB_CT,sg.DESC_SUB_CT,sg.ORDEM_SUB_CT,ctr.DTREFERENCIA,ctr.codigo_emp,ctr.cod_emp_mult,ctr.vl_contabil,extract(month from ctr.DTREFERENCIA)
       from contas_a_pagar ctr RIGHT JOIN p_contas p ON ctr.n_conta_plc = p.n_conta_plc and (ctr.lote is not null or (ctr.datq_ctp is null and ctr.entra_previsao = 'S'))
       INNER JOIN grupos_ct c ON p.grup_ct = c.grup_ct and
       (c.tipo_gr = 'S' or (c.desc_gr like '%INVEST%')) INNER JOIN SUB_GRUP_CT sg
       on p.COD_SUB_CT = sg.COD_SUB_CT where p.ativo = 1
;

/* View: POSICAOEST4, Owner: SYSDBA */
CREATE VIEW POSICAOEST4 (CHASSI, DATA_CHEGADA, MODELO, COR, ANO_FAB, ANO_MOD, CUSTO, CILINDRADA, CODIGO, ORDTIPO, DATA_VENDA, COD_EMPRESA, VALOR_REAL, VALOR_A_REC, VALOR_RECEBIDO, DATA_HONDA, COMANDO, TIPO_VENDA, RETORNO_DEMO, ULT_DT_DEMO, ULT_CANC_MT) AS

select vn.chassiv,est.data_ch_nota,est.descricao_versaoest,est.corest,
est.ano_fabest,est.ano_modest,est.preco_custo_rep,
est.cilindradaest,tpm.codigo,tpm.ordtipo,vn.data_ven,vn.cod_empresa,vn.valor_real,vn.valor_a_rec,vn.VL_RQ_PG_CXL,est.data_ch_notav,
vn.n_comando,vn.tipo_v,
(select max(ff.dtsituacao) from com_fat ff where ff.chassiv = vn.chassiv and ff.cod_estmoto = vn.cod_estmoto and (ff.tipv_veiculo = 'D') and (trim(coalesce(ff.status_v, '')) = 'FECHADO')),
(select max(ff.data_ven) from com_fat ff where ff.chassiv = vn.chassiv and ff.cod_estmoto = vn.cod_estmoto and (ff.tipv_veiculo = 'D') and (trim(coalesce(ff.status_v, '')) = 'FECHADO')),
(select max(ff.data_ven) from com_fat ff where ff.chassiv = vn.chassiv and ff.cod_estmoto = vn.cod_estmoto and (trim(coalesce(ff.status_v, '')) = 'CANCELADO'))
from com_fat vn
inner join est_moto est on est.chassi_c = vn.chassiv and est.codigo = vn.cod_estmoto and est.cod_empresa = vn.cod_empresa
inner join tipmodelo tpm on tpm.codigo = est.versaoest and tpm.cod_empresa = est.cod_empresa
where vn.ativo = 1 and trim(coalesce(est.posicao, '')) <> 'MORTO' and coalesce(est.status_demonst, 'N') = 'S'
;

/* View: ESTOQUELOJAVEIC4, Owner: SYSDBA */
CREATE VIEW ESTOQUELOJAVEIC4 (TP_ESTOQUE, ORDTIPO, MODELO, ANO_FAB, ANO_MOD, COR, CHASSI, NUM_NOTA, N_COMANDO, STATUS_USO, COD_EMPRESA) AS

select 'LOJA',tp.ordtipo,est.descricao_versaoest,est.ano_fabest,est.ano_modest,
est.corest,est.chassi_c,est.num_nota,cast('0' as integer),est.status_uso,est.cod_empresa
from
est_moto est,tipmodelo tp where est.versaoest = tp.codigo and
est.cod_empresa = tp.cod_empresa and est.ativo = 1 and (coalesce(est.status_estoque, '') = 'S')
and (coalesce(trim(est.posicao), 'VIVO') = 'VIVO')
union
select 'DEPO',tp.ordtipo,dp.descricao_versaoest,dp.ano_fabest,dp.ano_modest,dp.corest,
dp.chassi_c,dp.num_notav,dp.n_comando,dp.status_uso,dp.cod_empresa
from
est_moto dp,tipmodelo tp
where (dp.data_trans_ret is null) and (coalesce(dp.status_transdep, '') = 'S') and dp.versaoest = tp.codigo and
dp.cod_empresa = tp.cod_empresa and dp.ativo = 1
;

/* View: COMPRASMESESV40, Owner: SYSDBA */
CREATE VIEW COMPRASMESESV40 (COD_NF, NUM_NOTA, CHASSI, DATA_CH_NOTA, DESCRICAO_VERSAO, COR, ANO_FAB, ANO_MOD, CUSTO, COD_EMPRESA, COD_ESTMOTO, COD_NF_DEV, NITEM_DEV, TIPV_VEICULO, STATUS_USO) AS

select 0, it.num_nota,it.chassi_c,et.data_ch_nota, substr(it.descricao_versao, 1, 25),
it.cor,it.ano_fab,it.ano_mod,((et.valor_tot_nota/et.qtde_motos_nota)+it.piscofins),et.cod_empresa,
0, 0, 0, nt.tipv_veiculo,cast (et.tipo_entrada as char(10))
from ent_moto et
inner join ent_moto_itens it on it.num_nota = et.num_nota and it.cod_fornecedor = et.cod_fornecedor and it.cod_empresa = et.cod_empresa
inner join nat_op nt on nt.codigo_nop = et.cod_fisc_nota
where et.ativo = 1 and coalesce(nt.compra, '') <> 'N'
union
select nf4.cod_nf,nf4.num_nf,it4.chassi,nf4.data_lanc,substr(it4.descricao_item,1,25),
itv4.cor,itv4.ano_fab,itv4.ano_mod,it4.prec_cusm_prod,nf4.cod_empresa,
it4.cod_estmoto,it4.cod_nf_dev, it4.nitem_dev, nt.tipv_veiculo, itv4.tipo_venda
from notafiscal nf4
inner join notafiscal_item it4 on nf4.cod_nf=it4.cod_nf and nf4.cod_empresa=it4.cod_empresa
inner join notafiscal_item_veiculo itv4 on it4.cod_nf=itv4.cod_nf and it4.cod_empresa = itv4.cod_empresa and it4.chassi = itv4.chassi
inner join nat_op nt on nt.codigo_nop = it4.codigo_nop
where nf4.natureza_nf='E' and (nf4.status = 'Fechada')
and coalesce(nt.compra, '') <> 'N' and nf4.tipo_nf = 'V' and nf4.ativo=1
;

/* View: DEMANDAPGERAL4, Owner: SYSDBA */
CREATE VIEW DEMANDAPGERAL4 (TIPO, GRUPO_PROD, COD_PROD, VMES, VANO, VQT, DATA_OS_RQ, TIPO_D, TIPO_O, NDOC, ATIVO, COD_EMPRESA, NITEM) AS

select p.tipo, pp.grupo_prod,pp.cod_prod,
extract(month from p.data_fech),extract(year from p.data_fech),
pp.quant_ped_item,p.data_fech,p.tipv,p.tipor,p.nped,p.ativo,p.cod_empresa,pp.nitem
from pedvenda p
inner join pedvenda_prod pp on p.nped = pp.nped and p.cod_empresa = pp.cod_empresa and p.tipo = pp.tipo
where coalesce(p.status_ped,'')<>'CANCELADO' and (pp.status is null or pp.status = '') and (p.status_ped <> '' and not p.status_ped is null) and p.ativo = 1 and
pp.ativo = 1 and ((p.tipo = 'OS') or (p.tipo = 'REQ'))
union
select 'VPR',vnp.grupo_prod,vnp.cod_prod, extract(month from vnp.data_vnp),
extract(year from vnp.data_vnp),vnp.quant_prod_vp,vnp.data_vnp,'E','E',0,vnp.ativo,vnp.cod_empresa,0 from
venda_perdida vnp,tipovp tp where vnp.codigo_vp = tp.codigo_vp and tp.ent_sug_vp = 'S' and tp.cod_empresa = vnp.cod_empresa and vnp.ativo=1
;

/* View: FICHAVENDAPROD4, Owner: SYSDBA */
CREATE VIEW FICHAVENDAPROD4 (TP, NOME_CLIENTE, NDOC, VALOR, DATA, DATA_FECH, DESCR_PROD, NUM_FAB_PROD, QTDE, QTDE_CONV, VL_UNIT, VL_UNIT_LIQ, VL_UNIT_CONV, VL_UNIT_CONV_LIQ, VL_TOT, VL_TOT_LIQ, RATEIO_ACRESC, RATEIO_DESC, COD_CLIENTE, COD_EMPRESA, GRUPO_PROD, COD_PROD, COD_GRADE, TIPOVENDA, TIPOOS, DESCRICAOGRADE, N_ITEM, STATUS_PED, STATUS, TABPRATICADA, UNIDADE, UNIDADE_CONV, OPERACAO_CONV, FATOR_CONV) AS

select pv.Tipo,cl.nome_cliente, pv.nped,
coalesce(pv.valor_total, 0) valor_total,
pv.data_ped, pv.data_fech, pvp.descr_prod_ped,
pvp.num_fab_prod,
coalesce(pvp.quant_ped_item, 0) quant_ped_item,

case when (trim(coalesce(pvp.unidade_conv, '')) = '') then
       pvp.quant_ped_item
     when (trim(coalesce(pvp.unidade_conv, '')) = trim(coalesce(pvp.unidade, ''))) then
       pvp.quant_ped_item
     when ((pvp.operacao_conv = 'M') and (pvp.fator_conv > 0)) then
       (pvp.quant_ped_item * pvp.fator_conv)
     when ((pvp.operacao_conv = 'D') and (pvp.fator_conv > 0)) then
       (pvp.quant_ped_item / pvp.fator_conv)
     else
       pvp.quant_ped_item
end quant_ped_item_conv,

coalesce(pvp.vlun_ped_item, 0) vlun_ped_item,
case when (pvp.quant_ped_item > 0) then
       ((pvp.vltot_ped_item - pvp.rateio_desc + pvp.rateio_acresc) / pvp.quant_ped_item)
     else
        0
end vlun_ped_item_liq,

case when (trim(coalesce(pvp.unidade_conv, '')) = '') then
       pvp.vlun_ped_item
     when (trim(coalesce(pvp.unidade_conv, '')) = trim(coalesce(pvp.unidade, ''))) then
       pvp.vlun_ped_item
     when ((pvp.operacao_conv = 'M') and (pvp.fator_conv > 0)) then
       (pvp.vlun_ped_item / pvp.fator_conv)
     when ((pvp.operacao_conv = 'D') and (pvp.fator_conv > 0)) then
       (pvp.vlun_ped_item * pvp.fator_conv)
     else
       pvp.vlun_ped_item
end vlun_ped_item_conv,
case when (case when (trim(coalesce(pvp.unidade_conv, '')) = '') then
                  pvp.quant_ped_item
                when (trim(coalesce(pvp.unidade_conv, '')) = trim(coalesce(pvp.unidade, ''))) then
                  pvp.quant_ped_item
                when ((pvp.operacao_conv = 'M') and (pvp.fator_conv > 0)) then
                  (pvp.quant_ped_item * pvp.fator_conv)
                when ((pvp.operacao_conv = 'D') and (pvp.fator_conv > 0)) then
                  (pvp.quant_ped_item / pvp.fator_conv)
                else
                  pvp.quant_ped_item
           end > 0) then
             ((pvp.vltot_ped_item - pvp.rateio_desc + pvp.rateio_acresc) /
               case when (trim(coalesce(pvp.unidade_conv, '')) = '') then
                      pvp.quant_ped_item
                    when (trim(coalesce(pvp.unidade_conv, '')) = trim(coalesce(pvp.unidade, ''))) then
                      pvp.quant_ped_item
                    when ((pvp.operacao_conv = 'M') and (pvp.fator_conv > 0)) then
                      (pvp.quant_ped_item * pvp.fator_conv)
                    when ((pvp.operacao_conv = 'D') and (pvp.fator_conv > 0)) then
                      (pvp.quant_ped_item / pvp.fator_conv)
                    else
                      pvp.quant_ped_item
               end)
     else
       0
end vlun_ped_item_conv_liq,

coalesce(pvp.vltot_ped_item, 0) vltot_ped_item,

(coalesce(pvp.vltot_ped_item, 0) - coalesce(pvp.rateio_desc, 0) + coalesce(pvp.rateio_acresc, 0)) vltot_ped_item_liq,

pvp.rateio_acresc, pvp.rateio_desc,
pv.cod_cliente, pv.cod_empresa, pvp.grupo_prod, pvp.cod_prod, pvp.cod_grade,
pv.tipv, pv.tipo_os, gr.descricao, pvp.nitem, pv.status_ped, pvp.status,
pvp.tabpraticada, pvp.unidade, pvp.unidade_conv, pvp.operacao_conv, pvp.fator_conv
from pedvenda pv
inner join pedvenda_prod pvp on pvp.nped = pv.nped and pvp.cod_empresa = pv.cod_empresa and pvp.tipo = pv.tipo
and (pvp.status is null or pvp.status = '')
left join grade gr on pvp.cod_grade = gr.cod_grade and gr.cod_empresa = pvp.cod_empresa
inner join clientes cl on cl.cod_cliente = pv.cod_cliente and cl.cod_empresa = pv.cod_empresa
inner join produtos p on p.cod_prod = pvp.cod_prod and p.grupo_prod = pvp.grupo_prod and p.cod_empresa = pvp.cod_empresa
where pv.ativo = 1
;

/* View: VENDASMESES4, Owner: SYSDBA */
CREATE VIEW VENDASMESES4 (TIPO, GRUPO_PROD, COD_PROD, COD_GRADE, VMES, VANO, VQT, VTOT_VENDA, DATA_OS_RQ, NDOC, COD_CLIENTE, COD_PPS, SUB_G_PROD, TIP_PROD_IND, DESCONTO, CUSTOMC, CUSTOMR, ATIVO, COD_EMPRESA, NITEM, TIPV) AS

select p.tipo,pp.grupo_prod,pp.cod_prod,pp.cod_grade,
extract(month from p.data_fech),extract(year from p.data_fech),
pp.quant_ped_item,pp.vltot_ped_item,p.data_fech,p.nped,p.cod_cliente,
pr.cod_pps, pr.sub_g_prod,pr.tip_prod_ind,pp.rateio_desc,
(pp.quant_ped_item * pp.pcust_mc),(pp.quant_ped_item * pp.pcust_mr),pp.ATIVO,p.COD_EMPRESA,pp.nitem,p.tipv
from pedvenda p,pedvenda_prod pp,produtos pr where pp.nped = p.nped and pp.cod_empresa = p.cod_empresa and pp.tipo = p.tipo
and (pp.status is null or pp.status = '') and pp.grupo_prod = pr.grupo_prod and pp.cod_prod = pr.cod_prod and pp.cod_empresa = pr.cod_empresa
and ((p.tipo = 'OS' and (select retorno from sp_retorno_tipo_venda(p.tipo, p.tipo_os)) = 'S') or
(p.tipo = 'REQ' and (select retorno from sp_retorno_tipo_venda(p.tipo, p.tipv)) = 'S'))
and (p.status_ped <> '' or not p.status_ped is null)
and p.ativo = 1 order by 2,3
;

/* View: VENDASMESESOS4, Owner: SYSDBA */
CREATE VIEW VENDASMESESOS4 (TIPO, VMES, VANO, VQT, VTOT_VENDA, DATA_OS_RQ, NDOC, COD_CLIENTE, DESCONTO, MECANICO, DATA_ABERTURA, VALOR_PAGOHND, NITEM) AS

select 'PC',extract(month from os.data_fech),extract(year from os.data_fech),
ost.quant_ped_item,ost.vltot_ped_item,os.data_fech,os.nped,os.cod_cliente,
ost.rateio_desc,ost.col_cod_vendedor,os.data_ped,cast('0.00' as double precision),ost.nitem
from pedvenda os,pedvenda_prod ost
where ost.nped = os.nped and ost.tipo = os.tipo and ost.cod_empresa =
os.cod_empresa and (ost.status is null or ost.status = '') and os.status_ped = 'FECHADA'
and (os.tipo = 'OS' and
(select retorno from sp_retorno_tipo_venda(os.tipo, os.tipo_os)) = 'S')
union
select 'SS',extract(month from os.data_fech),extract(year from os.data_fech),
oss.quant_serv_ped,oss.valor_tot_serv,os.data_fech,os.nped,os.cod_cliente,
oss.rateio_desc,oss.cod_vendedor,os.data_ped,oss.prc_int_serv,oss.nitem
from pedvenda os,pedvenda_serv oss
where oss.nped = os.nped and oss.tipo = os.tipo and oss.cod_empresa =
os.cod_empresa and (oss.status is null or oss.status = '')  and os.status_ped = 'FECHADA'
and (os.tipo = 'OS' and
(select retorno from sp_retorno_tipo_venda(os.tipo, os.tipo_os)) = 'S')
;

/* View: VENDASPCLIENTES4, Owner: SYSDBA */
CREATE VIEW VENDASPCLIENTES4 (TIPO, N_DOC, DATA_VENDA, COD_CLIENTE, COD_EMPRESA) AS

select p.tipo, p.nped,p.data_fech, p.cod_cliente,p.cod_empresa
from pedvenda p where p.ativo = 1 and
p.status_ped <> '' and not p.status_ped is null and
((p.tipo = 'OS' and (select retorno from sp_retorno_tipo_venda(p.tipo, p.tipo_os)) = 'S') or
(p.tipo = 'REQ' and (select retorno from sp_retorno_tipo_venda(p.tipo, p.tipv)) = 'S')) and p.ativo = 1
;

/* View: PROD_SERV_EMVENDAS, Owner: SYSDBA */
CREATE VIEW PROD_SERV_EMVENDAS (COD_EMPRESA, DATA_FECH, NPED, TIPO, NITEM, PROD_SERV, GRUPOP_CODSERV, COD_PROD, QUANT_PED_ITEM, VLUN_PED_ITEM, VLTOT_PED_ITEM, VALOR_TOTAL_LIQUIDO, VALOR_TOTAL_BRUTO, RATEIO_DESC, RATEIO_ACRESC, PCUST_MC, DESCR_ITEM_PED, COMISS_PROD, COMISS_PROD_GER, N_NF, DESCRICAO, SIGLA, TIPO_OS, NOME_VENDEDOR, COD_VENDEDOR, COL_COD_VENDEDOR, PC_VEND_SERV, PC_VEND_PROD, COD_FUNCAO, DESC_FUNCAO, VENDA, QTDE_PROD, QTDE_SERV) AS

select v.cod_empresa,  v.data_fech, pp.nped,pp.tipo,pp.nitem,'P' as prod_serv,
pp.grupo_prod,pp.cod_prod,
coalesce(pp.quant_ped_item,0) as quant_ped_item,
coalesce(pp.vlun_ped_item,0) as vlun_ped_item,
coalesce(pp.vltot_ped_item,0) as vltot_ped_item,
coalesce(v.valor_total, 0) valor_total_liquido,
(coalesce(v.tot_prod, 0) + coalesce(v.tot_serv, 0) + coalesce(v.tot_prod_terc, 0) + coalesce(v.tot_serv_terc, 0)) valor_total_bruto,
coalesce(pp.rateio_desc,0) as rateio_desc,
coalesce(pp.rateio_acresc,0) as rateio_acresc,
coalesce(pp.pcust_mc,0) as pcust_mc,
pp.descr_prod_ped,
coalesce(pp.comiss_prod,0) as comiss_prod,
coalesce(pp.comiss_prod_ger,0) as comiss_prod_ger,
coalesce(pp.n_nf,0) as n_nf,
tv.descricao,tv.sigla,tv.tipo_os,c.nome_vendedor,c.cod_vendedor,
pp.col_cod_vendedor,c.pc_vend_serv, c.PC_VEND_PROD,f.cod_funcao,f.desc_funcao,tv.venda,
coalesce((select sum(coalesce(pp2.quant_ped_item, 0)) from pedvenda v2
          inner join pedvenda_prod pp2 on v2.tipo = pp2.tipo and v2.nped = pp2.nped and v2.cod_empresa = pp2.cod_empresa
          where v2.nped = v.nped
          and v2.tipo = v.tipo
          and v2.cod_empresa = v.cod_empresa
          and v2.status_ped = 'FECHADA'
          and v2.ativo = 1
          and (pp2.status <> 'CANCELADO' or (pp2.status is null))), 0) qtde_prod,
coalesce((select sum(coalesce(ps2.quant_serv_ped, 0)) from pedvenda v2
          inner join pedvenda_serv ps2 on v2.tipo = ps2.tipo and v2.nped = ps2.nped and v2.cod_empresa = ps2.cod_empresa
          where v2.nped = v.nped
          and v2.tipo = v.tipo
          and v2.cod_empresa = v.cod_empresa
          and v2.status_ped = 'FECHADA'
          and v2.ativo = 1
          and (ps2.status <> 'CANCELADO' or (ps2.status is null))), 0) qtde_serv
from tipo_vendas tv
inner join pedvenda v on v.tipo = tv.tipo and (v.tipv = tv.sigla or (v.tipo_os = tv.tipo_os))
inner join pedvenda_prod pp on v.tipo = pp.tipo and v.nped = pp.nped and v.cod_empresa = pp.cod_empresa
inner join grupos g on pp.grupo_prod = g.codigo_grup
inner join colaborador c on pp.cod_vendedor = c.cod_vendedor and pp.cod_empresa = c.cod_empresa
inner join funcoes f on c.cod_funcao = f.cod_funcao
where v.status_ped = 'FECHADA'
and v.ativo = 1
and (pp.status <> 'CANCELADO' or (pp.status is null))
union
select v.cod_empresa,  v.data_fech, ps.nped,ps.tipo,ps.nitem,'S' as prod_serv,
ps.cod_servico,'      ',
coalesce(ps.quant_serv_ped,0) as quant_serv_ped,
(case when ps.valor_un_serv=0 then ps.prc_int_serv else ps.valor_un_serv end) as valor_un_serv,
coalesce(ps.valor_tot_serv,0) as valor_tot_serv,
coalesce(v.valor_total, 0) valor_total_liquido,
(coalesce(v.tot_prod, 0) + coalesce(v.tot_serv, 0) + coalesce(v.tot_prod_terc, 0) + coalesce(v.tot_serv_terc, 0)) valor_total_bruto,
coalesce(ps.rateio_desc,0) as rateio_desc,
coalesce(ps.rateio_acresc,0) as rateio_acresc,0,
ps.desc_serv_ped,0,0,
coalesce(ps.n_nf,0) as n_nf,
tv.descricao,tv.sigla,tv.tipo_os,c.nome_vendedor,c.cod_vendedor,c.cod_vendedor,
c.pc_vend_serv, c.PC_VEND_PROD,
f.cod_funcao,f.desc_funcao,tv.venda,
coalesce((select sum(coalesce(pp2.quant_ped_item, 0)) from pedvenda v2
          inner join pedvenda_prod pp2 on v2.tipo = pp2.tipo and v2.nped = pp2.nped and v2.cod_empresa = pp2.cod_empresa
          where v2.nped = v.nped
          and v2.tipo = v.tipo
          and v2.cod_empresa = v.cod_empresa
          and v2.status_ped = 'FECHADA'
          and v2.ativo = 1
          and (pp2.status <> 'CANCELADO' or (pp2.status is null))), 0) qtde_prod,
coalesce((select sum(coalesce(ps2.quant_serv_ped, 0)) from pedvenda v2
          inner join pedvenda_serv ps2 on v2.tipo = ps2.tipo and v2.nped = ps2.nped and v2.cod_empresa = ps2.cod_empresa
          where v2.nped = v.nped
          and v2.tipo = v.tipo
          and v2.cod_empresa = v.cod_empresa
          and v2.status_ped = 'FECHADA'
          and v2.ativo = 1
          and (ps2.status <> 'CANCELADO' or (ps2.status is null))), 0) qtde_serv
from tipo_vendas tv
inner join pedvenda v on v.tipo = tv.tipo and (v.tipv = tv.sigla or (v.tipo_os = tv.tipo_os))
inner join pedvenda_serv ps on v.tipo = ps.tipo and v.nped = ps.nped and v.cod_empresa = ps.cod_empresa
inner join colaborador c on ps.cod_vendedor = c.cod_vendedor and ps.cod_empresa = c.cod_empresa
inner join funcoes f on c.cod_funcao = f.cod_funcao
where v.status_ped='FECHADA' and v.ativo = 1 and (ps.status <> 'CANCELADO' or (ps.status is null))
;

/* View: SERVICOSPRESTADOS, Owner: SYSDBA */
CREATE VIEW SERVICOSPRESTADOS (COD_EMPRESA, DATA_FECH, NPED, TIPO, COD_SERVICO, QUANT_SERV_PED, VALOR_UN_SERV, PRC_INT_SERV, VALOR_TOT_SERV, RATEIO_DESC, RATEIO_ACRESC, DESC_SERV_PED, N_NF, DESCRICAO_TIPV, TIPV, TIPO_OS, NOME_VENDEDOR, COD_VENDEDOR, COD_FUNCAO, DESC_FUNCAO, VENDA) AS

select v.cod_empresa,  v.data_fech, ps.nped,ps.tipo, ps.cod_servico,
coalesce(ps.quant_serv_ped,0) as quant_serv_ped,coalesce(ps.valor_un_serv,0) as valor_un_serv,
coalesce(ps.prc_int_serv,0) as prc_int_serv,
coalesce(ps.valor_tot_serv,0) as valor_tot_serv, coalesce(ps.rateio_desc,0) as rateio_desc,
coalesce(ps.rateio_acresc,0) as rateio_acresc, ps.desc_serv_ped,
coalesce(ps.n_nf,0) as n_nf,tv.descricao,tv.sigla,tv.tipo_os,c.nome_vendedor,c.cod_vendedor,
f.cod_funcao,f.desc_funcao,tv.venda from  tipo_vendas tv inner join pedvenda v
on v.tipo=tv.tipo and (v.tipv=tv.sigla or (v.tipo_os=tv.tipo_os))
inner join pedvenda_serv ps on v.tipo=ps.tipo and v.nped=ps.nped and v.cod_empresa=ps.cod_empresa
inner join colaborador c on ps.cod_vendedor=c.cod_vendedor and ps.cod_empresa=c.cod_empresa
inner join funcoes f on c.cod_funcao=f.cod_funcao
where v.status_ped='FECHADA' and v.ativo=1 and (ps.status<>'CANCELADO' or (ps.status is null))
;

/* View: RECEBIMENTOS5, Owner: SYSDBA */
CREATE VIEW RECEBIMENTOS5 (COD_EMPRESA, COD_EMP_MULT, COD_CLIENTE, NOME_CLIENTE, CPFCGC_CLIENTE, TP_RECEBIMENTO, TP_RECEBIMENTO2, ORDEM, COD_TIPO, TIPO, COD_CRED, NUM_DOC, NUM_DOC2, DATA_DOC, DATA_CONF, VALOR_A_RECEBER, VALOR_A_RECEBER_CORR, OBS_CXL, LOTEREC, DIA_CXL, OP_CXL, NOME_OP_CXL, COD_US, DATA_MOV, HISTORICO, VALOR_PAGO, DATA_VENC, TERCEIROS, CODIGO_CTRL, NOME_CTRL, NUM_RECIBO, VALOR_RECIBO, NCUPOM, NUM_NF, PARCELA, SEQID, SEQID2, VENDA, TIPV, TIPO_DOC, ID_COMMERCE, QTDE_PREST) AS

-- VIEW EXIBE OS RECEBIMENTOS DETALHADOS DO CAIXA AUXILIAR POR OPERADOR E DATA DO CAIXA
-- RELATORIO "RECEBIMENTOS CAIXA AUXILIAR"
    
    --- REQ, OS
    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else rq.cod_empresa end) cod_empresa,
    rq.cod_empresa, coalesce(rq.cod_cliente, 0) cod_cliente, cl.nome_cliente, cl.cpfcgc,
    case when (rq.id_commerce > 0) then 'ECOMMERCE' else case when (rq.tipo = 'REQ') then 'BALCAO' else 'SERVICOS' end end tp_recebimento,
    'DIRETO' tp_recebimento2,
    case when (rq.id_commerce > 0) then 7 else case when (rq.tipo = 'REQ') then 2 else 3 end end ordem, 0 cod_tipo, rq.tipo, 0 cod_cred,
    coalesce(rq.nped, 0) as Num_doc, coalesce(fp.ndoc, coalesce(rq.nped, 0)) as Num_doc2, rq.data_ped as data_doc,
    rq.data_fech as data_Conf, coalesce(rq.valor_total, 0) as valor_total, coalesce(rq.valor_total, 0) as valor_total, rq.obs_cxl_rq, rq.nped as loterec,
    rq.dia_cxl, coalesce(rq.op_cxl, 0) op_cxl, col.nome_vendedor, rq.cod_vendedor,
    fp.data_mov, fp.historico, coalesce(fp.valordoc, 0) valordoc, fp.data_venc, fp.terceiros,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    case when (rec.num_rec_dep <> '') then rec.num_rec_dep else coalesce(fp.rec_numvend,0) end as num_recibo, 0 as valor_recibo,
    coalesce(rq.num_nfce, 0) ncupom, coalesce(rq.num_nf, 0) num_nf,
    case when (fp.nrequisicao > 0) then coalesce(fp.nparcela, 0) else 0 end nparcela,
    coalesce(fp.seqform, rq.nped), coalesce(fp.seqform, rq.nped), coalesce(tp.venda, 'S') venda,
    case when(rq.tipo = 'REQ') then tp.sigla else tp.tipo_os end tipv, rq.tipo as tipo_doc,
    coalesce(rq.id_commerce, 0) id_commerce,
    1 qtde_prest

    from pedvenda rq
    inner join empresa emp on rq.cod_empresa = emp.cod_empresa
    inner join colaborador col on col.cod_vendedor = rq.op_cxl and col.cod_empresa = rq.cod_empresa
    left join tipo_vendas tp on tp.tipo = rq.tipo and (tp.sigla = rq.tipv or (tp.tipo_os = rq.tipo_os))
    left join clientes cl on cl.cod_cliente = rq.cod_cliente and cl.cod_empresa = rq.cod_empresa
    left join formpagamento fp on fp.nrequisicao = rq.nped and fp.tpdocs = rq.tipo and fp.cod_empresa = rq.cod_empresa and fp.recibo is null
    left join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where coalesce(trim(rq.status_ped), '') = 'FECHADA' and rq.tipo in ('REQ', 'OS')

    union

    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else rq.cod_empresa end) cod_empresa,
    rq.cod_empresa, coalesce(rq.cod_cliente, 0) cod_cliente, cl.nome_cliente, cl.cpfcgc,
    case when (rq.id_commerce > 0) then 'ECOMMERCE' else case when (rq.tipo = 'REQ') then 'BALCAO' else 'SERVICOS' end end tp_recebimento,
    'RECIBO' tp_recebimento2,
    case when (rq.id_commerce > 0) then 7 else case when (rq.tipo = 'REQ') then 2 else 3 end end ordem, 0 cod_tipo, rq.tipo, 0 cod_cred,
    coalesce(rq.nped, 0) as Num_doc, coalesce(fp.ndoc, coalesce(rq.nped, 0)) as Num_doc2, rq.data_ped as data_doc,
    rq.data_fech as data_Conf, coalesce(rq.valor_total, 0) as valor_total, coalesce(rq.valor_total, 0) as valor_total, rq.obs_cxl_rq, rq.nped as loterec,
    rq.dia_cxl, coalesce(rq.op_cxl, 0) op_cxl, col.nome_vendedor, rq.cod_vendedor,
    fp.data_mov, fp.historico, coalesce(fp.valordoc, 0) valordoc, fp.data_venc, fp.terceiros,
    case when (select first 1 ctrl.nome_ctrl from controles ctrl
    inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
    where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend ='REC' order by rc.valordoc asc) is null then
        0
    else (select first 1 ctrl.codigo_ctrl from controles ctrl
        inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
        where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend ='REC' order by rc.valordoc asc)
    end as codigo_ctrl,
    case when (select first 1 ctrl.nome_ctrl from controles ctrl
    inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
    where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend ='REC' order by rc.valordoc asc) is null then
        'SEM FORMA'
    else (select first 1 ctrl.nome_ctrl from controles ctrl
        inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
        where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend ='REC' order by rc.valordoc asc)
    end as nome_ctrl,
    case when (rec.num_rec_dep <> '') then rec.num_rec_dep else coalesce(fp.rec_numvend,0) end num_recibo,
    coalesce((select sum(rc.valor_orig) from recibos rc where rc.nrecibo = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa), 0) as valor_recibo,
    coalesce(rq.num_nfce, 0) ncupom, coalesce(rq.num_nf, 0) num_nf,
    case when (fp.nrequisicao > 0) then coalesce(fp.nparcela, 0) else 0 end nparcela,
    coalesce(fp.seqform, rq.nped), coalesce(fp.seqform, rq.nped), coalesce(tp.venda, 'S') venda,
    case when(rq.tipo = 'REQ') then tp.sigla else tp.tipo_os end tipv, rq.tipo as tipo_doc,
    coalesce(rq.id_commerce, 0) id_commerce,
    1 qtde_prest

    from pedvenda rq
    inner join empresa emp on rq.cod_empresa = emp.cod_empresa
    inner join colaborador col on col.cod_vendedor = rq.op_cxl and col.cod_empresa = rq.cod_empresa
    left join tipo_vendas tp on tp.tipo = rq.tipo and (tp.sigla = rq.tipv or (tp.tipo_os = rq.tipo_os))
    left join clientes cl on cl.cod_cliente = rq.cod_cliente and cl.cod_empresa = rq.cod_empresa
    inner join formpagamento fp on fp.nrequisicao = rq.nped and fp.tpdocs = rq.tipo and fp.cod_empresa = rq.cod_empresa and (not fp.recibo is null)
    left join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa
    where coalesce(trim(rq.status_ped), '') = 'FECHADA' and rq.tipo in ('REQ', 'OS')

    union
    
    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else rq.cod_empresa end) cod_empresa,
    rq.cod_empresa, coalesce(rq.cod_cliente, 0) cod_cliente, cl.nome_cliente, cl.cpfcgc,
    case when (rq.id_commerce > 0) then 'ECOMMERCE' else case when (rq.tipo = 'REQ') then 'BALCAO' else 'SERVICOS' end end tp_recebimento,
    'TROCO' tp_recebimento2,
    case when (rq.id_commerce > 0) then 7 else case when (rq.tipo = 'REQ') then 2 else 3 end end ordem, 0 cod_tipo, rq.tipo, 0 cod_cred,
    coalesce(rq.nped, 0) as Num_doc, coalesce(fp.ndoc, coalesce(rq.nped, 0)) as Num_doc2, rq.data_ped as data_doc,
    rq.data_fech as data_Conf, coalesce(rq.valor_total, 0) as valor_total, coalesce(rq.valor_total, 0) as valor_total, rq.obs_cxl_rq, rq.nped as loterec,
    rq.dia_cxl, coalesce(rq.op_cxl, 0) op_cxl, col.nome_vendedor, rq.cod_vendedor,
    fp.data_mov, fp.historico,
    coalesce(fp.valordoc, 0) valordoc, fp.data_venc, fp.terceiros,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    case when (rec.num_rec_dep <> '') then rec.num_rec_dep else coalesce(fp.rec_numvend,0) end num_recibo, 0 as valor_recibo,
    coalesce(rq.num_nfce, 0) ncupom, coalesce(rq.num_nf, 0) num_nf,
    case when (fp.nrequisicao > 0) then coalesce(fp.nparcela, 0) else 0 end nparcela,
    coalesce(fp.seqform, rq.nped), coalesce(fp.seqform, rq.nped),  coalesce(tp.venda, 'S') venda,
    case when(rq.tipo = 'REQ') then tp.sigla else tp.tipo_os end tipv, rq.tipo as tipo_doc,
    coalesce(rq.id_commerce, 0) id_commerce,
    1 qtde_prest

    from pedvenda rq
    inner join empresa emp on rq.cod_empresa = emp.cod_empresa
    inner join colaborador col on col.cod_vendedor = rq.op_cxl and col.cod_empresa = rq.cod_empresa
    left join tipo_vendas tp on tp.tipo = rq.tipo and (tp.sigla = rq.tipv or (tp.tipo_os = rq.tipo_os))
    left join clientes cl on cl.cod_cliente = rq.cod_cliente and cl.cod_empresa = rq.cod_empresa
    inner join formpagamento fp on fp.rec_numvend = rq.nped and fp.rec_tipvend = rq.tipo and fp.cod_empresa = rq.cod_empresa and fp.tpdocs = 'TRC'
    left join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where coalesce(trim(rq.status_ped), '') = 'FECHADA' and rq.tipo in ('REQ', 'OS')

    union
    
    --- CF
    
    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else mt.cod_empresa end) cod_empresa,
    mt.cod_empresa, coalesce(mt.clientes_v, 0) clientes_v, cl.nome_cliente, cl.cpfcgc,
    'VEICULOS' tp_recebimento, 'DIRETO' tp_recebimento2,
    1 ordem, 0 cod_tipo, 'MOT' as tipo, 0 cod_cred,
    coalesce(mt.n_comando, 0) as Num_doc, coalesce(fp.ndoc, coalesce(mt.n_comando, 0)) as Num_doc2, mt.data_ven as Data_Doc,
    mt.data_fech as Data_Conf, coalesce(mt.valor_a_rec, 0) as valor_total, coalesce(mt.valor_a_rec, 0) as valor_total, ' ' as obs_cxl_rq, mt.n_comando as loterec,
    mt.dia_cxl, coalesce(mt.op_cxl, 0) op_cxl, col.nome_vendedor, mt.covend_v,
    fp.data_mov, fp.historico, coalesce(fp.valordoc, 0), fp.data_venc, fp.terceiros,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    case when (rec.num_rec_dep <> '') then rec.num_rec_dep else coalesce(fp.rec_numvend,0) end num_recibo, 0 as valor_recibo,
    0 ncupom, coalesce(mt.num_nota_v, 0) num_nf,
    case when (fp.nrequisicao > 0) then coalesce(fp.nparcela, 0) else 0 end nparcela,
    coalesce(fp.seqform, mt.n_comando), coalesce(fp.seqform, mt.n_comando), coalesce(tp.venda, 'S') venda,
    tp.tipo_os, 'MOT' as tipo_doc, 0 id_commerce, 1 qtde_prest from com_fat mt
    inner join empresa emp on mt.cod_empresa = emp.cod_empresa
    inner join colaborador col on col.cod_vendedor = mt.op_cxl and col.cod_empresa = mt.cod_empresa
    left join tipo_vendas tp on tp.tipo = 'VEI' and tp.tipo_os = mt.tipo_v
    left join clientes cl on cl.cod_cliente = mt.clientes_v and cl.cod_empresa = mt.cod_empresa
    left join formpagamento fp on fp.nrequisicao = mt.n_comando and fp.tpdocs = 'MOT' and fp.cod_empresa = mt.cod_empresa and fp.recibo is null
    left join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where (coalesce(trim(mt.status_v), '') = 'FECHADO') and mt.natureza = 'S'

    union
    
    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else mt.cod_empresa end) cod_empresa,
    mt.cod_empresa, coalesce(mt.clientes_v, 0) clientes_v, cl.nome_cliente, cl.cpfcgc,
    'VEICULOS' tp_recebimento, 'RECIBO' tp_recebimento2,
    1 ordem, 0 cod_tipo, 'MOT' as tipo, 0 cod_cred,
    coalesce(mt.n_comando, 0) as Num_doc, coalesce(fp.ndoc, coalesce(mt.n_comando, 0)) as Num_doc2, mt.data_ven as Data_Doc,
    mt.data_fech as Data_Conf, coalesce(mt.valor_a_rec, 0) as valor_total,  coalesce(mt.valor_a_rec, 0) as valor_total, ' ' as obs_cxl_rq, mt.n_comando as loterec,
    mt.dia_cxl, coalesce(mt.op_cxl, 0) op_cxl, col.nome_vendedor, mt.covend_v,
    fp.data_mov, fp.historico, coalesce(fp.valordoc, 0), fp.data_venc, fp.terceiros,
    case when (select first 1 ctrl.nome_ctrl from controles ctrl
    inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
    where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend = 'REC' order by rc.valordoc asc) is null then
        0
    else (select first 1 ctrl.codigo_ctrl from controles ctrl
        inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
        where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend = 'REC' order by rc.valordoc asc)
    end as codigo_ctrl,
    case when (select first 1 ctrl.nome_ctrl from controles ctrl
    inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
    where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend = 'REC' order by rc.valordoc asc) is null then
        'SEM FORMA'
    else (select first 1 ctrl.nome_ctrl from controles ctrl
        inner join formpagamento rc on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
        where rc.rec_numvend = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa and rc.rec_tipvend = 'REC' order by rc.valordoc asc)
    end as nome_ctrl,
    case when (rec.num_rec_dep <> '') then rec.num_rec_dep else coalesce(fp.rec_numvend,0) end num_recibo,
    coalesce((select sum(rc.valor_orig) from recibos rc where rc.nrecibo = fp.rec_numvend and rc.cod_empresa = fp.cod_empresa), 0) as valor_recibo,
    0 ncupom, coalesce(mt.num_nota_v, 0) num_nf,
    case when (fp.nrequisicao > 0) then coalesce(fp.nparcela, 0) else 0 end nparcela,
    coalesce(fp.seqform, mt.n_comando), coalesce(fp.seqform, mt.n_comando),  coalesce(tp.venda, 'S') venda,
    tp.tipo_os, 'MOT' as tipo_doc, 0 id_commerce, 1 qtde_prest from com_fat mt
    inner join empresa emp on mt.cod_empresa = emp.cod_empresa
    inner join colaborador col on col.cod_vendedor = mt.op_cxl and col.cod_empresa = mt.cod_empresa
    left join tipo_vendas tp on tp.tipo = 'VEI' and tp.tipo_os = mt.tipo_v
    left join clientes cl on cl.cod_cliente = mt.clientes_v and cl.cod_empresa = mt.cod_empresa
    inner join formpagamento fp on fp.nrequisicao = mt.n_comando and fp.tpdocs = 'MOT' and fp.cod_empresa = mt.cod_empresa and (not fp.recibo is null)
    left join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where (coalesce(trim(mt.status_v), '') = 'FECHADO') and mt.natureza = 'S'

    union
    
    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else mt.cod_empresa end) cod_empresa,
    mt.cod_empresa, coalesce(mt.clientes_v, 0) clientes_v, cl.nome_cliente, cl.cpfcgc,
    'VEICULOS' tp_recebimento, 'TROCO' tp_recebimento2,
    1 ordem, 0 cod_tipo, 'MOT' as tipo, 0 cod_cred,
    coalesce(mt.n_comando, 0) as Num_doc, coalesce(fp.ndoc, coalesce(mt.n_comando, 0)) as Num_doc2, mt.data_ven as Data_Doc,
    mt.data_fech as Data_Conf, coalesce(mt.valor_a_rec, 0) as valor_total,  coalesce(mt.valor_a_rec, 0) as valor_total, ' ' as obs_cxl_rq, mt.n_comando as loterec,
    mt.dia_cxl, coalesce(mt.op_cxl, 0) op_cxl, col.nome_vendedor, mt.covend_v,
    fp.data_mov, fp.historico, coalesce(fp.valordoc, 0), fp.data_venc, fp.terceiros,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    case when (rec.num_rec_dep <> '') then rec.num_rec_dep else coalesce(fp.rec_numvend,0) end num_recibo, 0 as valor_recibo,
    0 ncupom, coalesce(mt.num_nota_v, 0) num_nf,
    case when (fp.nrequisicao > 0) then coalesce(fp.nparcela, 0) else 0 end nparcela,
    coalesce(fp.seqform, mt.n_comando), coalesce(fp.seqform, mt.n_comando),  coalesce(tp.venda, 'S') venda,
    tp.tipo_os, 'MOT' as tipo_doc, 0 id_commerce, 1 qtde_prest from com_fat mt
    inner join empresa emp on mt.cod_empresa = emp.cod_empresa
    inner join colaborador col on col.cod_vendedor = mt.op_cxl and col.cod_empresa = mt.cod_empresa
    left join tipo_vendas tp on tp.tipo = 'VEI' and tp.tipo_os = mt.tipo_v
    left join clientes cl on cl.cod_cliente = mt.clientes_v and cl.cod_empresa = mt.cod_empresa
    inner join formpagamento fp on fp.rec_numvend = mt.n_comando and fp.rec_tipvend = 'MOT' and fp.cod_empresa = mt.cod_empresa and fp.tpdocs = 'TRC'
    left join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa
    left join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where (coalesce(trim(mt.status_v), '') = 'FECHADO') and mt.natureza = 'S'

    union

    --RECIBO

    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else rec.cod_empresa end) cod_empresa,
    (case when(emp.financeiro_unificado = 'S') then coalesce(rec.cod_emp_mult, rec.cod_empresa) else rec.cod_empresa end) cod_emp_mult,
    coalesce(rec.cod_devedor, 0) cod_cliente, rec.nome_dev nome_cliente, cl.cpfcgc,
    'RECIBO ANTECIPADO' tp_recebimento, 'DIRETO' tp_recebimento2, 4 ordem,
    0 cod_tipo, 'RECIBO' tipo, 0 cod_cred,
