    'N' venda, '' tipv, 'REC' as tipo_doc, 0 id_commerce, 1 qtde_prest
    from recibos rec
    inner join empresa emp on rec.cod_empresa = emp.cod_empresa
    inner join colaborador col on col.cod_vendedor = rec.op_cxl and col.cod_empresa = rec.cod_empresa
    left join clientes cl on cl.cod_cliente = rec.cod_devedor and cl.cod_empresa = rec.cod_empresa
    inner join formpagamento fp on fp.rec_numvend = rec.nrecibo and fp.cod_empresa = rec.cod_empresa and fp.rec_tipvend = 'REC' and fp.tpdocs = 'TRC'
    left join CONTROLES ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
    
    union

    -- PRESTACOES

    select (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pr.codigo_emp end) cod_empresa,
