    mt.cod_empresa,
    mt.data_fech, mt.dia_cxl, coalesce(mt.op_cxl, 0) op_cxl, 0 id_commerce,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    coalesce(fp.valordoc, 0) valordoc,
    coalesce(fp.seqform, mt.n_comando), coalesce(fp.seqform, mt.n_comando) from com_fat mt
    inner join empresa emp on mt.cod_empresa = emp.cod_empresa
    inner join formpagamento fp on fp.nrequisicao = mt.n_comando and fp.tpdocs = 'MOT' and fp.cod_empresa = mt.cod_empresa  and fp.recibo is null
    inner join CONTROLES ctr on fp.cod_controle = ctr.codigo_ctrl and fp.cod_empresa = ctr.codigo_emp
    where (coalesce(trim(mt.status_v), '') = 'FECHADO') and mt.natureza = 'S'
    /* where coalesce((select count(*) from formpagamento frc where frc.nrequisicao = mt.n_comando and
        frc.tpdocs = 'MOT' and frc.cod_empresa = mt.cod_empresa and (not frc.recibo is null)),0) <= 0*/
    
