    coalesce(fp.seqform, pr.cod_cred), coalesce(fp.seqform, pr.cod_cred)
    from baixa_creditos pr
    inner join empresa emp on pr.codigo_emp = emp.cod_empresa
    inner join colaborador col on col.cod_vendedor = pr.op_cxl and col.cod_empresa = pr.cod_emp_mult
    left join clientes cl on cl.cod_cliente = pr.cod_cliente and cl.cod_empresa = pr.cod_emp_mult
