    left join clientes cl on cl.cod_cliente = pr.cod_cliente and cl.cod_empresa = pr.cod_emp_mult
    left join controle_creditos cc on cc.cod_cred = pr.cod_cred and cc.cod_emp_mult = pr.cod_emp_mult
    inner join formpagamento fp on fp.nrequisicao = pr.lote_cxl and fp.cod_empresa = pr.cod_emp_mult and fp.tpdocs = 'PRE' and (not fp.recibo is null)
