    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
    'RECIBO',
    --case when ctr.nome_ctrl is null then 'SEM FORMA' else ctr.nome_ctrl end nome_ctrl,
    case when(fp.valordoc < 0) then (coalesce(fp.valordoc, 0) * -1) else coalesce(fp.valordoc, 0) end valor_pago,
    coalesce(fp.seqform, pr.cod_cred), coalesce(fp.seqform, pr.cod_cred)
