    inner join formpagamento fp on fp.rec_numvend = pr.lote_cxl and fp.cod_empresa = pr.cod_emp_mult and fp.rec_tipvend = 'PRE' and fp.tpdocs = 'TRC'
    left join CONTROLES ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
    left join CONTROLES ctr1 on ctr1.codigo_ctrl = pr.codigo_ctrl and ctr1.codigo_emp = pr.codigo_emp
    where coalesce(pr.status_c, '') = '' and pr.datq_c is null

    union

    -- LANC CXL
    
    select 'LANCAMENTO AVULSO' tp_recebimento, 'DIRETO' tp_recebimento2,
    6 ordem, 'LCXL', 'LCXL',
    (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else lanc.codigo_emp end) cod_empresa,
    lanc.codigo_emp, lanc.data_lc_cxl, lanc.data_lc_cxl, coalesce(lanc.op_cxl, 0) op_cxl, 0 id_commerce,
    case when ctr.nome_ctrl is null then 0 else ctr.codigo_ctrl end codigo_ctrl,
