/* View: VENDAPRODUTOS, Owner: SYSDBA */
CREATE VIEW VENDAPRODUTOS (COD_EMPRESA, DATA_FECH, NPED, TIPO, GRUPO_PROD, COD_PROD, COD_GRADE, QUANT_PED_ITEM, VLUN_ORIG, VLUN_PED_ITEM, VLTOT_PED_ITEM, RATEIO_DESC, RATEIO_ACRESC, DESCR_PROD_PED, PCUST_MC, COMISS_PROD, COMISS_PROD_GER, N_NF, DESCRICAO_TIPV, TIPV, TIPO_OS, DESCRICAO_GRUPO, NOME_VENDEDOR, NOME_PARTICIPANTE, COD_VENDEDOR, COD_PARTICIPANTE, COL_COD_VENDEDOR, COD_FUNCAO, DESC_FUNCAO, NITEM, VENDA, NOME_CLIENTEDAV, DEV_NPED, DEV_TIPO, COD_CIDADE, NOME_CIDADE) AS

select v.cod_empresa,v.data_fech,
pp.nped,pp.tipo, pp.grupo_prod,pp.cod_prod,pp.cod_grade,
coalesce(pp.quant_ped_item,0) as quant_ped_item,
coalesce(pp.vlun_orig, 0) as vlun_orig,
coalesce(pp.vlun_ped_item,0) as vlun_ped_item,
coalesce(pp.vltot_ped_item,0) as vltot_ped_item,
coalesce(pp.rateio_desc,0) as rateio_desc,
coalesce(pp.rateio_acresc,0) as rateio_acresc,
pp.descr_prod_ped,
coalesce(pp.pcust_mc,0) as pcust_mc,
coalesce(pp.comiss_prod,0) as comiss_prod,
coalesce(pp.comiss_prod_ger,0) as comiss_prod_ger,
coalesce(pp.n_nf,0) as n_nf,
tv.descricao,tv.sigla,tv.tipo_os, g.descricao,
c.nome_vendedor, p.nome_participante,c.cod_vendedor, p.cod_participante, pp.col_cod_vendedor, f.cod_funcao,f.desc_funcao,
pp.nitem,tv.venda,v.nome_clientedav,v.nped,v.tipo, cl.cod_cidade, cd.nome_cidade from tipo_vendas tv
inner join pedvenda v on v.tipo=tv.tipo and (v.tipv=tv.sigla or (v.tipo_os=tv.tipo_os))
inner join pedvenda_prod pp on v.tipo=pp.tipo and v.nped=pp.nped and v.cod_empresa=pp.cod_empresa
inner join grupos g on pp.grupo_prod=g.codigo_grup
inner join colaborador c on pp.cod_vendedor=c.cod_vendedor and pp.cod_empresa=c.cod_empresa
left join participante p on pp.cod_vendedor1 = p.cod_participante and pp.cod_empresa = p.cod_empresa
inner join funcoes f on c.cod_funcao=f.cod_funcao
left join clientes cl on cl.cod_cliente = v.cod_cliente and cl.cod_empresa = v.cod_cliente
left join cidades cd on cd.cod_cidade = cl.cod_cidade
where v.status_ped='FECHADA' and v.ativo=1 and (pp.status<>'CANCELADO' or (pp.status is null))
union
select d.cod_empresa,d.data,
d.sequencia,'DEV' as tipo,d.grupo_prod,d.cod_prod,d.cod_grade,
d.quant as quant_ped_item,
((-1)*coalesce(d.valor_orig, 0)) as valor_orig,
((-1)*coalesce(d.valor, 0)) as valor,
((-1)*(coalesce(d.quant, 0)*coalesce(d.valor, 0))) as vltot_ped_item,
0 as rateio_desc,
0 as rateio_acresc,
substr(d.descricao,1,60) as descr_prod_ped,
((-1)*coalesce(d.pcust_mc, 0)) as pcust_mc,
((-1)*coalesce(d.comiss_prod, 0)),
((-1)*coalesce(d.comiss_prod_ger, 0)),
num_nota_nfe,
case when tv.descricao is null then 'V - VAREJO          ' else tv.descricao end as descricao,
case when tv.sigla is null then 'V' else tv.sigla end as sigla,
tv.tipo_os,g.descricao,c.nome_vendedor, null nome_participante,
c.cod_vendedor, null cod_participante,c.cod_vendedor,f.cod_funcao,f.desc_funcao,
d.seqid,coalesce(tv.venda,'S'),d.nome_cliente,d.cod_venda,d.tipo_venda, cl.cod_cidade, cd.nome_cidade
from devolucao d
inner join colaborador c on d.cod_vendedor = c.cod_vendedor and d.cod_empresa = c.cod_empresa
inner join funcoes f on c.cod_funcao = f.cod_funcao
inner join grupos g on d.grupo_prod = g.codigo_grup
left join pedvenda v on d.tipo_venda = v.tipo and coalesce(d.cod_venda,0) = v.nped and d.cod_empresa = v.cod_empresa
left join clientes cl on cl.cod_cliente = d.cod_cliente and cl.cod_empresa = d.cod_cliente
left join cidades cd on cd.cod_cidade = cl.cod_cidade
left join tipo_vendas tv on v.tipo = tv.tipo and (v.tipv=tv.sigla or (v.tipo_os=tv.tipo_os))
;

/* View: PRODISENTO_PISCOFINS, Owner: SYSDBA */
CREATE VIEW PRODISENTO_PISCOFINS (TIPO, DATA_LANC, NUM_NF_CUMPOM, NSERIEECF, COD_TERMINAL, NITEM, GRUPO_PROD, COD_PROD, NUM_FAB_PROD, NBM, DESCR_PROD, QUANTIDADE, VALOR_UNITARIO, VALOR_TOTAL, NCM, COD_EMPRESA, CST_PIS) AS

select
'NF' as Tipo,
nf.data_lanc,
nf.num_nf,
null as nserieecf,
null as cod_terminal,
inf.nitem,
p.grupo_prod,
p.cod_prod,
p.num_fab_prod,
p.nbm,
p.descr_prod,
coalesce(inf.quantidade,0) as quantidade,
coalesce(inf.valor_unitario,0)-(coalesce(inf.rateio_desconto,0)/coalesce(inf.quantidade,1)) as valor_unitario,
coalesce(inf.valor_total,0)-coalesce(inf.rateio_desconto,0) as valor_total,
inf.ncm,
inf.cod_empresa,
case when (p.isento_pis = 'S') then '07' else p.cst_pis end cst_pis
from notafiscal nf
inner join notafiscal_item inf on nf.cod_nf=inf.cod_nf and nf.cod_empresa=inf.cod_empresa
inner join produtos p on inf.grupo_prod=p.grupo_prod and inf.cod_prod=p.cod_prod and inf.cod_empresa=p.cod_empresa
where p.nbm is not null and p.nbm<>'' and p.ativo=1
and case when (p.isento_pis = 'S') then '07' else p.cst_pis end in ('04', '05', '06', '07')
and nf.status ='Fechada' and nf.situacao_nfe='Autorizada'
union
select
'ECF' as Tipo,
c.data,
c.cupom,
c.nserieecf,
c.cod_terminal,
c2.registro,
p.grupo_prod,
p.cod_prod,
p.num_fab_prod,
p.nbm,
p.descr_prod,
coalesce(c2.quantidade,0) as quantidade,
coalesce(c2.preco,0)+
(((coalesce(c2.perc_acresc,0)+coalesce(c2.rat_acres,0))/coalesce(c2.quantidade,1))-
((coalesce(c2.rat_desc,0)+coalesce(c2.perc_desc,0))/coalesce(c2.quantidade,1))) as valor_unitario,
(coalesce(c2.total,0)+coalesce(c2.perc_acresc,0)+coalesce(c2.rat_acres,0)-coalesce(c2.rat_desc,0)-coalesce(c2.perc_desc,0)) as valor_total,
'' as NCM,
c2.cod_empresa,
case when (p.isento_pis = 'S') then '07' else p.cst_pis end cst_pis
from cupom c
inner join cupom2 c2 on c.cod_terminal=c2.cod_terminal and c.nserieecf=c2.nserieecf and c.cupom = c2.cupom and c.registro=c2.ordem and c.cod_empresa =c2.cod_empresa
inner join produtos p on c2.grupo_prod=p.grupo_prod and c2.cod_prod=p.cod_prod and c2.cod_empresa=p.cod_empresa
where p.nbm is not null and p.nbm<>'' and p.ativo=1
and case when (p.isento_pis = 'S') then '07' else p.cst_pis end in ('04', '05', '06', '07')
and (c.status_cp is null or (c.status_cp<>'CANCELADO'))
union
select 'NFD' tipo,
nd.dataemissao,
nd.numeronota,
null as nserieecf,
null as cod_terminal,
ndi.nitem,
p.grupo_prod,
p.cod_prod, 
p.num_fab_prod,
p.nbm,
p.descr_prod,
ndi.quantid_item,
coalesce(ndi.vl_tot_item,0) VALOR_TOTAL,
coalesce(ndi.vl_tot_item,0) VALOR_LIQUIDO,
'' as NCM,
ndi.cod_empresa,
case when (p.isento_pis = 'S') then '07' else p.cst_pis end cst_pis 
from nf_serie_d_itens ndi
inner join nf_serie_d nd on nd.numeronota = ndi.numeronota and nd.cod_empresa = ndi.cod_empresa
inner join produtos p on p.grupo_prod = ndi.grupo_prod and p.cod_prod = ndi.cod_prod and p.cod_empresa = ndi.cod_empresa
where p.nbm is not null and p.nbm<>'' and p.ativo=1
and nd.status = 'FECHADA'
and case when (p.isento_pis = 'S') then '07' else p.cst_pis end in ('04', '05', '06', '07')
union
select 'NFC' tipo,
nfc.data_lanc,
nfc.num_nf,
null as nserieecf,
null as cod_terminal,
nfci.nitem,
p.grupo_prod,
p.cod_prod,
p.num_fab_prod,
p.nbm,
p.descr_prod,
nfci.qcom,
coalesce(nfci.vuncom, 0) as valor_unitario,
coalesce(nfci.vprod, 0) as valor_total,
'' as NCM,
nfci.cod_empresa,
case when (p.isento_pis = 'S') then '07' else p.cst_pis end cst_pis from nfce nfc
inner join nfce_item nfci on nfci.cod_nfce = nfc.cod_nfce and nfci.cod_empresa = nfc.cod_empresa
inner join produtos p on nfci.grupo_prod=p.grupo_prod and nfci.cod_prod=p.cod_prod and nfci.cod_empresa=p.cod_empresa
where p.nbm is not null and p.nbm<>'' and p.ativo=1
and nfc.status = 'Fechada' and nfc.situacao_nfce = 'Autorizada'
and case when (p.isento_pis = 'S') then '07' else p.cst_pis end in ('04', '05', '06', '07')
order by 1,2
;

/* View: ORCAMENTO4, Owner: SYSDBA */
CREATE VIEW ORCAMENTO4 (COD_EMPRESA, TIPO, PROD_SERV, NITEM, NPED, COD_PROD_SER, GRUPO_PROD, COD_PROD, COD_SERVICO, ORIGEM_SERVICO, NUM_FAB_PROD, ID_KIT, CODIGO_KIT, DESCRICA0_KIT, VALOR_UN_KIT, VALOR_KIT, VALOR_UN_KIT_LIQ, VALOR_KIT_LIQ, RATEIO_ACRESC_KIT, RATEIO_DESC_KIT, UNIDADE, DESCRICAO, COD_GRADE, QUANTIDADE, VL_UNITARIO, VL_TOTAL_ITEM, UNIDADE_CONV, QUANTIDADE_CONV, VL_UNITARIO_CONV, OPERACAO_CONV, FATOR_CONV, RATEIO_DESC, RATEIO_ACRESC, MARCA_P, STATUS, NCM, COD_TECNICO_MECAN, NOME_TECNICO_MECAN, COD_TECNICO_MECAN2, NOME_TECNICO_MECAN2, NCUPOM, N_NF, ICM_PROD, ISENTO_PROD, N_INCIDENCIA_PROD, CST_PROD, TIPO_FOTO, ORDEM) AS

select pvp.cod_empresa, pvp.tipo, 'PRODUTO', pvp.nitem,
pvp.nped, 'P-'||p.num_fab_prod, pvp.grupo_prod, pvp.cod_prod, null, null, pvp.num_fab_prod,
pvp.id_kit, pvp.codigo_kit, case when (pvp.codigo_kit > 0) then k.descricao_kit else pvp.descr_prod_ped end descricao_kit,
(select sum(coalesce(pedvenda_prod.vltot_ped_item, 0)) from pedvenda_prod
    where pedvenda_prod.nped = pvp.nped
    and pedvenda_prod.tipo = pvp.tipo
    and pedvenda_prod.cod_empresa = pvp.cod_empresa
    and pedvenda_prod.codigo_kit = pvp.codigo_kit
    and pedvenda_prod.id_kit = pvp.id_kit
    and pedvenda_prod.cod_empresa = pvp.cod_empresa
    and coalesce(pvp.status, '') <> 'CANCELADO') valor_un_kit,
(select sum(coalesce(pedvenda_prod.vltot_ped_item, 0)) from pedvenda_prod
    where pedvenda_prod.nped = pvp.nped
    and pedvenda_prod.tipo = pvp.tipo
    and pedvenda_prod.cod_empresa = pvp.cod_empresa
    and pedvenda_prod.codigo_kit = pvp.codigo_kit
    and pedvenda_prod.id_kit = pvp.id_kit
    and pedvenda_prod.cod_empresa = pvp.cod_empresa
    and coalesce(pvp.status, '') <> 'CANCELADO') valor_kit,
(select sum(coalesce(pedvenda_prod.vltot_ped_item, 0) + coalesce(pedvenda_prod.rateio_acresc, 0) - coalesce(pedvenda_prod.rateio_desc, 0)) from pedvenda_prod
    where pedvenda_prod.nped = pvp.nped
    and pedvenda_prod.tipo = pvp.tipo
    and pedvenda_prod.cod_empresa = pvp.cod_empresa
    and pedvenda_prod.codigo_kit = pvp.codigo_kit
    and pedvenda_prod.id_kit = pvp.id_kit
    and pedvenda_prod.cod_empresa = pvp.cod_empresa
    and coalesce(pvp.status, '') <> 'CANCELADO') valor_un_kit_liq,
(select sum(coalesce(pedvenda_prod.vltot_ped_item, 0) + coalesce(pedvenda_prod.rateio_acresc, 0) - coalesce(pedvenda_prod.rateio_desc, 0)) from pedvenda_prod
    where pedvenda_prod.nped = pvp.nped
    and pedvenda_prod.tipo = pvp.tipo
    and pedvenda_prod.cod_empresa = pvp.cod_empresa
    and pedvenda_prod.codigo_kit = pvp.codigo_kit
    and pedvenda_prod.id_kit = pvp.id_kit
    and pedvenda_prod.cod_empresa = pvp.cod_empresa
    and coalesce(pvp.status, '') <> 'CANCELADO') valor_tot_kit_liq,
(select sum(coalesce(pedvenda_prod.rateio_acresc, 0)) from pedvenda_prod
    where pedvenda_prod.nped = pvp.nped
    and pedvenda_prod.tipo = pvp.tipo
    and pedvenda_prod.cod_empresa = pvp.cod_empresa
    and pedvenda_prod.codigo_kit = pvp.codigo_kit
    and pedvenda_prod.id_kit = pvp.id_kit
    and pedvenda_prod.cod_empresa = pvp.cod_empresa
    and coalesce(pvp.status, '') <> 'CANCELADO') rateio_acresc_kit,
(select sum(coalesce(pedvenda_prod.rateio_desc, 0)) from pedvenda_prod
    where pedvenda_prod.nped = pvp.nped
    and pedvenda_prod.tipo = pvp.tipo
    and pedvenda_prod.cod_empresa = pvp.cod_empresa
    and pedvenda_prod.codigo_kit = pvp.codigo_kit
    and pedvenda_prod.id_kit = pvp.id_kit
    and pedvenda_prod.cod_empresa = pvp.cod_empresa
    and coalesce(pvp.status, '') <> 'CANCELADO') rateio_desc_kit,
pvp.unidade, pvp.descr_prod_ped, pvp.cod_grade,
coalesce(pvp.quant_ped_item, 0) quant_ped_item,
coalesce(pvp.vlun_ped_item, 0) vlun_ped_item,
coalesce(pvp.vltot_ped_item, 0) vltot_ped_item,
pvp.unidade_conv,
case when (trim(coalesce(pvp.unidade_conv, '')) = '') then
       coalesce(pvp.quant_ped_item, 0)
     when (trim(coalesce(pvp.unidade, '')) = trim(coalesce(pvp.unidade_conv, ''))) then
       coalesce(pvp.quant_ped_item, 0)
     when ((coalesce(pvp.operacao_conv, '') = 'M') and (coalesce(pvp.fator_conv, 0) > 0)) then
       (coalesce(pvp.quant_ped_item, 0) * coalesce(pvp.fator_conv, 0))
     when ((coalesce(pvp.operacao_conv, '') = 'D') and (coalesce(pvp.fator_conv, 0) > 0)) then
       (coalesce(pvp.quant_ped_item, 0) / coalesce(pvp.fator_conv, 0))
     else
       coalesce(pvp.quant_ped_item, 0)
end quant_ped_item_conv,
case when (trim(coalesce(pvp.unidade_conv, '')) = '') then
       coalesce(pvp.vlun_ped_item, 0)
     when (trim(coalesce(pvp.unidade, '')) = trim(coalesce(pvp.unidade_conv, ''))) then
       coalesce(pvp.vlun_ped_item, 0)
     when ((coalesce(pvp.operacao_conv, '') = 'M') and (coalesce(pvp.fator_conv, 0) > 0)) then
       (coalesce(pvp.vlun_ped_item, 0) / coalesce(pvp.fator_conv, 0))
     when ((coalesce(pvp.operacao_conv, '') = 'D') and (coalesce(pvp.fator_conv, 0) > 0)) then
       (coalesce(pvp.vlun_ped_item, 0) * coalesce(pvp.fator_conv, 0))
     else
       coalesce(pvp.vlun_ped_item, 0)
end vlun_ped_item_conv,
pvp.operacao_conv,
pvp.fator_conv,
coalesce(pvp.rateio_desc,0) as rateio_desc,
coalesce(pvp.rateio_acresc,0) as rateio_acresc,
p.marca_p, pvp.status,
p.nbm, pvp.cod_vendedor, col.nome_vendedor, pvp.col_cod_vendedor, col2.nome_vendedor,
pv.ncupom, pvp.n_nf, p.icm_prod, p.isento_prod, p.n_incidencia_prod, p.cst_prod,
case when (trim(pvp.tipo) = 'REQ') then -1000 when (trim(pvp.tipo) = 'OS') then -1001 else -1002 end tipo,
1 ordem
from pedvenda_prod pvp
inner join pedvenda pv on pv.nped = pvp.nped and pv.tipo = pvp.tipo and pv.cod_empresa = pvp.cod_empresa
inner join produtos p on pvp.grupo_prod = p.grupo_prod and pvp.cod_prod = p.cod_prod and pvp.cod_empresa = p.cod_empresa
left join kits_prod k on k.codigo_kit = pvp.codigo_kit and k.cod_empresa = pvp.cod_empresa
left join colaborador col on col.cod_vendedor = pvp.cod_vendedor and col.cod_empresa = pvp.cod_empresa
left join colaborador col2 on col2.cod_vendedor = pvp.col_cod_vendedor and col2.cod_empresa = pvp.cod_empresa
where pvp.ativo=1
union
select pvs.cod_empresa,pvs.tipo, 'SERVICO',pvs.nitem,
pvs.nped, 'S-'||(select result from strzero(pvs.cod_servico, 5)), null, null, pvs.cod_servico, coalesce(tp.stipo, ''), null,
null, null, pvs.desc_serv_ped, null, null, null, null, null, null,
null, pvs.desc_serv_ped, null, pvs.quant_serv_ped,
coalesce(pvs.valor_un_serv, 0) valor_un_serv,
coalesce(pvs.valor_tot_serv, 0) valor_tot_serv,
null, pvs.quant_serv_ped as quant_serv_ped_conv,
coalesce(pvs.valor_un_serv, 0) as valor_un_serv_conv,
null, null,
coalesce(pvs.rateio_desc,0) as rateio_desc,
coalesce(pvs.rateio_acresc,0) as rateio_acresc,
null, pvs.status,
null, pvs.cod_vendedor, col.nome_vendedor, pvs.cod_vendedor1, col2.nome_vendedor,
null, null, null, null, null, null,
case when (trim(pvs.tipo) = 'REQ') then -1000 when (trim(pvs.tipo) = 'OS') then -1001 else -1002 end tipo,
2 ordem
from pedvenda_serv pvs
inner join pedvenda pv on pv.nped = pvs.nped and pv.tipo = pvs.tipo and pv.cod_empresa = pvs.cod_empresa
left join tipo_servico tp on tp.cod_servico = pvs.cod_servico
left join colaborador col on pvs.cod_vendedor = col.cod_vendedor and pvs.cod_empresa = col.cod_empresa
left join colaborador col2 on pvs.cod_vendedor1 = col2.cod_vendedor and pvs.cod_empresa = col2.cod_empresa
where pvs.ativo=1
union
select vpt.cod_empresa, vpt.tipo, 'PRODUTOT', vpt.seqid,
vpt.nped, 'PROD-T', null, null, null, null, null,
null, null, vpt.descricao, null, null, null, null, null, null,
vpt.unidade, vpt.descricao, null, vpt.qtde,
vpt.vl_unit, vpt.vl_total,
null, vpt.qtde as qtde_conv, vpt.vl_unit as vl_unit_conv, null, null,
0, 0, null, null, null, null, null, null, null,
null, null,  null, null, null, null,
case when (trim(vpt.tipo) = 'REQ') then -1000 when (trim(vpt.tipo) = 'OS') then -1001 else -1002 end tipo,
3 ordem  from pedvenda pv
inner join pedvenda_prod_terc vpt on pv.nped=vpt.nped and pv.cod_empresa=vpt.cod_empresa and pv.tipo=vpt.tipo
where vpt.ativo=1
union
select vst.cod_empresa, vst.tipo, 'SERVICOT', vst.seqid,
vst.nped, 'SERV-T', null, null, null, null, null,
null, null, vst.descr_servt, null, null, null, null, null, null,
null, vst.descr_servt, null, 1,
vst.vl_servt, vst.vl_servt,
null, 1, vst.vl_servt, null, null,
0, 0, null, null, null, null, null, null, null,
null, null, null, null, null, null,
case when (trim(vst.tipo) = 'REQ') then -1000 when (trim(vst.tipo) = 'OS') then -1001 else -1002 end tipo,
4 ordem  from pedvenda pv
inner join pedvenda_serv_terc vst on pv.nped = vst.nped and pv.cod_empresa = vst.cod_empresa and pv.tipo = vst.tipo
where vst.ativo=1
;

/* View: VENDAS_GERAIS, Owner: SYSDBA */
CREATE VIEW VENDAS_GERAIS (TIPO, NPED, DATA_VENDA, VALOR_VENDA, VALOR_REAL, VALOR_NF, NUM_NF, DATA_NF, NCUPOM, DATA_CUPOM, VALOR_CUPOM, COD_CLIENTE, NOME_CLIENTE, NOME_VENDEDOR, OPERADOR, OPERADORBAL, DIA_CXL, STATUS_CXL, COD_EMPRESA, COD_EMP_MULT, VENDA, TIPV) AS

select pd.tipo as tp_doc,pd.nped,pd.data_fech,pd.valor_total,pd.valor_total as valor_real,
pd.valor_total as valor_nf,pd.num_nf,pd.data_nf,pd.ncupom,pd.data_cupom,((cp.valorcupom-cp.valor_desc)+cp.valor_acres) as valorcupom,cl.cod_cliente,
cl.nome_cliente,v.nome_vendedor,pd.op_cxl,pd.operador,pd.dia_cxl,pd.STATUS_CXL_RQ,
(case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pd.cod_empresa end) cod_empresa,
pd.cod_empresa,
tv.venda,pd.tipv from pedvenda pd
inner join empresa emp on pd.cod_empresa = emp.cod_empresa
inner join clientes cl on pd.cod_cliente = cl.cod_cliente and pd.cod_empresa = cl.cod_empresa
inner join colaborador v on pd.cod_vendedor = v.cod_vendedor and pd.cod_empresa = v.cod_empresa
left join cupom cp on pd.ncupom = cp.cupom and pd.NSERIEECF = cp.NSERIEECF and pd.cod_empresa = cp.cod_empresa
inner join tipo_vendas tv on pd.tipo=tv.tipo and (pd.tipv=tv.sigla or (pd.tipo_os=tv.tipo_os))
where pd.data_fech  >= '01/01/2010' and coalesce(pd.status_ped, '') <> 'CANCELADO'
union
select 'MOT' as tp_doc,pd.n_comando,pd.data_ven,pd.valor_a_rec,pd.valor_real,
pd.prven_v,pd.num_nota_v,pd.data_ven,0 as ncupom, cast('01/01/2001' as timestamp) as data_cupom,0 as valorcupom,cl.cod_cliente,
cl.nome_cliente,v.nome_vendedor,pd.op_cxl,pd.covend_v,pd.dia_cxl,pd.STATUS_CXL_RQ,
(case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pd.cod_empresa end) cod_empresa,
pd.cod_empresa,
tv.venda, 'V'
from com_fat pd
inner join empresa emp on pd.cod_empresa = emp.cod_empresa
inner join clientes cl on pd.clientes_v = cl.cod_cliente and pd.cod_empresa = cl.cod_empresa
inner join colaborador v on pd.covend_v = v.cod_vendedor and pd.cod_empresa = v.cod_empresa
inner join tipo_vendas tv on tv.tipo = 'VEI' and pd.tipo_v = tv.tipo_os
where pd.data_ven  >= '01/01/2010' and pd.natureza = 'S' and (coalesce(pd.status_v, '') = 'FECHADO')
;

/* View: DEB_JUR, Owner: SYSDBA */
CREATE VIEW DEB_JUR (N_CONTA_PLC, NOME, DATA_ENT_CTP, TIPO_DOC, N_DOC, HISTORICO, DATA_VENC, VALOR, TERCEIRO, CONTROLE, DATA_QUITACAO, CODIGO_EMP, COD_EMP_MULT, TIPODOC_CTP, DATA_BAIXA, NDOC_V, LOTE_QUIT, CODIGO_VEND, CODSEQ, TPDOC, COD_CLIENTE, STATUS_C, VALOR_CORR, EXIBIR_RESUMO_FINANCEIRO) AS

-- VIEW EXIBE AS CONTAS A PAGAR
-- RELATORIO "RESUMO FINANCEIRO" EXIBIDO NA PARTE DAS CONTAS A PAGAR VENCIDAS
select ctp.n_conta_plc, ctp.nome_for_ctp, ctp.data_ent_ctp, ctp.tipo_ctp, ctp.n_doc_ctp,
    ctp.historico_ctp, ctp.data_venc_ctp, ctp.valor_ctp, '' terceiro,
    ctp.codigo_ctrl, ctp.datq_ctp,
    (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else ctp.codigo_emp end) cod_empresa,
    ctp.cod_emp_mult, ctp.tipo_ctp,
    ctp.data_venc_ctp, ctp.n_doc_ctp, ctp.lote, ctp.us_cad,
    ctp.cod_contrp, 'CTP', ctp.cod_forn_nfe, ctp.status_ctp, ctp.valor_ctp, coalesce(ctr.exibir_resumo_financeiro, 'S')
    from contas_a_pagar ctp
    left join empresa emp on ctp.codigo_emp = emp.cod_empresa
    inner join controles ctr on ctr.codigo_ctrl = ctp.codigo_ctrl and ctr.codigo_emp = ctp.codigo_emp
;

/* View: PROD_PISCOFINS, Owner: SYSDBA */
CREATE VIEW PROD_PISCOFINS (TIPO, NATUREZA_NF, DATA_LANC, NUM_NF_CUMPOM, NSERIEECF, COD_TERMINAL, NITEM, GRUPO_PROD, COD_PROD, NUM_FAB_PROD, NBM, DESCR_PROD, QUANTIDADE, VALOR_UNITARIO, VALOR_TOTAL, NCM, COD_EMPRESA, VALOR_PIS, VALOR_COFINS, TOTPIS_COFINS) AS

select
'NF' as Tipo,
nf.natureza_nf,
nf.data_lanc,
nf.num_nf,
null as nserieecf,
0 as cod_terminal,
inf.nitem,
p.grupo_prod,
p.cod_prod,
p.num_fab_prod,
p.nbm,
p.descr_prod,
coalesce(inf.quantidade,0) as quantidade,
coalesce(inf.valor_unitario,0)-(coalesce(inf.rateio_desconto,0)/coalesce(inf.quantidade,1)) as valor_unitario,
coalesce(inf.valor_total,0)-coalesce(inf.rateio_desconto,0) as valor_total,
inf.ncm,
inf.cod_empresa,
coalesce(inf.valor_pis,0) as valor_pis,
coalesce(inf.valor_cofins,0) as valor_cofins,
coalesce((inf.valor_pis + inf.valor_cofins),0) as totPIS_COFINS
from notafiscal nf
inner join notafiscal_item inf on nf.cod_nf=inf.cod_nf and nf.cod_empresa=inf.cod_empresa
inner join produtos p on inf.grupo_prod=p.grupo_prod and inf.cod_prod=p.cod_prod and inf.cod_empresa=p.cod_empresa
where p.ativo=1 and (nf.status ='Fechada')
union
select
'ECF' as Tipo,
'S' as natureza_nf,
c.data,
c.cupom, 
c.nserieecf,
c.cod_terminal,
c2.registro,
p.grupo_prod,
p.cod_prod,
p.num_fab_prod,
p.nbm,
p.descr_prod,
coalesce(c2.quantidade,0) as quantidade,
coalesce(c2.preco,0)+
(((coalesce(c2.perc_acresc,0)+coalesce(c2.rat_acres,0))/coalesce(c2.quantidade,1))-
((coalesce(c2.rat_desc,0)+coalesce(c2.perc_desc,0))/coalesce(c2.quantidade,1))) as valor_unitario,
(coalesce(c2.total,0)+coalesce(c2.perc_acresc,0)+coalesce(c2.rat_acres,0)-coalesce(c2.rat_desc,0)-coalesce(c2.perc_desc,0)) as valor_total,
'' as NCM,
c2.cod_empresa,
coalesce(c2.valor_pis,0) as valor_pis,
coalesce(c2.valor_cofins,0) as valor_cofins,
coalesce((c2.valor_pis + c2.valor_cofins),0) as totPIS_COFINS
from cupom c
inner join cupom2 c2 on c.cod_terminal=c2.cod_terminal and c.nserieecf=c2.nserieecf and c.cupom = c2.cupom and c.cod_empresa =c2.cod_empresa and c.registro = c2.ordem
inner join produtos p on c2.grupo_prod=p.grupo_prod and c2.cod_prod=p.cod_prod and c2.cod_empresa=p.cod_empresa
where p.ativo=1 and (c.status_cp is null or c.status_cp<>'CANCELADO')
union
select 'NFD' as Tipo,
'S' as natureza_nf,
nd.dataemissao,
nd.numeronota,
null as nserieecf,
0 as cod_terminal,
ndi.nitem,
p.grupo_prod,
p.cod_prod,
p.num_fab_prod,
p.nbm,
p.descr_prod,
coalesce(ndi.quantid_item, 0) as quantidade,
coalesce(ndi.vl_un_item,0) valor_unitario,
coalesce(ndi.vl_tot_item,0) valor_total,
'' as NCM,
nd.cod_empresa,
0 valor_pis,
0 valor_cofins,
0 totPIS_COFINS
from nf_serie_d_itens ndi
inner join nf_serie_d nd on nd.numeronota = ndi.numeronota and nd.cod_empresa = ndi.cod_empresa
inner join produtos p on p.grupo_prod = ndi.grupo_prod and p.cod_prod = ndi.cod_prod and p.cod_empresa = ndi.cod_empresa
where p.ativo = 1 and nd.status = 'FECHADA'
union
select 'NFC' tipo,
'S' as natureza_nf,
nfc.data_lanc,
nfc.num_nf,
null as nserieecf,
0 as cod_terminal,
nfci.nitem,
p.grupo_prod,
p.cod_prod,
p.num_fab_prod,
p.nbm,
p.descr_prod,
coalesce(nfci.qcom, 0) quantidade,
coalesce(nfci.vuncom, 0) valor_unitario,
coalesce(nfci.vprod, 0) valor_total,
'' as NCM,
nfc.cod_empresa,
0 valor_pis,
0 valor_cofins,
0 totPIS_COFINS
from nfce nfc
inner join nfce_item nfci on nfci.cod_nfce = nfc.cod_nfce and nfci.cod_empresa = nfc.cod_empresa
inner join produtos p on nfci.grupo_prod=p.grupo_prod and nfci.cod_prod=p.cod_prod and nfci.cod_empresa=p.cod_empresa
where p.ativo = 1 and nfc.status = 'Fechada' and nfc.situacao_nfce = 'Autorizada'
order by 1,2
;

/* View: RECEB_DOCS, Owner: SYSDBA */
CREATE VIEW RECEB_DOCS (TP_RECEBIMENTO, TIPO, NPED, NOME_CTRL, DATA_FECH, VALOR_DOC, SEQFORM, N_DOC, COD_CLIENTE, COD_EMPRESA, NOME_CLIENTE, VALOR_TOTAL, NRECIBO, VALOR_RECIBO, DATA_VENC, N_PROCESSAMENTO, DATA_MOV) AS

select 'DIRETO' as tipo,pd.tipo as tipo_ped,pd.nped,
case when ctrl.nome_ctrl is null then 'SEM FORMA' else ctrl.nome_ctrl end as nome_ctrl,
pd.data_fech,fr.valordoc,fr.seqform,fr.ndoc,pd.cod_cliente,pd.cod_empresa,
fr.cliente,pd.valor_total,coalesce(fr.rec_numvend,0) as num_recibo,0 as valor_recibo,
fr.data_venc,fr.n_processamento,fr.data_mov
from pedvenda pd left join formpagamento fr on pd.tipo = fr.tpdocs and pd.nped = fr.nrequisicao and
pd.cod_empresa = fr.cod_empresa and fr.recibo is null left join
controles ctrl on fr.cod_controle = ctrl.codigo_ctrl and fr.cod_empresa = ctrl.codigo_emp
where (pd.tipo <> 'MOT' and pd.tipo <> 'ORC') and  pd.data_fech >= '01/01/2011' and
pd.valor_total <> 0 and
coalesce((select count(*) from formpagamento frc where frc.nrequisicao = pd.nped and
frc.tpdocs = pd.tipo and frc.cod_empresa = pd.cod_empresa and (not frc.recibo is null)),0) <= 0
union
select 'RECIBO' as tipo,pd.tipo as tipo_ped,pd.nped,
case when (select first 1 ctrl.nome_ctrl from controles ctrl inner join formpagamento rc
on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
where rc.nrequisicao = fr.rec_numvend and rc.cod_empresa = fr.cod_empresa and rc.tpdocs ='REC' order by valordoc asc)
is null then 'SEM FORMA' else (select first 1 ctrl.nome_ctrl from controles ctrl inner join formpagamento rc
on rc.cod_controle = ctrl.codigo_ctrl and rc.cod_empresa = ctrl.codigo_emp
where rc.nrequisicao = fr.rec_numvend and rc.cod_empresa = fr.cod_empresa and rc.tpdocs ='REC' order by valordoc asc) end as nome_ctrl,
pd.data_fech,fr.valordoc,fr.seqform,fr.ndoc,pd.cod_cliente,pd.cod_empresa,fr.cliente,pd.valor_total,coalesce(fr.rec_numvend,0) as num_recibo,
(select sum(rc.valor_orig) from recibos rc where rc.nrecibo = fr.rec_numvend and rc.cod_empresa = fr.cod_empresa) as valor_recibo,
fr.data_venc,fr.n_processamento,fr.data_mov
from pedvenda pd inner join formpagamento fr on pd.tipo = fr.tpdocs and pd.nped = fr.nrequisicao and
pd.cod_empresa = fr.cod_empresa and (not fr.recibo is null)
where (pd.tipo <> 'MOT' and pd.tipo <> 'ORC') and  pd.data_fech >= '01/01/2011'
and pd.valor_total <> 0
;

/* View: SALDOS_CTR_LANCAMENTOS, Owner: SYSDBA */
CREATE VIEW SALDOS_CTR_LANCAMENTOS (COD_LANC, CODIGO_CTRL, CODIGO_EMP, COD_EMP_MULT, TIPO_L, VALOR_L, DATA_ANT, DATA, VAL_SLD, VALOR_SLD_ATUAL, NOME_CTRL, HISTORICO, DOCS, LOTE, EXIBIR_RESUMO_FINANCEIRO) AS

-- VIEW EXIBE OS SALDOS POR CONTROLE DIARIAMENTE
-- RELATORIO "RESUMO FINANCEIRO", "ENTRADAS E SADAS POR CONTROLE FINANCEIRO" E "ENTRADAS E SADAS POR CONTROLE FINANCEIRO E DATA"
    SELECT DISTINCT LANC.COD_LANC, LANC.CODIGO_CTRL, LANC.CODIGO_EMP, LANC.COD_EMP_MULT, LANC.TIPO_L,
    LANC.VALOR_L, (LANC.DATA -1) DATA_ANT, LANC.DATA, COALESCE(SAL.VAL_SLD, 0) VAL_SLD,
    COALESCE(SALT.VAL_SLD, 0) VALOR_SLD_ATUAL, CTR.NOME_CTRL, LANC.HISTORICO_L, CTR.DOCS,
    (CASE WHEN (LANC.LOTE > 0) THEN LANC.LOTE  ELSE (CASE WHEN (LANC.LOTE_QUIT >0) THEN LANC.LOTE_QUIT ELSE LANC.LOTE_ENT END) END),
    COALESCE(CTR.EXIBIR_RESUMO_FINANCEIRO, 'S') FROM LANCAMENTOS LANC
    INNER JOIN CONTROLES CTR ON CTR.CODIGO_CTRL = LANC.CODIGO_CTRL AND CTR.CODIGO_EMP = LANC.CODIGO_EMP
    LEFT JOIN SAL_CTRL SAL ON SAL.CODIGO_CTRL = LANC.CODIGO_CTRL AND SAL.DATA_SLD = (LANC.DATA - 1) AND SAL.COD_EMP = LANC.CODIGO_EMP
    LEFT JOIN SAL_CTRL SALT ON SALT.CODIGO_CTRL = LANC.CODIGO_CTRL AND SALT.DATA_SLD = LANC.DATA AND SALT.COD_EMP = LANC.CODIGO_EMP
;

/* View: COMPRASMESESV4, Owner: SYSDBA */
CREATE VIEW COMPRASMESESV4 (NUM_NOTA, CHASSI, DATA_CH_NOTA, DESCRICAO_VERSAO, COR, ANO_FAB, ANO_MOD, CUSTO, COD_EMPRESA) AS

select it.num_nota,it.chassi_c,et.data_ch_nota,it.descricao_versao,
it.cor,it.ano_fab,it.ano_mod,((et.valor_tot_nota/et.qtde_motos_nota)+it.piscofins),et.cod_empresa
from ent_moto_itens it,ent_moto et
where
it.num_nota = et.num_nota
and it.cod_fornecedor = et.cod_fornecedor and 
(et.cod_fisc_nota <> 1409 and
et.cod_fisc_nota <> 2409 and et.cod_fisc_nota <> 1913)
and it.cod_empresa = et.cod_empresa and et.ativo = 1
union
select nf4.num_nf,it4.chassi,nf4.data_lanc,substr(it4.descricao_item,1,25),
itv4.cor,itv4.ano_fab,itv4.ano_mod,it4.prec_cusm_prod,nf4.cod_empresa
from notafiscal nf4 inner join notafiscal_item it4 on
nf4.cod_nf=it4.cod_nf and nf4.cod_empresa=it4.cod_empresa
inner join notafiscal_item_veiculo itv4
on it4.cod_nf=itv4.cod_nf and it4.cod_empresa = itv4.cod_empresa and
it4.chassi = itv4.chassi
where nf4.natureza_nf='E' and (nf4.status = 'Fechada')
and (nf4.codigo_nop <> 1409 and nf4.tipo_nf = 'V' and
nf4.codigo_nop <> 2409 and nf4.codigo_nop <> 1913)
and nf4.ativo=1
;

/* View: FICHAVENDAPROD, Owner: SYSDBA */
CREATE VIEW FICHAVENDAPROD (TP, NOME_CLIENTE, NDOC, VALOR, DATA, DATA_FECH, DESCR_PROD, NUM_FAB_PROD, QTDE, VL_UNIT, VL_TOT, COD_CLIENTE, COD_EMPRESA, COD_PROD, GRUPO_PROD) AS

select 'REQ',cl.nome_cliente, r.nreq, r.valor_total, r.data_req, r.data_c, ri.desc_prod_req,
ri.num_fab_prod, ri.quant_rq_item, ri.vlun_rq_item, ri.vltot_rq_item,
r.cod_cliente, r.cod_empresa, P.cod_prod, p.grupo_prod
from reqvenda r
inner join reqvenda_itens ri on ri.nreq = r.nreq and ri.cod_empresa = r.cod_empresa
inner join clientes cl on cl.cod_cliente = r.cod_cliente and cl.cod_empresa = r.cod_empresa
inner join produtos p on p.cod_prod = ri.cod_prod and p.grupo_prod = ri.grupo_prod and p.cod_empresa = ri.cod_empresa
where ri.n_nf is null and r.ativo = 1
union
select 'OS ',cl.nome_cliente ,os.n_os, os.valor_os, os.data_os, os.data_fec_os, osi.desc_os_prod,
osi.num_fab_prod, osi.quant_os_prod, osi.vl_unt_os_prod, osi.vl_tot_os_prod,
os.cod_cliente, os.cod_empresa , P.cod_prod, p.grupo_prod
from ordem_serv os
inner join os_item_prod osi on os.n_os = osi.n_os and os.cod_empresa = osi.cod_empresa
inner join clientes cl on cl.cod_cliente = os.cod_cliente and cl.cod_empresa = os.cod_empresa
inner join produtos p on p.cod_prod = osi.cod_prod and p.grupo_prod = osi.grupo_prod and p.cod_empresa = osi.cod_empresa
where osi.n_nf is null and os.ativo = 1
union
select 'NF ',cl.nome_cliente ,nf.num_nf_vnd, nf.vl_tot_vnd, nf.data_em_vnd, nf.data_ets_vnd, nfi.desc_prod_nf,
nfi.num_fab_prod, nfi.quant_item_vnd, nfi.vlun_item_vnd, nfi.vltot_item_vnd,
nf.cod_cliente, nf.cod_empresa, P.cod_prod, p.grupo_prod
from nf_venda nf
inner join item_nfvenda nfi on nf.num_nf_vnd = nfi.num_nf_vnd and nf.cod_empresa = nfi.cod_empresa
inner join clientes cl on cl.cod_cliente = nf.cod_cliente and cl.cod_empresa = nf.cod_empresa
inner join produtos p on p.cod_prod = nfi.cod_prod and p.grupo_prod = nfi.grupo_prod and p.cod_empresa = nfi.cod_empresa
and nf.sub_serie = nfi.sub_serie where nf.ativo = 1
;

/* View: MOVIMENTOSPRODSERV, Owner: SYSDBA */
CREATE VIEW MOVIMENTOSPRODSERV (TIPOPS, TIPO, STATUS_PED, VALOR_TOTAL, COD_CLIENTE, NOME_CLIENTE, DATA_PED, DATA_FECH, NPED, NITEM, COD_PROD, GRUPOOUSEDRV, COD_EMPRESA, NUM_FAB_PROD, COD_GRADE, DESCRICAO_GRADE, QTDE, VL_UNIT, VL_TOT, DESCR, RATEIO_DESC, RATEIO_ACRESC, ACRESC_ITEM, DESC_ITEM, DAV_ORIGEM, NPED_ORIGEM, TIPO_ORIGEM, STATUS_ITEM) AS

  select 'P' tipops ,p.tipo,p.status_ped,p.valor_total,c.cod_cliente,c.nome_cliente,p.data_ped,p.data_fech,
  pp.nped,pp.nitem,pp.cod_prod, pp.grupo_prod grupoOuServ,pp.cod_empresa, pp.num_fab_prod,
  pp.cod_grade, g.descricao,
  pp.quant_ped_item qtde, pp.vlun_ped_item vl_unit, pp.vltot_ped_item vl_tot,pp.descr_prod_ped descr,
  pp.rateio_desc,pp.rateio_acresc,pp.acresc_item, pp.desc_item,
  pp.dav_origem,pp.nped_origem,pp.tipo_origem,pp.status
  from pedvenda_prod pp
  inner join pedvenda p on p.nped = pp.nped and p.cod_empresa = pp.cod_empresa and pp.tipo = p.tipo
  inner join clientes c on c.cod_cliente = p.cod_cliente and c.cod_empresa = p.cod_empresa
  left join grade g on pp.cod_grade = g.cod_grade and pp.cod_empresa = g.cod_empresa
  where p.ativo = 1
  union
  select 'S' tipops,p.tipo,p.status_ped,p.valor_total,c.cod_cliente,c.nome_cliente,p.data_ped,p.data_fech,
  ps.nped,ps.nitem,ps.cod_servico cod_prod,ps.cod_servico grupoOuServ,ps.cod_empresa,ps.cod_servico num_fab_prod,
  null cod_grade, '' descricao,
  ps.quant_serv_ped qtde,ps.valor_un_serv vl_unit, ps.valor_tot_serv vl_tot,
  ps.desc_serv_ped descr,
  ps.rateio_desc,ps.rateio_acresc,ps.acresc_item, ps.desc_item,
  ps.dav_origem,ps.nped_origem,ps.tipo_origem,ps.status
  from pedvenda_serv ps
  inner join pedvenda p on p.nped = ps.nped and p.cod_empresa = ps.cod_empresa and ps.tipo = p.tipo
  inner join clientes c on c.cod_cliente = p.cod_cliente and c.cod_empresa = p.cod_empresa
  where p.ativo = 1
;

/* View: ORCAMENTO3, Owner: SYSDBA */
CREATE VIEW ORCAMENTO3 (COD_EMPRESA, PROD_SERV, NITEM, NPED, COD_PROD_SER, GRUPO_PROD, COD_PROD, DESCRICAO, QUANTIDADE, VL_UNITARIO, VL_TOTAL_ITEM, RATEIO_DESC, RATEIO_ACRESC, MARCA_P) AS

select pvp.cod_empresa, 'PRODUTO',pvp.nitem,pvp.nped,'P-'||p.num_fab_prod,pvp.grupo_prod,pvp.cod_prod,pvp.descr_prod_ped,pvp.quant_ped_item,
pvp.vlun_ped_item,pvp.vltot_ped_item,
case when (pv.desc_p_prod is null) and (pv.desconto is null) then 0
else (
coalesce(pvp.vltot_ped_item,0) * (coalesce(pv.desc_p_prod,0)/100)) +
((coalesce(pv.desconto,0)/
case when (
coalesce((select sum(pedp.vltot_ped_item) from pedvenda_prod pedp where pedp.nped=pv.nped and pedp.cod_empresa=pv.cod_empresa),0)
+coalesce((select sum(peds.valor_tot_serv) from pedvenda_serv peds where peds.nped=pv.nped and peds.cod_empresa=pv.cod_empresa),0)
) =0 then 1 else (
coalesce((select sum(pedp.vltot_ped_item) from pedvenda_prod pedp where pedp.nped=pv.nped and pedp.cod_empresa=pv.cod_empresa),0)
+coalesce((select sum(peds.valor_tot_serv) from pedvenda_serv peds where peds.nped=pv.nped and peds.cod_empresa=pv.cod_empresa),0)
) end
)*coalesce(pvp.vltot_ped_item,0))
end as rateio_desc,
coalesce(pvp.rateio_acresc,0) as rateio_acresc,p.marca_p
from pedvenda pv inner join pedvenda_prod pvp on pv.nped=pvp.nped and pv.cod_empresa=pvp.cod_empresa and pv.tipo=pvp.tipo inner join produtos p on pvp.grupo_prod=p.grupo_prod and pvp.cod_prod=p.cod_prod and pvp.cod_empresa=p.cod_empresa
where pvp.tipo='ORC' and pvp.ativo=1
union
select pvs.cod_empresa, 'SERVICO',pvs.nitem,pvs.nped,'S-'||pvs.cod_servico,null, null, pvs.desc_serv_ped,pvs.quant_serv_ped,
pvs.valor_un_serv,pvs.valor_tot_serv,
case when (pv.desc_p_serv is null) and (pv.desconto is null) then 0
else (coalesce(pvs.valor_tot_serv,0)*(coalesce(pv.desc_p_serv,0)/100)) +
((coalesce(pv.desconto,0)/
case when(
coalesce((select sum(pedp.vltot_ped_item) from pedvenda_prod pedp where pedp.nped=pv.nped and pedp.cod_empresa=pv.cod_empresa),0)+
coalesce((select sum(peds.valor_tot_serv) from pedvenda_serv peds where peds.nped=pv.nped and peds.cod_empresa=pv.cod_empresa),0)
)=0 then 1 else (
coalesce((select sum(pedp.vltot_ped_item) from pedvenda_prod pedp where pedp.nped=pv.nped and pedp.cod_empresa=pv.cod_empresa),0)+
coalesce((select sum(peds.valor_tot_serv) from pedvenda_serv peds where peds.nped=pv.nped and peds.cod_empresa=pv.cod_empresa),0)
) end
)*coalesce(pvs.valor_tot_serv,0))
end as rateio_desc,
coalesce(pvs.rateio_acresc,0) as rateio_acresc,null
from pedvenda pv inner join pedvenda_serv pvs on pv.nped=pvs.nped and pv.cod_empresa=pvs.cod_empresa and pv.tipo=pvs.tipo
where pvs.tipo='ORC' and pvs.ativo=1
union
select vpt.cod_empresa, 'PRODUTOT',null,vpt.nped, 'PROD-T',null,null,vpt.descricao,vpt.qtde,vpt.vl_unit,vpt.vl_total,0, 0,null  from pedvenda pv inner join pedvenda_prod_terc vpt on pv.nped=vpt.nped and pv.cod_empresa=vpt.cod_empresa and pv.tipo=vpt.tipo
where vpt.tipo='ORC' and vpt.ativo=1
union
select vst.cod_empresa, 'SERVICOT',null,vst.nped, 'SERV-T',null,null,vst.descr_servt,1,vst.vl_servt,vst.vl_servt,0, 0,null  from pedvenda pv inner join pedvenda_serv_terc vst on pv.nped=vst.nped and pv.cod_empresa=vst.cod_empresa and pv.tipo=vst.tipo
where vst.tipo='ORC' and vst.ativo=1
;

/* View: CRED_JUR, Owner: SYSDBA */
CREATE VIEW CRED_JUR (N_CONTA_PLC, NOME, DATA_REC, TIPO_DOC, N_DOC, HISTORICO, DATA_VENC, VALOR, TERCEIRO, CONTROLE, DATA_QUITACAO, CODIGO_EMP, COD_EMP_MULT, TIPODOC_V, DATA_VENDA, NDOC_V, LOTE_QUIT, CODIGO_VEND, CODSEQ, TPDOC, COD_CLIENTE, STATUS_C, VALOR_CORR, VALOR_LIQ, NOME_CTRL, EXIBIR_RESUMO_FINANCEIRO) AS

-- VIEW EXIBE OS CREDITOS E CHEQUES
-- RELATORIO "RESUMO FINANCEIRO" EXIBIDO NA PARTE DAS CONTAS A RECEBER VENCIDAS
select c.n_conta_plc,c.nome_c,c.data_rec_c,c.tipo_doc_c,c.n_doc_c,
       c.historico_c,c.data_venc_c,c.valor_c,c.nome_terc,
       c.codigo_ctrl,c.datq_c,
       (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else c.codigo_emp end) cod_empresa,
       c.cod_emp_mult,c.TP_DOC_V,
       c.DATA_VENDA,c.n_doc_v,c.lote_quit,c.codigo_vend,
       c.cod_cred,'CRED',c.cod_cliente,c.status_c,c.valor_corr,c.valor_liquido,ctr.nome_ctrl, coalesce(ctr.exibir_resumo_financeiro, 'S')
       from controle_creditos c
       left join empresa emp on c.codigo_emp = emp.cod_empresa
       inner join controles ctr on ctr.codigo_ctrl = c.codigo_ctrl and ctr.codigo_emp = c.codigo_emp
union
select ch.n_conta_plc,ch.nome_ch,ch.data_rec,CAST('CHQ            ' as CHAR(15)),ch.n_ch,
       ch.historico_ch,ch.data_venc,ch.valor_ch,CAST(ch.nome_terc AS CHAR(35)),
       ch.codigo_ctrl,ch.datq_ch,
       (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else ch.codigo_emp end) cod_empresa,
       ch.cod_emp_mult,ch.TP_DOC_V,
       ch.DATA_VENDA,ch.n_doc_v,ch.lote_quit,ch.codigo_vend,
       ch.codigo_ch,'CHQ ',ch.cod_cliente,ch.status_ch,ch.valor_corr,ch.valor_ch,ctr.nome_ctrl, coalesce(ctr.exibir_resumo_financeiro, 'S')
       from controle_cheque ch
       left join empresa emp on ch.codigo_emp = emp.cod_empresa
       inner join controles ctr on ctr.codigo_ctrl = ch.codigo_ctrl and ctr.codigo_emp = ch.codigo_emp
;

/* View: SPED_PRESUMIDO, Owner: SYSDBA */
CREATE VIEW SPED_PRESUMIDO (TIPO_DOC, TIPO_ITEM, NUM_DOC, E_S, DATA_LANCAMENTO, DATA_EMISSAO, CST_PIS, CFOP, VALOR_TOTAL, VALOR_LIQUIDO, DESCONTO, NITEM, CODIGO, COD_ITEM, DESCRICAO_ITEM, RECEITA_PIS_COFINS, CREDITO_PIS_COFINS, NCM, NUM_FAB_PROD, COD_EMPRESA, NAT_REC, NSERIE, COD_CLIENTE, BASE_PIS, ALIQ_PIS, ALIQ_COFINS, VALOR_PIS, VALOR_COFINS, MODELO, SERIE, SUBSERIE, SITUACAO) AS

select 'NF' TIPO_DOC,
nfi.tipo_item,
nf.num_nf NUM_DOC,
nf.natureza_nf E_S,
nf.data_lanc as DATA_LANCAMENTO,
nf.data_contabil DATA_EMISSAO,
nfi.cst_pis,
nfi.codigo_nop cfop,
coalesce(nfi.valor_total,0) VALOR_TOTAL,
(coalesce(nfi.valor_total,0) - (coalesce(nfi.rateio_desconto,0) + coalesce(nfi.vpisdeson,0) + coalesce(nfi.vcofinsdeson,0)) +
 coalesce(nfi.rateio_seguro,0) + coalesce(nfi.rateio_outdesp,0) + case when nf.frete_f_nfe = 'S' then 0 else coalesce(nfi.rateio_frete,0) end + coalesce(case when (nfi.valor_icmsub_ant > 0) then 0 else nfi.valor_icmsub end,0) + coalesce(nfi.valor_ipi,0) + coalesce(nfi.nfe_vipidevol,0) + coalesce(nfi.fcp_vfcpst,0) - iif(coalesce(nf.totais_com_deson, 'S') <> 'N', coalesce(nfi.vicmdeson, 0), 0)) VALOR_LIQUIDO,
(coalesce(nfi.rateio_desconto,0) + coalesce(nfi.vpisdeson,0) + coalesce(nfi.vcofinsdeson,0) + iif(coalesce(nf.totais_com_deson, 'S') <> 'N', coalesce(nfi.vicmdeson, 0), 0)) DESCONTO,
nfi.nitem,
nfi.cod_nf codigo,
case when nfi.tipo_item = 'P' then nfi.grupo_prod||'-'||nfi.cod_prod
    when nfi.tipo_item = 'V' then nfi.chassi
    when nfi.tipo_item = 'S' then nfi.cod_servico
    when nfi.tipo_item = 'O' then nfi.cod_nf||'-'||nfi.nitem
    when nfi.tipo_item = 'D' then nfi.cod_nf||'-'||nfi.nitem
    else nfi.num_fab_prod
end COD_ITEM,
nfi.descricao_item,
nt.receita_pis_cofins,
nt.credito_pis_cofins,
nfi.ncm,
nfi.num_fab_prod,
nfi.cod_empresa,
iif(coalesce(p.nat_rec, '') <> '', p.nat_rec, nbm.nat_rec) nat_rec,
'' NSERIE,
nf.cod_cliente,
nfi.base_pis,
nfi.aliq_pis,
nfi.aliq_cofins,
nfi.valor_pis,
nfi.valor_cofins,
nf.modelo_nf modelo,
nf.serie,
nf.subserie,
case when (nf.emissao_propria = 'S' and rtrim(nf.modelo_nf) = '55') then
  case when nf.situacao_nfe = 'Autorizada' then 'REGULAR'
        when nf.situacao_nfe = 'Cancelada' then 'CANCELADO'
        else'OUTROS'
  end
  when nf.status = 'Fechada' then 'REGULAR'
  when nf.status = 'Cancelada' then 'CANCELADO'
  else 'OUTROS'
end SITUACAO
from notafiscal nf
inner join notafiscal_item nfi on nfi.cod_nf = nf.cod_nf and nfi.cod_empresa = nf.cod_empresa
inner join produtos p on p.grupo_prod = nfi.grupo_prod and p.cod_prod = nfi.cod_prod and p.cod_empresa = nfi.cod_empresa
left join nat_op nt on nt.codigo_nop = nfi.codigo_nop
left join nbm on nbm.cod_ncm = nfi.ncm
where nf.status = 'Fechada'
and ( (nf.emissao_propria = 'S' and nf.modelo_nf = '55' and coalesce(nf.situacao_nfe,'') <> '' )
or (nf.emissao_propria = 'S' and nf.modelo_nf <> '55')
or (nf.emissao_propria = 'N') )
AND coalesce(nf.da,  'N') <> 'S'
union
select 'CP',
cp2.prod_serv,
cp.cupom,
'S',
cp.data,
cp.data,
cp2.cst_pis,
cp2.codigo_nop,
cp2.total,
(coalesce(CP2.total,0) + coalesce(cp2.rat_acres,0) + coalesce(cp2.perc_acresc,0) - coalesce(cp2.rat_desc,0) - coalesce(cp2.perc_desc,0) ),
(coalesce(cp2.rat_desc, 0) + coalesce(cp2.perc_desc,0)),
cp2.nitem,
cp.registro,
case when cp2.prod_serv = 'P' then cp2.grupo_prod||'-'||cp2.cod_prod else cp2.grupo_prod end,
cp2.descr_it,
nt.receita_pis_cofins,
nt.credito_pis_cofins,
case when prod_serv = 'P' then p.nbm else '00' end,
case when prod_serv = 'P' then p.num_fab_prod else '' end,
cp.cod_empresa,
iif(coalesce(p.nat_rec, '') <> '', p.nat_rec, nbm.nat_rec) nat_rec,
cp.cod_terminal||'-'||cp.nserieecf,
cp.cliente,
(coalesce(CP2.total,0) + coalesce(cp2.rat_acres,0) + coalesce(cp2.perc_acresc,0) - coalesce(cp2.rat_desc,0) - coalesce(cp2.perc_desc,0) ),
cp2.aliq_pis, 
cp2.aliq_cofins, 
(coalesce(CP2.total,0) + coalesce(cp2.rat_acres,0) + coalesce(cp2.perc_acresc,0) - coalesce(cp2.rat_desc,0) - coalesce(cp2.perc_desc,0) ) * cp2.aliq_pis / 100,
(coalesce(CP2.total,0) + coalesce(cp2.rat_acres,0) + coalesce(cp2.perc_acresc,0) - coalesce(cp2.rat_desc,0) - coalesce(cp2.perc_desc,0) ) * cp2.aliq_cofins / 100,
'2D',
'',
'',
case when rtrim(coalesce(cp.status_cp, '')) = '' then 'REGULAR'
  else cp.status_cp
end
from cupom cp
inner join cupom2 cp2 on cp.cod_terminal = cp2.cod_terminal and cp.nserieecf = cp2.nserieecf and
cp.cod_empresa = cp2.cod_empresa and cp.registro = cp2.ordem and cp.cupom = cp2.cupom
left join nat_op nt on nt.codigo_nop = cp2.codigo_nop
left join produtos p on p.grupo_prod = cp2.grupo_prod and p.cod_prod = cp2.cod_prod and
p.cod_empresa = cp2.cod_empresa
left join tipo_servico ts on ts.cod_servico = cp2.grupo_prod
left join nbm on nbm.cod_ncm = p.nbm
where ((cp2.status_it <> 'CANCELADO') or (cp2.status_it is null))
union
select 'NFS',
'S',
pv.num_nfeext,
'S',
pv.data_nfext,
pv.data_nfext,
ps.cst_pis,
ps.codigo_nop,
coalesce(ps.valor_tot_serv,0),
coalesce(ps.valor_tot_serv,0) + coalesce(ps.rateio_acresc,0) - coalesce(ps.rateio_desc,0),
coalesce(ps.rateio_desc,0),
ps.nitem,
ps.nped,
ps.cod_servico,
ps.desc_serv_ped,
nt.receita_pis_cofins,
nt.credito_pis_cofins,
'00',
'',
ps.cod_empresa,
'',
'',
pv.cod_cliente,
ps.base_pis,
ps.aliq_pis,
ps.aliq_cofins,
ps.valor_pis,
ps.valor_cofins,
'98',
'1',
'',
'REGULAR'
from pedvenda_serv ps
inner join pedvenda pv on pv.nped = ps.nped and pv.tipo = ps.tipo and pv.cod_empresa = ps.cod_empresa
left join nat_op nt on nt.codigo_nop = ps.codigo_nop
where not exists ( -- a partir do momento que usa a nova nfse essa nota externa deixa de funcionar
  select first 1 1 from nfse n
  where n.dhemi between (pv.data_nfext - 31) and (pv.data_nfext + 31) and n.situacao in (5,6,7) and n.cod_empresa = pv.cod_empresa
  and n.nnfse = pv.num_nfeext
)
and pv.num_nfeext > 0 and pv.tipo = 'OS'
and ((ps.lote_nfse = 0 ) or (ps.lote_nfse is null))
union
select 'NFS',
'ST',
pv.num_nfeext,
'S',
pv.data_nfext,
pv.data_nfext,
case when coalesce(ts.cst_pis, '') <> '' then ts.cst_pis else '01' end,
e.cfop_pad_serv,
coalesce(pt.vl_servt,0),
coalesce(pt.vl_servt,0),
0,
1,
pt.nped,
0,
pt.descr_servt,
nt.receita_pis_cofins,
nt.credito_pis_cofins,
'00',
'',
pv.cod_empresa,
'',
'',
pv.cod_cliente,
coalesce(pt.vl_servt,0),
coalesce(e.pis_emp,0),
coalesce(e.cofins_emp,0),
(coalesce(pt.vl_servt,0) * coalesce(e.pis_emp,0) / 100 ),
(coalesce(pt.vl_servt,0) * coalesce(e.cofins_emp,0) / 100),
'98',
'1',
'',
'REGULAR'
from pedvenda_serv_terc pt
inner join pedvenda pv on pv.nped = pt.nped and pv.tipo = pt.tipo and pv.cod_empresa = pt.cod_empresa
left join empresa e on e.cod_empresa = pt.cod_empresa
left join nat_op nt on nt.codigo_nop = e.cfop_pad_serv
left join tipo_servico ts on ts.cod_servico = e.cod_serv_padrao
where not exists (
  select first 1 1 from nfse n
  where n.dhemi between (pv.data_nfext - 31) and (pv.data_nfext + 31) and n.situacao in (5,6,7) and n.cod_empresa = pv.cod_empresa
  and n.nnfse = pv.num_nfeext
)
and pv.num_nfeext > 0 and pv.tipo = 'OS'
union
select 'NFS-e',
'S',
ps.n_nf,
'S',
ps.emissao_nfse,
ps.emissao_nfse,
ps.cst_pis,
ps.codigo_nop,
(coalesce(ps.valor_nfse,0) + coalesce(ps.rateio_desc,0) + coalesce(ps.irrf_servico,0) ),
coalesce(ps.valor_nfse,0) + coalesce(ps.irrf_servico,0),
coalesce(ps.rateio_desc,0),
ps.nitem,
ps.nped,
ps.cod_servico,
ps.desc_serv_ped,
nt.receita_pis_cofins,
nt.credito_pis_cofins,
'00',
'',
ps.cod_empresa,
'',
'',
pv.cod_cliente,
ps.base_pis,
ps.aliq_pis,
ps.aliq_cofins,
ps.valor_pis,
ps.valor_cofins,
'98',
'1',
'',
'REGULAR'
from pedvenda_serv ps
inner join pedvenda pv on pv.nped = ps.nped and pv.tipo = ps.tipo and pv.cod_empresa = ps.cod_empresa
left join nat_op nt on nt.codigo_nop = ps.codigo_nop
where ps.nfse_id is null and ps.status_nfse = 'Autorizada'
and pv.tipo = 'OS' and ps.lote_nfse > 0
union
select 'NF-D',
'P',
nd.numeronota,
'S',
case when nd.dataentrada is null then nd.dataemissao else nd.dataentrada end,
nd.dataemissao,
ndi.cst_pis,
p.codigo_nop,
coalesce(ndi.vl_tot_item,0),
coalesce(ndi.vl_tot_item,0),
0,
ndi.nitem,
ndi.numeronota,
ndi.grupo_prod||'-'||ndi.cod_prod,
ndi.desc_prod,
nt.receita_pis_cofins,
nt.credito_pis_cofins,
p.nbm,
p.num_fab_prod,
ndi.cod_empresa,
iif(coalesce(p.nat_rec, '') <> '', p.nat_rec, nbm.nat_rec) nat_rec,
'',
nd.cod_cliente,
ndi.base_pis,
ndi.aliq_pis,
ndi.aliq_cofins,
ndi.valor_pis,
ndi.valor_cofins,
'02',
nd.serie,
nd.subserie,
case when rtrim(coalesce(nd.status, '')) = 'FECHADA' then 'REGULAR'
  else 'CANCELADO'
end
from nf_serie_d_itens ndi
inner join nf_serie_d nd on nd.numeronota = ndi.numeronota and nd.cod_empresa = ndi.cod_empresa
inner join produtos p on p.grupo_prod = ndi.grupo_prod and p.cod_prod = ndi.cod_prod and p.cod_empresa = ndi.cod_empresa
left join nat_op nt on nt.codigo_nop = p.codigo_nop
left join nbm on nbm.cod_ncm = p.nbm
union
select 'Frete',
'F',
st.num_documento,
'E',
case when st.data_lancamento is null then st.data_emissao else st.data_lancamento end,
st.data_emissao,
st.cst_pis,
cast(st.cfop as double precision),
coalesce(st.valor_total,0),
coalesce(st.valor_total,0),
0,
1,
st.cod_serv_transp,
st.tipo||'-'||st.cif_fob_outros,
t.nome_tr,
nt.receita_pis_cofins,
nt.credito_pis_cofins,
'00',
'',
st.cod_empresa,
'',
'',
'T'||st.cod_transportador,
st.base_pis,
st.aliq_pis,
st.aliq_cofins,
st.valor_pis,
st.valor_cofins,
st.modelo,
st.serie,
ST.sub_serie,
'REGULAR'
from servico_transporte st
inner join transportador t on t.codigo_tr = st.cod_transportador and t.cod_empresa = st.cod_empresa
left join nat_op nt on nt.codigo_nop = st.cfop
where (((st.tipo = 'E') and (st.cif_fob_outros = 2)) or ( (st.tipo = 'S') and (st.cif_fob_outros = 1)))
union
select 'NFC',
'P',
nfc.num_nf,
'S',
nfc.data_lanc,
nfc.data_lanc,
nfci.pis_cst,
nfci.cfop,
coalesce(nfci.vprod, 0),
(coalesce(nfci.vprod, 0) - coalesce(nfci.vdesc, 0)
+ coalesce(nfci.vseg, 0) + coalesce(nfci.voutro, 0) + coalesce(nfci.vfrete, 0)),
coalesce(nfci.vdesc, 0),
nfci.nitem,
nfc.num_nf,
nfci.grupo_prod||'-'||nfci.cod_prod,
nfci.xprod,
nt.receita_pis_cofins,
nt.credito_pis_cofins,
p.nbm,
p.num_fab_prod,
nfc.cod_empresa,
iif(coalesce(p.nat_rec, '') <> '', p.nat_rec, nbm.nat_rec) nat_rec,
'',
nfc.cod_cliente,
iif(coalesce(nfci.pis_valiqprod, 0) > 0, coalesce(nfci.pis_qbcprod, 0), coalesce(nfci.pis_vbc, 0)),-- (coalesce(CP2.total,0) + coalesce(cp2.rat_acres,0) + coalesce(cp2.perc_acresc,0) - coalesce(cp2.rat_desc,0) - coalesce(cp2.perc_desc,0) ),
iif(coalesce(nfci.pis_ppis, 0) > 0, coalesce(nfci.pis_ppis, 0), coalesce(nfci.pis_valiqprod, 0)),-- cp2.aliq_pis,
iif(coalesce(nfci.cofins_pcofins, 0) > 0, coalesce(nfci.cofins_pcofins, 0), coalesce(nfci.cofins_valiqprod, 0)),-- cp2.aliq_cofins,
coalesce(nfci.pis_vpis, 0),
coalesce(nfci.cofins_vcofins, 0),
nfc.modelo,
nfc.serie,
'',
case when (nfc.situacao_nfce = 'Autorizada') then 'REGULAR'
  when (nfc.situacao_nfce = 'Cancelada') then 'CANCELADO'
  when (nfc.situacao_nfce = 'Inutilizada') then 'OUTROS'
  when (nfc.situacao_nfce = 'Denegada') then 'OUTROS'
  else 'OUTROS' end

from nfce nfc
inner join nfce_item nfci on nfci.cod_nfce = nfc.cod_nfce and nfci.cod_empresa = nfc.cod_empresa
inner join produtos p on nfci.grupo_prod = p.grupo_prod and nfci.cod_prod=p.cod_prod and nfci.cod_empresa=p.cod_empresa
left join nat_op nt on nt.codigo_nop = nfci.cfop
left join tipo_servico ts on ts.cod_servico = nfci.grupo_prod
left join nbm on nbm.cod_ncm = p.nbm
where nfc.status = 'Fechada'
union
select
  'NFS-e' TIPO_DOC,
  'S' TIPO_ITEM,
  n.nnfse NUM_DOC,
  iif(n.natureza_emissao in (0,1), 'S', 'E') E_S,
  n.dhemi DATA_LANCAMENTO,
  n.dhemi DATA_EMISSAO,
  n.pc_cst CST_PIS,
  iif(n.natureza_emissao in (0,1), 5933, 1933) CFOP,
  coalesce(n.vserv, 0) VALOR_TOTAL,
  coalesce(n.vserv, 0) - coalesce(n.vdescincond, 0)  VALOR_LIQUIDO,
  coalesce(n.vdescincond, 0) DESCONTO,
  1 N_ITEM,
  n.seqid CODIGO,
  n.cod_servico COD_ITEM,
  n.xdescserv DESCRICAO_ITEM,
  nt.receita_pis_cofins RECEITA_PIS_COFINS,
  nt.credito_pis_cofins CREDITO_PIS_COFINS,
  '00' NCM,
  '' NUM_FAB_PROD,
  n.cod_empresa COD_EMPRESA,
  '' NAT_REC,
  '' NSERIE,
  n.cod_cliente COD_CLIENTE,
  coalesce(n.pc_vbcpiscofins, 0) BASE_PIS,
  coalesce(n.pc_paliqpis, 0) ALIQ_PIS,
  coalesce(n.pc_paliqcofins, 0) ALIQ_COFINS,
  coalesce(n.pc_vpis, 0) VALOR_PIS,
  coalesce(n.pc_vcofins, 0) VALOR_COFINS,
  '98',
  n.serie, 
  '' subserie, 
  'REGULAR' situacao
from nfse n                                                                               
left join empresa emp on emp.cod_empresa = n.cod_empresa
left join tipo_servico ts on ts.cod_servico = n.cod_servico
left join clientes cl on cl.cod_cliente = n.cod_cliente and cl.cod_empresa = n.cod_empresa
left join nat_op nt on nt.codigo_nop = iif(n.natureza_emissao in (0,1), 5933, 1933)
where n.situacao = 5
;

/* View: FICHAPRODUTOS, Owner: SYSDBA */
CREATE VIEW FICHAPRODUTOS (TIPO, NATUREZA, EMPRESA, NUMDOC, NITEM, DATA, CLIENTE, COD_EMPRESA, DESCR_GRUPO, GRUPO_PROD, COD_PROD, COD_GRADE, DESCR_GRADE, NUM_FAB_PROD, DESCR_PROD, EST_F, EST_PROD, PREC_TAB_PROD, PREC_PUBLICO, PREC_CUS_PRD, PREC_CUSM_PRD, ENTRADA, SAIDA, VLTOT_VENDA) AS

select distinct 'VENDA' TIPO, 'S' NATUREZA, emp.nome_emp EMPRESA, ped.nped NUMDOC, pedpro.nitem, ped.data_fech DATA, (cl.cod_cliente ||' - '|| cl.nome_cliente) CLIENTE, pr.cod_empresa,gr.descricao descr_grupo, pr.grupo_prod, pr.cod_prod, coalesce(gra.cod_grade, 0) cod_grade, coalesce(gra.descricao,'SEM GRADE') descr_grade, pr.num_fab_prod, pr.descr_prod,
(case when coalesce(gra.cod_grade, 0) <= 0 then coalesce(pr.est_f,0) else coalesce(gp.qtde,0) end) EST_F,
coalesce(pr.est_f,0) est_prod,
coalesce(pr.prec_tab_prod, 0) prec_tab_prod, coalesce(pr.prec_publico,0) prec_publico,
coalesce(pr.prec_cus_prod,0) prec_cus_prod, coalesce(pr.prec_cusm_prod,0) prec_cusm_prod,
0.00 ENTRADA, coalesce(pedpro.quant_ped_item,0) SAIDA, (coalesce(pedpro.vltot_ped_item,0) + coalesce(pedpro.acresc_item,0) - coalesce(pedpro.desc_item,0)) VLTOT_VENDA
from produtos pr
inner join pedvenda_prod pedpro on pedpro.grupo_prod = pr.grupo_prod and pedpro.cod_prod = pr.cod_prod and pedpro.cod_empresa = pr.cod_empresa and coalesce(pedpro.status,'') <> 'CANCELADO'
inner join pedvenda ped on ped.nped = pedpro.nped and ped.tipo = pedpro.tipo and ped.cod_empresa = pedpro.cod_empresa and ped.tipo <> 'ORC' and (not ped.status_ped is null or ped.status_ped <> '''')
left join grupos gr on gr.codigo_grup = pr.grupo_prod
left join grade gra on gra.cod_grade = pedpro.cod_grade and gra.cod_empresa = pedpro.cod_empresa
left join cod_grade_prod gp on gp.cod_grade = gra.cod_grade and gp.grupo_prod = pr.grupo_prod and gp.cod_prod = pr.cod_prod and gp.cod_empresa = pr.cod_empresa
left join clientes cl on cl.cod_cliente = ped.cod_cliente and cl.cod_empresa = ped.cod_empresa
inner join empresa emp on emp.cod_empresa = pr.cod_empresa
union
select distinct 'PRODUCAO' TIPO, 'E' NATUREZA, emp.nome_emp EMPRESA, pd.cod_producao NUMDOC, pdi.nitem, pd.data_fechamento DATA, (cl.cod_cliente ||' - '|| cl.nome_cliente) CLIENTE, pr.cod_empresa,gr.descricao descr_grupo, pr.grupo_prod, pr.cod_prod, 0 cod_grade, 'SEM GRADE' descr_grade, pr.num_fab_prod, pr.descr_prod,
pr.est_f, coalesce(pr.est_f,0) est_prod, coalesce(pr.prec_tab_prod, 0) prec_tab_prod, coalesce(pr.prec_publico,0) prec_publico,
coalesce(pr.prec_cus_prod,0) prec_cus_prod, coalesce(pr.prec_cusm_prod,0) prec_cusm_prod,
coalesce(pdi.quantidade,0) ENTRADA, 0.00 SAIDA, 0.00 VLTOT_VENDA
from produtos pr
inner join producao_item pdi on pdi.grupo_prod = pr.grupo_prod and pdi.cod_prod = pr.cod_prod and pdi.cod_empresa = pr.cod_empresa
inner join producao pd on pd.cod_producao = pdi.cod_producao and pd.cod_empresa = pdi.cod_empresa
left join grupos gr on gr.codigo_grup = pr.grupo_prod
left join clientes cl on cl.cod_cliente = pd.cod_cliente and cl.cod_empresa = pd.cod_empresa
inner join empresa emp on emp.cod_empresa = pr.cod_empresa
where pd.status = 'FECHADO'
union
select distinct 'NF' TIPO, 'E' NATUREZA, emp.nome_emp EMPRESA, nf.num_nf NUMDOC, nfi.nitem, nf.data_lanc DATA, (cl.cod_cliente ||' - '|| cl.nome_cliente) CLIENTE, pr.cod_empresa, gr.descricao descr_grupo, pr.grupo_prod, pr.cod_prod, coalesce(gra.cod_grade, 0) cod_grade, coalesce(gra.descricao,'SEM GRADE') descr_grade, pr.num_fab_prod, pr.descr_prod,
(case when coalesce(gra.cod_grade, 0) <= 0 then coalesce(pr.est_f,0) else coalesce(gp.qtde,0) end) EST_F,
coalesce(pr.est_f,0) est_prod, coalesce(pr.prec_tab_prod, 0) prec_tab_prod, coalesce(pr.prec_publico,0) prec_publico,
coalesce(pr.prec_cus_prod,0) prec_cus_prod, coalesce(pr.prec_cusm_prod,0) prec_cusm_prod,
(case when coalesce(gra.cod_grade, 0) <= 0 then coalesce(nfi.quantidade,0) else coalesce(grcomp.qtde,0) end) ENTRADA,
0.00 SAIDA, 0.00 VLTOT_VENDA
from produtos pr
inner join notafiscal_item nfi on nfi.grupo_prod = pr.grupo_prod and nfi.cod_prod = pr.cod_prod and nfi.cod_empresa = pr.cod_empresa and (nfi.altera_estoque_cfop <> 'N' or nfi.altera_estoque_cfop is null)
inner join notafiscal nf on nf.cod_nf = nfi.cod_nf and nfi.cod_empresa = nf.cod_empresa and nf.natureza_nf ='E' and nf.status ='Fechada' and nf.ativo = 1
left join grupos gr on gr.codigo_grup = pr.grupo_prod
left join cod_grade_prod_compra grcomp on
nfi.grupo_prod = grcomp.grupo_prod and nfi.cod_prod = grcomp.cod_prod and nfi.cod_empresa = grcomp.cod_empresa and
nfi.cod_nf = grcomp.num_nota_nfe and nfi.nitem = grcomp.cod_forn_nfe
left join grade gra on grcomp.cod_grade = gra.cod_grade and grcomp.cod_empresa = gra.cod_empresa
left join cod_grade_prod gp on gp.cod_grade = gra.cod_grade and gp.grupo_prod = pr.grupo_prod and gp.cod_prod = pr.cod_prod and gp.cod_empresa = pr.cod_empresa
left join clientes cl on cl.cod_cliente = nf.cod_cliente and cl.cod_empresa = nf.cod_empresa
inner join empresa emp on emp.cod_empresa = pr.cod_empresa
union
select distinct 'PRODUCAO' TIPO, 'S' NATUREZA, emp.nome_emp EMPRESA, pd.cod_producao NUMDOC, pi.nitem, pd.data_fechamento DATA, (cl.cod_cliente ||' - '|| cl.nome_cliente) CLIENTE, pr.cod_empresa, gr.descricao descr_grupo, pr.grupo_prod, pr.cod_prod, 0 cod_grade, 'SEM GRADE' descr_grade, pr.num_fab_prod, pr.descr_prod,
pr.est_f, coalesce(pr.est_f,0) est_prod, coalesce(pr.prec_tab_prod, 0) prec_tab_prod, coalesce(pr.prec_publico,0) prec_publico,
coalesce(pr.prec_cus_prod,0) prec_cus_prod, coalesce(pr.prec_cusm_prod,0) prec_cusm_prod,
0.00 ENTRADA, coalesce(pi.quantidade_utilizada,0) SAIDA, 0.00 VLTOT_VENDA
from produtos pr
inner join producao_item_indice pi on pi.grupo_prod = pr.grupo_prod and pi.cod_prod = pr.cod_prod and pi.cod_empresa = pr.cod_empresa
inner join producao pd on pd.cod_producao = pi.cod_producao and pd.cod_empresa = pi.cod_empresa
left join grupos gr on gr.codigo_grup = pr.grupo_prod
left join clientes cl on cl.cod_cliente = pd.cod_cliente and cl.cod_empresa = pd.cod_empresa
inner join empresa emp on emp.cod_empresa = pr.cod_empresa
where pd.status = 'FECHADO'
union
select distinct 'DEV' TIPO, 'E' NATUREZA, emp.nome_emp EMPRESA, dev.sequencia, 1 nitem, dev.data, (cl.cod_cliente ||' - '|| cl.nome_cliente) CLIENTE, pr.cod_empresa, gr.descricao descr_grupo, pr.grupo_prod, pr.cod_prod, coalesce(gra.cod_grade, 0) cod_grade, coalesce(gra.descricao,'SEM GRADE') descr_grade, pr.num_fab_prod, pr.descr_prod,
(case when coalesce(gra.cod_grade, 0) <= 0 then coalesce(pr.est_f,0) else coalesce(gp.qtde,0) end) EST_F,
coalesce(pr.est_f,0) est_prod, coalesce(pr.prec_tab_prod, 0) prec_tab_prod, coalesce(pr.prec_publico,0) prec_publico,
coalesce(pr.prec_cus_prod,0) prec_cus_prod, coalesce(pr.prec_cusm_prod,0) prec_cusm_prod,
coalesce(dev.quant,0) ENTRADA, 0.00 SAIDA, 0.00 VLTOT_VENDA
from produtos pr
inner join devolucao dev on dev.grupo_prod = pr.grupo_prod and dev.cod_prod = pr.cod_prod and dev.cod_empresa = pr.cod_empresa
left join grupos gr on gr.codigo_grup = pr.grupo_prod
left join grade gra on gra.cod_grade = dev.cod_grade and gra.cod_empresa = dev.cod_empresa
left join cod_grade_prod gp on gp.cod_grade = gra.cod_grade and gp.grupo_prod = pr.grupo_prod and gp.cod_prod = pr.cod_prod and gp.cod_empresa = pr.cod_empresa
left join clientes cl on cl.cod_cliente = dev.cod_cliente and cl.cod_empresa = dev.cod_empresa
inner join empresa emp on emp.cod_empresa = pr.cod_empresa
;

/* View: FICHAVENDAPROD_SERV, Owner: SYSDBA */
CREATE VIEW FICHAVENDAPROD_SERV (COD_EMPRESA, NOME_EMP, TIPO, NPED, NITEM, DATA_FECH, GRPROD_CODSERV, COD_PROD, DESCR_PROD_PED, COD_GRADE, DESCRICAO_GRADE, QUANT_PED_ITEM, VLUN_PED_ITEM, VLTOT_PED_ITEM, N_NF, NUM_FAB_PROD, RATEIO_DESC, RATEIO_ACRESC, COD_CLIENTE, NOME_CLIENTE, CPFCNPJ, COD_VENDEDOR, NOME_VENDEDOR) AS

select e.cod_empresa, e.nome_emp, pv.tipo,pv.nped,it.nitem,pv.data_fech,it.grupo_prod,it.cod_prod, it.descr_prod_ped,
g.cod_grade,g.descricao, it.quant_ped_item,it.vlun_ped_item,
it.vltot_ped_item,it.n_nf,pr.num_fab_prod,it.rateio_desc,it.rateio_acresc,
cl.cod_cliente, cl.nome_cliente,cl.cpfcgc,col.cod_vendedor,col.nome_vendedor
from clientes cl inner join pedvenda pv
on cl.cod_cliente = pv.cod_cliente and cl.cod_empresa = pv.cod_empresa
inner join pedvenda_prod it
on it.nped = pv.nped and it.tipo = pv.tipo and it.cod_empresa=pv.cod_empresa
inner join colaborador col on it.cod_vendedor=col.cod_vendedor and it.cod_empresa=col.cod_empresa
inner join grade g on it.cod_grade = g.cod_grade and it.cod_empresa = g.cod_empresa
inner join produtos pr
on it.cod_prod = pr.cod_prod and it.grupo_prod = pr.grupo_prod and pr.cod_empresa=it.cod_empresa
inner join empresa e on cl.cod_empresa=e.cod_empresa
where (coalesce(it.status,'') <> 'CANCELADO') and pv.data_fech is not null and
(pv.tipo = 'REQ' and ((select retorno from sp_retorno_tipo_venda(pv.tipo, pv.tipv))='S'))
and pv.ativo=1

union

select e.cod_empresa, e.nome_emp, 'MOT' tipo, cf.n_comando nped, 1 nitem, cf.data_fech, 0 grupo_prod, cf.chassiv cod_prod, est.descricao_versaoest descr_prod_ped,
0 cod_grade, ' ' descricao, 1 quant_ped_item, cf.valor_real vlun_ped_item,
cf.valor_real vltot_ped_item, cf.num_nota_v n_nf, cf.chassiv num_fab_prod, 0 rateio_desc, 0 rateio_acresc,
cl.cod_cliente, cl.nome_cliente, cl.cpfcgc, col.cod_vendedor,col.nome_vendedor
from clientes cl
inner join com_fat cf on cl.cod_cliente = cf.clientes_v and cl.cod_empresa = cf.cod_empresa
inner join est_moto est on est.codigo = cf.cod_estmoto and est.chassi_c = cf.chassiv and est.cod_empresa = cf.cod_empresa
inner join colaborador col on cf.covend_v = col.cod_vendedor and cf.cod_empresa = col.cod_empresa
inner join empresa e on cl.cod_empresa = e.cod_empresa
where cf.natureza = 'S' and (coalesce(trim(cf.status_v), '') = 'FECHADO')

union

select e.cod_empresa, e.nome_emp, pv.tipo,pv.nped,it.nitem,pv.data_fech,it.grupo_prod,it.cod_prod, it.descr_prod_ped,
g.cod_grade,g.descricao, it.quant_ped_item,it.vlun_ped_item,
it.vltot_ped_item,it.n_nf,pr.num_fab_prod,it.rateio_desc,it.rateio_acresc,
cl.cod_cliente, cl.nome_cliente,cl.cpfcgc,col.cod_vendedor,col.nome_vendedor
from clientes cl inner join pedvenda pv
on cl.cod_cliente = pv.cod_cliente and cl.cod_empresa = pv.cod_empresa
inner join pedvenda_prod it
on it.nped = pv.nped and it.tipo = pv.tipo and it.cod_empresa=pv.cod_empresa
inner join colaborador col on it.cod_vendedor=col.cod_vendedor and it.cod_empresa=col.cod_empresa
inner join grade g on it.cod_grade = g.cod_grade and it.cod_empresa = g.cod_empresa
inner join produtos pr
on it.cod_prod = pr.cod_prod and it.grupo_prod = pr.grupo_prod and pr.cod_empresa=it.cod_empresa
inner join empresa e on cl.cod_empresa=e.cod_empresa
where (coalesce(it.status,'') <> 'CANCELADO') and pv.data_fech is not null and
(pv.tipo = 'OS' and
(((select retorno from sp_retorno_tipo_venda(pv.tipo, pv.tipo_os))='S')
or ((select retorno from sp_os_garantia(pv.tipo_os))='S')))
and pv.ativo=1

union

SELECT e.cod_empresa, e.nome_emp, pv.tipo,pv.nped,s.nitem,pv.data_fech,s.cod_servico,'      ',s.desc_serv_ped,null,
'                               ',
s.quant_serv_ped, s.valor_un_serv,s.valor_tot_serv,s.n_nf,'                    ',
s.rateio_desc,s.rateio_acresc,cl.cod_cliente, cl.nome_cliente,cl.cpfcgc,col.cod_vendedor,col.nome_vendedor
FROM clientes cl inner join  pedvenda pv
on cl.cod_cliente = pv.cod_cliente and cl.cod_empresa = pv.cod_empresa
inner join pedvenda_serv s
on s.nped = pv.nped and s.tipo = pv.tipo and s.cod_empresa=pv.cod_empresa
inner join colaborador col on s.cod_vendedor=col.cod_vendedor and s.cod_empresa=col.cod_empresa
inner join empresa e on cl.cod_empresa=e.cod_empresa
where coalesce(s.status,'') <> 'CANCELADO'  and  pv.data_fech  is not null and
pv.ativo=1 and (pv.tipo = 'OS' and
(((select retorno from sp_retorno_tipo_venda('OS', pv.tipo_os))='S')
or ((select retorno from sp_os_garantia(pv.tipo_os))='S')))

union

SELECT e.cod_empresa, e.nome_emp, 'DEV',d.sequencia,d.seqid,d.data,d.grupo_prod,
d.cod_prod,d.descricao,d.cod_grade,g.descricao, (-1)*d.quant,(-1)*d.valor,(-1)*(d.valor*d.quant),
d.NUM_NOTA_NFE,d.num_fab_prod,0,0,cl.cod_cliente, cl.nome_cliente,cl.cpfcgc,col.cod_vendedor,col.nome_vendedor FROM clientes cl
inner join  devolucao d
on cl.cod_cliente =d.cod_cliente and cl.cod_empresa = d.cod_empresa
inner join colaborador col on d.cod_vendedor=col.cod_vendedor and d.cod_empresa=col.cod_empresa
inner join grade g on d.cod_grade = g.cod_grade and d.cod_empresa = g.cod_empresa
inner join empresa e on cl.cod_empresa=e.cod_empresa
WHERE d.ativo=1 and d.data is not null
;

/* View: VW_DES_E, Owner: SYSDBA */
CREATE VIEW VW_DES_E (COD_EMPRESA, NUM_DOC, TIPO_DOC, COD_SERVICO, TIPO_REGISTRO, DATA_EMISSAO, COD_CTISS, COD_SUBITEM, MODELO_DOCUMENTO, SERIE_DOCUMENTO, SUBSERIE_DOCUMENTO, TIPO_NEGOCIO, EXIGIBILIDADE_ISSQN, LOCAL_INCIDENCIA, REG_ESP_TRIB, TIPO_REC_ISSQN, NUMERO_DOCUMENTO, NUMERO_FINAL, VALOR_BRUTO, VALOR_SERVICO, ALIQUOTA, SITUACAO_DOCUMENTO, SIMPLES_NACIONAL, INSC_MUN_TOMADOR, CNPJ_TOMADOR, CPF_TOMADOR, NOME_TOMADOR, LOGRADOURO_TOMADOR, NUM_IMOVEL_TOMADOR, COMPLEMENTO_TOMADOR, BAIRRO_TOMADOR, CIDADE_TOMADOR, PAIS_TOMADOR, CEP_TOMADOR, TELEFONE_TOMADOR, EMAIL_TOMADOR, LOCAL_PRESTACAO, PAIS_PRESTACAO, DATA_COMPETENCIA, DATA_CANCELAMENTO, MOTIVO_CANCELAMENTO, OUTRO_MOTIVO_CANCELAMENTO) AS

SELECT PV.COD_EMPRESA,
PV.NPED,
'NFS-EXT',
PS.COD_SERVICO,
'E',
PV.DATA_NFEXT,
TS.CTISS,
TS.NFS_SERVICO,
5,
0,
'',
1,
1,
CI.IBGE_COD_CIDADE,
(CASE WHEN E.REGIME LIKE '%SIMPLES%' THEN 9 ELSE 1 END),
COALESCE(PS.ISS_RETIDO, 2),
(CASE WHEN (SUBSTRING(PV.NUM_NFEEXT FROM 1 FOR 4) = EXTRACT(YEAR FROM PV.DATA_NFEXT))
 THEN PV.NUM_NFEEXT ELSE EXTRACT(YEAR FROM PV.DATA_NFEXT) || PV.NUM_NFEEXT END),
(CASE WHEN (SUBSTRING(PV.NUM_NFEEXT FROM 1 FOR 4) = EXTRACT(YEAR FROM PV.DATA_NFEXT))
 THEN PV.NUM_NFEEXT ELSE EXTRACT(YEAR FROM PV.DATA_NFEXT) || PV.NUM_NFEEXT END),
PV.VALOR_NFEXT,
(((SELECT COALESCE(SUM(COALESCE(PST.VL_SERVT, 0)), 0)
  FROM PEDVENDA_SERV_TERC PST
  WHERE PST.NPED = PV.NPED
  AND PST.TIPO = PV.TIPO
  AND PST.COD_EMPRESA = PV.COD_EMPRESA) / PV.TOT_SERV) * PS.VALOR_TOT_SERV) +
  PS.VALOR_TOT_SERV - PS.RATEIO_DESC + PS.RATEIO_ACRESC,
(CASE WHEN COALESCE(CI.IBGE_COD_CIDADE, E.IBGE_COD_CIDADE) = E.IBGE_COD_CIDADE THEN (CASE WHEN E.REGIME LIKE '%SIMPLES%' THEN 0 ELSE TS.ALIQ_ISS END) ELSE 0 END),
1,
(CASE WHEN E.REGIME LIKE '%SIMPLES%' THEN 1 ELSE 2 END),
(CASE WHEN CI.IBGE_COD_CIDADE = 3106200 THEN COALESCE(C.INSC_MUNICIPAL, '') ELSE '' END),
(CASE WHEN CHAR_LENGTH(TRIM(C.CPFCGC)) = 14 THEN TRIM(C.CPFCGC) ELSE '' END),
(CASE WHEN CHAR_LENGTH(TRIM(C.CPFCGC)) = 11 THEN TRIM(C.CPFCGC) ELSE '' END),
COALESCE(C.RAZAO, 'DIVERSOS'),
COALESCE(C.ENDERECO, ''),
COALESCE(C.NUM_END_CLIENTE, ''),
COALESCE(C.COMPLEMENTO, ''),
COALESCE(C.BAIRRO, ''),
CI.IBGE_COD_CIDADE,
C.COD_PAIS,
COALESCE(C.CEP, ''),
COALESCE(C.FONE_CLIENTE, ''),
COALESCE(C.EMAIL, ''),
CI.IBGE_COD_CIDADE,
'1058',
PV.DATA_NFEXT,
NULL,
NULL,
NULL
FROM PEDVENDA PV
LEFT JOIN PEDVENDA_SERV PS ON PV.NPED = PS.NPED AND PV.TIPO = PS.TIPO AND PV.COD_EMPRESA = PS.COD_EMPRESA
LEFT JOIN TIPO_SERVICO TS ON TS.COD_SERVICO = PS.COD_SERVICO
LEFT JOIN CLIENTES C ON C.COD_CLIENTE = PV.COD_CLIENTE AND C.COD_EMPRESA = PV.COD_EMPRESA
LEFT JOIN CIDADES CI ON CI.COD_CIDADE = C.COD_CIDADE
LEFT JOIN EMPRESA E ON E.COD_EMPRESA = PS.COD_EMPRESA
WHERE COALESCE(PV.NUM_NFEEXT, 0) > 0 AND PV.TIPO = 'OS'
AND COALESCE(PS.LOTE_NFSE, 0) = 0
AND COALESCE(PS.VALOR_TOT_SERV, 0) > 0
AND UPPER(TRIM(COALESCE(PS.STATUS, ''))) <> 'CANCELADO'

UNION

SELECT PV.COD_EMPRESA,
PV.NPED,
'NFS-E',
PS.COD_SERVICO,
'E',
PS.EMISSAO_NFSE,
COALESCE(PS.CTISS, TS.CTISS),
COALESCE(PS.NFS_SERVICO, TS.NFS_SERVICO),
5,
0,
'',
1,
1,
CI.IBGE_COD_CIDADE,
(CASE WHEN E.REGIME LIKE '%SIMPLES%' THEN 9 ELSE 1 END),
COALESCE(PS.ISS_RETIDO, 2),
(CASE WHEN (SUBSTRING(PS.N_NF FROM 1 FOR 4) = EXTRACT(YEAR FROM PS.EMISSAO_NFSE))
 THEN PS.N_NF ELSE EXTRACT(YEAR FROM PS.EMISSAO_NFSE) || PS.N_NF END),
(CASE WHEN (SUBSTRING(PS.N_NF FROM 1 FOR 4) = EXTRACT(YEAR FROM PS.EMISSAO_NFSE))
 THEN PS.N_NF ELSE EXTRACT(YEAR FROM PS.EMISSAO_NFSE) || PS.N_NF END),
PS.VALOR_NFSE,
(((SELECT COALESCE(SUM(COALESCE(PST.VL_SERVT, 0)), 0)
  FROM PEDVENDA_SERV_TERC PST
  WHERE PST.NPED = PV.NPED
  AND PST.TIPO = PV.TIPO
  AND PST.COD_EMPRESA = PV.COD_EMPRESA) / PV.TOT_SERV) * PS.VALOR_TOT_SERV) +
  PS.VALOR_TOT_SERV - PS.RATEIO_DESC + PS.RATEIO_ACRESC,
(CASE WHEN COALESCE(CI.IBGE_COD_CIDADE, E.IBGE_COD_CIDADE) = E.IBGE_COD_CIDADE THEN (CASE WHEN E.REGIME LIKE '%SIMPLES%' THEN 0 ELSE COALESCE(PS.ALIQ_ISS, TS.ALIQ_ISS) END) ELSE 0 END),
1,
(CASE WHEN E.REGIME LIKE '%SIMPLES%' THEN 1 ELSE 2 END),
(CASE WHEN CI.IBGE_COD_CIDADE = 3106200 THEN COALESCE(C.INSC_MUNICIPAL, '') ELSE '' END),
(CASE WHEN CHAR_LENGTH(TRIM(C.CPFCGC)) = 14 THEN TRIM(C.CPFCGC) ELSE '' END),
(CASE WHEN CHAR_LENGTH(TRIM(C.CPFCGC)) = 11 THEN TRIM(C.CPFCGC) ELSE '' END),
COALESCE(C.RAZAO, 'DIVERSOS'),
COALESCE(C.ENDERECO, ''),
COALESCE(C.NUM_END_CLIENTE, ''),
COALESCE(C.COMPLEMENTO, ''),
COALESCE(C.BAIRRO, ''),
CI.IBGE_COD_CIDADE,
C.COD_PAIS,
COALESCE(C.CEP, ''),
COALESCE(C.FONE_CLIENTE, ''),
COALESCE(C.EMAIL, ''),
CI.IBGE_COD_CIDADE,
'1058',
PS.EMISSAO_NFSE,
NULL,
NULL,
NULL
FROM PEDVENDA_SERV PS
LEFT JOIN PEDVENDA PV ON PS.NPED = PV.NPED AND PS.TIPO = PV.TIPO AND PS.COD_EMPRESA = PV.COD_EMPRESA
LEFT JOIN TIPO_SERVICO TS ON TS.COD_SERVICO = PS.COD_SERVICO
LEFT JOIN CLIENTES C ON C.COD_CLIENTE = PV.COD_CLIENTE AND C.COD_EMPRESA = PV.COD_EMPRESA
LEFT JOIN CIDADES CI ON CI.COD_CIDADE = C.COD_CIDADE
LEFT JOIN EMPRESA E ON E.COD_EMPRESA = PS.COD_EMPRESA
WHERE PS.STATUS_NFSE = 'Autorizada' AND PV.TIPO = 'OS' AND PS.LOTE_NFSE > 0
AND COALESCE(PS.VALOR_TOT_SERV, 0) > 0
AND UPPER(TRIM(COALESCE(PS.STATUS, ''))) <> 'CANCELADO'

UNION

SELECT NC.COD_EMPRESA,
NC.N_OS,
'NFS-E CANCELADAS',
NULL,
'E',
NC.EMISSAO_NFSE,
NC.CTISS,
NC.NFS_SERVICO,
5,
0,
'',
0,
0,
CI.IBGE_COD_CIDADE,
0,
(CASE WHEN COALESCE(NC.ISS_RETIDO, 2) = 0 THEN 2 ELSE COALESCE(NC.ISS_RETIDO, 2) END),
(CASE WHEN (SUBSTRING(NC.NUM_NFSE FROM 1 FOR 4) = EXTRACT(YEAR FROM NC.EMISSAO_NFSE))
 THEN NC.NUM_NFSE ELSE EXTRACT(YEAR FROM NC.EMISSAO_NFSE) || NC.NUM_NFSE END),
(CASE WHEN (SUBSTRING(NC.NUM_NFSE FROM 1 FOR 4) = EXTRACT(YEAR FROM NC.EMISSAO_NFSE))
 THEN NC.NUM_NFSE ELSE EXTRACT(YEAR FROM NC.EMISSAO_NFSE) || NC.NUM_NFSE END),
NC.VALOR_NFSE,
NC.VALOR_NFSE,
(CASE WHEN COALESCE(CI.IBGE_COD_CIDADE, E.IBGE_COD_CIDADE) = E.IBGE_COD_CIDADE THEN (CASE WHEN E.REGIME LIKE '%SIMPLES%' THEN 0 ELSE NC.ALIQ_ISS END) ELSE 0 END),
2,
(CASE WHEN E.REGIME LIKE '%SIMPLES%' THEN 1 ELSE 2 END),
(CASE WHEN CI.IBGE_COD_CIDADE = 3106200 THEN COALESCE(C.INSC_MUNICIPAL, '') ELSE '' END),
(CASE WHEN CHAR_LENGTH(TRIM(C.CPFCGC)) = 14 THEN TRIM(C.CPFCGC) ELSE '' END),
(CASE WHEN CHAR_LENGTH(TRIM(C.CPFCGC)) = 11 THEN TRIM(C.CPFCGC) ELSE '' END),
COALESCE(C.RAZAO, 'DIVERSOS'),
COALESCE(C.ENDERECO, ''),
COALESCE(C.NUM_END_CLIENTE, ''),
COALESCE(C.COMPLEMENTO, ''),
COALESCE(C.BAIRRO, ''),
CI.IBGE_COD_CIDADE,
C.COD_PAIS,
COALESCE(C.CEP, ''),
COALESCE(C.FONE_CLIENTE, ''),
COALESCE(C.EMAIL, ''),
CI.IBGE_COD_CIDADE,
'1058',
NC.EMISSAO_NFSE,
NC.DATA_CANC,
SUBSTRING(NC.MOTIVO_CANCELAMENTO FROM 1 FOR 1),
NULL
FROM NFSE_CANCELADAS NC
LEFT JOIN CLIENTES C ON C.COD_CLIENTE = NC.COD_CLIENTE AND C.COD_EMPRESA = NC.COD_EMPRESA
LEFT JOIN CIDADES CI ON CI.COD_CIDADE = C.COD_CIDADE
LEFT JOIN EMPRESA E ON E.COD_EMPRESA = NC.COD_EMPRESA

UNION

SELECT CP.COD_EMPRESA,
CP.CUPOM,
'CP',
CP2.GRUPO_PROD,
'E',
CP.DATA,
TS.CTISS,
TS.NFS_SERVICO,
13,
0,
'',
(CASE WHEN UPPER(COALESCE(CP2.STATUS_IT, '')) = 'CANCELADO' THEN 0 ELSE 1 END),
(CASE WHEN UPPER(COALESCE(CP2.STATUS_IT, '')) = 'CANCELADO' THEN 0 ELSE 1 END),
E.IBGE_COD_CIDADE,
(CASE WHEN UPPER(COALESCE(CP2.STATUS_IT, '')) = 'CANCELADO' THEN 0 ELSE (CASE WHEN E.REGIME LIKE '%SIMPLES%' THEN 9 ELSE 1 END) END),
COALESCE(TS.ISS_RETIDO, 2),
CF.NUM_EQUIP || CP.CUPOM,
CF.NUM_EQUIP || CP.CUPOM,
CP.TOTAL,
CP2.TOTAL + CP2.RAT_ACRES - CP2.RAT_DESC,
(CASE WHEN E.REGIME LIKE '%SIMPLES%' THEN 0 ELSE TS.ALIQ_ISS END),
(CASE WHEN UPPER(COALESCE(CP2.STATUS_IT, '')) = 'CANCELADO' THEN 2 ELSE 1 END),
(CASE WHEN E.REGIME LIKE '%SIMPLES%' THEN 1 ELSE 2 END),
(CASE WHEN CI.IBGE_COD_CIDADE = 3106200 THEN COALESCE(C.INSC_MUNICIPAL, '') ELSE '' END),
(CASE WHEN CHAR_LENGTH(TRIM(C.CPFCGC)) = 14 THEN TRIM(C.CPFCGC) ELSE '' END),
(CASE WHEN CHAR_LENGTH(TRIM(C.CPFCGC)) = 11 THEN TRIM(C.CPFCGC) ELSE '' END),
COALESCE(C.RAZAO, 'DIVERSOS'),
COALESCE(C.ENDERECO, ''),
COALESCE(C.NUM_END_CLIENTE, ''),
COALESCE(C.COMPLEMENTO, ''),
COALESCE(C.BAIRRO, ''),
CI.IBGE_COD_CIDADE,
C.COD_PAIS,
COALESCE(C.CEP, ''),
COALESCE(C.FONE_CLIENTE, ''),
COALESCE(C.EMAIL, ''),
CI.IBGE_COD_CIDADE,
'1058',
CP.DATA,
(CASE WHEN UPPER(COALESCE(CP2.STATUS_IT, '')) = 'CANCELADO' THEN CP.DATA ELSE NULL END),
(CASE WHEN UPPER(COALESCE(CP2.STATUS_IT, '')) = 'CANCELADO' THEN 2 ELSE NULL END),
NULL
FROM CUPOM CP
LEFT JOIN CUPOM2 CP2 ON CP2.COD_TERMINAL = CP.COD_TERMINAL AND CP2.CUPOM = CP.CUPOM AND CP2.NSERIEECF = CP.NSERIEECF
AND CP2.COD_EMPRESA = CP.COD_EMPRESA AND CP2.ORDEM = CP.REGISTRO
LEFT JOIN CONFIMP CF ON CF.NUM_SERIE_ECF = CP.NSERIEECF AND CF.COD_TERMINAL = CP.COD_TERMINAL AND CF.COD_EMPRESA = CP.COD_EMPRESA
LEFT JOIN TIPO_SERVICO TS ON TS.COD_SERVICO = CP2.GRUPO_PROD
LEFT JOIN CLIENTES C ON C.COD_CLIENTE = CP.CLIENTE AND C.COD_EMPRESA = CP.COD_EMPRESA
LEFT JOIN CIDADES CI ON CI.COD_CIDADE = C.COD_CIDADE
LEFT JOIN EMPRESA E ON E.COD_EMPRESA = CP.COD_EMPRESA
WHERE CP2.PROD_SERV = 'S'
;

/* View: VW_DES_R, Owner: SYSDBA */
CREATE VIEW VW_DES_R (COD_EMPRESA, NUM_DOC, TIPO_DOC, COD_SERVICO, TIPO_REGISTRO, DATA_PAG_REC_CRED, DATA_EMISSAO, MODELO_DOCUMENTO, SERIE_DOCUMENTO, SUBSERIE_DOCUMENTO, SIT_ESP_RESP, MOTIVO_NAO_RETENCAO, LOCAL_INCIDENCIA, TIPO_REC_ISSQN, NUMERO_DOCUMENTO, VALOR_BRUTO, VALOR_SERVICO, ALIQUOTA, SIMPLES_NACIONAL, INSC_MUN_PRESTADOR, CNPJ_PRESTADOR, CPF_PRESTADOR, NOME_PRESTADOR, LOGRADOURO_PRESTADOR, NUM_IMOVEL_PRESTADOR, COMPLEMENTO_PRESTADOR, BAIRRO_PRESTADOR, CIDADE_PRESTADOR, PAIS_PRESTADOR, CEP_PRESTADOR, TELEFONE_PRESTADOR, EMAIL_PRESTADOR, LOCAL_PRESTACAO, PAIS_PRESTACAO) AS

SELECT NF.COD_EMPRESA,
NF.NUM_NF,
'NOTAFISCAL',
NI.COD_SERVICO,
'R',
NF.DATA_LANC,
NF.DATA_CONTABIL,
NF.MOD_DES_BH,
(CASE WHEN COALESCE(NF.SEM_SERIE, '') = 'S' THEN NULL ELSE NF.SERIE END),
NF.SUBSERIE,
1,
(CASE WHEN NF.TIPO_REC_ISSQN = 1 THEN 16 ELSE 1 END),
NF.LOCAL_INCIDENCIA,
NF.TIPO_REC_ISSQN,
(CASE WHEN COALESCE(NF.MOD_DES_BH, 0) = 5
    THEN (CASE WHEN (SUBSTRING(NF.NUM_NF FROM 1 FOR 4) = EXTRACT(YEAR FROM NF.DATA_CONTABIL))
            THEN NF.NUM_NF ELSE EXTRACT(YEAR FROM NF.DATA_CONTABIL) || NF.NUM_NF END)
            ELSE NF.NUM_NF END),
NF.VALOR_SERV,
NI.VALOR_TOTAL,
(CASE
    WHEN (COALESCE(NF.TIPO_REC_ISSQN, '') = '1' AND TRIM(UPPER(COALESCE(C.REGIME, ''))) = 'SIMPLES') THEN NF.ALIQ_ISS
    WHEN (COALESCE(NF.TIPO_REC_ISSQN, '') = '2' AND (TRIM(UPPER(COALESCE(C.REGIME, ''))) = 'SIMPLES' OR TRIM(UPPER(COALESCE(C.REGIME, ''))) = 'MEI')) THEN 0
    ELSE NF.ALIQ_ISS
END),
(CASE TRIM(UPPER(C.REGIME))
    WHEN 'SIMPLES' THEN
        1
    WHEN 'MEI' THEN
        3
    ELSE
        2
END),
(CASE WHEN CI.IBGE_COD_CIDADE = 3106200 THEN COALESCE(C.INSC_MUNICIPAL, '') ELSE '' END),
(CASE WHEN CHAR_LENGTH(TRIM(C.CPFCGC)) = 14 THEN TRIM(C.CPFCGC) ELSE '' END),
(CASE WHEN CHAR_LENGTH(TRIM(C.CPFCGC)) = 11 THEN TRIM(C.CPFCGC) ELSE '' END),
COALESCE(C.RAZAO, ''),
COALESCE(C.ENDERECO, ''),
COALESCE(C.NUM_END_CLIENTE, ''),
COALESCE(C.COMPLEMENTO, ''),
COALESCE(C.BAIRRO, ''),
CI.IBGE_COD_CIDADE,
C.COD_PAIS,
COALESCE(C.CEP, ''),
COALESCE(C.FONE_CLIENTE, ''),
COALESCE(C.EMAIL, ''),
E.IBGE_COD_CIDADE,
'1058'
FROM NOTAFISCAL NF
LEFT JOIN NOTAFISCAL_ITEM NI ON NI.COD_NF = NF.COD_NF AND NI.COD_EMPRESA = NF.COD_EMPRESA
LEFT JOIN TIPO_SERVICO TS ON TS.COD_SERVICO = NI.COD_SERVICO
LEFT JOIN CLIENTES C ON C.COD_CLIENTE = NF.COD_CLIENTE AND C.COD_EMPRESA = NF.COD_EMPRESA
LEFT JOIN CIDADES CI ON CI.COD_CIDADE = C.COD_CIDADE
LEFT JOIN EMPRESA E ON E.COD_EMPRESA = NF.COD_EMPRESA
WHERE NI.TIPO_ITEM = 'S' AND NF.STATUS = 'Fechada' AND NF.EMISSAO_PROPRIA <> 'S'
;

