ALTER PROCEDURE ATRIBUIR_CUSTO (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA INTEGER,
PDATA TIMESTAMP,
PCODNF INTEGER,
PNUMERO INTEGER,
PTIPO VARCHAR(3) CHARACTER SET NONE,
PNITEM INTEGER,
PNATUREZA CHAR(1) CHARACTER SET NONE)
AS 
declare variable VRESULT varchar(10);
declare variable VESTOQUE double precision;
declare variable VDATA_ANT timestamp;
declare variable VCUSTO_MEDIO double precision;
declare variable VCOD_CORRECAO integer;
declare variable VCOD_NFX integer;
declare variable VCOD_NF integer;
declare variable VCOD_PRODUCAO integer;
declare variable VSEQID integer;
declare variable VSEQID_HD integer;
declare variable VSEQID_HP integer;
declare variable VVALORPARARATEIO double precision;
declare variable VPESOPARARATEIO double precision;
declare variable VVALORCUSTO double precision;
declare variable VSOLVENTE_INS char(1);
declare variable VPREC_CUSM_PROD_INS double precision;
declare variable VQUANTIDADE_UTILIZADA_INS double precision;
declare variable VQUANTIDADE_PERDA_INS double precision;
declare variable VPESO_UN_INS double precision;
declare variable VPESO_UTIL_INS double precision;
declare variable VDATA_ESTOQUE_INI_PD timestamp;
declare variable VDATA_ESTOQUE_FIM_PD timestamp;
declare variable VDATA_ESTOQUETMP timestamp;
declare variable VQUANTIDADE_PRODUZIDA_PD double precision;
declare variable VGRUPO_PROD_ACAB integer;
declare variable VCOD_PROD_ACAB char(6);
declare variable VNITEM_ACAB integer;
declare variable VQUANTIDADE_ACAB double precision;
declare variable VPESO_UTIL_ACAB double precision;
declare variable VCUSTO_INDICE double precision;
declare variable VCUSTO_RATEIO double precision;
declare variable VPREC_CUS_PROD double precision;
declare variable VPREC_CUSM_PROD double precision;
begin
  /* Procedure Text */
  vcusto_medio  = 0;
  vcod_correcao = 0;
  vcod_nf       = 0;
  vcod_producao = 0;
  vcod_nfx      = 0;
  vseqid        = 0;
  vseqid_hd     = 0;
  vseqid_hp     = 0;

  if ((coalesce(vcod_correcao, 0) <= 0)
        and (coalesce(vcod_nf, 0) <= 0)
        and (coalesce(vcod_producao, 0) <= 0)
        and (coalesce(vcod_nfx, 0) <= 0)) then
  begin
    select first 1 hd.cod_empresa from hist_estoque_diario hd
    where hd.data = :pdata
    and hd.grupo_prod = :pgrupo_prod
    and hd.cod_prod = :pcod_prod
    -- and hd.cod_grade = :pcod_grade
    and hd.cod_empresa = :pcod_empresa
    and hd.qtde = 0
    and hd.custo_med <> 0
      into :vcod_correcao;
  end

  if ((coalesce(vcod_correcao, 0) <= 0)
        and (coalesce(vcod_nf, 0) <= 0)
        and (coalesce(vcod_producao, 0) <= 0)
        and (coalesce(vcod_nfx, 0) <= 0)) then
  begin
    select first 1 hp.cod_empresa from hist_estoque_diario_prod hp
    where hp.data = :pdata
    and hp.grupo_prod = :pgrupo_prod
    and hp.cod_prod = :pcod_prod
    -- and hp.cod_grade = :pcod_grade
    and hp.cod_empresa = :pcod_empresa
    and hp.qtde = 0
    and hp.custo_med <> 0
      into :vcod_correcao;
  end

  if ((coalesce(vcod_correcao, 0) <= 0)
        and (coalesce(vcod_nf, 0) <= 0)
        and (coalesce(vcod_producao, 0) <= 0)
        and (coalesce(vcod_nfx, 0) <= 0)) then
  begin
    select first 1 nf.cod_nf from notafiscal nf
    inner join notafiscal_item nfi on
      nfi.cod_nf = nf.cod_nf
      and nfi.cod_empresa = nf.cod_empresa
    where nf.data_estoque = :pdata
    and nf.cod_empresa = :pcod_empresa
    and nfi.grupo_prod = :pgrupo_prod
    and nfi.cod_prod = :pcod_prod
    -- and nfi.cod_grade = :pcod_grade
    and nf.natureza_nf = 'E'
    and (nf.status = 'Fechada')
    and nfi.altera_custo_cfop <> 'N'
    and nf.ativo = 1
      into :vcod_nf;
  end

  if ((coalesce(vcod_correcao, 0) <= 0)
        and (coalesce(vcod_nf, 0) <= 0)
        and (coalesce(vcod_producao, 0) <= 0)
        and (coalesce(vcod_nfx, 0) <= 0)) then
  begin
    select first 1 f.cod_nf from fichaprodutosdetalhada f
    where f.data_estoque = :pdata
    and f.tipo = 'NFX'
    and f.cod_empresa = :pcod_empresa
    and f.grupo_prod = :pgrupo_prod
    and f.cod_prod = :pcod_prod
    -- and nfi.cod_grade = :pcod_grade
    and f.natureza = 'E'
    --and f.altera_custo <> 'N'
      into :vcod_nfx;
  end

  if ((coalesce(vcod_correcao, 0) <= 0)
        and (coalesce(vcod_nf, 0) <= 0)
        and (coalesce(vcod_producao, 0) <= 0)
        and (coalesce(vcod_nfx, 0) <= 0)) then
  begin
    select first 1 p.cod_producao from producao p
    inner join producao_item pii on
      pii.cod_producao = p.cod_producao
      and pii.cod_empresa = p.cod_empresa
    where p.data_estoque = :pdata
    and p.cod_empresa = :pcod_empresa
    and pii.grupo_prod = :pgrupo_prod
    and pii.cod_prod = :pcod_prod
    -- and pii.cod_grade = :pcod_grade
    and p.status = 'FECHADO'
      into :vcod_producao;
  end

  -- Custo foi alterado no dia, se nao atribuir custo data anterior
  if ((coalesce(vcod_correcao, 0) > 0)
       or (coalesce(vcod_nf, 0) > 0)
       or (coalesce(vcod_producao, 0) > 0)
       or (coalesce(vcod_nfx, 0) > 0)) then
  begin
    select first 1 est.seqid, est.dia, est.custo_medio from estoque_diario est
    where est.grupo_prod = :pgrupo_prod
    and est.cod_prod = :pcod_prod
    -- and est.cod_grade = :pcod_grade
    and est.cod_empresa = :pcod_empresa
    and est.dia = :pdata
    order by est.dia desc
      into :vseqid, :vdata_ant, :vcusto_medio;
  end
  else
  begin
    select first 1 est.seqid, est.dia, est.custo_medio from estoque_diario est
    where est.grupo_prod = :pgrupo_prod
    and est.cod_prod = :pcod_prod
    -- and est.cod_grade = :pcod_grade
    and est.cod_empresa = :pcod_empresa
    and est.dia < :pdata
    order by est.dia desc
      into :vseqid, :vdata_ant, :vcusto_medio;
  end

  if (coalesce(vcusto_medio, 0) > 0) then
  begin
    if ((trim(ptipo) = 'PDC') and (trim(pnatureza) = 'S')) then
    begin
      update producao_item_indice pii set
        pii.prec_cusm_prod = coalesce(:vcusto_medio, 0)
      where pii.cod_producao = :pnumero
      and pii.cod_empresa = :pcod_empresa
      and pii.nitem = :pnitem
      and pii.grupo_prod = :pgrupo_prod
      and pii.cod_prod = :pcod_prod;

      select result from corrigir_custo_acabado (
        :pnumero,
        :ptipo,
        :pnitem,
        :pcod_empresa,
        :pdata)
          into :vresult;
    end
    else if ((trim(ptipo) = 'NF') and (trim(pnatureza) = 'E')) then
    begin
      update notafiscal_item nfi set
        nfi.prec_cusm_prod = coalesce(:vcusto_medio, 0)
      where nfi.cod_nf = :pcodnf
      and nfi.cod_empresa = :pcod_empresa
      and nfi.nitem = :pnitem;
    end
    else if ((trim(ptipo) = 'DEV') and (trim(pnatureza) = 'E')) then
    begin
      update devolucao dev set
        dev.pcust_mc = coalesce(:vcusto_medio, 0)
      where dev.sequencia = :pnumero
      and dev.cod_empresa = :pcod_empresa
      and dev.grupo_prod = :pgrupo_prod
      and dev.cod_prod = :pcod_prod;
    end
    else if (((trim(ptipo) = 'REQ') or (trim(ptipo) = 'OS')) and (trim(pnatureza) = 'S')) then
    begin
      update pedvenda_prod pp set
        pp.pcust_c = coalesce(:vcusto_medio, 0),
        pp.pcust_r = coalesce(:vcusto_medio, 0),
        pp.pcust_mc = coalesce(:vcusto_medio, 0),
        pp.pcust_mr = coalesce(:vcusto_medio, 0)
      where pp.nped = :pnumero
      and pp.tipo = :ptipo
      and pp.cod_empresa = :pcod_empresa
      and pp.nitem = :pnitem
      and pp.grupo_prod = :pgrupo_prod
      and pp.cod_prod = :pcod_prod
      and (pp.status is null or pp.status = '');
    end

    vseqid    = 0;
    vseqid_hd = 0;
    vseqid_hp = 0;
    select first 1 hp.seqid from hist_estoque_diario_prod hp
    where hp.numero = :pnumero
    and hp.tipor = trim(:ptipo)
    and hp.cod_empresa = :pcod_empresa
    and hp.nitem = :pnitem
    and hp.grupo_prod = :pgrupo_prod
    and hp.cod_prod = :pcod_prod
      into :vseqid_hp;

    if (coalesce(vseqid_hp, 0) <= 0) then
    begin
      select first 1 he.seqid from hist_estoque_diario he
      where he.numero = :pnumero
      and he.tipor = trim(:ptipo)
      and he.cod_empresa = :pcod_empresa
      and he.nitem = :pnitem
      and he.grupo_prod = :pgrupo_prod
      and he.cod_prod = :pcod_prod
        into :vseqid_hd;
    end

    if (coalesce(vseqid_hp, 0) > 0) then
    begin
      if ((coalesce(ptipo, '') = 'NF') or (coalesce(ptipo, '') = 'NFX') or (coalesce(ptipo, '') = 'PDC')) then
      begin
        update hist_estoque_diario_prod hp set
          hp.valor_unit = coalesce(:vcusto_medio, 0),
          hp.valor_tot = round(hp.qtde * coalesce(:vcusto_medio, 0), 2),
          hp.custo_med = coalesce(:vcusto_medio, 0)
        where hp.numero = :pnumero
        and hp.tipor = trim(:ptipo)
        and hp.cod_empresa = :pcod_empresa
        and hp.nitem = :pnitem
        and hp.grupo_prod = :pgrupo_prod
        and hp.cod_prod = :pcod_prod;
      end
      else
      begin
        update hist_estoque_diario_prod hp set
          hp.custo_med = coalesce(:vcusto_medio, 0)
        where hp.numero = :pnumero
        and hp.tipor = trim(:ptipo)
        and hp.cod_empresa = :pcod_empresa
        and hp.nitem = :pnitem
        and hp.grupo_prod = :pgrupo_prod
        and hp.cod_prod = :pcod_prod;
      end
    end
    else if (coalesce(vseqid_hd, 0) > 0) then
    begin
      if ((coalesce(ptipo, '') = 'NF') or (coalesce(ptipo, '') = 'NFX') or (coalesce(ptipo, '') = 'PDC')) then
      begin
        update hist_estoque_diario hd set
          hd.valor_unit = coalesce(:vcusto_medio, 0),
          hd.valor_tot = round(hd.qtde * coalesce(:vcusto_medio, 0), 2),
          hd.custo_med = coalesce(:vcusto_medio, 0)
        where hd.numero = :pnumero
        and hd.tipor = trim(:ptipo)
        and hd.cod_empresa = :pcod_empresa
        and hd.nitem = :pnitem
        and hd.grupo_prod = :pgrupo_prod
        and hd.cod_prod = :pcod_prod;
      end
      else
      begin
        update hist_estoque_diario hd set
          hd.custo_med = coalesce(:vcusto_medio, 0)
        where hd.numero = :pnumero
        and hd.tipor = trim(:ptipo)
        and hd.cod_empresa = :pcod_empresa
        and hd.nitem = :pnitem
        and hd.grupo_prod = :pgrupo_prod
        and hd.cod_prod = :pcod_prod;
      end
    end
  end

  execute procedure atribuir_custo_data_ant (
    :pgrupo_prod,
    :pcod_prod,
    :pcod_grade,
    :pcod_empresa,
    :pdata);

  suspend;
end;
 
 ^

ALTER PROCEDURE ATRIBUIR_CUSTO_DATA_ANT (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA INTEGER,
PDATA TIMESTAMP)
AS 
declare variable VSEQID integer;
declare variable VDATA_ANT timestamp;
declare variable VCUSTO_MEDIO double precision;
declare variable VCOD_CORRECAO integer;
declare variable VCOD_NF integer;
declare variable VCOD_PRODUCAO integer;
declare variable VCOD_NFX integer;
begin
  /* Procedure Text */
  vcusto_medio  = 0;
  vcod_correcao = 0;
  vcod_nf       = 0;
  vcod_producao = 0;
  vcod_nfx      = 0;
  select first 1 est.seqid, est.dia, est.custo_medio from estoque_diario est
  where est.grupo_prod = :pgrupo_prod
  and est.cod_prod = :pcod_prod
  and est.cod_grade = :pcod_grade
  and est.cod_empresa = :pcod_empresa
  and est.dia < :pdata
  order by est.dia desc
    into :vseqid, :vdata_ant, :vcusto_medio;

  if ((coalesce(vcod_correcao, 0) <= 0)
    and (coalesce(vcod_nf, 0) <= 0)
    and (coalesce(vcod_producao, 0) <= 0)
    and (coalesce(vcod_nfx, 0) <= 0)) then
  begin
    select first 1 hd.cod_empresa from hist_estoque_diario hd
    where hd.data = :pdata
    and hd.grupo_prod = :pgrupo_prod
    and hd.cod_prod = :pcod_prod
    -- and hd.cod_grade = :pcod_grade
    and hd.cod_empresa = :pcod_empresa
    and hd.qtde = 0
    and hd.custo_med <> 0
      into :vcod_correcao;
  end

  if ((coalesce(vcod_correcao, 0) <= 0)
    and (coalesce(vcod_nf, 0) <= 0)
    and (coalesce(vcod_producao, 0) <= 0)
    and (coalesce(vcod_nfx, 0) <= 0)) then
  begin
    select first 1 hp.cod_empresa from hist_estoque_diario_prod hp
    where hp.data = :pdata
    and hp.grupo_prod = :pgrupo_prod
    and hp.cod_prod = :pcod_prod
    -- and hp.cod_grade = :pcod_grade
    and hp.cod_empresa = :pcod_empresa
    and hp.qtde = 0
    and hp.custo_med <> 0
      into :vcod_correcao;
  end

  if ((coalesce(vcod_correcao, 0) <= 0)
    and (coalesce(vcod_nf, 0) <= 0)
    and (coalesce(vcod_producao, 0) <= 0)
    and (coalesce(vcod_nfx, 0) <= 0)) then
  begin
    select first 1 nf.cod_nf from notafiscal nf
    inner join notafiscal_item nfi on
      nfi.cod_nf = nf.cod_nf
      and nfi.cod_empresa = nf.cod_empresa
    where nf.data_estoque = :pdata
    and nf.cod_empresa = :pcod_empresa
    and nfi.grupo_prod = :pgrupo_prod
    and nfi.cod_prod = :pcod_prod
    -- and nfi.cod_grade = :pcod_grade
    and nf.natureza_nf = 'E'
    and (nf.status = 'Fechada')
    and nfi.altera_custo_cfop <> 'N'
    and nf.ativo = 1
      into :vcod_nf;
  end

  if ((coalesce(vcod_correcao, 0) <= 0)
        and (coalesce(vcod_nf, 0) <= 0)
        and (coalesce(vcod_producao, 0) <= 0)
        and (coalesce(vcod_nfx, 0) <= 0)) then
  begin
    select first 1 f.cod_nf from fichaprodutosdetalhada f
    where f.data_estoque = :pdata
    and f.tipo = 'NFX'
    and f.cod_empresa = :pcod_empresa
    and f.grupo_prod = :pgrupo_prod
    and f.cod_prod = :pcod_prod
    -- and nfi.cod_grade = :pcod_grade
    and f.natureza = 'E'
    -- and f.altera_custo <> 'N'
      into :vcod_nfx;
  end

  if ((coalesce(vcod_correcao, 0) <= 0)
    and (coalesce(vcod_nf, 0) <= 0)
    and (coalesce(vcod_producao, 0) <= 0)
    and (coalesce(vcod_nfx, 0) <= 0)) then
  begin
    select first 1 p.cod_producao from producao p
    inner join producao_item pii on
      pii.cod_producao = p.cod_producao
      and pii.cod_empresa = p.cod_empresa
    where p.data_estoque = :pdata
    and p.cod_empresa = :pcod_empresa
    and pii.grupo_prod = :pgrupo_prod
    and pii.cod_prod = :pcod_prod
    -- and pii.cod_grade = :pcod_grade
    and p.status = 'FECHADO'
      into :vcod_producao;
  end

  if ((coalesce(vseqid, 0) > 0)
    and (coalesce(vcod_correcao, 0) <= 0)
    and (coalesce(vcod_nf, 0) <= 0)
    and (coalesce(vcod_producao, 0) <= 0)
    and (coalesce(vcod_nfx, 0) <= 0)) then
  begin
    update estoque_diario est set
      est.custo_medio = coalesce(:vcusto_medio, 0)
    where est.grupo_prod = :pgrupo_prod
    and est.cod_prod = :pcod_prod
    -- and est.cod_grade = :pcod_grade
    and est.cod_empresa = :pcod_empresa
    and est.dia = :pdata;

    update custos c set
      c.prec_cus_med = coalesce(:vcusto_medio, 0),
      c.pr_cusc_prod = coalesce(:vcusto_medio, 0),
      c.valor = coalesce(:vcusto_medio, 0)
    where c.grupo_prod = :pgrupo_prod
    and c.cod_prod = :pcod_prod
    and c.cod_empresa = :pcod_empresa
    and c.data = :pdata;
  end

  suspend;
end;
 
 ^

ALTER PROCEDURE ATRIBUIR_EST_DATA (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PDATA TIMESTAMP)
AS 
declare variable VSEQID integer;
declare variable VCOD_GRADE integer;
declare variable VEST double precision;
declare variable VESTOQUE double precision;
declare variable VENT_SAIDA double precision;
begin
  /* Procedure Text */
  for select est.seqid, est.cod_grade, est.estoque from estoque_diario est
      where est.grupo_prod = :pgrupo_prod
      and est.cod_prod = :pcod_prod
      and est.cod_empresa = :pcod_empresa
      and est.dia = (select first 1 est1.dia from estoque_diario est1
                     where est1.grupo_prod = :pgrupo_prod
                     and est1.cod_prod = :pcod_prod
                     and est1.cod_empresa = :pcod_empresa
                     and est1.dia < :pdata
                     order by est1.dia desc)
        into :vseqid, :vcod_grade, :vest do
  begin
    if (coalesce(vseqid, 0) <= 0) then
      exit;

    select sum(case when (f.natureza = 'S') then
                  - coalesce(f.qtde, 0)
                else
                  coalesce(f.qtde, 0)
           end) qtde from fichaprodutosdetalhada f
    where f.grupo_prod = :pgrupo_prod
    and f.cod_prod = :pcod_prod
    and f.cod_grade = :vcod_grade
    and f.cod_empresa = :pcod_empresa
    and f.data_estoque = :pdata
      into :vent_saida;

    vestoque = coalesce(vest, 0) + coalesce(vent_saida, 0);

    update estoque_diario est set
      est.estoque = coalesce(:vestoque, 0)
    where est.grupo_prod = :pgrupo_prod
    and est.cod_prod = :pcod_prod
    and est.cod_grade = :vcod_grade
    and est.cod_empresa = :pcod_empresa
    and est.dia = :pdata;
  end
  suspend;
end;
 
 ^

ALTER PROCEDURE ATRIBUIR_EST_ULT_DATA (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PDATA TIMESTAMP)
AS 
declare variable VEXISTE_GRADE integer;
declare variable VCOD_GRADE integer;
declare variable VESTOQUE double precision;
declare variable VESTOQUE_TOT double precision;
declare variable VDATA timestamp;
declare variable VCUSTO_MEDIO double precision;
begin
  /* Procedure Text */
  select first 1 est.dia, est.custo_medio from estoque_diario est
  where est.grupo_prod = :pgrupo_prod
  and est.cod_prod = :pcod_prod
  and est.cod_empresa = :pcod_empresa
  order by est.dia desc
    into :vdata, :vcusto_medio;

  -- Atualizar estoque somente na ultima data
  if (pdata <> vdata) then
    exit;

  vestoque = 0;
  vestoque_tot = 0;
  select count(*) from cod_grade_prod cg
  where cg.grupo_prod = :pgrupo_prod
  and cg.cod_prod = :pcod_prod
  and cg.cod_empresa = :pcod_empresa
  and cg.ativo = 1
    into :vexiste_grade;

  if (coalesce(vexiste_grade, 0) > 0) then
  begin
    for select cg.cod_grade from cod_grade_prod cg
        where cg.grupo_prod = :pgrupo_prod
        and cg.cod_prod = :pcod_prod
        and cg.cod_empresa = :pcod_empresa
        and cg.ativo = 1
    into :vcod_grade do
    begin
      select first 1 est.estoque from estoque_diario est
      where est.grupo_prod = :pgrupo_prod
      and est.cod_prod = :pcod_prod
      and est.cod_grade = :vcod_grade
      and est.cod_empresa = :pcod_empresa
      order by est.dia desc
        into :vestoque;

      vestoque_tot = coalesce(vestoque_tot, 0) + coalesce(vestoque, 0);

      update or insert into cod_grade_prod (grupo_prod, cod_prod, cod_grade, cod_empresa, qtde, ativo)
      values (:pgrupo_prod, :pcod_prod, :vcod_grade, :pcod_empresa, coalesce(:vestoque, 0), 1)
      matching (grupo_prod, cod_prod, cod_grade, cod_empresa);
    end

    update produtos pr set
      pr.est_f = coalesce(:vestoque_tot, 0),
      pr.prec_cus_prod  = coalesce(:vcusto_medio, 0),
      pr.prec_cusm_prod = coalesce(:vcusto_medio, 0),
      pr.prec_cusr_prod = coalesce(:vcusto_medio, 0),
      pr.prec_rep_prod  = coalesce(:vcusto_medio, 0)
    where pr.grupo_prod = :pgrupo_prod
    and pr.cod_prod = :pcod_prod
    and pr.cod_empresa = :pcod_empresa;
  end
  else
  begin
    select first 1 est.estoque from estoque_diario est
    where est.grupo_prod = :pgrupo_prod
    and est.cod_prod = :pcod_prod
    and est.cod_grade = 0
    and est.cod_empresa = :pcod_empresa
    order by est.dia desc
      into :vestoque;

    update produtos pr set
      pr.est_f = coalesce(:vestoque, 0),
      pr.prec_cus_prod = coalesce(:vcusto_medio, 0),
      pr.prec_cusm_prod = coalesce(:vcusto_medio, 0),
      pr.prec_cusr_prod = coalesce(:vcusto_medio, 0),
      pr.prec_rep_prod  = coalesce(:vcusto_medio, 0)
    where pr.grupo_prod = :pgrupo_prod
    and pr.cod_prod = :pcod_prod
    and pr.cod_empresa = :pcod_empresa;
  end
  suspend;
end;
 
 ^

ALTER PROCEDURE ATUALIZAR_CUSTO_ACAB_DOC (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PDATA_INI TIMESTAMP,
PDATA_FIM TIMESTAMP,
PCUSTO_MEDIO DOUBLE PRECISION)
AS 
declare variable VNUMDOC_INI integer;
declare variable VNUMDOC_FIM integer;
begin
  /* Procedure Text */
  
  -- Corrigir custo 
  update estoque_diario est set
    est.custo_medio = coalesce(:pcusto_medio, 0)
  where est.grupo_prod = :pgrupo_prod
  and est.cod_prod = :pcod_prod
  and est.cod_empresa = :pcod_empresa
  and est.dia >= :pdata_ini
  and est.dia <= :pdata_fim;
  
  update custos c set
    c.pr_cusc_prod = coalesce(:pcusto_medio, 0),
    c.prec_cus_med = coalesce(:pcusto_medio, 0)
  where c.grupo_prod = :pgrupo_prod
  and c.cod_prod = :pcod_prod
  and c.cod_empresa = :pcod_empresa
  and c.data >= :pdata_ini
  and c.data <= :pdata_fim;

  -- Atualizar requisicoes
  select numdoc_ini, numdoc_fim from retorna_numdoc_ini_fim(
    :pgrupo_prod,
    :pcod_prod,
    :pcod_empresa,
    'REQ',
    :pdata_ini,
    :pdata_fim)
      into :vnumdoc_ini, :vnumdoc_fim;
    
  if ((coalesce(vnumdoc_ini, 0) > 0) and (coalesce(vnumdoc_fim, 0) > 0)) then
  begin
    update pedvenda_prod pp set
      pp.pcust_c  = coalesce(:pcusto_medio, 0),
      pp.pcust_r  = coalesce(:pcusto_medio, 0),
      pp.pcust_mc = coalesce(:pcusto_medio, 0),
      pp.pcust_mr = coalesce(:pcusto_medio, 0)
    where pp.nped >= :vnumdoc_ini
    and pp.nped <= :vnumdoc_fim
    and pp.tipo = 'REQ'
    and pp.grupo_prod = :pgrupo_prod
    and pp.cod_prod = :pcod_prod
    and pp.cod_empresa = :pcod_empresa;

    update hist_estoque_diario hd set
      hd.custo_med = coalesce(:pcusto_medio, 0)
    where hd.numero >= :vnumdoc_ini
    and hd.numero <= :vnumdoc_fim
    and hd.tipor = 'REQ'
    and hd.grupo_prod = :pgrupo_prod
    and hd.cod_prod = :pcod_prod
    and hd.cod_empresa = :pcod_empresa;

    update hist_estoque_diario_prod hp set
      hp.custo_med = coalesce(:pcusto_medio, 0)
    where hp.numero >= :vnumdoc_ini
    and hp.numero <= :vnumdoc_fim
    and hp.tipor = 'REQ'
    and hp.grupo_prod = :pgrupo_prod
    and hp.cod_prod = :pcod_prod
    and hp.cod_empresa = :pcod_empresa;
  end

  -- Atualizar ordem de servico
  select numdoc_ini, numdoc_fim from retorna_numdoc_ini_fim(
    :pgrupo_prod,
    :pcod_prod,
    :pcod_empresa,
    'OS',
    :pdata_ini,
    :pdata_fim)
      into :vnumdoc_ini, :vnumdoc_fim;
    
  if ((coalesce(vnumdoc_ini, 0) > 0) and (coalesce(vnumdoc_fim, 0) > 0)) then
  begin
    update pedvenda_prod pp set
      pp.pcust_c  = coalesce(:pcusto_medio, 0),
      pp.pcust_r  = coalesce(:pcusto_medio, 0),
      pp.pcust_mc = coalesce(:pcusto_medio, 0),
      pp.pcust_mr = coalesce(:pcusto_medio, 0)
    where pp.nped >= :vnumdoc_ini
    and pp.nped <= :vnumdoc_fim
    and pp.tipo = 'OS'
    and pp.grupo_prod = :pgrupo_prod
    and pp.cod_prod = :pcod_prod
    and pp.cod_empresa = :pcod_empresa;

    update hist_estoque_diario hd set
      hd.custo_med = coalesce(:pcusto_medio, 0)
    where hd.numero >= :vnumdoc_ini
    and hd.numero <= :vnumdoc_fim
    and hd.tipor = 'OS'
    and hd.grupo_prod = :pgrupo_prod
    and hd.cod_prod = :pcod_prod
    and hd.cod_empresa = :pcod_empresa;

    update hist_estoque_diario_prod hp set
      hp.custo_med = coalesce(:pcusto_medio, 0)
    where hp.numero >= :vnumdoc_ini
    and hp.numero <= :vnumdoc_fim
    and hp.tipor = 'OS'
    and hp.grupo_prod = :pgrupo_prod
    and hp.cod_prod = :pcod_prod
    and hp.cod_empresa = :pcod_empresa;
  end

  -- Atualizar orcamentos
  select numdoc_ini, numdoc_fim from retorna_numdoc_ini_fim(
    :pgrupo_prod,
    :pcod_prod,
    :pcod_empresa,
    'ORC',
    :pdata_ini,
    :pdata_fim)
      into :vnumdoc_ini, :vnumdoc_fim;
    
  if ((coalesce(vnumdoc_ini, 0) > 0) and (coalesce(vnumdoc_fim, 0) > 0)) then
  begin
    update pedvenda_prod pp set
      pp.pcust_c  = coalesce(:pcusto_medio, 0),
      pp.pcust_r  = coalesce(:pcusto_medio, 0),
      pp.pcust_mc = coalesce(:pcusto_medio, 0),
      pp.pcust_mr = coalesce(:pcusto_medio, 0)
    where pp.nped >= :vnumdoc_ini
    and pp.nped <= :vnumdoc_fim
    and pp.tipo = 'ORC'
    and pp.grupo_prod = :pgrupo_prod
    and pp.cod_prod = :pcod_prod
    and pp.cod_empresa = :pcod_empresa;

    update hist_estoque_diario hd set
      hd.custo_med = coalesce(:pcusto_medio, 0)
    where hd.numero >= :vnumdoc_ini
    and hd.numero <= :vnumdoc_fim
    and hd.tipor = 'ORC'
    and hd.grupo_prod = :pgrupo_prod
    and hd.cod_prod = :pcod_prod
    and hd.cod_empresa = :pcod_empresa;

    update hist_estoque_diario_prod hp set
      hp.custo_med = coalesce(:pcusto_medio, 0)
    where hp.numero >= :vnumdoc_ini
    and hp.numero <= :vnumdoc_fim
    and hp.tipor = 'ORC'
    and hp.grupo_prod = :pgrupo_prod
    and hp.cod_prod = :pcod_prod
    and hp.cod_empresa = :pcod_empresa;
  end

  -- Atualizar devolucao
  select numdoc_ini, numdoc_fim from retorna_numdoc_ini_fim(
    :pgrupo_prod,
    :pcod_prod,
    :pcod_empresa,
    'DEV',
    :pdata_ini,
    :pdata_fim)
      into :vnumdoc_ini, :vnumdoc_fim;

  if ((coalesce(vnumdoc_ini, 0) > 0) and (coalesce(vnumdoc_fim, 0) > 0)) then
  begin
    update devolucao dev set
      dev.pcust_mc  = coalesce(:pcusto_medio, 0)
    where dev.sequencia >= :vnumdoc_ini
    and dev.sequencia <= :vnumdoc_fim
    and dev.grupo_prod = :pgrupo_prod
    and dev.cod_prod = :pcod_prod
    and dev.cod_empresa = :pcod_empresa;

    update hist_estoque_diario hd set
      hd.custo_med = coalesce(:pcusto_medio, 0)
    where hd.numero >= :vnumdoc_ini
    and hd.numero <= :vnumdoc_fim
    and hd.tipor = 'DEV'
    and hd.grupo_prod = :pgrupo_prod
    and hd.cod_prod = :pcod_prod
    and hd.cod_empresa = :pcod_empresa;

    update hist_estoque_diario_prod hp set
      hp.custo_med = coalesce(:pcusto_medio, 0)
    where hp.numero >= :vnumdoc_fim
    and hp.numero <= :vnumdoc_ini
    and hp.tipor = 'DEV'
    and hp.grupo_prod = :pgrupo_prod
    and hp.cod_prod = :pcod_prod
    and hp.cod_empresa = :pcod_empresa;
  end

  -- Atualizar notafiscal saida
  select numdoc_ini, numdoc_fim from retorna_numdoc_ini_fim(
    :pgrupo_prod,
    :pcod_prod,
    :pcod_empresa,
    'NF',
    :pdata_ini,
    :pdata_fim)
      into :vnumdoc_ini, :vnumdoc_fim;
    
  if ((coalesce(vnumdoc_ini, 0) > 0) and (coalesce(vnumdoc_fim, 0) > 0)) then
  begin
    update notafiscal_item nfi set
      nfi.prec_cus_rep  = coalesce(:pcusto_medio, 0),
      nfi.prec_cus_cnt  = coalesce(:pcusto_medio, 0),
      nfi.prec_cus_r = coalesce(:pcusto_medio, 0),
      nfi.prec_cusm_prod = coalesce(:pcusto_medio, 0)
    where nfi.cod_nf >= :vnumdoc_ini
    and nfi.cod_nf <= :vnumdoc_fim
    and nfi.codigo_nop > 3000
    and nfi.grupo_prod = :pgrupo_prod
    and nfi.cod_prod = :pcod_prod
    and nfi.cod_empresa = :pcod_empresa;
  end
  suspend;
end ^

ALTER PROCEDURE ATUALIZAR_ESTOQUE_DIARIO (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PDATA TIMESTAMP)
RETURNS (RESULT VARCHAR(10) CHARACTER SET NONE)
AS 
declare variable VEXISTE_REG integer;
declare variable VDATA_DOCTMP timestamp;
begin
  /* Procedure Text */
  result = 'OK';
  select first 1 est.seqid from estoque_diario est
  where est.dia >= :pdata
  and est.grupo_prod = :pgrupo_prod
  and est.cod_prod = :pcod_prod
  and est.cod_empresa = :pcod_empresa
    into :vexiste_reg;

  if (coalesce(vexiste_reg, 0) > 0) then
  begin
    for select distinct est.dia from estoque_diario est
        where est.dia >= :pdata
        and est.grupo_prod = :pgrupo_prod
        and est.cod_prod = :pcod_prod
        and est.cod_empresa = :pcod_empresa
         into :vdata_doctmp do
    begin
      execute procedure atribuir_est_data (
        :pgrupo_prod,
        :pcod_prod,
        :pcod_empresa,
        :vdata_doctmp);
    end

    -- Atualizar estoque
    execute procedure atribuir_est_ult_data (
      :pgrupo_prod,
      :pcod_prod,
      :pcod_empresa,
      :vdata_doctmp);
  end
  suspend;
end;
 
 ^

ALTER PROCEDURE ATUALIZAR_LISTA_PROMOCAO (COD_EMPRESA INTEGER)
RETURNS (RESULT VARCHAR(10) CHARACTER SET NONE)
AS 
declare variable VDATA_INI timestamp;
declare variable VDATA_FIM timestamp;
declare variable VHORA_INI varchar(8);
declare variable VHORA_FIM varchar(8);
declare variable VORDEM integer;
declare variable VTIPO char(1);
declare variable VCODIGO integer;
declare variable VCOD_TPPRECO integer;
declare variable VDESCRICAO varchar(128);
declare variable VPROMOCAO integer;
declare variable VLOCALIDADE integer;
declare variable VSETOR integer;
declare variable VCIDADE integer;
declare variable VAVULSO integer;
declare variable VQUANTIDADE integer;
declare variable VINCORDEM integer;
begin
  /* Procedure Text */
  result = 'ERRO';

  for select promocao.cod_promocao, promocao.cod_tppreco,
      cast('2000-01-01 00:00:01' as timestamp) data_ini,
      cast('2099-12-31 23:59:59' as timestamp) data_fim,
      '00:00:01' hora_ini,
      '23:59:59' hora_fim from promocao
      where promocao.cod_promocao > 0 
	  and promocao.cod_empresa = :cod_empresa
      and promocao.data_ini is null
      and promocao.data_fim is null
      into :vpromocao, :vcod_tppreco, :vdata_ini, :vdata_fim, :vhora_ini, :vhora_fim do
  begin
    update promocao set
        promocao.data_ini = :vdata_ini,
        promocao.data_fim = :vdata_fim,
        promocao.hora_ini = :vhora_ini,
        promocao.hora_fim = :vhora_fim
    where promocao.cod_promocao = :vpromocao
    and promocao.cod_tppreco = :vcod_tppreco
    and promocao.cod_empresa = :cod_empresa;
  end

  for select promocao.cod_promocao, promocao.cod_tppreco,
      ((select result from strzero(extract(hour from promocao.data_ini), 2)) || ':' ||
       (select result from strzero(extract(minute from promocao.data_ini), 2)) || ':' ||
       (select result from strzero(extract(second from promocao.data_ini), 2))
      ) hora_ini,
      ((select result from strzero(extract(hour from promocao.data_fim), 2)) || ':' ||
       (select result from strzero(extract(minute from promocao.data_fim), 2)) || ':' ||
       (select result from strzero(extract(second from promocao.data_fim), 2))
      ) hora_fim from promocao
      where promocao.cod_empresa = :cod_empresa
	  and promocao.cod_promocao > 0
      and promocao.data_ini is not null
      and promocao.data_fim is not null
      and coalesce(promocao.hora_ini, '') = ''
      and coalesce(promocao.hora_fim, '') = ''
        into :vpromocao, :vcod_tppreco, :vhora_ini, :vhora_fim do
  begin
    update promocao set
        promocao.hora_ini = :vhora_ini,
        promocao.hora_fim = :vhora_fim
    where promocao.cod_promocao = :vpromocao
    and promocao.cod_tppreco = :vcod_tppreco
    and promocao.cod_empresa = :cod_empresa;
  end

  select count(*) from tipo_preco where cod_tppreco = 1 and cod_empresa = :cod_empresa into :vpromocao;
  if (coalesce(vpromocao, 0) <= 0) then
  begin
    insert into tipo_preco (cod_tppreco, cod_empresa, tipo, descr_tipo, recalc_preco, usar_debcred)
    values (1, :cod_empresa, 'P', 'PROMOCAO', NULL, NULL);
  end

  select count(*) from tipo_preco where cod_tppreco = 2 and cod_empresa = :cod_empresa into :vlocalidade;
  if (coalesce(vlocalidade, 0) <= 0) then
  begin
    insert into tipo_preco (cod_tppreco, cod_empresa, tipo, descr_tipo, recalc_preco, usar_debcred)
    values (2, :cod_empresa, 'T', 'LOCALIDADE', 'S', 'S');
  end

  select count(*) from tipo_preco where cod_tppreco = 3 and cod_empresa = :cod_empresa into :vsetor;
  if (coalesce(vsetor, 0) <= 0) then
  begin
    insert into tipo_preco (cod_tppreco, cod_empresa, tipo, descr_tipo, recalc_preco, usar_debcred)
    values (3, :cod_empresa, 'T', 'SETOR', 'S', 'S');
  end

  select count(*) from tipo_preco where cod_tppreco = 4 and cod_empresa = :cod_empresa into :vcidade;
  if (coalesce(vcidade, 0) <= 0) then
  begin
    insert into tipo_preco (cod_tppreco, cod_empresa, tipo, descr_tipo, recalc_preco, usar_debcred)
    values (4, :cod_empresa, 'T', 'CIDADE', 'S', 'S');
  end

  select count(*) from tipo_preco where cod_tppreco = 5 and cod_empresa = :cod_empresa into :vavulso;
  if (coalesce(vavulso, 0) <= 0) then
  begin
    insert into tipo_preco (cod_tppreco, cod_empresa, tipo, descr_tipo, recalc_preco, usar_debcred)
    values (5, :cod_empresa, 'T', 'AVULSO', NULL, NULL);
  end

  select count(*) from tipo_preco where cod_tppreco = 6 and cod_empresa = :cod_empresa into :vquantidade;
  if (coalesce(vquantidade, 0) <= 0) then
  begin
    insert into tipo_preco (cod_tppreco, cod_empresa, tipo, descr_tipo, recalc_preco, usar_debcred)
    values (6, :cod_empresa, 'Q', 'QUANTIDADE', 'N', 'S');
  end
  
  select count(*) from promocao where cod_promocao = 0 and cod_tppreco = 2 and cod_empresa = :cod_empresa into :vpromocao;
  
  if (coalesce(vpromocao, 0) <= 0) then
  begin
    insert into promocao (cod_promocao, cod_tppreco, cod_empresa, descr_promocao, ordem, ativo, recalc_preco, usar_debcred)
    values (0, 2, :cod_empresa, 'TABELA DE PRECO', 1, 1, 'N', 'S');
  end
  
  select count(*) from promocao where cod_promocao = 0 and cod_tppreco = 3 and cod_empresa = :cod_empresa into :vpromocao;
  
  if (coalesce(vpromocao, 0) <= 0) then
  begin
    insert into promocao (cod_promocao, cod_tppreco, cod_empresa, descr_promocao, ordem, ativo, recalc_preco, usar_debcred)
    values (0, 3, :cod_empresa, 'TABELA DE PRECO', 1, 1, 'N', 'S');
  end
  
  select count(*) from promocao where cod_promocao = 0 and cod_tppreco = 4 and cod_empresa = :cod_empresa into :vpromocao;
  
  if (coalesce(vpromocao, 0) <= 0) then
  begin
    insert into promocao (cod_promocao, cod_tppreco, cod_empresa, descr_promocao, ordem, ativo, recalc_preco, usar_debcred)
    values (0, 4, :cod_empresa, 'TABELA DE PRECO', 1, 1, 'N', 'S');
  end
  
  select count(*) from promocao where cod_promocao = 0 and cod_tppreco = 6 and cod_empresa = :cod_empresa into :vpromocao;
  
  if (coalesce(vpromocao, 0) <= 0) then
  begin
    insert into promocao (cod_promocao, cod_tppreco, cod_empresa, descr_promocao, ordem, ativo, recalc_preco, usar_debcred)
    values (0, 6, :cod_empresa, 'TABELA DE PRECO', 1, 1, 'N', 'S');
  end
  
  update promocao set ordem = 999 where ativo <> 1;

  select count(*) from promocao where cod_promocao > 0 and cod_tppreco = 2 and cod_empresa = :cod_empresa and padrao = 'S' into :vlocalidade;
  if (coalesce(vlocalidade, 0) <= 0) then
  begin
    insert into promocao (cod_promocao, cod_tppreco, cod_empresa, descr_promocao, data_ini, data_fim, hora_ini, hora_fim, ordem, ativo, recalc_preco, usar_debcred, padrao)
    values ((select cod from incrementa_codigo (:cod_empresa, 'PROMOCAO')),
             2,
             :cod_empresa,
             'LOCALIDADE',
             '2000-01-01 00:00:01',
             '2099-12-31 23:59:59',
             '00:00:01',
             '23:59:59',
             0,
             88,
             coalesce((select coalesce(tipo_preco.recalc_preco, 'N') from tipo_preco
                       where tipo_preco.cod_tppreco = 2
                       and tipo_preco.cod_empresa = :cod_empresa), 'N'),
             'S',
			 'S');
  end

  select count(*) from promocao where cod_promocao > 0 and cod_tppreco = 3 and cod_empresa = :cod_empresa and padrao = 'S' into :vsetor;
  if (coalesce(vsetor, 0) <= 0) then
  begin
    insert into promocao (cod_promocao, cod_tppreco, cod_empresa, descr_promocao, data_ini, data_fim, hora_ini, hora_fim, ordem, ativo, recalc_preco, usar_debcred, padrao)
    values ((select cod from incrementa_codigo (:cod_empresa, 'PROMOCAO')),
             3,
             :cod_empresa,
             'SETOR',
             '2000-01-01 00:00:01',
             '2099-12-31 23:59:59',
             '00:00:01',
             '23:59:59',
             0,
             88,
             coalesce((select coalesce(tipo_preco.recalc_preco, 'N') from tipo_preco
                      where tipo_preco.cod_tppreco = 3
                      and tipo_preco.cod_empresa = :cod_empresa), 'N'),
             'S',
			 'S');
  end

  select count(*) from promocao where cod_promocao > 0 and cod_tppreco = 4 and cod_empresa = :cod_empresa and padrao = 'S' into :vcidade;
  if (coalesce(vcidade, 0) <= 0) then
  begin
    insert into promocao (cod_promocao, cod_tppreco, cod_empresa, descr_promocao, data_ini, data_fim, hora_ini, hora_fim, ordem, ativo, recalc_preco, usar_debcred, padrao)
    values ((select cod from incrementa_codigo (:cod_empresa, 'PROMOCAO')),
             4,
             :cod_empresa,
             'CIDADE',
             '2000-01-01 00:00:01',
             '2099-12-31 23:59:59',
             '00:00:01',
             '23:59:59',
             0,
             88,
             coalesce((select coalesce(tipo_preco.recalc_preco, 'N') from tipo_preco
                      where tipo_preco.cod_tppreco = 4
                      and tipo_preco.cod_empresa = :cod_empresa), 'N'),
             'S',
			 'S');
  end

  select count(*) from promocao where cod_promocao > 0 and cod_tppreco = 6 and cod_empresa = :cod_empresa and padrao = 'S' into :vquantidade;
  if (coalesce(vquantidade, 0) <= 0) then
  begin
    insert into promocao (cod_promocao, cod_tppreco, cod_empresa, descr_promocao, data_ini, data_fim, hora_ini, hora_fim, ordem, ativo, recalc_preco, usar_debcred, padrao)
    values ((select cod from incrementa_codigo (:cod_empresa, 'PROMOCAO')),
             6,
             :cod_empresa,
             'QUANTIDADE',
             '2000-01-01 00:00:01',
             '2099-12-31 23:59:59',
             '00:00:01',
             '23:59:59',
             0,
             88,
             coalesce((select coalesce(tipo_preco.recalc_preco, 'N') from tipo_preco
                      where tipo_preco.cod_tppreco = 6
                      and tipo_preco.cod_empresa = :cod_empresa), 'N'),
             'S',
			 'S');
  end
  
  vincordem = 0;
  for select (1000 + promocao.ordem) ordem, tipo_preco.tipo, promocao.cod_promocao, promocao.cod_tppreco, promocao.descr_promocao from promocao
      inner join tipo_preco on tipo_preco.cod_tppreco = promocao.cod_tppreco and tipo_preco.cod_empresa =  promocao.cod_empresa
      where promocao.cod_empresa = :cod_empresa and promocao.ativo in (1, 88) and tipo_preco.tipo = 'P' and promocao.cod_promocao > 0 
      union all
      select first 1 (2000 + promocao.ordem) ordem, tipo_preco.tipo, promocao.cod_promocao, promocao.cod_tppreco, promocao.descr_promocao from promocao
      inner join tipo_preco on tipo_preco.cod_tppreco = promocao.cod_tppreco and tipo_preco.cod_empresa =  promocao.cod_empresa
      where promocao.cod_empresa = :cod_empresa and promocao.ativo in (1, 88) and tipo_preco.tipo = 'T' and promocao.cod_promocao > 0 and promocao.descr_promocao = 'LOCALIDADE'
      union all
      select first 1 (3000 + promocao.ordem) ordem, tipo_preco.tipo, promocao.cod_promocao, promocao.cod_tppreco, promocao.descr_promocao from promocao
      inner join tipo_preco on tipo_preco.cod_tppreco = promocao.cod_tppreco and tipo_preco.cod_empresa =  promocao.cod_empresa
      where promocao.cod_empresa = :cod_empresa and promocao.ativo in (1, 88) and tipo_preco.tipo = 'T' and promocao.cod_promocao > 0 and promocao.descr_promocao = 'SETOR'
      union all
      select first 1 (4000 + promocao.ordem) ordem, tipo_preco.tipo, promocao.cod_promocao, promocao.cod_tppreco, promocao.descr_promocao from promocao
      inner join tipo_preco on tipo_preco.cod_tppreco = promocao.cod_tppreco and tipo_preco.cod_empresa =  promocao.cod_empresa
      where promocao.cod_empresa = :cod_empresa and promocao.ativo in (1, 88) and tipo_preco.tipo = 'T' and promocao.cod_promocao > 0 and promocao.descr_promocao = 'CIDADE'
      union all
      select (5000 + promocao.ordem) ordem, tipo_preco.tipo, promocao.cod_promocao, promocao.cod_tppreco, promocao.descr_promocao from promocao
      inner join tipo_preco on tipo_preco.cod_tppreco = promocao.cod_tppreco and tipo_preco.cod_empresa =  promocao.cod_empresa
      where promocao.cod_empresa = :cod_empresa and promocao.ativo in (1, 88) and tipo_preco.tipo = 'T' and promocao.cod_promocao > 0 and promocao.descr_promocao not in ('LOCALIDADE', 'SETOR', 'CIDADE')
      union all
      select first 1 (6000 + promocao.ordem) ordem, tipo_preco.tipo, promocao.cod_promocao, promocao.cod_tppreco, promocao.descr_promocao from promocao
      inner join tipo_preco on tipo_preco.cod_tppreco = promocao.cod_tppreco and tipo_preco.cod_empresa =  promocao.cod_empresa
      where promocao.cod_empresa = :cod_empresa and promocao.ativo in (1, 88) and tipo_preco.tipo = 'Q' and promocao.cod_promocao > 0 and promocao.descr_promocao = 'QUANTIDADE'
      order by 4, 1
        into :vordem, :vtipo, :vcodigo, :vcod_tppreco, :vdescricao do
  begin
     vincordem = vincordem + 1;
     update promocao set promocao.ordem = coalesce(:vincordem, 0)
     where promocao.cod_promocao = :vcodigo
     and promocao.cod_tppreco = :vcod_tppreco
     and promocao.cod_empresa = :cod_empresa;
  end

  result = 'OK';
  suspend;
end;
 
 ^

ALTER PROCEDURE AUMENTA_ESTOQUE (VGRUPO INTEGER,
VCOD_PROD CHAR(6) CHARACTER SET NONE,
QUANT DOUBLE PRECISION,
VESTS DOUBLE PRECISION,
VESTM DOUBLE PRECISION,
VESTC DOUBLE PRECISION,
VDATA TIMESTAMP,
COD_EMPRESA INTEGER)
AS 
BEGIN
  UPDATE PRODUTOS SET EST_F = EST_F+:QUANT,ESTS = ESTS+:VESTS,
  ESTM = ESTM+:VESTM,ESTC = ESTC+:VESTC WHERE GRUPO_PROD = :VGRUPO AND 
  COD_PROD = :VCOD_PROD and cod_empresa = :cod_empresa and ativo=1;
END ^

ALTER PROCEDURE BAIXA_E (VGRUPO INTEGER,
VCOD_PROD CHAR(6) CHARACTER SET NONE,
QUANT DOUBLE PRECISION,
VESTS DOUBLE PRECISION,
VESTM DOUBLE PRECISION,
VESTC DOUBLE PRECISION,
VDATA TIMESTAMP,
VTAB CHAR(20) CHARACTER SET NONE)
AS 
BEGIN EXIT; END ^

ALTER PROCEDURE BAIXA_ESTOQUE (VGRUPO INTEGER,
VCOD_PROD CHAR(6) CHARACTER SET NONE,
QUANT DOUBLE PRECISION,
VESTS DOUBLE PRECISION,
VESTM DOUBLE PRECISION,
VESTC DOUBLE PRECISION,
VDATA TIMESTAMP,
COD_EMPRESA INTEGER)
AS 
BEGIN
  UPDATE PRODUTOS SET EST_F = EST_F-:QUANT,ESTS = ESTS-:VESTS,
  ESTM = ESTM-:VESTM,ESTC = ESTC-:VESTC,
  DT_ULT_VNDA = DT_ULT_VND,DT_ULT_VND = CAST('NOW' AS DATE) WHERE GRUPO_PROD = :VGRUPO AND 
  COD_PROD = :VCOD_PROD and cod_empresa = :cod_empresa and ativo=1;
END ^

ALTER PROCEDURE BAIXA_ESTOQUE_GRADE (VGRUPO INTEGER,
VCOD_PROD CHAR(6) CHARACTER SET NONE,
VCOD_GRADE INTEGER,
QUANT DOUBLE PRECISION,
COD_EMPRESA INTEGER)
AS 
BEGIN
  UPDATE COD_GRADE_PROD SET QTDE = QTDE-:QUANT WHERE GRUPO_PROD = :VGRUPO AND 
  COD_PROD = :VCOD_PROD AND COD_GRADE = :VCOD_GRADE and COD_EMPRESA = :COD_EMPRESA;
END ^

ALTER PROCEDURE BAIXA_REC_DET (PNRECIBO INTEGER,
PTIPO_BAIXA CHAR(10) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (SEQCAD_REC INTEGER,
COD_EMPRESA INTEGER,
NRECIBO INTEGER,
VALOR_BAIXA DOUBLE PRECISION,
VALOR_RECIBO DOUBLE PRECISION,
DATA_REC TIMESTAMP,
RECANT CHAR(1) CHARACTER SET NONE,
NDOCANT INTEGER,
DATA_BAIXA TIMESTAMP,
HISTORICO_REC VARCHAR(50) CHARACTER SET NONE,
ATIVO INTEGER,
COD_US INTEGER,
TP_DOC_BAIXA CHAR(3) CHARACTER SET NONE,
TP_BAIXA CHAR(1) CHARACTER SET NONE,
LOTE_QUIT INTEGER,
COD_UNIFICADA INTEGER,
OP_CXL INTEGER)
AS 
declare variable VSQL varchar(100);
begin
  /* Procedure Text */

  vsql = '';
  if (coalesce(ptipo_baixa, '') = 'MANUAL') then
    vsql = ' and hist.tp_doc_baixa is null ';
  else if ((coalesce(ptipo_baixa, '') = 'REQ') or (coalesce(ptipo_baixa, '') = 'OS'))  then
    vsql = ' and hist.tp_doc_baixa = ''' || :ptipo_baixa || '';
  else if ((coalesce(ptipo_baixa, '') = 'PRE') or (coalesce(ptipo_baixa, '') = 'CC') or (coalesce(ptipo_baixa, '') = 'CH'))  then
    vsql = ' and hist.tp_doc_baixa = ''PRE'' ';

  for execute statement
        ' select hist.seqcad_rec, hist.cod_empresa, hist.nrecibo, hist.valor_baixa, hist.valor_recibo, hist.data_rec, hist.recant,
          hist.ndocant, hist.data_baixa, hist.historico_rec, hist.ativo, hist.cod_us,
          hist.tp_doc_baixa, hist.tp_baixa, hist.lote_quit, hist.cod_unificada, hist.op_cxl from hist_rec hist
          where hist.nrecibo = ' || :pnrecibo || '
          and hist.cod_empresa = ' || :pcod_empresa || :vsql
       into :seqcad_rec, :cod_empresa, :nrecibo, :valor_baixa, :valor_recibo, :data_rec, :recant,
            :ndocant, :data_baixa, :historico_rec, :ativo, :cod_us,
            :tp_doc_baixa, :tp_baixa, :lote_quit, :cod_unificada, :op_cxl do
  begin
    suspend;
  end
end ^

ALTER PROCEDURE CONSULTAR_CUSTO_ESTOQUE (PTIPO VARCHAR(5) CHARACTER SET NONE,
PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA INTEGER,
PDATA TIMESTAMP,
PCOD_NF INTEGER,
PNITEM_NF INTEGER,
PQTDE DOUBLE PRECISION,
PCUSTO_MED DOUBLE PRECISION)
RETURNS (RESULT VARCHAR(10) CHARACTER SET NONE)
AS 
declare variable VCAMPOS varchar(1000);
declare variable VWHERE varchar(1000);
declare variable VSQL varchar(1000);
declare variable VSQL2 varchar(1000);
declare variable VEXISTE_REG integer;
declare variable VORDEMTMP integer;
declare variable VNUM_DOCTMP integer;
declare variable VTIPO_DOCTMP char(6);
declare variable VDATA_DOCTMP timestamp;
declare variable VNITEMTMP integer;
declare variable VNATUREZATMP char(1);
declare variable VCOD_NFTMP integer;
declare variable VALTEROU_CUSTO char(10);
begin
  /* Procedure Text */
  vwhere = ' where f.grupo_prod = ' || :pgrupo_prod || '
  and f.cod_prod = ''' || :pcod_prod || '''
  and f.cod_grade = ' || :pcod_grade || '
  and f.cod_empresa = ' || :pcod_empresa || '
  and f.data_estoque >= ''' || cast(:pdata as date) || '''
  and f.tipo in (''DEV'', ''NF'', ''REQ'', ''OS'', ''PDC'', ''COR'') ';

  vcampos = ' select f.data_estoque, f.natureza, f.ordem, f.tipo, f.cod_nf, f.numdoc, f.nitem_id, f.altera_custo ';

  vsql  = ' select first 1 f.cod_empresa from fichaprodutosdetalhada f '
          || vwhere;

  vsql2 = vcampos || ' from fichaprodutosdetalhada f '
          || vwhere;

  if (trim(ptipo) = 'NFX') then
  begin
    vsql2 = vsql2 ||
        ' union ' ||
        vcampos || ' from fichaprodutosdetalhada f ' ||
        ' where f.cod_nf = ' || :pcod_nf || '
          and f.nitem_id = ' || :pnitem_nf || '
          and f.natureza = ''E''
          and f.grupo_prod = ' || :pgrupo_prod || '
          and f.cod_prod = ''' || :pcod_prod || '''
          and f.cod_grade = ' || :pcod_grade || '
          and f.cod_empresa = ' || :pcod_empresa || '
          and f.data_estoque = ''' || cast(:pdata as date) || '''
          and f.tipo = ''NFX'' ';
  end

  vsql2 = vsql2 ||
    ' order by 1, 2, 3, 4, 5, 6, 7 ';

  execute statement
    :vsql
      into :vexiste_reg;

  if (coalesce(vexiste_reg, 0) > 0) then
  begin
    for execute statement
          :vsql2
            into :vdata_doctmp, :vnaturezatmp, :vordemtmp, :vtipo_doctmp, :vcod_nftmp, :vnum_doctmp, :vnitemtmp, :valterou_custo do
    begin
      -- Parar rotina na proxima nota
      if ((coalesce(pcod_nf, 0) > 0)
           and (trim(vtipo_doctmp) = 'NF')
           and (trim(vnaturezatmp) = 'E')
           and (coalesce(vcod_nftmp, 0) > coalesce(pcod_nf, 0))
           and (coalesce(valterou_custo, 'N') = 'S')) then
      begin
        result = 'OK';
        suspend;
        exit;
      end

      -- Parar rotina no proximo item
      if ((coalesce(pcod_nf, 0) > 0)
          and (trim(vtipo_doctmp) = 'NF')
          and (trim(vnaturezatmp) = 'E')
          and (coalesce(vcod_nftmp, 0) = coalesce(pcod_nf, 0))
          and (coalesce(vnitemtmp, 0) > coalesce(pnitem_nf, 0))
          and (coalesce(valterou_custo, 'N') = 'S')) then
      begin
        result = 'OK';
        suspend;
        exit;
      end

      if ( ((trim(vtipo_doctmp) = 'NFX') and (trim(vnaturezatmp) = 'E'))
           or ((trim(vtipo_doctmp) = 'NF') and (trim(vnaturezatmp) = 'E'))
           or (((trim(vtipo_doctmp) = 'REQ') or (trim(vtipo_doctmp) = 'OS')) and (trim(vnaturezatmp) = 'S'))
           or ((trim(vtipo_doctmp) = 'DEV') and (trim(vnaturezatmp) = 'E'))
           or ((trim(vtipo_doctmp) = 'PDC') and (trim(vnaturezatmp) = 'S'))
           or (trim(vtipo_doctmp) = 'COR')  ) then
      begin
        execute procedure atribuir_custo (
          :pgrupo_prod,
          :pcod_prod,
          :pcod_grade,
          :pcod_empresa,
          :vdata_doctmp,
          :vcod_nftmp,
          :vnum_doctmp,
          :vtipo_doctmp,
          :vnitemtmp,
          :vnaturezatmp);
      end

      if ((coalesce(pcod_nf, 0) > 0)
          and ((trim(vtipo_doctmp) = 'NFX') or (trim(vtipo_doctmp) = 'NF'))
          and (trim(vnaturezatmp) = 'E')
          and (coalesce(vcod_nftmp, 0) = coalesce(pcod_nf, 0))
          and (coalesce(vnitemtmp, 0) = coalesce(pnitem_nf, 0))) then
      begin
        execute procedure corrigir_estoque_diario (
          :pgrupo_prod,
          :pcod_prod,
          :pcod_grade,
          :pcod_empresa,
          :vdata_doctmp,
          :vcod_nftmp,
          :vtipo_doctmp,
          :pqtde,
          :pcusto_med,
          1);
      end
      else if (coalesce(pcusto_med, 0) > 0) then
      begin
        execute procedure corrigir_estoque_diario (
          :pgrupo_prod,
          :pcod_prod,
          :pcod_grade,
          :pcod_empresa,
          :vdata_doctmp,
          :vcod_nftmp,
          :vtipo_doctmp,
          :pqtde,
          :pcusto_med,
          0);
      end
      else
      begin
        execute procedure corrigir_estoque_diario (
          :pgrupo_prod,
          :pcod_prod,
          :pcod_grade,
          :pcod_empresa,
          :vdata_doctmp,
          0,
          '',
          0,
          0,
          0);
      end
    end

    -- Atualizar estoque
    execute procedure atribuir_est_ult_data (
      :pgrupo_prod,
      :pcod_prod,
      :pcod_empresa,
      :vdata_doctmp);
  end
  suspend;
end ^

ALTER PROCEDURE CORRIGIR_CUSTO_ACABADO (PCOD_PRODUCAO INTEGER,
PTIPO CHAR(6) CHARACTER SET NONE,
PNITEM INTEGER,
PCOD_EMPRESA INTEGER,
PDATA TIMESTAMP)
RETURNS (RESULT VARCHAR(10) CHARACTER SET NONE)
AS 
declare variable VQUANTIDADE_PRODUZIDA_PD double precision;
declare variable VGRUPO_PROD_ACAB integer;
declare variable VCOD_PROD_ACAB char(6);
declare variable VNITEM_ACAB integer;
declare variable VQUANTIDADE_ACAB double precision;
declare variable VPESO_UTIL_ACAB double precision;
declare variable VSOLVENTE_INS char(1);
declare variable VPESO_UN_INS double precision;
declare variable VPESO_UTIL_INS double precision;
declare variable VPREC_CUSM_PROD_INS double precision;
declare variable VQUANTIDADE_UTILIZADA_INS double precision;
declare variable VQUANTIDADE_PERDA_INS double precision;
declare variable VVALORCUSTO double precision;
declare variable VCUSTO_INDICE double precision;
declare variable VCUSTO_RATEIO double precision;
declare variable VVALORPARARATEIO double precision;
declare variable VPESOPARARATEIO double precision;
declare variable VPREC_CUS_PROD double precision;
declare variable VPREC_CUSM_PROD double precision;
declare variable VDATA_ESTOQUETMP timestamp;
declare variable VDATA_ESTOQUE_INI_PD timestamp;
declare variable VDATA_ESTOQUE_FIM_PD timestamp;
declare variable VSEQID integer;
begin
  /* Procedure Text */
  result = 'FALHA';

  vvalorpararateio = 0;
  vpesopararateio  = 0;
  vvalorcusto      = 0;
  for select pii.solvente, pii.prec_cusm_prod,
      pii.quantidade_utilizada,
      pii.quantidade_perda,
      pii.peso_un,
      pii.peso_util from producao p
      inner join producao_item_indice pii on
        pii.cod_producao = p.cod_producao
        and pii.cod_empresa = p.cod_empresa
      where pii.cod_producao = :pcod_producao
      and pii.cod_empresa = :pcod_empresa
      and pii.nitem = 0
      and p.status = 'FECHADO'
        into :vsolvente_ins, :vprec_cusm_prod_ins, :vquantidade_utilizada_ins, :vquantidade_perda_ins,
        :vpeso_un_ins, :vpeso_util_ins do
  begin
    if (trim(vsolvente_ins) <> 'S') then
    begin
      vvalorpararateio = coalesce(vvalorpararateio, 0) +
        (coalesce(vprec_cusm_prod_ins, 0) * coalesce(vquantidade_utilizada_ins, 0));

      vvalorpararateio = coalesce(vvalorpararateio, 0) +
        (coalesce(vprec_cusm_prod_ins, 0) * coalesce(vquantidade_perda_ins, 0));

      vpesopararateio = coalesce(vpesopararateio, 0) +
        (coalesce(vpeso_util_ins, 0));

      vpesopararateio = coalesce(vpesopararateio, 0) +
        (coalesce(vpeso_util_ins, 0) * coalesce(vquantidade_perda_ins, 0));
    end
  end

  for select case when (p.data_estoque is not null) then p.data_estoque else p.data_fechamento end data_estoque,
      p.quantidadeproduzida,
      pi.grupo_prod, pi.cod_prod, pi.nitem,
      pi.quantidade, pi.peso_util from producao p
      inner join producao_item pi on
        pi.cod_producao = p.cod_producao
        and pi.cod_empresa = p.cod_empresa
      where pi.cod_producao = :pcod_producao
      and pi.cod_empresa = :pcod_empresa
      and pi.nitem = :pnitem
      and p.status = 'FECHADO'
        into :vdata_estoque_ini_pd, :vquantidade_produzida_pd,
             :vgrupo_prod_acab, :vcod_prod_acab, :vnitem_acab,
             :vquantidade_acab, :vpeso_util_acab do
  begin
    for select pii.prec_cusm_prod, pii.quantidade_utilizada, pii.quantidade_perda from producao p
        inner join producao_item_indice pii on
          pii.cod_producao = p.cod_producao
          and pii.cod_empresa = p.cod_empresa
        where pii.cod_producao = :pcod_producao
        and pii.cod_empresa = :pcod_empresa
        and pii.nitem = :vnitem_acab
        and p.status = 'FECHADO'
          into :vprec_cusm_prod_ins, :vquantidade_utilizada_ins, :vquantidade_perda_ins do
    begin
      vvalorcusto = coalesce(vvalorcusto, 0) +
        (coalesce(vprec_cusm_prod_ins, 0) * coalesce(vquantidade_utilizada_ins, 0));

      vvalorcusto = coalesce(vvalorcusto, 0) +
        (coalesce(vprec_cusm_prod_ins, 0) * coalesce(vquantidade_perda_ins, 0));
    end

    vcusto_indice = coalesce(vvalorcusto, 0);
    vvalorcusto = 0;
    if ((coalesce(vvalorpararateio, 0) > 0) and (coalesce(vquantidade_produzida_pd, 0) > 0)) then
      vvalorcusto = (coalesce(vpeso_util_acab, 0) * coalesce(vquantidade_produzida_pd, 0));
    vcusto_rateio = coalesce(vvalorcusto, 0);
    vprec_cus_prod = ((coalesce(vcusto_indice, 0) + coalesce(vcusto_rateio, 0)) / coalesce(vquantidade_acab, 0));
    select custo_medio from retorna_custo_med_acab (
      :vgrupo_prod_acab,
      :vcod_prod_acab,
      :pcod_empresa,
      :pdata,
      :vprec_cus_prod,
      :vquantidade_acab)
        into :vprec_cusm_prod;

    update producao_item pi set
      pi.custo_indice   = coalesce(:vcusto_indice, 0),
      pi.custo_rateio   = coalesce(:vcusto_rateio, 0),
      pi.prec_cus_prod  = coalesce(:vprec_cus_prod, 0),
      pi.prec_cusm_prod = coalesce(:vprec_cusm_prod, 0)
    where pi.cod_producao = :pcod_producao
    and pi.cod_empresa = :pcod_empresa
    and pi.nitem = coalesce(:vnitem_acab, 0)
    and pi.grupo_prod = :vgrupo_prod_acab
    and pi.cod_prod = :vcod_prod_acab;

    for select cast((case when (p.data_estoque is not null) then p.data_estoque else p.data_fechamento end) as timestamp) data_estoque
        from producao p
        inner join producao_item pi on
          pi.cod_producao = p.cod_producao
          and pi.cod_empresa = p.cod_empresa
        where pi.cod_producao > :pcod_producao
        and pi.grupo_prod = :vgrupo_prod_acab
        and pi.cod_prod = :vcod_prod_acab
        and pi.cod_empresa = :pcod_empresa
        and p.status = 'FECHADO'
        union
        select cast(current_date as timestamp) from rdb$database
        where coalesce((select first 1 p.cod_producao from producao p
               inner join producao_item pi on
                 pi.cod_producao = p.cod_producao
                 and pi.cod_empresa = p.cod_empresa
               where pi.cod_producao > :pcod_producao
               and pi.grupo_prod = :vgrupo_prod_acab
               and pi.cod_prod = :vcod_prod_acab
               and pi.cod_empresa = :pcod_empresa
               and p.status = 'FECHADO'), 0) = 0
          into :vdata_estoquetmp do
    begin
      if (vdata_estoque_ini_pd > vdata_estoquetmp) then
      begin
        vdata_estoque_fim_pd = vdata_estoquetmp - 1;
        break;
      end
      else
        vdata_estoque_fim_pd = vdata_estoquetmp;
    end

    -- Atualizar custo produtos acabados
    execute procedure atualizar_custo_acab_doc (
      :vgrupo_prod_acab,
      :vcod_prod_acab,
      :pcod_empresa,
      :vdata_estoque_ini_pd,
      :vdata_estoque_fim_pd,
      :vprec_cusm_prod);

    
    update hist_estoque_diario_prod hp set
	  hp.valor_unit = coalesce(:vprec_cusm_prod, 0),
	  hp.valor_tot = round(hp.qtde * coalesce(:vprec_cusm_prod, 0), 2)
    where hp.numero = :pcod_producao
    and hp.tipor = :ptipo
    and hp.cod_empresa = :pcod_empresa
    and hp.nitem = :pnitem
    and hp.grupo_prod = :vgrupo_prod_acab
    and hp.cod_prod = :vcod_prod_acab;

    update hist_estoque_diario hd set
  	  hd.valor_unit = coalesce(:vprec_cusm_prod, 0),
	  hd.valor_tot = round(hd.qtde * coalesce(:vprec_cusm_prod, 0), 2)
    where hd.numero = :pcod_producao
    and hd.tipor = :ptipo
    and hd.cod_empresa = :pcod_empresa
    and hd.nitem = :pnitem
    and hd.grupo_prod = :vgrupo_prod_acab
    and hd.cod_prod = :vcod_prod_acab;
  end

  result = 'OK';
  suspend;
end;
 
 ^

ALTER PROCEDURE CORRIGIR_ESTOQUE_DIARIO (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA INTEGER,
PDATA TIMESTAMP,
PCOD_NF INTEGER,
PTIPO VARCHAR(5) CHARACTER SET NONE,
PQTDE DOUBLE PRECISION,
PCUSTO_MED DOUBLE PRECISION,
PCORRIGIR_CUSTO_EST INTEGER)
AS 
declare variable VDATA timestamp;
declare variable VESTOQUETMP double precision;
declare variable VESTOQUEDIARIOTMP double precision;
declare variable VESTOQUETMPGER double precision;
declare variable VESTOQUEDIARIOTMPGER double precision;
begin
  /* Procedure Text */
  select estoque, estoque_diario from retorna_estoque_ant(
    :pgrupo_prod,
    :pcod_prod,
    :pcod_grade,
    :pcod_empresa,
    :pdata,
    1)
    into :vestoquetmp, :vestoquediariotmp;

  select estoque, estoque_diario from retorna_estoque_ant(
    :pgrupo_prod,
    :pcod_prod,
    :pcod_grade,
    :pcod_empresa,
    :pdata,
    0)
    into :vestoquetmpGer, :vestoquediariotmpGer;

  if ((coalesce(pcusto_med, 0) > 0) and (coalesce(pcorrigir_custo_est, 0) = 1)) then
  begin
    update estoque_diario est set
      est.estoque = (est.estoque + :pqtde),
      est.custo_medio = :pcusto_med
    where est.grupo_prod = :pgrupo_prod
    and est.cod_prod = :pcod_prod
    and est.cod_grade = :pcod_grade
    and est.cod_empresa = :pcod_empresa
    and est.dia = :pdata;

    update custos c set
      c.prec_cus_med = :pcusto_med,
      c.pr_cusc_prod = :pcusto_med,
      c.valor = :pcusto_med
    where c.grupo_prod = :pgrupo_prod
    and c.cod_prod = :pcod_prod
    and c.cod_empresa = :pcod_empresa
    and c.data = :pdata;

    if (trim(coalesce(ptipo, '')) = 'NFX') then
    begin
       select first 1 f.data_estoque from fichaprodutosdetalhada f
       where f.cod_nf = :pcod_nf
       and f.natureza = 'S'
       and f.cod_empresa = :pcod_empresa
       and f.tipo = 'NFX'
         into :vdata;

      if (vdata is null) then
      begin
        update estoque_diario est set
          est.estoque = (est.estoque + :pqtde)
        where est.grupo_prod = :pgrupo_prod
        and est.cod_prod = :pcod_prod
        and est.cod_grade = :pcod_grade
        and est.cod_empresa = :pcod_empresa
        and est.dia > :pdata;
      end
      else
      begin
        update estoque_diario est set
          est.estoque = (est.estoque + :pqtde)
        where est.grupo_prod = :pgrupo_prod
        and est.cod_prod = :pcod_prod
        and est.cod_grade = :pcod_grade
        and est.cod_empresa = :pcod_empresa
        and est.dia > :pdata
        and est.dia < :vdata;
      end
    end
    else
    begin
      update estoque_diario est set
        est.estoque = (est.estoque + :pqtde)
      where est.grupo_prod = :pgrupo_prod
      and est.cod_prod = :pcod_prod
      and est.cod_grade = :pcod_grade
      and est.cod_empresa = :pcod_empresa
      and est.dia > :pdata;
    end

    if (trim(coalesce(ptipo, '')) = 'NF') then
    begin
      if (coalesce(pcod_grade, 0) > 0) then
      begin
        update cod_grade_prod cg set
          cg.qtde = (cg.qtde + :pqtde)
        where cg.grupo_prod = :pgrupo_prod
        and cg.cod_prod = :pcod_prod
        and cg.cod_grade = :pcod_grade
         and cg.cod_empresa = :pcod_empresa;
      end

      update produtos pr set
        pr.est_f = (pr.est_f + :pqtde)
      where pr.grupo_prod = :pgrupo_prod
      and pr.cod_prod = :pcod_prod
      and pr.cod_empresa = :pcod_empresa;
   end
  end
  else if ((coalesce(pcusto_med, 0) > 0) and (coalesce(pcorrigir_custo_est, 0) = 0)) then
  begin
    update estoque_diario est set
      est.custo_medio = :pcusto_med
    where est.grupo_prod = :pgrupo_prod
    and est.cod_prod = :pcod_prod
    and est.cod_grade = :pcod_grade
    and est.cod_empresa = :pcod_empresa
    and est.dia = :pdata;

    update custos c set
      c.prec_cus_med = :pcusto_med,
      c.pr_cusc_prod = :pcusto_med,
      c.valor = :pcusto_med
    where c.grupo_prod = :pgrupo_prod
    and c.cod_prod = :pcod_prod
    and c.cod_empresa = :pcod_empresa
    and c.data = :pdata;
  end
  else if ((coalesce(vestoquetmp, 0) > 0) and (coalesce(vestoquetmpGer, 0) > 0)) then
  begin
    update estoque_diario est set
      est.estoque = :vestoquetmp,
      est.custo_medio = ((est.custo_medio / :vestoquetmpger) * :vestoquediariotmpger)
    where est.grupo_prod = :pgrupo_prod
    and est.cod_prod = :pcod_prod
    and est.cod_grade = :pcod_grade
    and est.cod_empresa = :pcod_empresa
    and est.dia = :pdata;

    update custos c set
      c.prec_cus_med = ((c.prec_cus_med / :vestoquetmpger) * :vestoquediariotmpger),
      c.pr_cusc_prod = ((c.pr_cusc_prod / :vestoquetmpger) * :vestoquediariotmpger),
      c.valor = ((c.pr_cusc_prod / :vestoquetmpger) * :vestoquediariotmpger)
    where c.grupo_prod = :pgrupo_prod
    and c.cod_prod = :pcod_prod
    and c.cod_empresa = :pcod_empresa
    and c.data = :pdata;
  end
  else
  begin
    update estoque_diario est set
      est.estoque = :vestoquetmp
    where est.grupo_prod = :pgrupo_prod
    and est.cod_prod = :pcod_prod
    and est.cod_grade = :pcod_grade
    and est.cod_empresa = :pcod_empresa
    and est.dia = :pdata;
  end

  suspend;
end;
 
 ^

ALTER PROCEDURE CORRIGIR_EST_CUSTO_NF_PDC (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PNUM INTEGER,
PNITEM INTEGER,
PQUANTIDADE DOUBLE PRECISION)
RETURNS (RESULT VARCHAR(100) CHARACTER SET NONE)
AS 
declare variable VCOD_NF integer;
declare variable VNITEM_NF integer;
declare variable VNATUREZA_NF char(1);
declare variable VTIPO_NF char(1);
declare variable VDATA_NF timestamp;
declare variable VQUANTIDADE double precision;
declare variable VVALOR_UNITARIO double precision;
declare variable VVALOR_TOTAL double precision;
declare variable VPREC_CUS_CNT double precision;
declare variable VPREC_CUS_REP double precision;
declare variable VPREC_CUSM_PROD double precision;
declare variable VPR_CUSC_PROD double precision;
declare variable VPREC_CUS_R double precision;
declare variable VQCOM double precision;
declare variable VNUM_DOCTMP integer;
declare variable VTIPO_DOCTMP char(6);
declare variable VNITEMTMP integer;
declare variable VDATA_DOCTMP timestamp;
declare variable VNATUREZATMP char(1);
declare variable VCOD_NFTMP integer;
declare variable VESTOQUETMP double precision;
declare variable VESTOQUEDIARIOTMP double precision;
declare variable VEXISTE_REG integer;
declare variable VEXISTE_IND integer;
declare variable VEXISTE_GRADE integer;
declare variable VSQL varchar(1000);
declare variable VSQL2 varchar(1000);
declare variable VWHERE varchar(1000);
declare variable VGRUPO_PROD integer;
declare variable VCOD_PROD char(6);
declare variable VCOD_GRADE integer;
declare variable VRESULT varchar(10);
begin
  /* Procedure Text */
  result = 'FALHA';

  vcod_nf = 0;
  vnitem_nf = 0;
  vnatureza_nf = '';
  vtipo_nf = '';
  vquantidade = 0;
  vvalor_unitario = 0;
  vvalor_total = 0;
  vprec_cus_cnt = 0;
  vprec_cus_rep = 0;
  vprec_cusm_prod = 0;
  vpr_cusc_prod = 0;
  vprec_cus_r = 0;
  vqcom = 0;

  vnum_doctmp      = 0;
  vtipo_doctmp     = '';
  vnitemtmp        = 0;
  vdata_doctmp     = null;
  vnaturezatmp     = '';

  if ((trim(ptipo) <> 'NF') and (trim(ptipo) <> 'PDF')) then
  begin
    result = 'DOCUMENTO DEVE SER NF OU PRODUCAO';
    exit;
  end

  if (pquantidade <= 0) then
  begin
    result = 'QUANTIDADE INFORMADA DEVE SER MAIOR QUE ZERO';
    exit;
  end

  if (ptipo = 'NF') then
  begin
    select nfi.cod_nf,
    nfi.nitem,
    nf.natureza_nf,
    nf.tipo_nf,
    nf.data_estoque,
    nfi.quantidade,
    nfi.valor_unitario,
    nfi.valor_total,
    nfi.prec_cus_cnt,
    nfi.prec_cus_rep,
    nfi.prec_cusm_prod,
    nfi.pr_cusc_prod,
    nfi.prec_cus_r,
    nfi.qcom from notafiscal_item nfi
    inner join notafiscal nf on
        nf.cod_nf = nfi.cod_nf
        and nf.cod_empresa = nfi.cod_empresa
    where nfi.cod_nf = :pnum
    and nfi.cod_empresa = :pcod_empresa
    and nfi.nitem = :pnitem
    and nfi.grupo_prod = :pgrupo_prod
    and nfi.cod_prod = :pcod_prod
    and nfi.cod_grade = :pcod_grade
     into :vcod_nf, :vnitem_nf, :vnatureza_nf, :vtipo_nf, :vdata_nf,
      :vquantidade, :vvalor_unitario, :vvalor_total,
      :vprec_cus_cnt, :vprec_cus_rep, :vprec_cusm_prod,
      :vpr_cusc_prod, :vprec_cus_r, :vqcom;

    if (trim(vnatureza_nf) <> 'E') then 
    begin
      result = 'NF DEVE SER DE ENTRADA';
      exit;
    end

    if (trim(vtipo_nf) <> 'P') then
    begin
      result = 'NF DEVE SER DE PRODUTO';
      exit;
    end

    if (vcod_nf > 0) then
    begin
      update notafiscal_item nfi set nfi.quantidade = :pquantidade,
        nfi.valor_unitario = ((:vvalor_unitario / :pquantidade) * :vquantidade),
        nfi.prec_cus_cnt = ((:vprec_cus_cnt / :pquantidade) * :vquantidade),
        nfi.prec_cus_rep = ((:vprec_cus_rep / :pquantidade) * :vquantidade),
        nfi.prec_cusm_prod = ((:vprec_cusm_prod / :pquantidade) * :vquantidade),
        nfi.pr_cusc_prod = ((:vpr_cusc_prod / :pquantidade) * :vquantidade)
      where nfi.cod_nf = :pnum
      and nfi.cod_empresa = :pcod_empresa
      and nfi.nitem = :pnitem
      and nfi.grupo_prod = :pgrupo_prod
      and nfi.cod_prod = :pcod_prod
      and nfi.cod_grade = :pcod_grade;

      select result from consultar_custo_estoque (
        'NF',
        :pgrupo_prod,
        :pcod_prod,
        :pcod_grade,
        :pcod_empresa,
        :vdata_nf,
        :vcod_nf,
        :vnitem_nf,
        0,
        0)
          into :vresult;
    end
  end

  result = 'OK';
  suspend;
end ^

ALTER PROCEDURE CORRIGIR_EST_QTDE_CUSTO_NF_PDC (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PNUM INTEGER,
PNITEM INTEGER,
PQUANTIDADE DOUBLE PRECISION,
PCUSTO_MED DOUBLE PRECISION)
RETURNS (RESULT VARCHAR(100) CHARACTER SET NONE)
AS 
declare variable VSEQID_HP integer;
declare variable VSEQID_HD integer;
declare variable VCOD_NF integer;
declare variable VNITEM_NF integer;
declare variable VNATUREZA_NF char(1);
declare variable VTIPO_NF char(1);
declare variable VDATA_NF timestamp;
declare variable VQUANTIDADE double precision;
declare variable VVALOR_UNITARIO double precision;
declare variable VVALOR_TOTAL double precision;
declare variable VPREC_CUS_CNT double precision;
declare variable VPREC_CUS_REP double precision;
declare variable VPREC_CUSM_PROD double precision;
declare variable VPR_CUSC_PROD double precision;
declare variable VPREC_CUS_R double precision;
declare variable VQCOM double precision;
declare variable VNUM_DOCTMP integer;
declare variable VTIPO_DOCTMP char(6);
declare variable VNITEMTMP integer;
declare variable VDATA_DOCTMP timestamp;
declare variable VNATUREZATMP char(1);
declare variable VCOD_NFTMP integer;
declare variable VESTOQUETMP double precision;
declare variable VESTOQUEDIARIOTMP double precision;
declare variable VEXISTE_REG integer;
declare variable VEXISTE_IND integer;
declare variable VEXISTE_GRADE integer;
declare variable VSQL varchar(1000);
declare variable VSQL2 varchar(1000);
declare variable VWHERE varchar(1000);
declare variable VGRUPO_PROD integer;
declare variable VCOD_PROD char(6);
declare variable VCOD_GRADE integer;
declare variable VRESULT varchar(10);
begin
  /* Procedure Text */
  result = 'FALHA';

  vcod_nf = 0;
  vnitem_nf = 0;
  vnatureza_nf = '';
  vtipo_nf = '';
  vquantidade = 0;
  vvalor_unitario = 0;
  vvalor_total = 0;
  vprec_cus_cnt = 0;
  vprec_cus_rep = 0;
  vprec_cusm_prod = 0;
  vpr_cusc_prod = 0;
  vprec_cus_r = 0;
  vqcom = 0;

  vnum_doctmp      = 0;
  vtipo_doctmp     = '';
  vnitemtmp        = 0;
  vdata_doctmp     = null;
  vnaturezatmp     = '';

  if ((trim(ptipo) <> 'NF') and (trim(ptipo) <> 'NFX') and (trim(ptipo) <> 'PDF')) then
  begin
    result = 'DOCUMENTO DEVE SER NF OU PRODUCAO';
    exit;
  end

  if (pquantidade <= 0) then
  begin
    result = 'QUANTIDADE INFORMADA DEVE SER MAIOR QUE ZERO';
    exit;
  end

  if (pcusto_med <= 0) then
  begin
    result = 'CUSTO MEDIO INFORMADA DEVE SER MAIOR QUE ZERO';
    exit;
  end

  if (ptipo = 'NF') then
  begin
    select nfi.cod_nf,
    nfi.nitem,
    nf.natureza_nf,
    nf.tipo_nf,
    nf.data_estoque,
    nfi.quantidade,
    nfi.valor_unitario,
    nfi.valor_total,
    nfi.prec_cus_cnt,
    nfi.prec_cus_rep,
    nfi.prec_cusm_prod,
    nfi.pr_cusc_prod,
    nfi.prec_cus_r,
    nfi.qcom from notafiscal_item nfi
    inner join notafiscal nf on
        nf.cod_nf = nfi.cod_nf
        and nf.cod_empresa = nfi.cod_empresa
    where nfi.cod_nf = :pnum
    and nfi.cod_empresa = :pcod_empresa
    and nfi.nitem = :pnitem
    and nfi.grupo_prod = :pgrupo_prod
    and nfi.cod_prod = :pcod_prod
    and nfi.cod_grade = :pcod_grade
     into :vcod_nf, :vnitem_nf, :vnatureza_nf, :vtipo_nf, :vdata_nf,
      :vquantidade, :vvalor_unitario, :vvalor_total,
      :vprec_cus_cnt, :vprec_cus_rep, :vprec_cusm_prod,
      :vpr_cusc_prod, :vprec_cus_r, :vqcom;

    if (trim(vnatureza_nf) <> 'E') then 
    begin
      result = 'NF DEVE SER DE ENTRADA';
      exit;
    end

    if (trim(vtipo_nf) <> 'P') then
    begin
      result = 'NF DEVE SER DE PRODUTO';
      exit;
    end

    if (vcod_nf > 0) then
    begin
      update notafiscal_item nfi set nfi.quantidade = :pquantidade,
        nfi.prec_cusm_prod = :pcusto_med
      where nfi.cod_nf = :pnum
      and nfi.cod_empresa = :pcod_empresa
      and nfi.nitem = :pnitem
      and nfi.grupo_prod = :pgrupo_prod
      and nfi.cod_prod = :pcod_prod
      and nfi.cod_grade = :pcod_grade;

      select result from consultar_custo_estoque (
        'NF',
        :pgrupo_prod,
        :pcod_prod,
        :pcod_grade,
        :pcod_empresa,
        :vdata_nf,
        :vcod_nf,
        :vnitem_nf,
        :pquantidade - :vquantidade,
        :pcusto_med)
          into :vresult;
    end
  end
  else if (ptipo = 'NFX') then
  begin
    select first 1
    hp.seqid,
    hp.cod_nf,
    hp.nitem,
    hp.natureza,
    hp.data,
    hp.qtde,
    hp.valor_unit,
    hp.valor_tot,
    hp.custo_med from hist_estoque_diario_prod hp
    where hp.cod_nf = :pnum
    and hp.tipor = 'NF'
    and hp.natureza = 'E'
    and hp.cod_empresa = :pcod_empresa
    and hp.nitem = :pnitem
    and hp.grupo_prod = :pgrupo_prod
    and hp.cod_prod = :pcod_prod
     into :vseqid_hp, :vcod_nf, :vnitem_nf, :vnatureza_nf, :vdata_nf,
      :vquantidade, :vvalor_unitario, :vvalor_total, :vprec_cusm_prod;

    if (coalesce(vseqid_hp, 0) <= 0) then
    begin
      select first 1
      he.seqid,
      he.cod_nf,
      he.nitem,
      he.natureza,
      he.data,
      he.qtde,
      he.valor_unit,
      he.valor_tot,
      he.custo_med from hist_estoque_diario he
      where he.cod_nf = :pnum
      and he.tipor = 'NF'
      and he.natureza = 'E'
      and he.cod_empresa = :pcod_empresa
      and he.nitem = :pnitem
      and he.grupo_prod = :pgrupo_prod
      and he.cod_prod = :pcod_prod
      into :vseqid_hd, :vcod_nf, :vnitem_nf, :vnatureza_nf, :vdata_nf,
       :vquantidade, :vvalor_unitario, :vvalor_total, :vprec_cusm_prod;
    end

    if (trim(vnatureza_nf) <> 'E') then 
    begin
      result = 'NF DEVE SER DE ENTRADA';
      exit;
    end

    if (coalesce(vcod_nf, 0) > 0) then
    begin
      if (coalesce(vseqid_hp, 0) > 0) then
      begin
        update hist_estoque_diario_prod hp set hp.qtde = :pquantidade,
          hp.valor_unit = ((:vvalor_unitario / :pquantidade) * :vquantidade),
          hp.custo_med = :pcusto_med
        where hp.cod_nf = :pnum
        and hp.cod_empresa = :pcod_empresa
        and hp.natureza = 'E'
        and hp.nitem = :pnitem
        and hp.grupo_prod = :pgrupo_prod
        and hp.cod_prod = :pcod_prod
        and hp.cod_grade = :pcod_grade;

        update hist_estoque_diario_prod hp set hp.qtde = :pquantidade,
          hp.valor_unit = ((:vvalor_unitario / :pquantidade) * :vquantidade),
          hp.custo_med = :pcusto_med
        where hp.cod_nf = :pnum
        and hp.cod_empresa = :pcod_empresa
        and hp.natureza = 'S'
        and hp.nitem = :pnitem
        and hp.grupo_prod = :pgrupo_prod
        and hp.cod_prod = :pcod_prod
        and hp.cod_grade = :pcod_grade;
      end

      if (coalesce(vseqid_hd, 0) > 0) then
      begin
        update hist_estoque_diario hd set hd.qtde = :pquantidade,
          hd.valor_unit = ((:vvalor_unitario / :pquantidade) * :vquantidade),
          hd.custo_med = :pcusto_med
        where hd.cod_nf = :pnum
        and hd.cod_empresa = :pcod_empresa
        and hd.natureza = 'E'
        and hd.nitem = :pnitem
        and hd.grupo_prod = :pgrupo_prod
        and hd.cod_prod = :pcod_prod
        and hd.cod_grade = :pcod_grade;

        update hist_estoque_diario hd set hd.qtde = :pquantidade,
          hd.valor_unit = ((:vvalor_unitario / :pquantidade) * :vquantidade),
          hd.custo_med = :pcusto_med
        where hd.cod_nf = :pnum
        and hd.cod_empresa = :pcod_empresa
        and hd.natureza = 'S'
        and hd.nitem = :pnitem
        and hd.grupo_prod = :pgrupo_prod
        and hd.cod_prod = :pcod_prod
        and hd.cod_grade = :pcod_grade;
      end

      select result from consultar_custo_estoque (
        'NFX',
        :pgrupo_prod,
        :pcod_prod,
        :pcod_grade,
        :pcod_empresa,
        :vdata_nf,
        :vcod_nf,
        :vnitem_nf,
        :pquantidade - :vquantidade,
        :pcusto_med)
          into :vresult;
    end
  end

  result = 'OK';
  suspend;
end;
 
 ^

ALTER PROCEDURE DATE_OF (DATAHORA TIMESTAMP)
RETURNS (DATA TIMESTAMP)
AS 
  declare variable Y varchar(4);
  declare variable M varchar(2);
  declare variable D varchar(2);
begin
  y = substring( (select result from strzero( extract ( YEAR  from :datahora ), 4)) from  1 for 4);
  m = substring( (select result from strzero( extract ( MONTH from :datahora ), 2)) from  1 for 2);
  d = substring( (select result from strzero( extract ( DAY   from :datahora ), 2)) from  1 for 2);
  data = cast(y ||'-'||m||'-'||d as timestamp);
  suspend;
end ^

ALTER PROCEDURE DATE_OF_MONTH (DATAHORA TIMESTAMP)
RETURNS (START_DATE TIMESTAMP,
END_DATE TIMESTAMP)
AS 
begin
  select dateadd(-extract(day from :DATAHORA) + 1 day to :DATAHORA),
         dateadd(+ 30 day to dateadd(-extract(day from :DATAHORA) + 1 day to :DATAHORA))
  from RDB$DATABASE
    into :START_DATE, :END_DATE;

  while (extract ( month from :start_date) < extract ( month from :end_date)) do
  begin
    end_date = dateadd(-1 day to :end_date);
  end
  suspend;
end ^

ALTER PROCEDURE DEC_TO_HEX (DECIMAL_VAL BIGINT)
RETURNS (HEX_VAL VARCHAR(16) CHARACTER SET NONE)
AS 
DECLARE VARIABLE REMINDER INT;
DECLARE VARIABLE DIGITS CHAR(16);
BEGIN
    -- Mapeamento dos digitos hexadecimais (0-9, A-F)
    DIGITS = '0123456789ABCDEF';
    HEX_VAL = '';

    -- Caso especial para o numero zero
    IF (DECIMAL_VAL = 0) THEN
    BEGIN
        HEX_VAL = '0';
        SUSPEND;
        EXIT;
    END

    -- Loop de divisao sucessiva por 16
    WHILE (DECIMAL_VAL > 0) DO
    BEGIN
        REMINDER = MOD(DECIMAL_VAL, 16);
        HEX_VAL = SUBSTRING(DIGITS FROM REMINDER + 1 FOR 1) || HEX_VAL;
        DECIMAL_VAL = DECIMAL_VAL / 16;
    END

    SUSPEND;
END ^

ALTER PROCEDURE DEVOLUCAO_GRUPO (PNPED INTEGER,
PTIPO_VENDA CHAR(3) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PGRUPO_PROD INTEGER)
RETURNS (TIPO CHAR(3) CHARACTER SET NONE,
NPED INTEGER,
TIPO_VENDA CHAR(3) CHARACTER SET NONE,
COD_EMPRESA INTEGER,
DATA TIMESTAMP,
VALOR_DEV DOUBLE PRECISION,
QUANT_DEV DOUBLE PRECISION,
GRUPO_PROD INTEGER)
AS 
begin
  /* Procedure Text */
  select 'DEV' as tipo,
  coalesce(dev.cod_venda, 0) nped, coalesce(dev.tipo_venda, '') tipo_venda, dev.cod_empresa, dev.data,
  dev.grupo_prod,
  sum(case when(coalesce(dev.valor_tot, 0) > 0) then coalesce(dev.valor_tot, 0) else coalesce((dev.valor * dev.quant), 0) end) valor_dev,
  count(distinct(dev.sequencia)) quant_dev from devolucao dev
  where coalesce(dev.cod_venda, 0) = :pnped
  and dev.tipo_venda = :ptipo_venda
  and dev.cod_empresa = :pcod_empresa
  and dev.grupo_prod = :pgrupo_prod
  group by 1, 2, 3, 4, 5, 6
  into :tipo, :nped, :tipo_venda, :cod_empresa, :data, :grupo_prod, :valor_dev, :quant_dev;
  suspend;
end ^

