ALTER PROCEDURE DIMINUI_ESTOQUE (VGRUPO INTEGER,
VCOD_PROD CHAR(6) CHARACTER SET NONE,
QUANT DOUBLE PRECISION,
VESTS DOUBLE PRECISION,
VESTM DOUBLE PRECISION,
VESTC DOUBLE PRECISION,
VDATA TIMESTAMP,
COD_EMPRESA INTEGER)
AS 
BEGIN
  UPDATE PRODUTOS SET EST_F = EST_F-:QUANT,ESTS = ESTS-:VESTS,
  ESTM = ESTM-:VESTM,ESTC = ESTC-:VESTC WHERE GRUPO_PROD = :VGRUPO AND 
  COD_PROD = :VCOD_PROD and cod_empresa = :cod_empresa and ativo = 1;
END ^

ALTER PROCEDURE ESTOQUEREAL (VGRUPO INTEGER,
VCODIGO CHAR(6) CHARACTER SET NONE,
VEMPRESA INTEGER)
RETURNS (ESTOQUE DOUBLE PRECISION)
AS 
declare variable vestpend double precision;
declare variable vestprod double precision;
begin
select sum(pi.quant_ped_item) from pedvenda_prod pi
inner join pedvenda p on p.nped = pi.nped and p.tipo = pi.tipo and p.cod_empresa = pi.cod_empresa
where pi.grupo_prod = :vgrupo and pi.cod_prod = :vcodigo and pi.cod_empresa = :vempresa and p.tipo <> 'ORC'
and p.data_fech is null
into:vEstPend;
if (:vEstPend is null) then
    vEstPend = 0;
select pp.est_f from produtos pp
where pp.grupo_prod = :vgrupo and pp.cod_prod = :vcodigo and pp.cod_empresa = :vempresa
into:vEstProd;
if (:vEstProd is null) then
    vEstProd = 0;
 estoque = :vEstProd - :vEstPend;
end ^

ALTER PROCEDURE EXISTE_BAIXA_REC (PNRECIBO INTEGER,
PTIPO_BAIXA VARCHAR(10) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (SEQCAD_REC INTEGER,
COD_EMPRESA INTEGER,
NRECIBO INTEGER,
VALOR_BAIXA DOUBLE PRECISION,
VALOR_RECIBO DOUBLE PRECISION,
DATA_REC TIMESTAMP,
RECANT CHAR(1) CHARACTER SET NONE,
NDOCANT INTEGER,
DATA_BAIXA TIMESTAMP,
HISTORICO_REC VARCHAR(50) CHARACTER SET NONE,
ATIVO INTEGER,
COD_US INTEGER,
TP_DOC_BAIXA CHAR(3) CHARACTER SET NONE,
TP_BAIXA CHAR(1) CHARACTER SET NONE,
LOTE_QUIT INTEGER,
COD_UNIFICADA INTEGER,
OP_CXL INTEGER)
AS 
declare variable VSQL varchar(100);
begin
  /* Procedure Text */
  if (coalesce(pnrecibo, 0) = 0) then
  begin
    suspend;
    exit;
  end

  vsql = '';
  if (coalesce(ptipo_baixa, '') = 'MANUAL') then
    vsql = ' and hist.tp_doc_baixa is null ';
  else if ((coalesce(ptipo_baixa, '') = 'REQ') or (coalesce(ptipo_baixa, '') = 'OS'))  then
    vsql = ' and hist.tp_doc_baixa = ''' || :ptipo_baixa || '';
  else if ((coalesce(ptipo_baixa, '') = 'PRE') or (coalesce(ptipo_baixa, '') = 'CC') or (coalesce(ptipo_baixa, '') = 'CH'))  then
    vsql = ' and hist.tp_doc_baixa = ''PRE'' ';

  execute statement
    ' select first 1 hist.seqcad_rec, hist.cod_empresa, hist.nrecibo, hist.valor_baixa, hist.valor_recibo, hist.data_rec, hist.recant,
      hist.ndocant, hist.data_baixa, hist.historico_rec, hist.ativo, hist.cod_us,
      hist.tp_doc_baixa, hist.tp_baixa, hist.lote_quit, hist.cod_unificada, hist.op_cxl from hist_rec hist
      where hist.nrecibo = ' || :pnrecibo || '
      and hist.cod_empresa =' || :pcod_empresa || :vsql
        into :seqcad_rec, :cod_empresa, :nrecibo, :valor_baixa, :valor_recibo, :data_rec, :recant,
             :ndocant, :data_baixa, :historico_rec, :ativo, :cod_us,
             :tp_doc_baixa, :tp_baixa, :lote_quit, :cod_unificada, :op_cxl;

  suspend;
end ^

ALTER PROCEDURE EXISTE_DEV_NF_V (PCOD_NF INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (NDEV INTEGER)
AS 
begin
  /* Procedure Text */
 select first 1 nf.cod_nf from notafiscal nf
  where nf.cod_nf = coalesce((
    select first 1 nf2.cod_nf from notafiscal nf2
    inner join notafiscal_item nfi2 on nfi2.cod_nf = nf2.cod_nf and nfi2.cod_empresa = nf2.cod_empresa
    where nfi2.cod_nf_dev = :pcod_nf and nf2.cod_empresa = :pcod_empresa), 0)
  and nf.cod_empresa = :pcod_empresa
  and nf.tipo_nf = 'V' and nf.natureza_nf = 'E' and nf.devolucao = 'SIM'
  and nf.status = 'Fechada' into :ndev;
  ndev = coalesce(ndev, 0);
  suspend;
end;
 
 ^

ALTER PROCEDURE EXISTE_FORMAS (PNDOC INTEGER,
PTIPODOC VARCHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (NDOC INTEGER,
TIPODOC VARCHAR(6) CHARACTER SET NONE,
DATA_MOV TIMESTAMP,
VALOR_TOTAL DOUBLE PRECISION,
ENTRADA DOUBLE PRECISION,
CREDIARIO CHAR(1) CHARACTER SET NONE,
VALOR_VALE DOUBLE PRECISION,
JUROS DOUBLE PRECISION,
PRCSS CHAR(1) CHARACTER SET NONE)
AS 
declare variable VSQL varchar(600);
declare variable VCONFFORMPAGAMENTO varchar(3);
declare variable VNF integer;
declare variable VSERIE integer;
declare variable VTEMP varchar(400);
begin
  VSQL = '';
  VTEMP = '';
  /* Procedure Text */
  select conf_formpagamento from empresa where cod_empresa = 1 into :vconfformpagamento;
  if ((trim(coalesce(vconfformpagamento, 'PED')) = 'PED') or (trim(coalesce(ptipodoc, '')) = 'PRE')) then
  begin
    select first 1 fp.nrequisicao, fp.tpdocs, fp.data_mov,

    coalesce((select sum(coalesce(fp2.valordoc, 0)) from formpagamento fp2
    where fp2.nrequisicao = fp.nrequisicao and fp2.tpdocs = fp.tpdocs and fp2.cod_empresa = fp.cod_empresa), 0) valor_total,

    coalesce((select sum(coalesce(fp3.valordoc, 0)) from formpagamento fp3
    inner join controles ctr3 on fp3.cod_controle = ctr3.codigo_ctrl and fp3.cod_empresa = ctr3.codigo_emp and ctr3.docs = 'N'
    where fp3.nrequisicao = fp.nrequisicao and fp3.tpdocs = fp.tpdocs and fp3.cod_empresa = fp.cod_empresa), 0) entrada,

    coalesce((case when (coalesce((select coalesce(count(*), 0) from formpagamento fp4
    inner join controles ctr4 on ctr4.codigo_ctrl = fp4.cod_controle and ctr4.codigo_emp = fp4.cod_empresa
    where fp4.nrequisicao = fp.nrequisicao and fp4.tpdocs = fp.tpdocs and fp4.cod_empresa = fp.cod_empresa
    and trim(ctr4.fp_regra_fidelidade) = 'CR'), 0) > 0) then 'S' else 'N' end), 'N') crediario,

    coalesce((select sum(coalesce(fp5.valordoc, 0)) from formpagamento fp5
    where fp5.nrequisicao = fp.nrequisicao and fp5.tpdocs = fp.tpdocs and fp5.cod_empresa = fp.cod_empresa
    and fp5.ativo = 1 and fp5.prg_fid = 'S'), 0) valor_vale,

    coalesce((case when coalesce((select coalesce(count(*), 0) from formpagamento fp6
    where fp6.nrequisicao = fp.nrequisicao and fp6.tpdocs = fp.tpdocs and fp6.cod_empresa = fp.cod_empresa
    and fp6.prcss = 'S'), 0) > 0 then 'S' else 'N' end), 'N') prcss,

    (coalesce((select sum(coalesce(fp7.vl_juros, 0)) from formpagamento fp7
    where fp7.nrequisicao = fp.nrequisicao and fp7.tpdocs = fp.tpdocs and fp7.cod_empresa = fp.cod_empresa), 0) +
    coalesce((select sum(coalesce(fp7.vl_juros, 0)) from formpagamento fp7
    inner join hist_rec h on h.ndocant = fp7.nrequisicao and h.tp_doc_baixa = fp7.tpdocs and h.cod_empresa = fp7.cod_empresa
    where h.ndocant = fp.nrequisicao and h.tp_doc_baixa = fp.tpdocs and h.cod_empresa = fp.cod_empresa), 0)) vl_juros

       from formpagamento fp
    where fp.nrequisicao = :pndoc and fp.tpdocs = :ptipodoc and fp.cod_empresa = :pcod_empresa and fp.ativo = 1
    into :ndoc, :tipodoc, :data_mov, :valor_total, :entrada, :crediario, :valor_vale, :prcss, :juros;
  end
  else
  begin
    if (trim(ptipodoc) = 'MOT') then
    begin
      VSQL = ' select cf.num_nota_v as n_nf, cf.sub_serie as serie from com_fat cf
        where cf.n_comando = '||:pndoc||' and cf.cod_empresa = '||:pcod_empresa;
    end
    else
    begin
      VSQL = ' select pp.n_nf, pp.serie from pedvenda_prod pp
        where pp.nped = '||:pndoc||' and pp.tipo = '''||:ptipodoc||'''
        and pp.cod_empresa = '||:pcod_empresa||' and pp.ativo = 1
        and ((pp.status is null) or (pp.status <> ''CANCELADO'')) and pp.n_nf > 0 and pp.serie <> ''''
        union
        select ps.n_nf, ps.serie from pedvenda_serv ps
        where ps.nped = '||:pndoc||' and ps.tipo = '''||:ptipodoc||'''
        and ps.cod_empresa = '||:pcod_empresa||' and ps.ativo = 1
        and ((ps.status is null) or (ps.status <> ''CANCELADO'')) and ps.n_nf > 0 and ps.serie <> ''''
        group by 1,2 ';
    end

    for execute statement VSQL into :vnf, :vserie do
    begin
       if (trim(VTEMP) = '') then
          VTEMP = ' ((fp.num_nota = '||:vnf||' and fp.sub_serie = '||:vserie||')';
       else
          VTEMP = VTEMP || ' or (fp.num_nota = '||:vnf||
            ' and fp.sub_serie = '||:vserie||')';
    end
    if (trim(coalesce(VTEMP, '')) <> '') then
      VTEMP = VTEMP || ')';

    if (trim(coalesce(VTEMP, '')) <> '') then
    begin
        execute statement
        ' select first 1 fp.nrequisicao, fp.tpdocs, fp.data_mov,
          coalesce((select sum(coalesce(fp2.valordoc, 0)) from formpagamento fp2
          where fp2.nrequisicao = fp.nrequisicao and fp2.tpdocs = fp.tpdocs and fp2.cod_empresa = fp.cod_empresa), 0) valor_total,
    
          coalesce((select sum(coalesce(fp3.valordoc, 0)) from formpagamento fp3
          inner join controles ctr3 on fp3.cod_controle = ctr3.codigo_ctrl and fp3.cod_empresa = ctr3.codigo_emp and ctr3.docs = ''N''
          where fp3.nrequisicao = fp.nrequisicao and fp3.tpdocs = fp.tpdocs and fp3.cod_empresa = fp.cod_empresa), 0) entrada,
    
          coalesce((case when (coalesce((select coalesce(count(*), 0) from formpagamento fp4
          inner join controles ctr4 on ctr4.codigo_ctrl = fp4.cod_controle and ctr4.codigo_emp = fp4.cod_empresa
          where fp4.nrequisicao = fp.nrequisicao and fp4.tpdocs = fp.tpdocs and fp4.cod_empresa = fp.cod_empresa
          and trim(ctr4.fp_regra_fidelidade) = ''CR''), 0) > 0) then ''S'' else ''N'' end), ''N'') crediario,
    
          coalesce((select sum(coalesce(fp5.valordoc, 0)) from formpagamento fp5
          where fp5.nrequisicao = fp.nrequisicao and fp5.tpdocs = fp.tpdocs and fp5.cod_empresa = fp.cod_empresa
          and fp5.ativo = 1 and fp5.prg_fid = ''S''), 0) valor_vale,

          coalesce((case when coalesce((select coalesce(count(*), 0) from formpagamento fp6
          where fp6.nrequisicao = fp.nrequisicao and fp6.tpdocs = fp.tpdocs and fp6.cod_empresa = fp.cod_empresa
          and fp6.prcss = ''S''), 0) > 0 then ''S'' else ''N'' end), ''N'') prcss,

          (coalesce((select sum(coalesce(fp7.vl_juros, 0)) from formpagamento fp7
          where fp7.nrequisicao = fp.nrequisicao and fp7.tpdocs = fp.tpdocs and fp7.cod_empresa = fp.cod_empresa), 0) +
          coalesce((select sum(coalesce(fp7.vl_juros, 0)) from formpagamento fp7
          inner join hist_rec h on h.ndocant = fp7.nrequisicao and h.tp_doc_baixa = fp7.tpdocs and h.cod_empresa = fp7.cod_empresa
          where h.ndocant = fp.nrequisicao and h.tp_doc_baixa = fp.tpdocs and h.cod_empresa = fp.cod_empresa), 0)) vl_juros


             from formpagamento fp
          where '||:VTEMP||' and fp.tpdocs <> ''LCS'' and fp.cod_empresa = '||:pcod_empresa||'
          and fp.ativo = 1 '
          into :ndoc, :tipodoc, :data_mov, :valor_total, :entrada, :crediario, :valor_vale, :prcss, :juros;
      end
  end
  suspend;
end;
 
 ^

ALTER PROCEDURE EXISTE_LOCACAO (PNPED INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (RESULT CHAR(1) CHARACTER SET NONE)
AS 
declare variable VVALUE1_B blob sub_type 1 segment size 4096;
declare variable VNLINHA integer;
declare variable VLINHA varchar(100);
declare variable VEXISTE integer;
declare variable VCONF_SERVICO integer;
declare variable VEXIBIR_SERVICO integer;
declare variable VORIGEM_SERVICO varchar(1000);
declare variable VEXIBSERV varchar(10);
declare variable VORIGSERV varchar(1000);
declare variable VEXIBTODOS varchar(1000);
declare variable VTEMP varchar(1000);
declare variable VSTIPO char(10);
begin
  /* Procedure Text */
  select config_sistema.value1_b from config_sistema
  where config_sistema.chave = 'ped_vnd_impressao_recibo_locacao'
  and config_sistema.cod_empresa = :pcod_empresa
    into :vvalue1_b;

  vconf_servico   = 0;
  vexibir_servico = 0;

  result          = 'N';

  vexibServ       = 'N';
  vorigServ       = '';
  vexibtodos      = 'N';
  for select util_split_blob_to_row.mnumber, util_split_blob_to_row.retstring
      from util_split_blob_to_row (:vvalue1_b)
    into :vnlinha, :vlinha do
  begin
    if ((coalesce(vconf_servico, 0) > 0) and (coalesce(vexibir_servico, 0) = 0)) then
    begin
      select result from pos ('Exibir', :vlinha)
        into :vexibir_servico;

      if (coalesce(vexibir_servico, 0) > 0) then
      begin
        vtemp = replace(vlinha, 'Exibir', '');
        vtemp = replace(vtemp, '=', '');
        vtemp = replace(vtemp, ascii_char(13), '');

        select case when(result > 0) then 'S' else 'N' end from pos ('S', :vtemp)
          into :vexibserv;
      end
    end

    if ((coalesce(vconf_servico, 0) > 0) and (coalesce(vexibir_servico, 0) > 0) and (coalesce(vorigem_servico, 0) = 0)) then
    begin
      select result from pos ('Origem', :vlinha)
        into :vorigem_servico;

      if (coalesce(vorigem_servico, 0) > 0) then
      begin
        vtemp = replace(vlinha, 'Origem', '');
        vtemp = replace(vtemp, '=', '');
        vtemp = replace(vtemp, ascii_char(13), '');

        vorigServ = trim(coalesce(vtemp, ''));
      end

      if (coalesce(vorigem_servico, 0) > 0) then
      begin
        select case when (result > 0) then 'S' else 'N' end from pos ('TODOS', :vlinha)
          into :vexibtodos;
      end
    end

    if (coalesce(vconf_servico, 0) = 0) then
    begin
      select result from pos ('[Conf_Servico]', :vlinha)
        into :vconf_servico;
    end

    if ((coalesce(vconf_servico, 0) > 0) and (coalesce(vexibir_servico, 0) > 0) and (coalesce(vorigem_servico, 0) > 0)) then
      break;
  end

  if ((coalesce(vexibserv, 'N')) <> 'S') then
  begin
    result = 'N';
    suspend;
    exit;
  end

  if ((trim(coalesce(vexibserv, 'N')) = 'S') and (trim(coalesce(vorigServ, '')) <> '') and (trim(coalesce(vexibtodos, 'N')) = 'S')) then
    vexiste = 1;
  else if ((trim(coalesce(vexibserv, 'N')) = 'S') and (trim(coalesce(vorigServ, '')) <> '')) then
  begin
    for select distinct tipo_servico.stipo from pedvenda
        inner join pedvenda_serv on pedvenda.nped = pedvenda_serv.nped and pedvenda.tipo = pedvenda_serv.tipo and pedvenda.cod_empresa = pedvenda_serv.cod_empresa
        inner join tipo_servico on tipo_servico.cod_servico = pedvenda_serv.cod_servico
        where pedvenda.nped = :pnped
        and pedvenda.tipo = :ptipo
        and pedvenda.cod_empresa = :pcod_empresa
        and (pedvenda_serv.status <> 'CANCELADO' or pedvenda_serv.status is null)
          into :vstipo do
    begin
      select case when (p_split.osplit is not null) then 1 else 0 end from p_split (:vorigServ, '|')
      where p_split.osplit = :vstipo
        into :vexiste;

      if (coalesce(vexiste, 0) > 0) then
        break;
    end
  end

  if (coalesce(vexiste, 0) > 0) then
    result = 'S';
  suspend;
end ^

ALTER PROCEDURE EXISTE_PAGAMENTOS (PLOTE INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (CODIGO INTEGER,
TIPOLANC VARCHAR(10) CHARACTER SET NONE,
COD_EMPRESA INTEGER,
COD_EMP_MULT INTEGER,
LOTE INTEGER,
NATUREZA CHAR(1) CHARACTER SET NONE,
CODIGO_CTRL INTEGER,
N_CONTA_PLC DOUBLE PRECISION,
NCHEQUE VARCHAR(20) CHARACTER SET NONE,
NDOC VARCHAR(20) CHARACTER SET NONE,
VALOR DOUBLE PRECISION,
DATA TIMESTAMP,
DATAVENCIMENTO TIMESTAMP,
DTREFERENCIA TIMESTAMP,
DATAQUITACAO TIMESTAMP)
AS 
begin
  /* Procedure Text */
  if (coalesce(plote, 0) <= 0) then
  begin
    suspend;
    exit;
  end

  select first 1 * from (
    select lanc.cod_lanc as codigo, 'LANC' tipolanc,
    lanc.codigo_emp as cod_empresa, lanc.cod_emp_mult, lanc.lote as lote,
    lanc.tipo_l as natureza, lanc.codigo_ctrl, lanc.n_conta_plc,
    lanc.n_cheq_l as ncheque, lanc.ndoc_l as ndoc, lanc.valor_l, lanc.data, null datavencimento,
    lanc.dtreferencia, lanc.datq_l as dataquitacao from lancamentos lanc
    inner join controles ctrl on ctrl.codigo_ctrl = lanc.codigo_ctrl and ctrl.codigo_emp = lanc.codigo_emp
    where ctrl.docs = 'N'
    union all
    select ch.codigo_ch as codigo, 'CH' tipolanc,
    coalesce(ch.cod_emp_lote, ch.codigo_emp) as cod_empresa, ch.cod_emp_mult, ch.lote as lote,
    'E' as natureza, ch.codigo_ctrl, ch.n_conta_plc,
    ch.n_ch as ncheque, ch.n_doc_v as ndoc, ch.valor_ch, ch.data_rec as data, ch.data_venc as datavencimento,
    ch.data_rec as dtreferencia, ch.datq_ch as dataquitacao from controle_cheque ch
    union all
    select cc.cod_cred as codigo, 'CC' tipolanc,
    coalesce(cc.cod_emp_lote, cc.codigo_emp) as cod_empresa, cc.cod_emp_mult, cc.lote as lote,
    'E' as natureza, cc.codigo_ctrl, cc.n_conta_plc,
    null ncheque, cc.n_doc_c as ndoc, cc.valor_c, cc.data_rec_c as data, cc.data_venc_c as datavencimento,
    cc.data_rec_c as dtreferencia, cc.datq_c as dataquitacao from controle_creditos cc
    union all
    select bc.cod_cred as codigo, 'CC' tipolanc,
    coalesce(bc.cod_emp_lote, bc.codigo_emp) as cod_empresa, bc.cod_emp_mult, bc.lote as lote,
    'E' as natureza, bc.codigo_ctrl, cc.n_conta_plc,
    null ncheque,bc.n_doc_c, bc.valor_quitado, bc.data_rec_c as data, bc.data_venc_c as datavencimento,
    bc.data_rec_c as dtreferencia, bc.datq_c as dataquitacao from baixa_creditos bc
    inner join controle_creditos cc on cc.cod_cred = bc.cod_cred and cc.codigo_emp = bc.codigo_emp
    where bc.tip_baixa = 'P'
  ) pag
  where pag.lote = :plote
  and pag.cod_empresa = :pcod_empresa
    into :codigo, :tipolanc,
        :cod_empresa, :cod_emp_mult, :lote,
        :natureza, :codigo_ctrl, :n_conta_plc,
        :ncheque, :ndoc, :valor, :data, :datavencimento, :dtreferencia, :dataquitacao;
  suspend;
end;
 
 ^

ALTER PROCEDURE EXISTE_PERMUTA (PLOTE INTEGER,
PTIPOLOTE VARCHAR(10) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (RESULT INTEGER)
AS 
begin
  /* Procedure Text */
  result = 0;

  if (coalesce(plote, 0) = 0) then
  begin
    result = coalesce(result, 0);
    suspend;
    exit;
  end

  if ((coalesce(ptipolote, '') = 'CH') or (coalesce(ptipolote, '') = 'CC') or (coalesce(ptipolote, '') = 'BC')) then
  begin
    select count(*) from contas_a_pagar cp
    where cp.lote = :plote
    and cp.codigo_emp = :pcod_empresa
    and cp.datq_ctp is not null
      into :result;

    if (coalesce(result, 0) > 0) then
    begin
     result = coalesce(result, 0);
     suspend;
     exit;
    end
  end
  else
  begin
    select count(*) from controle_cheque ch
    where ch.lote = :plote
    and ch.codigo_emp = :pcod_empresa
    and ch.datq_ch is not null
      into :result;

    if (coalesce(result, 0) > 0) then
    begin
      result = coalesce(result, 0);
      suspend;
      exit;
    end

    select count(*) from controle_creditos cc
    where cc.lote = :plote
    and cc.codigo_emp = :pcod_empresa
    and cc.datq_c is not null
      into :result;

    if (coalesce(result, 0) > 0) then
    begin
      result = coalesce(result, 0);
      suspend;
      exit;
    end

    select count(*) from baixa_creditos bc
    where bc.lote = :plote
    and bc.codigo_emp = :pcod_empresa
    and bc.tip_baixa = 'P'
    and bc.datq_c is not null
      into :result;

    if (coalesce(result, 0) > 0) then
    begin
      result = coalesce(result, 0);
      suspend;
      exit;
    end

    suspend;
  end
end ^

ALTER PROCEDURE EXISTE_RECEBIMENTOS (PLOTE INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (CODIGO INTEGER,
TIPOLANC VARCHAR(10) CHARACTER SET NONE,
COD_EMPRESA INTEGER,
COD_EMP_MULT INTEGER,
LOTE INTEGER,
NATUREZA CHAR(1) CHARACTER SET NONE,
CODIGO_CTRL INTEGER,
N_CONTA_PLC DOUBLE PRECISION,
NCHEQUE VARCHAR(20) CHARACTER SET NONE,
NDOC VARCHAR(20) CHARACTER SET NONE,
VALOR DOUBLE PRECISION,
DATA TIMESTAMP,
DATAVENCIMENTO TIMESTAMP,
DTREFERENCIA TIMESTAMP,
DATAQUITACAO TIMESTAMP)
AS 
begin
  /* Procedure Text */
  if (coalesce(plote, 0) <= 0) then
  begin
    suspend;
    exit;
  end

  select first 1 * from (
    select lanc.cod_lanc as codigo, 'LANC' tipolanc,
    lanc.codigo_emp as cod_empresa, lanc.cod_emp_mult, lanc.lote_ent as lote,
    lanc.tipo_l as natureza, lanc.codigo_ctrl, lanc.n_conta_plc,
    lanc.n_cheq_l as ncheque, lanc.ndoc_l as ndoc, lanc.valor_l, lanc.data, null datavencimento,
    lanc.dtreferencia, lanc.datq_l as dataquitacao from lancamentos lanc
    where lanc.tipo_l = 'E'
    union all
    select ch.codigo_ch as codigo, 'CH' tipolanc,
    ch.codigo_emp as cod_empresa, ch.cod_emp_mult, ch.lote_ent as lote,
    'E' as natureza, ch.codigo_ctrl, ch.n_conta_plc,
    ch.n_ch as ncheque, ch.n_doc_v as ndoc, ch.valor_ch, ch.data_rec as data, ch.data_venc as datavencimento,
    ch.data_rec as dtreferencia, ch.datq_ch as dataquitacao from controle_cheque ch
    union all
    select cc.cod_cred as codigo, 'CC' tipolanc,
    cc.codigo_emp as cod_empresa, cc.cod_emp_mult, cc.lote_ent as lote,
    'E' as natureza, cc.codigo_ctrl, cc.n_conta_plc,
    null ncheque, cc.n_doc_c as ndoc, cc.valor_c, cc.data_rec_c as data, cc.data_venc_c as datavencimento,
    cc.data_rec_c as dtreferencia, cc.datq_c as dataquitacao from controle_creditos cc
    union all
    select bc.cod_cred as codigo, 'CC' tipolanc,
    bc.codigo_emp as cod_empresa, bc.cod_emp_mult, bc.lote_ent as lote,
    'E' as natureza, bc.codigo_ctrl, cc.n_conta_plc,
    null ncheque,bc.n_doc_c, bc.valor_quitado, bc.data_rec_c as data, bc.data_venc_c as datavencimento,
    bc.data_rec_c as dtreferencia, bc.datq_c as dataquitacao from baixa_creditos bc
    inner join controle_creditos cc on cc.cod_cred = bc.cod_cred and cc.codigo_emp = bc.codigo_emp
    where bc.tip_baixa = 'P'
  ) rec
  where rec.lote = :plote
  and rec.cod_empresa = :pcod_empresa
    into :codigo, :tipolanc,
        :cod_empresa, :cod_emp_mult, :lote,
        :natureza, :codigo_ctrl, :n_conta_plc,
        :ncheque, :ndoc, :valor, :data, :datavencimento, :dtreferencia, :dataquitacao;
  suspend;
end;
 
 ^

ALTER PROCEDURE EXISTE_RECIBO (PLOTE INTEGER,
PTIPOLOTE VARCHAR(10) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (RESULT INTEGER)
AS 
begin
  /* Procedure Text */
  result = 0;

  if (coalesce(plote, 0) = 0) then
  begin
    result = coalesce(result, 0);
    suspend;
    exit;
  end

  if ((coalesce(ptipolote, '') = 'CH') or (coalesce(ptipolote, '') = 'CC') or (coalesce(ptipolote, '') = 'BC')) then
  begin
    select count(*) from hist_rec hist
    where hist.lote_quit = :plote
    and hist.cod_empresa = :pcod_empresa
      into :result;
  end

  suspend;
end ^

ALTER PROCEDURE FLOATTOSTR (VALOR DOUBLE PRECISION,
CDECIMAL SMALLINT = 2)
RETURNS (RESULTADO VARCHAR(64) CHARACTER SET NONE)
AS 
begin
  resultado = '' || round(coalesce(valor, 0), cdecimal);

  while (substring(resultado from char_length(resultado) for 1) = '0') do
    resultado = substring(resultado from 1 for char_length(resultado) - 1);

  if (substring(resultado from char_length(resultado) for 1) = '.') then
    resultado = substring(resultado from 1 for char_length(resultado) - 1);

  resultado = replace(resultado, '.', ',');

  suspend;
end ^

ALTER PROCEDURE FORMAS_DET (PNDOC INTEGER,
PTIPODOC VARCHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (SEQFORM INTEGER,
COD_EMPRESA INTEGER,
NDOC VARCHAR(20) CHARACTER SET NONE,
DATA_MOV TIMESTAMP,
DATA_VENC TIMESTAMP,
VALORDOC DOUBLE PRECISION,
COD_CONTROLE INTEGER,
NOME_CTRL VARCHAR(35) CHARACTER SET NONE,
N_CONTA_PLC DOUBLE PRECISION,
DOCS CHAR(2) CHARACTER SET NONE,
NPARCELA INTEGER,
SECAO INTEGER,
REC_TIPVEND CHAR(3) CHARACTER SET NONE,
REC_NUMVEND INTEGER,
RECIBO CHAR(1) CHARACTER SET NONE,
COD_CLIENTE INTEGER,
HISTORICO VARCHAR(100) CHARACTER SET NONE,
PRG_FID CHAR(1) CHARACTER SET NONE,
QTDE_REG INTEGER)
AS 
declare variable VSQL varchar(600);
declare variable VCONFFORMPAGAMENTO varchar(3);
declare variable VNF integer;
declare variable VSERIE integer;
declare variable VTEMP varchar(400);
declare variable VTEMP2 varchar(400);
begin
  VSQL = '';
  VTEMP = '';
  VTEMP2 = '';
  /* Procedure Text */
  select conf_formpagamento from empresa where cod_empresa = 1 into :vconfformpagamento;
  if ((trim(coalesce(vconfformpagamento, '')) = 'PED') or (trim(coalesce(ptipodoc, '')) = 'PRE')) then
  begin
    for select fp.seqform, fp.cod_empresa, fp.ndoc, fp.data_mov, fp.data_venc,
    fp.valordoc, fp.cod_controle, ctr.nome_ctrl, fp.n_conta_plc, ctr.docs,
    fp.nparcela, fp.secao, fp.rec_tipvend, fp.rec_numvend, fp.recibo, fp.cod_cliente, fp.historico, fp.prg_fid,
        coalesce((select count(*) from formpagamento fp2
        where fp2.nrequisicao = fp.nrequisicao and fp2.tpdocs = fp.tpdocs and fp2.cod_empresa = fp.cod_empresa), 0)
    from formpagamento fp
    inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
    where fp.nrequisicao = :pndoc and fp.tpdocs = :ptipodoc and fp.cod_empresa = :pcod_empresa
    and fp.ativo = 1
    into :seqform, :cod_empresa, :ndoc, :data_mov, :data_venc, :valordoc, :cod_controle, :nome_ctrl, :n_conta_plc, :docs,
      :nparcela, :secao, :rec_tipvend, :rec_numvend, :recibo, :cod_cliente, :historico, :prg_fid, :qtde_reg do
      suspend;
  end
  else
  begin
    if (trim(ptipodoc) = 'MOT') then
    begin
      VSQL = ' select cf.num_nota_v as n_nf, cf.sub_serie as serie from com_fat cf
        where cf.n_comando = '||:pndoc||' and cf.cod_empresa = '||:pcod_empresa;
    end
    else
    begin
      VSQL = ' select pp.n_nf, pp.serie from pedvenda_prod pp
        where pp.nped = '||:pndoc||' and pp.tipo = '''||:ptipodoc||'''
        and pp.cod_empresa = '||:pcod_empresa||' and pp.ativo = 1
        and ((pp.status is null) or (pp.status <> ''CANCELADO'')) and pp.n_nf > 0 and pp.serie <> ''''
        union
        select ps.n_nf, ps.serie from pedvenda_serv ps
        where ps.nped = '||:pndoc||' and ps.tipo = '''||:ptipodoc||'''
        and ps.cod_empresa = '||:pcod_empresa||' and ps.ativo = 1
        and ((ps.status is null) or (ps.status <> ''CANCELADO'')) and ps.n_nf > 0 and ps.serie <> ''''
        group by 1,2 ';
    end

    for execute statement VSQL into :vnf, :vserie do
    begin
       if (trim(VTEMP) = '') then
       begin
          VTEMP = ' ((fp.num_nota = '||:vnf||' and fp.sub_serie = '||:vserie||')';
          VTEMP2 = ' ((fp2.num_nota = '||:vnf||' and fp2.sub_serie = '||:vserie||')';
       end
       else
       begin
          VTEMP = VTEMP || ' or (fp.num_nota = '||:vnf||' and fp.sub_serie = '||:vserie||')';
          VTEMP2 = VTEMP2 || ' or (fp2.num_nota = '||:vnf||' and fp2.sub_serie = '||:vserie||')';
       end
    end
    if (trim(coalesce(VTEMP, '')) <> '') then
    begin
      VTEMP = VTEMP || ')';
      VTEMP2 = VTEMP2 || ')';
    end

    if (trim(coalesce(VTEMP, '')) <> '') then
    begin
        for execute statement
        ' select fp.seqform, fp.cod_empresa, fp.ndoc, fp.data_mov, fp.data_venc,
          fp.valordoc, fp.cod_controle, ctr.nome_ctrl, fp.n_conta_plc, ctr.docs,
          fp.nparcela, fp.secao, fp.rec_tipvend, fp.rec_numvend, fp.recibo, fp.cod_cliente, fp.historico, fp.prg_fid,
             coalesce((select count(*) from formpagamento fp2
             where '||:VTEMP2||' and fp2.tpdocs <> ''LCS'' and fp2.cod_empresa = '||:pcod_empresa||'
             and fp2.ativo = 1), 0)
          from formpagamento fp
          inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
          where '||:VTEMP||' and fp.tpdocs <> ''LCS'' and fp.cod_empresa = '||:pcod_empresa||'
          and fp.ativo = 1 '
          into :seqform, :cod_empresa, :ndoc, :data_mov, :data_venc, :valordoc, :cod_controle, :nome_ctrl, :n_conta_plc, :docs,
          :nparcela, :secao, :rec_tipvend, :rec_numvend, :recibo, :cod_cliente, :historico, :prg_fid, :qtde_reg do
            suspend;
      end
  end
end ^

ALTER PROCEDURE FORMAS_PROG_FID_DET (PDTINI TIMESTAMP,
PDTFIM TIMESTAMP,
PCOD_CLIENTE INTEGER,
PCOD_EMPRESA INTEGER,
PREGRA VARCHAR(60) CHARACTER SET NONE,
PNDOC INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PSIMULACAO CHAR(1) CHARACTER SET NONE)
RETURNS (NREQUISICAO INTEGER,
TPDOCS VARCHAR(3) CHARACTER SET NONE,
DATA_FECH TIMESTAMP,
COD_EMPRESA INTEGER,
VALORENTRADA DOUBLE PRECISION,
VALORTOTAL DOUBLE PRECISION,
DEV DOUBLE PRECISION,
CRED CHAR(1) CHARACTER SET NONE,
FP_REGRA_FIDELIDADE VARCHAR(20) CHARACTER SET NONE,
PERC_DIA_REAL DOUBLE PRECISION,
PONTOS DOUBLE PRECISION)
AS 
declare variable VTEMP varchar(100);
declare variable VTEMP2 varchar(100);
declare variable VTEMP3 varchar(100);
declare variable VTEMP_REQOS varchar(100);
declare variable VTEMP_MOT varchar(100);
declare variable VPERC_ENT double precision;
begin
  VTEMP = '';
  VTEMP2 = '';
  VTEMP3 = '';
  VTEMP_REQOS = '';
  VTEMP_MOT = '';

  if (COALESCE(PNDOC, 0) > 0) then
  begin
    VTEMP = ' and pd.nped = '||:pndoc||' and pd.tipo = '''||:ptipo||''' ';
    VTEMP2 = ' and cf.n_comando = '||:pndoc||' ';
  end
  else
  begin
    VTEMP = ' and pd.data_fech >= '''||:pdtini||''' and pd.data_fech <= '''||:pdtfim||''' ';
    VTEMP2 = ' and cf.data_fech >= '''||:pdtini||''' and cf.data_fech <= '''||:pdtfim||''' ';
  end

  if (COALESCE(psimulacao,  'N') = 'S') then
  begin
    VTEMP3 = ' and (select ndev from existe_dev_nf_v(cf.cod_nf, cf.cod_empresa)) = 0 ';
    VTEMP_REQOS  = ' and coalesce(tv.venda, ''N'') = ''S'' and coalesce(tv.gerar_pontos, ''N'') = ''S'' ';
    VTEMP_MOT = ' and coalesce(tv.venda, ''N'') = ''S'' and coalesce(tv.gerar_pontos, ''N'') = ''S'' ';
  end
  else
  begin
    VTEMP_REQOS  = ' and coalesce(pd.tp_venda, tv.venda) = ''S'' and coalesce(pd.tp_gerar_pontos, tv.gerar_pontos) = ''S'' ';
    VTEMP_MOT = ' and coalesce(cf.tp_venda, tv.venda) = ''S'' and coalesce(cf.tp_gerar_pontos, tv.gerar_pontos) = ''S'' ';
  end

  for execute statement    
  ' select pd.nped, pd.tipo, pd.cod_empresa, pd.data_fech,
    coalesce((select coalesce(fp3.entrada, 0) from existe_formas(pd.nped, pd.tipo, pd.cod_empresa) fp3), 0) entrada,
    coalesce((select coalesce(fp2.valor_total, 0) from existe_formas(pd.nped, pd.tipo, pd.cod_empresa) fp2), 0) valor_total,
    coalesce((select coalesce(fp1.crediario, ''N'') from existe_formas
      (pd.nped, pd.tipo, pd.cod_empresa) fp1), ''N'') crediario,
    coalesce((select coalesce(dp.valor_dev, 0) from devolucao_nped (pd.nped, pd.tipo, pd.cod_empresa) dp), 0) dev from pedvenda pd
    inner join clientes cl on cl.cod_cliente = pd.cod_cliente and cl.cod_empresa = pd.cod_empresa
    left join tipo_faturamento tf on tf.codigo_faturamento = cl.codigo_faturamento and tf.ativo = 1
    inner join tipo_vendas tv on pd.tipo = tv.tipo and pd.tipv = tv.sigla
        '||VTEMP_REQOS||'
    where trim(pd.tipo) = ''REQ'' and coalesce(pd.status_ped, '''') = ''FECHADA''
    '||VTEMP||' and pd.cod_empresa = '||:pcod_empresa||'
    and (coalesce(pd.valor_total, 0) >
        coalesce((select coalesce(abs(dp.valor_dev), 0) from devolucao_nped (pd.nped, pd.tipo, pd.cod_empresa) dp), 0))
    and (coalesce(pd.valor_total, 0) >
        coalesce((select coalesce(abs(vl.valor_vale), 0) from vale_doc_prg (pd.nped, pd.tipo, pd.cod_empresa) vl), 0))
    and coalesce(cl.cl_gerar_pontos, ''S'') <> ''N''
    and coalesce(tf.status_f, '''') <> ''BARRADO''
    and pd.cod_cliente <> '||:pcod_cliente||'
    
    union

    select pd.nped, pd.tipo, pd.cod_empresa, pd.data_fech,
    coalesce((select coalesce(fp3.entrada, 0) from existe_formas(pd.nped, pd.tipo, pd.cod_empresa) fp3), 0) entrada,
    coalesce((select coalesce(fp2.valor_total, 0) from existe_formas(pd.nped, pd.tipo, pd.cod_empresa) fp2), 0) valor_total,
    coalesce((select coalesce(fp1.crediario, ''N'') from existe_formas
      (pd.nped, pd.tipo, pd.cod_empresa) fp1), ''N'') crediario,
     coalesce((select coalesce(dp.valor_dev, 0) from devolucao_nped (pd.nped, pd.tipo, pd.cod_empresa) dp), 0) dev from pedvenda pd
    inner join clientes cl on cl.cod_cliente = pd.cod_cliente and cl.cod_empresa = pd.cod_empresa
    left join tipo_faturamento tf on tf.codigo_faturamento = cl.codigo_faturamento and tf.ativo = 1
    inner join tipo_vendas tv on pd.tipo = tv.tipo and pd.tipo_os = tv.tipo_os
        '||VTEMP_REQOS||'
    where trim(pd.tipo) = ''OS'' and coalesce(pd.status_ped, '''') = ''FECHADA''
    '||VTEMP||' and pd.cod_empresa = '||:pcod_empresa||'
    and coalesce(pd.cl_gerar_pontos, coalesce(cl.cl_gerar_pontos, ''S'')) <> ''N''
    and (coalesce(pd.valor_total, 0) >
        coalesce((select coalesce(abs(dp.valor_dev), 0) from devolucao_nped (pd.nped, pd.tipo, pd.cod_empresa) dp), 0))
    and (coalesce(pd.valor_total, 0) >
        coalesce((select coalesce(abs(vl.valor_vale), 0) from vale_doc_prg (pd.nped, pd.tipo, pd.cod_empresa) vl), 0))
    and coalesce(cl.cl_gerar_pontos, ''S'') <> ''N''
    and coalesce(tf.status_f, '''') <> ''BARRADO''
    and pd.cod_cliente <> '||:pcod_cliente||'
    
    union
    select cf.n_comando, ''MOT'' as tipo, cf.cod_empresa, cf.data_fech,

    coalesce((select coalesce(fp3.entrada, 0) from existe_formas(cf.n_comando, ''MOT'', cf.cod_empresa) fp3), 0) entrada,
    coalesce((select coalesce(fp2.valor_total, 0) from existe_formas(cf.n_comando, ''MOT'', cf.cod_empresa) fp2), 0) valor_total,
    coalesce((select coalesce(fp1.crediario, ''N'') from existe_formas
      (cf.n_comando, ''MOT'', cf.cod_empresa) fp1), ''N'') crediario,
    0 dev from com_fat cf
    inner join clientes cl on cl.cod_cliente = cf.clientes_v and cl.cod_empresa = cf.cod_empresa
    left join tipo_faturamento tf on tf.codigo_faturamento = cl.codigo_faturamento and tf.ativo = 1 
    inner join tipo_vendas tv on tv.tipo = ''VEI'' and tv.tipo_os = cf.tipo_v
        '||VTEMP_MOT||'
    where cf.status_v = ''FECHADO'' and cf.natureza = ''S''
    '||VTEMP2||' and cf.cod_empresa = '||:pcod_empresa||'
    and coalesce(cl.cl_gerar_pontos, ''S'') <> ''N''
    and coalesce(tf.status_f, '''') <> ''BARRADO''
    '||VTEMP3||'
    and (coalesce(cf.valtot_v, 0) >
        coalesce((select coalesce(abs(vl.valor_vale), 0) from vale_doc_prg (cf.n_comando, ''MOT'', cf.cod_empresa) vl), 0))
    and cf.clientes_v <> '||:pcod_cliente

  into: nrequisicao, :tpdocs, :cod_empresa, :data_fech, :valorentrada, :valortotal, :cred, :dev DO
  begin
     vperc_ent = 0;
     if (coalesce(valortotal, 0) > 0) then
       vperc_ent = ((valorentrada / valortotal) * 100);
     fp_regra_fidelidade = '';
     perc_dia_real = 0;
     pontos = 0;

     if (coalesce(valortotal, 0) > 0) then
     begin
       if ((coalesce(cred, 'N') = 'N')
         and (coalesce(valorentrada, 0) = coalesce(valortotal, 0))) then
       begin
         select first 1 trim(coalesce(crf.valor_vc, '')), coalesce(crf.pontos, 0) from regras_prog_fidelidade rf
         inner join config_regras_prog_fidelidade crf on crf.cod_tp_regra = rf.cod_tp_regra and crf.cod_empresa = rf.cod_empresa
         inner join controles ctr on trim(ctr.fp_regra_fidelidade) = trim(crf.valor_vc) and ctr.codigo_emp = crf.cod_empresa
         where rf.descricao_regra = :pregra and rf.situacao = 'ATIVA'
         and crf.valor_vc = 'DIN' and rf.cod_empresa = :cod_empresa
         order by crf.pontos asc
          into :fp_regra_fidelidade, :pontos;
         if (coalesce(fp_regra_fidelidade, '') <> '') then
           suspend;
       end
       else if (coalesce(cred, 'N') = 'N') then
       begin
         select first 1 trim(coalesce(ctr.fp_regra_fidelidade, '')), coalesce(crf.pontos, 0) from formpagamento fp
         inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
         inner join config_regras_prog_fidelidade crf on crf.valor_vc = ctr.fp_regra_fidelidade and crf.cod_empresa = ctr.codigo_emp
         inner join regras_prog_fidelidade rf on rf.cod_tp_regra = crf.cod_tp_regra and rf.cod_empresa = crf.cod_empresa and rf.descricao_regra = :pregra
         where fp.nrequisicao = :nrequisicao and fp.tpdocs = :tpdocs and fp.cod_empresa = :cod_empresa
         order by crf.pontos asc
          into :fp_regra_fidelidade, :pontos;
         if (coalesce(fp_regra_fidelidade, '') <> '') then
           suspend;
       end
       else if (coalesce(vperc_ent, 0) > 0) then
       begin
         select first 1 trim(coalesce(crf.valor_vc, '')), coalesce(crf.perc_dia_real, 0), coalesce(crf.pontos, 0) from regras_prog_fidelidade rf
         inner join config_regras_prog_fidelidade crf on crf.cod_tp_regra = rf.cod_tp_regra and crf.cod_empresa = rf.cod_empresa
         inner join controles ctr on trim(ctr.fp_regra_fidelidade) = 'CR' and ctr.codigo_emp = crf.cod_empresa
         where rf.descricao_regra = :pregra and rf.situacao = 'ATIVA'
         and crf.valor_vc = 'CRX' and rf.cod_empresa = :cod_empresa
         and crf.perc_dia_real <= :vperc_ent
         order by crf.perc_dia_real desc
          into :fp_regra_fidelidade, :perc_dia_real, :pontos;
         if (trim(coalesce(fp_regra_fidelidade, '')) = '') then
         begin
           select first 1 trim(coalesce(crf.valor_vc, '')), coalesce(crf.perc_dia_real, 0), coalesce(crf.pontos, 0) from regras_prog_fidelidade rf
           inner join config_regras_prog_fidelidade crf on crf.cod_tp_regra = rf.cod_tp_regra and crf.cod_empresa = rf.cod_empresa
           inner join controles ctr on trim(ctr.fp_regra_fidelidade) = 'CR' and ctr.codigo_emp = crf.cod_empresa
           where rf.descricao_regra = :pregra and rf.situacao = 'ATIVA'
           and crf.valor_vc = 'CRC' and rf.cod_empresa = :cod_empresa
             into :fp_regra_fidelidade, :perc_dia_real, :pontos;
         end
         if (trim(coalesce(fp_regra_fidelidade, '')) = '') then
         begin
           select first 1 trim(coalesce(ctr.fp_regra_fidelidade, '')), coalesce(crf.pontos, 0) from formpagamento fp
           inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
           inner join config_regras_prog_fidelidade crf on crf.valor_vc = ctr.fp_regra_fidelidade and crf.cod_empresa = ctr.codigo_emp
           inner join regras_prog_fidelidade rf on rf.cod_tp_regra = crf.cod_tp_regra and rf.cod_empresa = crf.cod_empresa and rf.descricao_regra = :pregra
           where fp.nrequisicao = :nrequisicao and fp.tpdocs = :tpdocs and fp.cod_empresa = :cod_empresa
           order by crf.pontos asc
            into :fp_regra_fidelidade, :pontos;
         end
         if (coalesce(fp_regra_fidelidade, '') <> '') then
           suspend;
       end
       else
       begin
         select first 1 trim(coalesce(crf.valor_vc, '')), coalesce(crf.perc_dia_real, 0), coalesce(crf.pontos, 0) from regras_prog_fidelidade rf
         inner join config_regras_prog_fidelidade crf on crf.cod_tp_regra = rf.cod_tp_regra and crf.cod_empresa = rf.cod_empresa
         inner join controles ctr on trim(ctr.fp_regra_fidelidade) = 'CR' and ctr.codigo_emp = crf.cod_empresa
         where rf.descricao_regra = :pregra and rf.situacao = 'ATIVA'
         and crf.valor_vc = 'CRS' and rf.cod_empresa = :cod_empresa
          into :fp_regra_fidelidade, :perc_dia_real, :pontos;
         if (trim(coalesce(fp_regra_fidelidade, '')) = '') then
         begin
           select first 1 trim(coalesce(ctr.fp_regra_fidelidade, '')), coalesce(crf.pontos, 0) from formpagamento fp
           inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
           inner join config_regras_prog_fidelidade crf on crf.valor_vc = ctr.fp_regra_fidelidade and crf.cod_empresa = ctr.codigo_emp
           inner join regras_prog_fidelidade rf on rf.cod_tp_regra = crf.cod_tp_regra and rf.cod_empresa = crf.cod_empresa and rf.descricao_regra = :pregra
           where fp.nrequisicao = :nrequisicao and fp.tpdocs = :tpdocs and fp.cod_empresa = :cod_empresa
           order by crf.pontos asc
            into :fp_regra_fidelidade, :pontos;
         end
         if (coalesce(fp_regra_fidelidade, '') <> '') then
           suspend;
       end
     end
     if (coalesce(fp_regra_fidelidade, '') = '') then
       suspend;
  end
end;
 
 ^

ALTER PROCEDURE GETCREDIARIO (PCPFCGC VARCHAR(18) CHARACTER SET NONE,
PCOD_CLIENTE INTEGER,
PCOD_EMPRESA INTEGER,
PFINANCEIRO_UNIFICADO CHAR(1) CHARACTER SET NONE,
PDIAS_CARENCIA_JUROS INTEGER)
RETURNS (VALOR_DEBITO DOUBLE PRECISION,
QTDE_DEBITO INTEGER,
MEDIA_DEBITO DOUBLE PRECISION,
VALOR_DEBITO_ATRASO_CAR DOUBLE PRECISION,
QTDE_DEBITO_ATRASO_CAR INTEGER,
MEDIA_DEBITO_ATRASO_CAR DOUBLE PRECISION,
VALOR_DEBITO_ATRASO DOUBLE PRECISION,
QTDE_DEBITO_ATRASO INTEGER,
MEDIA_DEBITO_ATRASO DOUBLE PRECISION)
AS 
declare variable VSQL varchar(10000);
declare variable VVALOR_DEBITO double precision;
declare variable VQTDE_DEBITO integer;
declare variable VMEDIA_DEBITO double precision;
declare variable VVALOR_DEBITO_ATRASO_CAR double precision;
declare variable VQTDE_DEBITO_ATRASO_CAR integer;
declare variable VMEDIA_DEBITO_ATRASO_CAR double precision;
declare variable VVALOR_DEBITO_ATRASO double precision;
declare variable VQTDE_DEBITO_ATRASO integer;
declare variable VMEDIA_DEBITO_ATRASO double precision;
begin
  /* Procedure Text */
  valor_debito = 0;
  qtde_debito  = 0;
  media_debito = 0;

  valor_debito_atraso = 0;
  qtde_debito_atraso  = 0;
  media_debito_atraso = 0;

  valor_debito_atraso_car = 0;
  qtde_debito_atraso_car  = 0;
  media_debito_atraso_car = 0;

  vsql =
    ' select
      sum(coalesce(controle_cheque.valor_ch, 0)) soma,
      count(*) qtde,
      sum(case when (controle_cheque.data_venc > current_date) then
                 0
               else
                 datediff(day, controle_cheque.data_venc, current_date)
      end) media from controle_cheque
      left join empresa on empresa.cod_empresa = controle_cheque.cod_emp_mult
      left join clientes on
        clientes.cod_cliente = controle_cheque.cod_cliente
        and clientes.cod_empresa = controle_cheque.cod_emp_mult
      inner join controles on
        controles.codigo_ctrl = controle_cheque.codigo_ctrl
        and controles.codigo_emp = controle_cheque.codigo_emp
        and trim(coalesce(controles.exibir_doc, ''A'')) in ('''', ''A'', ''L'') ';
    
  if ((coalesce(pfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
    vsql = vsql ||
      ' where clientes.cpfcgc = ''' || :pcpfcgc || ''' ';
  else
    vsql = vsql ||
      ' where controle_cheque.cod_cliente = ' || :pcod_cliente;
    
  vsql = vsql ||
    ' and (controle_cheque.status_ch is null or controle_cheque.status_ch = '''') ';
    
  if ((coalesce(pfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
    vsql = vsql ||
      ' and empresa.codigo_unificadora = ' || :pcod_empresa;
  else
    vsql = vsql ||
      ' and controle_cheque.codigo_emp = ' || :pcod_empresa;
    
  execute statement
    vsql into :vvalor_debito, :vqtde_debito, :vmedia_debito;
    
  valor_debito = coalesce(valor_debito, 0) + coalesce(vvalor_debito, 0);
  qtde_debito  = coalesce(qtde_debito, 0)  + coalesce(vqtde_debito, 0);
  media_debito = coalesce(media_debito, 0) + coalesce(vmedia_debito, 0);

  vsql =
    ' select
      sum(coalesce(controle_cheque.valor_ch, 0)) valor,
      count(*) qtde,
      sum(case when (controle_cheque.data_venc > current_date) then
                 0
               else
                 datediff(day, controle_cheque.data_venc, current_date)
      end) media from controle_cheque
      left join empresa on empresa.cod_empresa = controle_cheque.cod_emp_mult
      inner join controles on
        controles.codigo_ctrl = controle_cheque.codigo_ctrl
         and controles.codigo_emp = controle_cheque.codigo_emp
         and trim(coalesce(controles.exibir_doc, ''A'')) in ('''', ''A'', ''S'')
      inner join clientes on
         clientes.cod_cliente = controle_cheque.cod_cliente
         and clientes.cod_empresa = controle_cheque.cod_emp_mult ';

  if ((coalesce(pfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
    vsql = vsql ||
      ' where clientes.cpfcgc = ''' || :pcpfcgc || ''' ';
  else
    vsql = vsql ||
      ' where controle_cheque.cod_cliente = ' || :pcod_cliente;

  vsql = vsql ||
    '  and controle_cheque.data_venc < current_date
       and ((controle_cheque.status_ch is null) or (controle_cheque.status_ch = '''')) ';

  if ((coalesce(pfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
    vsql = vsql ||
      ' and empresa.codigo_unificadora = ' || :pcod_empresa;
  else
    vsql = vsql ||
      ' and controle_cheque.codigo_emp = ' || :pcod_empresa;

  execute statement
    vsql into :vvalor_debito_atraso, :vqtde_debito_atraso, :vmedia_debito_atraso;

  valor_debito_atraso = coalesce(valor_debito_atraso, 0) + coalesce(vvalor_debito_atraso, 0);
  qtde_debito_atraso  = coalesce(qtde_debito_atraso, 0)  + coalesce(vqtde_debito_atraso, 0);
  media_debito_atraso = coalesce(media_debito_atraso, 0) + coalesce(vmedia_debito_atraso, 0);

  vsql =
    ' select
      sum(coalesce(controle_cheque.valor_ch, 0)) valor,
      count(*) qtde,
      sum(case when (controle_cheque.data_venc > current_date) then
                 0
               else
                 datediff(day, controle_cheque.data_venc, current_date)
      end) media from controle_cheque
      left join empresa on empresa.cod_empresa = controle_cheque.cod_emp_mult
      inner join controles on
        controles.codigo_ctrl = controle_cheque.codigo_ctrl
         and controles.codigo_emp = controle_cheque.codigo_emp
         and trim(coalesce(controles.exibir_doc, ''A'')) in ('''', ''A'', ''S'')
      inner join clientes on
         clientes.cod_cliente = controle_cheque.cod_cliente
         and clientes.cod_empresa = controle_cheque.cod_emp_mult ';

  if ((coalesce(pfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
    vsql = vsql ||
      ' where clientes.cpfcgc = ''' || :pcpfcgc || ''' ';
  else
    vsql = vsql ||
      ' where controle_cheque.cod_cliente = ' || :pcod_cliente;

  vsql = vsql ||
    '  and controle_cheque.data_venc + ' || :pdias_carencia_juros || ' < current_date
       and ((controle_cheque.status_ch is null) or (controle_cheque.status_ch = '''')) ';

  if ((coalesce(pfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
    vsql = vsql ||
      ' and empresa.codigo_unificadora = ' || :pcod_empresa;
  else
    vsql = vsql ||
      ' and controle_cheque.codigo_emp = ' || :pcod_empresa;

  execute statement
    vsql into :vvalor_debito_atraso_car, :vqtde_debito_atraso_car, :vmedia_debito_atraso_car;

  valor_debito_atraso_car = coalesce(valor_debito_atraso_car, 0) + coalesce(vvalor_debito_atraso_car, 0);
  qtde_debito_atraso_car  = coalesce(qtde_debito_atraso_car, 0)  + coalesce(vqtde_debito_atraso_car, 0);
  media_debito_atraso_car = coalesce(media_debito_atraso_car, 0) + coalesce(vmedia_debito_atraso_car, 0);

  vsql =
    ' select
      sum(coalesce(controle_creditos.valor_c, 0)) valor,
      count(*) qtde,
      sum(case when (controle_creditos.data_venc_c > current_date) then
                 0
               else
                 datediff(day, controle_creditos.data_venc_c, current_date)
      end) media from controle_creditos
      left join empresa on empresa.cod_empresa = controle_creditos.cod_emp_mult
      left join clientes on
        clientes.cod_cliente = controle_creditos.cod_cliente
        and clientes.cod_empresa = controle_creditos.cod_emp_mult
      inner join controles on
        controles.codigo_ctrl = controle_creditos.codigo_ctrl
        and controles.codigo_emp = controle_creditos.codigo_emp
        and trim(coalesce(controles.exibir_doc, ''A'')) in ('''', ''A'', ''L'') ';

  if ((coalesce(pfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
    vsql = vsql ||
      ' where clientes.cpfcgc = ''' || :pcpfcgc || ''' ';
  else
    vsql = vsql ||
      ' where controle_creditos.cod_cliente = ' || :pcod_cliente;

  vsql = vsql ||
    ' and (controle_creditos.status_c is null or controle_creditos.status_c = '''') ';

  if ((coalesce(pfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
    vsql = vsql || ' and empresa.codigo_unificadora = ' || :pcod_empresa;
  else
    vsql = vsql || ' and controle_creditos.codigo_emp = ' || :pcod_empresa;

  execute statement
    vsql into :vvalor_debito, :vqtde_debito, :vmedia_debito;

  valor_debito = coalesce(valor_debito, 0) + coalesce(vvalor_debito, 0);
  qtde_debito  = coalesce(qtde_debito, 0)  + coalesce(vqtde_debito, 0);
  media_debito = coalesce(media_debito, 0) + coalesce(vmedia_debito, 0);

  vsql =
    ' select
      sum(coalesce(controle_creditos.valor_c, 0)) valor,
      count(*) qtde,
      sum(case when (controle_creditos.data_venc_c > current_date) then
                 0
               else
                 datediff(day, controle_creditos.data_venc_c, current_date)
      end) media from controle_creditos
      left join empresa on empresa.cod_empresa = controle_creditos.cod_emp_mult
      inner join controles on
        controles.codigo_ctrl = controle_creditos.codigo_ctrl
        and controles.codigo_emp = controle_creditos.codigo_emp
        and trim(coalesce(controles.exibir_doc, ''A'')) in ('''', ''A'', ''S'')
      inner join clientes on
        clientes.cod_cliente = controle_creditos.cod_cliente
        and clientes.cod_empresa = controle_creditos.cod_emp_mult ';

  if ((coalesce(pfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
    vsql = vsql ||
      ' where clientes.cpfcgc = ''' || :pcpfcgc || ''' ';
  else
    vsql = vsql ||
      ' where controle_creditos.cod_cliente = ' || :pcod_cliente;

  vsql = vsql ||
    ' and controle_creditos.data_venc_c < current_date
      and ((controle_creditos.status_c is null) or (controle_creditos.status_c = '''')) ';

  if ((coalesce(pfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
    vsql = vsql ||
      ' and empresa.codigo_unificadora = ' || :pcod_empresa;
  else
    vsql = vsql ||
      ' and controle_creditos.codigo_emp = ' || :pcod_empresa;

  execute statement
    vsql into :vvalor_debito_atraso, :vqtde_debito_atraso, :vmedia_debito_atraso;

  valor_debito_atraso = coalesce(valor_debito_atraso, 0) + coalesce(vvalor_debito_atraso, 0);
  qtde_debito_atraso  = coalesce(qtde_debito_atraso, 0)  + coalesce(vqtde_debito_atraso, 0);
  media_debito_atraso = coalesce(media_debito_atraso, 0) + coalesce(vmedia_debito_atraso, 0);

  vsql =
    ' select
      sum(coalesce(controle_creditos.valor_c, 0)) valor,
      count(*) qtde,
      sum(case when (controle_creditos.data_venc_c > current_date) then
                 0
               else
                 datediff(day, controle_creditos.data_venc_c, current_date)
      end) media from controle_creditos
      left join empresa on empresa.cod_empresa = controle_creditos.cod_emp_mult
      inner join controles on
        controles.codigo_ctrl = controle_creditos.codigo_ctrl
        and controles.codigo_emp = controle_creditos.codigo_emp
        and trim(coalesce(controles.exibir_doc, ''A'')) in ('''', ''A'', ''S'')
      inner join clientes on
        clientes.cod_cliente = controle_creditos.cod_cliente
        and clientes.cod_empresa = controle_creditos.cod_emp_mult ';

  if ((coalesce(pfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
    vsql = vsql ||
      ' where clientes.cpfcgc = ''' || :pcpfcgc || ''' ';
  else
    vsql = vsql ||
      ' where controle_creditos.cod_cliente = ' || :pcod_cliente;
  
  vsql = vsql ||
    ' and controle_creditos.data_venc_c + ' || :pdias_carencia_juros || ' < current_date
      and ((controle_creditos.status_c is null) or (controle_creditos.status_c = '''')) ';
  
  if ((coalesce(pfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
    vsql = vsql ||
      ' and empresa.codigo_unificadora = ' || :pcod_empresa;
  else
    vsql = vsql ||
      ' and controle_creditos.codigo_emp = ' || :pcod_empresa;

  execute statement
    vsql into :vvalor_debito_atraso_car, :vqtde_debito_atraso_car, :vmedia_debito_atraso_car;

  valor_debito_atraso_car = coalesce(valor_debito_atraso_car, 0) + coalesce(vvalor_debito_atraso_car, 0);
  qtde_debito_atraso_car  = coalesce(qtde_debito_atraso_car, 0)  + coalesce(vqtde_debito_atraso_car, 0);
  media_debito_atraso_car = coalesce(media_debito_atraso_car, 0) + coalesce(vmedia_debito_atraso_car, 0);

  if (coalesce(qtde_debito, 0) > 0) then
    media_debito = coalesce(media_debito, 0) / coalesce(qtde_debito, 0);
  else
    media_debito = coalesce(media_debito, 0);

  if (coalesce(qtde_debito_atraso, 0) > 0) then
    media_debito_atraso = coalesce(media_debito_atraso, 0) / coalesce(qtde_debito_atraso, 0);
  else
    media_debito_atraso = coalesce(media_debito_atraso, 0);

  if (coalesce(qtde_debito_atraso_car, 0) > 0) then
    media_debito_atraso_car = coalesce(media_debito_atraso_car, 0) / coalesce(qtde_debito_atraso_car, 0);
  else
    media_debito_atraso_car = coalesce(media_debito_atraso_car, 0);

  suspend;
end ^

ALTER PROCEDURE GETCREDITOS (PNSU VARCHAR(20) CHARACTER SET NONE,
PAUT VARCHAR(20) CHARACTER SET NONE,
PNPARCELA INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (COD_CRED INTEGER,
CODIGO_EMP INTEGER)
AS 
begin
  cod_cred   = 0;
  codigo_emp = 0;
  if ((trim(coalesce(pnsu, '')) = '') and (trim(coalesce(paut, '')) = '')) then
    suspend;
  else if ((trim(coalesce(pnsu, '')) <> '') and (trim(coalesce(paut, '')) <> '')) then
  begin
    execute statement
      'select first 1 cc.cod_cred, cc.codigo_emp from controle_creditos cc
       where (select result from retirar_zero_esquerda (cc.n_docnsu_adm)) = '''|| (select result from retirar_zero_esquerda (:pnsu)) || '''
       and cc.n_aut_cart = ''' || :paut || '''
       and coalesce(cc.nparcela, 1) = '||:pnparcela||'
       and cc.cod_emp_mult = '||:pcod_empresa || '
       order by 1 desc '
         into :cod_cred, :codigo_emp;

    cod_cred   = coalesce(cod_cred, 0);
    codigo_emp = coalesce(codigo_emp, 0);
    suspend;
  end
  else if (trim(coalesce(pnsu, '')) <> '') then
  begin
    execute statement
      'select first 1 cc.cod_cred, cc.codigo_emp from controle_creditos cc
       where (select result from retirar_zero_esquerda (cc.n_docnsu_adm)) = '''|| (select result from retirar_zero_esquerda (:pnsu)) || '''
       and coalesce(cc.nparcela, 1) = '||:pnparcela||'
       and cc.cod_emp_mult = '||:pcod_empresa || '
       order by 1 desc '
         into :cod_cred, :codigo_emp;

    cod_cred   = coalesce(cod_cred, 0);
    codigo_emp = coalesce(codigo_emp, 0);
    suspend;
  end
end ^

