      'select first 1 min(cc.cod_cred) cod_cred, min(cc.codigo_emp) codigo_emp, count(*) qtde_reg from controle_creditos cc
       where cc.n_docnsu_adm = '''||:pnsu || '''
       and coalesce(cc.nparcela, 1) = '||:pnparcela||'
       and cc.cod_emp_mult = '||:pcod_empresa||'
       and cc.datq_c is null'
         into :cod_cred, :codigo_emp, :qtde_reg;
    suspend;
  end
end ^

