       and coalesce(cc.nparcela, 1) = '||:pnparcela||'
       and cc.cod_emp_mult = '||:pcod_empresa||'
       and cc.datq_c is not null
       and (coalesce((select count(*) from controle_creditos cc2
                      where (select result from retirar_zero_esquerda (cc2.n_docnsu_adm)) = '''|| (select result from retirar_zero_esquerda (:pnsu)) || '''
                      and coalesce(cc2.nparcela, 1) = '||:pnparcela||'
                      and cc2.cod_emp_mult = '||:pcod_empresa||'
                      and cc2.datq_c is null), 0)) = 0
       order by 1 desc '
         into :cod_cred, :codigo_emp;

    cod_cred   = coalesce(cod_cred, 0);
    codigo_emp = coalesce(codigo_emp, 0);
    suspend;
  end
end ^

ALTER PROCEDURE GETCRIARPRODUCAO_TEMP (PNPED INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (RESULT VARCHAR(100) CHARACTER SET NONE)
AS 
declare variable VGRUPO_PROD_ACAB integer;
declare variable VCOD_PROD_ACAB char(6);
declare variable VCOD_GRADE_ACAB integer;
declare variable VCOD_EMPRESA_ACAB integer;
declare variable VQUANT_PED_ACAB double precision;
declare variable VGRUPO_PROD_MPRIMA integer;
declare variable VCOD_PROD_MPRIMA char(6);
declare variable VESTOQUE_MPRIMA double precision;
declare variable VQUANT_MPRIMA double precision;
declare variable VTEMP double precision;
declare variable VRESULT varchar(100);
declare variable VRESULT_OK varchar(100);
declare variable VGRUPO_PROD integer;
declare variable VCOD_PROD char(6);
declare variable VCOD_GRADE integer;
declare variable VQTDE double precision;
declare variable VTQDE_DIM_EST double precision;
begin
  /* Procedure Text */
  result = 'OK';

  if ((:pnped > 0) and (trim(:ptipo) <> '') and (:pcod_empresa > 0)) then
  begin
    for select pp.grupo_prod, pp.cod_prod, pp.cod_grade, pp.cod_empresa, sum(coalesce(pp.quant_ped_item, 0)) quant_ped_item from pedvenda pd
      inner join pedvenda_prod pp on
        pp.nped = pd.nped
        and pp.tipo = pd.tipo
        and pp.cod_empresa = pd.cod_empresa
      inner join produtos pr on
        pr.grupo_prod = pp.grupo_prod
        and pr.cod_prod = pp.cod_prod
        and pr.cod_empresa = pp.cod_empresa
      where pp.nped = :pnped
      and pp.tipo = :ptipo
      and pp.cod_empresa = :pcod_empresa
      and coalesce(pp.status, '') <> 'CANCELADO'
      and pp.ativo = 1
      and not(coalesce(pp.quant_ped_item, 0) = coalesce(pp.quant_item_dev, 0) and coalesce(pp.status, '') = 'CANCELADO')
      and coalesce(pr.criar_producao_aut, 'N') = 'S'
      group by 1, 2, 3, 4
    into :vgrupo_prod_acab, :vcod_prod_acab, :vcod_grade_acab, :vcod_empresa_acab, :vquant_ped_acab do
    begin
      for select grupo_prod, cod_prod, cod_grade, qtde from getprodutosacabados (
        :vgrupo_prod_acab,
        :vcod_prod_acab,
        :vcod_grade_acab,
        :vcod_empresa_acab,
        coalesce(:vquant_ped_acab, 0))
          into :vgrupo_prod, :vcod_prod, :vcod_grade, :vqtde do
      begin
        vtqde_dim_est = 0;
        if  ( (coalesce(vgrupo_prod_acab, 0) = coalesce(vgrupo_prod, 0))
          and (coalesce(vcod_prod_acab, '') = coalesce(vcod_prod, ''))
          and (coalesce(vcod_grade_acab, 0) = coalesce(vcod_grade, 0))  ) then
        begin
          vtqde_dim_est = 0;
        end
        else
        begin
          vtqde_dim_est = coalesce(vqtde, 0);
        end

        select result from getmateria_prima_recursivo(
          :pnped,
          :ptipo,
          :vgrupo_prod,
          :vcod_prod,
          coalesce(:vcod_grade, 0),
          :pcod_empresa,
          coalesce(:vqtde, 0),
          coalesce(:vtqde_dim_est, 0)
        )
          into :vresult;

        if (coalesce(vresult, '') = 'OK') then
          vresult_ok = coalesce(vresult, '');

        if ((coalesce(vresult_ok, '') <> 'OK') and (coalesce(vresult, '') <> 'OK')) then
        begin
          result = vresult;
          suspend;
        end
      end
    end
  end
  result = 'OK';
  suspend;
end ^

ALTER PROCEDURE GETDEBITOSEMATRASO (PCPFCGC VARCHAR(18) CHARACTER SET NONE,
PCOD_CLIENTE INTEGER,
PCOD_EMPRESA INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE)
RETURNS (VALOR DOUBLE PRECISION,
QTDE INTEGER)
AS 
declare variable VSQL varchar(1000);
declare variable VFINANCEIRO_UNIFICADO char(1);
declare variable VDIAS_CARENCIA_JUROS integer;
declare variable VVALOR double precision;
declare variable VQTDE integer;
begin
  valor = 0;
  qtde  = 0;

  select empresa.financeiro_unificado, empresa.dias_car_juros from empresa where empresa.cod_empresa = :pcod_empresa into :vfinanceiro_unificado, :vdias_carencia_juros;

  if ((coalesce(ptipo, '') = 'CH') or (coalesce(ptipo, '') = 'A')) then
  begin
    vsql =
      ' select sum(coalesce(controle_cheque.valor_ch, 0)) valor, count(*) qtde from controle_cheque
        left join empresa on empresa.cod_empresa = controle_cheque.cod_emp_mult
        inner join controles on
          controles.codigo_ctrl = controle_cheque.codigo_ctrl
           and controles.codigo_emp = controle_cheque.codigo_emp
           and trim(coalesce(controles.exibir_doc, ''A'')) in ('''', ''A'', ''S'')
        inner join clientes on
           clientes.cod_cliente = controle_cheque.cod_cliente
           and clientes.cod_empresa = controle_cheque.cod_emp_mult ';

    if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
      vsql = vsql ||
        ' where clientes.cpfcgc = ''' || :pcpfcgc || ''' ';
    else
      vsql = vsql ||
        ' where controle_cheque.cod_cliente = ' || :pcod_cliente;

    vsql = vsql ||
      '  and controle_cheque.data_venc + ' || :vdias_carencia_juros || ' < current_date
         and ((controle_cheque.status_ch is null) or (controle_cheque.status_ch = '''')) ';

    if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
      vsql = vsql ||
        ' and empresa.codigo_unificadora = ' || :pcod_empresa;
    else
      vsql = vsql ||
        ' and controle_cheque.codigo_emp = ' || :pcod_empresa;

    execute statement
      vsql into :vvalor, :vqtde;

    valor = coalesce(valor, 0) + coalesce(vvalor, 0);
    qtde  = coalesce(qtde, 0)  + coalesce(vqtde, 0);
  end

  if ((coalesce(ptipo, '') = 'CC') or (coalesce(ptipo, '') = 'A')) then
  begin
    vsql =
      ' select sum(coalesce(controle_creditos.valor_c, 0)) valor, count(*) qtde from controle_creditos
        left join empresa on empresa.cod_empresa = controle_creditos.cod_emp_mult
        inner join controles on
          controles.codigo_ctrl = controle_creditos.codigo_ctrl
          and controles.codigo_emp = controle_creditos.codigo_emp
          and trim(coalesce(controles.exibir_doc, ''A'')) in ('''', ''A'', ''S'')
        inner join clientes on
          clientes.cod_cliente = controle_creditos.cod_cliente
          and clientes.cod_empresa = controle_creditos.cod_emp_mult ';

    if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
      vsql = vsql ||
        ' where clientes.cpfcgc = ''' || :pcpfcgc || ''' ';
    else
      vsql = vsql ||
        ' where controle_creditos.cod_cliente = ' || :pcod_cliente;

    vsql = vsql ||
      ' and controle_creditos.data_venc_c + ' || :vdias_carencia_juros || ' < current_date
        and ((controle_creditos.status_c is null) or (controle_creditos.status_c = '''')) ';

    if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
      vsql = vsql ||
        ' and empresa.codigo_unificadora = ' || :pcod_empresa;
    else
      vsql = vsql ||
        ' and controle_creditos.codigo_emp = ' || :pcod_empresa;

    execute statement
      vsql into :vvalor, :vqtde;

    valor = coalesce(valor, 0) + coalesce(vvalor, 0);
    qtde  = coalesce(qtde, 0)  + coalesce(vqtde, 0);
  end

  suspend;
end ^

ALTER PROCEDURE GETESTOQUEDISPONIVEL (PGRUPOPROD INTEGER,
PCODPROD CHAR(6) CHARACTER SET NONE,
PCODGRADE INTEGER,
PCODEMPRESA INTEGER,
PNUMVENDA INTEGER,
PTIPOVENDA VARCHAR(5) CHARACTER SET NONE,
PCODPEDALMOX INTEGER,
PNITEMPEDALMOX INTEGER)
RETURNS (ESTOQUE DOUBLE PRECISION,
PEND_REQOS DOUBLE PRECISION,
PEND_PDC DOUBLE PRECISION,
PEND_ALMOX DOUBLE PRECISION,
EST_F DOUBLE PRECISION,
EST_PRIMA DOUBLE PRECISION)
AS 
declare variable VSQL varchar(1000);
declare variable VESTOQUE double precision;
declare variable VPENDENCIA double precision;
declare variable VABATERITENS char(1);
declare variable VUSAR_PRODUCAO_TIPO char(1);
declare variable VCOD_VENDEDOR integer;
declare variable VUSARCONFERENCIAPRODUTO char(1);
declare variable VCRIAR_PRODUCAO_AUT char(1);
begin     

  if ((pgrupoprod is null) or (pcodprod is null) or (pcodempresa is null)) then
   exit;

  vSql = '';
  select abater_itens from empresa where cod_empresa = :pcodempresa into: vabateritens;

  select usar_producao_tipo from empresa where cod_empresa = :pcodempresa into :vusar_producao_tipo;

  select criar_producao_aut from produtos where grupo_prod = :pgrupoprod and cod_prod = :pcodprod and cod_empresa = :pcodempresa into :vcriar_producao_aut;

  if (coalesce(pcodgrade, 0) <= 0) then
  begin
    select est_f from produtos
    where grupo_prod = :pgrupoprod
    and cod_prod = :pcodprod
    and cod_empresa = :pcodempresa into :vestoque;
  end
  else
  begin
    select qtde from cod_grade_prod
    where grupo_prod = :pgrupoprod
    and cod_prod = :pcodprod
    and cod_grade = :pcodgrade
    and cod_empresa = :pcodempresa into :vestoque;
  end

  est_f = coalesce(vestoque, 0);

  if ((coalesce(vabateritens, '') = 'S') and (coalesce(pnumvenda, 0) > 0) and (Trim(coalesce(ptipovenda, '')) <> '')) then
  begin
    select first 1 coalesce(tv.usar_conferencia_produto, '') as usar_conferencia_produto, pv.cod_vendedor from pedvenda pv
    inner join tipo_vendas tv on tv.tipo = pv.tipo and tv.sigla = pv.tipv
    where pv.nped = :pnumvenda
    and pv.tipo = :ptipovenda
    and pv.cod_empresa = :pcodempresa
    order by tv.cod_tipo into : vusarconferenciaproduto, :vcod_vendedor;

    if (coalesce(vusarconferenciaproduto, '') <> 'S') then
      vSql = vsql || ' inner join tipo_vendas tv on tv.sigla = pd.tipv and tv.tipo = pd.tipo
         and (coalesce(tv.usar_conferencia_produto, '''') <> ''S'')';
  end

  vSql = vSql || ' where pd.ativo = 1 and itpd.grupo_prod = '||:pgrupoprod||' and itpd.cod_prod = '''||:pcodprod||'''
     and pd.cod_empresa = ' || pcodempresa ||'
     and (pd.data_fech is null or pd.data_fech < ''01.01.1899'' ) and (itpd.status<>''CANCELADO'' or itpd.status is null)
     and pd.tipo <> ''ORC'' ';

  if ((coalesce(vabateritens, '') = 'S') and (coalesce(pnumvenda, 0) > 0)
    and (Trim(ptipovenda) <> '') and (Trim(vusarconferenciaproduto) <> 'S')) then
    vSql = vSql || ' and pd.cod_vendedor = '|| :vcod_vendedor;

  if (coalesce(pcodgrade, 0) > 0) then
    vSql = vSql || ' and itpd.cod_grade = '|| :pcodgrade;
             
  if ((coalesce(pnumvenda, 0) > 0) and (coalesce(ptipovenda, '') <> '')) then
    vSql = vSql || ' and pd.nped = '|| :pnumvenda || ' and pd.tipo = ''' || :ptipovenda || ''' ';

  execute statement
    ' select sum(itpd.quant_ped_item) as pendecia from pedvenda pd
    inner join pedvenda_prod itpd on pd.nped = itpd.nped and pd.cod_empresa = itpd.cod_empresa and pd.tipo = itpd.tipo
    ' || vSql into :vpendencia;

  pend_reqos = coalesce(vpendencia, 0);

  vestoque = coalesce(vestoque, 0) - coalesce(vpendencia, 0);

  vsql = '';
  if (coalesce(pcodgrade, 0) > 0) then
    vSql = vSql || ' and pi.cod_grade = '||:pcodgrade;

  if (Trim(coalesce(ptipovenda, '')) = 'PRODUCAO') then
    vSql = vSql || ' and pd.cod_producao <> '|| :pnumvenda;

  execute statement 'select sum(coalesce(pi.quantidade_utilizada,0) + coalesce(pi.quantidade_perda,0)) as pendecia from producao pd, producao_item_indice pi
                    where pi.grupo_prod = ' || :pgrupoprod ||
                    ' and pi.cod_prod = ''' || :pcodprod || '''
                    and pd.cod_producao = pi.cod_producao and pd.cod_empresa = pi.cod_empresa
                    and (pd.data_fechamento is null) and pd.cod_empresa = ' || :pcodempresa || vsql into :vpendencia;

  pend_pdc = coalesce(vpendencia, 0);

  vestoque = coalesce(vestoque, 0) - coalesce(vpendencia, 0);

  vSql = '';
  if (coalesce(pcodgrade, 0) > 0) then
      vSql = vSql || ' and c.cod_grade = '||:pcodgrade;

  execute statement
    ' select sum(coalesce(c.quant,0)) as pendecia from controle_almoxarifado c
      where not(c.cod_pedido = '||:pcodpedalmox||' and c.nitem = '||:pnitempedalmox||')'||'
      and c.grupo_prod = '|| :pgrupoprod ||' and c.cod_prod = '''||:pcodprod||'''
      and c.cod_empresa = '||:pcodempresa|| vsql into :vpendencia;

  pend_almox = coalesce(vpendencia, 0);

  vestoque = coalesce(vestoque, 0) - coalesce(vpendencia, 0);

  if ((coalesce(vcriar_producao_aut, 'N') = 'S') and (coalesce(vusar_producao_tipo, 'N') = 'S')) then
  begin
    vSql = '';
    if (coalesce(pcodgrade, 0) > 0) then
      vSql = :pcodgrade;
    else
      vSql = '0';
    
    execute statement
      ' select estoque from getestoque_recursivo (
          ' || :pgrupoprod || ',
          ''' || :pcodprod || ''', '
          || :pcodempresa || ', '
          || :vSql || ') ' into :vpendencia;
    
    est_prima = coalesce(vpendencia, 0);
  end

  estoque   = COALESCE(vestoque, 0);
  est_f     = COALESCE(est_f, 0);
  est_prima = COALESCE(est_prima, 0);
  suspend;
end;
 
 ^

ALTER PROCEDURE GETESTOQUEEMPRESAS (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESAS VARCHAR(50) CHARACTER SET NONE,
PSOMAR_EMP_SEM_EST INTEGER)
RETURNS (ESTOQUE DOUBLE PRECISION,
PEND_REQOS DOUBLE PRECISION,
PEND_PDC DOUBLE PRECISION,
PEND_ALMOX DOUBLE PRECISION,
EST_F DOUBLE PRECISION,
EST_PRIMA DOUBLE PRECISION)
AS 
declare variable VEMPRESA varchar(20);
declare variable VESTOQUE double precision;
declare variable VPEND_REQOS double precision;
declare variable VPEND_PDC double precision;
declare variable VPEND_ALMOX double precision;
declare variable VEST_F double precision;
declare variable VEST_PRIMA double precision;
begin
  /* Procedure Text */
  estoque = 0;
  pend_reqos = 0;
  pend_pdc = 0;
  pend_almox = 0;
  est_f = 0;
  est_prima = 0;

  vestoque = 0;
  vpend_reqos = 0;
  vpend_pdc = 0;
  vpend_almox = 0;
  vest_f = 0;
  vest_prima = 0;
  for select osplit from p_split (:pcod_empresas, ',')
    into :vempresa do
  begin
    select estoque, pend_reqos, pend_pdc, pend_almox, est_f, est_prima  from getestoquedisponivel
        (:pgrupo_prod, :pcod_prod, :pcod_grade, :vempresa, 0, '', 0, 0)
          into :vestoque, :vpend_reqos, :vpend_pdc, :vpend_almox, :vest_f, :vest_prima;

    if (coalesce(psomar_emp_sem_est, 0) > 0) then
    begin
      estoque    = coalesce(estoque, 0)    + coalesce(vestoque, 0);
      pend_reqos = coalesce(pend_reqos, 0) + coalesce(vpend_reqos, 0);
      pend_pdc   = coalesce(pend_pdc, 0)   + coalesce(vpend_pdc, 0);
      pend_almox = coalesce(pend_almox, 0) + coalesce(vpend_almox, 0);
      est_f      = coalesce(est_f, 0)      + coalesce(vest_f, 0);
      est_prima  = coalesce(est_prima, 0)  + coalesce(vest_prima, 0);
    end
    else if (coalesce(vestoque, 0) > 0) then
    begin
      estoque    = coalesce(estoque, 0)    + coalesce(vestoque, 0);
      pend_reqos = coalesce(pend_reqos, 0) + coalesce(vpend_reqos, 0);
      pend_pdc   = coalesce(pend_pdc, 0)   + coalesce(vpend_pdc, 0);
      pend_almox = coalesce(pend_almox, 0) + coalesce(vpend_almox, 0);
      est_f      = coalesce(est_f, 0)      + coalesce(vest_f, 0);
      est_prima  = coalesce(est_prima, 0)  + coalesce(vest_prima, 0);
    end
  end

  suspend;
end ^

ALTER PROCEDURE GETESTOQUE_RECURSIVO (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PCOD_GRADE INTEGER)
RETURNS (ESTOQUE DOUBLE PRECISION)
AS 
declare variable VSQL varchar(500);
declare variable VEXISTE_GRADE integer;
declare variable VCRIAR_PRODUCAO_AUT char(1);
declare variable VUSAR_PRODUCAO_TIPO char(1);
declare variable VGRUPO_PROD_MPRIMA integer;
declare variable VCOD_PROD_MPRIMA char(6);
declare variable VCOD_GRADE_MPRIMA integer;
declare variable VQUANT_MPRIMA double precision;
declare variable VESTOQUE double precision;
declare variable VESTOQUE_P double precision;
declare variable VESTOQUE_GERAL double precision;
declare variable VID_IND_A integer;
declare variable VTEMP double precision;
declare variable VTEMP_SQL varchar(100);
declare variable VOK integer;
begin
  /* Procedure Text */
  vestoque_geral = 0;
  vestoque_p = 0;
  vok = 0;
  estoque = 0;

  select usar_producao_tipo from empresa where cod_empresa = :pcod_empresa into :vusar_producao_tipo;

  if (coalesce(vusar_producao_tipo, 'N') <> 'S') then
  begin
    suspend;
    exit;
  end

  select criar_producao_aut from produtos where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa into :vcriar_producao_aut;

  if (coalesce(vcriar_producao_aut, 'N') <> 'S') then
  begin
    suspend;
    exit;
  end

  select count(*) from cod_grade_prod where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa and cod_grade > 0 into :vexiste_grade;

  vtemp_sql = '';
  if (coalesce(pcod_grade, 0) > 0) then
    vtemp_sql = ' and pa.cod_grade = ' || :pcod_grade;
  else if (coalesce(vexiste_grade, 0) > 0) then
    vtemp_sql = ' and pa.cod_grade > 0 ';

  vestoque_geral = 0;
  vsql = ' select 0 from rdb$database ';
  if ((coalesce(vexiste_grade, 0) > 0) or (coalesce(pcod_grade, 0) > 0)) then
    vsql = ' select ' ||
           iif((coalesce(pcod_grade, 0) <= 0) and (coalesce(vexiste_grade, 0) > 0), '', ' first 1 ') ||
           ' pa.id_ind from produtos_pdc_var pa
             where pa.grupo_prod = ' || :pgrupo_prod || '
             and pa.cod_prod = ' || :pcod_prod || '
           ' || vtemp_sql || '
             and pa.cod_empresa = ' || :pcod_empresa;

  for
    execute statement
      vsql into :vid_ind_a do
  begin
    vtemp = 0;
    vok = 0;
    vestoque_p = 0;
    for
      select ind.grupo_prod_mprima, ind.cod_prod_mprima,
      iif(coalesce(pm.quant, 0) > 0, coalesce(pm.quant, 0), coalesce(ind.quant, 0)) quant,
      iif(coalesce(pm.cod_grade, 0) > 0, coalesce(pm.cod_grade, 0), 0) cod_grade_mprima,
      coalesce((select estoque from getestoquedisponivel(
        ind.grupo_prod_mprima,
        ind.cod_prod_mprima,
        iif(coalesce(pm.cod_grade, 0) > 0, coalesce(pm.cod_grade, 0), 0),
        ind.cod_empresa,
        0,
        '',
        0,
        0)), 0) estoque from indice_tecnico ind
      left join produtos_pdc_var_it pm on
        pm.id_ind = coalesce(:vid_ind_a, 0)
        and pm.grupo_prod = ind.grupo_prod_mprima
        and pm.cod_prod = ind.cod_prod_mprima
        and pm.cod_empresa = ind.cod_empresa
      inner join produtos pa on
        pa.grupo_prod = ind.grupo_prod_acabado
        and pa.cod_prod = ind.cod_prod_acabado
        and pa.cod_empresa = ind.cod_empresa
      where ind.grupo_prod_acabado = :pgrupo_prod
      and ind.cod_prod_acabado = :pcod_prod
      and ind.cod_empresa = :pcod_empresa
      and coalesce(pa.criar_producao_aut, 'N') = 'S'
        into :vgrupo_prod_mprima, :vcod_prod_mprima, :vquant_mprima, :vcod_grade_mprima, :vtemp do
    begin
      if (coalesce(vestoque_p, 0) = 0) then
        vestoque = (coalesce(vtemp, 0) / coalesce(vquant_mprima, 0));
      else if ((coalesce(vtemp, 0) / coalesce(vquant_mprima, 0)) < coalesce(vestoque_p, 0)) then
        vestoque = (coalesce(vtemp, 0) / coalesce(vquant_mprima, 0));
    
      vtemp = 0;
      select estoque from getestoque_recursivo (
        :vgrupo_prod_mprima,
        :vcod_prod_mprima,
        :pcod_empresa,
        :vcod_grade_mprima) into :vtemp;
    
      vestoque = coalesce(vestoque, 0) + coalesce(vtemp, 0);
    
      if (coalesce(vok, 0) = 0) then
        vestoque_p = coalesce(vestoque, 0);
      else if (coalesce(vestoque, 0) < coalesce(vestoque_p, 0)) then
        vestoque_p = coalesce(vestoque, 0);

      vok = 1;
    end
    estoque = coalesce(estoque, 0) + coalesce(vestoque_p, 0);
  end
  suspend;
end ^

ALTER PROCEDURE GETLIMITECREDITOS (PCPFCGC VARCHAR(18) CHARACTER SET NONE,
PCOD_CLIENTE INTEGER,
PCOD_EMPRESA INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE)
RETURNS (VALOR DOUBLE PRECISION,
QTDE INTEGER)
AS 
declare variable VSQL varchar(1000);
declare variable VFINANCEIRO_UNIFICADO char(1);
declare variable VVALOR double precision;
declare variable VQTDE integer;
begin
  /* Procedure Text */
  valor = 0;
  qtde  = 0;

  select empresa.financeiro_unificado from empresa where empresa.cod_empresa = :pcod_empresa into :vfinanceiro_unificado;

  if ((coalesce(ptipo, '') = 'CH') or (coalesce(ptipo, '') = 'A')) then
  begin
    vsql =
      ' select sum(coalesce(formpagamento.valordoc, 0)) soma, count(*) qtde from formpagamento
        left join empresa on empresa.cod_empresa = formpagamento.cod_empresa
        left join clientes on
          clientes.cod_cliente = formpagamento.cod_cliente
          and clientes.cod_empresa = formpagamento.cod_empresa
        inner join controles on
          controles.codigo_ctrl = formpagamento.cod_controle
          and controles.codigo_emp = formpagamento.cod_empresa
          and trim(coalesce(controles.exibir_doc, ''A'')) in ('''', ''A'', ''L'') ';

    if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
      vsql = vsql ||
        ' where clientes.cpfcgc = ''' || :pcpfcgc || ''' ';
    else
      vsql = vsql ||
        ' where formpagamento.cod_cliente = ' || :pcod_cliente;

    vsql = vsql ||
      ' and formpagamento.tipdoc = ''S1'' and formpagamento.tpdocs <> ''PRE'' and formpagamento.prcss is null ';

    if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
      vsql = vsql ||
        ' and empresa.codigo_unificadora = ' || :pcod_empresa;
    else
      vsql = vsql ||
        ' and formpagamento.cod_empresa = ' || :pcod_empresa;

    vsql = vsql ||
      ' and formpagamento.data_mov >= (current_date - 365) ';

    execute statement
      vsql into :vvalor, :vqtde;

    valor = coalesce(valor, 0) + coalesce(vvalor, 0);
    qtde  = coalesce(qtde, 0)  + coalesce(vqtde, 0);

    vsql =
      ' select sum(coalesce(controle_cheque.valor_ch, 0)) soma, count(*) qtde from controle_cheque
        left join empresa on empresa.cod_empresa = controle_cheque.cod_emp_mult
        left join clientes on
          clientes.cod_cliente = controle_cheque.cod_cliente
          and clientes.cod_empresa = controle_cheque.cod_emp_mult
        inner join controles on
          controles.codigo_ctrl = controle_cheque.codigo_ctrl
          and controles.codigo_emp = controle_cheque.codigo_emp
          and trim(coalesce(controles.exibir_doc, ''A'')) in ('''', ''A'', ''L'') ';

    if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
      vsql = vsql ||
        ' where clientes.cpfcgc = ''' || :pcpfcgc || ''' ';
    else
      vsql = vsql ||
        ' where controle_cheque.cod_cliente = ' || :pcod_cliente;

    vsql = vsql ||
      ' and (controle_cheque.status_ch is null or controle_cheque.status_ch = '''') ';

    if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
      vsql = vsql ||
        ' and empresa.codigo_unificadora = ' || :pcod_empresa;
    else
      vsql = vsql ||
        ' and controle_cheque.codigo_emp = ' || :pcod_empresa;

    execute statement
      vsql into :vvalor, :vqtde;

    valor = coalesce(valor, 0) + coalesce(vvalor, 0);
    qtde  = coalesce(qtde, 0)  + coalesce(vqtde, 0);
  end

  if ((coalesce(ptipo, '') = 'CC') or (coalesce(ptipo, '') = 'A')) then
  begin
    vsql =
      ' select sum(coalesce(formpagamento.valordoc, 0)) soma, count(*) qtde from formpagamento
        left join empresa on empresa.cod_empresa = formpagamento.cod_empresa
        left join clientes on
          clientes.cod_cliente = formpagamento.cod_cliente
          and clientes.cod_empresa = formpagamento.cod_empresa
        inner join controles on
          controles.codigo_ctrl = formpagamento.cod_controle
          and controles.codigo_emp = formpagamento.cod_empresa
          and trim(coalesce(controles.exibir_doc, ''A'')) in ('''', ''A'', ''L'') ';

    if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
      vsql = vsql ||
        ' where clientes.cpfcgc = ''' || :pcpfcgc || ''' ';
    else
      vsql = vsql ||
        ' where formpagamento.cod_cliente = ' || :pcod_cliente;

    vsql = vsql ||
      ' and formpagamento.tipdoc = ''S2'' and formpagamento.tpdocs <> ''PRE'' and formpagamento.prcss is null ';

    if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
      vsql = vsql ||
        ' and empresa.codigo_unificadora = ' || :pcod_empresa;
    else
      vsql = vsql ||
        ' and formpagamento.cod_empresa = ' || :pcod_empresa;

    execute statement
      vsql into :vvalor, :vqtde;

    valor = coalesce(valor, 0) + coalesce(vvalor, 0);
    qtde  = coalesce(qtde, 0)  + coalesce(vqtde, 0);

    vsql =
      ' select sum(coalesce(controle_creditos.valor_c, 0)) valor, count(*) qtde from controle_creditos
        left join empresa on empresa.cod_empresa = controle_creditos.cod_emp_mult
        left join clientes on
          clientes.cod_cliente = controle_creditos.cod_cliente
          and clientes.cod_empresa = controle_creditos.cod_emp_mult
        inner join controles on
          controles.codigo_ctrl = controle_creditos.codigo_ctrl
          and controles.codigo_emp = controle_creditos.codigo_emp
          and trim(coalesce(controles.exibir_doc, ''A'')) in ('''', ''A'', ''L'') ';

    if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
      vsql = vsql ||
        ' where clientes.cpfcgc = ''' || :pcpfcgc || ''' ';
    else
      vsql = vsql ||
        ' where controle_creditos.cod_cliente = ' || :pcod_cliente;

    vsql = vsql ||
      ' and (controle_creditos.status_c is null or controle_creditos.status_c = '''') ';

    if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpfcgc, '') <> '')) then
      vsql = vsql || ' and empresa.codigo_unificadora = ' || :pcod_empresa;
    else
      vsql = vsql || ' and controle_creditos.codigo_emp = ' || :pcod_empresa;

    execute statement
      vsql into :vvalor, :vqtde;

    valor = coalesce(valor, 0) + coalesce(vvalor, 0);
    qtde  = coalesce(qtde, 0)  + coalesce(vqtde, 0);
  end

  suspend;
end ^

ALTER PROCEDURE GETMATERIA_PRIMA_RECURSIVO (PNPED INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA INTEGER,
PQUANT DOUBLE PRECISION,
PQTDE_DIM_EST DOUBLE PRECISION)
RETURNS (RESULT VARCHAR(100) CHARACTER SET NONE)
AS 
declare variable VPRODUCAO_AUT_ESTOQUE_NEG double precision;
declare variable VEST_F_ACABADO double precision;
declare variable VESTOQUE_DISP_ACABADO double precision;
declare variable VESTOQUE_MATPRIMA_ACABADO double precision;
declare variable VQUANT_ITEM_ACABADO double precision;
declare variable VEST_F_ANT_ACABADO double precision;
declare variable VCUSTO_INDICE_ACABADO double precision;
declare variable VCUSTO_RATEIO_ACABADO double precision;
declare variable VPREC_CUS_PROD_ACABADO double precision;
declare variable VPREC_CUSM_PROD_ACABADO double precision;
declare variable VPESO_BRUT_PROD_ACABADO double precision;
declare variable VGRUPO_PROD_MPRIMA integer;
declare variable VCOD_PROD_MPRIMA char(6);
declare variable VCOD_GRADE_MPRIMA integer;
declare variable VIND_IND_MPRIMA integer;
declare variable VEST_F_MPRIMA double precision;
declare variable VESTOQUE_DISP_MPRIMA double precision;
declare variable VESTOQUE_RECURSIVO_MPRIMA double precision;
declare variable VQUANT_MPRIMA double precision;
declare variable VQTDE_PRODUCAO double precision;
declare variable VPREC_CUS_PROD_MPRIMA double precision;
declare variable VPREC_CUSM_PROD_MPRIMA double precision;
declare variable VPESO_BRUT_PROD_MPRIMA double precision;
declare variable VID_IND_A integer;
declare variable VPREC_CUS_MED_TEMP double precision;
declare variable VTEMP double precision;
declare variable VVALORPARARATEIO_MPRIMA double precision;
declare variable VRESULT varchar(100);
declare variable VEXISTE_GRADE integer;
begin
  /* Procedure Text */
  vqtde_producao = 0;
  result = 'OK';

  select value1_f from config_sistema
  where chave = 'producao_aut_estoque_neg'
  and cod_empresa = :pcod_empresa
  into: vproducao_aut_estoque_neg;

  select est_f, estoque from getestoquedisponivel(
    :pgrupo_prod,
    :pcod_prod,
    coalesce(:pcod_grade, 0),
    :pcod_empresa,
    0,
    '',
    0,
    0)
  into :vest_f_acabado, :vestoque_disp_acabado;

  if (coalesce(pqtde_dim_est, 0) > 0) then
  begin
    vest_f_acabado = coalesce(:vest_f_acabado, 0) - coalesce(pqtde_dim_est, 0);
    vestoque_disp_acabado = coalesce(vestoque_disp_acabado, 0)  - coalesce(pqtde_dim_est, 0);
  end

  select estoque from getestoque_recursivo(
    :pgrupo_prod,
    :pcod_prod,
    :pcod_empresa,
    coalesce(:pcod_grade, 0))
  into :vestoque_matprima_acabado;

  -- Produto acabado sem estoque
  if (coalesce(vestoque_disp_acabado, 0) >= 0) then
  begin
    result = 'PRODUTO ACABADO NAO ESTA COM ESTOQUE NEGATIVO';
    suspend;
    exit;
  end

  if (coalesce(vproducao_aut_estoque_neg, 0) = 0) then
    if (coalesce(vestoque_matprima_acabado, 0) <= 0) then
    begin
      result = 'MATERIA PRIMA SEM ESTOQUE SUFICIENTE';
      suspend;
      exit;
    end

  -- Produto acabado nao possui cadastro da grade na producao
  if (coalesce(pcod_grade, 0) <= 0) then
  begin
    select count(*) from cod_grade_prod cprod
    where cprod.grupo_prod = :pgrupo_prod
    and cprod.cod_prod = :pcod_prod
    and cprod.cod_empresa = :pcod_empresa
    and cprod.cod_grade > 0
      into :vexiste_grade;

    if ((coalesce(vexiste_grade, 0) > 0) and (coalesce(pcod_grade, 0) <= 0)) then
    begin
      result = 'PRODUTO ACABADO NAO POSSUI CADASTRO DA GRADE NA PRODUCAO';
      suspend;
      exit;
    end
  end
  
  select first 1 pa.id_ind from produtos_pdc_var pa
  where pa.grupo_prod = :pgrupo_prod
  and pa.cod_prod = :pcod_prod
  and pa.cod_grade = :pcod_grade
  and pa.cod_empresa = :pcod_empresa
  into :vid_ind_a;

  -- Produto acabado nao possui cadastro da grade na producao
  if ((coalesce(pcod_grade, 0) > 0) and (coalesce(vid_ind_a, 0) <= 0)) then
  begin
    result = 'PRODUTO ACABADO NAO POSSUI CADASTRO DA GRADE NA PRODUCAO';
    suspend;
    exit;
  end

  -- Estoque anterior do produto acabado
  vest_f_ant_acabado  = (coalesce(pquant, 0)) - abs(coalesce(vest_f_acabado, 0));

  -- Quantidade produto acabado
  if ((coalesce(vest_f_ant_acabado, 0) = 0) and (coalesce(pquant, 0) = abs(coalesce(vest_f_ant_acabado, 0)))) then
    vquant_item_acabado = coalesce(pquant, 0);
  else
    vquant_item_acabado = coalesce(pquant, 0) - coalesce(vest_f_ant_acabado, 0);

  -- Estoque materia prima menor que o da venda
  if (coalesce(vproducao_aut_estoque_neg, 0) = 1) then
    vquant_item_acabado = abs(coalesce(vest_f_acabado, 0));
  else if (coalesce(vquant_item_acabado, 0) > coalesce(vestoque_matprima_acabado, 0)) then
    vquant_item_acabado = coalesce(vestoque_matprima_acabado, 0);

  vtemp = 0;
  vprec_cus_med_temp = 0;
  vcusto_indice_acabado = 0;
  vcusto_rateio_acabado = 0;
  vprec_cus_prod_acabado = 0;
  vprec_cusm_prod_acabado = 0;
  vvalorpararateio_mprima = 0;
  for select ind.grupo_prod_mprima, ind.cod_prod_mprima,
    iif(coalesce(gr.cod_grade, 0) > 0, coalesce(gr.cod_grade, 0), 0),
    iif(coalesce(pm.id_ind, 0) > 0, coalesce(pm.id_ind_it, 0), 0),
    iif(coalesce(gr.cod_grade, 0) > 0, coalesce(gr.qtde, 0),
    coalesce(pr.est_f, 0)),
    (select estoque from getestoquedisponivel(
      ind.grupo_prod_mprima,
      ind.cod_prod_mprima,
      iif(coalesce(gr.cod_grade, 0) > 0, coalesce(gr.cod_grade, 0), 0),
      ind.cod_empresa,
      0,
      '',
      0,
      0)) estoque_disp_mprima,
    (select estoque from getestoque_recursivo(
      ind.grupo_prod_mprima,
      ind.cod_prod_mprima,
      ind.cod_empresa,
      iif(coalesce(gr.cod_grade, 0) > 0, coalesce(gr.cod_grade, 0), 0))) estoque_recursivo_mprima,
    iif(coalesce(pm.quant, 0) > 0, coalesce(pm.quant, 0), coalesce(ind.quant, 0)) quant,
    coalesce(pa.prec_cus_prod, 0) prec_cus_prod_acabado,
    coalesce(pa.prec_cusm_prod, 0) prec_cusm_prod_acabado,
    coalesce(pa.peso_brut_prod, 0) peso_brut_prod_acabado,
    coalesce(pr.prec_cus_prod, 0) prec_cus_prod_mprima,
    coalesce(pr.prec_cusm_prod, 0) prec_cusm_prod_mprima from indice_tecnico ind
    inner join produtos pa on
        pa.grupo_prod = ind.grupo_prod_acabado
        and pa.cod_prod = ind.cod_prod_acabado
        and pa.cod_empresa = ind.cod_empresa
    inner join produtos pr on
        pr.grupo_prod = ind.grupo_prod_mprima
        and pr.cod_prod = ind.cod_prod_mprima
        and pr.cod_empresa = ind.cod_empresa
    left join produtos_pdc_var_it pm on
        pm.id_ind = coalesce(:vid_ind_a, 0)
        and pm.grupo_prod = ind.grupo_prod_mprima
        and pm.cod_prod = ind.cod_prod_mprima
        and pm.cod_empresa = ind.cod_empresa
    left join cod_grade_prod gr on
        gr.grupo_prod = ind.grupo_prod_mprima
        and gr.cod_prod = ind.cod_prod_mprima
        and gr.cod_grade = coalesce(pm.cod_grade, 0)
        and gr.cod_empresa = ind.cod_empresa
    where ind.grupo_prod_acabado = :pgrupo_prod
    and ind.cod_prod_acabado = :pcod_prod
    and ind.cod_empresa = :pcod_empresa
    and coalesce(pa.criar_producao_aut, 'N') = 'S'
    and (select count(*) from temp_producao_aut tmp
         where tmp.nped = :pnped
         and tmp.tipo = :ptipo
         and tmp.cod_empresa = :pcod_empresa
         and tmp.grupo_prod_acabado = :pgrupo_prod
         and tmp.cod_prod_acabado = :pcod_prod
         and tmp.cod_grade_acabado = coalesce(:pcod_grade, 0)
         and tmp.grupo_prod_mprima = ind.grupo_prod_mprima
         and tmp.cod_prod_mprima = ind.cod_prod_mprima
         and tmp.cod_grade_mprima = coalesce(gr.cod_grade, 0)) = 0
  into :vgrupo_prod_mprima, :vcod_prod_mprima, :vcod_grade_mprima, :vind_ind_mprima,
    :vest_f_mprima, :vestoque_disp_mprima, :vestoque_recursivo_mprima, :vquant_mprima,
    :vprec_cus_prod_acabado, :vprec_cusm_prod_acabado, :vpeso_brut_prod_acabado,
    :vprec_cus_prod_mprima, :vprec_cusm_prod_mprima do
  begin
    -- Materia prima nao possui cadastro da grade na producao
    if ((coalesce(vcod_grade_mprima, 0) > 0) and (coalesce(vind_ind_mprima, 0) <= 0)) then
    begin
      result = 'MATERIA PRIMA NAO POSSUI CADASTRO DA GRADE NA PRODUCAO';
      suspend;
      exit;
    end

    -- Sem estoque na materia prima
    if (coalesce(vproducao_aut_estoque_neg, 0) = 0) then
      if ((coalesce(vestoque_disp_mprima, 0) + coalesce(vestoque_recursivo_mprima, 0)) < coalesce(vquant_mprima, 0)) then
      begin
        result = 'MATERIA PRIMA SEM ESTOQUE SUFICIENTE';
        suspend;
        exit;
      end

    -- Custo indico item acabado
    vcusto_indice_acabado = coalesce(vcusto_indice_acabado, 0) +
      (coalesce(vprec_cusm_prod_mprima, 0) * coalesce(vquant_mprima, 0));

    -- Materia prima tem estoque disponivel
    if (coalesce(vquant_mprima, 0) > 0) then
    begin
      if (coalesce(vqtde_producao, 0) > (coalesce(vestoque_disp_mprima, 0) + coalesce(vestoque_recursivo_mprima, 0)) / coalesce(vquant_mprima, 0)) then
        vqtde_producao = ((coalesce(vestoque_disp_mprima, 0) + coalesce(vestoque_recursivo_mprima, 0)) / coalesce(vquant_mprima, 0));
      else if (coalesce(vqtde_producao, 0) = 0) then
        vqtde_producao = ((coalesce(vestoque_disp_mprima, 0) + coalesce(vestoque_recursivo_mprima, 0)) / coalesce(vquant_mprima, 0));
    end
    else
      vqtde_producao = (coalesce(vestoque_disp_mprima, 0) + coalesce(vestoque_recursivo_mprima, 0));

    -- Preco de custo medio atual
    vtemp = coalesce(vtemp, 0) + (coalesce(vprec_cus_prod_mprima, 0) * coalesce(vquant_mprima, 0));
  end

  vprec_cus_med_temp = 0;
  -- Preco de custo medio atual
  vprec_cus_med_temp = coalesce(vprec_cus_med_temp, 0) +
    (coalesce(vtemp, 0) * (coalesce(vquant_item_acabado, 0) / coalesce(pquant, 0)));

  -- Preco de custo medio anterior
  if (coalesce(vest_f_ant_acabado, 0) > 0) then
    vprec_cus_med_temp = coalesce(vprec_cus_med_temp, 0) +
        (coalesce(vprec_cusm_prod_acabado, 0) * ((coalesce(pquant, 0) - coalesce(vquant_item_acabado, 0)) / coalesce(pquant, 0)));

  -- Preco de custo medio acabado
  vprec_cusm_prod_acabado = coalesce(vprec_cus_med_temp, 0);

  -- Preco de custo item acabado
  vprec_cus_prod_acabado = coalesce(vcusto_indice_acabado, 0);

  -- Custo indice acabado
  vcusto_indice_acabado = coalesce(vcusto_indice_acabado, 0) * coalesce(:vquant_item_acabado, 0);

  if (result = 'OK') then
  begin
    for select ind.grupo_prod_mprima, ind.cod_prod_mprima,
      iif(coalesce(gr.cod_grade, 0) > 0, coalesce(gr.cod_grade, 0), 0),
      iif(coalesce(pm.id_ind, 0) > 0, coalesce(pm.id_ind_it, 0), 0),
      iif(coalesce(gr.cod_grade, 0) > 0, coalesce(gr.qtde, 0), coalesce(pr.est_f, 0)),
      (select estoque from getestoquedisponivel(
        ind.grupo_prod_mprima,
        ind.cod_prod_mprima,
        iif(coalesce(gr.cod_grade, 0) > 0, coalesce(gr.cod_grade, 0), 0),
        ind.cod_empresa,
        0,
        '',
        0,
        0)) estoque_disp_mprima,
      (select estoque from getestoque_recursivo(
        ind.grupo_prod_mprima,
        ind.cod_prod_mprima,
        ind.cod_empresa,
        iif(coalesce(gr.cod_grade, 0) > 0, coalesce(gr.cod_grade, 0), 0))) estoque_recursivo_mprima,
      iif(coalesce(pm.quant, 0) > 0, coalesce(pm.quant, 0), coalesce(ind.quant, 0)) quant,
      coalesce(pr.prec_cus_prod, 0) prec_cus_prod,
      coalesce(pr.prec_cusm_prod, 0) prec_cusm_prod,
      coalesce(pr.peso_brut_prod, 0) peso_brut_prod from indice_tecnico ind
      inner join produtos pa on
        pa.grupo_prod = ind.grupo_prod_acabado
        and pa.cod_prod = ind.cod_prod_acabado
        and pa.cod_empresa = ind.cod_empresa
      inner join produtos pr on
        pr.grupo_prod = ind.grupo_prod_mprima
        and pr.cod_prod = ind.cod_prod_mprima
        and pr.cod_empresa = ind.cod_empresa
      left join produtos_pdc_var_it pm on
        pm.id_ind = coalesce(:vid_ind_a, 0)
        and pm.grupo_prod = ind.grupo_prod_mprima
        and pm.cod_prod = ind.cod_prod_mprima
        and pm.cod_empresa = ind.cod_empresa
      left join cod_grade_prod gr on
        gr.grupo_prod = ind.grupo_prod_mprima
        and gr.cod_prod = ind.cod_prod_mprima
        and gr.cod_grade = coalesce(pm.cod_grade, 0)
        and gr.cod_empresa = ind.cod_empresa
      where ind.grupo_prod_acabado = :pgrupo_prod
      and ind.cod_prod_acabado = :pcod_prod
      and ind.cod_empresa = :pcod_empresa
      and coalesce(pa.criar_producao_aut, 'N') = 'S'
      and (select count(*) from temp_producao_aut tmp
           where tmp.nped = :pnped
           and tmp.tipo = :ptipo
           and tmp.cod_empresa = :pcod_empresa
           and tmp.grupo_prod_acabado = :pgrupo_prod
           and tmp.cod_prod_acabado = :pcod_prod
           and tmp.cod_grade_acabado = coalesce(:pcod_grade, 0)
           and tmp.grupo_prod_mprima = ind.grupo_prod_mprima
           and tmp.cod_prod_mprima = ind.cod_prod_mprima
           and tmp.cod_grade_mprima = coalesce(gr.cod_grade, 0)) = 0
    into :vgrupo_prod_mprima, :vcod_prod_mprima, :vcod_grade_mprima, :vind_ind_mprima,
        :vest_f_mprima, :vestoque_disp_mprima, :vestoque_recursivo_mprima, :vquant_mprima,
        :vprec_cus_prod_mprima, :vprec_cusm_prod_mprima, :vpeso_brut_prod_mprima do
    begin
      insert into temp_producao_aut (
        nped,
        tipo,
        cod_empresa,
        grupo_prod_acabado,
        cod_prod_acabado,
        cod_grade_acabado,
        quant_ped_item_acabado,
        est_f_acabado,
        est_f_ant_acabado,
        estoque_disp_acabado,
        custo_indice_acabado,
        custo_rateio_acabado,
        prec_cus_prod_acabado,
        prec_cusm_prod_acabado,
        peso_un_acabado,
        peso_util_acabado,
        grupo_prod_mprima,
        cod_prod_mprima,
        cod_grade_mprima,
        quant_mprima,
        est_f_mprima,
        estoque_disp_mprima,
        qtde_producao,
        prec_cusm_prod_mprima,
        peso_un_mprima,
        peso_util_mprima
      )
      values (
        :pnped,
        :ptipo,
        :pcod_empresa,
        :pgrupo_prod,
        :pcod_prod,
        coalesce(:pcod_grade, 0),
        coalesce(:vquant_item_acabado, 0),
        coalesce(:vest_f_acabado, 0),
        coalesce(:vest_f_ant_acabado, 0),
        coalesce(:vestoque_disp_acabado, 0),
        coalesce(:vcusto_indice_acabado, 0),
        coalesce(:vcusto_rateio_acabado, 0),
        coalesce(:vprec_cus_prod_acabado, 0),
        coalesce(:vprec_cusm_prod_acabado, 0),
        iif(coalesce(:vpeso_brut_prod_acabado, 0) > 0, coalesce(:vpeso_brut_prod_acabado, 0), 1),
        iif(coalesce(:vpeso_brut_prod_acabado, 0) > 0, coalesce(:vpeso_brut_prod_acabado, 0), 1) * coalesce(:vquant_item_acabado, 0),
        :vgrupo_prod_mprima,
        :vcod_prod_mprima,
        coalesce(:vcod_grade_mprima, 0),
        coalesce(:vquant_mprima, 0),
        coalesce(:vest_f_mprima, 0),
        coalesce(:vestoque_disp_mprima, 0) + coalesce(:vestoque_recursivo_mprima, 0),
        coalesce(:vqtde_producao, 0),
        coalesce(:vprec_cusm_prod_mprima, 0),
        iif(coalesce(:vpeso_brut_prod_mprima, 0) > 0, coalesce(:vpeso_brut_prod_mprima, 0), 0),
        iif(coalesce(:vpeso_brut_prod_mprima, 0) > 0, coalesce(:vpeso_brut_prod_mprima, 0), 0) * coalesce(:vquant_mprima, 0)
      );
    end
  end
  suspend;
end;
 
 ^

ALTER PROCEDURE GETPRECOEMPRESAS (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESAS VARCHAR(50) CHARACTER SET NONE,
PCOD_TAB_PRECO INTEGER,
PUTILIZAR_PRECO VARCHAR(10) CHARACTER SET NONE)
RETURNS (PREC_TAB_PROD DOUBLE PRECISION,
PREC_PUBLICO DOUBLE PRECISION,
COD_TABELA INTEGER,
DESCR_TABELA VARCHAR(128) CHARACTER SET NONE,
TIPO_TABELA CHAR(1) CHARACTER SET NONE,
PRECO_TABELA DOUBLE PRECISION,
COD_PROMOCAO INTEGER,
DESCR_PROMOCAO VARCHAR(128) CHARACTER SET NONE,
TIPO_PROMOCAO CHAR(1) CHARACTER SET NONE,
DATA_INI TIMESTAMP,
DATA_FIM TIMESTAMP,
PRECO_PROMOCAO DOUBLE PRECISION)
AS 
declare variable VEMPRESA varchar(20);
declare variable VESTOQUE double precision;
declare variable VPREC_TAB_PROD double precision;
declare variable VPREC_PUBLICO double precision;
declare variable VCOD_TABELA integer;
declare variable VDESCR_TABELA varchar(128);
declare variable VTIPO_TABELA char(1);
declare variable VTABPRECO double precision;
declare variable VPROMPRECO double precision;
declare variable VCOD_PROMOCAO integer;
declare variable VDESCR_PROMOCAO varchar(128);
declare variable VTIPO_PROMOCAO char(1);
declare variable VDATA_INI timestamp;
declare variable VDATA_FIM timestamp;
begin
  /* Procedure Text */
  vprec_tab_prod = null;
  vprec_publico  = null;
  vtabpreco      = null;
  vprompreco     = null;

  prec_tab_prod  = null;
  prec_publico   = null;

  cod_tabela     = null;
  descr_tabela   = null;
  tipo_tabela    = null;
  preco_tabela   = null;

  cod_promocao   = null;
  descr_promocao = null;
  tipo_promocao  = null;
  data_ini       = null;
  data_fim       = null;
  preco_promocao = null;

  for select osplit from p_split (:pcod_empresas, ',')
    into :vempresa do
  begin
    if (trim(coalesce(putilizar_preco, '')) = 'PADRAO') then
    begin
      vestoque = 1;
    end
    else
    begin
      select estoque from getestoquedisponivel
          (:pgrupo_prod, :pcod_prod, 0, :vempresa, 0, '', 0, 0)
            into :vestoque;
    end

    if (coalesce(vestoque, 0) > 0) then
    begin
      select
      round(coalesce(produtos.prec_tab_prod, 0), 2) prec_tab_prod,
      round(coalesce(produtos.prec_publico, 0), 2) prec_publico from produtos
      where produtos.grupo_prod = :pgrupo_prod
      and produtos.cod_prod = :pcod_prod
      and produtos.cod_empresa = :vempresa
        into :vprec_tab_prod , :vprec_publico;

      if (trim(coalesce(putilizar_preco, '')) = 'PADRAO') then
      begin
        prec_tab_prod = vprec_tab_prod;
      end
      else if ((trim(coalesce(putilizar_preco, '')) = 'MAIOR') and (coalesce(vprec_tab_prod, 0) > coalesce(prec_tab_prod, 0))) then
      begin
        prec_tab_prod = vprec_tab_prod;
      end
      else if ((trim(coalesce(putilizar_preco, '')) = 'MENOR') and ((coalesce(prec_tab_prod, 0) = 0) or (coalesce(vprec_tab_prod, 0) < coalesce(prec_tab_prod, 0)))) then
      begin
        prec_tab_prod = vprec_tab_prod;
      end

      if (trim(coalesce(putilizar_preco, '')) = 'PADRAO') then
      begin
        prec_publico = vprec_publico;
      end
      else if ((trim(coalesce(putilizar_preco, '')) = 'MAIOR') and (coalesce(vprec_publico, 0) > coalesce(prec_publico, 0))) then
      begin
        prec_publico = vprec_publico;
      end
      else if ((trim(coalesce(putilizar_preco, '')) = 'MENOR') and ((coalesce(prec_publico, 0) = 0) or (coalesce(vprec_publico, 0) < coalesce(prec_publico, 0)))) then
      begin
        prec_publico = vprec_publico;
      end
            
      if (coalesce(pcod_tab_preco, 0) > 0) then
      begin
        select first 1
        promocao.cod_promocao,
        promocao.descr_promocao,
        tipo_preco.tipo,
        round(coalesce(promocao_produto.valor_promocao, 0), 2) from produtos
        inner join promocao_produto on
          promocao_produto.grupo_prod = produtos.grupo_prod
          and promocao_produto.cod_prod = produtos.cod_prod
          and promocao_produto.cod_empresa = produtos.cod_empresa
        inner join promocao on
          promocao.cod_promocao = promocao_produto.cod_promocao
          and promocao.cod_empresa = promocao_produto.cod_empresa
          and promocao.ativo = 1
        left join tipo_preco on
            tipo_preco.cod_tppreco = promocao_produto.cod_tppreco
            and tipo_preco.cod_empresa = promocao_produto.cod_empresa
        where promocao_produto.grupo_prod = :pgrupo_prod
        and promocao_produto.cod_prod = :pcod_prod
        and promocao_produto.cod_empresa = :vempresa
        and promocao_produto.cod_promocao = :pcod_tab_preco
          into :vcod_tabela, :vdescr_tabela, :vtipo_tabela, :vtabpreco;
      end
      else
      begin
        select
        0 cod_tabela,
        'PRECO PADRAO VAREJO' descr_tabela,
        'V' tipo_tabela,
        round(coalesce(produtos.prec_tab_prod, 0), 2) from produtos
        where produtos.grupo_prod = :pgrupo_prod
        and produtos.cod_prod = :pcod_prod
        and produtos.cod_empresa = :vempresa
          into :vcod_tabela, :vdescr_tabela, :vtipo_tabela, :vtabpreco;
      end  

      if (trim(coalesce(putilizar_preco, '')) = 'PADRAO') then
      begin
        cod_tabela   = vcod_tabela;
        descr_tabela = vdescr_tabela;
        tipo_tabela  = vtipo_tabela;
        preco_tabela = vtabpreco;
      end
      else if ((trim(coalesce(putilizar_preco, '')) = 'MAIOR') and (coalesce(vtabpreco, 0) > coalesce(preco_tabela, 0))) then
      begin
        cod_tabela   = vcod_tabela;
        descr_tabela = vdescr_tabela;
        tipo_tabela  = vtipo_tabela;
        preco_tabela = vtabpreco;
      end
      else if ((trim(coalesce(putilizar_preco, '')) = 'MENOR') and ((coalesce(preco_tabela, 0) = 0) or (coalesce(vtabpreco, 0) < coalesce(preco_tabela, 0)))) then
      begin
        cod_tabela   = vcod_tabela;
        descr_tabela = vdescr_tabela;
        tipo_tabela  = vtipo_tabela;
        preco_tabela = vtabpreco;
      end

      select first 1
      promocao.cod_promocao,
      promocao.descr_promocao,
      tipo_preco.tipo,
      promocao_produto.data_ini,
      promocao_produto.data_fim,
      case when(promocao_produto.porcentagem > 0) then
             round(produtos.prec_tab_prod, 2) - round((round(produtos.prec_tab_prod * promocao_produto.porcentagem) / 100), 2)
           else
             round(promocao_produto.valor_promocao, 2)
      end valor_promocao from produtos
      inner join promocao_produto on
        promocao_produto.grupo_prod = produtos.grupo_prod
        and promocao_produto.cod_prod = produtos.cod_prod
        and promocao_produto.cod_empresa = produtos.cod_empresa
      inner join promocao on promocao.cod_promocao = promocao_produto.cod_promocao
        and promocao.cod_empresa = promocao_produto.cod_empresa
        and promocao.ativo = 1
      inner join promocao_ordem_ec on
        promocao_ordem_ec.cod_promocao = promocao_produto.cod_promocao
        and promocao_ordem_ec.cod_empresa = promocao_produto.cod_empresa
      left join tipo_preco on tipo_preco.cod_tppreco = promocao_produto.cod_tppreco
        and tipo_preco.cod_empresa = promocao_produto.cod_empresa
--        and tipo_preco.tipo = 'P'
      where promocao_produto.grupo_prod = :pgrupo_prod
      and promocao_produto.cod_prod = :pcod_prod
      and promocao_produto.cod_empresa = :vempresa
      and current_date >= coalesce(promocao_produto.data_ini, promocao.data_ini)
      and current_date <= coalesce(promocao_produto.data_fim, promocao.data_fim)
      order by promocao_ordem_ec.ordem
        into :vcod_promocao, :vdescr_promocao, :vtipo_promocao, :vdata_ini, :vdata_fim, :vprompreco;

      if (trim(coalesce(putilizar_preco, '')) = 'PADRAO') then
      begin
        cod_promocao   = vcod_promocao;
        descr_promocao = vdescr_promocao;
        tipo_promocao  = vtipo_promocao;
        data_ini       = vdata_ini;
        data_fim       = vdata_fim;
        preco_promocao = vprompreco;
      end
      else if ((trim(coalesce(putilizar_preco, '')) = 'MAIOR') and (coalesce(vprompreco, 0) > coalesce(preco_promocao, 0))) then
      begin
        cod_promocao   = vcod_promocao;
        descr_promocao = vdescr_promocao;
        tipo_promocao  = vtipo_promocao;
        data_ini       = vdata_ini;
        data_fim       = vdata_fim;
        preco_promocao = vprompreco;
      end
      else if ((trim(coalesce(putilizar_preco, '')) = 'MENOR') and ((coalesce(preco_promocao, 0) = 0) or (coalesce(vprompreco, 0) < coalesce(preco_promocao, 0)))) then
      begin
        cod_promocao   = vcod_promocao;
        descr_promocao = vdescr_promocao;
        tipo_promocao  = vtipo_promocao;
        data_ini       = vdata_ini;
        data_fim       = vdata_fim;
        preco_promocao = vprompreco;
      end
    end

    if (trim(coalesce(putilizar_preco, '')) = 'PADRAO') then
      break;
  end

  suspend;
end;
 
 ^

ALTER PROCEDURE GETPRODUTOSACABADOS (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA INTEGER,
PQTDE DOUBLE PRECISION)
RETURNS (GRUPO_PROD INTEGER,
COD_PROD CHAR(6) CHARACTER SET NONE,
COD_GRADE INTEGER,
QTDE DOUBLE PRECISION)
AS 
begin
  /* Procedure Text */

  select produtos.grupo_prod, produtos.cod_prod, cod_grade_prod.cod_grade from produtos
  left join cod_grade_prod on
    cod_grade_prod.grupo_prod = produtos.grupo_prod
    and cod_grade_prod.cod_prod = produtos.cod_prod
    and cod_grade_prod.cod_grade = :pcod_grade
    and cod_grade_prod.cod_empresa = produtos.cod_empresa
  where produtos.grupo_prod = :pgrupo_prod
  and produtos.cod_prod = :pcod_prod
  and produtos.cod_empresa = :pcod_empresa
    into :grupo_prod, :cod_prod, :cod_grade;

  grupo_prod = coalesce(grupo_prod, 0);
  cod_prod = coalesce(cod_prod, '');
  cod_grade = coalesce(cod_grade, 0);
  qtde = coalesce(pqtde, 0);

  suspend;

  for select grupo_prod, cod_prod, cod_grade, qtde from getprodutosacabados_recursivo (
    :pgrupo_prod,
    :pcod_prod,
    :pcod_grade,
    :pcod_empresa,
    coalesce(:pqtde, 0))
    into :grupo_prod, :cod_prod, :cod_grade, :qtde do
  begin
    suspend;
  end
end ^

ALTER PROCEDURE GETPRODUTOSACABADOS_RECURSIVO (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA INTEGER,
PQTDE DOUBLE PRECISION)
RETURNS (GRUPO_PROD INTEGER,
COD_PROD CHAR(6) CHARACTER SET NONE,
COD_GRADE INTEGER,
QTDE DOUBLE PRECISION)
AS 
begin
  /* Procedure Text */

  for select indice_tecnico.grupo_prod_mprima, indice_tecnico.cod_prod_mprima,
    iif(coalesce(produtos_pdc_var_it.cod_grade, 0) > 0, coalesce(produtos_pdc_var_it.cod_grade, 0), 0) cod_grade,
    (iif(coalesce(produtos_pdc_var_it.quant, 0) > 0,
       coalesce(produtos_pdc_var_it.quant, 0),
       coalesce(indice_tecnico.quant, 0) )
           * coalesce(:pqtde, 0)) quant
  from indice_tecnico
  inner join produtos on
    produtos.grupo_prod = indice_tecnico.grupo_prod_mprima
    and produtos.cod_prod = indice_tecnico.cod_prod_mprima
    and produtos.cod_empresa = indice_tecnico.cod_empresa
  left join produtos_pdc_var on
    produtos_pdc_var.grupo_prod = :pgrupo_prod
    and produtos_pdc_var.cod_prod = :pcod_prod
    and produtos_pdc_var.cod_grade = :pcod_grade
    and produtos_pdc_var.cod_empresa = :pcod_empresa
  left join produtos_pdc_var_it on
    produtos_pdc_var_it.id_ind = produtos_pdc_var.id_ind
    and produtos_pdc_var_it.cod_empresa = produtos_pdc_var.cod_empresa
    and produtos_pdc_var_it.grupo_prod =  indice_tecnico.grupo_prod_mprima
    and produtos_pdc_var_it.cod_prod = indice_tecnico.cod_prod_mprima
  where indice_tecnico.grupo_prod_acabado = :pgrupo_prod
  and indice_tecnico.cod_prod_acabado = :pcod_prod
  and indice_tecnico.cod_empresa = :pcod_empresa
  and produtos.criar_producao_aut = 'S'
    into :grupo_prod, :cod_prod, :cod_grade, :qtde do
  begin
    suspend;

    for select grupo_prod, cod_prod, cod_grade, qtde from getprodutosacabados_recursivo (
      :grupo_prod,
      :cod_prod,
      :cod_grade,
      :pcod_empresa,
      coalesce(:qtde, 0))
      into :grupo_prod, :cod_prod, :cod_grade, :qtde do
    begin
      suspend;
    end
  end
end ^

ALTER PROCEDURE GETPRODUTOSSIMILAR (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA VARCHAR(6) CHARACTER SET NONE)
RETURNS (EXISTESIMILAR INTEGER)
AS 
begin
  execute statement
   'select first 1 ps.grupo_ps from prod_similares ps
    inner join produtos p on ps.cod_ps = p.cod_prod and ps.grupo_ps = p.grupo_prod and p.cod_empresa = ps.cod_empresa
    where ps.cod_prod = '||:pcod_prod||'
    and ps.grupo_prod = '''||:pgrupo_prod||'''
    and p.cod_empresa in ('''||pcod_empresa||''')
    and ps.ativo = 1
    and p.ativo = 1
    and (select estoque from getestoquedisponivel(ps.grupo_ps, ps.cod_ps, 0, ps.cod_empresa, 0, '''', 0, 0)) > 0 '
    into :existesimilar;

  existesimilar = iif(coalesce(existesimilar, 0) > 0, 1, 0);
  suspend;
end ^

ALTER PROCEDURE GETPRODUTOSSIMILARGRUPO (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA VARCHAR(50) CHARACTER SET NONE)
RETURNS (EXISTESIMILAR INTEGER)
AS 
begin
  execute statement
   'select first 1 ps.grupo_prod from prod_similares_grupos_itens ps
    inner join produtos p on ps.grupo_prod = p.grupo_prod and ps.cod_prod = p.cod_prod and ps.cod_empresa = p.cod_empresa
    where ps.cod_grupo_sim in
      (select first 1 distinct ps1.cod_grupo_sim from prod_similares_grupos_itens ps1
       inner join prod_similares_grupos pp on pp.cod_grupo_sim = ps1.cod_grupo_sim and pp.cod_empresa = ps1.cod_empresa
       inner join produtos p on ps1.grupo_prod = p.grupo_prod and ps1.cod_prod = p.cod_prod and ps1.cod_empresa = p.cod_empresa
       where ps1.grupo_prod = '||:pgrupo_prod||'
       and ps1.cod_prod = '''||:pcod_prod||'''
       and ps1.cod_empresa in ('''||:pcod_empresa||''')
       and pp.ativo = 1
       and p.ativo = 1)
    and ps.cod_empresa in ('''||:pcod_empresa||''')
    and not(ps.grupo_prod = '||:pgrupo_prod||' and ps.cod_prod = '''||:pcod_prod||''')
    and (select estoque from getestoquedisponivel(ps.grupo_prod, ps.cod_prod, 0, ps.cod_empresa, 0, '''', 0, 0)) > 0'
    into :existesimilar;

  existesimilar = iif(coalesce(existesimilar, 0) > 0, 1, 0);
  suspend;
end ^

