       and p.ativo = 1)
    and ps.cod_empresa in ('''||:pcod_empresa||''')
    and not(ps.grupo_prod = '||:pgrupo_prod||' and ps.cod_prod = '''||:pcod_prod||''')
    and (select estoque from getestoquedisponivel(ps.grupo_prod, ps.cod_prod, 0, ps.cod_empresa, 0, '''', 0, 0)) > 0'
    into :existesimilar;

  existesimilar = iif(coalesce(existesimilar, 0) > 0, 1, 0);
  suspend;
end ^

ALTER PROCEDURE GETPROXIMONOSSONUMERO (VCOD_EMPRESA INTEGER,
VCOD_COBREBEM INTEGER)
RETURNS (NOSSONUMERO VARCHAR(20) CHARACTER SET NONE)
AS 
declare variable VDIG integer;
declare variable VPNUM varchar(20);
declare variable VNOVONUM varchar(20);
declare variable VINUM varchar(20);
declare variable J bigint;
declare variable VFNUM varchar(20);
declare variable F bigint;
declare variable I bigint;
begin
    select proximonossonumero, inicionossonumero, qtdedignossonumero,FIMNOSSONUMERO from cobrebem where cod_cobrebem = :vcod_cobrebem and
        cod_empresa = :vcod_empresa into :vpnum, :vinum, :vdig, :vfnum;

    if (:vpnum is null) then
        vpnum = :vinum;

    vpnum = trim(:vpnum);
    vfnum = trim(:vfnum);
    vinum = trim(:vinum);

    J = cast(:vpnum as bigint);
    F = cast(:vfnum as bigint);
    I = cast(:vinum as bigint);

    if (J >= F) then
    J = I;
    else
    J = J + 1;

    select result from strzero(:J,:vdig) into :vnovonum;
    update cobrebem set proximonossonumero = :vnovonum where cod_cobrebem = :vcod_cobrebem and
            cod_empresa = :vcod_empresa;
    nossonumero = :vpnum;
    suspend;
end ^

ALTER PROCEDURE GETQTDEITENSDEVOLVIDOS (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA VARCHAR(50) CHARACTER SET NONE,
PDATA TIMESTAMP)
RETURNS (VALORDEVOLVIDO DOUBLE PRECISION,
QTDEITEMDEVOLVIDO DOUBLE PRECISION)
AS 
begin
  execute statement
   'select sum(coalesce(quant, 0) * coalesce(valor, 0)) as SomaValorDevolvido,
    sum(coalesce(quant, 0)) as qtdItemDevolvido from devolucao
    where grupo_prod = '||:pgrupo_prod||'
    and cod_prod = '''||:pcod_prod||'''
    and cod_empresa in ('''||:pcod_empresa||''')
    and data >= '''||:pdata||'''
    and ativo = 1 ' ||
    iif(:pcod_grade > 0, ' and cod_grade = '|| :pcod_grade, '')
    into :valordevolvido, :qtdeitemdevolvido;

  valordevolvido    = coalesce(valordevolvido, 0);
  qtdeitemdevolvido = coalesce(qtdeitemdevolvido, 0);
  suspend;
end ^

ALTER PROCEDURE GETQTDEITENSPEDIDO (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA VARCHAR(50) CHARACTER SET NONE)
RETURNS (QTDEITEMPEDIDO DOUBLE PRECISION)
AS 
begin
  execute statement
    ' select sum(coalesce(it.quant_it_prod, 0)) as qtdItemPedido
      from item_pedido it
      inner join pedido pd on it.num_ped = pd.num_ped and it.cod_empresa = pd.cod_empresa
      where it.grupo_prod = '||:pgrupo_prod||'
      and it.cod_prod = '''||:pcod_prod||'''
      and coalesce(it.cod_emp_mult, it.cod_empresa) in ('''||:pcod_empresa||''')
      and pd.status_ped  = ''EFETIVADO''
      and pd.ativo = 1
      and coalesce(it.recebido, ''N'') = ''N'' '||
      iif(:pcod_grade > 0, ' and it.cod_grade = '|| :pcod_grade, '')
      into: qtdeitempedido;

  qtdeitempedido = coalesce(qtdeitempedido, 0);
  suspend;
end ^

ALTER PROCEDURE GETQTDEITENSPEDIDOREC (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA VARCHAR(50) CHARACTER SET NONE)
RETURNS (QTDEITEMPEDIDOREC DOUBLE PRECISION)
AS 
begin
  execute statement
    ' select sum(distinct(coalesce(ir.qtde_recebida,0))) qtdeRecebida
      from item_pedido it
      inner join pedido pd on it.num_ped = pd.num_ped and it.cod_empresa = pd.cod_empresa
      left join item_pedido_nf_rec ir on ir.num_ped = it.num_ped
      and ir.grupo_prod = it.grupo_prod and ir.cod_prod = it.cod_prod
      and ir.cod_empresa = it.cod_empresa and ir.nitem = it.nitem
      where it.grupo_prod = '||:pgrupo_prod||'
      and it.cod_prod = '''||:pcod_prod||'''
      and coalesce(it.cod_emp_mult, it.cod_empresa) in ('''||:pcod_empresa||''')
      and pd.status_ped  = ''EFETIVADO''
      and pd.ativo = 1
      and coalesce(it.recebido, ''N'') = ''N'' ' ||
      iif(:pcod_grade > 0, ' and it.cod_grade = '|| :pcod_grade, '')
      into qtdeitempedidorec;

  qtdeitempedidorec = coalesce(qtdeitempedidorec, 0);
  suspend;
end ^

ALTER PROCEDURE GETQTDEITENSVENDA (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA VARCHAR(50) CHARACTER SET NONE,
PDATA TIMESTAMP,
PTIPOVENDAOS VARCHAR(500) CHARACTER SET NONE,
PTIPOSVENDA VARCHAR(500) CHARACTER SET NONE,
PTIPOSORIGEM VARCHAR(500) CHARACTER SET NONE)
RETURNS (QTDEITEMREQOS DOUBLE PRECISION)
AS 
begin
  execute statement
    ' select sum(ipv.quant_ped_item) as qtdItemREQOS from pedvenda pv
      inner join pedvenda_prod ipv on ipv.nped = pv.nped and ipv.tipo = pv.tipo and ipv.cod_empresa = pv.cod_empresa
      and (ipv.status is null or status = '''')
      where ipv.grupo_prod = '||:pgrupo_prod||'
      and ipv.cod_prod = '''||:pcod_prod||'''
      and pv.data_fech >= '''||:pdata||'''
      and ((pv.tipo = ''REQ'') or (pv.tipo = ''OS''
      and pv.tipo_os in '||:ptipovendaos||'))
      and pv.cod_empresa in ('''||:pcod_empresa||''')
      and pv.ativo = 1 '||
      iif(trim(:ptiposVenda) <> '', ' and '||:ptiposVenda, '') ||
      iif(trim(:ptiposorigem) <> '', ' and '||:ptiposorigem, '') ||
      iif(:pcod_grade > 0, ' and ipv.cod_grade = '|| :pcod_grade, '')
      into :qtdeitemreqos;

  qtdeitemreqos = coalesce(qtdeitemreqos, 0);
  suspend;
end ^

ALTER PROCEDURE GETQTDEITENSVENDAPERDIDA (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA VARCHAR(50) CHARACTER SET NONE,
PDATA TIMESTAMP)
RETURNS (QTDEITEMVNDPERD DOUBLE PRECISION)
AS 
begin
  execute statement
   'select sum(coalesce(vnp.quant_prod_vp, 0)) as qtdItemVndPerd from venda_perdida vnp
   inner join tipovp tp on vnp.codigo_vp = tp.codigo_vp and vnp.cod_empresa = tp.cod_empresa
   where vnp.grupo_prod = '||:pgrupo_prod||'
   and vnp.cod_prod = '''||:pcod_prod||'''
   and vnp.data_vnp >= '''||:pdata||'''
   and tp.ent_sug_vp = ''S''
   and vnp.cod_empresa in ('''||:pcod_empresa||''')
   and vnp.ativo = 1 '
   into: qtdeitemvndperd;

  qtdeitemvndperd = coalesce(qtdeitemvndperd, 0);
  suspend;
end ^

ALTER PROCEDURE INCREMENTA_CODIGO (VCOD_EMPRESA INTEGER,
VTABELA VARCHAR(32) CHARACTER SET NONE)
RETURNS (COD INTEGER)
AS 
  declare variable TAB varchar(32);
begin
  select distinct(TABELA)
  from CODIGO
  where TABELA = :VTABELA and
        COD_EMPRESA = :VCOD_EMPRESA
    into :TAB;

  if (:TAB is null) then
    insert into CODIGO (TABELA, COD_EMPRESA, VALOR)
    values (:VTABELA, :VCOD_EMPRESA, 0);

  update CODIGO
  set VALOR = coalesce(VALOR, 0) + 1
  where TABELA = :VTABELA and
        COD_EMPRESA = :VCOD_EMPRESA;

  select VALOR
  from CODIGO
  where TABELA = :VTABELA and
        COD_EMPRESA = :VCOD_EMPRESA
    into :COD;

  suspend;
end ^

ALTER PROCEDURE INCREMENTA_ETIQ (VCOD_EMPRESA INTEGER)
RETURNS (COD INTEGER)
AS 
declare variable VALOR bigint;
begin
  select VALOR from COD_ETIQ
  where COD_EMPRESA = :VCOD_EMPRESA
    into :VALOR;

  if (VALOR is null) then
    insert into COD_ETIQ (COD_EMPRESA, VALOR)
    values (:VCOD_EMPRESA, 0);

  update COD_ETIQ set VALOR = coalesce(VALOR, 0) + 1
  where COD_EMPRESA = :VCOD_EMPRESA;

  select VALOR from COD_ETIQ
  where COD_EMPRESA = :VCOD_EMPRESA
    into :COD;

  suspend;
end ^

ALTER PROCEDURE INCREMENTA_WS (VCOD_EMPRESA INTEGER,
VTABELA VARCHAR(32) CHARACTER SET NONE,
VSEQUENCIA VARCHAR(32) CHARACTER SET NONE)
RETURNS (COD INTEGER)
AS 
declare variable TAB varchar(32);
BEGIN 
     EXECUTE STATEMENT 'SELECT GEN_ID('||:VSEQUENCIA||', 1) FROM RDB$DATABASE' INTO :cod; 
     if (coalesce(cod, 0) <= 1) then
     BEGIN 
       SELECT MAX(VALOR) FROM CODIGO WHERE TABELA = :VTABELA INTO :cod; 
       if (coalesce(cod, 0) > 0) then
       BEGIN
         EXECUTE STATEMENT 'ALTER SEQUENCE '||:VSEQUENCIA||' RESTART WITH '|| CAST(:cod AS VARCHAR(128));
         EXECUTE STATEMENT 'SELECT GEN_ID('||:VSEQUENCIA||', 1) FROM RDB$DATABASE' INTO :cod;
       END
       else
       BEGIN
         EXECUTE STATEMENT 'ALTER SEQUENCE '||:VSEQUENCIA||' RESTART WITH 0 ';
         EXECUTE STATEMENT 'SELECT GEN_ID('||:VSEQUENCIA||', 1) FROM RDB$DATABASE' INTO :cod;
       END
    END 
    SUSPEND; 
END ^

ALTER PROCEDURE INSERIR_ETIQUETA_DADOS_TRANSP (PCOD_EMPRESA INTEGER)
RETURNS (RESULT VARCHAR(10) CHARACTER SET NONE)
AS 
declare variable VEXISTE_DADOS_TRANSP integer;
declare variable VCOD_TRANSP integer;
declare variable VCOD_MAX_TRANSP integer;
begin
  /* Procedure Text */
  RESULT = 'OK';

  select c.cod_empresa from cabecalho_etiqueta c
  where c.tabela = 'NOTAFISCAL_DANFE'
  and c.descricao = 'DADOS TRANSPORTE'
  and c.cod_empresa = :pcod_empresa into :vexiste_dados_transp;

  if (coalesce(vexiste_dados_transp, 0) <= 0) then
  begin
    select first 1 c.cod_etiqueta from cabecalho_etiqueta c
    where c.cod_empresa = :pcod_empresa
    order by c.cod_etiqueta desc into :vcod_max_transp;

    select cod from incrementa_codigo (:pcod_empresa, 'CABECALHO_ETIQUETA') into :vcod_transp;

    if ((coalesce(vcod_max_transp, 0) > 0)
       and (coalesce(vcod_max_transp, 0) + 1 > coalesce(vcod_transp, 0))) then
    begin
        vcod_transp = vcod_max_transp + 1;

        update codigo cd set cd.valor = coalesce(:vcod_max_transp, 0)
        where cd.tabela = 'CABECALHO_ETIQUETA'
        and cd.cod_empresa = :pcod_empresa;
    end

    -- Cabecalho
    INSERT INTO CABECALHO_ETIQUETA (COD_ETIQUETA, COD_EMPRESA, TAMANHO_P, DESCRICAO, TABELA, COLUNAS, COMPRIMENTO_P, LARGURA_P, DISTANCIA_ENTRECOL, TAMANHO_ETI_V, MARGEM_SUPERIOR, MARGEM_INFERIOR, MARGEM_ESQUERDA, MARGEM_DIREITA, ORIENTACAO, ATIVO, PORTA, AGENTE_ID, QUANT_IMPRESSAO)
    VALUES (:vcod_transp, :pcod_empresa, 'Custom Size', 'DADOS TRANSPORTE', 'NOTAFISCAL_DANFE', 1, 90, 105, 0, 90, 0, 0, 0, 0, 0, 1, NULL, NULL, 1);

