ALTER PROCEDURE INSERIR_ETIQUETA_DANFE_SIMP (PCOD_EMPRESA INTEGER)
RETURNS (RESULT VARCHAR(10) CHARACTER SET NONE)
AS 
declare variable VEXISTE_DANFE_SIMPL integer;
declare variable VCOD_DANFE integer;
declare variable VCOD_MAX_DANFE integer;
begin
  /* Procedure Text */
  result = 'OK';

  select c.cod_empresa from cabecalho_etiqueta c
  where c.tabela = 'NOTAFISCAL_DANFE'
  and c.descricao = 'DANFE SIMPLIFICADO'
  and c.cod_empresa = :pcod_empresa into :vexiste_danfe_simpl;

  if (coalesce(vexiste_danfe_simpl, 0) <= 0) then
  begin
    select first 1 c.cod_etiqueta from cabecalho_etiqueta c
    where c.cod_empresa = :pcod_empresa
    order by c.cod_etiqueta desc into :vcod_max_danfe;

    select cod from incrementa_codigo (:pcod_empresa, 'CABECALHO_ETIQUETA') into :vcod_danfe;

    if ((coalesce(vcod_max_danfe, 0) > 0)
       and (coalesce(vcod_max_danfe, 0) + 1 > coalesce(vcod_danfe, 0))) then
    begin
        vcod_danfe = vcod_max_danfe + 1;

        update codigo cd set cd.valor = coalesce(:vcod_max_danfe, 0)
        where cd.tabela = 'CABECALHO_ETIQUETA'
        and cd.cod_empresa = :pcod_empresa;
    end

    -- Cabecalho
    INSERT INTO CABECALHO_ETIQUETA (COD_ETIQUETA, COD_EMPRESA, TAMANHO_P, DESCRICAO, TABELA, COLUNAS, COMPRIMENTO_P, LARGURA_P, DISTANCIA_ENTRECOL, TAMANHO_ETI_V, MARGEM_SUPERIOR, MARGEM_INFERIOR, MARGEM_ESQUERDA, MARGEM_DIREITA, ORIENTACAO, ATIVO, PORTA, AGENTE_ID, QUANT_IMPRESSAO)
    VALUES (:vcod_danfe, :pcod_empresa, 'Custom Size', 'DANFE SIMPLIFICADO', 'NOTAFISCAL_DANFE', 1, 110, 90, 0, 110, 0, 0, 0, 0, 0, 1, NULL, NULL, 0);

    -- Campos
    INSERT INTO CAMPOS_ETIQUETA (COD_ETIQUETA, COD_CAMPOETI, COD_EMPRESA, DESCRICAO, CAMPO, CAMPOFIXO, VALORCAMPOFIXO, TAMANHO, NOME_FONTE, TAMANHO_FONTE, COR_FONTE, NEGRITO, ITALICO, SUBLINHADO, POSICAO_V, POSICAO_H, ATIVO, QTDCASASDEC, MASCARA, CAMPOCALCULADO, CAMPOCODBARRA, CAMPOIMAGEM, QUEBRA_LINHA, CODBARRA_VIS_TEXTO, CODBARRA_TIPO, ALTURA, COMPRIMENTO, ALINHAMENTO, FORMATO_MONETARIO, MASCARAR_VALOR, FORMULA, AUTOSIZE, BARCODE, AUTOWIDTH, STRETCH, CAMPOVARIAVEL, TEXTOCAMPOVARIAVEL, CAMPOSISTEMA, TIPOSISTEMA, QTDEZEROESQUERDA, CASASDECIMAIS, VALOR_DEFAULT)
    VALUES (:vcod_danfe, 1, :pcod_empresa, 'DANFE SIMPLIFICADO - ETIQUETA', 'FIXO1', 'S', 'DANFE Simplificado - Etiqueta', 333, 'Arial', 10, 'clWindowText', 'S', 'N', 'N', 1, 1, 1, NULL, NULL, 'N', 'N', 'N', 'N', NULL, NULL, 16, 333, 'CENTRO', NULL, NULL, NULL, 'N', NULL, NULL, NULL, 'N', '', 'N', '', NULL, NULL, NULL);

    INSERT INTO CAMPOS_ETIQUETA (COD_ETIQUETA, COD_CAMPOETI, COD_EMPRESA, DESCRICAO, CAMPO, CAMPOFIXO, VALORCAMPOFIXO, TAMANHO, NOME_FONTE, TAMANHO_FONTE, COR_FONTE, NEGRITO, ITALICO, SUBLINHADO, POSICAO_V, POSICAO_H, ATIVO, QTDCASASDEC, MASCARA, CAMPOCALCULADO, CAMPOCODBARRA, CAMPOIMAGEM, QUEBRA_LINHA, CODBARRA_VIS_TEXTO, CODBARRA_TIPO, ALTURA, COMPRIMENTO, ALINHAMENTO, FORMATO_MONETARIO, MASCARAR_VALOR, FORMULA, AUTOSIZE, BARCODE, AUTOWIDTH, STRETCH, CAMPOVARIAVEL, TEXTOCAMPOVARIAVEL, CAMPOSISTEMA, TIPOSISTEMA, QTDEZEROESQUERDA, CASASDECIMAIS, VALOR_DEFAULT)
    VALUES (:vcod_danfe, 2, :pcod_empresa, 'OPERACAO:', 'FIXO2', 'S', 'OPERACAO:', 64, 'Arial', 8, 'clWindowText', 'S', 'N', 'N', 9, 23, 1, NULL, NULL, 'N', 'N', 'N', 'N', NULL, NULL, 12, 64, 'ESQUERDA', NULL, NULL, NULL, 'N', NULL, NULL, NULL, 'N', '', 'N', '', NULL, NULL, NULL);

