ALTER PROCEDURE KIT_COM_GRADE (PCODIGO_KIT INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (RESULT INTEGER)
AS 
declare variable VGRUPO_PROD integer;
declare variable VCOD_PROD char(6);
begin
  /* Procedure Text */
  result = 0;
  for  select distinct i.grupo_prod, i.cod_prod from kits_prod_kits i
       where i.codigo_kit = :pcodigo_kit
       and i.cod_empresa = :pcod_empresa
         into :vgrupo_prod, :vcod_prod do
  begin
     select first 1 iif(c.cod_empresa > 0, 1, 0)  from cod_grade_prod c
     where c.grupo_prod = :vgrupo_prod
     and c.cod_prod = :vcod_prod
     and c.cod_empresa = :pcod_empresa
        into result;

     if (result > 0) then
        break;
  end
  suspend;
end;
 
 ^

ALTER PROCEDURE MOVIMENTA_ESTOQUE (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PCOD_GRADE INTEGER,
PQTDE_ENTRADA DOUBLE PRECISION,
PQTDE_SAIDA DOUBLE PRECISION,
PALTDTULTVND INTEGER)
AS 
  declare variable PEXISTEGRADE smallint;
  declare variable PEXISTEMOVD smallint;
  declare variable VESTOQUE double precision;
  declare variable VCUSTOMEDIO double precision;
  declare variable CURRENT_TS timestamp;
  declare variable VESTPROD double precision;
  declare variable VCONTGRA integer;
begin
  select CURRENT_D
  from SP_CURRENT_TS(:PCOD_EMPRESA)
    into :CURRENT_TS;

  if (:pqtde_entrada > 0) then
  begin
    if (:paltdtultvnd > 0) then
    begin
      update produtos set est_f = coalesce(est_f, 0) + :pqtde_entrada, dt_ult_vnd = dt_ult_vnda
        where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa;
    end
    else
    begin
      update produtos set est_f = coalesce(est_f, 0) + :pqtde_entrada
        where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa;
    end

    if (:pcod_grade > 0) then
    begin
      pexistegrade = 0;
      select first 1 cod_grade from cod_grade_prod
        where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa
        and cod_grade = :pcod_grade into :pexistegrade;

      if (coalesce(:pexistegrade,0) > 0) then
      begin
        update cod_grade_prod set qtde = coalesce(qtde, 0) + :pqtde_entrada
          where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa
          and cod_grade = :pcod_grade;
      end
      else
      begin
        insert into cod_grade_prod (grupo_prod, cod_prod, cod_grade, cod_empresa, qtde, ativo)
          values (:pgrupo_prod, :pcod_prod, :pcod_grade, :pcod_empresa, :pqtde_entrada, 1);
      end
    end
  end
  else if (:pqtde_saida > 0) then
  begin
    if (:paltdtultvnd > 0) then
    begin
      update produtos set est_f = coalesce(est_f, 0) - :pqtde_saida, dt_ult_vnda = dt_ult_vnd, dt_ult_vnd = :CURRENT_TS
        where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa;
    end
    else
    begin
      update produtos set est_f = coalesce(est_f, 0) - :pqtde_saida
        where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa;
    end

    if (:pcod_grade > 0) then
    begin
      pexistegrade = 0;
      select first 1 cod_grade from cod_grade_prod
        where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa
        and cod_grade = :pcod_grade into :pexistegrade;

      if (coalesce(:pexistegrade,0) > 0) then
      begin
        update cod_grade_prod set qtde = coalesce(qtde, 0) - :pqtde_saida
          where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa
          and cod_grade = :pcod_grade;
      end
      else
      begin
        insert into cod_grade_prod (grupo_prod, cod_prod, cod_grade, cod_empresa, qtde, ativo)
          values (:pgrupo_prod, :pcod_prod, :pcod_grade, :pcod_empresa, ((-1) * :pqtde_saida), 1);
      end
    end
  end

  if (:pcod_grade > 0) then
  begin
    vestprod = 0;
    select est_f from produtos
    where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa
      into :vestprod;

    vestoque = 0;
    vcontgra = 0;
    select count(qtde), sum(qtde) from cod_grade_prod
    where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa
      into :vcontgra, :vestoque;

    if ((coalesce(vcontgra, 0) > 0) and
        (round(coalesce(vestprod, 0)) <> round(coalesce(vestoque, 0)))) then
      update produtos set est_f = :vestoque
      where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa;
  end

  pexisteMovD = 0;
  select first 1 cod_empresa from estoque_diario
    where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa
    and cod_grade = :pcod_grade and dia = :CURRENT_TS and tipo = 'P' into :pexisteMovD;
    
  select case when coalesce(gp.cod_grade, 0) > 0 then gp.qtde else p.est_f end, p.prec_cusm_prod
    from produtos p
    left join cod_grade_prod gp on gp.grupo_prod = p.grupo_prod and gp.cod_prod = p.cod_prod
      and gp.cod_empresa = p.cod_empresa and gp.cod_grade = :pcod_grade
    where p.grupo_prod = :pgrupo_prod and p.cod_prod = :pcod_prod and p.cod_empresa = :pcod_empresa
    into :vEstoque, :vCustoMedio;
    
  if (coalesce(:pexisteMovD,0) > 0) then
  begin
    update estoque_diario set estoque = :vEstoque, custo_medio = :vCustoMedio
      where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa
      and cod_grade = :pcod_grade and dia = :CURRENT_TS and tipo = 'P';
  end
  else
  begin
    insert into estoque_diario (grupo_prod, cod_prod, cod_empresa, cod_grade, dia, estoque, custo_medio, tipo, seqid )
      values (:pgrupo_prod, :pcod_prod, :pcod_empresa, :pcod_grade, :CURRENT_TS, :vEstoque, :vCustoMedio, 'P', gen_id(INC_ESTOQUE_DIARIO, 1));
  end
end
 
 ^

ALTER PROCEDURE MOVIMENTA_ESTOQUE_EC (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PCOD_GRADE INTEGER,
PQTDE_ENTRADA DOUBLE PRECISION,
PQTDE_SAIDA DOUBLE PRECISION)
AS 
declare variable PEXISTEGRADE smallint;
begin
  if (:pqtde_entrada > 0) then
  begin
    update produtos_ec set estoque_ec = estoque_ec + :pqtde_entrada
      where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa;


    if (:pcod_grade > 0) then
    begin
      pexistegrade = 0;
      select first 1 cod_grade from produtos_ec_grade
        where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa
        and cod_grade = :pcod_grade into :pexistegrade;

      if (coalesce(:pexistegrade,0) > 0) then
      begin
        update produtos_ec_grade set estoque_ec = estoque_ec + :pqtde_entrada
          where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa
          and cod_grade = :pcod_grade;
      end
      else
      begin
        insert into produtos_ec_grade (grupo_prod, cod_prod, cod_grade, cod_empresa, estoque_ec)
          values (:pgrupo_prod, :pcod_prod, :pcod_grade, :pcod_empresa, :pqtde_entrada);
      end
    end
  end
  else if (:pqtde_saida > 0) then
  begin
    update produtos_ec set estoque_ec = estoque_ec - :pqtde_saida
      where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa;

    if (:pcod_grade > 0) then
    begin
      pexistegrade = 0;
      select first 1 cod_grade from produtos_ec_grade
        where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa
        and cod_grade = :pcod_grade into :pexistegrade;

      if (coalesce(:pexistegrade,0) > 0) then
      begin
        update produtos_ec_grade set estoque_ec = estoque_ec - :pqtde_saida
          where grupo_prod = :pgrupo_prod and cod_prod = :pcod_prod and cod_empresa = :pcod_empresa
          and cod_grade = :pcod_grade;
      end
      else
      begin
        insert into produtos_ec_grade (grupo_prod, cod_prod, cod_grade, cod_empresa, estoque_ec)
          values (:pgrupo_prod, :pcod_prod, :pcod_grade, :pcod_empresa, ((-1) * :pqtde_saida));
      end
    end
  end
end;
 
 ^

ALTER PROCEDURE NUMERO_FABRICANTE (N_FABRICANTE VARCHAR(40) CHARACTER SET NONE,
COD_EMPRESA INTEGER)
AS 
DECLARE VARIABLE QTDE INTEGER;
BEGIN
   SELECT COUNT(NUM_FAB_PROD) FROM PRODUTOS
      WHERE NUM_FAB_PROD = :N_FABRICANTE
      and COD_EMPRESA = :COD_EMPRESA
   Into :QTDE;
   IF (QTDE > 0) then
      EXCEPTION EXC_NFABRICANTE;
END ^

ALTER PROCEDURE PAGAMENTOS_DET (PLOTE INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (CODIGO INTEGER,
TIPOLANC VARCHAR(10) CHARACTER SET NONE,
COD_EMPRESA INTEGER,
COD_EMP_MULT INTEGER,
LOTE INTEGER,
NATUREZA CHAR(1) CHARACTER SET NONE,
HISTORICO VARCHAR(100) CHARACTER SET NONE,
COD_CLIENTE INTEGER,
CODIGO_CTRL INTEGER,
N_CONTA_PLC DOUBLE PRECISION,
NCHEQUE VARCHAR(20) CHARACTER SET NONE,
NDOC VARCHAR(20) CHARACTER SET NONE,
VALOR DOUBLE PRECISION,
DATA TIMESTAMP,
DATAVENCIMENTO TIMESTAMP,
DTREFERENCIA TIMESTAMP,
DATAQUITACAO TIMESTAMP,
NPARCELA INTEGER)
AS 
begin
  /* Procedure Text */
  if (coalesce(plote, 0) <= 0) then
  begin
    suspend;
    exit;
  end

  for select * from (
    select lanc.cod_lanc as codigo, 'LANC' tipolanc,
    lanc.codigo_emp as cod_empresa, lanc.cod_emp_mult, lanc.lote as lote,
    lanc.tipo_l as natureza, lanc.historico_l as historico, null cod_cliente, lanc.codigo_ctrl, lanc.n_conta_plc,
    lanc.n_cheq_l as ncheque, lanc.ndoc_l as ndoc, lanc.valor_l, lanc.data, null datavencimento,
    lanc.dtreferencia, lanc.datq_l as dataquitacao, null nparcela from lancamentos lanc
    inner join controles ctrl on ctrl.codigo_ctrl = lanc.codigo_ctrl and ctrl.codigo_emp = lanc.codigo_emp
    where ctrl.docs = 'N'
    union all
    select ch.codigo_ch as codigo, 'CH' tipolanc,
    coalesce(ch.cod_emp_lote, ch.codigo_emp) as cod_empresa, ch.cod_emp_mult, ch.lote as lote,
    'E' as natureza, ch.historico_ch as historico, ch.cod_cliente, ch.codigo_ctrl, ch.n_conta_plc,
    ch.n_ch as ncheque, ch.n_doc_v as ndoc, ch.valor_ch, ch.data_rec as data, ch.data_venc as datavencimento,
    ch.data_rec as dtreferencia, ch.datq_ch as dataquitacao, null nparcela from controle_cheque ch
    union all
    select cc.cod_cred as codigo, 'CC' tipolanc,
    coalesce(cc.cod_emp_lote, cc.codigo_emp) as cod_empresa, cc.cod_emp_mult, cc.lote as lote,
    'E' as natureza, cc.historico_c as historico, cc.cod_cliente, cc.codigo_ctrl, cc.n_conta_plc,
    null ncheque, cc.n_doc_c as ndoc, cc.valor_c, cc.data_rec_c as data, cc.data_venc_c as datavencimento,
    cc.data_rec_c as dtreferencia, cc.datq_c as dataquitacao, cc.nparcela from controle_creditos cc
    union all
    select bc.cod_cred as codigo, 'CC' tipolanc,
    coalesce(bc.cod_emp_lote, bc.codigo_emp) as cod_empresa, bc.cod_emp_mult, bc.lote as lote,
    'E' as natureza, bc.historico_c as historico, bc.cod_cliente, bc.codigo_ctrl, cc.n_conta_plc,
    null ncheque,bc.n_doc_c, bc.valor_quitado, bc.data_rec_c as data, bc.data_venc_c as datavencimento,
    bc.data_rec_c as dtreferencia, bc.datq_c as dataquitacao, cc.nparcela from baixa_creditos bc
    inner join controle_creditos cc on cc.cod_cred = bc.cod_cred and cc.codigo_emp = bc.codigo_emp
    where bc.tip_baixa = 'P'
  ) pag
  where pag.lote = :plote
  and pag.cod_empresa = :pcod_empresa
    into :codigo, :tipolanc,
        :cod_empresa, :cod_emp_mult, :lote,
        :natureza, :historico, :cod_cliente, :codigo_ctrl, :n_conta_plc,
        :ncheque, :ndoc, :valor, :data, :datavencimento, :dtreferencia, :dataquitacao, :nparcela do
     suspend;
end ^

ALTER PROCEDURE POS (SUBSTR VARCHAR(100) CHARACTER SET NONE,
STR VARCHAR(100) CHARACTER SET NONE)
RETURNS (RESULT INTEGER)
AS 
declare variable substr2 varchar(201); /* 1 + SubStr-lenght + Str-length */
declare variable tmp varchar(100);
BEGIN
IF (SubStr IS NULL OR Str IS NULL)
THEN BEGIN result = NULL; EXIT; END
SubStr2 = SubStr || '%';
Tmp = '';
result = 1;
WHILE (Str NOT LIKE SubStr2 AND Str NOT LIKE Tmp) DO BEGIN
SubStr2 = '_' || SubStr2;
Tmp = Tmp || '_';
result = result + 1;
END
IF (Str LIKE Tmp) THEN result = 0;
SUSPEND;
END ^

ALTER PROCEDURE P_SPLIT (ITEXTO VARCHAR(4000) CHARACTER SET NONE,
ISEPARADOR CHAR(1) CHARACTER SET NONE)
RETURNS (OSPLIT VARCHAR(20) CHARACTER SET NONE)
AS 
declare variable VTEXTO varchar(4000);
declare variable VPOSICAO integer;
declare variable VPOSICAO_INICIAL integer;
declare variable VSPLIT varchar(4000);
BEGIN
    vtexto = itexto;
    vposicao_inicial = 1;
    vposicao = 1;
    
    IF (iseparador IS NULL OR itexto IS NULL) THEN
    BEGIN
        -- Sair da funcao sem executar
    END
    ELSE
    BEGIN
        WHILE (CHAR_LENGTH(vtexto) > 0) DO
        BEGIN
            vposicao = POSITION (:iseparador, vtexto, vposicao_inicial);
            IF (vposicao <= 0) THEN
            BEGIN
                vsplit = SUBSTRING (:vtexto FROM :vposicao_inicial FOR
                        CHAR_LENGTH (:vtexto) - vposicao_inicial + 1);
                IF (NOT :vsplit IS NULL AND NOT :vsplit = '') THEN
                BEGIN
                    osplit = :vsplit;   
                    SUSPEND;
                END
                BREAK;
            END
            vsplit = SUBSTRING (:vtexto FROM :vposicao_inicial
                    FOR :vposicao - vposicao_inicial);
            IF (NOT :vsplit IS NULL AND NOT :vsplit = '') THEN
            BEGIN
                osplit = :vsplit;   
            END
            vsplit = NULL;
            vposicao_inicial = :vposicao + 1;
            SUSPEND;
        END
    END
END;
 
 ^

ALTER PROCEDURE RECEBIMENTOS_DET (PLOTE INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (CODIGO INTEGER,
TIPOLANC VARCHAR(10) CHARACTER SET NONE,
COD_EMPRESA INTEGER,
COD_EMP_MULT INTEGER,
LOTE INTEGER,
NATUREZA CHAR(1) CHARACTER SET NONE,
HISTORICO VARCHAR(100) CHARACTER SET NONE,
COD_CLIENTE INTEGER,
CODIGO_CTRL INTEGER,
N_CONTA_PLC DOUBLE PRECISION,
NCHEQUE VARCHAR(20) CHARACTER SET NONE,
NDOC VARCHAR(20) CHARACTER SET NONE,
VALOR DOUBLE PRECISION,
DATA TIMESTAMP,
DATAVENCIMENTO TIMESTAMP,
DTREFERENCIA TIMESTAMP,
DATAQUITACAO TIMESTAMP,
NPARCELA INTEGER,
NOSSO_NUMERO_BANCO VARCHAR(20) CHARACTER SET NONE,
COD_COBREBEM INTEGER,
COD_ADM INTEGER,
N_DOCNSU_ADM VARCHAR(10) CHARACTER SET NONE,
N_AUT_CART VARCHAR(20) CHARACTER SET NONE,
TAXA_COBRANCA DOUBLE PRECISION)
AS 
begin
  /* Procedure Text */
  if (coalesce(plote, 0) <= 0) then
  begin
    suspend;
    exit;
  end

  for select * from (
    select lanc.cod_lanc as codigo, 'LANC' tipolanc,
    lanc.codigo_emp as cod_empresa, lanc.cod_emp_mult, lanc.lote_ent as lote,
    lanc.tipo_l as natureza, lanc.historico_l as historico, null cod_cliente,  lanc.codigo_ctrl, lanc.n_conta_plc,
    lanc.n_cheq_l as ncheque, lanc.ndoc_l as ndoc, lanc.valor_l, lanc.data, null datavencimento,
    lanc.dtreferencia, lanc.datq_l as dataquitacao, null nparcela,
    null nosso_numero_banco, null cod_cobrebem,
    null cod_adm, null n_docnsu_adm, null n_aut_cart, null taxa_cobranca from lancamentos lanc
    where lanc.tipo_l = 'E'
    union all
    select ch.codigo_ch as codigo, 'CH' tipolanc,
    ch.codigo_emp as cod_empresa, ch.cod_emp_mult, ch.lote_ent as lote,
    'E' as natureza, ch.historico_ch as historico, ch.cod_cliente, ch.codigo_ctrl, ch.n_conta_plc,
    ch.n_ch as ncheque, ch.n_doc_v as ndoc, ch.valor_ch, ch.data_rec as data, ch.data_venc as datavencimento,
    ch.data_rec as dtreferencia, ch.datq_ch as dataquitacao, null nparcela,
    null nosso_numero_banco, null cod_cobrebem,
    null cod_adm, null n_docnsu_adm, null n_aut_cart, null taxa_cobranca  from controle_cheque ch
    union all
    select cc.cod_cred as codigo, 'CC' tipolanc,
    cc.codigo_emp as cod_empresa, cc.cod_emp_mult, cc.lote_ent as lote,
    'E' as natureza, cc.historico_c as historico, cc.cod_cliente, cc.codigo_ctrl, cc.n_conta_plc,
    null ncheque, cc.n_doc_c as ndoc, cc.valor_c, cc.data_rec_c as data, cc.data_venc_c as datavencimento,
    cc.data_rec_c as dtreferencia, cc.datq_c as dataquitacao, cc.nparcela,
    cc.nosso_numero_banco, cc.cod_cobrebem,
    cc.cod_adm, cc.n_docnsu_adm, cc.n_aut_cart, cc.taxa_cobranca from controle_creditos cc
    union all
    select bc.cod_cred as codigo, 'CC' tipolanc,
    bc.codigo_emp as cod_empresa, bc.cod_emp_mult, bc.lote_ent as lote,
    'E' as natureza, bc.historico_c as historico, bc.cod_cliente, bc.codigo_ctrl, cc.n_conta_plc,
    null ncheque,bc.n_doc_c, bc.valor_quitado, bc.data_rec_c as data, bc.data_venc_c as datavencimento,
    bc.data_rec_c as dtreferencia, bc.datq_c as dataquitacao, cc.nparcela,
    cc.nosso_numero_banco, cc.cod_cobrebem,
    cc.cod_adm, cc.n_docnsu_adm, cc.n_aut_cart, cc.taxa_cobranca from baixa_creditos bc
    inner join controle_creditos cc on cc.cod_cred = bc.cod_cred and cc.codigo_emp = bc.codigo_emp
    where bc.tip_baixa = 'P'
  ) rec
  where rec.lote = :plote
  and rec.cod_empresa = :pcod_empresa
    into :codigo, :tipolanc,
        :cod_empresa, :cod_emp_mult, :lote,
        :natureza, :historico, :cod_cliente, :codigo_ctrl, :n_conta_plc,
        :ncheque, :ndoc, :valor, :data, :datavencimento, :dtreferencia, :dataquitacao, :nparcela,
        :nosso_numero_banco, :cod_cobrebem,
        :cod_adm, :n_docnsu_adm, :n_aut_cart, :taxa_cobranca do
    suspend;
end ^

ALTER PROCEDURE REC_PREST_PROG_FID_DET (PDTINI TIMESTAMP,
PDTFIM TIMESTAMP,
PCODCLIENTE INTEGER,
PCOD_EMPRESA INTEGER,
PREGRA VARCHAR(60) CHARACTER SET NONE,
PCOD_CRED INTEGER,
PSIMULACAO CHAR(1) CHARACTER SET NONE)
RETURNS (COD_CRED INTEGER,
DATQ_C TIMESTAMP,
DATA_VENC_C TIMESTAMP,
COD_EMPRESA INTEGER,
DIAS DOUBLE PRECISION,
TIPO VARCHAR(10) CHARACTER SET NONE,
PERC_DIA_REAL DOUBLE PRECISION,
CARENCIA DOUBLE PRECISION)
AS 
declare variable VCARENCIA integer;
declare variable VPERC_ENT double precision;
declare variable VCRED integer;
declare variable VTEMP varchar(100);
declare variable VTEMP2 varchar(1000);
begin
  VTEMP = '';
  VTEMP2 = '';

  if (COALESCE(PCOD_CRED, 0) > 0) then
  begin
    VTEMP = ' cr.cod_cred = '||:pcod_cred||' ';
  end
  else
  begin
    VTEMP = ' cr.dia_cxl >= '''||:pdtini||''' and cr.dia_cxl <= '''||:pdtfim||''' ';
  end

  if (COALESCE(psimulacao,  'N') = 'S') then
  begin
    VTEMP2 = '  and (case when (cr.tp_doc_v = ''MOT'') then
                coalesce(tpv.venda, ''N'')
              else
                case when (pd.tipo = ''REQ'') then
                       coalesce(tpreq.venda, ''N'')
                     else
                       coalesce(tpord.venda, ''N'')
                end
        end) = ''S''
    and (case when (cr.tp_doc_v = ''MOT'') then
                 coalesce(tpv.gerar_pontos, ''N'')
               else
                 case when (pd.tipo = ''REQ'') then
                        coalesce(tpreq.gerar_pontos, ''N'')
                      else
                        coalesce(tpord.gerar_pontos, ''N'')
                 end
         end) = ''S'' ';
  end
  else
  begin
    VTEMP2 = '  and (case when (cr.tp_doc_v = ''MOT'') then
                coalesce(cf.tp_venda, coalesce(tpv.venda, ''N''))
              else
                case when (pd.tipo = ''REQ'') then
                       coalesce(pd.tp_venda, coalesce(tpreq.venda, ''N''))
                     else
                       coalesce(pd.tp_venda, coalesce(tpord.venda, ''N''))
                end
        end) = ''S''
    and (case when (cr.tp_doc_v = ''MOT'') then
                 coalesce(cf.tp_gerar_pontos, coalesce(tpv.gerar_pontos, ''N''))
               else
                 case when (pd.tipo = ''REQ'') then
                        coalesce(pd.tp_gerar_pontos, coalesce(tpreq.gerar_pontos, ''N''))
                      else
                        coalesce(pd.tp_gerar_pontos, coalesce(tpord.gerar_pontos, ''N''))
                 end
         end) = ''S'' ';
  end

  for execute statement
   ' select cr.cod_cred, cr.dia_cxl, cr.data_venc_c, cr.codigo_emp, emp.dias_car_juros from controle_creditos cr
    inner join clientes cl on cr.cod_cliente = cl.cod_cliente and cr.cod_emp_mult = cl.cod_empresa
    inner join controles ctrl on cr.codigo_ctrl = ctrl.codigo_ctrl and cr.codigo_emp = ctrl.codigo_emp
    inner join empresa emp on emp.cod_empresa = cr.codigo_emp
    left join pedvenda pd on cr.n_doc_v = pd.nped and cr.tp_doc_v = pd.tipo and cr.codigo_emp = pd.cod_empresa
    left join tipo_vendas tpreq on trim(tpreq.tipo) = ''REQ'' and tpreq.sigla = pd.tipv
    left join tipo_vendas tpord on trim(tpord.tipo) = ''OS'' and tpord.tipo_os = pd.tipo_os
    left join com_fat cf on cr.n_doc_v = cf.n_comando and cr.tp_doc_v = ''MOT'' and cr.codigo_emp = cf.cod_empresa
    left join tipo_vendas tpv on trim(tpv.tipo) = ''VEI'' and tpv.tipo_os = cf.tipo_v
    left join tipo_faturamento tf on tf.codigo_faturamento = cl.codigo_faturamento and tf.ativo = 1 
    where '||VTEMP||'
    and ctrl.entra_prest_cxl = ''S''
    and cr.codigo_emp = '||:pcod_empresa||'
    and cr.tp_doc_v in (''REQ'', ''OS'', ''MOT'')
    and (coalesce((select count(*) from formpagamento fp
    where fp.nrequisicao = cr.lote_cxl and fp.tpdocs = ''PRE'' and fp.cod_empresa = cr.codigo_emp), 0) > 0)
    and (case when (cr.tp_doc_v = ''MOT'') then
                coalesce(cf.tp_venda, coalesce(tpv.venda, ''N''))
              else
                case when (pd.tipo = ''REQ'') then
                       coalesce(pd.tp_venda, coalesce(tpreq.venda, ''N''))
                     else
                       coalesce(pd.tp_venda, coalesce(tpord.venda, ''N''))
                end
        end) = ''S''
    and (case when (cr.tp_doc_v = ''MOT'') then
                 coalesce(cf.tp_gerar_pontos, coalesce(tpv.gerar_pontos, ''N''))
               else
                 case when (pd.tipo = ''REQ'') then
                        coalesce(pd.tp_gerar_pontos, coalesce(tpreq.gerar_pontos, ''N''))
                      else
                        coalesce(pd.tp_gerar_pontos, coalesce(tpord.gerar_pontos, ''N''))
                 end
         end) = ''S''
    and coalesce(cl.cl_gerar_pontos, ''S'') <> ''N''
    and coalesce(tf.status_f, '''') <> ''BARRADO''
    and cr.cod_cliente <> '||:pcodcliente
  into :cod_cred, :datq_c, :data_venc_c, :cod_empresa, :carencia do
  begin
     dias = abs(:datq_c - :data_venc_c);
     tipo = '';

     if ((coalesce(:carencia, 0) > 0) and (:datq_c > :data_venc_c) and ((:datq_c - :data_venc_c) <= coalesce(:vcarencia, 0))) then
     begin
       select first 1 trim(coalesce(crf.valor_vc, '')), coalesce(crf.perc_dia_real, 0) from regras_prog_fidelidade rf
       inner join config_regras_prog_fidelidade crf on crf.cod_tp_regra = rf.cod_tp_regra and crf.cod_empresa = rf.cod_empresa
       where rf.descricao_regra = :pregra and rf.cod_empresa = :pcod_empresa
       and trim(coalesce(crf.valor_vc, '')) = 'PC'
         into :tipo, :perc_dia_real;
     end
     else if (:datq_c = :data_venc_c) then
     begin
       select first 1 trim(coalesce(crf.valor_vc, '')), coalesce(crf.perc_dia_real, 0) from regras_prog_fidelidade rf
       inner join config_regras_prog_fidelidade crf on crf.cod_tp_regra = rf.cod_tp_regra and crf.cod_empresa = rf.cod_empresa
       where rf.descricao_regra = :pregra and rf.situacao = 'ATIVA' and rf.cod_empresa = :pcod_empresa
       and trim(coalesce(crf.valor_vc, '')) = 'PDV'
         into :tipo, :perc_dia_real;
     end
     else if (:datq_c > :data_venc_c) then
     begin
       select first 1 trim(coalesce(crf.valor_vc, '')), coalesce(crf.perc_dia_real, 0) from regras_prog_fidelidade rf
       inner join config_regras_prog_fidelidade crf on crf.cod_tp_regra = rf.cod_tp_regra and crf.cod_empresa = rf.cod_empresa
       where rf.descricao_regra = :pregra and rf.situacao = 'ATIVA' and rf.cod_empresa = :pcod_empresa
       and trim(coalesce(crf.valor_vc, '')) = 'PTX' and coalesce(crf.perc_dia_real, 0) <= :dias
       order by crf.perc_dia_real desc
         into :tipo, :perc_dia_real;

       if (trim(coalesce(tipo, '')) = '') then
       begin
         select first 1 trim(coalesce(crf.valor_vc, '')), coalesce(crf.perc_dia_real, 0) from regras_prog_fidelidade rf
         inner join config_regras_prog_fidelidade crf on crf.cod_tp_regra = rf.cod_tp_regra and crf.cod_empresa = rf.cod_empresa
         where rf.descricao_regra = :pregra and rf.situacao = 'ATIVA' and rf.cod_empresa = :pcod_empresa
         and trim(coalesce(crf.valor_vc, '')) = 'PT'
          into :tipo, :perc_dia_real;
       end
     end
     else
     begin
       select first 1 trim(coalesce(crf.valor_vc, '')), coalesce(crf.perc_dia_real, 0) from regras_prog_fidelidade rf
       inner join config_regras_prog_fidelidade crf on crf.cod_tp_regra = rf.cod_tp_regra and crf.cod_empresa = rf.cod_empresa
       where rf.descricao_regra = :pregra and rf.situacao = 'ATIVA' and rf.cod_empresa = :pcod_empresa
       and trim(coalesce(crf.valor_vc, '')) = 'PAX' and coalesce(crf.perc_dia_real, 0) <= :dias
       order by crf.perc_dia_real desc
         into :tipo, :perc_dia_real;

       if (trim(coalesce(tipo, '')) = '') then
       begin
         select first 1 trim(coalesce(crf.valor_vc, '')), coalesce(crf.perc_dia_real, 0) from regras_prog_fidelidade rf
         inner join config_regras_prog_fidelidade crf on crf.cod_tp_regra = rf.cod_tp_regra and crf.cod_empresa = rf.cod_empresa
         where rf.descricao_regra = :pregra and rf.situacao = 'ATIVA' and rf.cod_empresa = :pcod_empresa
         and trim(coalesce(crf.valor_vc, '')) = 'PA'
          into :tipo, :perc_dia_real;
       end
     end
     if (trim(coalesce(tipo, '')) <> '') then
       suspend;
  end
end;
 
 ^

ALTER PROCEDURE REMOVER_GRADE_PRODUTO (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (RESULT VARCHAR(10) CHARACTER SET NONE)
AS 
declare variable VGRUPO_PROD integer;
declare variable VCOD_PROD char(6);
declare variable VCOD_EMPRESA integer;
declare variable VCOD_GRADE integer;
declare variable VPREC_CUSM_PROD double precision;
declare variable VESTOQUE_GRADE double precision;
declare variable VESTOQUE_PROD double precision;
declare variable VSEQID integer;
declare variable VTEMP_SQL varchar(1000);
begin
  /* Procedure Text */
  result = 'ERRO';
  if ((pgrupo_prod > 0) or (trim(pcod_prod) <> '')) then
  begin
    vtemp_sql =
      ' where produtos.grupo_prod = ' || :pgrupo_prod || '
        and produtos.cod_prod = ''' || :pcod_prod || '''
        and produtos.cod_empresa = ' || :pcod_empresa;
  end
  else
  begin
    vtemp_sql =
      ' where produtos.cod_empresa = ' || :pcod_empresa;
  end

  for execute statement
    ' select produtos.grupo_prod, produtos.cod_prod, produtos.cod_empresa, produtos.prec_cusm_prod from produtos ' ||
      vtemp_sql || '
      and (select count(*) from cod_grade_prod
           where cod_grade_prod.grupo_prod = produtos.grupo_prod
           and cod_grade_prod.cod_prod = produtos.cod_prod
           and cod_grade_prod.cod_empresa = produtos.cod_empresa) > 0 '
        into :vgrupo_prod, :vcod_prod, :vcod_empresa, :vprec_cusm_prod do
  begin
    vestoque_prod = 0;
    for select cod_grade_prod.cod_grade, cod_grade_prod.qtde from cod_grade_prod
        where cod_grade_prod.grupo_prod = :vgrupo_prod
        and cod_grade_prod.cod_prod = :vcod_prod
        and cod_grade_prod.cod_empresa = :vcod_empresa
          into :vcod_grade, :vestoque_grade do
    begin
      vestoque_grade = coalesce(vestoque_grade, 0);
      vestoque_prod  = coalesce(vestoque_prod, 0) + coalesce(vestoque_grade, 0);

      select first 1 estoque_diario.seqid from estoque_diario
      where estoque_diario.grupo_prod = :vgrupo_prod
      and estoque_diario.cod_prod = :vcod_prod
      and estoque_diario.cod_grade = :vcod_grade
      and estoque_diario.dia = current_date
      and estoque_diario.cod_empresa = :pcod_empresa
        into :vseqid;

      if (coalesce(vseqid, 0) > 0) then
      begin
        update estoque_diario set estoque_diario.estoque = 0
        where estoque_diario.tipo = 'P'
        and estoque_diario.seqid = :vseqid
        and estoque_diario.cod_empresa = :vcod_empresa;
      end
      else
      begin
        insert into estoque_diario
        (tipo, seqid, cod_empresa, dia, grupo_prod, cod_prod, cod_grade, estoque, custo_medio)
        values ('P', (select cod from incrementa_codigo (:pcod_empresa, 'ESTOQUE_DIARIO')), :pcod_empresa,
        current_date, :vgrupo_prod, :vcod_prod, :vcod_grade, 0, coalesce(:vprec_cusm_prod, 0));
      end
    end

    select first 1 estoque_diario.seqid from estoque_diario
    where estoque_diario.grupo_prod = :vgrupo_prod
    and estoque_diario.cod_prod = :vcod_prod
    and estoque_diario.cod_grade = 0
    and estoque_diario.dia = current_date
    and estoque_diario.cod_empresa = :pcod_empresa
      into :vseqid;

    if (coalesce(vseqid, 0) > 0) then
    begin
      update estoque_diario set estoque_diario.estoque = coalesce(:vestoque_prod, 0)
      where estoque_diario.tipo = 'P'
      and estoque_diario.seqid = :vseqid
      and estoque_diario.cod_empresa = :vcod_empresa;
    end
    else
    begin
      insert into estoque_diario
      (tipo, seqid, cod_empresa, dia, grupo_prod, cod_prod, cod_grade, estoque, custo_medio)
      values ('P', (select cod from incrementa_codigo (:pcod_empresa, 'ESTOQUE_DIARIO')), :pcod_empresa,
      current_date, :vgrupo_prod, :vcod_prod, 0, coalesce(:vestoque_prod, 0), coalesce(:vprec_cusm_prod, 0));
    end

    update produtos set produtos.est_f = coalesce(:vestoque_prod, 0)
    where produtos.grupo_prod = :vgrupo_prod
    and produtos.cod_prod = :vcod_prod
    and produtos.cod_empresa = :pcod_empresa;

    delete from cod_grade_prod
    where cod_grade_prod.grupo_prod = :vgrupo_prod
    and cod_grade_prod.cod_prod = :vcod_prod
    and cod_grade_prod.cod_empresa = :pcod_empresa;

    delete from cod_grade_prod_compra
    where cod_grade_prod_compra.grupo_prod = :vgrupo_prod
    and cod_grade_prod_compra.cod_prod = :vcod_prod
    and cod_grade_prod_compra.cod_empresa = :vcod_empresa;

    update pedvenda_prod set pedvenda_prod.cod_grade = 0
    where pedvenda_prod.grupo_prod = :vgrupo_prod
    and pedvenda_prod.cod_prod = :vcod_prod
    and pedvenda_prod.cod_empresa = :pcod_empresa
    and pedvenda_prod.cod_grade > 0;
  end

  result = 'OK';
  suspend;
end;
 
 ^

ALTER PROCEDURE RESUMO_FINANCEIRO_UNIFICADO (PDTINI DATE,
PDTFIM DATE,
PCOD_EMPRESA INTEGER,
PREGIMECAIXA CHAR(1) CHARACTER SET NONE,
PTODASCONTAS CHAR(1) CHARACTER SET NONE,
PAGRUPARUNIFADA CHAR(1) CHARACTER SET NONE,
PCODEMPUNIFICADA INTEGER)
RETURNS (TPDTQUIT_DTREF INTEGER,
TIPO_DESP VARCHAR(10) CHARACTER SET NONE,
TIPO VARCHAR(11) CHARACTER SET NONE,
COD_EMPRESA INTEGER,
COD_EMP_MULT INTEGER,
N_CONTA_PLC DOUBLE PRECISION,
DTQUIT_DTREF TIMESTAMP,
NDOC VARCHAR(50) CHARACTER SET NONE,
VALOR DOUBLE PRECISION,
HISTORICO VARCHAR(200) CHARACTER SET NONE,
DATA TIMESTAMP,
COD_LANC INTEGER,
VALOR_PAGO DOUBLE PRECISION,
DESC_PADR VARCHAR(50) CHARACTER SET NONE,
DESC_SUB_CT VARCHAR(50) CHARACTER SET NONE,
FORNECEDOR VARCHAR(100) CHARACTER SET NONE,
NOME_CTRL VARCHAR(50) CHARACTER SET NONE,
EXIBIR_RESUMO_FINANCEIRO CHAR(1) CHARACTER SET NONE,
DATA_INI TIMESTAMP,
DATA_FIM TIMESTAMP,
ATIVO INTEGER,
ORDEM INTEGER,
DESC_GR VARCHAR(50) CHARACTER SET NONE,
DESC_DEP VARCHAR(50) CHARACTER SET NONE)
AS 
declare variable VCAMPO varchar(15);
declare variable VTEMP varchar(100);
declare variable VTEMPCODEMP varchar(100);
declare variable VTEMPTODAS varchar(2000);
declare variable VFINANCEIRO_UNIFICADO char(1);
declare variable VEMP_UNIFICADA integer;
begin
  /* Procedure Text */
  VCAMPO = 'COD_EMPRESA';
  VTEMP = '';
  VTEMPCODEMP = '';
  VTEMPTODAS = '';

  VFINANCEIRO_UNIFICADO = '';
  VEMP_UNIFICADA = 0;

  select codigo_unificadora, financeiro_unificado from empresa
  where cod_empresa = :pcod_empresa into :vemp_unificada, :vfinanceiro_unificado;

  if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (vemp_unificada > 0) and (pcodempunificada > 0)) then
  begin
    if (vemp_unificada = pcod_empresa) then
      VTEMPCODEMP = ' and cod_empresa = ' || pcodempunificada;
    else
      VTEMPCODEMP = ' and cod_empresa = ' || pcod_empresa;  
     VCAMPO = 'COD_EMP_MULT';
  end
  else
    VTEMPCODEMP = ' and cod_empresa = ' || pcod_empresa;
    
  if (pregimecaixa = 'S') then
    VTEMP = ' and tpdtquit_dtref = 1';
  else
    VTEMP = ' and tpdtquit_dtref = 2';

  if (ptodascontas <> 'S') then
    VTEMP = VTEMP || ' and trim(tipo) <> ''TODAS'' ';

  FOR EXECUTE STATEMENT
  ' select cod_empresa from empresa
    where ativo = 1 ' || VTEMPCODEMP into :cod_empresa  do
  begin
    IF (COALESCE(PTODASCONTAS, '') = 'S') THEN
       VTEMPTODAS = ' union
        select distinct 1, ''LANC'', ''TODAS'', cast('||:cod_empresa||' as integer), cast('||:cod_empresa||' as integer),
        p.n_conta_plc, null datq_l, '''' ndoc_l, 0 valor_l, '''' historico_l, null data, 0 cod_lanc, 0 valor_l,
        case when trim(coalesce(p.desc_padr, '''')) = '''' then p.desc_plc else p.desc_padr end desc_padr,
        s.desc_sub_ct, p.tipo_ctp, ''S'', '''' nome_ctrl,
        cast('''||:pdtini||''' as timestamp) data_ini,
        cast('''||:pdtfim||''' as timestamp) data_fim,
        p.ativo, 1 ordem, c.desc_gr, ct.desc_dep from p_contas p
        inner join grupos_ct c on p.grup_ct = c.grup_ct and c.tipo_gr = ''S''
        left join sub_grup_ct s on p.cod_sub_ct = s.cod_sub_ct
        left join depart_ct ct on ct.cod_dep = c.cod_dep
        UNION
        select distinct 2, ''LANC'', ''TODAS'', cast('||:cod_empresa||' as integer), cast('||:cod_empresa||' as integer),
        p.n_conta_plc, null dtreferencia, '''' ndoc_l, 0 valor_l, '''' historico_l, null data, 0 cod_lanc, 0 valor_l,
        case when trim(coalesce(p.desc_padr, '''')) = '''' then p.desc_plc else p.desc_padr end desc_padr,
        s.desc_sub_ct, p.tipo_ctp, ''S'', '''' nome_ctrl,
        cast('''||:pdtini||''' as timestamp) data_ini,
        cast('''||:pdtfim||''' as timestamp) data_fim,
        p.ativo, 1 ordem, c.desc_gr, ct.desc_dep from p_contas p
        inner join grupos_ct c on p.grup_ct = c.grup_ct and c.tipo_gr = ''S''
        left join sub_grup_ct s on p.cod_sub_ct = s.cod_sub_ct
        left join depart_ct ct on ct.cod_dep = c.cod_dep ';

    FOR EXECUTE STATEMENT
    ' select tpdtquit_dtref, tipo_desp, tipo, cod_empresa, cod_emp_mult,
        n_conta_plc, dtquit_dtref, ndoc, valor, historico, data,
        cod_lanc, valor_pago, desc_padr, desc_sub_ct, fornecedor,
        exibir_resumo_financeiro, nome_ctrl,
        cast('''||:pdtini||''' as timestamp) data_ini,
        cast('''||:pdtfim||''' as timestamp) data_fim,
        ativo, ordem, desc_gr, desc_dep from resumo_financeiro
        where ((dtquit_dtref  >= '''||:pdtini||'''
        and dtquit_dtref <= '''||:pdtfim||'''))
        and ' || :vcampo || ' = '||:cod_empresa|| vtemp || vtemptodas

    into :tpdtquit_dtref, :tipo_desp, :tipo, :cod_empresa, cod_emp_mult,
        :n_conta_plc, :dtquit_dtref, :ndoc, :valor, :historico, :data,
        :cod_lanc, :valor_pago, :desc_padr, :desc_sub_ct, :fornecedor,
        :exibir_resumo_financeiro, :nome_ctrl,
        :data_ini, :data_fim, :ativo, :ordem, :desc_gr, :desc_dep do
     begin
        if (trim(coalesce(pagruparunifada, '')) = 'S') then 
          cod_empresa = pcod_empresa;

        if (tpdtquit_dtref is not null) then
          suspend;
     end
  end
end ^

ALTER PROCEDURE RETIRAR_ZERO_ESQUERDA (VALOR VARCHAR(50) CHARACTER SET NONE)
RETURNS (RESULT VARCHAR(50) CHARACTER SET NONE)
AS 
declare variable I integer;
declare variable ZERO_ESQ char(1);
declare variable VVAL varchar(50);
BEGIN
  i = 0;
  ZERO_ESQ = 'N';
  RESULT = '';
  vval= trim(valor);

  while (i < char_length(:vval)) do
  begin
    if ((SUBSTRING(:vval FROM i + 1 FOR 1) = '0') and (TRIM(RESULT) = '')) then
        RESULT = RESULT;
    else
        RESULT = RESULT || SUBSTRING(:vval FROM i + 1 FOR 1);
    i = i + 1;
  end

  SUSPEND;
END ^

ALTER PROCEDURE RETIRAR_ZERO_ESQ_DESCONS_ULT_D (VALOR VARCHAR(50) CHARACTER SET NONE)
RETURNS (RESULT VARCHAR(50) CHARACTER SET NONE)
AS 
declare variable I integer;
declare variable ZERO_ESQ char(1);
declare variable VVAL varchar(50);
begin
  i = 0;
  ZERO_ESQ = 'N';
  RESULT = '';
  vval= trim(valor);

  while (i < char_length(:vval)) do
  begin
    if ((SUBSTRING(:vval FROM i + 1 FOR 1) = '0') and (TRIM(RESULT) = '')) then
        RESULT = RESULT;
    else
        RESULT = RESULT || SUBSTRING(:vval FROM i + 1 FOR 1);
    i = i + 1;
  end

  if (CHAR_LENGTH(TRIM(RESULT)) > 1) then
    RESULT = SUBSTRING(RESULT FROM 1 FOR CHAR_LENGTH(TRIM(RESULT)) - 1);

  SUSPEND;
end ^

ALTER PROCEDURE RETORNASALDOSCONTROLES (PCOD_CONTROLE INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (SALDOCAIXA DOUBLE PRECISION,
SALDOBANCO DOUBLE PRECISION,
DIFERENCA DOUBLE PRECISION)
AS 
declare variable VSALDOBANCO_LANC double precision;
declare variable VSALDOCAIXA_LANC double precision;
declare variable VTEMP double precision;
declare variable VTEMP2 double precision;
declare variable VDIAFINANC timestamp;
begin
  VSALDOCAIXA_LANC = 0;
  VSALDOBANCO_LANC = 0;
  VTEMP = 0;
  VTEMP2 = 0;
  SALDOBANCO = 0;
  SALDOCAIXA = 0;
  DIFERENCA = 0;

  VDIAFINANC = NULL;

  select max(fech_dia.dia_fcd) as data from fech_dia
  where fech_dia.codigo_emp = :PCOD_EMPRESA INTO :VDIAFINANC;

  select first 1 sal_ctrl.saldo_banco, sal_ctrl.val_sld from sal_ctrl where sal_ctrl.codigo_ctrl = :PCOD_CONTROLE
  and sal_ctrl.data_sld =
    (select max(sal.data_sld) as max_data_sld from sal_ctrl sal
     where sal.codigo_ctrl = :PCOD_CONTROLE and sal.cod_emp = :PCOD_EMPRESA)
  and sal_ctrl.cod_emp = :PCOD_EMPRESA order by sal_ctrl.data_sld INTO :VTEMP, :VTEMP2;

  select sum(case when (lancamentos.tipo_l = 'E') then coalesce(lancamentos.valor_l, 0)
              else (0 - coalesce(lancamentos.valor_l, 0)) end) from lancamentos
  where lancamentos.codigo_ctrl = :PCOD_CONTROLE
  and ((lancamentos.dt_compensado = (:VDIAFINANC + 1)) or (lancamentos.dt_compensado is null))
  and not(lancamentos.data < (:VDIAFINANC + 1))
  and lancamentos.data <= (:VDIAFINANC + 1)
  and lancamentos.codigo_emp = :PCOD_EMPRESA INTO : VSALDOCAIXA_LANC;

  select sum(case when (lancamentos.tipo_l = 'E') then coalesce(lancamentos.valor_l, 0)
              else (0 - coalesce(lancamentos.valor_l, 0)) end) from lancamentos
  where lancamentos.codigo_ctrl = :PCOD_CONTROLE
  and ((lancamentos.dt_compensado = (:VDIAFINANC + 1)) or (lancamentos.dt_compensado is null))
  and (lancamentos.dia_fcd = (:VDIAFINANC + 1))
  and lancamentos.data <= (:VDIAFINANC + 1)
  and lancamentos.codigo_emp = :PCOD_EMPRESA INTO : VSALDOBANCO_LANC;

  SALDOCAIXA = COALESCE(VTEMP2, 0) + COALESCE(VSALDOCAIXA_LANC, 0);
  SALDOBANCO = COALESCE(VTEMP, 0) + COALESCE(VSALDOBANCO_LANC, 0);
  DIFERENCA = COALESCE(SALDOCAIXA, 0) - COALESCE(SALDOBANCO, 0);

  suspend;
end;
 
 ^

ALTER PROCEDURE RETORNA_COMISSAO_FAIXADESC (PCOD_COMISSAO_FAIXA_DESC INTEGER,
PCOD_EMPRESA INTEGER,
PPERC_DESCONTO DOUBLE PRECISION,
PVALOR_ITEM DOUBLE PRECISION)
RETURNS (ICODIGO_REGRA INTEGER,
IDESCRICAO_REGRA VARCHAR(50) CHARACTER SET NONE,
ITIPO_REGRA VARCHAR(10) CHARACTER SET NONE,
IPERCENTUAL_REGRA DOUBLE PRECISION,
IPERCENTUAL_DESC DOUBLE PRECISION,
IVALOR_COMISSAO DOUBLE PRECISION)
AS 
begin
  /* Procedure Text */
  icodigo_regra = 0;
  idescricao_regra = '';
  itipo_regra = '';
  ipercentual_regra = 0;
  ivalor_comissao = 0;
  if (coalesce(pcod_comissao_faixa_desc, 0) > 0) then
  begin
      select first 1 cdesc.codigo, cdesc.descricao, cdesc.tipo, cperc.perc_comissao from comissao_faixa_desconto cdesc
      inner join comissao_faixa_desconto_vig cvig on
        cvig.codigo = cdesc.codigo
        and cvig.cod_empresa = cdesc.cod_empresa
        and current_date >= cvig.dtini_vig
        and current_date <= cvig.dtfim_vig
      inner join comissao_faixa_desconto_perc cperc on
        cperc.cod_vig = cvig.cod_vig
        and cperc.codigo = cvig.codigo
        and cperc.cod_empresa = cvig.cod_empresa
        and :pperc_desconto >= cperc.perc_desc_ini
        and :pperc_desconto <= cperc.perc_desc_fim
      where cdesc.codigo = :pcod_comissao_faixa_desc
      and cdesc.cod_empresa = :pcod_empresa
      and cdesc.ativo = 1 into :icodigo_regra, :idescricao_regra, :itipo_regra, :ipercentual_regra;
  end
  if (coalesce(icodigo_regra, 0) <= 0) then
  begin
    select first 1 cdesc.codigo, cdesc.descricao, cdesc.tipo, cperc.perc_comissao from comissao_faixa_desconto cdesc
    inner join comissao_faixa_desconto_vig cvig on
      cvig.codigo = cdesc.codigo
      and cvig.cod_empresa = cdesc.cod_empresa
      and current_date >= cvig.dtini_vig
      and current_date <= cvig.dtfim_vig
    inner join comissao_faixa_desconto_perc cperc on
      cperc.cod_vig = cvig.cod_vig
      and cperc.codigo = cvig.codigo
      and cperc.cod_empresa = cvig.cod_empresa
      and :pperc_desconto >= cperc.perc_desc_ini
      and :pperc_desconto <= cperc.perc_desc_fim
    where cdesc.tipo = 'GERAL'
    and cdesc.cod_empresa = :pcod_empresa
    and cdesc.ativo = 1 into :icodigo_regra, :idescricao_regra, :itipo_regra, :ipercentual_regra;
  end
  if ((coalesce(icodigo_regra, 0) > 0) and (coalesce(ipercentual_regra, 0) > 0)) then
  begin
    ivalor_comissao = round(((coalesce(pvalor_item, 0) / 100) * coalesce(ipercentual_regra, 0)), 2);
    ipercentual_desc = coalesce(pperc_desconto, 0);
  end
  suspend;
end;
 
 ^

ALTER PROCEDURE RETORNA_CONTRATOS (PNPED INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (COD_CONTRATO INTEGER,
DESCR_CONTRATO VARCHAR(75) CHARACTER SET NONE,
TOT_FORMPAG DOUBLE PRECISION,
TOT_BOLETAS DOUBLE PRECISION,
N_SEQ_BOL VARCHAR(22) CHARACTER SET NONE,
NOSSO_NUMERO_BANCO VARCHAR(44) CHARACTER SET NONE,
DATA_REMESSA TIMESTAMP,
COD_COBREBEM INTEGER,
COD_CONTROLE_CX INTEGER,
COD_RPS VARCHAR(100) CHARACTER SET NONE,
NUM_NFS VARCHAR(100) CHARACTER SET NONE,
SERIE_NFS VARCHAR(5) CHARACTER SET NONE,
DATA_NFS TIMESTAMP,
SITUACAO_NFS VARCHAR(100) CHARACTER SET NONE,
DESCRICAOERRO_NFS VARCHAR(1000) CHARACTER SET NONE,
COD_NF INTEGER,
NUM_NF BIGINT,
SERIE_NF VARCHAR(5) CHARACTER SET NONE,
DATA_NF TIMESTAMP,
SITUACAO_NF VARCHAR(100) CHARACTER SET NONE,
DESCRICAOERRO_NF VARCHAR(1000) CHARACTER SET NONE,
DATA_EMAIL_NFS TIMESTAMP,
DATA_WHATSAPP_NFS TIMESTAMP,
DATA_EMAIL_NF TIMESTAMP,
DATA_WHATSAPP_NF TIMESTAMP,
DATA_EMAIL_BOL TIMESTAMP,
DATA_WHATSAPP_BOL TIMESTAMP,
DATA_EMAIL_REC TIMESTAMP,
DATA_WHATSAPP_REC TIMESTAMP,
GERAR_NFS CHAR(1) CHARACTER SET NONE,
GERAR_NF CHAR(1) CHARACTER SET NONE,
GERAR_REC_LOC CHAR(1) CHARACTER SET NONE,
GERAR_BOLETO CHAR(1) CHARACTER SET NONE)
AS 
declare variable VCOD_RPS_TMP integer;
declare variable VTOT_FORMPAG double precision;
declare variable VTOT_BOLETAS double precision = 000.00;
declare variable VNUM_NFS_TMP bigint;
declare variable VN_SEQ_BOL_TMP integer;
declare variable VNOSSO_NUMERO_BANCO_TMP varchar(20);
declare variable VN_SEQ_BOL varchar(22);
declare variable VNOSSO_NUMERO_BANCO varchar(44);
declare variable VDATA_REMESSA timestamp;
declare variable VCOD_COBREBEM integer;
declare variable VCOD_CONTROLE_CX integer;
declare variable VCOD_RPS varchar(100);
declare variable VNUM_NFS varchar(100);
declare variable VSERIE_NFS varchar(5);
declare variable VDATA_NFS timestamp;
declare variable VSITUACAO_NFS varchar(100);
declare variable VDESCRICAOERRO_NFS varchar(1000);
declare variable VCOD_NF integer;
declare variable VNUM_NF bigint;
declare variable VSERIE_NF varchar(5);
declare variable VDATA_NF timestamp;
declare variable VSITUACAO_NF varchar(100);
declare variable VDESCRICAOERRO_NF varchar(1000);
declare variable VDATA_EMAIL_NFS timestamp;
declare variable VDATA_WHATSAPP_NFS timestamp;
declare variable VDATA_EMAIL_NF timestamp;
declare variable VDATA_WHATSAPP_NF timestamp;
declare variable VDATA_EMAIL_BOL timestamp;
declare variable VDATA_WHATSAPP_BOL timestamp;
declare variable VDATA_EMAIL_REC timestamp;
declare variable VDATA_WHATSAPP_REC timestamp;
begin
  /* Procedure Text */
  cod_contrato        = null;
  descr_contrato      = null;
  num_nfs             = null;
  serie_nfs           = null;
  data_nfs            = null;

  situacao_nfs        = null;
  num_nf              = null;
  serie_nf            = null;
  data_nf             = null;
  situacao_nf         = null;
  descricaoerro_nf    = null;

  tot_formpag         = null;
  tot_boletas         = null;
  n_seq_bol           = null;
  nosso_numero_banco  = null;
  data_remessa        = null;
  cod_cobrebem        = null;
  cod_controle_cx     = null;

  data_email_nfs      = null;
  data_whatsapp_nfs   = null;
  data_email_nf       = null;
  data_whatsapp_nf    = null;
  data_email_bol      = null;
  data_whatsapp_bol   = null;

  data_email_rec      = null;
  data_whatsapp_rec   = null;

  gerar_nfs           = null;
  gerar_nf            = null;
  gerar_rec_loc       = null;
  gerar_boleto        = null;

  vcod_rps_tmp        = null;
  vnum_nfs_tmp        = null;

  vcod_rps            = null;
  vnum_nfs            = null;
  vserie_nfs          = null;
  vdata_nfs           = null;
  vsituacao_nfs       = null;
  vdescricaoerro_nfs  = null;

  vtot_formpag        = null;
  vtot_boletas        = null;
  vn_seq_bol          = null;
  vnosso_numero_banco = null;
  vdata_remessa       = null;
  vcod_cobrebem       = null;
  vcod_controle_cx    = null;

  vdata_email_nfs     = null;
  vdata_whatsapp_nfs  = null;
  vdata_email_nf      = null;
  vdata_whatsapp_nf   = null;
  vdata_email_bol     = null;
  vdata_whatsapp_bol  = null;
  vdata_email_rec     = null;
  vdata_whatsapp_rec  = null;

  vcod_nf             = null;
  vnum_nf             = null;
  vserie_nf           = null;
  vdata_nf            = null;
  vsituacao_nf        = null;
  vdescricaoerro_nf   = null;

  select valor_total from existe_formas (:pnped, :ptipo, :pcod_empresa)
    into :vtot_formpag;

  select sum(coalesce(boletas.vl_doc_bol, 0)) from boletas
  where boletas.num_nf_vnd = :pnped
  and boletas.tipo_emissao = :ptipo
  and boletas.cod_empresa = :pcod_empresa
  and boletas.ativo = 1
    into :vtot_boletas;

  for select first 2 boletas.n_seq_bol, boletas.nosso_numero_banco,
      boletas.data_remessa, boletas.cod_cobrebem, boletas.cod_controle_cx from boletas
      where boletas.num_nf_vnd = :pnped
      and boletas.tipo_emissao = :ptipo
      and boletas.cod_empresa = :pcod_empresa
      and boletas.ativo = 1
      order by 1
        into :vn_seq_bol_tmp, :vnosso_numero_banco_tmp, :vdata_remessa, :vcod_cobrebem, :vcod_controle_cx do
  begin
    if (coalesce(vn_seq_bol_tmp, 0) > 0) then
      vn_seq_bol = coalesce(vn_seq_bol, '') || iif(trim(coalesce(vn_seq_bol, '')) <> '', ',', '') || coalesce(vn_seq_bol_tmp, 0);

    if (trim(coalesce(vnosso_numero_banco_tmp, '')) <> '') then
      vnosso_numero_banco = coalesce(vnosso_numero_banco, '') || iif(trim(coalesce(vnosso_numero_banco, '')) <> '', ',', '') || coalesce(vnosso_numero_banco_tmp, 0);
  end

  if (coalesce(vn_seq_bol_tmp, 0) > 0) then
  begin
    select first 1 data_env from(
        select env_doc.data_env from env_doc
        where env_doc.num_doc = 'BOL_' || :vn_seq_bol_tmp
        and env_doc.cod_empresa = :pcod_empresa
        and env_doc.tipo_env = 'W'
        union
        select bol.data_whatsapp_bol from boletas bol
        where bol.n_seq_bol = :vn_seq_bol_tmp
        and bol.cod_empresa = :pcod_empresa
        order by 1 desc)
    order by 1 desc
          into :vdata_whatsapp_bol;

    select first 1 data_env from(
        select env_doc.data_env from env_doc
        where env_doc.num_doc = 'BOL_' || :vn_seq_bol_tmp
        and env_doc.cod_empresa = :pcod_empresa
        and env_doc.tipo_env = 'E'
        union
        select bol.data_email_bol from boletas bol
        where bol.n_seq_bol = :vn_seq_bol_tmp
        and bol.cod_empresa = :pcod_empresa
        order by 1 desc)
    order by 1 desc
          into :vdata_email_bol;
  end

  if (coalesce(pnped, 0) > 0) then
  begin
    select first 1 data_env from(
        select first 1 env_doc.data_env from env_doc
        where env_doc.num_doc = 'LOC' || trim(:ptipo) || '_'  || :pnped
        and env_doc.cod_empresa = :pcod_empresa
        and env_doc.tipo_env = 'W'
        order by 1 desc)
          into :vdata_whatsapp_rec;

    select first 1 data_env from(
        select first 1 env_doc.data_env from env_doc
        where env_doc.num_doc = 'LOC' || trim(:ptipo) || '_' || :pnped
        and env_doc.cod_empresa = :pcod_empresa
        and env_doc.tipo_env = 'E'
        order by 1 desc)
          into :vdata_email_rec;
  end

  for select distinct pedvenda_serv.cod_rps, pedvenda_serv.n_nf, pedvenda_serv.serie,
        pedvenda_serv.emissao_nfse, pedvenda_serv.status_nfse from pedvenda
        inner join pedvenda_serv on
          pedvenda_serv.nped = pedvenda.nped
          and pedvenda_serv.tipo = pedvenda.tipo
          and pedvenda_serv.cod_empresa = pedvenda.cod_empresa
        where pedvenda.nped = :pnped
        and pedvenda.tipo = :ptipo
        and pedvenda.cod_empresa = :pcod_empresa
        and pedvenda.status_ped = 'FECHADA'
        and (pedvenda_serv.status <> 'CANCELADO' or pedvenda_serv.status is null)
        order by 1 asc
          into :vcod_rps_tmp, :vnum_nfs_tmp, :vserie_nfs, :vdata_nfs, :vsituacao_nfs do
  begin
    if (coalesce(vcod_rps_tmp, 0) > 0) then
      vcod_rps = coalesce(vcod_rps, '') || iif(trim(coalesce(vcod_rps, '')) <> '', ',', '') || coalesce(vcod_rps_tmp, 0);

    if (coalesce(vnum_nfs_tmp, 0) > 0) then
      vnum_nfs = coalesce(vnum_nfs, '') || iif(trim(coalesce(vnum_nfs, '')) <> '', ',', '') || coalesce(vnum_nfs_tmp, 0);
  end

  if (coalesce(vcod_rps_tmp, 0) > 0) then
  begin
    select first 1 env_doc.data_env from env_doc
    where env_doc.num_doc = 'RPS_' || :vcod_rps_tmp
    and env_doc.cod_empresa = :pcod_empresa
    and env_doc.tipo_env = 'W'
    order by env_doc.data_env desc
      into :vdata_whatsapp_nfs;
        
    select first 1 env_doc.data_env from env_doc
    where env_doc.num_doc = 'RPS_' || :vcod_rps_tmp
    and env_doc.cod_empresa = :pcod_empresa
    and env_doc.tipo_env = 'E'
    order by env_doc.data_env desc
      into :vdata_email_nfs;
  end

  select first 1 notafiscal.cod_nf, notafiscal.num_nf, notafiscal.serie,
  notafiscal.data_lanc, notafiscal.situacao_nfe, notafiscal.descricaoerro from notafiscal
  inner join pedvenda on
    pedvenda.nped = notafiscal.nped
    and pedvenda.tipo = notafiscal.tipo_ped
    and pedvenda.cod_empresa = notafiscal.cod_empresa
    and pedvenda.num_nf = notafiscal.num_nf
    and pedvenda.serie_nf = notafiscal.serie
  where notafiscal.nped = :pnped
  and notafiscal.tipo_ped = :ptipo
  and notafiscal.cod_empresa = :pcod_empresa
  order by 1 desc
    into :vcod_nf, :vnum_nf, vserie_nf, :vdata_nf, :vsituacao_nf, :vdescricaoerro_nf;

  if (coalesce(vcod_nf, 0) > 0) then
  begin
    select first 1 env_doc.data_env from env_doc
    where env_doc.num_doc = 'NF_' || :vcod_nf
    and env_doc.cod_empresa = :pcod_empresa
    and env_doc.tipo_env = 'W'
    order by env_doc.data_env desc
      into :vdata_whatsapp_nf;

    select first 1 env_doc.data_env from env_doc
    where env_doc.num_doc = 'NF_' || :vcod_nf
    and env_doc.cod_empresa = :pcod_empresa
    and env_doc.tipo_env = 'E'
    order by env_doc.data_env desc
      into :vdata_email_nf;
  end

  for select distinct cod_contrato, descr_contrato, gerar_nfs, gerar_nf, gerar_rec_loc, gerar_boleto from (
        select distinct pedvenda_serv.cod_contrato,
        clientes_com_contrato.descr_contrato,
        clientes_com_contrato.gerar_nfs,
        clientes_com_contrato.gerar_nf,
        clientes_com_contrato.gerar_rec_loc,
        clientes_com_contrato.gerar_boleto from pedvenda
        inner join pedvenda_serv on
          pedvenda_serv.nped = pedvenda.nped
          and pedvenda_serv.tipo = pedvenda.tipo
          and pedvenda_serv.cod_empresa = pedvenda.cod_empresa
        inner join clientes_com_contrato on
          clientes_com_contrato.cod_contrato = pedvenda_serv.cod_contrato
          and clientes_com_contrato.cod_empresa = pedvenda_serv.cod_empresa
        where pedvenda.nped = :pnped
        and pedvenda.tipo = :ptipo
        and pedvenda.cod_empresa = :pcod_empresa
        and pedvenda.status_ped = 'FECHADA'
        and (pedvenda_serv.status <> 'CANCELADO' or pedvenda_serv.status is null)
        union
        select distinct pedvenda_prod.cod_contrato,
        clientes_com_contrato.descr_contrato,
        clientes_com_contrato.gerar_nfs,
        clientes_com_contrato.gerar_nf,
        clientes_com_contrato.gerar_rec_loc,
        clientes_com_contrato.gerar_boleto from pedvenda
        inner join pedvenda_prod on
          pedvenda_prod.nped = pedvenda.nped
          and pedvenda_prod.tipo = pedvenda.tipo
          and pedvenda_prod.cod_empresa = pedvenda.cod_empresa
        inner join clientes_com_contrato on
          clientes_com_contrato.cod_contrato = pedvenda_prod.cod_contrato
          and clientes_com_contrato.cod_empresa = pedvenda_prod.cod_empresa
        where pedvenda.nped = :pnped
        and pedvenda.tipo = :ptipo
        and pedvenda.cod_empresa = :pcod_empresa
        and pedvenda.status_ped = 'FECHADA'
        and (pedvenda_prod.status <> 'CANCELADO' or pedvenda_prod.status is null)  )
          into :cod_contrato, :descr_contrato, :gerar_nfs, :gerar_nf, :gerar_rec_loc, :gerar_boleto do
  begin
    cod_rps            = trim(vcod_rps);
    num_nfs            = trim(vnum_nfs);
    serie_nfs          = trim(vserie_nfs);
    data_nfs           = vdata_nfs;
    situacao_nfs       = trim(vsituacao_nfs);
    descricaoerro_nfs  = trim(vdescricaoerro_nfs);
    data_email_nfs     = vdata_email_nfs;
    data_whatsapp_nfs  = vdata_whatsapp_nfs;

    cod_nf             = vcod_nf;
    num_nf             = vnum_nf;
    serie_nf           = trim(vserie_nf);
    data_nf            = vdata_nf;
    situacao_nf        = trim(vsituacao_nf);
    descricaoerro_nf   = trim(vdescricaoerro_nf);
    data_email_nf      = vdata_email_nf;
    data_whatsapp_nf   = vdata_whatsapp_nf;

    tot_formpag        = vtot_formpag;
    tot_boletas        = vtot_boletas;
    n_seq_bol          = trim(vn_seq_bol);
    nosso_numero_banco = trim(vnosso_numero_banco);
    data_remessa       = vdata_remessa;
    cod_cobrebem       = vcod_cobrebem;
    cod_controle_cx    = vcod_controle_cx;
    data_email_bol     = vdata_email_bol;
    data_whatsapp_bol  = vdata_whatsapp_bol;

    data_email_rec     = vdata_email_rec;
    data_whatsapp_rec  = vdata_whatsapp_rec;

    suspend;
  end
end;
 
 ^

ALTER PROCEDURE RETORNA_CTRL_AG_CONTA (PAGENCIA_CTRL VARCHAR(10) CHARACTER SET NONE,
PN_CONTA_CTRL VARCHAR(10) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (CODIGO_CTRL INTEGER,
NOME_CTRL VARCHAR(35) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  codigo_ctrl = 0;
  nome_ctrl   = '';
  select first 1 controles.codigo_ctrl, controles.nome_ctrl from controles
  where (select result from retirar_zero_esquerda (controles.agencia_ctrl)) =
    (select result from retirar_zero_esquerda (:pagencia_ctrl))
  and (select result from retirar_zero_esquerda (controles.n_conta_ctrl)) =
    (select result from retirar_zero_esquerda (:pn_conta_ctrl))
  and controles.codigo_emp = :pcod_empresa
    into :codigo_ctrl, :nome_ctrl;

  if (coalesce(codigo_ctrl, 0) <= 0) then
  begin
    select first 1 controles.codigo_ctrl, controles.nome_ctrl from controles
    where (select result from retirar_zero_esq_descons_ult_d (controles.n_conta_ctrl)) =
      (select result from retirar_zero_esq_descons_ult_d (:pn_conta_ctrl))
    and controles.codigo_emp = :pcod_empresa
      into :codigo_ctrl, :nome_ctrl;
  end

  codigo_ctrl = coalesce(codigo_ctrl, 0);
  nome_ctrl   = coalesce(nome_ctrl, '');
  suspend;
end;
 
 ^

ALTER PROCEDURE RETORNA_CUSTO_MED_ACAB (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PDATA TIMESTAMP,
PPREC_CUS_PROD_ACAB DOUBLE PRECISION,
PQUANTIDADE_ACAB DOUBLE PRECISION)
RETURNS (CUSTO_MEDIO DOUBLE PRECISION)
AS 
declare variable VEXISTE_GRADE integer;
declare variable VCOD_GRADE integer;
declare variable VCUSTO_MEDIO double precision;
declare variable VESTOQUE double precision;
declare variable VEST_TMP double precision;
begin
  custo_medio = 0;
  vest_tmp    = 0;
  vestoque    = 0;
  /* Procedure Text */
  select count(*) from cod_grade_prod cp
  where cp.grupo_prod = :pgrupo_prod
  and cp.cod_prod = :pcod_prod
  and cp.cod_empresa = :pcod_empresa
  and cp.ativo = 1
    into :vexiste_grade;

  if (coalesce(vexiste_grade, 0) > 0) then
  begin
    for select cp.cod_grade from cod_grade_prod cp
        where cp.grupo_prod = :pgrupo_prod
        and cp.cod_prod = :pcod_prod
        and cp.cod_empresa = :pcod_empresa
        and cp.ativo = 1
          into :vcod_grade do
    begin
      select first 1 coalesce(est.estoque, 0) estoque from estoque_diario est
      where est.grupo_prod = :pgrupo_prod
      and est.cod_prod = :pcod_prod
      and est.cod_grade = :vcod_grade
      and est.cod_empresa = :pcod_empresa
      and est.dia < :pdata
      order by est.dia desc
        into :vest_tmp;

      vestoque = coalesce(vestoque, 0) + coalesce(vest_tmp, 0);

      select first 1 coalesce(est.custo_medio, 0) custo_medio from estoque_diario est
      where est.grupo_prod = :pgrupo_prod
      and est.cod_prod = :pcod_prod
      and est.cod_empresa = :pcod_empresa
      and est.dia < :pdata
      order by est.dia desc
        into :vcusto_medio;
    end
  end
  else
  begin
    select first 1 coalesce(est.estoque, 0) estoque, coalesce(est.custo_medio, 0) custo_medio from estoque_diario est
    where est.grupo_prod = :pgrupo_prod
    and est.cod_prod = :pcod_prod
    and est.cod_empresa = :pcod_empresa
    and est.dia < :pdata
    order by est.dia desc
      into :vestoque, :vcusto_medio;
  end

  if ((coalesce(vcusto_medio, 0) > 0) and (coalesce(vestoque, 0) > 0)) then
  begin
    custo_medio = (coalesce(vcusto_medio, 0) * coalesce(vestoque, 0));
    custo_medio = (coalesce(custo_medio, 0) +
      (coalesce(pprec_cus_prod_acab, 0) * coalesce(pquantidade_acab, 0)));

    if (coalesce(pquantidade_acab, 0) + coalesce(vestoque, 0) > 0) then
      custo_medio = (coalesce(custo_medio, 0) / (coalesce(pquantidade_acab, 0) + coalesce(vestoque, 0)));
    else
      custo_medio = coalesce(custo_medio, 0);
  end
  else
    custo_medio = coalesce(vcusto_medio, 0);
  suspend;
end;
 
 ^

ALTER PROCEDURE RETORNA_DATA_ENV_BOL (PN_SEQ_BOL INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (DATA_ENV_WHATSAPP TIMESTAMP,
DATA_ENV_EMAIL TIMESTAMP,
DATA_ENV_MENS TIMESTAMP)
AS 
begin
  /* Procedure Text */
  data_env_email    = null;
  data_env_whatsapp = null;
  data_env_mens     = null;

  select first 1 data_env from(
        select first 1 env_doc.data_env from env_doc
        where env_doc.num_doc = 'BOL_' || :pn_seq_bol
        and env_doc.cod_empresa = :pcod_empresa
        and env_doc.tipo_env = 'W'
        union
        select first 1 bol.data_whatsapp_bol from boletas bol
        where bol.n_seq_bol = :pn_seq_bol
        and bol.cod_empresa = :pcod_empresa
        order by 1 desc)
          into :data_env_whatsapp;

  select first 1 data_env from(
        select first 1 env_doc.data_env from env_doc
        where env_doc.num_doc = 'BOL_' || :pn_seq_bol
        and env_doc.cod_empresa = :pcod_empresa
        and env_doc.tipo_env = 'E'
        union
        select first 1 bol.data_email_bol from boletas bol
        where bol.n_seq_bol = :pn_seq_bol
        and bol.cod_empresa = :pcod_empresa
        order by 1 desc)
          into :data_env_email;

  select first 1 data_env from(
        select first 1 env_doc.data_env from env_doc
        where env_doc.num_doc = 'BOL_' || :pn_seq_bol
        and env_doc.cod_empresa = :pcod_empresa
        and env_doc.tipo_env = 'M'
        union
        select first 1 bol.data_email_bol from boletas bol
        where bol.n_seq_bol = :pn_seq_bol
        and bol.cod_empresa = :pcod_empresa
        order by 1 desc)
          into :data_env_mens;

  suspend;
end;
 
 ^

ALTER PROCEDURE RETORNA_DOC_CASHBACK (PNDOC INTEGER,
PTIPODOC CHAR(3) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (NDOC INTEGER,
TIPODOC CHAR(3) CHARACTER SET NONE,
COD_EMPRESA INTEGER,
VALOR_DESCONTO DOUBLE PRECISION,
VALOR_ACRESCIMO DOUBLE PRECISION,
VALOR_TOTAL DOUBLE PRECISION,
VALOR_VALE DOUBLE PRECISION,
COD_CLIENTE INTEGER,
NOME_CLIENTE VARCHAR(35) CHARACTER SET NONE,
RAZAO_CLIENTE VARCHAR(60) CHARACTER SET NONE,
CPFCGC_CLIENTE VARCHAR(18) CHARACTER SET NONE,
RG_CLIENTE VARCHAR(10) CHARACTER SET NONE,
TELEFONE_CLIENTE VARCHAR(13) CHARACTER SET NONE,
CELULAR_CLIENTE VARCHAR(13) CHARACTER SET NONE,
EMAIL_CLIENTE VARCHAR(256) CHARACTER SET NONE,
DATA_NASC_CLIENTE TIMESTAMP,
SEXO_GENERO_CLIENTE CHAR(1) CHARACTER SET NONE,
COD_VENDEDOR INTEGER,
NOME_VENDEDOR VARCHAR(35) CHARACTER SET NONE,
CPF_VENDEDOR VARCHAR(11) CHARACTER SET NONE,
RG_VENDEDOR VARCHAR(11) CHARACTER SET NONE,
TELEFONE_VENDEDOR VARCHAR(13) CHARACTER SET NONE,
EMAIL_VENDEDOR VARCHAR(128) CHARACTER SET NONE,
DATA_NASC_VENDEDOR TIMESTAMP)
AS 
begin
  /* Procedure Text */
  if ((trim(coalesce(ptipodoc, '')) = 'REQ') or (trim(coalesce(ptipodoc, '')) = 'OS')) then
  begin
    select pedvenda.nped, pedvenda.tipo, pedvenda.cod_empresa, pedvenda.valor_total,
    (coalesce((select sum(coalesce(pedvenda_prod.rateio_desc, 0)) from pedvenda_prod
               where pedvenda_prod.nped = pedvenda.nped
               and pedvenda_prod.tipo = pedvenda.tipo
               and pedvenda_prod.cod_empresa = pedvenda.cod_empresa
               and coalesce(pedvenda_prod.status, '') = ''), 0)
    ) valor_desconto,
    (coalesce((select sum(coalesce(pedvenda_prod.rateio_acresc, 0)) from pedvenda_prod
               where pedvenda_prod.nped = pedvenda.nped
               and pedvenda_prod.tipo = pedvenda.tipo
               and pedvenda_prod.cod_empresa = pedvenda.cod_empresa
               and coalesce(pedvenda_prod.status, '') = ''), 0)
    ) valor_acrescimo,
    coalesce((select coalesce(valor_vale, 0) from existe_formas (pedvenda.nped, pedvenda.tipo, pedvenda.cod_empresa)), 0) valor_vale,
    clientes.cod_cliente, clientes.nome_cliente, clientes.razao, clientes.cpfcgc, clientes.rg,
    clientes.fone_cliente, clientes.fone_celular, clientes.email, clientes.data_nasc, clientes.sexo,
    colaborador.cod_vendedor, colaborador.nome_vendedor, colaborador.cpf_vendedor, colaborador.rg_vendedor,
    colaborador.fone_vendedor, colaborador.email, colaborador.dat_nasc_col from pedvenda
    inner join clientes on clientes.cod_cliente = pedvenda.cod_cliente and clientes.cod_empresa = pedvenda.cod_empresa
    inner join colaborador on colaborador.cod_vendedor = pedvenda.cod_vendedor and colaborador.cod_empresa = pedvenda.cod_empresa
    where pedvenda.nped = :pndoc
    and pedvenda.tipo = :ptipodoc
    and pedvenda.cod_empresa = :pcod_empresa
      into :ndoc, :tipodoc, :cod_empresa, :valor_total, :valor_desconto, :valor_acrescimo, :valor_vale,
           :cod_cliente, :nome_cliente, :razao_cliente, :cpfcgc_cliente, :rg_cliente,
           :telefone_cliente, :celular_cliente, :email_cliente, :data_nasc_cliente, :sexo_genero_cliente,
           :cod_vendedor, :nome_vendedor, :cpf_vendedor, :rg_vendedor,
           :telefone_vendedor, :email_vendedor, :data_nasc_vendedor;
  end
  else if (trim(coalesce(ptipodoc, '')) = 'DEV') then
  begin
    select devolucao_tot.ndev, 'DEV', devolucao_tot.cod_empresa, - abs(devolucao_tot.valor_dev) valor_dev, 0 valor_desconto, 0 valor_acrescimo, 0 valor_vale,
    clientes.cod_cliente, clientes.nome_cliente, clientes.razao, clientes.cpfcgc, clientes.rg,
    clientes.fone_cliente, clientes.fone_celular, clientes.email, clientes.data_nasc, clientes.sexo,
    colaborador.cod_vendedor, colaborador.nome_vendedor, colaborador.cpf_vendedor, colaborador.rg_vendedor,
    colaborador.fone_vendedor, colaborador.email, colaborador.dat_nasc_col from devolucao_tot
    inner join clientes on clientes.cod_cliente = devolucao_tot.cod_cliente and clientes.cod_empresa = devolucao_tot.cod_empresa
    inner join colaborador on colaborador.cod_vendedor = devolucao_tot.cod_vendedor and colaborador.cod_empresa = devolucao_tot.cod_empresa
    where devolucao_tot.ndev = :pndoc
    and devolucao_tot.cod_empresa = :pcod_empresa
      into :ndoc, :tipodoc, :cod_empresa, :valor_total, :valor_desconto, :valor_acrescimo, :valor_vale,
           :cod_cliente, :nome_cliente, :razao_cliente, :cpfcgc_cliente, :rg_cliente,
           :telefone_cliente, :celular_cliente, :email_cliente, :data_nasc_cliente, :sexo_genero_cliente,
           :cod_vendedor, :nome_vendedor, :cpf_vendedor, :rg_vendedor,
           :telefone_vendedor, :email_vendedor, :data_nasc_vendedor;

    if (coalesce(cod_empresa, 0) = 0) then
    begin
      select devolucao_hist_tot.ndev, 'DEV', devolucao_hist_tot.cod_empresa, - abs(devolucao_hist_tot.valor_dev) valor_dev, 0 valor_desconto, 0 valor_acrescimo,
      clientes.cod_cliente, clientes.nome_cliente, clientes.razao, clientes.cpfcgc, clientes.rg,
      clientes.fone_cliente, clientes.fone_celular, clientes.email, clientes.data_nasc, clientes.sexo,
      colaborador.cod_vendedor, colaborador.nome_vendedor, colaborador.cpf_vendedor, colaborador.rg_vendedor,
      colaborador.fone_vendedor, colaborador.email, colaborador.dat_nasc_col from devolucao_hist_tot
      inner join clientes on clientes.cod_cliente = devolucao_hist_tot.cod_cliente and clientes.cod_empresa = devolucao_hist_tot.cod_empresa
      inner join colaborador on colaborador.cod_vendedor = devolucao_hist_tot.cod_vendedor and colaborador.cod_empresa = devolucao_hist_tot.cod_empresa
      where devolucao_hist_tot.ndev = :pndoc
      and devolucao_hist_tot.cod_empresa = :pcod_empresa
        into :ndoc, :tipodoc, :cod_empresa, :valor_total, :valor_desconto, :valor_acrescimo,
             :cod_cliente, :nome_cliente, :razao_cliente, :cpfcgc_cliente, :rg_cliente,
             :telefone_cliente, :celular_cliente, :email_cliente, :data_nasc_cliente, :sexo_genero_cliente,
             :cod_vendedor, :nome_vendedor, :cpf_vendedor, :rg_vendedor,
             :telefone_vendedor, :email_vendedor, :data_nasc_vendedor;
    end
  end

  suspend;
end ^

ALTER PROCEDURE RETORNA_EC_VLTB_PROM (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (DESC_TABELA VARCHAR(128) CHARACTER SET NONE,
VALOR_TAB_PRO DOUBLE PRECISION)
AS 
  declare variable VCOD_TAB_PRECO integer;  
  declare variable CURRENT_TS timestamp;
begin
  select CURRENT_D
  from SP_CURRENT_TS(:PCOD_EMPRESA)
    into :CURRENT_TS;

  DESC_TABELA = '';
  VALOR_TAB_PRO = 0;

  SELECT CONFIG_API.COD_TAB_PRECO FROM CONFIG_API WHERE CONFIG_API.COD_EMPRESA = :PCOD_EMPRESA AND API = 'TRAYCOMMERCE' into :VCOD_TAB_PRECO;

  SELECT FIRST 1
  PROMOCAO.DESCR_PROMOCAO,
  CASE WHEN(PROMOCAO_PRODUTO.PORCENTAGEM > 0) THEN
        (ROUND(PRODUTOS.PREC_TAB_PROD, 2) - ROUND((ROUND(PRODUTOS.PREC_TAB_PROD * PROMOCAO_PRODUTO.PORCENTAGEM) / 100), 2))
      ELSE
        ROUND(PROMOCAO_PRODUTO.VALOR_PROMOCAO, 2)
  END
  FROM PROMOCAO_PRODUTO
  INNER JOIN PRODUTOS ON
      PRODUTOS.GRUPO_PROD = PROMOCAO_PRODUTO.GRUPO_PROD
      AND PRODUTOS.COD_PROD = PROMOCAO_PRODUTO.COD_PROD
      AND PRODUTOS.COD_EMPRESA = PROMOCAO_PRODUTO.COD_EMPRESA
  INNER JOIN PROMOCAO ON
      PROMOCAO.COD_PROMOCAO = PROMOCAO_PRODUTO.COD_PROMOCAO
      AND PROMOCAO.COD_EMPRESA = PROMOCAO_PRODUTO.COD_EMPRESA
      AND PROMOCAO.ATIVO = 1
  INNER JOIN PROMOCAO_ORDEM_EC ON
      PROMOCAO_ORDEM_EC.COD_PROMOCAO = PROMOCAO_PRODUTO.COD_PROMOCAO
      AND PROMOCAO_ORDEM_EC.COD_EMPRESA = PROMOCAO_PRODUTO.COD_EMPRESA
  LEFT JOIN TIPO_PRECO ON TIPO_PRECO.COD_TPPRECO = PROMOCAO_PRODUTO.COD_TPPRECO
      AND TIPO_PRECO.COD_EMPRESA = PROMOCAO_PRODUTO.COD_EMPRESA
      --    AND TIPO_PRECO.TIPO = 'P' 
  WHERE PROMOCAO_PRODUTO.GRUPO_PROD = :PGRUPO_PROD
      AND PROMOCAO_PRODUTO.COD_PROD = :PCOD_PROD
      AND PROMOCAO_PRODUTO.COD_EMPRESA = :PCOD_EMPRESA
      AND :CURRENT_TS >= COALESCE(PROMOCAO_PRODUTO.DATA_INI, PROMOCAO.DATA_INI)
      AND :CURRENT_TS <= COALESCE(PROMOCAO_PRODUTO.DATA_FIM, PROMOCAO.DATA_FIM) into :DESC_TABELA, :VALOR_TAB_PRO;

  if ((coalesce(VALOR_TAB_PRO, 0) <= 0) and (coalesce(VCOD_TAB_PRECO, 0) > 0)) then
  begin
    SELECT FIRST 1 PROMOCAO.DESCR_PROMOCAO, ROUND(PROMOCAO_PRODUTO.VALOR_PROMOCAO, 2)
    FROM PROMOCAO_PRODUTO
    INNER JOIN PROMOCAO ON PROMOCAO.COD_PROMOCAO = PROMOCAO_PRODUTO.COD_PROMOCAO
    AND PROMOCAO.COD_EMPRESA = PROMOCAO_PRODUTO.COD_EMPRESA
    AND PROMOCAO.ATIVO = 1
    LEFT JOIN TIPO_PRECO ON TIPO_PRECO.COD_TPPRECO = PROMOCAO_PRODUTO.COD_TPPRECO
    AND TIPO_PRECO.COD_EMPRESA = PROMOCAO_PRODUTO.COD_EMPRESA
    --AND TIPO_PRECO.TIPO = 'T'
    WHERE PROMOCAO_PRODUTO.GRUPO_PROD = :PGRUPO_PROD
    AND PROMOCAO_PRODUTO.COD_PROD = :PCOD_PROD
    AND PROMOCAO_PRODUTO.COD_EMPRESA = :PCOD_EMPRESA
    AND PROMOCAO_PRODUTO.COD_PROMOCAO = :VCOD_TAB_PRECO into :DESC_TABELA, :VALOR_TAB_PRO;
  end

  if (coalesce(VALOR_TAB_PRO, 0) <= 0) then
  begin
    SELECT 'PRECO DE TABELA', ROUND(PRODUTOS.PREC_TAB_PROD, 2) FROM PRODUTOS
    WHERE PRODUTOS.GRUPO_PROD = :PGRUPO_PROD
    AND PRODUTOS.COD_PROD = :PCOD_PROD
    AND PRODUTOS.COD_EMPRESA = :PCOD_EMPRESA into :DESC_TABELA, :VALOR_TAB_PRO;
  end

  suspend;
end
 
 ^

ALTER PROCEDURE RETORNA_EC_VLTB_PROMKIT (PCODIGO_KIT INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (VALOR_TAB_PROKIT DOUBLE PRECISION)
AS 
declare variable VGRUPO_PROD integer;
declare variable VCOD_PROD char(6);
declare variable VCOD_EMPRESA integer;
declare variable VQUANT_PROD_KIT double precision;
declare variable VVALOR_TEMP double precision;
begin
  VVALOR_TEMP = 0;
  VALOR_TAB_PROKIT = 0;

  for select kits_prod_kits.grupo_prod,
    kits_prod_kits.cod_prod,
    kits_prod_kits.cod_empresa,
    kits_prod_kits.quant_prod_kit from kits_prod
  inner join kits_prod_kits on kits_prod_kits.codigo_kit = kits_prod.codigo_kit and kits_prod_kits.cod_empresa = kits_prod.cod_empresa
  where kits_prod_kits.codigo_kit = :pcodigo_kit
  and kits_prod_kits.cod_empresa = :pcod_empresa
    into :vgrupo_prod, :vcod_prod, :vcod_empresa, :vquant_prod_kit do
  begin
    select valor_tab_pro FROM retorna_ec_vltb_prom(:vgrupo_prod, :vcod_prod, :vcod_empresa) into :vvalor_temp;

    VALOR_TAB_PROKIT = VALOR_TAB_PROKIT + (COALESCE(VQUANT_PROD_KIT, 0) * round(coalesce(VVALOR_TEMP, 0), 2));
  end
  suspend;
end ^

ALTER PROCEDURE RETORNA_ESTOQUE_ANT (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA INTEGER,
PDATA TIMESTAMP,
PPORGRADE INTEGER)
RETURNS (ESTOQUE DOUBLE PRECISION,
ESTOQUE_DIARIO DOUBLE PRECISION)
AS 
declare variable VEST double precision;
begin
  /* Procedure Text */
  estoque = 0;
  estoque_diario = 0;

  EXECUTE STATEMENT
  ' select sum(coalesce(est.estoque, 0)) estoque from estoque_diario est
    where est.dia = ''' || :pdata || '''
    and est.grupo_prod = ' || :pgrupo_prod || '
    and est.cod_prod = ''' || :pcod_prod || '''
    ' || iif(pporgrade > 0, ' and est.cod_grade = ' || :pcod_grade, '') || '
    and est.cod_empresa = ' || :pcod_empresa
     into :estoque_diario;

  EXECUTE STATEMENT
  ' select sum(coalesce(est.estoque, 0)) estoque from estoque_diario est
    where est.dia = (select first 1 est1.dia from estoque_diario est1
                     where est1.grupo_prod = est.grupo_prod
                     and est1.cod_prod = est.cod_prod
                     ' || iif(pporgrade > 0, ' and est1.cod_grade = ' || :pcod_grade, '') || '
                     and est1.cod_empresa = est.cod_empresa
                     and est1.dia <= ''' || (:pdata - 1) || '''
                     order by est1.dia desc)
    and est.grupo_prod = ' || :pgrupo_prod || '
    and est.cod_prod = ''' || :pcod_prod || '''
    ' || iif(pporgrade > 0, ' and est.cod_grade = ' || :pcod_grade, '') || '
    and est.cod_empresa = ' || :pcod_empresa
      into :vest;

  estoque = coalesce(estoque, 0) + coalesce(vest, 0);

  EXECUTE STATEMENT
  ' select sum(case when (hd.natureza = ''S'') then
                  - coalesce(hd.qtde, 0)
                else
                  coalesce(hd.qtde, 0)
           end) qtde from hist_estoque_diario hd
    where hd.grupo_prod = ' || :pgrupo_prod || '
    and hd.cod_prod = ''' || :pcod_prod || '''
    ' || iif(pporgrade > 0, ' and coalesce(hd.cod_grade, 0) = ' || :pcod_grade, '') || '
    and hd.tipor = ''COR''
    and hd.data = ''' || :pdata || '''
    and hd.cod_empresa = ' || :pcod_empresa
      into :vest;

  estoque = coalesce(estoque, 0) + coalesce(vest, 0);

  EXECUTE STATEMENT
  ' select sum(case when (hp.natureza = ''S'') then
                  - coalesce(hp.qtde, 0)
                else
                  coalesce(hp.qtde, 0)
           end) qtde from hist_estoque_diario_prod hp
    where hp.grupo_prod = ' || :pgrupo_prod || '
    and hp.cod_prod = ''' || :pcod_prod || '''
    ' || iif(pporgrade > 0, ' and coalesce(hp.cod_grade, 0) = ' || :pcod_grade, '') || '
    and hp.tipor = ''COR''
    and hp.data = ''' || :pdata || '''
    and hp.cod_empresa = ' || :pcod_empresa
      into :vest;

  estoque = coalesce(estoque, 0) + coalesce(vest, 0);

  EXECUTE STATEMENT
  ' select sum(case when grcomp.qtde is null then
                      coalesce(infe.quant_item_nfe, 0)
                    else
                      coalesce(grcomp.qtde, 0) end) quantidade
    from nf_entrada nfe
    inner join item_nf_entrada infe on
      infe.num_nota_nfe = nfe.num_nota_nfe
      and infe.cod_forn_nfe = nfe.cod_forn_nfe
      and infe.cod_empresa = nfe.cod_empresa
    left join cod_grade_prod_compra grcomp on
      infe.grupo_prod = grcomp.grupo_prod
      and infe.cod_prod = grcomp.cod_prod
      and infe.cod_empresa = grcomp.cod_empresa
      and infe.num_nota_nfe = grcomp.num_nota_nfe
      and infe.cod_forn_nfe = grcomp.cod_forn_nfe
    left join grade gra on
      grcomp.cod_grade = gra.cod_grade
      and grcomp.cod_empresa = gra.cod_empresa
    where nfe.data_lanc_nfe = ''' || :pdata || '''
    and nfe.cod_empresa = ' || :pcod_empresa || '
    and infe.grupo_prod = ' || :pgrupo_prod || '
    and infe.cod_prod = ''' || :pcod_prod || '''
    ' || iif(pporgrade > 0, ' and grcomp.cod_grade = ' || :pcod_grade, '') || '
    and infe.altera_estoque_cfop = ''S''
    and nfe.status_nfe = ''CONFIRMADA''
    and nfe.ativo = 1 '
      into :vest;

  estoque = coalesce(estoque, 0) + coalesce(vest, 0);

  EXECUTE STATEMENT
  ' select sum(coalesce(nfi.quantidade, 0)) quantidade from notafiscal nf
    inner join notafiscal_item nfi on
      nfi.cod_nf = nf.cod_nf
      and nfi.cod_empresa = nf.cod_empresa
    where nf.data_estoque = ''' || :pdata || '''
    and nf.cod_empresa = ' || :pcod_empresa || '
    and nfi.grupo_prod = ' || :pgrupo_prod || '
    and nfi.cod_prod = ''' || :pcod_prod || '''
    ' || iif(pporgrade > 0, ' and nfi.cod_grade = ' || :pcod_grade, '') || '
    and nf.natureza_nf = ''E''
    and (nf.status = ''Fechada'')
    and (nfi.altera_estoque_cfop <> ''N'' or nfi.altera_estoque_cfop is null)
    and nf.ativo = 1 '
      into :vest;

  estoque = coalesce(estoque, 0) + coalesce(vest, 0);

  EXECUTE STATEMENT
  ' select sum(coalesce(dev.quant, 0)) quantidade from devolucao dev
    left join grade gra on gra.cod_grade = dev.cod_grade and gra.cod_empresa = dev.cod_empresa
    where coalesce(dev.nf_gerou, '''') <> ''S''
    and dev.data_estoque = ''' || :pdata || '''
    and dev.grupo_prod = ' || :pgrupo_prod || '
    and dev.cod_prod = ''' || :pcod_prod || '''
    ' || iif(pporgrade > 0, ' and dev.cod_grade = ' || :pcod_grade, '') || '
    and dev.cod_empresa = ' || :pcod_empresa
      into :vest;

  estoque = coalesce(estoque, 0) + coalesce(vest, 0);

  EXECUTE STATEMENT
  ' select sum(coalesce(pi.quantidade, 0)) quantidade from producao pd
    inner join producao_item pi on
      pi.cod_producao = pd.cod_producao
      and pi.cod_empresa = pd.cod_empresa
    where pd.data_estoque = ''' || :pdata || '''
    and pi.grupo_prod = ' || :pgrupo_prod || '
    and pi.cod_prod = ''' || :pcod_prod || '''
    ' || iif(pporgrade > 0, ' and pi.cod_grade = ' || :pcod_grade, '') || '
    and pi.cod_empresa = ' || :pcod_empresa || '
    and pd.status = ''FECHADO'' '
      into :vest;

  estoque = coalesce(estoque, 0) + coalesce(vest, 0);

  EXECUTE STATEMENT
  ' select sum(coalesce(ipv.quant_ped_item, 0)) quantidade from pedvenda pv
    inner join pedvenda_prod ipv on ipv.tipo = pv.tipo and ipv.nped = pv.nped and ipv.cod_empresa = pv.cod_empresa
    where pv.data_estoque = ''' || :pdata || '''
    and ipv.grupo_prod = ' || :pgrupo_prod || '
    and ipv.cod_prod = ''' || :pcod_prod || '''
    ' || iif(pporgrade > 0, ' and ipv.cod_grade = ' || :pcod_grade, '') || '
    and pv.cod_empresa = ' || :pcod_empresa || '
    and pv.status_ped = ''FECHADA'' and pv.tipo <> ''ORC''
    and ((ipv.status is null) or (ipv.status <> ''CANCELADO''))
    and pv.ativo = 1 '
      into :vest;

  estoque = coalesce(estoque, 0) - coalesce(vest, 0);

  EXECUTE STATEMENT
  ' select sum(coalesce(pi.quantidade_utilizada, 0) + coalesce(pi.quantidade_perda, 0)) from producao pd
    inner join producao_item_indice pi on
      pi.cod_producao = pd.cod_producao
      and pi.cod_empresa = pd.cod_empresa
    where pd.data_estoque = ''' || :pdata || '''
    and pi.grupo_prod = ' || :pgrupo_prod || '
    and pi.cod_prod = ''' || :pcod_prod || '''
    ' || iif(pporgrade > 0, ' and pi.cod_grade = ' || :pcod_grade, '') || '
    and pi.cod_empresa = ' || :pcod_empresa || '
    and pd.status = ''FECHADO'' '
      into :vest;

  estoque = coalesce(estoque, 0) - coalesce(vest, 0);

  suspend;
end ^

ALTER PROCEDURE RETORNA_IMG_KIT (PCODIGO_KIT INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (CODIGO_KIT INTEGER,
COD_EMPRESA INTEGER,
LISTA_IMAGENS BLOB CHARACTER SET NONE,
URL_IMAGENS BLOB CHARACTER SET NONE,
COD_IMAGENS BLOB CHARACTER SET NONE)
AS 
declare variable VIMAGEM blob sub_type 1 segment size 256;
declare variable VURL blob sub_type 1 segment size 256;
declare variable VCOD_IMG integer;
begin
  /* Procedure Text */
  codigo_kit    = pcodigo_kit;
  cod_empresa   = pcod_empresa;
  lista_imagens = null;
  url_imagens   = null;
  cod_imagens   = null;

  select lista_imagens, url_imagens from kits_prod
  where codigo_kit = :pcodigo_kit
  and cod_empresa = :pcod_empresa
    into :lista_imagens, :url_imagens;

  if (trim(coalesce(lista_imagens, '')) = '') then
  begin
    for select img.imagem, img.url, img.cod_img from kits_prod_imagens pimg
        inner join imagens_doc img on
          img.cod_img = pimg.cod_img
          and img.cod_empresa = pimg.cod_empresa
        where pimg.codigo_kit = :pcodigo_kit
        and pimg.cod_empresa = :pcod_empresa
          into :vimagem, :vurl, :vcod_img do
    begin
      if (trim(coalesce(lista_imagens, '')) = '') then
        lista_imagens = :vimagem;
      else
        lista_imagens = lista_imagens || ASCII_CHAR(13) || :vimagem;

      if (trim(coalesce(url_imagens, '')) = '') then
        url_imagens = iif(trim(coalesce(vurl, '')) = '', 'sem url', :vurl);
      else
        url_imagens = url_imagens || ASCII_CHAR(13) || iif(trim(coalesce(vurl, '')) = '', 'sem url', :vurl);

      if (trim(coalesce(cod_imagens, '')) = '') then
        cod_imagens = :vcod_img;
      else
        cod_imagens = cod_imagens || ASCII_CHAR(13) || :vcod_img;
    end
  end
  suspend;
end ^

ALTER PROCEDURE RETORNA_IMG_PROD (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (GRUPO_PROD INTEGER,
COD_PROD CHAR(10) CHARACTER SET NONE,
COD_GRADE INTEGER,
COD_EMPRESA INTEGER,
LISTA_IMAGENS BLOB CHARACTER SET NONE,
URL_IMAGENS BLOB CHARACTER SET NONE,
COD_IMAGENS BLOB CHARACTER SET NONE)
AS 
declare variable VIMAGEM blob sub_type 1 segment size 256;
declare variable VURL blob sub_type 1 segment size 256;
declare variable VCOD_IMG integer;
begin
  /* Procedure Text */
  grupo_prod    = pgrupo_prod;
  cod_prod      = pcod_prod;
  cod_grade     = pcod_grade;
  cod_empresa   = pcod_empresa;
  lista_imagens = null;
  url_imagens   = null;
  cod_imagens   = null;

  select lista_imagens, url_imagens from produtos_imagens
  where grupo_prod = :pgrupo_prod
  and cod_prod = :pcod_prod
  and cod_grade = :pcod_grade
  and cod_empresa = :pcod_empresa
    into :lista_imagens, :url_imagens;

  if (trim(coalesce(lista_imagens, '')) = '') then
  begin
    for select img.imagem, img.url, img.cod_img from produtos_grade_imagens pimg
        inner join imagens_doc img on
          img.cod_img = pimg.cod_img
          and img.cod_empresa = pimg.cod_empresa
        where pimg.grupo_prod = :pgrupo_prod
        and pimg.cod_prod = :pcod_prod
        and pimg.cod_grade = :pcod_grade
        and pimg.cod_empresa = :pcod_empresa
          into :vimagem, :vurl, :vcod_img do
    begin
      if (trim(coalesce(lista_imagens, '')) = '') then
        lista_imagens = :vimagem;
      else
        lista_imagens = lista_imagens || ASCII_CHAR(13) || :vimagem;

      if (trim(coalesce(url_imagens, '')) = '') then
        url_imagens = iif(trim(coalesce(vurl, '')) = '', 'sem url', :vurl);
      else
        url_imagens = url_imagens || ASCII_CHAR(13) || iif(trim(coalesce(vurl, '')) = '', 'sem url', :vurl);

      if (trim(coalesce(cod_imagens, '')) = '') then
        cod_imagens = :vcod_img;
      else
        cod_imagens = cod_imagens || ASCII_CHAR(13) || :vcod_img;
    end
  end
  suspend;
end ^

ALTER PROCEDURE RETORNA_LISTAPROD_CASHBACK (PNDOC INTEGER,
PTIPODOC CHAR(3) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (GRUPO_PROD INTEGER,
COD_PROD CHAR(6) CHARACTER SET NONE,
COD_EMPRESA INTEGER,
NITEM INTEGER,
DESCR_PROD VARCHAR(75) CHARACTER SET NONE,
VALOR_TOT_ITEM DOUBLE PRECISION,
VALOR_DESCONTO DOUBLE PRECISION,
VALOR_ACRESCIMO DOUBLE PRECISION,
PERC_COMISSAO_CASHBACK DOUBLE PRECISION,
DIAS_VENC_CASHBACK INTEGER,
ATIVO INTEGER,
ID_INTEG BIGINT)
AS 
begin
  /* Procedure Text */
  if ((trim(coalesce(ptipodoc, '')) = 'REQ') or (trim(coalesce(ptipodoc, '')) = 'OS')) then
  begin
     for select
         pedvenda_prod.grupo_prod,
         pedvenda_prod.cod_prod,
         pedvenda_prod.cod_empresa,
         pedvenda_prod.nitem,
         pedvenda_prod.descr_prod_ped,
         pedvenda_prod.vltot_ped_item,
         pedvenda_prod.rateio_desc,
         pedvenda_prod.rateio_acresc,
         produtos.perc_comissao_cashback,
         produtos.dias_venc_cashback,
         produtos.ativo,
         produtos_integ.cod_integ from pedvenda
         inner join pedvenda_prod on pedvenda_prod.nped = pedvenda.nped and pedvenda_prod.tipo = pedvenda.tipo and pedvenda_prod.cod_empresa = pedvenda.cod_empresa
         inner join produtos on produtos.grupo_prod = pedvenda_prod.grupo_prod and produtos.cod_prod = pedvenda_prod.cod_prod and produtos.cod_empresa = pedvenda_prod.cod_empresa
         left join produtos_integ on produtos_integ.grupo_prod = produtos.grupo_prod and produtos_integ.cod_prod = produtos.cod_prod and produtos_integ.cod_empresa = produtos.cod_empresa
         where pedvenda.nped = :pndoc
         and pedvenda.tipo = :ptipodoc
         and pedvenda.cod_empresa = :pcod_empresa
           into :grupo_prod, :cod_prod, :cod_empresa, :nitem, :descr_prod, :valor_tot_item, :valor_desconto, :valor_acrescimo,
                :perc_comissao_cashback, :dias_venc_cashback, :ativo, :id_integ do
     begin
       suspend;
     end
  end
  else if (trim(coalesce(ptipodoc, '')) = 'DEV') then
  begin
     for select
         devolucao.grupo_prod,
         devolucao.cod_prod,
         devolucao.cod_empresa,
         devolucao.sequencia,
         devolucao.descricao,
         - abs(devolucao.valor) valor,
         0 valor_desconto,
         0 valor_acrescimo,
         produtos.perc_comissao_cashback,
         produtos.dias_venc_cashback,
         produtos.ativo,
         produtos_integ.cod_integ from devolucao
         inner join produtos on produtos.grupo_prod = devolucao.grupo_prod and produtos.cod_prod = devolucao.cod_prod and produtos.cod_empresa = devolucao.cod_empresa
         left join produtos_integ on produtos_integ.grupo_prod = produtos.grupo_prod and produtos_integ.cod_prod = produtos.cod_prod and produtos_integ.cod_empresa = produtos.cod_empresa and produtos_integ.tipo_integ = 0
         where devolucao.sequencia = :pndoc
         and devolucao.cod_empresa = :pcod_empresa
           into :grupo_prod, :cod_prod, :cod_empresa, :nitem, :descr_prod, :valor_tot_item, :valor_desconto, :valor_acrescimo,
                :perc_comissao_cashback, :dias_venc_cashback, :ativo, :id_integ do
     begin
       suspend;
     end

     if (coalesce(cod_empresa, 0) = 0) then
     begin
       for select
           hist_estoque_diario_prod.grupo_prod,
           hist_estoque_diario_prod.cod_prod,
           hist_estoque_diario_prod.cod_empresa,
           hist_estoque_diario_prod.numero,
           (coalesce(produtos.descr_prod, '') ||
            case when (hist_estoque_diario_prod.cod_grade > 0) then
                   ' ' || coalesce(grade.descricao, 0)
                 else
                   ''
            end
           ) descricao,
           - abs(hist_estoque_diario_prod.valor_tot) valor,
           0 valor_desconto,
           0 valor_acrescimo,
           produtos.perc_comissao_cashback,
           produtos.dias_venc_cashback,
           produtos.ativo,
           produtos_integ.cod_integ from hist_estoque_diario_prod
           inner join produtos on produtos.grupo_prod = hist_estoque_diario_prod.grupo_prod and produtos.cod_prod = hist_estoque_diario_prod.cod_prod and produtos.cod_empresa = hist_estoque_diario_prod.cod_empresa
           left join produtos_integ on produtos_integ.grupo_prod = produtos.grupo_prod and produtos_integ.cod_prod = produtos.cod_prod and produtos_integ.cod_empresa = produtos.cod_empresa and produtos_integ.tipo_integ = 0
           left join grade on grade.cod_grade = hist_estoque_diario_prod.cod_grade and grade.cod_empresa = hist_estoque_diario_prod.cod_empresa
           where hist_estoque_diario_prod.numero = :pndoc
           and hist_estoque_diario_prod.cod_empresa = :pcod_empresa
           and hist_estoque_diario_prod.natureza = 'E'
             into :grupo_prod, :cod_prod, :cod_empresa, :nitem, :descr_prod, :valor_tot_item, :valor_desconto, :valor_acrescimo,
                  :perc_comissao_cashback, :dias_venc_cashback, :ativo, :id_integ do
       begin
         suspend;
       end
     end
  end
end ^

ALTER PROCEDURE RETORNA_NUMDOC_INI_FIM (PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PDATAINI TIMESTAMP,
PDATAFIM TIMESTAMP)
RETURNS (NUMDOC_INI INTEGER,
NUMDOC_FIM INTEGER)
AS 
begin
  /* Procedure Text */
  if ((trim(ptipo) = 'REQ') or (trim(ptipo) = 'OS') or (trim(ptipo) = 'ORC')) then
  begin
    select first 1 pd.nped from pedvenda pd
    inner join pedvenda_prod pp on
      pp.nped = pd.nped
      and pp.tipo = pd.tipo
      and pp.cod_empresa = pd.cod_empresa
    where pp.tipo = :ptipo
    and pp.cod_empresa = :pcod_empresa
    and pp.grupo_prod = :pgrupo_prod
    and pp.cod_prod = :pcod_prod
    and pd.data_estoque >= :pdataini
    and pd.data_estoque <= :pdatafim
    order by pd.nped
      into :numdoc_ini;

    select first 1 pd.nped from pedvenda pd
    inner join pedvenda_prod pp on
      pp.nped = pd.nped
      and pp.tipo = pd.tipo
      and pp.cod_empresa = pd.cod_empresa
    where pp.tipo = :ptipo
    and pp.cod_empresa = :pcod_empresa
    and pp.grupo_prod = :pgrupo_prod
    and pp.cod_prod = :pcod_prod
    and pd.data_estoque >= :pdataini
    and pd.data_estoque <= :pdatafim
    order by pd.nped desc
      into :numdoc_fim;
  end
  else if (trim(ptipo) = 'NF') then
  begin
    select first 1 nf.cod_nf from notafiscal nf
    inner join notafiscal_item nfi on
      nfi.cod_nf = nf.cod_nf
      and nfi.cod_empresa = nf.cod_empresa
    where nf.natureza_nf = 'S'
    and nf.cod_empresa = :pcod_empresa
    and nfi.codigo_nop > 3000
    and nfi.grupo_prod = :pgrupo_prod
    and nfi.cod_prod = :pcod_prod
    and nf.data_lanc >= :pdataini
    and nf.data_lanc <= :pdatafim
    order by nf.cod_nf
      into :numdoc_ini;

    select first 1 nf.cod_nf from notafiscal nf
    inner join notafiscal_item nfi on
      nfi.cod_nf = nf.cod_nf
      and nfi.cod_empresa = nf.cod_empresa
    where nf.natureza_nf = 'S'
    and nf.cod_empresa = :pcod_empresa
    and nfi.codigo_nop > 3000
    and nfi.grupo_prod = :pgrupo_prod
    and nfi.cod_prod = :pcod_prod
    and nf.data_lanc >= :pdataini
    and nf.data_lanc <= :pdatafim
    order by nf.cod_nf desc
      into :numdoc_fim;
  end
  else if (trim(ptipo) = 'DEV') then
  begin
    select first 1 dev.sequencia from devolucao dev
    where dev.grupo_prod = :pgrupo_prod
    and dev.cod_prod = :pcod_prod
    and dev.cod_empresa = :pcod_empresa
    and dev.data_estoque >= :pdataini
    and dev.data_estoque <= :pdataini
    order by dev.sequencia
      into :numdoc_ini;

    select first 1 dev.sequencia from devolucao dev
    where dev.grupo_prod = :pgrupo_prod
    and dev.cod_prod = :pcod_prod
    and dev.cod_empresa = :pcod_empresa
    and dev.data_estoque >= :pdataini
    and dev.data_estoque <= :pdataini
    order by dev.sequencia desc
      into :numdoc_ini;
  end

  suspend;
end;
 
 ^

ALTER PROCEDURE RETORNA_NUM_COM_FAT (PCOD_NF INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (N_COMANDO INTEGER)
AS 
BEGIN
  select cf.n_comando from com_fat cf
  where cf.cod_nf = :pcod_nf and cf.cod_empresa = :pcod_empresa into: n_comando;
  n_comando = coalesce(n_comando, 0);
  SUSPEND;
END ^

ALTER PROCEDURE RETORNA_PAG_CH (PLOTE INTEGER,
PDATA_LOTE TIMESTAMP,
PCOD_EMPRESA INTEGER,
PVER_FORMAS INTEGER,
PFORM_PAG VARCHAR(200) CHARACTER SET NONE)
RETURNS (ENCONTROU INTEGER,
FORM_PAG VARCHAR(200) CHARACTER SET NONE,
FORM_PAG2 VARCHAR(200) CHARACTER SET NONE)
AS 
declare variable VTEMP varchar(200);
declare variable VTEMP2 varchar(200);
declare variable VCONTROLE varchar(35);
declare variable VVALOR double precision;
begin
  /* Procedure Text */
  encontrou = 0;
  form_pag = '';
  form_pag2 = '';

  if (coalesce(pver_formas, 0) = 0) then
  begin
    suspend;
    exit;
  end

  if (coalesce(plote, 0) <= 0) then
  begin
    suspend;
    exit;
  end

  if (trim(coalesce(pform_pag, '')) = '') then
  begin
    for select distinct det.nome_ctrl, sum(coalesce(det.valor, 0)) valor from det_recebimentos_ch det
        left join empresa emp on emp.cod_empresa = det.cod_empresa
        where iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, det.cod_empresa) = :pcod_empresa
        and det.lote = :plote
        and det.data_lote = iif(emp.financeiro_unificado = 'S', :pdata_lote, det.data_lote)
        group by 1
        order by 1
       into :vcontrole, :vvalor do
    begin
      encontrou = 1;

      vtemp = trim(coalesce(vtemp, '')) ||
        iif (trim(coalesce(vtemp, '')) = '', '', ' | ') ||
            trim(coalesce(vcontrole, ''));

      vtemp2 = trim(coalesce(vtemp2, '')) ||
        iif (trim(coalesce(vtemp2, '')) = '', '', ' | ') ||
            trim(coalesce(vcontrole, '')) ||
                ' (R$' || trim(cast(cast(vvalor as numeric(12, 2)) as varchar(24))) || ')';
    end

    if (character_length(vtemp) > 200) then
      form_pag = trim(substring(trim(vtemp) from 1 for 200));
    else
      form_pag = trim(vtemp);

    if (character_length(vtemp2) > 200) then
      form_pag2 = trim(substring(trim(vtemp2) from 1 for 200));
    else
      form_pag2 = trim(vtemp2);
    suspend;
  end
  else
  begin
    for select distinct det.nome_ctrl, sum(coalesce(det.valor, 0)) valor from det_recebimentos_ch det
        left join empresa emp on emp.cod_empresa = det.cod_empresa
        where iif(emp.financeiro_unificado = 'S', emp.codigo_unificadora, det.cod_empresa) = :pcod_empresa
        and det.lote = :plote
        and det.data_lote = iif(emp.financeiro_unificado = 'S', :pdata_lote, det.data_lote)
        and det.nome_ctrl like :pform_pag
        group by 1
        order by 1
       into :vcontrole, :vvalor do
    begin
      encontrou = 1;

      vtemp = trim(coalesce(vtemp, '')) ||
        iif (trim(coalesce(vtemp, '')) = '', '', ' | ') ||
            trim(coalesce(vcontrole, ''));

      vtemp2 = trim(coalesce(vtemp2, '')) ||
        iif (trim(coalesce(vtemp2, '')) = '', '', ' | ') ||
            trim(coalesce(vcontrole, '')) ||
                ' (R$' || trim(cast(cast(vvalor as numeric(12, 2)) as varchar(24))) || ')';
    end

    if (character_length(vtemp) > 200) then
      form_pag = trim(substring(trim(vtemp) from 1 for 200));
    else
      form_pag = trim(vtemp);

    if (character_length(vtemp2) > 200) then
      form_pag2 = trim(substring(trim(vtemp2) from 1 for 200));
    else
      form_pag2 = trim(vtemp2);
    suspend;
  end
end ^

