ALTER PROCEDURE RETORNA_PEND_CONFERE (PNSU VARCHAR(20) CHARACTER SET NONE,
PAUT VARCHAR(20) CHARACTER SET NONE,
PNPARCELA INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (RESULT INTEGER)
AS 
begin
  result = 0;
  if ((trim(coalesce(pnsu, '')) = '') and (trim(coalesce(paut, '')) = '')) then
    suspend;
  else if ((trim(coalesce(pnsu, '')) <> '') and (trim(coalesce(paut, '')) <> '')) then
  begin
    execute statement
      ' select first 1 cf.id from conciliacao_financeiro cf
        left join conciliacao_adquirente adq on
          adq.id = cf.acquirer_id
        left join conciliacao_status_pag_adq stpag_adq on
          stpag_adq.codigo = cf.status_pag_cod
          and stpag_adq.id_adquirente = adq.id
        left join conciliacao_status_pag stpag on
          stpag.id = stpag_adq.id_status_pag
        where (select result from retirar_zero_esquerda (cf.nsu)) = ''' || (select result from retirar_zero_esquerda (:pnsu)) || '''
        and cf.authorization_number = ''' || :paut || '''
        and coalesce(cf.installment_number, 1) = ' || coalesce(:pnparcela, 1) || '
        and cf.cod_empresa = ' || :pcod_empresa || '
        and stpag_adq.status = ''P'''
          into :result;
  end
  else if (trim(coalesce(pnsu, '')) <> '') then
  begin
    execute statement
      ' select first 1 cf.id from conciliacao_financeiro cf
        left join conciliacao_adquirente adq on
          adq.id = cf.acquirer_id
        left join conciliacao_status_pag_adq stpag_adq on
          stpag_adq.codigo = cf.status_pag_cod
          and stpag_adq.id_adquirente = adq.id
        left join conciliacao_status_pag stpag on
          stpag.id = stpag_adq.id_status_pag
        where (select result from retirar_zero_esquerda (cf.nsu)) = ''' || (select result from retirar_zero_esquerda (:pnsu)) || '''
        and coalesce(cf.installment_number, 1) = ' || coalesce(:pnparcela, 1) || '
        and cf.cod_empresa = ' || :pcod_empresa || '
        and stpag_adq.status = ''P'''
      into :result;
  end

  suspend;
end ^

ALTER PROCEDURE RETORNA_QTDE_COND (PNDOC INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER)
RETURNS (RESULT DOUBLE PRECISION)
AS 
declare variable VTEMP varchar(50);
begin
  /* Procedure Text */
  result = 0;
  vtemp = '';
  if (pcod_grade > 0) then
    vtemp = ' and c.cod_grade = ' || :pcod_grade;

  execute statement
  ' select sum(coalesce(c.quantidade, 0)) quantidade from pedvenda_prod_cond_dev c
    where c.nped = ' || :pndoc || '
    and c.tipo = ''' || :ptipo || '''
    and c.grupo_prod = ' || :pgrupo_prod || '
    and c.cod_prod = ''' || :pcod_prod || '''
    and c.cod_empresa = ' || :pcod_empresa ||
    vtemp
      into :result;

  result = coalesce(result, 0);
  suspend;
end ^

ALTER PROCEDURE RETORNA_QTDE_COND_PAG (PCOND_PAG VARCHAR(30) CHARACTER SET NONE)
RETURNS (QTDE_PARC INTEGER,
DIAS_PRAZO INTEGER)
AS 
declare variable I integer;
declare variable J integer;
declare variable VTEMP varchar(30);
begin
  /* Procedure Text */
  if  ((select result from pos('X', upper(:pcond_pag))) > 0) then
  begin
    vtemp = trim(substring(:pcond_pag from 1 for (select result from Pos('X', upper(:pcond_pag))) - 1));
    if (char_length(trim(pcond_pag)) = (char_length(trim(vtemp)) + 1)) then
    begin
      qtde_parc  = (select result from sonumeros (:vtemp));
      dias_prazo = (30 * qtde_parc);
      suspend;
      exit;
    end
  end

  if ((select result from pos('VISTA', :pcond_pag)) > 0) then
  begin
    qtde_parc = 1;
    dias_prazo = 0;
    suspend;
    exit;
  end
  else if ((select result from pos('NENHUMA', :pcond_pag)) > 0) then
  begin
    qtde_parc = 0;
    dias_prazo = 0;
    suspend;
    exit;
  end
  else
  begin
    vtemp = '';
    qtde_parc = 0;
    i = 1;
    j = char_length(trim(pcond_pag));
    while (i <= j) do
    begin
      if ((select result from sonumeros (substring(:pcond_pag from :i for 1))) <> '') then
        vtemp = vtemp || substring(:pcond_pag from i for 1);
      else if (trim(vtemp) <> '') then
      begin
        qtde_parc = qtde_parc + 1;
        dias_prazo = cast(trim(vtemp) as Integer);
        vtemp = '';
      end
      i = i + 1;
    end
  end

  suspend;
end ^

ALTER PROCEDURE RETORNA_QTDE_COND_VND (PNDOC INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PVALOR_TOT DOUBLE PRECISION)
RETURNS (VALOR_TOTAL_COND DOUBLE PRECISION,
VALOR_TOTAL_DEV_COND DOUBLE PRECISION)
AS 
begin
  /* Procedure Text */
  valor_total_cond     = 0;
  valor_total_dev_cond = 0;

  execute statement
  ' select sum(
        coalesce(c.quantidade, 0) *
        coalesce((select first 1 coalesce(pp.vlun_ped_item, 0) from pedvenda_prod pp
        where pp.nped = c.nped
        and pp.tipo = c.tipo
        and pp.grupo_prod = c.grupo_prod
        and pp.cod_prod = c.cod_prod
        and pp.cod_empresa = c.cod_empresa
        and (pp.status<>''CANCELADO'' or pp.status is null)), 0)
    ) quantidade from pedvenda_prod_cond_dev c
    where c.nped = ' || :pndoc || '
    and c.tipo = ''' || :ptipo || '''
    and c.cod_empresa = ' || :pcod_empresa
      into :valor_total_dev_cond;

  valor_total_cond     = coalesce(pvalor_tot, 0) + coalesce(valor_total_dev_cond, 0);
  valor_total_dev_cond = coalesce(valor_total_dev_cond, 0);
  suspend;
end ^

ALTER PROCEDURE RETORNA_QTDE_DEV_ITEM (PNDOC INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER,
PNITEM INTEGER)
RETURNS (RESULT DOUBLE PRECISION)
AS 
declare variable VNITEM integer;
declare variable VCODIGO_NOP double precision;
declare variable VQUANT_PED_ITEM double precision;
declare variable VQUANT_DEV_REST double precision;
declare variable VQUANT_DEV_TOT double precision;
begin
  /* Procedure Text */
  result = 0;

  execute statement
  ' select sum(coalesce(d.quant, 0)) quantidade from devolucao d
    where d.cod_venda = ' || :pndoc || '
    and d.tipo_venda = ''' || :ptipo || '''
    and d.grupo_prod = ' || :pgrupo_prod || '
    and d.cod_prod = ''' || :pcod_prod || '''
    and d.cod_grade = ' || :pcod_grade || '
    and d.cod_empresa = ' || :pcod_empresa
    into :vquant_dev_tot;

  vquant_dev_rest = coalesce(vquant_dev_tot, 0);

  for execute statement
  ' select
    pp.nitem,
    pp.codigo_nop,
    coalesce(pp.quant_ped_item, 0) quant_ped_item from pedvenda_prod pp
    where pp.nped = ' || :pndoc || '
    and pp.tipo = ''' || :ptipo || '''
    and pp.grupo_prod = ' || :pgrupo_prod || '
    and pp.cod_prod = ''' || :pcod_prod || '''
    and pp.cod_grade = ' || :pcod_grade || '
    and pp.cod_empresa = ' || :pcod_empresa || '
    and (pp.status<>''CANCELADO'' or pp.status is null)
    order by pp.nped, pp.tipo, pp.grupo_prod, pp.cod_prod, pp.nitem, pp.cod_empresa, pp.cod_grade, pp.codigo_nop '
      into :vnitem, :vcodigo_nop, :vquant_ped_item do
  begin
    if (pnitem = vnitem) then
    begin
      if ((coalesce(vquant_dev_rest, 0) > 0) and (coalesce(vquant_dev_rest, 0) > coalesce(vquant_ped_item, 0))) then
        result = coalesce(vquant_ped_item, 0);
      else if ((coalesce(vquant_dev_rest, 0) > 0) and (coalesce(vquant_dev_rest, 0) <= coalesce(vquant_ped_item, 0))) then
        result = coalesce(vquant_dev_rest, 0);
      else
        result = 0;
      break;
    end

    if ((coalesce(vquant_dev_rest, 0) > 0) and (coalesce(vquant_dev_rest, 0) > coalesce(vquant_ped_item, 0))) then
      vquant_dev_rest = vquant_dev_rest - vquant_ped_item;
    else if ((coalesce(vquant_dev_rest, 0) > 0) and (coalesce(vquant_dev_rest, 0) <= coalesce(vquant_ped_item, 0))) then
      vquant_dev_rest = vquant_dev_rest - vquant_ped_item;
    else
      vquant_dev_rest = 0;
  end

  result = coalesce(result, 0);
  suspend;
end ^

ALTER PROCEDURE RETORNA_QTDE_DEV_VND (PNDOC INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PVALOR_TOT DOUBLE PRECISION)
RETURNS (VALOR_TOTAL_DEV DOUBLE PRECISION,
VALOR_TOTAL_APOS_DEV DOUBLE PRECISION)
AS 
begin
  /* Procedure Text */
  valor_total_dev = 0;
  execute statement
  ' select sum(coalesce(d.quant, 0) * coalesce(d.valor, 0)) quantidade from devolucao d
    where d.cod_venda = ' || :pndoc || '
    and d.tipo_venda = ''' || :ptipo || '''
    and d.cod_empresa = ' || :pcod_empresa
      into :valor_total_dev;

  valor_total_dev = coalesce(valor_total_dev, 0);
  valor_total_apos_dev = coalesce(pvalor_tot, 0) - coalesce(valor_total_dev, 0);
  suspend;
end ^

ALTER PROCEDURE RETORNA_QTDE_KIT (NPED INTEGER,
TIPO CHAR(3) CHARACTER SET NONE,
COD_EMPRESA INTEGER)
RETURNS (QTDE DOUBLE PRECISION)
AS 
declare variable VTEMP double precision;
declare variable QTDE_KIT double precision;
declare variable QTDE_PROD double precision;
declare variable VID_KIT integer;
begin
  qtde_kit = 0;
  qtde_prod = 0;
  for select distinct coalesce(pp.id_kit, 0) from pedvenda_prod pp
      where pp.nped = :nped
      and pp.tipo = :tipo
      and pp.cod_empresa = :cod_empresa
      and coalesce(pp.status, '') = ''
    and pp.id_kit > 0
        into :vid_kit do
  begin
    qtde_kit = qtde_kit + 1;
  end

  for select sum(coalesce((case when (trim(coalesce(pp.unidade_conv, '')) = '') then
                           coalesce(pp.quant_ped_item, 0)
                         when (trim(coalesce(pp.unidade, '')) = trim(coalesce(pp.unidade_conv, ''))) then
                           coalesce(pp.quant_ped_item, 0)
                         when ((coalesce(pp.operacao_conv, '') = 'M') AND (coalesce(pp.fator_conv, 0) > 0)) then
                           (coalesce(pp.quant_ped_item, 0) * coalesce(pp.fator_conv, 0))
                         when ((coalesce(pp.operacao_conv, '') = 'D') AND (coalesce(pp.fator_conv, 0) > 0)) then
                           (coalesce(pp.quant_ped_item, 0) / coalesce(pp.fator_conv, 0))
                         else
                           coalesce(pp.quant_ped_item, 0)
                        end), 0)) from pedvenda_prod pp
      where pp.nped = :nped
      and pp.tipo = :tipo
      and pp.cod_empresa = :cod_empresa
      and coalesce(pp.status, '') = ''
      and coalesce(pp.codigo_kit, 0) <= 0
      union
      select sum(coalesce(ppt.qtde, 0)) from pedvenda_prod_terc ppt
      where ppt.nped = :nped
      and ppt.tipo = :tipo
      and ppt.cod_empresa = :cod_empresa
          into :vtemp do
  begin
    qtde_prod = qtde_prod + vtemp;
  end

  qtde = coalesce(qtde_kit, 0) + coalesce(qtde_prod, 0);
  suspend;
end ^

ALTER PROCEDURE RETORNA_QTDE_MES_ULT_GER (PCOD_CONTRATO INTEGER,
PCOD_EMPRESA INTEGER,
PCOD_CLIENTE INTEGER,
PDIA_VENCIMENTO INTEGER,
PDIAS_APOS_VENC INTEGER,
PCOD_VENDEDOR INTEGER,
PCOD_CONTROLE INTEGER,
TIPO_OS VARCHAR(40) CHARACTER SET NONE,
PGERAR_CONTRATO_CADA_MES INTEGER,
PDATA_BASE_VENDA TIMESTAMP,
PAGRUPAR_CTR INTEGER,
PDESCONS_REGRA_CTRL INTEGER)
RETURNS (CONTRATOS_CADA_MES INTEGER,
QTDE_MES_ULT_GER INTEGER)
AS 
declare variable VTEMP_CTR_MES integer;
declare variable VTEMP_QTDE_MES integer;
declare variable VCTR_MES_PROD integer;
declare variable VCTR_MES_SERV integer;
declare variable VQTDE_MES_PROD integer;
declare variable VQTDE_MES_SERV integer;
declare variable VTEMP_SQL varchar(2000);
begin
  /* Procedure Text */
  contratos_cada_mes   = 0;
  qtde_mes_ult_ger = 0;
  if (coalesce(pagrupar_ctr, 0) = 0) then
  begin
    vtemp_sql =
      ' select coalesce(ctr.contratos_cada_mes, 1) contratos_cada_mes,
               coalesce((select case when (max(pd.data_fech) is null) then
                               datediff(month, date ''01.01.2000'', cast(''' || :pdata_base_venda || ''' as timestamp))
                             else
                               datediff(month, max(pd.data_fech), cast(''' || :pdata_base_venda || ''' as timestamp))
                        end
                 from pedvenda pd
                 inner join pedvenda_prod pdp on pdp.nped = pd.nped and pdp.tipo = pd.tipo and pdp.cod_empresa = pd.cod_empresa
                 where pdp.cod_contrato = ctr.cod_contrato
                 and pdp.tipo = ''OS''
                 and pdp.cod_empresa = ctr.cod_empresa
                 and pd.status_ped = ''FECHADA''
                 and (pdp.status <> ''CANCELADO'' or pdp.status is null)), 0) qtde_mes_ult_ger

        from clientes cl
        inner join clientes_com_contrato ctr on ctr.cod_cliente = cl.cod_cliente and ctr.cod_empresa = cl.cod_empresa
        where ctr.cod_contrato = ' || :pcod_contrato || '
        and ctr.cod_empresa = ' || :pcod_empresa || '
        order by 1, 2 ';

     execute statement
       vtemp_sql
        into :vtemp_ctr_mes, :vtemp_qtde_mes;
     begin
       vctr_mes_prod  = coalesce(vtemp_ctr_mes, 1);
       vqtde_mes_prod = coalesce(vtemp_qtde_mes, 0);
     end

    vtemp_sql =
      ' select coalesce(ctr.contratos_cada_mes, 1) contratos_cada_mes,
               coalesce((select case when (max(pd.data_fech) is null) then
                               datediff(month, date ''01.01.2000'', cast(''' || :pdata_base_venda || ''' as timestamp))
                             else
                               datediff(month, max(pd.data_fech), cast(''' || :pdata_base_venda || ''' as timestamp))
                        end
                 from pedvenda pd
                 inner join pedvenda_serv pds on pds.nped = pd.nped and pds.tipo = pd.tipo and pds.cod_empresa = pd.cod_empresa
                 where pds.cod_contrato = ctr.cod_contrato
                 and pds.tipo = ''OS''
                 and pds.cod_empresa = ctr.cod_empresa
                 and pd.status_ped = ''FECHADA''
                 and (pds.status <> ''CANCELADO'' or pds.status is null)), 0) qtde_mes_ult_ger

        from clientes cl
        inner join clientes_com_contrato ctr on ctr.cod_cliente = cl.cod_cliente and ctr.cod_empresa = cl.cod_empresa
        where ctr.cod_contrato = ' || :pcod_contrato || '
        and ctr.cod_empresa = ' || :pcod_empresa || '
        order by 1, 2 ';

    execute statement
      vtemp_sql
        into :vtemp_ctr_mes, :vtemp_qtde_mes;
    begin
      vctr_mes_serv  = coalesce(vtemp_ctr_mes, 1);
      vqtde_mes_serv = coalesce(vtemp_qtde_mes, 0);
    end

    contratos_cada_mes = coalesce(vctr_mes_prod, 0);
    qtde_mes_ult_ger   = coalesce(vqtde_mes_prod , 0);

    if ((coalesce(vqtde_mes_serv, 0) < coalesce(qtde_mes_ult_ger, 0))) then
    begin
      qtde_mes_ult_ger   = coalesce(vqtde_mes_serv, 0);
      contratos_cada_mes = coalesce(vctr_mes_serv, 0);
    end

    if (coalesce(contratos_cada_mes, 0) <= 0) then
      contratos_cada_mes = coalesce(vctr_mes_serv, 0);
  end
  else
  begin
    vtemp_sql =
      ' select first 1
               coalesce(ctr.contratos_cada_mes, 1) contratos_cada_mes,
               coalesce((select case when (max(pd.data_fech) is null) then
                                       datediff(month, date ''01.01.2000'', cast(''' || :pdata_base_venda || ''' as timestamp))
                                     else
                                       datediff(month, max(pd.data_fech), cast(''' || :pdata_base_venda || ''' as timestamp))
                                end
                         from pedvenda pd
                         inner join pedvenda_prod pdp on pdp.nped = pd.nped and pdp.tipo = pd.tipo and pdp.cod_empresa = pd.cod_empresa
                         where pdp.cod_contrato = ctr.cod_contrato
                         and pdp.tipo = ''OS''
                         and pdp.cod_empresa = ctr.cod_empresa
                         and pd.status_ped = ''FECHADA''
                         and (pdp.status <> ''CANCELADO'' or pdp.status is null)), 0) qtde_mes_ult_ger
        from clientes cl
        inner join clientes_com_contrato ctr on ctr.cod_cliente = cl.cod_cliente and ctr.cod_empresa = cl.cod_empresa
        inner join controles ctrl on ctrl.codigo_ctrl = ctr.cod_controle and ctrl.codigo_emp = ctr.cod_empresa
        left join colaborador col on col.cod_vendedor = ctr.cod_vendedor and col.cod_empresa = ctr.cod_empresa
        where ctr.cod_cliente = ' || :pcod_cliente || '
        and ctr.cod_empresa = ' || :pcod_empresa || '
        and coalesce(ctr.dia_vencimento, 0) = ' || :pdia_vencimento || '
        and coalesce(ctr.dias_apos_venc, 0) = ' || :pdias_apos_venc || '
        and ctr.cod_vendedor = ' || :pcod_vendedor || '
        and ctr.cod_controle = ' || :pcod_controle || '
        and ctr.tipo_os = ''' || :tipo_os || '''
        and coalesce(ctr.contratos_cada_mes, 1) = ' || :pgerar_contrato_cada_mes || '
        and ctr.status = ''Ativo''
        and ((ctr.data_inicial_vigencia is null) or (ctr.data_inicial_vigencia <= ''' || :pdata_base_venda || ''')) ';

    if (coalesce(pdescons_regra_ctrl, 0) = 0) then
    begin
      vtemp_sql = vtemp_sql ||
        ' and (not ctr.DATA_INICIAL_BOLETO is null) and (ctr.DATA_INICIAL_BOLETO <= ''' || :pdata_base_venda || ''') ';
    end

    vtemp_sql = vtemp_sql ||
      ' order by 1, 2 ';

    execute statement
      vtemp_sql
        into :vtemp_ctr_mes, :vtemp_qtde_mes;
    begin
      vctr_mes_prod = coalesce(vtemp_ctr_mes, 1);
      vqtde_mes_prod     = coalesce(vtemp_qtde_mes, 0);
    end

    vtemp_sql =
      ' select first 1
               coalesce(ctr.contratos_cada_mes, 1) contratos_cada_mes,
               coalesce((select case when (max(pd.data_fech) is null) then
                                       datediff(month, date ''01.01.2000'', cast(''' || :pdata_base_venda || ''' as timestamp))
                                     else
                                       datediff(month, max(pd.data_fech), cast(''' || :pdata_base_venda || ''' as timestamp))
                                end
                         from pedvenda pd
                         inner join pedvenda_serv pds on pds.nped = pd.nped and pds.tipo = pd.tipo and pds.cod_empresa = pd.cod_empresa
                         where pds.cod_contrato = ctr.cod_contrato
                         and pds.tipo = ''OS''
                         and pds.cod_empresa = ctr.cod_empresa
                         and pd.status_ped = ''FECHADA''
                         and (pds.status <> ''CANCELADO'' or pds.status is null)), 0) qtde_mes_ult_ger
        from clientes cl
        inner join clientes_com_contrato ctr on ctr.cod_cliente = cl.cod_cliente and ctr.cod_empresa = cl.cod_empresa
        inner join controles ctrl on ctrl.codigo_ctrl = ctr.cod_controle and ctrl.codigo_emp = ctr.cod_empresa
        left join colaborador col on col.cod_vendedor = ctr.cod_vendedor and col.cod_empresa = ctr.cod_empresa
        where ctr.cod_cliente = ' || :pcod_cliente || '
        and ctr.cod_empresa = ' || :pcod_empresa || '
        and coalesce(ctr.dia_vencimento, 0) = ' || :pdia_vencimento || '
        and coalesce(ctr.dias_apos_venc, 0) = ' || :pdias_apos_venc || '
        and ctr.cod_vendedor = ' || :pcod_vendedor || '
        and ctr.cod_controle = ' || :pcod_controle || '
        and ctr.tipo_os = ''' || :tipo_os || '''
        and coalesce(ctr.contratos_cada_mes, 1) = ' || :pgerar_contrato_cada_mes || '
        and ctr.status = ''Ativo''
        and ((ctr.data_inicial_vigencia is null) or (ctr.data_inicial_vigencia <= ''' || :pdata_base_venda || ''')) ';

    if (coalesce(pdescons_regra_ctrl, 0) = 0) then
    begin
      vtemp_sql = vtemp_sql ||
        ' and (not ctr.DATA_INICIAL_BOLETO is null) and (ctr.DATA_INICIAL_BOLETO <= ''' || :pdata_base_venda || ''') ';
    end

    vtemp_sql = vtemp_sql ||
      ' order by 1, 2 ';

    execute statement
      vtemp_sql
        into :vtemp_ctr_mes, :vtemp_qtde_mes;
    begin
      vctr_mes_serv  = coalesce(vtemp_ctr_mes, 1);
      vqtde_mes_serv = coalesce(vtemp_qtde_mes, 0);
    end

    contratos_cada_mes = coalesce(vctr_mes_prod, 0);
    qtde_mes_ult_ger   = coalesce(vqtde_mes_prod , 0);

    if ((coalesce(vqtde_mes_serv, 0) < coalesce(qtde_mes_ult_ger, 0))) then
    begin
      qtde_mes_ult_ger   = coalesce(vqtde_mes_serv, 0);
      contratos_cada_mes = coalesce(vctr_mes_serv, 0);
    end

    if (coalesce(contratos_cada_mes, 0) <= 0) then
      contratos_cada_mes = coalesce(vctr_mes_serv, 0);
  end

  contratos_cada_mes = coalesce(contratos_cada_mes, 0);
  qtde_mes_ult_ger   = coalesce(qtde_mes_ult_ger, 0);
  suspend;
end ^

ALTER PROCEDURE RETORNA_QTDE_VALOR_DEV (PNDOC INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER,
PGRUPO_PROD INTEGER,
PCOD_PROD CHAR(6) CHARACTER SET NONE,
PCOD_GRADE INTEGER)
RETURNS (QTDE_VND DOUBLE PRECISION,
VALOR_VND_TOT DOUBLE PRECISION,
QTDE_DEV DOUBLE PRECISION,
VALOR_DEV_TOT DOUBLE PRECISION,
COMISSAO_PROD DOUBLE PRECISION)
AS 
declare variable VTEMP varchar(50);
begin
  /* Procedure Text */
  qtde_vnd = 0;
  valor_vnd_tot = 0;
  qtde_dev = 0;
  valor_dev_tot = 0;
  comissao_prod = 0;
  vtemp = '';

  if (pcod_grade > 0) then
    vtemp = ' and pp.cod_grade = ' || :pcod_grade;

  if (ptipo = 'DEV') then
  begin
    execute statement
    ' select sum(coalesce(pp.quant_ped_item, 0)) quantidade,
      sum(coalesce(pp.vltot_ped_item, 0)) vltot_ped_item from devolucao dev
      inner join pedvenda_prod pp on
        pp.nped = dev.cod_venda
        and pp.tipo = dev.tipo_venda
        and pp.grupo_prod = dev.grupo_prod
        and pp.cod_prod = dev.cod_prod
        and pp.cod_empresa = dev.cod_empresa
        and pp.cod_grade = dev.cod_grade
        and (pp.status <> ''CANCELADO'' or pp.status is null)
      where dev.sequencia = ' || :pndoc || '
      and dev.grupo_prod = ' || :pgrupo_prod || '
      and dev.cod_prod = ''' || :pcod_prod || '''
      and pp.cod_empresa = ' || :pcod_empresa ||
      vtemp
        into :qtde_vnd, :valor_vnd_tot;

  end
  else
  begin
    execute statement
    ' select sum(coalesce(pp.quant_ped_item, 0)) quantidade,
      sum(coalesce(pp.vltot_ped_item, 0)) valor_tot from pedvenda pd
      inner join pedvenda_prod pp on
        pd.nped = pp.nped
        and pd.tipo = pp.tipo
        and pd.cod_empresa = pp.cod_empresa
      where pp.nped = ' || :pndoc || '
      and pp.tipo = ''' || :ptipo || '''
      and pp.grupo_prod = ' || :pgrupo_prod || '
      and pp.cod_prod = ''' || :pcod_prod || '''
      and (pp.status <> ''CANCELADO'' or pp.status is null)
      and pp.cod_empresa = ' || :pcod_empresa ||
      vtemp
        into :qtde_vnd, :valor_vnd_tot;
  end

  qtde_vnd = coalesce(qtde_vnd, 0);
  valor_vnd_tot = coalesce(valor_vnd_tot, 0);

  if (pcod_grade > 0) then
    vtemp = ' and d.cod_grade = ' || :pcod_grade;

  if (ptipo = 'DEV') then
  begin
    execute statement
    ' select sum(coalesce(d.quant, 0)) quantidade,
      sum(coalesce(d.quant, 0) * coalesce(d.valor, 0)) valor_tot from devolucao d
      where d.sequencia = ' || :pndoc || '
      and d.grupo_prod = ' || :pgrupo_prod || '
      and d.cod_prod = ''' || :pcod_prod || '''
      and d.cod_empresa = ' || :pcod_empresa ||
      vtemp
        into :qtde_dev, :valor_dev_tot;
  end
  else
  begin
    execute statement
    ' select sum(coalesce(d.quant, 0)) quantidade,
      sum(coalesce(d.quant, 0) * coalesce(d.valor, 0)) valor_tot from devolucao d
      where d.cod_venda = ' || :pndoc || '
      and d.tipo_venda = ''' || :ptipo || '''
      and d.grupo_prod = ' || :pgrupo_prod || '
      and d.cod_prod = ''' || :pcod_prod || '''
      and d.cod_empresa = ' || :pcod_empresa ||
      vtemp
        into :qtde_dev, :valor_dev_tot;
  end

  qtde_dev = coalesce(qtde_dev, 0);
  valor_dev_tot = coalesce(valor_dev_tot, 0);

  if ((ptipo = 'DEV') and (coalesce(qtde_dev, 0) > 0) and (coalesce(qtde_vnd, 0) > 0)) then
    comissao_prod = (coalesce(qtde_dev, 0) * ((coalesce(valor_dev_tot, 0) / coalesce(qtde_dev, 0)) - (coalesce(valor_vnd_tot, 0) / coalesce(qtde_vnd, 0))));
  else
    comissao_prod = 0;
  suspend;
end ^

ALTER PROCEDURE RETORNA_VALOR_BOL_CTR (PCOD_CONTRATO INTEGER,
PCOD_EMPRESA INTEGER,
PCOD_CLIENTE INTEGER,
PDIA_VENCIMENTO INTEGER,
PDIAS_APOS_VENC INTEGER,
PCOD_VENDEDOR INTEGER,
PCOD_CONTROLE INTEGER,
PTIPO_OS VARCHAR(40) CHARACTER SET NONE,
PGERAR_CONTRATO_CADA_MES INTEGER,
PDATA_BASE_VENDA TIMESTAMP,
PAGRUPAR_CTR INTEGER,
PDESCONS_REGRA_CTRL INTEGER)
RETURNS (VALOR_BOLETO DOUBLE PRECISION)
AS 
declare variable VTEMP_SQL varchar(2000);
begin
  /* Procedure Text */
  valor_boleto = 0;

  if (coalesce(pagrupar_ctr, 0) = 0) then
  begin
    vtemp_sql =
      ' select coalesce(ctr1.valor_contrato, 0) from clientes_com_contrato ctr1
        left join controles ctrl on
          ctrl.codigo_ctrl = ctr1.cod_controle
          and ctrl.codigo_emp = ctr1.cod_empresa
        where ctr1.cod_contrato = ' || :pcod_contrato || '
        and ctr1.cod_empresa = ' || :pcod_empresa || '
        and ctr1.status = ''Ativo''
        and ((ctr1.data_inicial_vigencia is null) or (ctr1.data_inicial_vigencia <= ''' || :pdata_base_venda || '''))
        and (not ctr1.data_inicial_boleto is null) and (ctr1.data_inicial_boleto <= ''' || :pdata_base_venda || ''')
        and coalesce(ctrl.nao_gera_finan, ''N'') <> ''S''
        and ctrl.usar_boleto = ''S'' ';

    execute statement
      vtemp_sql
        into :valor_boleto;
    
    valor_boleto = coalesce(valor_boleto, 0);
  end
  else
  begin
    vtemp_sql =
      ' select sum(coalesce(ctr1.valor_contrato, 0)) from clientes_com_contrato ctr1
        left join controles ctrl on
          ctrl.codigo_ctrl = ctr1.cod_controle
          and ctrl.codigo_emp = ctr1.cod_empresa
        where ctr1.cod_cliente = ' || :pcod_cliente || '
        and ctr1.cod_empresa = ' || :pcod_empresa || '
        and coalesce(ctr1.dia_vencimento, 0) = ' || :pdia_vencimento || '
        and coalesce(ctr1.dias_apos_venc, 0) = ' || :pdias_apos_venc || '
        and ctr1.cod_vendedor = ' || :pcod_vendedor || '
        and ctr1.cod_controle = ' || :pcod_controle || '
        and ctr1.tipo_os = ''' || :ptipo_os || '''
        and coalesce(ctr1.contratos_cada_mes, 1) = ' || :pgerar_contrato_cada_mes || '
        and ctr1.status = ''Ativo''
        and ((ctr1.data_inicial_vigencia is null) or (ctr1.data_inicial_vigencia <= ''' || :pdata_base_venda || '''))
        and (not ctr1.data_inicial_boleto is null) and (ctr1.data_inicial_boleto <= ''' || :pdata_base_venda || ''')
        and coalesce(ctrl.nao_gera_finan, ''N'') <> ''S''
        and ctrl.usar_boleto = ''S'' ';

    execute statement
      vtemp_sql
        into :valor_boleto;

    valor_boleto = coalesce(valor_boleto, 0);
  end
  suspend;
end ^

ALTER PROCEDURE RETORNA_VALOR_CTR (PCOD_CONTRATO INTEGER,
PCOD_EMPRESA INTEGER,
PCOD_CLIENTE INTEGER,
PDIA_VENCIMENTO INTEGER,
PDIAS_APOS_VENC INTEGER,
PCOD_VENDEDOR INTEGER,
PCOD_CONTROLE INTEGER,
PTIPO_OS VARCHAR(40) CHARACTER SET NONE,
PGERAR_CONTRATO_CADA_MES INTEGER,
PDATA_BASE_VENDA TIMESTAMP,
PAGRUPAR_CTR INTEGER,
PDESCONS_REGRA_CTRL INTEGER)
RETURNS (VALOR_CONTRATO DOUBLE PRECISION,
VALOR_PROD DOUBLE PRECISION,
VALOR_SERV DOUBLE PRECISION)
AS 
declare variable VTEMP_SQL varchar(2000);
begin
  /* Procedure Text */
  if (coalesce(pagrupar_ctr, 0) = 0) then
  begin
    vtemp_sql =
      ' select coalesce(ctr1.valor_contrato, 0) valor_contrato,
        coalesce(ctr1.valor_prod, 0) valor_prod,
        coalesce(ctr1.valor_serv, 0) valor_serv from clientes_com_contrato ctr1
        where ctr1.cod_contrato = ' || :pcod_contrato || '
        and ctr1.cod_empresa = ' || :pcod_empresa;

    execute statement
      vtemp_sql
        into :valor_contrato, :valor_prod, :valor_serv;
  end
  else
  begin
    vtemp_sql =
      ' select sum(coalesce(ctr1.valor_contrato, 0)) valor_contrato,
        sum(coalesce(ctr1.valor_prod, 0)) valor_prod,
        sum(coalesce(ctr1.valor_serv, 0)) valor_serv from clientes_com_contrato ctr1
        where ctr1.cod_cliente = ' || :pcod_cliente || '
        and ctr1.cod_empresa = ' || :pcod_empresa || '
        and coalesce(ctr1.dia_vencimento, 0) = ' || :pdia_vencimento || '
        and coalesce(ctr1.dias_apos_venc, 0) = ' || :pdias_apos_venc || '
        and ctr1.cod_vendedor = ' || :pcod_vendedor || '
        and ctr1.cod_controle = ' || :pcod_controle || '
        and ctr1.tipo_os = ''' || :ptipo_os || '''
        and coalesce(ctr1.contratos_cada_mes, 1) = ' || :pgerar_contrato_cada_mes || '
        and ctr1.status = ''Ativo''
        and ((ctr1.data_inicial_vigencia is null)
              or (ctr1.data_inicial_vigencia <= ''' || :pdata_base_venda || ''')) ';

    if (coalesce(pdescons_regra_ctrl, 0) = 0) then
    begin
      vtemp_sql = vtemp_sql ||
        ' and (not ctr1.data_inicial_boleto is null)
          and (ctr1.data_inicial_boleto <= ''' || :pdata_base_venda || ''') ';
    end

    execute statement
      vtemp_sql
        into :valor_contrato, :valor_prod, :valor_serv;
  end

  valor_contrato = coalesce(valor_contrato, 0);
  valor_prod     = coalesce(valor_prod, 0);
  valor_serv     = coalesce(valor_serv, 0);
  suspend;
end ^

ALTER PROCEDURE RETORNA_VEICULO (PCHASSI VARCHAR(17) CHARACTER SET NONE,
PPLACA VARCHAR(10) CHARACTER SET NONE,
PCODIGO INTEGER,
PCOD_EMPRESA INTEGER)
RETURNS (ICHASSI VARCHAR(17) CHARACTER SET NONE,
IPLACA VARCHAR(10) CHARACTER SET NONE,
ICODIGO INTEGER,
ICOD_EMPRESA INTEGER)
AS 
begin
  /* Procedure Text */
  pplaca = trim(coalesce(pplaca, ''));
  pchassi = trim(coalesce(pchassi, ''));
  pcodigo = coalesce(pcodigo, 0);
  pcod_empresa = coalesce(pcod_empresa, 0);

  iplaca = '';
  ichassi = '';
  icodigo = 0;
  if ((trim(pchassi) <> '') and (trim(pplaca) <> '') and (pcodigo > 0))  then
  begin
    select first 1 veiculos.placa, veiculos.chassi, veiculos.codigo, veiculos.cod_empresa from veiculos
    where veiculos.placa = :pplaca
    and veiculos.chassi = :pchassi
    and veiculos.codigo = :pcodigo
    and veiculos.cod_empresa = :pcod_empresa
    and veiculos.ativo <> 99
        into :iplaca, :ichassi, :icodigo, :icod_empresa;

    if ((trim(ichassi) = '') or (trim(iplaca) = '') or (pcodigo <= 0))  then
    begin
      if ((trim(pplaca) <> '') and (trim(iplaca) = '')) then
      begin
        select first 1 veiculos.placa, veiculos.chassi, veiculos.codigo, veiculos.cod_empresa from veiculos
        where veiculos.placa = :pplaca
        and veiculos.cod_empresa = :pcod_empresa
        and veiculos.ativo <> 99
            into :iplaca, :ichassi, :icodigo, :icod_empresa;
      end
      if ((trim(pchassi) <> '') and (trim(ichassi) = '')) then
      begin
        select first 1 veiculos.placa, veiculos.chassi, veiculos.codigo, veiculos.cod_empresa from veiculos
        where veiculos.chassi = :pchassi
        and veiculos.cod_empresa = :pcod_empresa
        and veiculos.ativo <> 99
            into :iplaca, :ichassi, :icodigo, :icod_empresa;
      end
      if ((pcodigo > 0) and (icodigo <= 0)) then
      begin
        select first 1 veiculos.placa, veiculos.chassi, veiculos.codigo, veiculos.cod_empresa from veiculos
        where veiculos.codigo = :pcodigo
        and veiculos.cod_empresa = :pcod_empresa
        and veiculos.ativo <> 99
            into :iplaca, :ichassi, :icodigo, :icod_empresa;
      end
    end
  end
  else if (trim(pplaca) <> '') then
  begin
    select first 1 veiculos.placa, veiculos.chassi, veiculos.codigo, veiculos.cod_empresa from veiculos
    where veiculos.placa = :pplaca
    and veiculos.cod_empresa = :pcod_empresa
    and veiculos.ativo <> 99
        into :iplaca, :ichassi, :icodigo, :icod_empresa;
  end
  else if (trim(pchassi) <> '') then
  begin
    select first 1 veiculos.placa, veiculos.chassi, veiculos.codigo, veiculos.cod_empresa from veiculos
    where veiculos.chassi = :pchassi
    and veiculos.cod_empresa = :pcod_empresa
    and veiculos.ativo <> 99
        into :iplaca, :ichassi, :icodigo, :icod_empresa;
  end
  else if (pcodigo > 0) then
  begin
    select first 1 veiculos.placa, veiculos.chassi, veiculos.codigo, veiculos.cod_empresa from veiculos
    where veiculos.codigo = :pcodigo
    and veiculos.cod_empresa = :pcod_empresa
    and veiculos.ativo <> 99
        into :iplaca, :ichassi, :icodigo, :icod_empresa;
  end
  suspend;
end;
 
 ^

ALTER PROCEDURE RETORNA_VL_CHQ_ABERTO (PCOD_CLIENTE INTEGER,
PCOD_EMPRESA INTEGER,
PCPF_CNPJ VARCHAR(18) CHARACTER SET NONE)
RETURNS (VALOR_CHQ DOUBLE PRECISION)
AS 
declare variable VSQL varchar(1000);
declare variable VFINANCEIRO_UNIFICADO char(1);
declare variable VVALOR_CHQ double precision;
begin
  /* Procedure Text */

  valor_chq = 0;

  select empresa.financeiro_unificado from empresa where empresa.cod_empresa = :pcod_empresa into :vfinanceiro_unificado;

  vsql =
    ' select sum(coalesce(formpagamento.valordoc, 0)) soma from formpagamento
      inner join empresa on empresa.cod_empresa = formpagamento.cod_empresa
      inner join clientes on
        clientes.cod_cliente = formpagamento.cod_cliente
        and clientes.cod_empresa = formpagamento.cod_empresa
      inner join controles on
        controles.codigo_ctrl = formpagamento.cod_controle
        and controles.codigo_emp = formpagamento.cod_empresa
        and trim(coalesce(controles.exibir_doc, ''A'')) in ('''', ''A'', ''L'') ';

  if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpf_cnpj, '') <> '')) then
    vsql = vsql ||
      ' where clientes.cpfcgc = ''' || :pcpf_cnpj || ''' ';
  else
    vsql = vsql ||
      ' where formpagamento.cod_cliente = ' || :pcod_cliente;

  vsql = vsql ||
    ' and formpagamento.tipdoc = ''S1'' and formpagamento.tpdocs <> ''PRE'' and formpagamento.prcss is null ';

  if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpf_cnpj, '') <> '')) then
    vsql = vsql ||
      ' and empresa.codigo_unificadora = ' || :pcod_empresa;
  else
    vsql = vsql ||
      ' and formpagamento.cod_empresa = ' || :pcod_empresa;

  vsql = vsql ||
    ' and formpagamento.data_mov >= (current_date - 365) ';

  execute statement
    vsql into :vvalor_chq;

  valor_chq = coalesce(valor_chq, 0) + coalesce(vvalor_chq, 0);
    
  vsql =
    ' select sum(coalesce(controle_cheque.valor_ch, 0)) soma from controle_cheque
      inner join clientes on clientes.cod_cliente = controle_cheque.cod_cliente and clientes.cod_empresa = controle_cheque.cod_emp_mult
      inner join empresa on empresa.cod_empresa = controle_cheque.codigo_emp
      inner join controles on
        controles.codigo_ctrl = controle_cheque.codigo_ctrl
        and controles.codigo_emp = controle_cheque.codigo_emp
        and trim(coalesce(controles.exibir_doc, ''A'')) in ('''', ''A'', ''L'') ';

  if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpf_cnpj, '') <> '')) then
    vsql = vsql ||
      ' where clientes.cpfcgc = ''' || :pcpf_cnpj || ''' ';
  else
    vsql = vsql ||
      ' where controle_cheque.codigo_emp = ' || :pcod_empresa;

  vsql = vsql ||
    '  and (controle_cheque.status_ch is null or controle_cheque.status_ch = '''') ';

  if ((coalesce(vfinanceiro_unificado, 'N') = 'S') and (coalesce(pcpf_cnpj, '') <> '')) then
    vsql = vsql ||
      ' and empresa.codigo_unificadora = ' || :pcod_empresa;
  else
    vsql = vsql ||
      ' and controle_cheque.codigo_emp = ' || :pcod_empresa;

  execute statement
    vsql into :vvalor_chq;

  valor_chq = coalesce(valor_chq, 0) + coalesce(vvalor_chq, 0);

  suspend;
end ^

