  valor_cred = coalesce(valor_cred, 0) + coalesce(vvalor_cred, 0);

  suspend;
end ^

ALTER PROCEDURE RETORNA_VL_RECANT_ABERTO (PCOD_CLIENTE INTEGER,
PCOD_EMPRESA INTEGER,
PCPF_CNPJ VARCHAR(18) CHARACTER SET NONE)
RETURNS (VALOR_REC DOUBLE PRECISION)
AS 
begin
  /* Procedure Text */
  if (coalesce(pcpf_cnpj, '') <> '') then
  begin
    select sum(coalesce(recibos.valor, 0)) soma from recibos
    inner join empresa on empresa.cod_empresa = recibos.cod_empresa
    inner join clientes on
      clientes.cod_cliente = recibos.cod_benef
      and clientes.cod_empresa = recibos.cod_empresa
    where clientes.cpfcgc = :pcpf_cnpj
    and ((recibos.recant = 'S') or (recibos.recant = 'O'))
    and (case when(empresa.financeiro_unificado = 'S') then empresa.codigo_unificadora else recibos.cod_empresa end) = :pcod_empresa
    and recibos.ativo = 1
    and ((recibos.status_rec is null) or (recibos.status_rec <> 'RECEBIDO'))
      into :valor_rec;
  end
  else
  begin
    select sum(coalesce(recibos.valor, 0)) soma from recibos
    inner join empresa on empresa.cod_empresa = recibos.cod_empresa
    inner join clientes on
      clientes.cod_cliente = recibos.cod_benef
      and clientes.cod_empresa = recibos.cod_empresa
    where recibos.cod_benef = :pcod_cliente
    and ((recibos.recant = 'S') or (recibos.recant = 'O'))
    and (case when(empresa.financeiro_unificado = 'S') then empresa.codigo_unificadora else recibos.cod_empresa end) = :pcod_empresa
    and recibos.ativo = 1
    and ((recibos.status_rec is null) or (recibos.status_rec <> 'RECEBIDO'))
      into :valor_rec;
  end

  valor_rec = coalesce(valor_rec, 0);
  suspend;
end ^

ALTER PROCEDURE RET_DADOS_ULT_COMPRA (PCOD_EMPRESA INTEGER,
PCOD_CLIENTE INTEGER)
RETURNS (NDOC INTEGER,
TIPO CHAR(3) CHARACTER SET NONE,
DATA_FECH TIMESTAMP,
VALOR_TOTAL DOUBLE PRECISION)
AS 
declare variable VNDOC integer;
declare variable VTIPO char(3);
declare variable VDATA_FECH timestamp;
declare variable VVALOR_TOTAL double precision;
begin
  /* Procedure Text */
  ndoc = 0;
  tipo = '';
  data_fech = null;
  valor_total = 0;

  vndoc = 0;
  vtipo = '';
  vdata_fech = null;
  vvalor_total = 0;

  select first 1 nped, tipo, data_fech, valor_total from pedvenda
  where trim(tipo) in ('REQ', 'OS')
  and status_ped = 'FECHADA'
  and data_fech is not null
  and cod_empresa = :pcod_empresa
  and cod_cliente = :pcod_cliente
  order by 3 desc, 1 desc
   into :ndoc, :tipo, :data_fech, :valor_total;

  select first 1 n_comando, 'MOT' tipo, data_fech, valtot_v from com_fat
  where natureza = 'S'
  and status_v = 'FECHADO'
  and data_fech is not null
  and cod_empresa = :pcod_empresa
  and clientes_v = 9999
  order by 3 desc, 1 desc
    into :vndoc, :vtipo, :vdata_fech, :vvalor_total;

  if ((vndoc > 0) and (ndoc <= 0)) then
  begin
    ndoc = vndoc;
    tipo = :vtipo;
    data_fech = :vdata_fech;
    valor_total = :vvalor_total;
  end
  else if ((ndoc > 0) and (vndoc > 0)) then
  begin
    if (vdata_fech >= :data_fech) then
    begin
      ndoc = vndoc;
      tipo = :vtipo;
      data_fech = :vdata_fech;
      valor_total = :vvalor_total;
    end
  end

  suspend;
end;
 
 ^

ALTER PROCEDURE SAIDAS_RECEB_MERCADORIA_CXL (PDATAINI TIMESTAMP,
PDATAFIM TIMESTAMP,
PCODEMPRESA INTEGER,
POPCXL INTEGER,
PAGRUPAROPERADORES CHAR(1) CHARACTER SET NONE)
RETURNS (ORDEM INTEGER,
MODALIDADE VARCHAR(30) CHARACTER SET NONE,
TIPO CHAR(10) CHARACTER SET NONE,
NOME_CLIENTE VARCHAR(50) CHARACTER SET NONE,
OP_CXL INTEGER,
NOME_OP_CXL VARCHAR(35) CHARACTER SET NONE,
DATA_FECH TIMESTAMP,
NPED INTEGER,
VALOR_TOTAL DOUBLE PRECISION,
VALOR_LOTE DOUBLE PRECISION,
QTDE_LOTE INTEGER,
COD_CRED INTEGER,
AGRUPAR_OPERADORES CHAR(1) CHARACTER SET NONE,
FINANCEIRO_UNIFICADO CHAR(1) CHARACTER SET NONE,
COD_EMPRESA INTEGER,
COD_EMP_MULT INTEGER,
CODEMPRESA_TEMP INTEGER,
IDENTIFICACAO_EMP_TEMP VARCHAR(64) CHARACTER SET NONE,
EXIBIR_EMP CHAR(1) CHARACTER SET NONE,
VALORDINHEIRO DOUBLE PRECISION,
VALORRECEBIMENTO DOUBLE PRECISION,
DATA_INI TIMESTAMP,
DATA_FIM TIMESTAMP)
AS 
begin
  /* Procedure Text */
  for select case when (pv.tipo = 'REQ') then 2 else 3 end ordem,
    'A Vista' modalidade, pv.tipo, cl.nome_cliente,
    case when (:pagruparoperadores = 'S') then null else pv.op_cxl end op_cxl,
    case when (:pagruparoperadores = 'S') then null else col.nome_vendedor end nome_op_cxl,
    pv.dia_cxl as data_fech, pv.nped,
    coalesce(pv.valor_total, 0) valor_total,
    coalesce(pv.valor_total, 0) valor_lote,
    1 qtde_lote,
    null cod_cred,
    :pAgruparOperadores agrupar_operadores,
    emp.financeiro_unificado,
    pv.cod_empresa as cod_empresa,
    pv.cod_empresa as cod_emp_mult,
    emp2.cod_empresa as codempresa_temp,
    emp2.identificacao_emp as identificacao_emp_temp,
    'N' as exibir_emp,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
             inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
             where fp.nrequisicao = pv.nped and fp.tpdocs = pv.tipo and fp.cod_empresa = pv.cod_empresa
             and ctr.docs = 'N'
             and coalesce(fp.recibo, '') <> 'S'
             and coalesce(ctr.nao_gera_finan, '') <> 'S'), 0) valordinheiro,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
             inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
             where fp.nrequisicao = pv.nped and fp.tpdocs = pv.tipo and fp.cod_empresa = pv.cod_empresa), 0) valorrecebimento,
    cast(:pdataIni as timestamp) data_ini, cast(:pdataFim  as timestamp) data_fim
    from pedvenda pv
    inner join empresa emp on emp.cod_empresa = pv.cod_empresa
    left join empresa emp2 on emp2.cod_empresa = pv.cod_empresa
    inner join clientes cl on cl.cod_cliente = pv.cod_cliente and cl.cod_empresa = pv.cod_empresa
    left join colaborador col on col.cod_vendedor = pv.op_cxl and col.cod_empresa = pv.cod_empresa
    where pv.dia_cxl >= :pdataIni
    and pv.dia_cxl <= :pdataFim
    and pv.cod_empresa = :pCodEmpresa
    and pv.tipo <> 'ORC'
    and pv.status_ped = 'FECHADA'
    and (select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
         inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
         where fp.nrequisicao = pv.nped and fp.tpdocs = pv.tipo and fp.cod_empresa = pv.cod_empresa
         and ctr.docs = 'N'
         and coalesce(fp.recibo, '') <> 'S'
         and coalesce(ctr.nao_gera_finan, '') <> 'S') > 0
    union
    select case when (pv.tipo = 'REQ') then 2 else 3 end ordem,
    'Detalhes' modalidade, pv.tipo, cl.nome_cliente,
    case when (:pagruparoperadores = 'S') then null else pv.op_cxl end op_cxl,
    case when (:pagruparoperadores = 'S') then null else col.nome_vendedor end nome_op_cxl,
    pv.dia_cxl as data_fech, pv.nped,
    coalesce(pv.valor_total, 0) valor_total,
    coalesce(pv.valor_total, 0) valor_lote,
    1 qtde_lote,
    null cod_cred,
    :pAgruparOperadores agrupar_operadores,
    emp.financeiro_unificado,
    pv.cod_empresa as cod_empresa,
    pv.cod_empresa as cod_emp_mult,
    emp2.cod_empresa as codempresa_temp,
    emp2.identificacao_emp as identificacao_emp_temp,
    'N' as exibir_emp,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = pv.nped and fp.tpdocs = pv.tipo and fp.cod_empresa = pv.cod_empresa
              and ctr.docs = 'N'
              and coalesce(fp.recibo, '') <> 'S'
              and coalesce(ctr.nao_gera_finan, '') <> 'S'), 0) valordinheiro,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = pv.nped and fp.tpdocs = pv.tipo and fp.cod_empresa = pv.cod_empresa), 0) valorrecebimento,
    cast(:pdataIni  as timestamp) data_ini, cast(:pdataFim  as timestamp) data_fim
    from pedvenda pv
    inner join empresa emp on emp.cod_empresa = pv.cod_empresa
    left join empresa emp2 on emp2.cod_empresa = pv.cod_empresa
    inner join clientes cl on cl.cod_cliente = pv.cod_cliente and cl.cod_empresa = pv.cod_empresa
    left join colaborador col on col.cod_vendedor = pv.op_cxl and col.cod_empresa = pv.cod_empresa
    where pv.dia_cxl >= :pdataIni
    and pv.dia_cxl <= :pdataFim
    and pv.cod_empresa = :pCodEmpresa
    and pv.tipo <> 'ORC'
    and pv.status_ped = 'FECHADA'
    union
    select 4 ordem, 'A Vista' modalidade, 'REC' tipo, cl.nome_cliente,
    case when (:pagruparoperadores = 'S') then null else rec.op_cxl end op_cxl,
    case when (:pagruparoperadores = 'S') then null else col.nome_vendedor end nome_op_cxl,
    rec.dia_cxl as data_fech, rec.nrecibo,
    coalesce(rec.valor_orig, 0) valor_total,
    coalesce(rec.valor_orig, 0) valor_lote,
    1 qtde_lote,
    null cod_cred,
    :pAgruparOperadores agrupar_operadores,
    emp.financeiro_unificado,
    rec.cod_empresa as cod_empresa,
    rec.cod_empresa as cod_emp_mult,
    emp2.cod_empresa as codempresa_temp,
    emp2.identificacao_emp as identificacao_emp_temp,
    'N' as exibir_emp,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = rec.nrecibo and fp.tpdocs = 'REC' and fp.cod_empresa = rec.cod_empresa
              and ctr.docs = 'N'
              and coalesce(fp.recibo, '') <> 'S'
              and coalesce(ctr.nao_gera_finan, '') <> 'S'), 0) valordinheiro,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = rec.nrecibo and fp.tpdocs = 'REC' and fp.cod_empresa = rec.cod_empresa), 0) valordinheiro,
    cast(:pdataIni as timestamp) data_ini, cast(:pdataFim  as timestamp) data_fim from recibos rec
    inner join empresa emp on emp.cod_empresa = rec.cod_empresa
    left join empresa emp2 on emp2.cod_empresa = rec.cod_empresa
    inner join clientes cl on cl.cod_cliente = rec.cod_devedor and cl.cod_empresa = rec.cod_empresa
    left join colaborador col on col.cod_vendedor = rec.op_cxl and col.cod_empresa = rec.cod_empresa
    where rec.dia_cxl >= :pdataIni
    and rec.dia_cxl <= :pdataFim
    and rec.cod_empresa = :pCodEmpresa
    and (select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
         inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
         where fp.nrequisicao = rec.nrecibo and fp.tpdocs = 'REC' and fp.cod_empresa = rec.cod_empresa
         and ctr.docs = 'N'
         and coalesce(fp.recibo, '') <> 'S'
         and coalesce(ctr.nao_gera_finan, '') <> 'S') > 0
    union
    select 4 ordem, 'Detalhes' modalidade, 'REC' tipo, cl.nome_cliente,
    case when (:pagruparoperadores = 'S') then null else rec.op_cxl end op_cxl,
    case when (:pagruparoperadores = 'S') then null else col.nome_vendedor end nome_op_cxl,
    rec.dia_cxl as data_fech, rec.nrecibo,
    coalesce(rec.valor_orig, 0) valor_total,
    coalesce(rec.valor_orig, 0) valor_lote,
    1 qtde_lote,
    null cod_cred,
    :pAgruparOperadores agrupar_operadores,
    emp.financeiro_unificado,
    rec.cod_empresa as cod_empresa,
    rec.cod_empresa as cod_emp_mult,
    emp2.cod_empresa as codempresa_temp,
    emp2.identificacao_emp as identificacao_emp_temp,
    'N' as exibir_emp,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = rec.nrecibo and fp.tpdocs = 'REC' and fp.cod_empresa = rec.cod_empresa
              and ctr.docs = 'N'
              and coalesce(fp.recibo, '') <> 'S'
              and coalesce(ctr.nao_gera_finan, '') <> 'S'), 0) valordinheiro,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = rec.nrecibo and fp.tpdocs = 'REC' and fp.cod_empresa = rec.cod_empresa), 0) valorrecebimento,
    cast(:pdataIni as timestamp) data_ini, cast(:pdataFim  as timestamp) data_fim from recibos rec
    inner join empresa emp on emp.cod_empresa = rec.cod_empresa
    left join empresa emp2 on emp2.cod_empresa = rec.cod_empresa
    inner join clientes cl on cl.cod_cliente = rec.cod_devedor and cl.cod_empresa = rec.cod_empresa
    left join colaborador col on col.cod_vendedor = rec.op_cxl and col.cod_empresa = rec.cod_empresa
    where rec.dia_cxl >= :pdataIni
    and rec.dia_cxl <= :pdataFim
    and rec.cod_empresa = :pCodEmpresa
    union
    select 5 ordem, 'A Vista' modalidade, 'PRE' tipo, cl.nome_cliente,
    case when (:pagruparoperadores = 'S') then null else cc.op_cxl end op_cxl,
    case when (:pagruparoperadores = 'S') then null else col.nome_vendedor end nome_op_cxl,
    cc.dia_cxl as data_fech, cc.lote_cxl,
