    coalesce((select sum(coalesce(cc1.vl_rq_pg_cxl,0)) from controle_creditos cc1
              where cc1.lote_cxl = cc.lote_cxl
              and cc1.codigo_emp = cc.cod_emp_mult), 0) valor_lote,
    (select count(*) from controle_creditos cc1
      where cc1.lote_cxl = cc.lote_cxl
      and cc1.codigo_emp = cc.cod_emp_mult) qtde_lote,
    cc.cod_cred,
    :pAgruparOperadores agrupar_operadores,
    emp.financeiro_unificado,
    cc.cod_emp_mult as cod_empresa,
    cc.cod_emp_mult,
    emp2.cod_empresa as codempresa_temp,
    emp2.identificacao_emp as identificacao_emp_temp,
    'N' as exibir_emp,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = cc.lote_cxl and fp.tpdocs = 'PRE' and fp.cod_empresa = cc.cod_emp_mult
              and ctr.docs = 'N'
              and coalesce(fp.recibo, '') <> 'S'
              and coalesce(ctr.nao_gera_finan, '') <> 'S'), 0) valordinheiro,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = cc.lote_cxl and fp.tpdocs = 'PRE' and fp.cod_empresa = cc.cod_emp_mult), 0) valorrecebimento,
    cast(:pdataIni as timestamp) data_ini, cast(:pdataFim  as timestamp) data_fim from controle_creditos cc
    inner join empresa emp on emp.cod_empresa = cc.codigo_emp
    left join empresa emp2 on emp2.cod_empresa = cc.cod_emp_mult
    inner join clientes cl on cl.cod_cliente = cc.cod_cliente and cl.cod_empresa = cc.cod_emp_mult
    left join colaborador col on col.cod_vendedor = cc.op_cxl and col.cod_empresa = cc.cod_emp_mult
    where cc.dia_cxl >= :pdataIni
    and cc.dia_cxl <= :pdataFim
    and cc.cod_emp_mult = :pCodEmpresa
    and (select count(fp.cod_controle) from formpagamento fp
         inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
         where fp.nrequisicao = cc.lote_cxl and fp.tpdocs = 'PRE' and fp.cod_empresa = cc.cod_emp_mult
         and ctr.docs = 'N'
         and coalesce(fp.recibo, '') <> 'S'
