    (select count(*) from controle_creditos cc1
      where cc1.lote_cxl = cc.lote_cxl
      and cc1.codigo_emp = cc.cod_emp_mult) qtde_lote,
    cc.cod_cred,
    :pAgruparOperadores agrupar_operadores,
    emp.financeiro_unificado,
    cc.cod_emp_mult as cod_empresa,
    cc.cod_emp_mult,
    emp2.cod_empresa as codempresa_temp,
    emp2.identificacao_emp as identificacao_emp_temp,
    'N' as exibir_emp,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = cc.lote_cxl and fp.tpdocs = 'PRE' and fp.cod_empresa = cc.cod_emp_mult
              and ctr.docs = 'N'
              and coalesce(fp.recibo, '') <> 'S'
              and coalesce(ctr.nao_gera_finan, '') <> 'S'), 0) valordinheiro,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = cc.lote_cxl and fp.tpdocs = 'PRE' and fp.cod_empresa = cc.cod_emp_mult), 0) valorrecebimento,
    cast(:pdataIni as timestamp) data_ini, cast(:pdataFim  as timestamp) data_fim from controle_creditos cc
    inner join empresa emp on emp.cod_empresa = cc.codigo_emp
    left join empresa emp2 on emp2.cod_empresa = cc.cod_emp_mult
    inner join clientes cl on cl.cod_cliente = cc.cod_cliente and cl.cod_empresa = cc.cod_emp_mult
    left join colaborador col on col.cod_vendedor = cc.op_cxl and col.cod_empresa = cc.cod_emp_mult
    where cc.dia_cxl >= :pdataIni
    and cc.dia_cxl <= :pdataFim
    and cc.cod_emp_mult = :pCodEmpresa
    union
    select 5 ordem, 'A Vista' modalidade, 'PRE' tipo, cl.nome_cliente,
    case when (:pagruparoperadores = 'S') then null else bc.op_cxl end op_cxl,
    case when (:pagruparoperadores = 'S') then null else col.nome_vendedor end nome_op_cxl,
    bc.dia_cxl as data_fech, bc.lote_cxl,
    coalesce(bc.vl_rq_pg_cxl, 0) valor_total,
    coalesce((select sum(coalesce(bc1.vl_rq_pg_cxl,0)) from baixa_creditos bc1
              where bc1.lote_cxl = bc.lote_cxl
              and bc1.codigo_emp = bc.cod_emp_mult), 0) valor_lote,
    (select count(*) from baixa_creditos bc1
      where bc1.lote_cxl = bc.lote_cxl
      and bc1.codigo_emp = bc.cod_emp_mult) qtde_lote,
    bc.seq_bxcred,
    :pAgruparOperadores agrupar_operadores,
    emp.financeiro_unificado,
    bc.cod_emp_mult as cod_empresa,
    bc.cod_emp_mult,
    emp2.cod_empresa as codempresa_temp,
    emp2.identificacao_emp as identificacao_emp_temp,
    'N' as exibir_emp,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = bc.lote_cxl and fp.tpdocs = 'PRE' and fp.cod_empresa = bc.cod_emp_mult
              and ctr.docs = 'N'
              and coalesce(fp.recibo, '') <> 'S'
              and coalesce(ctr.nao_gera_finan, '') <> 'S'), 0) valordinheiro,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = bc.lote_cxl and fp.tpdocs = 'PRE' and fp.cod_empresa = bc.cod_emp_mult), 0) valorrecebimento,
    cast(:pdataIni as timestamp) data_ini, cast(:pdataFim  as timestamp) data_fim from baixa_creditos bc
    inner join empresa emp on emp.cod_empresa = bc.codigo_emp
    left join empresa emp2 on emp2.cod_empresa = bc.cod_emp_mult
    inner join clientes cl on cl.cod_cliente = bc.cod_cliente and cl.cod_empresa = bc.cod_emp_mult
    left join colaborador col on col.cod_vendedor = bc.op_cxl and col.cod_empresa = bc.cod_emp_mult
    where bc.dia_cxl >= :pdataIni
    and bc.dia_cxl <= :pdataFim
    and bc.cod_emp_mult = :pCodEmpresa
    and bc.tip_baixa = 'P'
    and (select count(fp.cod_controle) from formpagamento fp
         inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
         where fp.nrequisicao = bc.lote_cxl and fp.tpdocs = 'PRE' and fp.cod_empresa = bc.cod_emp_mult
         and ctr.docs = 'N'
         and coalesce(fp.recibo, '') <> 'S'
         and coalesce(ctr.nao_gera_finan, '') <> 'S') > 0
    union
    select 5 ordem, 'Detalhes' modalidade, 'PRE' tipo, cl.nome_cliente,
    case when (:pagruparoperadores = 'S') then null else bc.op_cxl end op_cxl,
    case when (:pagruparoperadores = 'S') then null else col.nome_vendedor end nome_op_cxl,
    bc.dia_cxl as data_fech, bc.lote_cxl,
    coalesce(bc.vl_rq_pg_cxl, 0) valor_total,
    coalesce((select sum(coalesce(bc1.vl_rq_pg_cxl,0)) from baixa_creditos bc1
              where bc1.lote_cxl = bc.lote_cxl
              and bc1.codigo_emp = bc.cod_emp_mult), 0) valor_lote,
    (select count(*) from baixa_creditos bc1
      where bc1.lote_cxl = bc.lote_cxl
      and bc1.codigo_emp = bc.cod_emp_mult) qtde_lote,
    bc.seq_bxcred,
    :pAgruparOperadores agrupar_operadores,
    emp.financeiro_unificado,
    bc.cod_emp_mult as cod_empresa,
    bc.cod_emp_mult,
    emp2.cod_empresa as codempresa_temp,
    emp2.identificacao_emp as identificacao_emp_temp,
    'N' as exibir_emp,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = bc.lote_cxl and fp.tpdocs = 'PRE' and fp.cod_empresa = bc.cod_emp_mult
              and ctr.docs = 'N'
              and coalesce(fp.recibo, '') <> 'S'
              and coalesce(ctr.nao_gera_finan, '') <> 'S'), 0) valordinheiro,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = bc.lote_cxl and fp.tpdocs = 'PRE' and fp.cod_empresa = bc.cod_emp_mult), 0) valorrecebimento,
    cast(:pdataIni as timestamp) data_ini, cast(:pdataFim  as timestamp) data_fim from baixa_creditos bc
    inner join empresa emp on emp.cod_empresa = bc.codigo_emp
    left join empresa emp2 on emp2.cod_empresa = bc.cod_emp_mult
    inner join clientes cl on cl.cod_cliente = bc.cod_cliente and cl.cod_empresa = bc.cod_emp_mult
    left join colaborador col on col.cod_vendedor = bc.op_cxl and col.cod_empresa = bc.cod_emp_mult
    where bc.dia_cxl >= :pdataIni
    and bc.dia_cxl <= :pdataFim
    and bc.cod_emp_mult = :pCodEmpresa
    and bc.tip_baixa = 'P'
    union
    select 6 ordem, 'A Vista' modalidade, 'LCS' tipo, lanc.historico_cxl,
    case when (:pagruparoperadores = 'S') then null else lanc.op_cxl end op_cxl,
    case when (:pagruparoperadores = 'S') then null else col.nome_vendedor end nome_op_cxl,
    lanc.data_lc_cxl as data_fech, lanc.cod_lancxl,
    case when (lanc.tipo_lanc_cxl = 'S') then coalesce(lanc.valor_cxl * - 1, 0) else coalesce(lanc.valor_cxl, 0) end valor_total,
    case when (lanc.tipo_lanc_cxl = 'S') then coalesce(lanc.valor_cxl * - 1, 0) else coalesce(lanc.valor_cxl, 0) end valor_lote,
    1 qtde_lote,
    null cod_cred,
    :pAgruparOperadores agrupar_operadores,
    emp.financeiro_unificado,
    lanc.codigo_emp as cod_empresa,
    lanc.codigo_emp,
    emp2.cod_empresa as codempresa_temp,
    emp2.identificacao_emp as identificacao_emp_temp,
    'N' as exibir_emp,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = lanc.cod_lancxl and fp.tpdocs = 'LCS' and fp.cod_empresa = lanc.codigo_emp
              and ctr.docs = 'N'
              and coalesce(fp.recibo, '') <> 'S'
              and coalesce(ctr.nao_gera_finan, '') <> 'S'), 0) valordinheiro,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = lanc.cod_lancxl and fp.tpdocs = 'LCS' and fp.cod_empresa = lanc.codigo_emp), 0) valorrecebimento,
    cast(:pdataIni as timestamp) data_ini, cast(:pdataFim  as timestamp) data_fim from lanccxl lanc
    inner join empresa emp on emp.cod_empresa = lanc.codigo_emp
    left join empresa emp2 on emp2.cod_empresa = lanc.codigo_emp
    left join colaborador col on col.cod_vendedor = lanc.op_cxl and col.cod_empresa = lanc.codigo_emp
    where lanc.data_lc_cxl >= :pdataIni
    and lanc.data_lc_cxl <= :pdataFim
    and lanc.codigo_emp = :pCodEmpresa
    and lanc.tipo_doc_cxl is null
    and lanc.refrecibo is null
    and (select count(*) from formpagamento fp
         inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
         where fp.nrequisicao = lanc.cod_lancxl and fp.tpdocs = 'LCS' and fp.cod_empresa = lanc.codigo_emp
         and ctr.docs = 'N'
         and coalesce(fp.recibo, '') <> 'S'
         and coalesce(ctr.nao_gera_finan, '') <> 'S') > 0
    union
    select 6 ordem, 'Detalhes' modalidade, 'LCS' tipo, lanc.historico_cxl,
    case when (:pagruparoperadores = 'S') then null else lanc.op_cxl end op_cxl,
    case when (:pagruparoperadores = 'S') then null else col.nome_vendedor end nome_op_cxl,
    lanc.data_lc_cxl as data_fech, lanc.cod_lancxl,
    case when (lanc.tipo_lanc_cxl = 'S') then coalesce(lanc.valor_cxl * - 1, 0) else coalesce(lanc.valor_cxl, 0) end valor_total,
    case when (lanc.tipo_lanc_cxl = 'S') then coalesce(lanc.valor_cxl * - 1, 0) else coalesce(lanc.valor_cxl, 0) end valor_lote,
    1 qtde_lote,
    null cod_cred,
    :pAgruparOperadores agrupar_operadores,
    emp.financeiro_unificado,
    lanc.codigo_emp as cod_empresa,
    lanc.codigo_emp,
    emp2.cod_empresa as codempresa_temp,
    emp2.identificacao_emp as identificacao_emp_temp,
    'N' as exibir_emp,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = lanc.cod_lancxl and fp.tpdocs = 'LCS' and fp.cod_empresa = lanc.codigo_emp
              and ctr.docs = 'N'
              and coalesce(fp.recibo, '') <> 'S'
              and coalesce(ctr.nao_gera_finan, '') <> 'S'), 0) valordinheiro,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = lanc.cod_lancxl and fp.tpdocs = 'LCS' and fp.cod_empresa = lanc.codigo_emp), 0) valorrecebimento,
    cast(:pdataIni as timestamp) data_ini, cast(:pdataFim  as timestamp) data_fim from lanccxl lanc
    inner join empresa emp on emp.cod_empresa = lanc.codigo_emp
    left join empresa emp2 on emp2.cod_empresa = lanc.codigo_emp
    left join colaborador col on col.cod_vendedor = lanc.op_cxl and col.cod_empresa = lanc.codigo_emp
    where lanc.data_lc_cxl >= :pdataIni
    and lanc.data_lc_cxl <= :pdataFim
    and lanc.codigo_emp = :pCodEmpresa
    and lanc.tipo_doc_cxl is null
    and lanc.refrecibo is null
    order by 1, 2 desc, 4, 5
      into :ordem, :modalidade, :tipo, :nome_cliente, :op_cxl, :nome_op_cxl, :data_fech, :nped, :valor_total, :valor_lote, :qtde_lote, :cod_cred,
        :agrupar_operadores, :financeiro_unificado, :cod_empresa, :cod_emp_mult, :codempresa_temp, :identificacao_emp_temp,
        :exibir_emp, :valordinheiro, :valorrecebimento, :data_ini, :data_fim do
  begin
    suspend;
  end
end ^

ALTER PROCEDURE SAIDAS_RECEB_MERCADORIA_FINANC (PDATAINI TIMESTAMP,
PDATAFIM TIMESTAMP,
PCODEMPRESA INTEGER,
PCODEMPUNIFICADA INTEGER,
PAGRUPARUNIFICADAS CHAR(1) CHARACTER SET NONE)
RETURNS (ORDEM INTEGER,
ORDEM2 INTEGER,
TP_REL VARCHAR(20) CHARACTER SET NONE,
MODALIDADE VARCHAR(30) CHARACTER SET NONE,
TIPO CHAR(10) CHARACTER SET NONE,
NOME_CLIENTE VARCHAR(35) CHARACTER SET NONE,
OP_CXL INTEGER,
NOME_OP_CXL VARCHAR(35) CHARACTER SET NONE,
DATA_FECH TIMESTAMP,
NPED INTEGER,
SEQ_BXCREDCH INTEGER,
TIP_BAIXA CHAR(1) CHARACTER SET NONE,
VALOR_TOTAL DOUBLE PRECISION,
VALOR_LOTE DOUBLE PRECISION,
QTDE_LOTE INTEGER,
AGRUPAR_OPERADORES CHAR(1) CHARACTER SET NONE,
FINANCEIRO_UNIFICADO CHAR(1) CHARACTER SET NONE,
COD_EMPRESA INTEGER,
COD_EMP_MULT INTEGER,
CODEMPRESA_TEMP INTEGER,
IDENTIFICACAO_EMP_TEMP VARCHAR(64) CHARACTER SET NONE,
EXIBIR_EMP CHAR(1) CHARACTER SET NONE,
VALORRECEBIMENTO DOUBLE PRECISION,
VALORDINHEIRO DOUBLE PRECISION,
DATA_INI TIMESTAMP,
DATA_FIM TIMESTAMP)
AS 
begin
  /* Procedure Text */
  for select 1 ordem, case when (pv.tipo = 'REQ') then 2 else 3 end ordem2,
    'SAIDAS/VENDA' tp_rel,
    'A Vista' modalidade, pv.tipo, cl.nome_cliente,
    pv.op_cxl,
    col.nome_vendedor as nome_op_cxl,
    pv.data_fech, pv.nped, null, null,
    coalesce(pv.valor_total, 0) valor_total,
    coalesce(pv.valor_total, 0) valor_lote,
    1 qtde_lote,
    'S' agrupar_operadores,
    emp.financeiro_unificado,
    case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pv.cod_empresa end cod_empresa,
    pv.cod_empresa as cod_emp_mult,
    emp2.cod_empresa as codempresa_temp,
    emp2.identificacao_emp as identificacao_emp_temp,
    case when (:pCodEmpUnificada > 0) then 'N'
         when (:pAgruparUnificadas = 'S') then 'N'
         else 'S' end exibir_emp,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = pv.nped and fp.tpdocs = pv.tipo and fp.cod_empresa = pv.cod_empresa), 0) valorrecebimento,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = pv.nped and fp.tpdocs = pv.tipo and fp.cod_empresa = pv.cod_empresa
              and ctr.docs = 'N'
              and coalesce(fp.recibo, '') <> 'S'
              and coalesce(ctr.nao_gera_finan, '') <> 'S'), 0) valordinheiro,
    cast(:pdataIni as timestamp) data_ini, cast(:pdataFim  as timestamp) data_fim
    from pedvenda pv
    inner join empresa emp on emp.cod_empresa = pv.cod_empresa
    left join empresa emp2 on emp2.cod_empresa =
        (case when (:pCodEmpUnificada > 0) then :pCodEmpUnificada
              when (:pAgruparUnificadas = 'S') then emp.codigo_unificadora
              else pv.cod_empresa end)
    inner join clientes cl on cl.cod_cliente = pv.cod_cliente and cl.cod_empresa = pv.cod_empresa
    left join colaborador col on col.cod_vendedor = pv.op_cxl and col.cod_empresa = pv.cod_empresa
    where pv.data_fech >= :pdataIni
    and pv.data_fech <= :pdataFim
    and (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pv.cod_empresa end) = :pCodEmpresa
    and pv.tipo <> 'ORC'
    and pv.status_ped = 'FECHADA'
    and (select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
         inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
         where fp.nrequisicao = pv.nped and fp.tpdocs = pv.tipo and fp.cod_empresa = pv.cod_empresa
         and ctr.docs = 'N'
         and coalesce(fp.recibo, '') <> 'S'
         and coalesce(ctr.nao_gera_finan, '') <> 'S') > 0
    union
    select 1 ordem, case when (pv.tipo = 'REQ') then 2 else 3 end ordem2,
    'SAIDAS/VENDA' tp_rel,
    'Detalhes' modalidade, pv.tipo, cl.nome_cliente,
    pv.op_cxl,
    col.nome_vendedor as nome_op_cxl,
    pv.data_fech, pv.nped, null, null,
    coalesce(pv.valor_total, 0) valor_total,
    coalesce(pv.valor_total, 0) valor_lote,
    1 qtde_lote,
    'S' agrupar_operadores,
    emp.financeiro_unificado,
    case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pv.cod_empresa end cod_empresa,
    pv.cod_empresa as cod_emp_mult,
    emp2.cod_empresa as codempresa_temp,
    emp2.identificacao_emp as identificacao_emp_temp,
    case when (:pCodEmpUnificada > 0) then 'N'
         when (:pAgruparUnificadas = 'S') then 'N'
         else 'S' end exibir_emp,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = pv.nped and fp.tpdocs = pv.tipo and fp.cod_empresa = pv.cod_empresa), 0) valorrecebimento,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = pv.nped and fp.tpdocs = pv.tipo and fp.cod_empresa = pv.cod_empresa
              and ctr.docs = 'N'
              and coalesce(fp.recibo, '') <> 'S'
              and coalesce(ctr.nao_gera_finan, '') <> 'S'), 0) valordinheiro,
    cast(:pdataIni  as timestamp) data_ini, cast(:pdataFim  as timestamp) data_fim
    from pedvenda pv
    inner join empresa emp on emp.cod_empresa = pv.cod_empresa
    left join empresa emp2 on emp2.cod_empresa =
        (case when (:pCodEmpUnificada > 0) then :pCodEmpUnificada
              when (:pAgruparUnificadas = 'S') then emp.codigo_unificadora
              else pv.cod_empresa end)
    inner join clientes cl on cl.cod_cliente = pv.cod_cliente and cl.cod_empresa = pv.cod_empresa
    left join colaborador col on col.cod_vendedor = pv.op_cxl and col.cod_empresa = pv.cod_empresa
    where pv.data_fech >= :pdataIni
    and pv.data_fech <= :pdataFim
    and (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else pv.cod_empresa end) = :pCodEmpresa
    and pv.tipo <> 'ORC'
    and pv.status_ped = 'FECHADA'
    and (select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
         inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
         where fp.nrequisicao = pv.nped and fp.tpdocs = pv.tipo and fp.cod_empresa = pv.cod_empresa) > 0
    union
    select 2 ordem, 4 ordem2, 'RECIBO ANTECIPADO' tp_rel,
    'A Vista' modalidade, 'REC' tipo, cl.nome_cliente,
    rec.op_cxl,
    col.nome_vendedor as nome_op_cxl,
    rec.data_rec as data_fech, rec.nrecibo, null, null,
    coalesce(rec.valor_orig, 0) valor_total,
    coalesce(rec.valor_orig, 0) valor_lote,
    1 qtde_lote,
    'S' agrupar_operadores,
    emp.financeiro_unificado,
    case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else rec.cod_empresa end cod_empresa,
    rec.cod_empresa as cod_emp_mult,
    emp2.cod_empresa as codempresa_temp,
    emp2.identificacao_emp as identificacao_emp_temp,
    case when (:pCodEmpUnificada > 0) then 'N'
         when (:pAgruparUnificadas = 'S') then 'N'
         else 'S' end exibir_emp,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = rec.nrecibo and fp.tpdocs = 'REC' and fp.cod_empresa = rec.cod_empresa), 0) valorrecebimento,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = rec.nrecibo and fp.tpdocs = 'REC' and fp.cod_empresa = rec.cod_empresa
              and ctr.docs = 'N'
              and coalesce(fp.recibo, '') <> 'S'
              and coalesce(ctr.nao_gera_finan, '') <> 'S'), 0) valordinheiro,
    cast(:pdataIni as timestamp) data_ini, cast(:pdataFim  as timestamp) data_fim from recibos rec
    inner join empresa emp on emp.cod_empresa = rec.cod_empresa
    left join empresa emp2 on emp2.cod_empresa =
        (case when (:pCodEmpUnificada > 0) then :pCodEmpUnificada
              when (:pAgruparUnificadas = 'S') then emp.codigo_unificadora
              else rec.cod_empresa end)
    inner join clientes cl on cl.cod_cliente = rec.cod_devedor and cl.cod_empresa = rec.cod_empresa
    left join colaborador col on col.cod_vendedor = rec.op_cxl and col.cod_empresa = rec.cod_empresa
    where rec.data_rec >= :pdataIni
    and rec.data_rec <= :pdataFim
    and (case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else rec.cod_empresa end) = :pCodEmpresa
    and (select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
         inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
         where fp.nrequisicao = rec.nrecibo and fp.tpdocs = 'REC' and fp.cod_empresa = rec.cod_empresa
         and ctr.docs = 'N'
         and coalesce(fp.recibo, '') <> 'S'
         and coalesce(ctr.nao_gera_finan, '') <> 'S') > 0
    union
    select 2 ordem, 4 ordem2, 'RECIBO ANTECIPADO' tp_rel,
    'Detalhes' modalidade, 'REC' tipo, cl.nome_cliente,
    rec.op_cxl,
    col.nome_vendedor as nome_op_cxl,
    rec.data_rec as data_fech, rec.nrecibo, null, null,
    coalesce(rec.valor_orig, 0) valor_total,
    coalesce(rec.valor_orig, 0) valor_lote,
    1 qtde_lote,
    'S' agrupar_operadores,
    emp.financeiro_unificado,
    case when(emp.financeiro_unificado = 'S') then emp.codigo_unificadora else rec.cod_empresa end cod_empresa,
    rec.cod_empresa as cod_emp_mult,
    emp2.cod_empresa as codempresa_temp,
    emp2.identificacao_emp as identificacao_emp_temp,
    case when (:pCodEmpUnificada > 0) then 'N'
         when (:pAgruparUnificadas = 'S') then 'N'
         else 'S' end exibir_emp,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = rec.nrecibo and fp.tpdocs = 'REC' and fp.cod_empresa = rec.cod_empresa), 0) valorrecebimento,
    coalesce((select sum(coalesce(fp.valordoc, 0)) from formpagamento fp
              inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
              where fp.nrequisicao = rec.nrecibo and fp.tpdocs = 'REC' and fp.cod_empresa = rec.cod_empresa
              and ctr.docs = 'N'
              and coalesce(fp.recibo, '') <> 'S'
              and coalesce(ctr.nao_gera_finan, '') <> 'S'), 0) valordinheiro,
    cast(:pdataIni as timestamp) data_ini, cast(:pdataFim  as timestamp) data_fim from recibos rec
    inner join empresa emp on emp.cod_empresa = rec.cod_empresa
    left join empresa emp2 on emp2.cod_empresa =
        (case when (:pCodEmpUnificada > 0) then :pCodEmpUnificada
              when (:pAgruparUnificadas = 'S') then emp.codigo_unificadora
              else rec.cod_empresa end)
    inner join clientes cl on cl.cod_cliente = rec.cod_devedor and cl.cod_empresa = rec.cod_empresa
    left join colaborador col on col.cod_vendedor = rec.op_cxl and col.cod_empresa = rec.cod_empresa
    where rec.data_rec >= :pdataIni
