ALTER PROCEDURE SONUMEROS (TEXTO VARCHAR(100) CHARACTER SET NONE)
RETURNS (RESULT VARCHAR(100) CHARACTER SET NONE)
AS 
declare variable INDICE integer;
declare variable CARACTER char(1);
begin
 if (texto is null) then
   result = null;
 else
 begin
   result = texto;
   indice = char_length(result);
   while (indice > 0) do
   begin
     caracter = cast(substring(result from indice for 1) as char(1));
     if (not(caracter between '0' and '9')) then
       result = substring(result from 1 for (indice - 1)) ||
                   substring(result from (indice + 1) for
                    (char_length(result) - indice));
      indice = indice - 1;
   end
 end
 suspend;
end ^

ALTER PROCEDURE SPDB_CHECK_PRIVILEGES (USERNAME VARCHAR(31) CHARACTER SET NONE,
OBJECT_NAME VARCHAR(31) CHARACTER SET NONE)
AS 
  declare variable OBTYPE smallint;
  declare variable OBNAME varchar(31);
  declare variable DEPNAME varchar(31);
  declare variable COUNTPRIV integer;
  declare variable COUNTTEST integer;
  declare variable COUNTINSERT integer;
  declare variable MAXINSERT integer;
begin
  OBJECT_NAME = upper(trim(OBJECT_NAME));
  for select OBTYPE, NAME
      from (select 0 OBTYPE, R.RDB$RELATION_NAME NAME, null RELATION
            from RDB$RELATIONS R
            where ((R.RDB$SYSTEM_FLAG = 0) or (R.RDB$SYSTEM_FLAG is null)) and
                  (R.RDB$VIEW_SOURCE is null) and
                  (R.RDB$RELATION_NAME = :OBJECT_NAME)
            union
            select 1 OBTYPE, R.RDB$RELATION_NAME NAME, null RELATION
            from RDB$RELATIONS R
            where ((R.RDB$SYSTEM_FLAG = 0) or (R.RDB$SYSTEM_FLAG is null)) and
                  (R.RDB$VIEW_SOURCE is not null) and
                  (R.RDB$RELATION_NAME = :OBJECT_NAME)
            union
            select 2 OBTYPE, SP.RDB$PROCEDURE_NAME NAME, null RELATION
            from RDB$PROCEDURES SP
            where (SP.RDB$PROCEDURE_NAME = :OBJECT_NAME))
        into :OBTYPE, :OBNAME
  do
  begin
    if (OBTYPE = 2) then
      COUNTTEST = 1;
    else
      COUNTTEST = 5;
    select count(RP.RDB$PRIVILEGE)
    from RDB$USER_PRIVILEGES RP
    where RP.RDB$USER = :USERNAME and
          trim(RP.RDB$RELATION_NAME) = :OBNAME
      into :COUNTPRIV;

    if (COUNTTEST > coalesce(COUNTPRIV, 0)) then
      if (OBTYPE = 2) then
        execute statement 'GRANT EXECUTE ON PROCEDURE ' || OBNAME || ' TO ' || USERNAME;
      else
        execute statement 'GRANT ALL ON ' || OBNAME || ' TO ' || USERNAME;

    select count(TABELA), max(ORDEM)
    from RI_DEP
    where TABELA = :OBNAME
      into :COUNTINSERT, :MAXINSERT;

    if (coalesce(COUNTINSERT, 0) = 0) then
    begin
      insert into RI_DEP (ORDEM, TABELA)
      values (coalesce(:MAXINSERT, 0) + 1, :OBNAME);

      for select distinct DP.RDB$DEPENDED_ON_NAME
          from RDB$TRIGGERS T
            inner join RDB$DEPENDENCIES DP on DP.RDB$DEPENDENT_NAME = T.RDB$TRIGGER_NAME and
                  not DP.RDB$DEPENDED_ON_NAME starts with 'RDB$' and
                  DP.RDB$FIELD_NAME is null and
                  DP.RDB$DEPENDED_ON_TYPE in (0, 1, 5)
          where T.RDB$SYSTEM_FLAG = 0 and
                (T.RDB$RELATION_NAME = :OBNAME)
          union
          distinct select distinct DP.RDB$DEPENDED_ON_NAME
                   from RDB$DEPENDENCIES DP
                   where DP.RDB$DEPENDENT_NAME = :OBNAME and
                         DP.RDB$FIELD_NAME is null and
                         DP.RDB$DEPENDED_ON_TYPE in (0, 1, 5)
                     into :DEPNAME
      do
        execute procedure SPDB_CHECK_PRIVILEGES(:USERNAME, :DEPNAME);

    end
  end

end ^

ALTER PROCEDURE SPDB_COUNT_PK (TABELA VARCHAR(31) CHARACTER SET NONE)
RETURNS (COUNTPK SMALLINT)
AS 
begin
  COUNTPK = 0;
  select count(SG.RDB$FIELD_NAME) as FIELD_NAME
--  from RDB$INDICES IX
--    inner join RDB$INDEX_SEGMENTS SG on IX.RDB$INDEX_NAME = SG.RDB$INDEX_NAME
--    inner join RDB$RELATION_CONSTRAINTS RC on RC.RDB$INDEX_NAME = IX.RDB$INDEX_NAME
  from RDB$RELATION_CONSTRAINTS RC
    inner join RDB$INDICES IX on RC.RDB$INDEX_NAME = IX.RDB$INDEX_NAME
    inner join RDB$INDEX_SEGMENTS SG on IX.RDB$INDEX_NAME = SG.RDB$INDEX_NAME
  where RC.RDB$CONSTRAINT_TYPE = 'PRIMARY KEY' and
        RC.RDB$RELATION_NAME = :TABELA
    into :COUNTPK;
  suspend;
end ^

ALTER PROCEDURE SPDB_DEPEND (ATABELA VARCHAR(31) CHARACTER SET NONE,
EUDEPENDO SMALLINT,
DEPENDEMDEMIM SMALLINT)
RETURNS (TABELA VARCHAR(31) CHARACTER SET NONE,
IDEPEND SMALLINT,
DEPENDSONME SMALLINT)
AS 
begin
  IDEPEND = 0;
  DEPENDSONME = 0;
  if (EUDEPENDO = 1) then
  begin
    IDEPEND = EUDEPENDO;
    for select distinct RF.RDB$RELATION_NAME TAB_REF
        from RDB$INDICES IX
          left join RDB$INDEX_SEGMENTS SG on IX.RDB$INDEX_NAME = SG.RDB$INDEX_NAME
          left join RDB$RELATION_CONSTRAINTS RC on RC.RDB$INDEX_NAME = IX.RDB$INDEX_NAME
          left join RDB$RELATION_CONSTRAINTS RF on RF.RDB$INDEX_NAME = IX.RDB$FOREIGN_KEY
        where RC.RDB$CONSTRAINT_TYPE = 'FOREIGN KEY' and
              RC.RDB$RELATION_NAME = :ATABELA
          into :TABELA
    do
    begin
      suspend;
    end
  end
  IDEPEND = 0;
  DEPENDSONME = 0;
  if (DEPENDEMDEMIM = 1) then
  begin
    DEPENDSONME = DEPENDEMDEMIM;
    for select distinct trim(IDX.RDB$RELATION_NAME)
        from RDB$RELATION_CONSTRAINTS RELOR
          inner join RDB$REF_CONSTRAINTS REL on REL.RDB$CONST_NAME_UQ = RELOR.RDB$CONSTRAINT_NAME
          inner join RDB$INDICES IDX on IDX.RDB$INDEX_NAME = REL.RDB$CONSTRAINT_NAME
        where RELOR.RDB$CONSTRAINT_TYPE = 'PRIMARY KEY' and
              RELOR.RDB$RELATION_NAME = :ATABELA
          into :TABELA
    do
    begin
      suspend;
    end
  end
end ^

ALTER PROCEDURE SPDB_DEPENDENCIES (ATABELA VARCHAR(31) CHARACTER SET NONE,
DEPENDENCIATIPO CHAR(1) CHARACTER SET NONE,
RESETDEPENDS SMALLINT = 0)
RETURNS (ORDEM SMALLINT,
TABELA VARCHAR(31) CHARACTER SET NONE)
AS 
  declare variable RESULT integer;
begin
  if (RESETDEPENDS = 1) then
    delete from RI_DEP
    where TABELA <> '';

  for select RESULT
      from SPDB_MAKE_DEP(:ATABELA, :DEPENDENCIATIPO)
        into :RESULT
  do
  begin
    if (:RESULT = 1) then
      for select ORDEM, TABELA
          from RI_DEP
            into :ORDEM, :TABELA
      do
        if (ATABELA <> TABELA) then
          suspend;
  end
end ^

ALTER PROCEDURE SPDB_DEPENDENCIES_RI (DEPENDENCIATIPO CHAR(1) CHARACTER SET NONE,
RESETDEPENDS SMALLINT = 1)
AS 
  declare variable RESULT smallint;
begin
  if (RESETDEPENDS = 1) then
    delete from RI_DEP
    where TABELA <> '';

  select count(N.TABELA)
  from RI_REPLICATE_ACTIONS N
    left join SPDB_TABLES T on T.TABELA = N.TABELA
    left join SPDB_MAKE_DEP(N.TABELA, :DEPENDENCIATIPO) SP on 1 = 1
  where N.TABELA = T.TABELA
    into :RESULT;
end ^

ALTER PROCEDURE SPDB_EMP_KEY (TABELA VARCHAR(31) CHARACTER SET NONE)
RETURNS (CAMPO_EMP VARCHAR(31) CHARACTER SET NONE)
AS 
begin
  select first 1 TRIM(SG.RDB$FIELD_NAME) as FIELD_NAME
  from RDB$RELATION_CONSTRAINTS RC
    inner join RDB$INDICES IX on RC.RDB$INDEX_NAME = IX.RDB$INDEX_NAME
    inner join RDB$INDEX_SEGMENTS SG on IX.RDB$INDEX_NAME = SG.RDB$INDEX_NAME
    where RC.RDB$CONSTRAINT_TYPE = 'PRIMARY KEY' and
          SG.RDB$FIELD_NAME like '%COD%EMP%' and
          RC.RDB$RELATION_NAME = trim(upper(:TABELA))
    order by SG.RDB$FIELD_POSITION
      into :CAMPO_EMP;
  CAMPO_EMP = trim(coalesce(CAMPO_EMP, ''));
  suspend;
end
 
 ^

ALTER PROCEDURE SPDB_FIELDS (TABELA VARCHAR(31) CHARACTER SET NONE)
RETURNS (FIELDNAME VARCHAR(31) CHARACTER SET NONE,
FTYPE SMALLINT,
FSUBTYPE SMALLINT,
FIELDTYPE VARCHAR(32) CHARACTER SET NONE,
FIELDTYPE2 VARCHAR(32) CHARACTER SET NONE)
AS 
begin
  for select trim(RF.RDB$FIELD_NAME), F.RDB$FIELD_TYPE, F.RDB$FIELD_SUB_TYPE,
             case F.RDB$FIELD_TYPE
               when 7 then case F.RDB$FIELD_SUB_TYPE
                             when 0 then 'SMALLINT'
                             when 1 then 'NUMERIC'
                             when 2 then 'DECIMAL'
                           end
               when 8 then case F.RDB$FIELD_SUB_TYPE
                             when 0 then 'INTEGER'
                             when 1 then 'NUMERIC'
                             when 2 then 'DECIMAL'
                           end
               when 10 then 'FLOAT'
               when 12 then 'DATE'
               when 13 then 'TIME'
               when 14 then 'CHAR'
               when 16 then case F.RDB$FIELD_SUB_TYPE
                              when 0 then 'BIGINT'
                              when 1 then 'NUMERIC'
                              when 2 then 'DECIMAL'
                            end
               when 27 then 'DOUBLE'
               when 35 then 'TIMESTAMP'
               when 37 then 'VARCHAR'
               when 261 then 'BLOB ' || F.RDB$FIELD_SUB_TYPE
               else F.RDB$FIELD_TYPE || '?'
             end FIELD_TYPE,
             case F.RDB$FIELD_TYPE
               when 7 then case F.RDB$FIELD_SUB_TYPE
                             when 0 then 'INT'
                             when 1 then 'DOUBLE'
                             when 2 then 'DOUBLE'
                           end
               when 8 then case F.RDB$FIELD_SUB_TYPE
                             when 0 then 'INT'
                             when 1 then 'DOUBLE'
                             when 2 then 'DOUBLE'
                           end
               when 10 then 'DOUBLE'
               when 12 then 'DATETIME'
               when 13 then 'DATETIME'
               when 14 then 'STRING'
               when 16 then case F.RDB$FIELD_SUB_TYPE
                              when 0 then 'INT'
                              when 1 then 'DOUBLE'
                              when 2 then 'DOUBLE'
                            end
               when 27 then 'DOUBLE'
               when 35 then 'DATETIME'
               when 37 then 'STRING'
               when 261 then 'BLOB ' || F.RDB$FIELD_SUB_TYPE
               else F.RDB$FIELD_TYPE || '?'
             end FIELD_TYPE2
      from RDB$RELATION_FIELDS RF
        join RDB$FIELDS F on (F.RDB$FIELD_NAME = RF.RDB$FIELD_SOURCE)
      where (RF.RDB$RELATION_NAME = :TABELA) and
            (coalesce(RF.RDB$SYSTEM_FLAG, 0) = 0) and
            (F.RDB$COMPUTED_SOURCE is null)
      order by RF.RDB$FIELD_POSITION
        into :FIELDNAME, :FTYPE, :FSUBTYPE, :FIELDTYPE, :FIELDTYPE2
  do
    suspend;
end ^

ALTER PROCEDURE SPDB_FIELDS_ALL (TABELA VARCHAR(31) CHARACTER SET NONE)
RETURNS (NAME VARCHAR(31) CHARACTER SET NONE,
NTYPE SMALLINT,
SUBTYPE SMALLINT,
FTYPE VARCHAR(32) CHARACTER SET NONE,
FSIZE INTEGER,
ISPK SMALLINT,
ISFK SMALLINT,
FPOSITION INTEGER)
AS 
begin
  TABELA = upper(trim(TABELA));
  for select distinct T.FIELDNAME, T.FTYPE, T.SUBTYPE, T.FIELDTYPE, T.FIELDSIZE, T.FIELPOSITION,
                      iif(T.FIELDNAME = PK.FIELDNAME, 1, 0) ISPK, iif(T.FIELDNAME = FK.FIELDNAME, 1, 0) ISFK
      from (select trim(RF.RDB$FIELD_NAME) FIELDNAME, trim(F.RDB$FIELD_TYPE) FTYPE, F.RDB$FIELD_SUB_TYPE SUBTYPE,
                   case F.RDB$FIELD_TYPE
                     when 7 then case F.RDB$FIELD_SUB_TYPE
                                   when 0 then 'SMALLINT'
                                   when 1 then 'NUMERIC'
                                   when 2 then 'DECIMAL'
                                 end
                     when 8 then case F.RDB$FIELD_SUB_TYPE
                                   when 0 then 'INTEGER'
                                   when 1 then 'NUMERIC'
                                   when 2 then 'DECIMAL'
                                 end
                     when 10 then 'FLOAT'
                     when 12 then 'DATE'
                     when 13 then 'TIME'
                     when 14 then 'VARCHAR'
                     when 16 then case F.RDB$FIELD_SUB_TYPE
                                    when 0 then 'BIGINT'
                                    when 1 then 'NUMERIC'
                                    when 2 then 'DECIMAL'
                                  end
                     when 27 then 'DOUBLE'
                     when 35 then 'TIMESTAMP'
                     when 37 then 'VARCHAR'
                     when 261 then 'BLOB ' || F.RDB$FIELD_SUB_TYPE
                     else F.RDB$FIELD_TYPE || '?'
                   end FIELDTYPE,
                   trunc(F.RDB$FIELD_LENGTH / CH.RDB$BYTES_PER_CHARACTER) FIELDSIZE,
                   RF.RDB$FIELD_POSITION FIELPOSITION
            from RDB$RELATION_FIELDS RF
              join RDB$FIELDS F on (F.RDB$FIELD_NAME = RF.RDB$FIELD_SOURCE)
              left outer join RDB$CHARACTER_SETS CH on (CH.RDB$CHARACTER_SET_ID = F.RDB$CHARACTER_SET_ID)
            where (RF.RDB$RELATION_NAME = :TABELA) and
                  (coalesce(RF.RDB$SYSTEM_FLAG, 0) = 0) and
                  (F.RDB$COMPUTED_SOURCE is null)
            order by RF.RDB$FIELD_POSITION) as T
        left join SPDB_FIELDS_PK(:TABELA) PK on 1 = 1 and
              PK.FIELDNAME = T.FIELDNAME
        left join SPDB_FIELDS_FK(:TABELA) FK on 1 = 1 and
              FK.FIELDNAME = T.FIELDNAME
      order by T.FIELPOSITION
        into :NAME, :NTYPE, :SUBTYPE, :FTYPE, :FSIZE, :FPOSITION, :ISPK, :ISFK
  do
    suspend;
end ^

ALTER PROCEDURE SPDB_FIELDS_FK (TABELA VARCHAR(31) CHARACTER SET NONE)
RETURNS (TABLE_REF VARCHAR(31) CHARACTER SET NONE,
PK_NAME VARCHAR(31) CHARACTER SET NONE,
FIELDNAME VARCHAR(31) CHARACTER SET NONE,
FK_NAME VARCHAR(31) CHARACTER SET NONE,
TABLE_O VARCHAR(31) CHARACTER SET NONE,
DELETE_CASCATA SMALLINT,
UPDATE_CASCATA SMALLINT,
INDEX_POS INTEGER)
AS 
begin
  for select distinct trim(CONSTRAINTSDESTINO.RDB$RELATION_NAME) as TABLE_REF, trim(RDB$CONST_NAME_UQ) as PK_NAME,
                      trim(INDICES.RDB$FIELD_NAME) as FIELDNAME, trim(CONSTRAINTSORIGEM.RDB$CONSTRAINT_NAME) as FK_NAME,
                      trim(CONSTRAINTSORIGEM.RDB$RELATION_NAME) as TABLE_O,
                      iif(RELACIONAMENTOS.RDB$DELETE_RULE = 'CASCADE', 1, 0) DELETE_CASCATA,
                      iif(RELACIONAMENTOS.RDB$UPDATE_RULE = 'CASCADE', 1, 0) UPDATE_CASCATA,
                      INDICES.RDB$FIELD_POSITION
      from RDB$RELATION_CONSTRAINTS CONSTRAINTSORIGEM, RDB$RELATION_CONSTRAINTS CONSTRAINTSDESTINO, RDB$INDEX_SEGMENTS INDICES, RDB$REF_CONSTRAINTS RELACIONAMENTOS
      where CONSTRAINTSORIGEM.RDB$RELATION_NAME = :TABELA and
            CONSTRAINTSORIGEM.RDB$CONSTRAINT_TYPE = 'FOREIGN KEY' and
            CONSTRAINTSORIGEM.RDB$INDEX_NAME = INDICES.RDB$INDEX_NAME and
            CONSTRAINTSORIGEM.RDB$CONSTRAINT_NAME = RELACIONAMENTOS.RDB$CONSTRAINT_NAME and
            RELACIONAMENTOS.RDB$CONST_NAME_UQ = CONSTRAINTSDESTINO.RDB$CONSTRAINT_NAME
      order by CONSTRAINTSDESTINO.RDB$RELATION_NAME, CONSTRAINTSORIGEM.RDB$CONSTRAINT_NAME, INDICES.RDB$FIELD_POSITION
        into :TABLE_REF, :PK_NAME, :FIELDNAME, :FK_NAME, :TABLE_O, :DELETE_CASCATA, :UPDATE_CASCATA, :INDEX_POS
  do
    suspend;
end ^

ALTER PROCEDURE SPDB_FIELDS_PK (TABELA VARCHAR(31) CHARACTER SET NONE)
RETURNS (INDEX_POS INTEGER,
FIELDNAME VARCHAR(31) CHARACTER SET NONE,
PK_NAME VARCHAR(31) CHARACTER SET NONE)
AS 
begin
  for select SG.RDB$FIELD_POSITION, trim(SG.RDB$FIELD_NAME) , trim(RC.RDB$CONSTRAINT_NAME)
      from RDB$RELATION_CONSTRAINTS RC
        inner join RDB$INDICES IX on RC.RDB$INDEX_NAME = IX.RDB$INDEX_NAME
        inner join RDB$INDEX_SEGMENTS SG on IX.RDB$INDEX_NAME = SG.RDB$INDEX_NAME
      where RC.RDB$CONSTRAINT_TYPE = 'PRIMARY KEY' and
            RC.RDB$RELATION_NAME = :TABELA
      order by SG.RDB$FIELD_POSITION
        into :INDEX_POS, :FIELDNAME, :PK_NAME
  do
    suspend;
end ^

ALTER PROCEDURE SPDB_FIELDS_SCHEMA (TABELA CHAR(31) CHARACTER SET NONE)
RETURNS (FIELDNAME VARCHAR(31) CHARACTER SET NONE,
DBTYPE VARCHAR(6) CHARACTER SET NONE,
DBSUBTYPE SMALLINT,
FIELDTYPE INTEGER,
FIELDSIZE BIGINT,
FIELDPRECISION SMALLINT,
FIELDSCALE SMALLINT,
FIELDPOSITION SMALLINT,
ISPK INTEGER,
ISFK INTEGER,
HASDEFAULT INTEGER,
ISNULLABLE INTEGER,
ISCOMPUTED INTEGER,
FIELDTYPETEXT CHAR(8) CHARACTER SET NONE)
AS 
begin
  TABELA = upper(trim(TABELA));
  for select distinct T.FIELDNAME, T.DBTYPE, T.DBSUBTYPE, T.FIELDTYPE, T.FIELDSIZE,
                      iif(T.FIELDTYPE in (5, 6), T.FIELDPRECISION, null) FIELDPRECISION,
                      iif(T.FIELDTYPE in (5, 6), T.FIELDSCALE, null) FIELDSCALE, T.FIELDPOSITION,
                      iif(T.FIELDNAME = PK.FIELDNAME, 1, 0) ISPK, iif(T.FIELDNAME = FK.FIELDNAME, 1, 0) ISFK,
                      T.HASDEFAULT, T.ISNULLABLE, T.ISCOMPUTED,
                      case T.FIELDTYPE
                        when 1 then 'Boolean'
                        when 2 then 'Smallint'
                        when 3 then 'Integer'
                        when 4 then 'Bigint'
                        when 5 then 'Numeric'
                        when 6 then 'Decimal'
                        when 7 then 'Float'
                        when 8 then 'Double'
                        when 9 then 'Char'
                        when 10 then 'Varchar'
                        when 11 then 'Text'
                        when 12 then 'Datetime'
                        when 13 then 'Date'
                        when 14 then 'Time'
                        when 15 then 'Strings'
                        when 16 then 'Binary'
                        else 'Unknow'
                      end as FIELDTYPETEXT
      from (select trim(RF.RDB$FIELD_NAME) FIELDNAME, trim(F.RDB$FIELD_TYPE) DBTYPE, F.RDB$FIELD_SUB_TYPE DBSUBTYPE,
                   case F.RDB$FIELD_TYPE
                   --TFieldTypeSchemaDB = (fsUnknow = 0, fsBoolean = 1, fsSmallInt = 2, fsInteger = 3, fsBigint = 4, -- fsNumeric = 5, fsDecimal = 6, fsFloat = 7, fsDouble = 8,
                   -- fsChar = 9, fsVarchar = 10, fsText = 11, fsDateTime = 12, fsDate = 13, fsTime = 14, fsStrings = 15, fsBinary = 16);
                     when 7 then case F.RDB$FIELD_SUB_TYPE
                                   when 0 then 2 --'SMALLINT'
                                   when 1 then 5 --'NUMERIC'
                                   when 2 then 6 --'DECIMAL'
                                   else 0
                                 end
                     when 8 then case F.RDB$FIELD_SUB_TYPE
                                   when 0 then 3 --'INTEGER'
                                   when 1 then 5 --'NUMERIC'
                                   when 2 then 6 --'DECIMAL'
                                   else 0
                                 end
                     when 10 then 7 --'FLOAT'
                     when 12 then 13 --'DATE'
                     when 13 then 14 --'TIME'
                     when 14 then 9 --'CHAR'
                     when 16 then case F.RDB$FIELD_SUB_TYPE
                                    when 0 then 4 --'BIGINT'
                                    when 1 then 5 --'NUMERIC'
                                    when 2 then 6 --'DECIMAL'
                                    else 0
                                  end
                     when 27 then 8 --'DOUBLE'
                     when 35 then 12 -- 'TIMESTAMP'
                     when 37 then 10 --'VARCHAR'
                     when 261 then case F.RDB$FIELD_SUB_TYPE
                                     when 0 then 16 --'BLOB BINARY'
                                     when 1 then 15 --'BLOB TEXT'
                                     else 0
                                   end
                     else 0
                   end FIELDTYPE,
                   trunc(F.RDB$FIELD_LENGTH / CH.RDB$BYTES_PER_CHARACTER * iif(F.RDB$FIELD_TYPE in (14, 37), 1, null)) FIELDSIZE, -- 14 char e 37 varchar somente, resto fica null
                   F.RDB$FIELD_PRECISION FIELDPRECISION, F.RDB$FIELD_SCALE FIELDSCALE,
                   RF.RDB$FIELD_POSITION FIELDPOSITION, iif(RF.RDB$DEFAULT_VALUE is null, 0, 1) HASDEFAULT,
                   iif(RF.RDB$NULL_FLAG = 1, 0, 1) ISNULLABLE, iif(F.RDB$COMPUTED_SOURCE is not null, 1, 0) ISCOMPUTED
            from RDB$RELATION_FIELDS RF
              join RDB$FIELDS F on (F.RDB$FIELD_NAME = RF.RDB$FIELD_SOURCE)
              left outer join RDB$CHARACTER_SETS CH on (CH.RDB$CHARACTER_SET_ID = F.RDB$CHARACTER_SET_ID)
            where (RF.RDB$RELATION_NAME = :TABELA) and
                  (coalesce(RF.RDB$SYSTEM_FLAG, 0) = 0)
            order by RF.RDB$FIELD_POSITION) as T
        left join(select FIELDNAME
                  from SPDB_FIELDS_PK(:TABELA)) PK on PK.FIELDNAME = T.FIELDNAME
        left join(select FIELDNAME
                  from SPDB_FIELDS_FK(:TABELA)) FK on FK.FIELDNAME = T.FIELDNAME
      order by T.FIELDPOSITION
        into :FIELDNAME, :DBTYPE, :DBSUBTYPE, :FIELDTYPE, :FIELDSIZE, :FIELDPRECISION, :FIELDSCALE, :FIELDPOSITION,
             :ISPK, :ISFK, :HASDEFAULT, :ISNULLABLE, :ISCOMPUTED, :FIELDTYPETEXT
  do
  begin
    suspend;
  end
end ^

ALTER PROCEDURE SPDB_GUID (TIPO SMALLINT = 0)
RETURNS (GUID CHAR(36) CHARACTER SET NONE)
AS 
begin
  select UUID_TO_CHAR(gen_uuid()) from RDB$DATABASE into GUID;
  suspend;
end ^

ALTER PROCEDURE SPDB_IF_CREATETABLE (SQLTEXT BLOB CHARACTER SET NONE,
TERMINATORSTR VARCHAR(16) CHARACTER SET NONE = '!')
AS 
  declare variable IDXSTART integer;
  declare variable ISIZE integer;
  declare variable TEXT varchar(2000);
  declare variable TABELA varchar(31);
  declare variable SQLPART blob sub_type 1 segment size 80;
begin
  TEXT = upper(substring(SQLTEXT from 1 for 2000));
  TEXT = replace(TEXT, ascii_char(13) || ascii_char(10), ' ');
  TEXT = upper(TEXT);
  IDXSTART = position(' TABLE ', TEXT) + 6;
  ISIZE = position('(', upper(TEXT)) - IDXSTART;

  TEXT = substring(TEXT from IDXSTART for ISIZE);
  TEXT = trim(TEXT);

  TABELA = trim(substring(TEXT from 1 for 31));

  if (not exists(select 1
                 from RDB$RELATIONS
                 where RDB$RELATION_NAME = :TABELA)) then
    for select TEXT
        from SP_SPLIT(:SQLTEXT, :TERMINATORSTR)
          into :SQLPART
    do
      execute statement :SQLPART;
end ^

ALTER PROCEDURE SPDB_IS_PK (TABELA VARCHAR(31) CHARACTER SET NONE,
CAMPO VARCHAR(31) CHARACTER SET NONE)
RETURNS (ISPK SMALLINT)
AS 
begin
  ISPK = 0;
  for select count(SG.RDB$FIELD_NAME) as FIELD_NAME
      from RDB$RELATION_CONSTRAINTS RC
        inner join RDB$INDICES IX on RC.RDB$INDEX_NAME = IX.RDB$INDEX_NAME
        inner join RDB$INDEX_SEGMENTS SG on IX.RDB$INDEX_NAME = SG.RDB$INDEX_NAME
      where RC.RDB$CONSTRAINT_TYPE = 'PRIMARY KEY' and
            RC.RDB$RELATION_NAME = :TABELA and
            SG.RDB$FIELD_NAME = :CAMPO
        into :ISPK
  do
    suspend;
end ^

ALTER PROCEDURE SPDB_MAKE_DEP (TABELA VARCHAR(31) CHARACTER SET NONE,
DEPENDENCIATIPO CHAR(1) CHARACTER SET NONE,
COMEMPRESA INTEGER = 0)
RETURNS (RESULT INTEGER)
AS 
  declare variable MAXID integer;
  declare variable EXISTE integer;
begin
  --DEPENDENCIATIPO: E: Eu dependo delas; D: Dependem de mim
  DEPENDENCIATIPO = upper(trim(DEPENDENCIATIPO));

  select RESULT
  from SPDB_MAKE_DEP_RECURSIVE(:TABELA, :DEPENDENCIATIPO, :COMEMPRESA)
    into :RESULT;

  EXISTE = 0;
  select count(T.TABELA)
  from RI_DEP T
  where T.TABELA = :TABELA
    into :EXISTE;

  if (coalesce(EXISTE, 0) = 0) then
  begin
    select max(T.ORDEM)
    from RI_DEP T
      into :MAXID;
    MAXID = coalesce(MAXID, 0) + 1;
    insert into RI_DEP (ORDEM, TABELA)
    values (:MAXID, :TABELA);
  end
  RESULT = 1;
  suspend;
end ^

ALTER PROCEDURE SPDB_MAKE_DEP_RECURSIVE (TABELA VARCHAR(31) CHARACTER SET NONE,
DEPENDENCIATIPO CHAR(1) CHARACTER SET NONE,
COMEMPRESA INTEGER = 0)
RETURNS (RESULT INTEGER)
AS 
  declare variable TAB_REL varchar(31);
  declare variable MAXID integer;
  declare variable EXISTE integer;
  declare variable EUDEPENDO smallint;
  declare variable DEPENDEMDEMIM smallint;
begin
  --DEPENDENCIATIPO: E: Eu dependo delas; D: Dependem de mim

  EUDEPENDO = iif(DEPENDENCIATIPO = 'E', 1, 0);
  DEPENDEMDEMIM = iif(DEPENDENCIATIPO = 'D', 1, 0);

  for select distinct D.TABELA
      from SPDB_DEPEND(:TABELA, :EUDEPENDO, :DEPENDEMDEMIM) D
      where D.TABELA <> :TABELA
        into :TAB_REL
  do
  begin

    TAB_REL = trim(coalesce(TAB_REL, ''));

    EXISTE = 0;
    select count(T.TABELA)
    from RI_DEP T
    where T.TABELA = :TAB_REL
      into :EXISTE;

    if (coalesce(EXISTE, 0) = 0) then
    begin
      select RESULT
      from SPDB_MAKE_DEP_RECURSIVE(:TAB_REL, :DEPENDENCIATIPO, :COMEMPRESA)
        into :EXISTE;

      select max(T.ORDEM)
      from RI_DEP T
        into :MAXID;
      MAXID = coalesce(MAXID, 0) + 1;

      EXISTE = 0;
      if (COMEMPRESA = 0) then
        select count(T.TABELA)
        from SPDB_TABLES T
          left join SPDB_EMP_KEY(T.TABELA) P on 1 = 1
        where T.TABELA = :TAB_REL and
              P.CAMPO_EMP <> ''
          into :EXISTE;

      if ((coalesce(EXISTE, 0) > 0) or (COMEMPRESA = 0)) then
        insert into RI_DEP (ORDEM, TABELA)
        values (:MAXID, :TAB_REL);
    end
  end

  RESULT = 1;
  suspend;
end ^

ALTER PROCEDURE SPDB_REPLICATE_TABLE (TABELA VARCHAR(31) CHARACTER SET NONE,
ACAO CHAR(1) CHARACTER SET NONE,
IDORIG INTEGER,
IDDEST INTEGER)
RETURNS (PASSO BLOB CHARACTER SET NONE)
AS 
  declare variable CAMPO_E varchar(31);
  declare variable FIELDNAME varchar(31);
  declare variable FIELDKEY varchar(31);
  declare variable FTYPE integer;
  declare variable FSUBTYPE integer;
  declare variable STMT blob sub_type 1 segment size 80;
  declare variable SEQID integer;
begin
  if (ACAO = 'X')  then
  begin
    for select CAMPO_EMP from SPDB_EMP_KEY(:TABELA)
        where coalesce(CAMPO_EMP, '') <> ''
          into :CAMPO_E
    do
    begin
      PASSO = 'INICIADO';
      suspend;

      STMT = 'delete from ' || TABELA || ' where ' || CAMPO_E || ' = ' || cast(IDORIG as varchar(20));

      PASSO = stmt;
      suspend;

      execute statement STMT;

      delete from CODIGO
      where TABELA = :TABELA and
            COD_EMPRESA = :IDORIG;

      PASSO = 'CONCLUIDO';
      suspend;
    end
  end
  else
  if (ACAO = 'I') then
  begin
    for select CAMPO_EMP from SPDB_EMP_KEY(:TABELA)
        where coalesce(CAMPO_EMP, '') <> ''
          into :CAMPO_E
    do
    begin
      PASSO = 'INICIADO';
      suspend;

      STMT = '';

      FIELDKEY = '';
      for select RF.RDB$FIELD_NAME, F.RDB$FIELD_TYPE, F.RDB$FIELD_SUB_TYPE
          from RDB$RELATION_FIELDS RF
            join RDB$FIELDS F on (F.RDB$FIELD_NAME = RF.RDB$FIELD_SOURCE)
          where (RF.RDB$RELATION_NAME = :TABELA) and
                (coalesce(RF.RDB$SYSTEM_FLAG, 0) = 0) and
                (RF.RDB$FIELD_NAME <> :CAMPO_E) and
                (F.RDB$COMPUTED_SOURCE IS NULL) and
                (RF.RDB$FIELD_NAME not in ('REP_INT_ACTIVE', 'ID_COMMERCE', 'SEQID_SINC', 'SEQID_SINCOFF', 'GUIDT'))
          order by RF.RDB$FIELD_POSITION
            into :FIELDNAME, :FTYPE, FSUBTYPE
      do
      begin
        FIELDNAME = trim(FIELDNAME);
        if (STMT <> '') then
          STMT = STMT || ',' || FIELDNAME;
        else
          STMT = FIELDNAME;

        if ((FTYPE in (7, 8, 16)) and
            (FSUBTYPE = 0) and
            (FIELDKEY = '') and
            (TABELA <> 'PRODUTOS')) then
        begin
          -- talvez um retorno com a quantidade de campos q forma a pk, tabela terminal_cartao por exemplo tem cmpo inteiro chave, porem outro campo faz parete e nao usa tabela codigo
          select count(PK.FIELDNAME)
          from SPDB_FIELDS_PK(:TABELA) PK
          where PK.FIELDNAME = :FIELDNAME
            into :SEQID;

          if (coalesce(SEQID, 0) = 1) then
          begin
            select count(SG.RDB$FIELD_NAME) as FIELD_NAME
            from RDB$INDICES IX
              left join RDB$INDEX_SEGMENTS SG on IX.RDB$INDEX_NAME = SG.RDB$INDEX_NAME
              left join RDB$RELATION_CONSTRAINTS RC on RC.RDB$INDEX_NAME = IX.RDB$INDEX_NAME
            where RC.RDB$CONSTRAINT_TYPE = 'PRIMARY KEY' and
                  RC.RDB$RELATION_NAME = :TABELA and
                  SG.RDB$FIELD_NAME <> :CAMPO_E
              into :SEQID;

            if (coalesce(SEQID, 0) = 1) then
              FIELDKEY = FIELDNAME;
          end
        end
      end

      STMT = 'insert into ' || TABELA || '(' || CAMPO_E || ',' || STMT || ') ' || 'select ' || cast(IDDEST as varchar(20)) || ',' || STMT || ' from ' || TABELA || ' where ' || CAMPO_E || ' = ' || cast(IDORIG as varchar(20));

      PASSO = stmt;
      suspend;

      execute statement STMT;

      if (TABELA = 'PRODUTOS') then
      begin
        insert into CODIGO (TABELA, COD_EMPRESA, VALOR, CODIGO)
          select TABELA, :IDDEST, VALOR, 0 from CODIGO
            where TABELA = :TABELA and
                  COD_EMPRESA = :IDORIG;
      end
      else if (FIELDKEY <> '') then
      begin
        execute statement 'select max(' || FIELDKEY || ') from ' || TABELA || ' where ' || CAMPO_E || ' = ' || cast(IDDEST as varchar(20))
            into :SEQID;
        if (coalesce(SEQID, 0) > 0) then
          insert into CODIGO (TABELA, COD_EMPRESA, VALOR, CODIGO)
          values (:TABELA, :IDDEST, :SEQID, 0);
      end

      PASSO = 'CONCLUIDO';
      suspend;
    end
  end
end ^

ALTER PROCEDURE SPDB_RI_MAKE_DEP (TABELA VARCHAR(31) CHARACTER SET NONE)
AS 
  declare variable TAB_REL varchar(31);
  declare variable MAXID integer;
  declare variable EXISTE integer;
begin

  for select DISTINCT RF.RDB$RELATION_NAME TAB_REF
      from RDB$INDICES IX
        left join RDB$INDEX_SEGMENTS SG on IX.RDB$INDEX_NAME = SG.RDB$INDEX_NAME
        left join RDB$RELATION_CONSTRAINTS RC on RC.RDB$INDEX_NAME = IX.RDB$INDEX_NAME
        left join RDB$RELATION_CONSTRAINTS RF on RF.RDB$INDEX_NAME = IX.RDB$FOREIGN_KEY
      where RC.RDB$CONSTRAINT_TYPE = 'FOREIGN KEY' and
            RC.RDB$RELATION_NAME = :TABELA and
            RF.RDB$RELATION_NAME <> :TABELA
        into :TAB_REL
  do
  begin

    TAB_REL = trim(coalesce(TAB_REL, ''));

    EXISTE = 0;
    select count(T.TABELA)
    from RI_DEP T
    where T.TABELA = :TAB_REL
      into :EXISTE;

    if (coalesce(EXISTE, 0) = 0) then
    begin
      execute procedure SPDB_RI_MAKE_DEP(:TAB_REL);

      select max(T.ORDEM)
      from RI_DEP T
        into :MAXID;
      MAXID = coalesce(MAXID, 0) + 1;

      EXISTE = 0;
      select count(T.TABELA)
      from SPDB_TABLES T
        left join SPDB_EMP_KEY(T.TABELA) P on 1 = 1
      where T.TABELA = :TAB_REL and
            P.CAMPO_EMP <> ''
        into :EXISTE;

      if (coalesce(EXISTE, 0) > 0) then
        insert into RI_DEP (ORDEM, TABELA)
        values (:MAXID, :TAB_REL);
    end
  end
end
 
 ^

ALTER PROCEDURE SPDB_TABLES RETURNS (TABELA VARCHAR(31) CHARACTER SET NONE)
AS 
begin
  for select R.RDB$RELATION_NAME
      from RDB$RELATIONS R
      where ((R.RDB$SYSTEM_FLAG = 0) or (R.RDB$SYSTEM_FLAG is null)) and
            (R.RDB$VIEW_SOURCE is null)
      order by RDB$RELATION_NAME
        into :TABELA
  do
    suspend;
end ^

ALTER PROCEDURE SPDB_TABLES_COUNT (CODEMPRESA INTEGER)
RETURNS (TABELA VARCHAR(32) CHARACTER SET NONE,
CAMPO_EMP VARCHAR(32) CHARACTER SET NONE,
COD_EMPRESA INTEGER,
CONTADOR INTEGER,
TIPO SMALLINT,
TIPOSTR VARCHAR(16) CHARACTER SET NONE)
AS 
begin
  for select T.TABELA, T.CAMPO_EMP, max(T.TIPOSTR) TIPOSTR, sum(T.TIPO) TIPO
      from (select T.TABELA, T.CAMPO_EMP, T.TIPOSTR, T.TIPO
            from SPDB_TABLES_TIPO T
            union
            select trim(R.RDB$RELATION_NAME) TABELA, EK.CAMPO_EMP, '?' TIPOSTR, 0 TIPO
            from RDB$RELATIONS R
              left join SPDB_EMP_KEY(R.RDB$RELATION_NAME) EK on 1 = 1
            where ((R.RDB$SYSTEM_FLAG = 0) or (R.RDB$SYSTEM_FLAG is null)) and
                  (R.RDB$VIEW_SOURCE is null)) as T
      group by 1, 2
      order by TABELA
      into :TABELA, :CAMPO_EMP, :TIPOSTR, :TIPO
  do
  begin
    if ((coalesce(CODEMPRESA, 0) = 999) and (coalesce(campo_emp, '') <> '')) then
    begin
      for select cod_empresa from empresa into :cod_empresa do
      begin
        for execute statement 'select count(*) from ' || :TABELA || ' where ' ||:campo_emp || ' = ' || :cod_empresa
            into :CONTADOR
        do
        begin
          suspend;
        end
      end
    end
    else if ((coalesce(CODEMPRESA, 0) > 0) and (coalesce(campo_emp, '') <> '')) then
    begin
      COD_EMPRESA = CODEMPRESA;
      execute statement 'select count(*) from ' || :TABELA || ' where ' ||:campo_emp || ' = ' || :cod_empresa
          into :CONTADOR;
      suspend;
    end
    else
    begin
      COD_EMPRESA = null;
      execute statement 'select count(*) from ' || :TABELA
          into :CONTADOR;
      suspend;
    end
  end
end ^

