ALTER PROCEDURE SPDB_TRIGGER_TOGGLE_RI_TB_REP (ONOFF SMALLINT)
RETURNS (TABELA VARCHAR(31) CHARACTER SET NONE,
TGNAME VARCHAR(31) CHARACTER SET NONE)
AS 
begin
  if (ONOFF = 0) then
  begin
    for select DISTINCT NE.TABELA
        from RI_REPLICATE_ACTIONS NE
          into :TABELA
    do
    begin
      for select TG.RDB$TRIGGER_NAME
          from RDB$TRIGGERS TG
          where TG.RDB$RELATION_NAME = :TABELA and
                TG.RDB$SYSTEM_FLAG = 0 and
                TG.RDB$VALID_BLR = 1 and
                TG.RDB$TRIGGER_INACTIVE = 0
            into :TGNAME
      do
      begin
        insert into RI_REPLICATE_TRIGGERS values (:TGNAME);
        execute statement 'alter trigger ' || :TGNAME || ' inactive;';
        suspend;
      end
    end
  end
  else if (ONOFF = 1) then
  begin
    for select T.TRIGGERN
        from RI_REPLICATE_TRIGGERS T
          into :TGNAME
    do
    begin
      for select TG.RDB$RELATION_NAME
          from RDB$TRIGGERS TG
          where TG.RDB$TRIGGER_NAME = :TGNAME and
                TG.RDB$SYSTEM_FLAG = 0
            into :TABELA
      do
      begin
        execute statement 'alter trigger ' || :TGNAME || ' active;';
        suspend;
      end
    end
    delete from RI_REPLICATE_TRIGGERS;
  end
end ^

ALTER PROCEDURE SPED_1601 (EMPRESA INTEGER,
DATAINI TIMESTAMP,
DATAFIM TIMESTAMP)
RETURNS (COD_PART_IP INTEGER,
COD_PART_IT INTEGER,
TOT_VS DOUBLE PRECISION,
TOT_ISS DOUBLE PRECISION,
TOT_OUTROS DOUBLE PRECISION)
AS 
begin
  for select COD_PART_IP, COD_PART_IT, sum(TOT_VS), sum(TOT_ISS), sum(TOT_OUTROS)
      from SPED_1601_V1(:EMPRESA, :DATAINI, :DATAFIM)
      group by 1, 2
        into :COD_PART_IP, :COD_PART_IT, :TOT_VS, :TOT_ISS, :TOT_OUTROS
  do
    suspend;
end ^

ALTER PROCEDURE SPED_1601_V1 (EMPRESA INTEGER,
DATAINI TIMESTAMP,
DATAFIM TIMESTAMP)
RETURNS (COD_PART_IP INTEGER,
COD_PART_IT INTEGER,
TOT_VS DOUBLE PRECISION,
TOT_ISS DOUBLE PRECISION,
TOT_OUTROS DOUBLE PRECISION)
AS 
  declare variable CURRENT_COD_PART_IP integer;
  declare variable CURRENT_COD_PART_IT integer;
  declare variable NDOC integer;
  declare variable TIPODOC varchar(6);
  declare variable VALORDOC double precision;
  declare variable VALOROPERACAO double precision;
  declare variable VALORSERVICO double precision;
  declare variable CONTADOR integer;
  declare variable COD_CRED integer;
begin

  --competencia, instantaneo, debito e credito

  COD_PART_IP = null;
  COD_PART_IT = null;
  TOT_VS = 0;
  TOT_ISS = 0;
  TOT_OUTROS = 0;
  VALOROPERACAO = 0;
  CONTADOR = 0;
  for select coalesce(CL.CARTAO_SPED_PART, 0), coalesce(CL.CARTAO_SPED_PART_IT, 0), trim(tpdocs), coalesce(FP.nrequisicao, 0),
             sum(FP.VALORDOC) VALOROPERACAO
      from FORMPAGAMENTO FP
        inner join CONTROLES CL on CL.CODIGO_CTRL = FP.COD_CONTROLE and
              CL.CODIGO_EMP = FP.COD_EMPRESA
      where coalesce(CL.CARTAO_SPED, 0) in (1, 2, 3) and
            FP.COD_EMPRESA = :EMPRESA and
            FP.DATA_MOV >= :DATAINI and
            FP.DATA_MOV <= :DATAFIM
      group by 1, 2, 3, 4
      order by 1, 2, 3, 4
        into :CURRENT_COD_PART_IP, :CURRENT_COD_PART_IT, :TIPODOC, :NDOC, :VALOROPERACAO
  do
  begin
    CONTADOR = CONTADOR + 1;
    if (CONTADOR = 42) then
      CONTADOR = 0;

    if ((COD_PART_IP <> coalesce(CURRENT_COD_PART_IP, 0)) or (COD_PART_IT <> coalesce(CURRENT_COD_PART_IT, 0))) then
    begin
      suspend;
      TOT_VS = 0;
      TOT_ISS = 0;
      TOT_OUTROS = 0;
    end
    COD_PART_IP = CURRENT_COD_PART_IP;
    COD_PART_IT = CURRENT_COD_PART_IT;

    VALORSERVICO = 0;
    VALORDOC = 0;

    if (TIPODOC = 'OS') then
    begin
      select (coalesce(PV.TOT_PROD, 0) + coalesce(PV.TOT_SERV, 0) + coalesce(PV.TOT_PROD_TERC, 0) + coalesce(PV.TOT_SERV_TERC, 0)) TOTAL,
             (coalesce(PV.TOT_SERV, 0) + coalesce(PV.TOT_SERV_TERC, 0)) TOTALSERVICO
      from PEDVENDA PV
      where PV.NPED = :NDOC and
            PV.TIPO = :TIPODOC and
            PV.COD_EMPRESA = :EMPRESA
        into :VALORDOC, :VALORSERVICO;
    end
    else if (TIPODOC = 'REC') then
    begin                             
      select sum((coalesce(PV.TOT_PROD, 0) + coalesce(PV.TOT_SERV, 0) + coalesce(PV.TOT_PROD_TERC, 0) + coalesce(PV.TOT_SERV_TERC, 0))) TOTAL,
             sum((coalesce(PV.TOT_SERV, 0) + coalesce(PV.TOT_SERV_TERC, 0))) TOTALSERVICO
      from sp_recibo_usado_em(:ndoc, :empresa) orig
           inner join PEDVENDA PV on pv.tipo = orig.tipo and pv.nped = orig.numero and pv.cod_empresa = :empresa
        into :VALORDOC, :VALORSERVICO;
    end

      if ((coalesce(VALORSERVICO, 0) > 0) and (coalesce(VALORDOC, 0) > 0)) then
      begin
        VALORSERVICO = VALORSERVICO / VALORDOC;
        VALORSERVICO = round(VALOROPERACAO * VALORSERVICO, 2);

        TOT_ISS = TOT_ISS + VALORSERVICO;
        TOT_VS = TOT_VS + (VALOROPERACAO - VALORSERVICO);
      end
      else
        TOT_VS = TOT_VS + VALOROPERACAO;


  end
  if (VALOROPERACAO > 0) then
    suspend;

  --caixa, boletos e afins

  COD_PART_IP = null;
  COD_PART_IT = null;
  TOT_VS = 0;
  TOT_ISS = 0;
  TOT_OUTROS = 0;
  VALOROPERACAO = 0;
  CONTADOR = 0;
  for select coalesce(CL.CARTAO_SPED_PART, 0), coalesce(CL.CARTAO_SPED_PART_IT, 0), trim(CC.TP_DOC_V),
             coalesce(CC.N_DOC_V, 0), CC.COD_CRED, sum(coalesce(CC.VALOR_ORIGINAL, CC.VALOR_C)) VALOROPERACAO
      from CONTROLES CL
        inner join CONTROLE_CREDITOS CC on CL.CODIGO_CTRL = CC.CODIGO_CTRL and
              CL.CODIGO_EMP = CC.COD_EMP_MULT
      where CL.CARTAO_SPED in (4) and
            CL.CODIGO_EMP = :EMPRESA and
            CC.DATQ_C >= :DATAINI and
            CC.DATQ_C <= :DATAFIM and
            coalesce(cc.tip_baixa, '') not in ('M','A','D','C') and
            (select first 1 c.contr_banc from lancamentos l
            inner join controles c on c.codigo_ctrl = l.codigo_ctrl and c.codigo_emp = l.cod_emp_mult
            where l.lote_ent = cc.lote_quit and l.cod_emp_mult = cc.cod_emp_mult and c.docs = 'N' and c.contr_banc = 'S') = 'S'
      group by 1, 2, 3, 4, 5
      order by 1, 2, 3, 4, 5
        into :CURRENT_COD_PART_IP, :CURRENT_COD_PART_IT, :TIPODOC, :NDOC, :COD_CRED, :VALOROPERACAO
  do
  begin
    CONTADOR = CONTADOR + 1;
    if (CONTADOR = 42) then
      CONTADOR = 0;

    if ((COD_PART_IP <> coalesce(CURRENT_COD_PART_IP, 0)) or (COD_PART_IT <> coalesce(CURRENT_COD_PART_IT, 0))) then
    begin
      suspend;
      TOT_VS = 0;
      TOT_ISS = 0;
      TOT_OUTROS = 0;
    end
    COD_PART_IP = CURRENT_COD_PART_IP;
    COD_PART_IT = CURRENT_COD_PART_IT;

    VALORSERVICO = 0;
    VALORDOC = 0;

    if (TIPODOC = 'OS') then
    begin
      select (coalesce(PV.TOT_PROD, 0) + coalesce(PV.TOT_SERV, 0) + coalesce(PV.TOT_PROD_TERC, 0) + coalesce(PV.TOT_SERV_TERC, 0)) TOTAL,

                                                                                                                                                                                                                                                                      (coalesce(PV.TOT_SERV, 0) + coalesce(PV.TOT_SERV_TERC, 0)) TOTALSERVICO
      from PEDVENDA PV
      where PV.NPED = :NDOC and
            PV.TIPO = :TIPODOC and
            PV.COD_EMPRESA = :EMPRESA
        into :VALORDOC, :VALORSERVICO;
    end
    else
    if (TIPODOC = 'REC') then
    begin
      select sum((coalesce(PV.TOT_PROD, 0) + coalesce(PV.TOT_SERV, 0) + coalesce(PV.TOT_PROD_TERC, 0) + coalesce(PV.TOT_SERV_TERC, 0))) TOTAL,
             sum((coalesce(PV.TOT_SERV, 0) + coalesce(PV.TOT_SERV_TERC, 0))) TOTALSERVICO
      from SP_RECIBO_USADO_EM(:NDOC, :EMPRESA) ORIG
        inner join PEDVENDA PV on PV.TIPO = ORIG.TIPO and
              PV.NPED = ORIG.NUMERO and
              PV.COD_EMPRESA = :EMPRESA
        into :VALORDOC, :VALORSERVICO;
    end
    else
    if (coalesce(TIPODOC, '') <> 'REQ') then
    begin
      select sum((coalesce(PV.TOT_PROD, 0) + coalesce(PV.TOT_SERV, 0) + coalesce(PV.TOT_PROD_TERC, 0) + coalesce(PV.TOT_SERV_TERC, 0))) TOTAL,
             sum((coalesce(PV.TOT_SERV, 0) + coalesce(PV.TOT_SERV_TERC, 0))) TOTALSERVICO
      from SP_CRED_GET_VND_ORIG(:COD_CRED, :EMPRESA) ORIG
        inner join PEDVENDA PV on PV.TIPO = ORIG.TIPO and
              PV.NPED = ORIG.NUMERO and
              PV.COD_EMPRESA = :EMPRESA
        into :VALORDOC, :VALORSERVICO;
    end

    if ((coalesce(VALORSERVICO, 0) > 0) and
        (coalesce(VALORDOC, 0) > 0)) then
    begin
      VALORSERVICO = VALORSERVICO / VALORDOC;
      VALORSERVICO = round(VALOROPERACAO * VALORSERVICO, 2);

      TOT_ISS = TOT_ISS + VALORSERVICO;
      TOT_VS = TOT_VS + (VALOROPERACAO - VALORSERVICO);
    end
    else
      TOT_VS = TOT_VS + VALOROPERACAO;

  end
  if (VALOROPERACAO > 0) then
    suspend;

end
 
 ^

ALTER PROCEDURE SPRI_EXEC (TABELA VARCHAR(31) CHARACTER SET NONE,
CONDICAO_O VARCHAR(255) CHARACTER SET NONE,
CONDICAO_D VARCHAR(255) CHARACTER SET NONE,
IDORIGEM INTEGER,
REMOVER SMALLINT)
AS 
  declare variable CAMPO_E varchar(31);
  declare variable FIELDNAME varchar(31);
  declare variable FIELDKEY varchar(31);
  declare variable CONDORIG varchar(255);
  declare variable CONDDEST varchar(255);
  declare variable FTYPE2 varchar(32);
  declare variable STMT blob sub_type 1 segment size 80;
  declare variable STMTV blob sub_type 1 segment size 80;
  declare variable STMTRUN blob sub_type 1 segment size 80;
  declare variable STMTI blob sub_type 1 segment size 256;
  declare variable STMTU blob sub_type 1 segment size 256;
  declare variable STMTE blob sub_type 1 segment size 512;
  declare variable ISPK integer;
  declare variable COUNTPK integer;
  declare variable IDDEST integer;
  declare variable TIPO_ID smallint;
  declare variable SCHEMA_ID smallint;
  declare variable CONTEXT_VAR varchar(80);
  declare variable CONTEXT_STAT varchar(255);
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;
    
  select S.SCHEMA_ID, S.TIPO_ID
  from SPRI_SCHEMA(:TABELA, :IDORIGEM) S
      into :SCHEMA_ID, :TIPO_ID;

  if (coalesce(SCHEMA_ID, 0) <= 0) then
    exit;

  TIPO_ID = coalesce(TIPO_ID, 0);

  select GUIDT from RI_TAB where TABELA = :TABELA into :CONTEXT_VAR;

  if (CONTEXT_VAR is null) then
    exit;

  select RDB$GET_CONTEXT('USER_TRANSACTION', :CONTEXT_VAR)
  from RDB$DATABASE
    into :CONTEXT_STAT;

  if (trim(CONTEXT_STAT) = trim(CONDICAO_O)) then
    exit;

  RDB$SET_CONTEXT('USER_TRANSACTION', :CONTEXT_VAR, CONDICAO_O);

  insert into RI_TMP_SQL (SQLEXEC)
    values ('CONDICAO_O ' || :CONDICAO_O || ASCII_CHAR(13) || ' CONDICAO_D ' || :CONDICAO_D );

  select E.CAMPO_EMP, PK.COUNTPK
  from SPDB_EMP_KEY(:TABELA) E
    left join SPDB_COUNT_PK(:TABELA) PK on 1 = 1
    into :CAMPO_E, :COUNTPK;

  CONDICAO_O = trim(coalesce(CONDICAO_O, ''));
  CONDORIG = replace(CONDICAO_O, '@', 's') || iif(CONDICAO_O <> '', ' and ', '') || ' s.' || CAMPO_E || ' = ' || cast(IDORIGEM as varchar(20));

  CONDICAO_D = trim(coalesce(CONDICAO_D, ''));
  CONDDEST = replace(CONDICAO_D, '@', 'd') || iif(CONDICAO_D <> '', ' and ', '') || ' d.' || CAMPO_E || ' = @IDDEST@';

  if (((CONDICAO_O = '') or (CONDICAO_D = '')) and (COUNTPK > 1)) then
    exit;

  STMT = CAMPO_E;
  STMTV = '';
  STMTU = '';
  FIELDKEY = '';

  if (coalesce(REMOVER, 0) <> 1) then
    for select F.FIELDNAME, F.FIELDTYPE2, PK.ISPK
        from SPDB_FIELDS(:TABELA) F
          left join SPDB_IS_PK(:TABELA, F.FIELDNAME) PK on 1 = 1
          inner join RI_SCHEMA_TAB T on T.TABELA = :TABELA and
                T.SCHEMA_ID = :SCHEMA_ID
          left join RI_SCHEMA_TAB_EXCE TE on TE.TABELA_ID = T.ID and
                TE.CAMPO = F.FIELDNAME
        where F.FIELDNAME <> :CAMPO_E and
              F.FIELDNAME not in ('REP_INT_ACTIVE', 'ID_COMMERCE', 'SEQID_SINC', 'SEQID_SINCOFF', 'GUIDT') and
              TE.CAMPO is null
          into :FIELDNAME, :FTYPE2, ISPK    
    do
    begin
      STMT = STMT || ',' || FIELDNAME;

      if ((FTYPE2 = 'INT') and
          (FIELDKEY = '') and
          (coalesce(ISPK, 0) = 1) and
          (coalesce(COUNTPK, 0) = 2)) then 
          FIELDKEY = FIELDNAME;
  
      if ((TIPO_ID = 1) and
          (FIELDKEY = FIELDNAME)) then
      begin
        if (STMTV <> '') then
          STMTV = STMTV || ',';
  
        STMTV = STMTV || '@FUNCAO_INCREMENTA_CODIGO@';
      end
      else
      begin
        if (STMTV <> '') then
          STMTV = STMTV || ',';
        STMTV = STMTV || 's.' || FIELDNAME;
  
        if (STMTU <> '') then
          STMTU = STMTU || ',';
  
        STMTU = STMTU || 'd.' || FIELDNAME || '=s.' || FIELDNAME;
      end
    end

  for select E.EMPRESA_ID
      from RI_SCHEMA_EMP E
        inner join RI_SCHEMA S on E.SCHEMA_ID = S.ID
        inner join RI_SCHEMA_TAB TB on TB.SCHEMA_ID = S.ID
      where E.EMPRESA_ID <> :IDORIGEM and
            TB.TABELA = :TABELA and
            S.ID in (select S.ID
                     from RI_SCHEMA S
                       inner join RI_SCHEMA_TAB T on T.SCHEMA_ID = S.ID
                       inner join RI_SCHEMA_EMP E on E.SCHEMA_ID = S.ID
                     where E.EMPRESA_ID = :IDORIGEM and
                           T.TABELA = :TABELA)
      order by E.EMPRESA_ID
        into :IDDEST
  do
  begin
    if (REMOVER = 1) then
      STMTE = 'delete from ' || :TABELA || ' d where ' || replace(CONDDEST, '@IDDEST@', cast(IDDEST as varchar(20)));
    else
    begin 
      STMTRUN = replace(STMTV, '@FUNCAO_INCREMENTA_CODIGO@', '(select COD from INCREMENTA_CODIGO('|| cast(IDDEST as varchar(20)) || ',''' || :TABELA || '''))');

      STMTI = cast(IDDEST as varchar(20)) || ',' || STMTRUN;
  
      STMTE = 'merge into ' || TABELA || ' d' ||
              ' using (select * from ' || TABELA || ' where ' || replace(CONDORIG, 's.', '') || ') s' ||
              ' on (' || replace(CONDDEST, '@IDDEST@', cast(IDDEST as varchar(20))) || ')' ||
              ' when matched then' ||
              '   update set ' || STMTU ||
              ' when not matched then' ||
              '   insert (' || STMT || ') values (' || STMTI || ')';
    end

    insert into RI_TMP_SQL (SQLEXEC)
    values (:STMTE);

    execute statement STMTE;

    CONDICAO_O = replace(CONDICAO_O, '@.', '');
    CONDICAO_D = replace(CONDICAO_D, '@.', '');
    CONDICAO_O = replace(CONDICAO_O, ' and ', ' ');
    CONDICAO_D = replace(CONDICAO_D, ' and ', ' ');

    insert into RI_TAB_LOG (SEQID, TABELA, CONDICAO_O, CONDICAO_D, IDORIG, IDDEST, EXCLUSAO, DH_REP)
    values (gen_id(SEQ_REP_INT_LOG, 1), :TABELA, :CONDICAO_O, :CONDICAO_D, :IDORIGEM, :IDDEST, :REMOVER, current_timestamp);
  end

  RDB$SET_CONTEXT('USER_TRANSACTION', :CONTEXT_VAR, null);
end ^

ALTER PROCEDURE SPRI_FKCHECK (TABELA VARCHAR(31) CHARACTER SET NONE,
CONSTRAINT_NAME VARCHAR(31) CHARACTER SET NONE,
KEYVALUES BLOB CHARACTER SET NONE)
RETURNS (IDPK INTEGER)
AS 
  declare variable IDTMP integer;
  declare variable VALORES blob sub_type 1 segment size 512;
begin
  IDPK = 0;
  for select ID, KEYVALUES
      from RI_TAB_UPDATEKEY
      where TABELA = :TABELA and
            CONSTRAINT_NAME = :CONSTRAINT_NAME
        into :IDTMP, :VALORES
  do
  begin
    if (VALORES = KEYVALUES) then
    begin
      IDPK = IDTMP;
      break;
    end
  end

  suspend;
end ^

ALTER PROCEDURE SPRI_MAKE_OBJ (TABELA VARCHAR(31) CHARACTER SET NONE,
SCH_TB_ID INTEGER,
REMOVER SMALLINT = 0)
AS 
declare variable SCHEMA_ID integer;
declare variable TABLE_ID integer;
declare variable STMTTR blob sub_type 1 segment size 256;
declare variable SQLTMP blob sub_type 1 segment size 32;
declare variable SQLTMP2 blob sub_type 1 segment size 32;
declare variable SQLTMP3 blob sub_type 1 segment size 32;
declare variable STMTCASE0 blob sub_type 1 segment size 32;
declare variable STMTCASE1 blob sub_type 1 segment size 32;
declare variable STMTCASEWHEN1 blob sub_type 1 segment size 32;
declare variable STMTCASEWHEN2 blob sub_type 1 segment size 32;
declare variable STMTEMPTY blob sub_type 1 segment size 32;
declare variable STMTACTIVE blob sub_type 1 segment size 32;
declare variable STMTACTIVEEND blob sub_type 1 segment size 32;
declare variable LOGKEYSUPDATE blob sub_type 1 segment size 32;
declare variable VARPKID varchar(128);
declare variable TNAME varchar(31);
declare variable TRNAME varchar(31);
declare variable FNAME varchar(31);
declare variable PKNAME varchar(31);
declare variable FKNAME varchar(31);
declare variable FEMPNAME varchar(31);
declare variable FTYPE varchar(32);
declare variable FISPK smallint;
declare variable FISWHERE smallint;
declare variable TPID smallint;
declare variable KEYONLYEMP integer;
begin
  TABELA = trim(TABELA);

  update or insert into RI_TAB (TABELA)
  values (:TABELA)
  matching (TABELA);

  select T.ID, E.CAMPO_EMP
  from RI_TAB T
    left join SPDB_EMP_KEY(T.TABELA) E on 1 = 1
  where T.TABELA = :TABELA
    into :TABLE_ID, :FEMPNAME;

  TRNAME = 'TI_RI_' ||(select RESULT
                       from STRZERO(:TABLE_ID, 3));
  STMTCASE0 = '';
  STMTCASEWHEN1 = '';
  STMTCASEWHEN2 = '';
  STMTACTIVE = '';
  STMTACTIVEEND = '';

  if (REMOVER = 1) then
  begin
    FNAME = '';

    select count(ID)
    from RI_SCHEMA_TAB
    where TABELA = :TABELA
      into :TABLE_ID;

    if (coalesce(TABLE_ID, 0) = 0) then
    begin
      select trim(TG.RDB$TRIGGER_NAME)
      from RDB$TRIGGERS TG
      where TG.RDB$RELATION_NAME = :TABELA and
            TG.RDB$TRIGGER_NAME = :TRNAME and
            TG.RDB$SYSTEM_FLAG = 0
        into :FNAME;
  
      if (FNAME = TRNAME) then
        STMTTR = 'DROP TRIGGER ' || TRNAME;
      else
        STMTTR = 'DROP TRIGGER ' || TRNAME || ' - trigger not exists';
  
      insert into RI_TMP_SQL (SQLEXEC)
      values (:STMTTR);
  
      if (FNAME = TRNAME) then
        execute statement STMTTR;
      exit;
    end
    else
      REMOVER = 0;
  end

  VARPKID = '';
  SQLTMP = '';
  for select distinct TABLE_REF, PK_NAME, FK_NAME
    from SPDB_FIELDS_FK(:TABELA)
    where UPDATE_CASCATA = 1
      into :TNAME, :PKNAME, :FKNAME
  do
  begin
    SQLTMP2 = '';
    SQLTMP3 = '';

    for select FIELDNAME
        from SPDB_FIELDS_FK(:TABELA)
        where FK_NAME = :FKNAME
          into :FNAME
    do
    begin
      if (SQLTMP2 <> '') then
      begin
        SQLTMP2 = SQLTMP2 || ' || ''-'' || ';
        SQLTMP3 = SQLTMP3 || ' or ';
      end
      SQLTMP2 = SQLTMP2 || 'old.' || FNAME;
      SQLTMP3 = SQLTMP3 || '(old.' || FNAME || ' <> new.' || FNAME || ')';
    end

    SQLTMP = iif(SQLTMP <> '', ascii_char(13), '') ||
             SQLTMP ||
             '  if ((updating) and (' || SQLTMP3 || ')) then' || ascii_char(13) ||
             '    for select IDPK from SPRI_FKCHECK(''' || :TNAME || ''', ''' || :PKNAME || ''', ' || SQLTMP2 || ')' || ascii_char(13) ||
             '        where IDPK > 0' || ascii_char(13) ||
             '          into :IDPK' || ascii_char(13) ||
             '    do' || ascii_char(13) ||
             '      exit;' || ascii_char(13);

    VARPKID = '  declare variable IDPK integer;' || ascii_char(13);
  end
  LOGKEYSUPDATE = SQLTMP;

  SQLTMP = '';
  SQLTMP2 = '';
  for select FIELDNAME, PK_NAME from SPDB_FIELDS_PK(:TABELA)
        into :FNAME, :PKNAME
  do
  begin
    if (SQLTMP <> '') then
    begin
      SQLTMP = SQLTMP || ' or ';
      SQLTMP2 = SQLTMP2 || ' || ''-'' || ';
    end
    SQLTMP = SQLTMP || '(old.' || FNAME || ' <> new.' || FNAME || ')';
    SQLTMP2 = SQLTMP2 || 'old.' || FNAME;
  end

  LOGKEYSUPDATE = '  if ((updating) and (' || SQLTMP || ')) then' || ascii_char(13) ||
                  '    insert into RI_TAB_UPDATEKEY(TABELA, CONSTRAINT_NAME, KEYVALUES) values (''' || :TABELA || ''', ''' || :PKNAME || ''', ' || SQLTMP2 || ');' || ascii_char(13) ||
                  LOGKEYSUPDATE;

  select first 1 trim(F.FIELDNAME)
    from SPDB_FIELDS(:TABELA) F
    where F.FIELDNAME = 'REP_INT_ACTIVE' and
          F.FIELDTYPE2 = 'INT'
      into :STMTACTIVE;

  if (STMTACTIVE = 'REP_INT_ACTIVE') then
  begin
    STMTACTIVE = '  if ((updating) and (coalesce(new.REP_INT_ACTIVE, 0) <> 1)) then' || ascii_char(13) ||
                 '    exit;' || ascii_char(13) || ascii_char(13);

    for select trim(F.FIELDNAME), trim(F.FIELDTYPE2)
        from SPDB_FIELDS(:TABELA) F
          inner join SPDB_IS_PK(:TABELA, F.FIELDNAME) P on 1 = 1
        where P.ISPK = 1
          into :FNAME, :FTYPE
        do
        begin    
          if (STMTACTIVEEND <> '') then
            STMTACTIVEEND = STMTACTIVEEND || ' || '' and ';

          if (FTYPE in ('STRING')) then
            STMTACTIVEEND = STMTACTIVEEND || FNAME || ' = '''''' || new.' || FNAME || ' || '''''''' ';
          else
            STMTACTIVEEND = STMTACTIVEEND || FNAME || ' = '' || cast(new.' || FNAME ||' as varchar(64)) ';
        end

    STMTACTIVEEND = ascii_char(13) ||
                    '  if ((not deleting) and (new.REP_INT_ACTIVE = 1)) then' || ascii_char(13) ||
                    '    execute statement ''update ' || :TABELA || ' set REP_INT_ACTIVE = null where ' || STMTACTIVEEND || ';' || ascii_char(13);
  end

  for select distinct SCHEMA_ID
      from RI_SCHEMA_TAB
      where TABELA = :TABELA
      order by TIPO_ID
        into :SCHEMA_ID
  do
  begin
    STMTCASE1 = '';
    STMTEMPTY = '';
    for select F.FIELDNAME, F.FIELDTYPE2, P.ISPK, iif(W.CAMPO = F.FIELDNAME, 1, 0), T.TIPO_ID
        from SPDB_FIELDS(:TABELA) F
          left join SPDB_IS_PK(:TABELA, F.FIELDNAME) P on 1 = 1
          left join RI_SCHEMA_TAB T on T.TABELA = :TABELA and
                T.SCHEMA_ID = :SCHEMA_ID
          left join RI_SCHEMA_TAB_WHERE W on W.TABELA_ID = T.ID and
                W.CAMPO = F.FIELDNAME
        where (F.FIELDNAME <> :FEMPNAME) and
              (F.FIELDNAME <> 'REP_INT_ACTIVE') and
              (P.ISPK = 1 or W.CAMPO = F.FIELDNAME)
          into :FNAME, :FTYPE, :FISPK, :FISWHERE, :TPID
    do
    begin
      SQLTMP = '';

      if (((TPID = 0) and
          (FISPK = 1)) or ((TPID = 1) and
          (FISWHERE = 1))) then
      begin
        if ((TPID = 1) and (FISWHERE = 1) and (FTYPE in ('STRING'))) then
          STMTEMPTY = STMTEMPTY || ' and (coalesce(iif(@ACAO, @P1.' || FNAME || ', @P2.' || FNAME || '),'''') <> '''')';

        SQLTMP = SQLTMP || '''@.' || FNAME || '=''';

        if (FTYPE in ('STRING')) then
          SQLTMP = SQLTMP || ''''' || iif(@ACAO, @P1.' || FNAME || ', @P2.' || FNAME || ') || ''''''''';
        else
          SQLTMP = SQLTMP || ' || cast(iif(@ACAO, @P1.' || FNAME || ', @P2.' || FNAME || ') as varchar(64))';
      end

      if ((TPID = 0) and
          (FISPK = 1) and
          (STMTCASE0 <> 'FIM')) then
      begin
        if (STMTCASE0 <> '') then
          STMTCASE0 = STMTCASE0 || ' || '' and '' || ';
        STMTCASE0 = STMTCASE0 || SQLTMP;
      end

      if ((TPID = 1) and
          (FISWHERE = 1)) then
      begin
        if (STMTCASE1 <> '') then
          STMTCASE1 = STMTCASE1 || ' || '' and '' || ';
        STMTCASE1 = STMTCASE1 || SQLTMP;
      end
    end

    if ((STMTCASE0 <> '') and
        (STMTCASE0 <> 'FIM')) then
    begin
      STMTCASEWHEN1 = STMTCASEWHEN1 || '           when (S.TIPO_ID = 0) then ' || STMTCASE0 || ascii_char(13);
      STMTCASEWHEN2 = STMTCASEWHEN2 || '           when (S.TIPO_ID = 0) then ' || STMTCASE0 || ascii_char(13);
      STMTCASE0 = 'FIM';
    end
    if (STMTCASE1 <> '') then
    begin
      STMTCASEWHEN1 = STMTCASEWHEN1 || '           when (S.TIPO_ID = 1) and (S.SCHEMA_ID = ' || cast(:SCHEMA_ID as varchar(32)) || ')' || STMTEMPTY || ' then ' || STMTCASE1 || ascii_char(13);
      STMTCASEWHEN2 = STMTCASEWHEN2 || '           when (S.TIPO_ID = 1) and (S.SCHEMA_ID = ' || cast(:SCHEMA_ID as varchar(32)) || ')' || STMTEMPTY || ' then ' || STMTCASE1 || ascii_char(13);
    end

    STMTCASEWHEN1 = replace(STMTCASEWHEN1, '@ACAO', 'deleting');
    STMTCASEWHEN1 = replace(STMTCASEWHEN1, '@P1', 'old');
    STMTCASEWHEN1 = replace(STMTCASEWHEN1, '@P2', 'new');

    STMTCASEWHEN2 = replace(STMTCASEWHEN2, '@ACAO', 'inserting');
    STMTCASEWHEN2 = replace(STMTCASEWHEN2, '@P1', 'new');
    STMTCASEWHEN2 = replace(STMTCASEWHEN2, '@P2', 'old');
  end

  KEYONLYEMP = 0;
  if ((STMTCASEWHEN1 = '') and (STMTCASEWHEN2 = '')) then
    select count(T.TABELA)
    from SPDB_TABLES T
      inner join SPDB_COUNT_PK(T.TABELA) CP on 1 = 1
      inner join SPDB_EMP_KEY(T.TABELA) EK on 1 = 1
    where EK.CAMPO_EMP <> '' and
          CP.COUNTPK = 1 and
          T.TABELA = :TABELA
      into :KEYONLYEMP;

  STMTTR = 'CREATE OR ALTER TRIGGER @TRNAME FOR @TBNAME' || ascii_char(13) ||
           'ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 999' || ascii_char(13) ||
           'as' || ascii_char(13) ||
           iif(KEYONLYEMP = 1, '',
           '  declare variable CONDICAO_O varchar(255);' || ascii_char(13) ||
           '  declare variable CONDICAO_D varchar(255);' || ascii_char(13)) ||
           '@VARPKID@' ||
           'begin' || ascii_char(13) ||
           '@LOGKEYSUPDATE@' || ascii_char(13) ||
           '@STMTACTIVE@' ||
           iif(KEYONLYEMP = 1,
           '  execute procedure SPRI_EXEC(''@TBNAME'', '''', '''', iif(deleting, old.@FEMPNAME, new.@FEMPNAME), iif(deleting, 1, 0));',
           '  select' || ascii_char(13) ||
           '         case' || ascii_char(13) ||
           '@CASEWHEN1' ||
           '           else ''''' || ascii_char(13) ||
           '         end,' || ascii_char(13) ||
           '         case' || ascii_char(13) ||
           '@CASEWHEN2' ||
           '           else ''''' || ascii_char(13) ||
           '         end' || ascii_char(13) ||
           '  from SPRI_SCHEMA(''@TBNAME'', iif(deleting, old.@FEMPNAME, new.@FEMPNAME)) S' || ascii_char(13) ||
           '    into :CONDICAO_O, :CONDICAO_D;' || ascii_char(13) ||
           '' || ascii_char(13) ||
           '  if ((updating) and (new.@FEMPNAME <> old.@FEMPNAME)) then' || ascii_char(13) ||
           '    CONDICAO_O = '''';' || ascii_char(13) ||
           '' || ascii_char(13) ||
           '  if (CONDICAO_O <> '''') then' || ascii_char(13) ||
           '    execute procedure SPRI_EXEC(''@TBNAME'', :CONDICAO_O, :CONDICAO_D, iif(deleting, old.@FEMPNAME, new.@FEMPNAME), iif(deleting, 1, 0));') || ascii_char(13) ||
           '@STMTACTIVEEND@' ||
           'end';

  STMTTR = replace(STMTTR, '@TBNAME', :TABELA);
  STMTTR = replace(STMTTR, '@TRNAME', :TRNAME);
  STMTTR = replace(STMTTR, '@VARPKID@', :VARPKID);
  STMTTR = replace(STMTTR, '@LOGKEYSUPDATE@', :LOGKEYSUPDATE);
  STMTTR = replace(STMTTR, '@STMTACTIVE@', :STMTACTIVE);
  STMTTR = replace(STMTTR, '@FEMPNAME', :FEMPNAME);
  STMTTR = replace(STMTTR, '@CASEWHEN1', :STMTCASEWHEN1);
  STMTTR = replace(STMTTR, '@CASEWHEN2', :STMTCASEWHEN2);
  STMTTR = replace(STMTTR, '@STMTACTIVEEND@', :STMTACTIVEEND);

  insert into RI_TMP_SQL (SQLEXEC)
  values (:STMTTR);

  execute statement STMTTR;

  if (:TABELA in ('PRODUTOS', 'COD_GRADE_PROD') ) then
    execute procedure SPRI_MAKE_OBJ_EST(:TABELA, :SCH_TB_ID);
  else if (:TABELA in ('CONTROLES') ) then
    execute procedure SPRI_MAKE_OBJ_CTRL(:TABELA, :SCH_TB_ID);
end
 
 ^

ALTER PROCEDURE SPRI_MAKE_OBJ_CTRL (TABELA VARCHAR(31) CHARACTER SET NONE,
TABELA_ID INTEGER)
AS 
declare variable STMT blob sub_type 1 segment size 256;
begin
  if (TABELA = 'CONTROLES') then
  begin
    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'SALDO_ANT_CTRL') matching (TABELA_ID, CAMPO);
    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'SALDO_AT_CTRL') matching (TABELA_ID, CAMPO);
    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'SOBRA_CTRL') matching (TABELA_ID, CAMPO);

    STMT = 'create or alter trigger TI_RI_SALDO_CTRL for CONTROLES' || ascii_char(13) ||
           'active before update position 1' || ascii_char(13) ||
           'as' || ascii_char(13) ||
           '  declare variable CONTEXT_VAR char(36);' || ascii_char(13) ||
           '  declare variable CONTEXT_STAT varchar(255);' || ascii_char(13) ||
           'begin' || ascii_char(13) ||
           '  select GUIDT' || ascii_char(13) ||
           '  from RI_TAB' || ascii_char(13) ||
           '  where TABELA = ''CONTROLES'' ' || ascii_char(13) ||
           '    into :CONTEXT_VAR;' || ascii_char(13) ||
           '' || ascii_char(13) ||
           '  select RDB$GET_CONTEXT(''USER_TRANSACTION'', :CONTEXT_VAR)' || ascii_char(13) ||
           '  from RDB$DATABASE' || ascii_char(13) ||
           '    into :CONTEXT_STAT;' || ascii_char(13) ||
           '' || ascii_char(13) ||
           '  if (coalesce(CONTEXT_STAT, '''') <> '''') then' || ascii_char(13) ||
           '  begin' || ascii_char(13) ||
           '    new.SALDO_ANT_CTRL = old.SALDO_ANT_CTRL;' || ascii_char(13) ||
           '    new.SALDO_AT_CTRL = old.SALDO_AT_CTRL;' || ascii_char(13) ||
           '    new.SOBRA_CTRL = old.SOBRA_CTRL;' || ascii_char(13) ||
           '  end' || ascii_char(13) ||
           'end';
  end
  else
    STMT = '';

  if (coalesce(STMT, '') <> '') then
  begin
    insert into RI_TMP_SQL (SQLEXEC)
    values (:STMT);

    execute statement STMT;
  end
end ^

