    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'CLPRECO') matching (TABELA_ID, CAMPO);
    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'CLPOP') matching (TABELA_ID, CAMPO);
    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'CLQTV') matching (TABELA_ID, CAMPO);
    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'CLFRV') matching (TABELA_ID, CAMPO);
    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'CLATL') matching (TABELA_ID, CAMPO);
