    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'QTDDIAS_EXCESSO') matching (TABELA_ID, CAMPO);
    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'EST_SEGURANCA') matching (TABELA_ID, CAMPO);
    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'FREQ_PEDIDO') matching (TABELA_ID, CAMPO);
