    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'TEMPO_ENTREGASUG') matching (TABELA_ID, CAMPO);
    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'COD_INF') matching (TABELA_ID, CAMPO);
    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'COD_PRODUCAO') matching (TABELA_ID, CAMPO);
