    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'DT_ULT_E_PRODUCAO') matching (TABELA_ID, CAMPO);

    STMT = 'create or alter trigger TI_RI_EST_PROD for PRODUTOS' || ascii_char(13) ||
           'active before update position 1' || ascii_char(13) ||
           'as' || ascii_char(13) ||
           '  declare variable CONTEXT_VAR char(36);' || ascii_char(13) ||
           '  declare variable CONTEXT_STAT varchar(255);' || ascii_char(13) ||
           'begin' || ascii_char(13) ||
           '  select GUIDT' || ascii_char(13) ||
           '  from RI_TAB' || ascii_char(13) ||
           '  where TABELA = ''PRODUTOS'' ' || ascii_char(13) ||
           '    into :CONTEXT_VAR;' || ascii_char(13) ||
           '' || ascii_char(13) ||
           '  select RDB$GET_CONTEXT(''USER_TRANSACTION'', :CONTEXT_VAR)' || ascii_char(13) ||
           '  from RDB$DATABASE' || ascii_char(13) ||
           '    into :CONTEXT_STAT;' || ascii_char(13) ||
           '' || ascii_char(13) ||
           '  if (coalesce(CONTEXT_STAT, '''') <> '''') then' || ascii_char(13) ||
           '  begin' || ascii_char(13) ||
           '    new.EST_F = old.EST_F;' || ascii_char(13) ||
           '    new.PREC_CUS_PROD = old.PREC_CUS_PROD;' || ascii_char(13) ||
           '    new.PREC_CUSM_PROD = old.PREC_CUSM_PROD;' || ascii_char(13) ||
           '    new.PREC_CUSR_PROD = old.PREC_CUSR_PROD;' || ascii_char(13) ||
           '    new.PREC_CUSMR_PROD = old.PREC_CUSMR_PROD;' || ascii_char(13) ||
           '    new.PREC_CUS_MNF = old.PREC_CUS_MNF;' || ascii_char(13) ||
           '    new.PREC_CUSR_MNF = old.PREC_CUSR_MNF;' || ascii_char(13) ||
           '    new.PREC_REP_PROD = old.PREC_REP_PROD;' || ascii_char(13) ||
           '    new.DATA_ULT_COMPRA = old.DATA_ULT_COMPRA;' || ascii_char(13) ||
           '    new.NUM_NF_REC = old.NUM_NF_REC;' || ascii_char(13) ||
           '    new.VL_ULT_COMPRA = old.VL_ULT_COMPRA;' || ascii_char(13) ||
           '    new.PERC_FRETE_PROD = old.PERC_FRETE_PROD;' || ascii_char(13) ||
           '    new.ICMANT_SUB = old.ICMANT_SUB;' || ascii_char(13) ||
           '    new.BASEICMANT_SUB = old.BASEICMANT_SUB;' || ascii_char(13) ||
           '    new.LOCACAO_PROD = old.LOCACAO_PROD;' || ascii_char(13) ||
           '    new.LOCACAO_PROD_1 = old.LOCACAO_PROD_1;' || ascii_char(13) ||
           '    new.COMISSAO_PROD = old.COMISSAO_PROD;' || ascii_char(13) ||
           '    new.COMISSAO_PROD_GER = old.COMISSAO_PROD_GER;' || ascii_char(13) ||
           '    new.DT_ULT_VND = old.DT_ULT_VND;' || ascii_char(13) ||
           '    new.DT_ULT_VNDA = old.DT_ULT_VNDA;' || ascii_char(13) ||
           '    new.CLASSE_PROD = old.CLASSE_PROD;' || ascii_char(13) ||
           '    new.CLINV = old.CLINV;' || ascii_char(13) ||
           '    new.CLPRECO = old.CLPRECO;' || ascii_char(13) ||
