           '    new.CLFRV = old.CLFRV;' || ascii_char(13) ||
           '    new.CLATL = old.CLATL;' || ascii_char(13) ||
           '    new.DAT_CAD_PROD = old.DAT_CAD_PROD;' || ascii_char(13) ||
           '    new.VALORGE = old.VALORGE;' || ascii_char(13) ||
           '    new.VALORPME = old.VALORPME;' || ascii_char(13) ||
           '    new.QTDPROD_EXCESSO = old.QTDPROD_EXCESSO;' || ascii_char(13) ||
           '    new.QTDDIAS_EXCESSO = old.QTDDIAS_EXCESSO;' || ascii_char(13) ||
           '    new.EST_SEGURANCA = old.EST_SEGURANCA;' || ascii_char(13) ||
           '    new.FREQ_PEDIDO = old.FREQ_PEDIDO;' || ascii_char(13) ||
           '    new.DMD = old.DMD;' || ascii_char(13) ||
           '    new.TCUTILIZADO = old.TCUTILIZADO;' || ascii_char(13) ||
           '    new.QTD_ETIQUETAS = old.QTD_ETIQUETAS;' || ascii_char(13) ||
           '    new.MD5 = old.MD5;' || ascii_char(13) ||
           '    new.TEMPO_ENTREGASUG = old.TEMPO_ENTREGASUG;' || ascii_char(13) ||
           '    new.COD_INF = old.COD_INF;' || ascii_char(13) ||
           '    new.COD_PRODUCAO = old.COD_PRODUCAO;' || ascii_char(13) ||
           '    new.DT_ULT_S_PRODUCAO = old.DT_ULT_S_PRODUCAO;' || ascii_char(13) ||
           '    new.DT_ULT_E_PRODUCAO = old.DT_ULT_E_PRODUCAO;' || ascii_char(13) ||
           '  end' || ascii_char(13) ||
           'end';
  end
  else
  if (TABELA = 'COD_GRADE_PROD') then  
  begin
    update or insert into RI_SCHEMA_TAB_EXCE (TABELA_ID, CAMPO) values (:TABELA_ID, 'QTDE') matching (TABELA_ID, CAMPO);

    STMT = 'create or alter trigger TI_RI_EST_GRADE for COD_GRADE_PROD' || ascii_char(13) ||
           'active before update position 1' || ascii_char(13) ||
           'as' || ascii_char(13) ||
           '  declare variable CONTEXT_VAR char(36);' || ascii_char(13) ||
           '  declare variable CONTEXT_STAT varchar(255);' || ascii_char(13) ||
           'begin' || ascii_char(13) ||
           '  select GUIDT' || ascii_char(13) ||
           '  from RI_TAB' || ascii_char(13) ||
           '  where TABELA = ''COD_GRADE_PROD'' ' || ascii_char(13) ||
           '    into :CONTEXT_VAR;' || ascii_char(13) ||
           '' || ascii_char(13) ||
           '  select RDB$GET_CONTEXT(''USER_TRANSACTION'', :CONTEXT_VAR)' || ascii_char(13) ||
           '  from RDB$DATABASE' || ascii_char(13) ||
           '    into :CONTEXT_STAT;' || ascii_char(13) ||
           '' || ascii_char(13) ||
           '  if (coalesce(CONTEXT_STAT, '''') <> '''') then' || ascii_char(13) ||
           '  begin' || ascii_char(13) ||
           '    new.QTDE = old.QTDE;' || ascii_char(13) ||
           '  end' || ascii_char(13) ||
           'end';   
  end
  else
    STMT = '';

  if (coalesce(STMT, '') <> '') then
  begin
    insert into RI_TMP_SQL (SQLEXEC)
    values (:STMT);

    execute statement STMT;
  end
end ^

ALTER PROCEDURE SPRI_SCHEMA (TABELA VARCHAR(31) CHARACTER SET NONE,
IDORIGEM INTEGER)
RETURNS (SCHEMA_ID INTEGER,
TIPO_ID SMALLINT)
AS 
begin
  select T.SCHEMA_ID, T.TIPO_ID
  from RI_SCHEMA_TAB T
    inner join RI_SCHEMA_EMP E on E.SCHEMA_ID = T.SCHEMA_ID
  where T.TABELA = :TABELA and
        E.EMPRESA_ID = :IDORIGEM
    into :SCHEMA_ID, :TIPO_ID;

  suspend;
end ^

