ALTER PROCEDURE SP_NF_PEND_IMPORTXML (DATAINV TIMESTAMP,
CODEMPRESA INTEGER,
USADHEMI SMALLINT)
RETURNS (COD_NF INTEGER)
AS 
  declare variable GRU integer;
  declare variable COD varchar(14);
  declare variable QTMP T_VL_TODOS;
  declare variable QLOOP T_VL_TODOS;
  declare variable QEST T_VL_TODOS;
  declare variable IDDOC integer;
begin

  for select I.GRUPO_PROD, trim(I.COD_PROD), I.QUANTIDADE
      from VW_INV_TIPO74 I
      where I.DATA_INV = :DATAINV and
            I.COD_EMPRESA = :CODEMPRESA and
            I.CODIGO_POSSE <> 2
        into :GRU, :COD, :QEST
  do
  begin
    QEST = coalesce(QEST, 0);
    QLOOP = QEST;

    if (QLOOP > 0) then
    begin

      -- OBTENDO AS ULTIMAS ENTRADAS
      for execute statement 'select NFI.QUANTIDADE, nfi.cod_nf
          from NOTAFISCAL NF
            inner join NOTAFISCAL_ITEM NFI on NFI.COD_NF = NF.COD_NF and
                  NFI.COD_EMPRESA = NF.COD_EMPRESA
          where NF.NATUREZA_NF = ''E'' and
                NF.TIPO_NF = ''P'' and
                NF.STATUS = ''Fechada'' and
                coalesce(NF.DA, '''') <> ''S'' and ' || iif(:USADHEMI = 1, 'NF.DATA_CONTABIL', 'NF.DATA_LANC') || ' <= ''' || :DATAINV || ''' and
                coalesce(NFI.ALTERA_ESTOQUE_CFOP, ''S'') <> ''N'' and
                NFI.GRUPO_PROD = ' || :GRU || ' and
                NFI.COD_PROD = ''' || :COD || ''' and
                NFI.COD_EMPRESA = ' || :CODEMPRESA || '
          order by ' || iif(:USADHEMI = 1, 'NF.DATA_CONTABIL', 'NF.DATA_LANC') || ' DESC, NFI.NITEM DESC'
              into :QTMP, :IDDOC
      do
      begin
        QTMP = coalesce(QTMP, 0);

        if (QTMP > QLOOP) then
        begin
          QLOOP = 0;
        end
        else
        begin
          QLOOP = QLOOP - QTMP;
        end

        for select distinct NF.COD_NF
            from NOTAFISCAL NF
              inner join NOTAFISCAL_ITEM NFI on NFI.COD_NF = NF.COD_NF and
                    NFI.COD_EMPRESA = NF.COD_EMPRESA
            where NF.COD_NF = :IDDOC and
                  NF.COD_EMPRESA = :CODEMPRESA and
                  NF.IMPORT_XML is null and
                  NF.MODELO_NF = '55' and
                  coalesce(NF.PATH_XML_IMPORT, '') <> '' and
                  NFI.IMPORT_XML = 'S'
              into :COD_NF
        do
        begin
          suspend;
        end

        if (QLOOP <= 0) then
          break;

      end
    end -- if QLOOP > 0

  end
end ^

ALTER PROCEDURE SP_OPF_ICM_TABTRIBUTACAO (IDPESQUISA INTEGER = null)
