ALTER PROCEDURE SP_OS_GARANTIA (PCAMPOPESQUISA VARCHAR(10) CHARACTER SET NONE)
RETURNS (RETORNO CHAR(1) CHARACTER SET NONE)
AS 
declare variable VCOMGARANTIA char(1);
begin
  select tipo_vendas.comgarantia from tipo_vendas
      where tipo = 'OS' and tipo_os = :pcampopesquisa and ativo = 1
      into :vcomgarantia;
  retorno = 'N';
  if ( ltrim(rtrim(vcomgarantia))  <> '' ) then
    retorno = ltrim(rtrim(vcomgarantia));

  suspend;
end ^

ALTER PROCEDURE SP_PEDVENDA_PLANO_RATEAR (NPED INTEGER,
TIPO CHAR(3) CHARACTER SET NONE,
COD_EMPRESA INTEGER,
VPLANO DOUBLE PRECISION)
RETURNS (RESULT SMALLINT,
MSG VARCHAR(128) CHARACTER SET NONE)
AS 
  declare variable TOTAL double precision;
  declare variable TOTAL_PROD double precision;
  declare variable TOTAL_SERV double precision;
  declare variable ACRESC_PLANO double precision;
  declare variable PLANO_CALCULADO char(1);
  declare variable NITEM integer;
  declare variable GRUPO_PROD integer;
  declare variable COD_PROD char(6);
  declare variable COD_GRADE integer;
  declare variable CODIGO_NOP double precision;
  declare variable COD_SERVICO integer;
  declare variable PED integer;
begin
  RESULT = 1;
  MSG = '';

  if (VPLANO <= 0) then
  begin
    RESULT = 0;
    MSG = 'Sem valor para o plano, sem necessidade de calcular';
    suspend;
    exit;
  end
  
  if ((NPED = 0) or (trim(TIPO) not in ('REQ', 'OS')))  then
  begin                                                         
    RESULT = 0;
    MSG = 'Parametros invalidos';
    suspend;
    exit;
  end

  for select PV.NPED from PEDVENDA PV
    where PV.NPED = :NPED and PV.TIPO = :TIPO and PV.COD_EMPRESA = :COD_EMPRESA
    into :PED
  do
  begin
    if (NPED <> PED) then -- nao encontrado o pedido passado como parametro   
    begin                                   
      RESULT = 0;
      MSG = 'Pedido ou OS nao encontrado';
      suspend;
      exit;
    end
  end

  --obtendo o total geral produtos e servicos
  for select C.PLANO_CALCULADO, C.STATUS_PED, sum(C.TOTAL) TOTAL
      from (select PV.PLANO_CALCULADO, PV.STATUS_PED, sum(coalesce(PVP.VLTOT_PED_ITEM, 0)) TOTAL
            from PEDVENDA PV
              inner join PEDVENDA_PROD PVP on PVP.NPED = PV.NPED and
                    PVP.TIPO = PV.TIPO and
                    PVP.COD_EMPRESA = PV.COD_EMPRESA
            where PV.NPED = :NPED and
                  PV.TIPO = :TIPO and
                  PV.COD_EMPRESA = :COD_EMPRESA and
                  coalesce(PVP.STATUS, '') = ''
            group by 1,2
            union all
            select PV.PLANO_CALCULADO, PV.STATUS_PED, sum(coalesce(PVS.VALOR_TOT_SERV, 0))
            from PEDVENDA PV
              inner join PEDVENDA_SERV PVS on PVS.NPED = PV.NPED and
                    PVS.TIPO = PV.TIPO and
                    PVS.COD_EMPRESA = PV.COD_EMPRESA
            where PV.NPED = :NPED and
                  PV.TIPO = :TIPO and
                  PV.COD_EMPRESA = :COD_EMPRESA and
                  coalesce(PVS.STATUS, '') = ''
            group by 1, 2) as C
      group by 1,2
        into :PLANO_CALCULADO, :MSG, :TOTAL
  do
  begin
    if (coalesce(MSG, '') <> '') then
    begin
      RESULT = 0;
      MSG = 'Status igual a ' || MSG;
      suspend;
      exit;
    end
    
    if (coalesce(PLANO_CALCULADO, '') = 'S') then
    begin
      RESULT = 0;
      MSG = 'Plano j?? rateado entre os itens, tente novamente';
      suspend;
      exit;
    end
  end

  --setando no produto o rateio do acrecimo do plano
  update PEDVENDA_PROD
  set NAT_DESCACRES = 'VALOR',
      VALOR_DESCACRES = iif(trim(TP_DESCACRES) = 'DESCONTO', DESC_ITEM, ACRESC_ITEM),
      ACRESC_PLANO = round(:VPLANO / :TOTAL * VLTOT_PED_ITEM, 2)
  where NPED = :NPED and
        TIPO = :TIPO and
        COD_EMPRESA = :COD_EMPRESA and
        coalesce(STATUS, '') = '';

  --setando no servico o rateio do acrecimo do plano
  update PEDVENDA_SERV
  set ACRESC_PLANO = round(:VPLANO / :TOTAL * VALOR_TOT_SERV, 2)
  where NPED = :NPED and
        TIPO = :TIPO and
        COD_EMPRESA = :COD_EMPRESA and
        coalesce(STATUS, '') = '';

  -- somando o rateio aplicado para validar com o valor do parametro vplano
  for select sum(C.TOTAL_PROD) TOTAL_PROD, sum(C.TOTAL_SERV) TOTAL_SERV, sum(C.ACRESC_PLANO) ACRESC_PLANO
      from (select sum(coalesce(PVP.VLTOT_PED_ITEM, 0)) TOTAL_PROD, 0.0 TOTAL_SERV, sum(PVP.ACRESC_PLANO) ACRESC_PLANO
            from PEDVENDA PV
              inner join PEDVENDA_PROD PVP on PVP.NPED = PV.NPED and
                    PVP.TIPO = PV.TIPO and
                    PVP.COD_EMPRESA = PV.COD_EMPRESA
            where PV.NPED = :NPED and
                  PV.TIPO = :TIPO and
                  PV.COD_EMPRESA = :COD_EMPRESA and
                  coalesce(PVP.STATUS, '') = ''
            union all
            select 0.0 TOTAL_PROD, sum(coalesce(PVS.VALOR_TOT_SERV, 0)) TOTAL_SERV, sum(PVS.ACRESC_PLANO) ACRESC_PLANO
            from PEDVENDA PV
              inner join PEDVENDA_SERV PVS on PVS.NPED = PV.NPED and
                    PVS.TIPO = PV.TIPO and
                    PVS.COD_EMPRESA = PV.COD_EMPRESA
            where PV.NPED = :NPED and
                  PV.TIPO = :TIPO and
                  PV.COD_EMPRESA = :COD_EMPRESA and
                  coalesce(PVS.STATUS, '') = ''

      ) as C
        into :TOTAL_PROD, :TOTAL_SERV, :ACRESC_PLANO
  do
  begin
    -- valor diferente entao vamos ajustar para o primeiro item com maior valor seja servico ou produto
    if (round(VPLANO, 2) <> round(ACRESC_PLANO, 2)) then
    begin
      for select first 1 C.NITEM, C.GRUPO_PROD, C.COD_PROD, C.COD_GRADE, C.CODIGO_NOP, C.COD_SERVICO
          from (select first 1 PVP.VLTOT_PED_ITEM TOTAL, PVP.NITEM, PVP.GRUPO_PROD, PVP.COD_PROD, PVP.COD_GRADE,
                               PVP.CODIGO_NOP, null COD_SERVICO
                from PEDVENDA PV
                  inner join PEDVENDA_PROD PVP on PVP.NPED = PV.NPED and
                        PVP.TIPO = PV.TIPO and
                        PVP.COD_EMPRESA = PV.COD_EMPRESA
                where PV.NPED = :NPED and
                      PV.TIPO = :TIPO and
                      PV.COD_EMPRESA = :COD_EMPRESA and
                      coalesce(PVP.STATUS, '') = ''
                union all
                select first 1 PVS.VALOR_TOT_SERV TOTAL, PVS.NITEM, 0 GRUPO_PROD, '' COD_PROD, 0 COD_GRADE,
                               PVS.CODIGO_NOP, PVS.COD_SERVICO
                from PEDVENDA PV
                  inner join PEDVENDA_SERV PVS on PVS.NPED = PV.NPED and
                        PVS.TIPO = PV.TIPO and
                        PVS.COD_EMPRESA = PV.COD_EMPRESA
                where PV.NPED = :NPED and
                      PV.TIPO = :TIPO and
                      PV.COD_EMPRESA = :COD_EMPRESA and
                      coalesce(PVS.STATUS, '') = ''
                order by 1 desc) as C
            into :NITEM, :GRUPO_PROD, :COD_PROD, :COD_GRADE, :CODIGO_NOP, :COD_SERVICO
      do
      begin
        if (COD_SERVICO is null) then
          update PEDVENDA_PROD
          set ACRESC_PLANO = ACRESC_PLANO + (:VPLANO - :ACRESC_PLANO)
          where NPED = :NPED and
                TIPO = :TIPO and
                COD_EMPRESA = :COD_EMPRESA and
                NITEM = :NITEM and
                GRUPO_PROD = :GRUPO_PROD and
                COD_PROD = :COD_PROD and
                COD_GRADE = :COD_GRADE and
                CODIGO_NOP = :CODIGO_NOP;

        update PEDVENDA_SERV
        set ACRESC_PLANO = ACRESC_PLANO + (:VPLANO - :ACRESC_PLANO)
        where NPED = :NPED and
              TIPO = :TIPO and
              COD_EMPRESA = :COD_EMPRESA and
              NITEM = :NITEM and
              COD_SERVICO = :COD_SERVICO and
              CODIGO_NOP = :CODIGO_NOP;
      end
    end
  end

  -- atualizando o total dos produtos com o valor do plano
  update PEDVENDA_PROD PVP
  set --PVP.VLUN_PED_ITEM = round((PVP.VLTOT_PED_ITEM + coalesce(PVP.ACRESC_PLANO, 0)) / PVP.QUANT_PED_ITEM, 4),
      --PVP.VLTOT_PED_ITEM = PVP.VLTOT_PED_ITEM + coalesce(PVP.ACRESC_PLANO, 0)
      PVP.ACRESC_ITEM = PVP.ACRESC_ITEM + PVP.ACRESC_PLANO
  where PVP.NPED = :NPED and
        PVP.TIPO = :TIPO and
        PVP.COD_EMPRESA = :COD_EMPRESA and
        coalesce(STATUS, '') = '';

  -- atualizando o total dos servicos com o valor do plano
  update PEDVENDA_SERV PVS
  set -- PVS.VALOR_UN_SERV = round((PVS.VALOR_TOT_SERV + coalesce(PVS.ACRESC_PLANO, 0)) / PVS.QUANT_SERV_PED, 4),
      -- PVS.VALOR_TOT_SERV = PVS.VALOR_TOT_SERV + coalesce(PVS.ACRESC_PLANO, 0)
      PVS.ACRESC_ITEM = PVS.ACRESC_ITEM + PVS.ACRESC_PLANO
  where PVS.NPED = :NPED and
        PVS.TIPO = :TIPO and
        PVS.COD_EMPRESA = :COD_EMPRESA and
        coalesce(STATUS, '') = '';

  -- finalizando somamos o total prod e total serv para atualizar no cabecalho
  /*
  for select sum(C.TOTAL_PROD) TOTAL_PROD, sum(C.TOTAL_SERV) TOTAL_SERV
      from (select sum(coalesce(PVP.VLTOT_PED_ITEM, 0)) TOTAL_PROD, 0.0 TOTAL_SERV
            from PEDVENDA PV
              inner join PEDVENDA_PROD PVP on PVP.NPED = PV.NPED and
                    PVP.TIPO = PV.TIPO and
                    PVP.COD_EMPRESA = PV.COD_EMPRESA
            where PV.NPED = :NPED and
                  PV.TIPO = :TIPO and
                  PV.COD_EMPRESA = :COD_EMPRESA and
                  coalesce(PVP.STATUS, '') = ''
            union all
            select 0.0 TOTAL_PROD, sum(coalesce(PVS.VALOR_TOT_SERV, 0)) TOTAL_SERV
            from PEDVENDA PV
              inner join PEDVENDA_SERV PVS on PVS.NPED = PV.NPED and
                    PVS.TIPO = PV.TIPO and
                    PVS.COD_EMPRESA = PV.COD_EMPRESA
            where PV.NPED = :NPED and
                  PV.TIPO = :TIPO and
                  PV.COD_EMPRESA = :COD_EMPRESA and
                  coalesce(PVS.STATUS, '') = ''

      ) as C
        into :TOTAL_PROD, :TOTAL_SERV
  do    
  */
  begin
    -- atualizando o valor total do pedido
    update PEDVENDA
    set --TOT_PROD = :TOTAL_PROD,
        --TOT_SERV = :TOTAL_SERV,
        PLANO_CALCULADO = 'S'
    where NPED = :NPED and
          TIPO = :TIPO and
          COD_EMPRESA = :COD_EMPRESA;
  end

  MSG = 'OK';

  suspend;
end
 
 ^

ALTER PROCEDURE SP_PEDVENDA_PLANO_REVERTER (NPED INTEGER,
TIPO CHAR(3) CHARACTER SET NONE,
COD_EMPRESA INTEGER)
RETURNS (RESULT SMALLINT,
MSG VARCHAR(128) CHARACTER SET NONE)
AS 
  declare variable TOTAL_PROD double precision;
  declare variable TOTAL_SERV double precision;
  declare variable ACRESC_PLANO double precision;
  declare variable PED integer;
begin
  RESULT = 1;
  MSG = 'SEM ALTERACAO';

  if ((NPED = 0) or (trim(TIPO) not in ('REQ', 'OS')))  then
  begin
    suspend;
    exit;
  end

  --obtendo o total geral produtos e servicos
  for select C.PLANO_CALCULADO, sum(C.ACRESC_PLANO) TOTAL
      from (select PV.PLANO_CALCULADO, sum(coalesce(PVP.ACRESC_PLANO, 0)) ACRESC_PLANO
            from PEDVENDA PV
              inner join PEDVENDA_PROD PVP on PVP.NPED = PV.NPED and
                    PVP.TIPO = PV.TIPO and
                    PVP.COD_EMPRESA = PV.COD_EMPRESA
            where PV.NPED = :NPED and
                  PV.TIPO = :TIPO and
                  PV.COD_EMPRESA = :COD_EMPRESA and
                  coalesce(PVP.STATUS, '') = ''
            group by 1
            union all
            select PV.PLANO_CALCULADO, sum(coalesce(PVS.ACRESC_PLANO, 0)) ACRESC_PLANO
            from PEDVENDA PV
              inner join PEDVENDA_SERV PVS on PVS.NPED = PV.NPED and
                    PVS.TIPO = PV.TIPO and
                    PVS.COD_EMPRESA = PV.COD_EMPRESA
            where PV.NPED = :NPED and
                  PV.TIPO = :TIPO and
                  PV.COD_EMPRESA = :COD_EMPRESA and
                  coalesce(PVS.STATUS, '') = ''
            group by 1) as C
      group by 1
        into :MSG, :ACRESC_PLANO
  do
  begin
    if (coalesce(:MSG, '') <> 'S') then -- nao tem rateio feito anteriormente
    begin
      suspend;
      exit;
    end
  end

  for select PV.NPED from PEDVENDA PV
    where PV.NPED = :NPED and PV.TIPO = :TIPO and PV.COD_EMPRESA = :COD_EMPRESA
    into :PED
  do
  begin
    if (NPED <> PED) then -- nao encontrado o pedido passado como parametro   
    begin
      suspend;
      exit;
    end
  end

  if (coalesce(acresc_plano, 0) > 0) then
  begin
    -- atualizando o total dos produtos com o valor do plano
    update PEDVENDA_PROD PVP
    set --PVP.VLUN_PED_ITEM = round((PVP.VLTOT_PED_ITEM - coalesce(PVP.ACRESC_PLANO, 0)) / PVP.QUANT_PED_ITEM, 4),
        --PVP.VLTOT_PED_ITEM = PVP.VLTOT_PED_ITEM - coalesce(PVP.ACRESC_PLANO, 0),
        PVP.ACRESC_ITEM = PVP.ACRESC_ITEM - PVP.ACRESC_PLANO,
        PVP.ACRESC_PLANO = 0
    where PVP.NPED = :NPED and
          PVP.TIPO = :TIPO and
          PVP.COD_EMPRESA = :COD_EMPRESA and
          coalesce(STATUS, '') = '';
  
    -- atualizando o total dos servicos com o valor do plano
    update PEDVENDA_SERV PVS
    set --PVS.VALOR_UN_SERV = round((PVS.VALOR_TOT_SERV - coalesce(PVS.ACRESC_PLANO, 0)) / PVS.QUANT_SERV_PED, 4),
        --PVS.VALOR_TOT_SERV = PVS.VALOR_TOT_SERV - coalesce(PVS.ACRESC_PLANO, 0),
        PVS.ACRESC_ITEM = PVS.ACRESC_ITEM - PVS.ACRESC_PLANO,
        PVS.ACRESC_PLANO = 0
    where PVS.NPED = :NPED and
          PVS.TIPO = :TIPO and
          PVS.COD_EMPRESA = :COD_EMPRESA and
          coalesce(STATUS, '') = '';
  end

  -- finalizando somamos o total prod e total serv para atualizar no cabecalho
  /*
  for select sum(C.TOTAL_PROD) TOTAL_PROD, sum(C.TOTAL_SERV) TOTAL_SERV
      from (select sum(coalesce(PVP.VLTOT_PED_ITEM, 0)) TOTAL_PROD, 0.0 TOTAL_SERV
            from PEDVENDA PV
              inner join PEDVENDA_PROD PVP on PVP.NPED = PV.NPED and
                    PVP.TIPO = PV.TIPO and
                    PVP.COD_EMPRESA = PV.COD_EMPRESA
            where PV.NPED = :NPED and
                  PV.TIPO = :TIPO and
                  PV.COD_EMPRESA = :COD_EMPRESA and
                  coalesce(PVP.STATUS, '') = ''
            union all
            select 0.0 TOTAL_PROD, sum(coalesce(PVS.VALOR_TOT_SERV, 0)) TOTAL_SERV
            from PEDVENDA PV
              inner join PEDVENDA_SERV PVS on PVS.NPED = PV.NPED and
                    PVS.TIPO = PV.TIPO and
                    PVS.COD_EMPRESA = PV.COD_EMPRESA
            where PV.NPED = :NPED and
                  PV.TIPO = :TIPO and
                  PV.COD_EMPRESA = :COD_EMPRESA and
                  coalesce(PVS.STATUS, '') = ''

      ) as C
        into :TOTAL_PROD, :TOTAL_SERV
  do
  */
  begin
    -- atualizando o valor total do pedido
    update PEDVENDA
    set --TOT_PROD = :TOTAL_PROD,
        --TOT_SERV = :TOTAL_SERV,
        PLANO_CALCULADO = 'N'
    where NPED = :NPED and
          TIPO = :TIPO and
          COD_EMPRESA = :COD_EMPRESA;
  end

  MSG = 'REVERTIDO';

  suspend;
end ^

ALTER PROCEDURE SP_PRODUCAO_AUT (PNPED INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (RESULT VARCHAR(100) CHARACTER SET NONE)
AS 
declare variable VERRO char(1);
declare variable VCOD_PRODUCAO integer;
declare variable VGRUPO_PROD_A integer;
declare variable VCOD_PROD_A char(6);
declare variable VEST_F_A double precision;
declare variable VESTOQUE_DISP_A double precision;
declare variable VNITEM_A integer;
declare variable VCOD_GRADE_A integer;
declare variable VCODIGO_NOP_A double precision;
declare variable VNUM_FAB_PROD_A varchar(20);
declare variable VDESCR_PROD_A varchar(75);
declare variable VUNIDADE_A varchar(3);
declare variable VQUANT_PED_ITEM_A double precision;
declare variable VPREC_CUS_PROD_A double precision;
declare variable VPREC_CUSM_PROD_A double precision;
declare variable VCUSTO_INDICE_A double precision;
declare variable VCUSTO_RATEIO_A double precision;
declare variable VPESO_BRUT_PROD_A double precision;
declare variable VPESO_UN_A double precision;
declare variable VPESO_UTIL_A double precision;
declare variable VGRUPO_PROD_P integer;
declare variable VCOD_PROD_P char(6);
declare variable VNITEM_P integer;
declare variable VCOD_GRADE_P integer;
declare variable VCODIGO_NOP_P double precision;
declare variable VNUM_FAB_PROD_P varchar(20);
declare variable VDESCR_PROD_P varchar(75);
declare variable VUNIDADE_P varchar(3);
declare variable VQUANT_PED_ITEM_P double precision;
declare variable VQUANT_MPRIMA_P double precision;
declare variable VEST_F_MPRIMA double precision;
declare variable VPREC_CUS_PROD_P double precision;
declare variable VPREC_CUSM_PROD_P double precision;
declare variable VPESO_BRUT_PROD_P double precision;
declare variable VPESO_UN_P double precision;
declare variable VPESO_UTIL_P double precision;
declare variable VTIPO_ITEM_P char(2);
declare variable VNITEM_ACAB integer;
declare variable VNITEM_PRIMA integer;
declare variable VNITEMID_PRIMA integer;
declare variable VQTDE_MATERIA_PRIMA double precision;
declare variable VEXISTE_MAT_PRIMA integer;
declare variable VCRIAR_PROD_TEMP varchar(100);
declare variable VCRIAR_PROD integer;
declare variable VVENDA_FECHADA_HOJE integer;
declare variable VPRODUCAO_GERADA integer;
declare variable VPRODUCAO_GERADA_HOJE integer;
declare variable VPRODUCAO_ESTORNAR integer;
declare variable VSTATUS_PED varchar(10);
declare variable VTEMP varchar(50);
declare variable VPREC_CUS_PROD double precision;
declare variable VPREC_CUSM_PROD double precision;
declare variable VCUSTOMEDIO_A double precision;
declare variable VEST_F double precision;
declare variable VCODIGO_TEMP integer;
declare variable VPRECCUSPROD_TEMP double precision;
declare variable VPRECCUSMPROD_TEMP double precision;
declare variable VPRECCUSMNF_TEMP double precision;
declare variable VDATAULTCOMPRA_TEMP timestamp;
declare variable VNUMNFREC_TEMP integer;
declare variable VCODPRODU_TEMP integer;
declare variable VUSAR_PRODUCAO_TIPO char(1);
begin
  /* Procedure Text */
  result = 'ERRO';
  vproducao_gerada = 0;
  vproducao_gerada_hoje = 0;
  vexiste_mat_prima = 0;
  vnitem_acab = 0;
  vnitem_prima = 0;
  vnitemid_prima = 0;
  
  if ((trim(ptipo) <> 'REQ') and (trim(ptipo) <> 'OS'))  then
    exit;

  select usar_producao_tipo from empresa
  where cod_empresa = :pcod_empresa into :vusar_producao_tipo;

  if (coalesce(vusar_producao_tipo, 'N') <> 'S') then
  begin
    result = 'PRODUCAO SIMPLES NAO CONFIGURADA';
    suspend;
    exit;
  end

  if ((:pnped > 0) and (trim(:ptipo) <> '') and (:pcod_empresa > 0)) then
  begin
    select coalesce(status_ped, '') from pedvenda
    where nped = :pnped
    and tipo = :ptipo
    and cod_empresa = :pcod_empresa into :vstatus_ped;

    -- Venda aberta
    if (coalesce(vstatus_ped, '') = '') then
    begin
      select count(*) from producao_item pdi
      where pdi.nped = :pnped
      and pdi.tipo = :ptipo
      and pdi.cod_empresa = :pcod_empresa into :vproducao_estornar;

      -- Estornar producao
      if (coalesce(vproducao_estornar, 0) <= 0) then
      begin
        result = 'ITENS DA PRODUCAO DESTA VENDA JA REMOVIDOS';
        suspend;
        exit;
      end

      select first 1 pdi.cod_producao from producao pd
      inner join producao_item pdi on pdi.cod_producao = pd.cod_producao and pdi.cod_empresa = pd.cod_empresa
      where pd.data = (select current_d from sp_current_ts(:pcod_empresa))
      and pd.cod_empresa = :pcod_empresa
      and pd.geracao_aut = 'S'
      and pdi.nped = :pnped
      and pdi.tipo = :ptipo into :vproducao_gerada_hoje;

      -- Producao para venda gerada hoje
      if (coalesce(vproducao_gerada_hoje, 0) <= 0) then
      begin
        result = 'PRODUCAO NAO FOI GERADA HOJE';
        suspend;
        exit;
      end

      -- Deletando itens acabados
      for select cod_producao, nitem, grupo_prod, cod_prod, cod_grade, quantidade from producao_item
          where nped = :pnped
          and tipo = :ptipo
          and cod_empresa = :pcod_empresa
      into :vcod_producao, :vnitem_a, :vgrupo_prod_a, :vcod_prod_a, :vcod_grade_a, :vquant_ped_item_a do
      begin
        delete from producao_item
        where cod_producao = :vcod_producao
        and cod_empresa = :pcod_empresa
        and nitem = :vnitem_a;

        execute procedure movimenta_estoque(
          :vgrupo_prod_a,
          :vcod_prod_a,
          :pcod_empresa,
          coalesce(:vcod_grade_a, 0),
          0,
          coalesce(:vquant_ped_item_a, 0),
          0);

        select first 1 codigo, valor, prec_cus_med, pr_cusc_prod, data, num_nota_nfe, cod_producao from custos
        where grupo_prod = :vgrupo_prod_a
        and cod_prod = :vcod_prod_a
        and cod_empresa = :pcod_empresa
        order by data desc
        into :vcodigo_temp, :vpreccusprod_temp, :vpreccusmprod_temp, :vpreccusmnf_temp,
             :vdataultcompra_temp, :vnumnfrec_temp, :vcodprodu_temp;

        if (coalesce(vcodigo_temp, 0) > 0) then
        begin
          if (coalesce(vcodprodu_temp, 0) > 0) then
            update produtos set prec_cus_prod = coalesce(:vpreccusprod_temp, 0),
              prec_cusm_prod = coalesce(:vpreccusmprod_temp, 0),
              dt_ult_e_producao = :vdataultcompra_temp,
              cod_producao = coalesce(:vcodprodu_temp, 0)
            where grupo_prod = :vgrupo_prod_a
            and cod_prod = :vcod_prod_a
            and cod_empresa = :pcod_empresa;
          else
            update produtos set prec_cus_prod = coalesce(:vpreccusprod_temp, 0),
              prec_cusm_prod = coalesce(:vpreccusmprod_temp, 0),
              prec_cus_mnf = coalesce(:vpreccusmnf_temp, 0),
              data_ult_compra = :vdataultcompra_temp,
              num_nf_rec = coalesce(:vnumnfrec_temp, 0)
            where grupo_prod = :vcod_prod_a
            and cod_prod = :vcod_prod_a
            and cod_empresa = :pcod_empresa;
        end
      end

      -- Deletando materias primas
      for select cod_producao, nitem, nitem_ind, grupo_prod, cod_prod, cod_grade, quantidade_utilizada from producao_item_indice
          where nped = :pnped
          and tipo = :ptipo
          and cod_empresa = :pcod_empresa
      into :vcod_producao, :vnitem_a, :vnitem_p, :vgrupo_prod_p, :vcod_prod_p, :vcod_grade_p, :vqtde_materia_prima do
      begin
        delete from producao_item_indice
        where cod_producao = :vcod_producao
        and cod_empresa = :pcod_empresa
        and nitem = :vnitem_a
        and nitem_ind = :vnitem_p;

        execute procedure movimenta_estoque(
          :vgrupo_prod_p,
          :vcod_prod_p,
          :pcod_empresa,
          coalesce(:vcod_grade_p, 0),
          coalesce(:vqtde_materia_prima, 0),
          0,
          0);
      end

      -- Atualizar quantidade produzida da producao
      update producao set quantidadeproduzida = coalesce((select sum(coalesce(pdi.quantidade, 0)) from producao_item pdi
                                                          where pdi.cod_producao = :vproducao_gerada_hoje
                                                          and pdi.cod_empresa = :pcod_empresa), 0)
      where cod_producao = :vproducao_gerada_hoje
      and cod_empresa = :pcod_empresa;

      result = 'OK';
      suspend;
    end
    else if (coalesce(vstatus_ped, '') = 'FECHADA') then
    begin
      select count(*) from pedvenda pd
      inner join pedvenda_prod pp on
        pp.nped = pd.nped
        and pp.tipo = pd.tipo
        and pp.cod_empresa = pd.cod_empresa
      inner join produtos pr on
        pr.grupo_prod = pp.grupo_prod
        and pr.cod_prod = pp.cod_prod
        and pr.cod_empresa = pp.cod_empresa
      inner join indice_tecnico ind on
        ind.grupo_prod_acabado = pp.grupo_prod
        and ind.cod_prod_acabado = pp.cod_prod
        and ind.cod_empresa = pp.cod_empresa
      where pp.nped = :pnped
      and pp.tipo = :ptipo
      and pp.cod_empresa = :pcod_empresa
      and coalesce(pp.status, '') <> 'CANCELADO'
      and pp.ativo = 1
      and not(coalesce(pp.quant_ped_item, 0) = coalesce(pp.quant_item_dev, 0) and coalesce(pp.status, '') = 'CANCELADO')
      and coalesce(pr.criar_producao_aut, 'N') = 'S'
      into :vexiste_mat_prima;
    
      -- Venda possuiu produtos com insumos
      if (coalesce(vexiste_mat_prima, 0) <= 0) then
      begin
        result = 'NAO EXISTEM PRODUTOS ACABADOS CONFIG PARA GERAR PRODUCAO';
        suspend;
        exit;
      end

      select first 1 nped from pedvenda
      where nped = :pnped
      and tipo = :ptipo
      and cod_empresa = :pcod_empresa
      and data_fech = (select current_d from sp_current_ts(:pcod_empresa)) into :vvenda_fechada_hoje;

      -- venda fechada hoje
      if (coalesce(vvenda_fechada_hoje, 0) <= 0) then
      begin
        suspend;
        exit;
      end
    
      select first 1 cod_producao from producao
      where data = (select current_d from sp_current_ts(:pcod_empresa))
      and cod_empresa = :pcod_empresa
      and geracao_aut = 'S' into :vproducao_gerada_hoje;
    
      -- Nao existe nenhuma producao automatica gerada hoje
      if (coalesce(vproducao_gerada_hoje, 0) <= 0) then
      begin
        select count(*) from producao_item
        where nped = :pnped
        and tipo = :ptipo
        and cod_empresa = :pcod_empresa into :vproducao_gerada;
    
        -- Ja existe producao gerada para esta venda
        if (coalesce(vproducao_gerada, 0) > 0) then
        begin
          result = 'JA EXISTE PRODUCAO GERADA PARA ESTA VENDA';
          suspend;
          exit;
        end
      end
    
      verro = 'N';
      for select result from getcriarproducao_temp(:pnped, :ptipo, :pcod_empresa)
       into :vcriar_prod_temp do
      begin
        --  Producao temporaria criada para esta venda
        if (coalesce(vcriar_prod_temp, '') <> 'OK') then
        begin
          verro = 'S';  
          result = vcriar_prod_temp;
          suspend;
        end
      end

      -- Erro ao gerar producao temporaria
      if (coalesce(verro, 'N') = 'S') then
        exit;

      select count(*) from temp_producao_aut
      where nped = :pnped and tipo = :ptipo and cod_empresa = :pcod_empresa into :vcriar_prod;
    
      -- Producao temporaria foi criada para esta venda
      if (coalesce(vcriar_prod, 0) <= 0) then
      begin
        result = 'PRODUCAO TEMPORARIA NAO FOI GERADA';
        suspend;
        exit;
      end
    
      -- Producao automatica gerada hoje, se nao gerar nova producao
      if (coalesce(vproducao_gerada_hoje, 0) > 0) then
        vcod_producao = coalesce(vproducao_gerada_hoje, 0);
      else
        vcod_producao = (select cod from incrementa_codigo(:pcod_empresa, 'PRODUCAO'));
    
      -- Inserir nova producao, se nao existir uma gerada
      if (coalesce(vproducao_gerada_hoje, 0) <= 0) then
      begin
        insert into producao (cod_producao, cod_empresa, cod_cliente,
          data, data_fechamento, data_inicio, status, descricao, nlote,
          quantidadeprevista, quantidadeproducao,
          unidade, cod_formula, cod_emp_form, hora_inicio, hora_fechamento,
          data_estoque, tipo_k, tipo_conversao, geracao_aut)
        values (
          :vcod_producao,
          :pcod_empresa,
          null,
          (select current_d from sp_current_ts(:pcod_empresa)),
          (select current_d from sp_current_ts(:pcod_empresa)),
          (select current_d from sp_current_ts(:pcod_empresa)),
          'FECHADO',
          'PRODUCAO ' ||
          (cast((select result from strzero(
              extract(day from (select current_d from sp_current_ts(:pcod_empresa))), 2)) as varchar(2)) ||'/'||
           cast((select result from strzero(
              extract(month from (select current_d from sp_current_ts(:pcod_empresa))), 2))  as varchar(2)) ||'/'||
           case extract(weekday from (select current_d from sp_current_ts(:pcod_empresa)))
              when 0 then 'domingo'
              when 1 then 'segunda-feira'
              when 2 then 'terca-feira'
              when 3 then 'quarta-feira'
              when 4 then 'quinta-feira'
              when 5 then 'sexta-feira'
              when 6 then 'sabado'
          end),
          (select result from strzero(
            (select cod from incrementa_codigo(:pcod_empresa, 'PRODUCAO' ||
              cast(extract(year from (select current_d from sp_current_ts(:pcod_empresa))) as varchar(4)))), 4)) || '/' ||
                        substring(cast(extract(year from (select current_d from sp_current_ts(:pcod_empresa))) as varchar(4))  from 3 for 2),
          0,
          0,
          'KG',
          null,
          null,
          (select current_ts from sp_current_ts(:pcod_empresa)),
          (select current_ts from sp_current_ts(:pcod_empresa)),
          (select current_d from sp_current_ts(:pcod_empresa)),
          null,
          null,
          'S');
      end
    
      -- Retorna nitem total dos itens acabados
      select max(coalesce(nitem, 0)) from producao_item
      where cod_producao = :vcod_producao and cod_empresa = :pcod_empresa into :vnitem_acab;
    
      -- Retorna nitem total dos itens de insumos
      select max(coalesce(nitem, 0)) from producao_item_indice
      where cod_producao = :vcod_producao and cod_empresa = :pcod_empresa into :vnitem_prima;

      -- Retorna nitem_ind total dos itens de insumos
      select max(coalesce(nitem_ind, 0)) from producao_item_indice
      where cod_producao = :vcod_producao and cod_empresa = :pcod_empresa into :vnitemid_prima;
    
      -- Inserir itens acabados
      for select distinct tmp.grupo_prod_acabado, tmp.cod_prod_acabado, tmp.cod_grade_acabado,
         pr.codigo_nop, pr.num_fab_prod, pr.descr_prod, pr.unidade,
         coalesce(tmp.quant_ped_item_acabado, 0) quant_ped_item_acabado,
         coalesce(tmp.est_f_acabado, 0) est_f_acabado,
         coalesce(tmp.estoque_disp_acabado, 0) estoque_disp_acabado,
         coalesce(tmp.prec_cus_prod_acabado, 0) prec_cus_prod_acabado,
         coalesce(tmp.prec_cusm_prod_acabado, 0) prec_cusm_prod_acabado,
         coalesce(tmp.peso_un_acabado, 0) peso_un_acabado,
         coalesce(tmp.peso_util_acabado, 0) peso_util_acabado,
         coalesce(tmp.custo_indice_acabado, 0) custo_indice_acabado,
         coalesce(tmp.custo_rateio_acabado, 0) custo_rateio_acabado,
         coalesce(pr.peso_brut_prod, 0) peso_brut_prod from temp_producao_aut tmp
         inner join produtos pr on
            pr.grupo_prod = tmp.grupo_prod_acabado
            and pr.cod_prod = tmp.cod_prod_acabado
            and pr.cod_empresa = tmp.cod_empresa
         left join cod_grade_prod gr on
            gr.grupo_prod = tmp.grupo_prod_acabado
            and gr.cod_prod = tmp.cod_prod_acabado
            and gr.cod_grade = tmp.cod_grade_acabado
            and gr.cod_empresa = tmp.cod_empresa
         where tmp.nped = :pnped
         and tmp.tipo = :ptipo
         and tmp.cod_empresa = :pcod_empresa
         into :vgrupo_prod_a, :vcod_prod_a, :vcod_grade_a, :vcodigo_nop_a,
              :vnum_fab_prod_a, :vdescr_prod_a, :vunidade_a, :vquant_ped_item_a,
              :vest_f_a, :vestoque_disp_a, :vprec_cus_prod_a, :vprec_cusm_prod_a,
              :vpeso_un_a, :vpeso_util_a, :vcusto_indice_a, :vcusto_rateio_a, :vpeso_brut_prod_a do
      begin
        vnitem_acab = coalesce(vnitem_acab, 0) + 1;
        insert into producao_item (cod_producao, cod_empresa, nitem, grupo_prod, cod_prod, num_fab_prod,
          descr_prod, unidade, quantidade, prec_cusm_prod, prec_cus_prod,
          peso_un, peso_util, custo_indice, custo_rateio, seq, cod_grade, nped, tipo)
        values (
          :vcod_producao,
          :pcod_empresa,
          :vnitem_acab,
          :vgrupo_prod_a,
          :vcod_prod_a,
          :vnum_fab_prod_a,
          :vdescr_prod_a,
          :vunidade_a,
          coalesce(:vquant_ped_item_a, 0),
          coalesce(:vprec_cusm_prod_a, 0),
          coalesce(:vprec_cus_prod_a, 0),
          coalesce(:vpeso_un_a, 0),
          coalesce(:vpeso_util_a, 0),
          coalesce(:vcusto_indice_a, 0),
          coalesce(:vcusto_rateio_a, 0),
          :vnitem_acab,
          coalesce(:vcod_grade_a, 0),
          :pnped,
          :ptipo);

        -- Inserir materias primas
        for select tmp.grupo_prod_mprima, tmp.cod_prod_mprima, tmp.cod_grade_mprima,
          pr.codigo_nop, pr.num_fab_prod, pr.descr_prod, pr.unidade, pr.tipo_item,
          coalesce(tmp.quant_ped_item_acabado, 0) quant_ped_item_acabado,
          coalesce(tmp.quant_mprima, 0) quant_mprima,
          coalesce(tmp.est_f_mprima, 0) est_f_mprima,
          coalesce(tmp.prec_cusm_prod_mprima, 0) prec_cusm_prod_mprima,
          coalesce(tmp.peso_un_mprima, 0) peso_un_mprima,
          coalesce(tmp.peso_util_mprima, 0) peso_util_mprima from temp_producao_aut tmp
          inner join produtos pr on pr.grupo_prod = tmp.grupo_prod_mprima and pr.cod_prod = tmp.cod_prod_mprima and pr.cod_empresa = tmp.cod_empresa
          where tmp.nped = :pnped
          and tmp.tipo = :ptipo
          and tmp.cod_empresa = :pcod_empresa
          and tmp.grupo_prod_acabado = :vgrupo_prod_a
          and tmp.cod_prod_acabado = :vcod_prod_a
          and tmp.cod_grade_acabado = coalesce(:vcod_grade_a, 0)
        into :vgrupo_prod_p, :vcod_prod_p, :vcod_grade_p, :vcodigo_nop_p,
             :vnum_fab_prod_p, :vdescr_prod_p, :vunidade_p, :vtipo_item_p,
             :vquant_ped_item_p, :vquant_mprima_p, :vest_f_mprima,
             :vprec_cusm_prod_p, :vpeso_un_p, :vpeso_util_p do
        begin
          vqtde_materia_prima = coalesce(:vquant_ped_item_a, 0) * coalesce(vquant_mprima_p, 0);
          vnitem_prima        = coalesce(vnitem_prima, 0) + 1;
          vnitemid_prima      = coalesce(vnitemid_prima, 0) + 1;

          insert into producao_item_indice (cod_producao, cod_empresa, nitem, nitem_ind,
            grupo_prod, cod_prod, num_fab_prod, descr_prod, unidade, tipo_item,
            quantidade_receita, quantidade_utilizada, quantidade_perda, quantidade_teorica,
            prec_cusm_prod, cod_formula, peso_un, peso_util, solvente, seq, seqn, cod_grade, nped, tipo)
          values (
            :vcod_producao,
            :pcod_empresa,
            :vnitem_acab,
            :vnitemid_prima,
            :vgrupo_prod_p,
            :vcod_prod_p,
            :vnum_fab_prod_p,
            :vdescr_prod_p,
            :vunidade_p,
            :vtipo_item_p,
            coalesce(:vquant_mprima_p, 0),
            coalesce(:vqtde_materia_prima, 0),
            0,
            coalesce(:vqtde_materia_prima, 0),
            coalesce(:vprec_cusm_prod_p, 0),
            null,
            coalesce(:vpeso_un_p, 0),
            coalesce(:vpeso_util_p, 0),
            null,
            :vnitem_acab,
            :vnitemid_prima,
            coalesce(:vcod_grade_p, 0),
            :pnped,
            :ptipo);

          -- Movimentar estoque dos insumos
          execute procedure movimenta_estoque(
            :vgrupo_prod_p,
            :vcod_prod_p,
            :pcod_empresa,
            :vcod_grade_p,
            0,
            coalesce(:vqtde_materia_prima, 0),
            0);

          update produtos set dt_ult_s_producao = (select current_d from sp_current_ts(:pcod_empresa))
          where grupo_prod = :vgrupo_prod_p and cod_prod = :vcod_prod_p and cod_empresa = :pcod_empresa;
        end

        -- Movimentar estoque dos produtos acabados
        execute procedure movimenta_estoque(
          :vgrupo_prod_a,
          :vcod_prod_a,
          :pcod_empresa,
          :vcod_grade_a,
          coalesce(:vquant_ped_item_a, 0),
          0,
          0);

        vcustomedio_a = coalesce(vprec_cusm_prod_a, 0);

        /*
        update produtos set
          prec_cus_prod = coalesce(:vprec_cus_prod_a, 0),
          prec_cusm_prod = coalesce(:vcustomedio_a, 0),
          cod_producao = :vcod_producao,
          dt_ult_e_producao = (select current_d from sp_current_ts(:pcod_empresa))
        where grupo_prod = :vgrupo_prod_a
        and cod_prod = :vcod_prod_a
        and cod_empresa = :pcod_empresa;
        */

        update pedvenda_prod set
          pcust_c = coalesce(:vprec_cus_prod_a, 0),
          pcust_mc = coalesce(:vcustomedio_a, 0)
        where nped = :pnped
        and tipo = :ptipo
        and grupo_prod = :vgrupo_prod_a
        and cod_prod = :vcod_prod_a
        and cod_grade = :vcod_grade_a
        and cod_empresa = :pcod_empresa;

        insert into custos (codigo, cod_empresa, valor,
          grupo_prod, cod_prod, data, prec_cus_med, pr_cusc_prod, cod_producao)
        values (
          (select cod from incrementa_codigo(:pcod_empresa, 'CUSTOS')),
          :pcod_empresa,
          coalesce(:vprec_cus_prod_a, 0),
          :vgrupo_prod_a,
          :vcod_prod_a,
          (select current_d from sp_current_ts(:pcod_empresa)),
          coalesce(:vcustomedio_a, 0),
          coalesce(:vprec_cus_prod_a, 0),
          :vcod_producao);

        update producao_item set prec_cusm_prod = coalesce(:vcustomedio_a, 0)
        where cod_producao = :vcod_producao
        and cod_empresa = :pcod_empresa
        and nped = :pnped
        and tipo = :ptipo;
      end
    
      -- Atualizar quantidade produzida da producao
      if (coalesce(vcod_producao, 0) > 0) then
      begin
        update producao set quantidadeproduzida =
            coalesce((select sum(coalesce(pdi.quantidade, 0)) from producao_item pdi
                      where pdi.cod_producao = :vcod_producao
                      and pdi.cod_empresa = :pcod_empresa), 0)
        where cod_producao = :vcod_producao
        and cod_empresa = :pcod_empresa;
      end

      delete from temp_producao_aut
      where nped = :pnped
      and tipo = :ptipo
      and cod_empresa = :pcod_empresa;

      result = 'OK';
      suspend;
    end
  end
end;
 
 ^

ALTER PROCEDURE SP_PROXIMO_DIAUTIL (PI_DATA DATE)
RETURNS (PO_DATA TIMESTAMP)
AS 
declare variable VDATA date;
declare variable VDAY integer;
declare variable VNEWDAY integer;
declare variable I integer;
declare variable J integer;
declare variable VOK integer;
BEGIN
  SELECT EXTRACT(WEEKDAY FROM :PI_DATA) FROM RDB$DATABASE INTO :VDAY;
  IF (VDAY=6) THEN
    VDATA = PI_DATA+2;
  ELSE IF (VDAY=0) THEN
    VDATA = PI_DATA+1;
  ELSE
    VDATA = PI_DATA;
  SELECT COALESCE(COUNT(*),0)  FROM FERIADO F WHERE F.DATA_FERIADO = :VDATA INTO :I;
  IF (I>0) THEN
  BEGIN
    VDATA = VDATA+1;
    VOK = 0;
    WHILE (VOK=0) DO
    BEGIN
      SELECT COALESCE(COUNT(*), 0)  FROM FERIADO F WHERE F.DATA_FERIADO = :VDATA INTO :J;
      IF (J>0) THEN
        VDATA = VDATA+1;
      ELSE
      BEGIN
        SELECT EXTRACT(WEEKDAY FROM :VDATA) FROM RDB$DATABASE INTO :VNEWDAY;
        IF (VNEWDAY=6) THEN
          VDATA = VDATA+2;
        ELSE IF (VNEWDAY=0) THEN
          VDATA = VDATA+1;
        ELSE
          VOK = 1;
      END
    END
  END
  PO_DATA = VDATA;
  SUSPEND;
END ^

