ALTER PROCEDURE SP_REESTRUTURA_BUILDS (LIMITE INTEGER = 20)
RETURNS (VERSAO_SCRIPT INTEGER,
BUILD INTEGER,
SCRIPTS INTEGER)
AS 
begin
  -- retorna os scripts que foram criados apos o snapshot
  for select
      versao_script, build, count(*)
    from reestrurura_sql
    where versao_script >= 27
      group by 1, 2
      order by build desc, versao_script
      into :versao_script, :build, :scripts
  do
  begin
    suspend;

    limite = limite -1;

    if (limite <= 0) then
      exit;
  end
end ^

ALTER PROCEDURE SP_REESTRUTURA_ROLLBACK_LAST RETURNS (RESULT VARCHAR(32) CHARACTER SET NONE,
VERSAO INTEGER,
SCRIPTS INTEGER)
AS 
  declare variable snapshotid integer;
  declare variable seqscript integer;
  declare variable manifest blob sub_type 1 segment size 1024;
begin
  result = 'success';

  snapshotid = null;

  for select first 1
      ss.id, ss.manifest
    from reestrutura_snapshot ss
    order by ss.id desc
      into :snapshotid, :manifest
  do
  begin
    for select
        sss.script_version, sss.script_seq
      from reestrutura_snapshot_scripts sss
      where sss.snapshot_id = :snapshotid
      order by sss.script_version desc, sss.script_version desc
        into :versao, :seqscript
    do
    begin
      select count(*) from reestrurura_sql rs
      where rs.versao_script = :versao
        and rs.nitem > :seqscript
        into :scripts;

      delete from reestrurura_sql rs
      where rs.versao_script = :versao
        and rs.nitem > :seqscript;
    
      update reestrurura_ver rv set
        rv.build = (
          select max(rs.build)
          from reestrurura_sql rs
          where rs.versao_script = :versao
        )
      where rv.versao_script = :versao;

      suspend;
    end
  end

  if (snapshotid = null) then
  begin
    result = 'snapshot-empty';
    suspend;
    exit;
  end

  update config_sistema cs set
    cs.value1_b = :manifest
  where cs.chave = 'reestrutura_manifest'
    and cs.cod_empresa = 0;

  delete from reestrutura_snapshot where id = :snapshotid;

  result = 'fim';
  scripts = null;
  versao = null;

  suspend;
end;
 
 ^

ALTER PROCEDURE SP_REESTRUTURA_SNAPSHOT_NEW RETURNS (RESULT VARCHAR(32) CHARACTER SET NONE,
VERSAO INTEGER,
SEQUENCIA INTEGER)
AS 
  declare variable snapshotid integer;
  declare variable seqscript integer;
  declare variable manifest blob sub_type 1 segment size 1024;
  declare variable inserido smallint;
begin
  result = 'success';

  snapshotid = coalesce((select max(id) from reestrutura_snapshot), 0) + 1;
  inserido = 0;

  -- manifesto atual
  select cs.value1_b
  from config_sistema cs
  where cs.chave = 'reestrutura_manifest'
    and cs.cod_empresa = 0
    into :manifest;

  -- obtem registro mestre e sequencias do maior/ultimo por script
  for select
      rv.versao_script, max(rs.nitem)
    from reestrurura_ver rv
      left join reestrurura_sql rs on rs.versao_script = rv.versao_script
    where rv.versao_script >= 27
    group by 1
    order by rv.versao_script
      into :versao, :seqscript
  do
  begin
    --obten a sequencia da ultima versao
    select first 1
      s.script_seq
    from reestrutura_snapshot_scripts s
    where s.script_version = :versao
      order by s.snapshot_id desc
      into :sequencia;

    -- sequencia diferente entao registra
    if (coalesce(sequencia, 0) <> seqscript) then
    begin
      if (inserido <> 1) then
      begin
        -- snapshot do manifesto
        insert into reestrutura_snapshot
          (id, createdat, manifest)
        values
          (:snapshotid, current_timestamp, :manifest);
        inserido = 1;
      end
      -- insere snapshot do script caso o anterior seja diferente
      insert into reestrutura_snapshot_scripts
        (snapshot_id, script_version, script_seq)
      values (:snapshotid, :versao, :seqscript);


      sequencia = :seqscript;
      suspend;
    end
  end
end;
 
 ^

ALTER PROCEDURE SP_REESTRUTURA_SNAPSHOT_SQL RETURNS (VERSAO_SCRIPT INTEGER,
NITEM INTEGER,
VERSAO_SISTEMA VARCHAR(10) CHARACTER SET NONE,
BUILD INTEGER,
OPCOES VARCHAR(64) CHARACTER SET NONE,
EXECUCAO VARCHAR(8) CHARACTER SET NONE,
SQLTEXT BLOB CHARACTER SET NONE)
AS 
begin
  -- retorna os scripts que foram criados apos o snapshot
  for select
      rs.script_version, rs.script_seq
    from reestrutura_snapshot_scripts rs
    where rs.snapshot_id = (select max(snapshot_id) from reestrutura_snapshot_scripts)
    order by rs.script_version desc
      into :versao_script, :nitem
  do
  begin
    for select
        nitem, versao_sistema, build, opcoes, execucao, sqltext
      from reestrurura_sql
      where versao_script = :versao_script
        and nitem > :nitem
      order by nitem desc
        into :nitem, :versao_sistema, :build, :opcoes, :execucao, :sqltext
    do
      suspend;
  end
end ^

ALTER PROCEDURE SP_REESTRUTURA_SQL_BUILD (BUILD_INPUT INTEGER)
RETURNS (VERSAO_SCRIPT INTEGER,
NITEM INTEGER,
VERSAO_SISTEMA VARCHAR(10) CHARACTER SET NONE,
BUILD INTEGER,
OPCOES VARCHAR(64) CHARACTER SET NONE,
EXECUCAO VARCHAR(8) CHARACTER SET NONE,
SQLTEXT BLOB CHARACTER SET NONE)
AS 
begin
  for select
      versao_script, nitem,  versao_sistema, build, opcoes, execucao, sqltext
    from reestrurura_sql
    where versao_script >= 27
      and build = :build_input
    order by versao_script desc, nitem desc
      into :versao_script, :nitem, :versao_sistema, :build, :opcoes, :execucao, :sqltext
  do
    suspend;
end ^

ALTER PROCEDURE SP_REG_STS_USO (STS VARCHAR(64) CHARACTER SET NONE)
RETURNS (QTDE INTEGER)
AS 
  declare variable CURRENT_TS timestamp;
begin  
  select CURRENT_D
  from SP_CURRENT_TS
    into :CURRENT_TS;

  select quantidade from sts_uso
    where dia = :CURRENT_TS and sts_descricao = :sts
      into :qtde;

  if (coalesce(qtde, 0) = 0) then
  begin
    update or insert into sts_uso (dia, sts_descricao, quantidade)
      values (:CURRENT_TS, :sts, 1)
      matching (dia, sts_descricao)
      returning quantidade into :qtde;
  end
  else
  begin
    update sts_uso set quantidade = quantidade + 1
      where dia = :CURRENT_TS and sts_descricao = :sts;
    qtde = qtde + 1;
  end
  suspend;
end ^

ALTER PROCEDURE SP_RETORNO_DEBITOCREDITO (PTIPO CHAR(3) CHARACTER SET NONE,
PTIPV VARCHAR(1) CHARACTER SET NONE,
PTIPO_OS VARCHAR(10) CHARACTER SET NONE)
RETURNS (RETORNO CHAR(1) CHARACTER SET NONE)
AS 
declare variable VDEBCRED char(1);
begin
  vdebcred='';
  if ((ptipo = 'REQ') and (coalesce(:ptipv,'')<>'')) then
  begin
    select usar_debcred from tipo_vendas
      where tipo = :ptipo and sigla = :ptipv and ativo = 1
      into :vdebcred;
  end
  else if ((rtrim(ptipo) = 'OS') and (coalesce(:ptipo_os,'')<>'')) then
  begin
    select venda from tipo_vendas
      where tipo = :ptipo and tipo_os = :ptipo_os and ativo = 1
      into :vdebcred;
  end
  
  retorno = 'N';
  if ( ltrim(rtrim(vdebcred))  <> '' ) then
    retorno = ltrim(rtrim(vdebcred));

  suspend;
END ^

