ALTER PROCEDURE SP_SERV_EMPRESAS RETURNS (RESULT VARCHAR(4) CHARACTER SET NONE)
AS 
declare variable VCOD_SERVICO integer;
declare variable VCOD_EMPRESA integer;
declare variable VEXISTE integer;
begin
  RESULT = 'ERRO';
  /* Procedure Text */
  for select cod_servico, cod_empresa from tipo_servico into :VCOD_SERVICO, :VCOD_EMPRESA do
  begin
    if (coalesce(VCOD_EMPRESA, 0) > 0) then
    begin
        UPDATE OR INSERT INTO TIPO_SERVICO_EMPRESA (COD_SERVICO, COD_EMPRESA)
        VALUES (:VCOD_SERVICO, :VCOD_EMPRESA)
        MATCHING (COD_SERVICO, COD_EMPRESA);

        UPDATE TIPO_SERVICO SET COD_EMPRESA = NULL
        WHERE COD_SERVICO = :VCOD_SERVICO;
        RESULT = 'OK';
    end
    else
    begin
        SELECT COUNT(*) FROM TIPO_SERVICO_EMPRESA
        WHERE COD_SERVICO = :VCOD_SERVICO into :VEXISTE;

        if (coalesce(VEXISTE, 0) <= 0) then
        begin
            for select cod_empresa from empresa into :VCOD_EMPRESA do
            begin
                UPDATE OR INSERT INTO TIPO_SERVICO_EMPRESA (COD_SERVICO, COD_EMPRESA)
                VALUES (:VCOD_SERVICO, :VCOD_EMPRESA)
                MATCHING (COD_SERVICO, COD_EMPRESA);
                RESULT = 'OK';
            end
        end
    end
  end
  suspend;
end ^

ALTER PROCEDURE SP_SPLIT (TEXT_INPUT BLOB CHARACTER SET NONE,
SEPARATOR BLOB CHARACTER SET NONE = ',',
IGNORE_EMPTYS CHAR(1) CHARACTER SET NONE = 'S')
RETURNS (TEXT BLOB CHARACTER SET NONE)
AS 
begin
  while (TEXT_INPUT containing (SEPARATOR)) do
  begin
    TEXT = substring(TEXT_INPUT from 1 for (position(SEPARATOR, TEXT_INPUT) - 1));
    if ((TEXT <> '') or (IGNORE_EMPTYS = 'S')) then
      suspend;
    TEXT_INPUT = substring(TEXT_INPUT from (position(SEPARATOR, TEXT_INPUT) + char_length(SEPARATOR)) for char_length(TEXT_INPUT));
  end
  if (coalesce(TEXT_INPUT, '') <> '') then
    if ((TEXT <> '') or (IGNORE_EMPTYS = 'S')) then
    begin
      TEXT = TEXT_INPUT;
      suspend;
    end
end;

 
 ^

ALTER PROCEDURE SP_SPLITCHARS (TEXT_INPUT BLOB CHARACTER SET NONE,
ACHARS BLOB CHARACTER SET NONE = ',',
IGNORE_EMPTYS CHAR(1) CHARACTER SET NONE = 'S')
RETURNS (TEXT BLOB CHARACTER SET NONE)
AS 
  declare variable ASUB blob sub_type 1 segment size 80;
  declare variable ACH char(1);
begin
  TEXT = null;
  ASUB = TEXT_INPUT;

  while (char_length(ASUB) > 0) do
  begin
    ACH = substring(ASUB from 1 for 1);
    ASUB = substring(ASUB from 2 for char_length(ASUB) - 1);
    if (achars containing ach) then
    begin
      if ((TEXT <> '') or (IGNORE_EMPTYS <> 'S')) then
        suspend;

      TEXT = '';
    end
    else
      TEXT = coalesce(TEXT, '') || ACH;
  end

  if ((TEXT = null) and (coalesce(TEXT_INPUT, '') <> '')) then -- nao entrou no while
  begin
    TEXT = TEXT_INPUT;
    suspend;
  end
  else if ((TEXT <> '') or (IGNORE_EMPTYS <> 'S')) then -- entrou no while, porem nao teve split
    suspend;
end ^

