ALTER PROCEDURE SP_SQL_SINGLE_RECORD (SQL VARCHAR(1024) CHARACTER SET NONE,
SEPARATOR VARCHAR(16) CHARACTER SET NONE = ', ')
RETURNS (TEXT BLOB CHARACTER SET NONE)
AS 
  declare variable field_value blob sub_type 1 segment size 64;
begin
  text = '';
  for execute statement SQL
      into :field_value
  do
  begin
    if (coalesce(trim(field_value), '') <> '') then
    begin
      if (text = '') then
        text = trim(field_value);
      else
        text = text || separator || trim(field_value);
    end
  end
  suspend;
end ^

ALTER PROCEDURE SP_STATS_INC (DESCRICAO VARCHAR(64) CHARACTER SET NONE,
EMPRESA_ID INTEGER)
RETURNS (QTDE T_VL_TODOS)
AS 
  declare variable CURRENT_D timestamp;
  declare variable FIRST_D timestamp;
  declare variable LAST_D timestamp;
  declare variable ENVIADO char(1);
begin

  -- Registro do dia

  select CURRENT_D,
         cast(extract(year from current_date) || '-' || extract(month from current_date) || '-01' as date),
         dateadd(-1 day to dateadd(1 month to cast(extract(year from current_date) || '-' || extract(month from current_date) || '-01' as date)))
  from SP_CURRENT_TS(:EMPRESA_ID)
    into :CURRENT_D, :FIRST_D, :LAST_D;

  select first 1 QUANTIDADE, ENVIADO
  from STATS
  where DIA = :CURRENT_D and
        COD_E = :EMPRESA_ID and
        DESCRICAO = :DESCRICAO and
        TIPO = 0
    into :QTDE, :ENVIADO;

  if (coalesce(ENVIADO, '') <> 'S') then
  begin

    update or insert into STATS (DIA, COD_E, DESCRICAO, QUANTIDADE, TIPO)
    values (:CURRENT_D, :EMPRESA_ID, :DESCRICAO, coalesce(:QTDE, 0) + 1, 0)
    matching (DIA, COD_E, DESCRICAO, TIPO)
    returning QUANTIDADE
    into :QTDE;

  end

  suspend;

  -- Registro acumulado do mes

  select sum(QUANTIDADE)
  from STATS
  where DIA >= :FIRST_D and
        DIA <= :LAST_D and
        COD_E = :EMPRESA_ID and
        DESCRICAO = :DESCRICAO and
        TIPO = 0
    into :QTDE;

  update or insert into STATS (DIA, COD_E, DESCRICAO, QUANTIDADE, TIPO)
  values (:LAST_D, :EMPRESA_ID, :DESCRICAO, coalesce(:QTDE, 0), 3)
  matching (DIA, COD_E, DESCRICAO, TIPO);

end
 
 ^

ALTER PROCEDURE SP_STATS_US (US_HW VARCHAR(32) CHARACTER SET NONE,
US_WIN VARCHAR(32) CHARACTER SET NONE,
SERIAL CHAR(8) CHARACTER SET NONE,
EMPRESA_ID INTEGER)
RETURNS (DESCRICAO VARCHAR(64) CHARACTER SET NONE,
QTDE T_VL_TODOS)
AS 
  declare variable CURRENT_D timestamp;  
  declare variable FIRST_D timestamp;
  declare variable LAST_D timestamp;
  declare variable ENVIADO char(1);
begin

  -- Registro do dia

  select CURRENT_D,
         cast(extract(year from current_date) || '-' || extract(month from current_date) || '-01' as date),
         dateadd(-1 day to dateadd(1 month to cast(extract(year from current_date) || '-' || extract(month from current_date) || '-01' as date)))
  from SP_CURRENT_TS(:EMPRESA_ID)
    into :CURRENT_D, :FIRST_D, :LAST_D;

  update or insert into STATS_US (DIA, COD_E, USUARIO_HW, USUARIO_WINDOWS, SERIALHD)
  values ((select CURRENT_D
           from SP_CURRENT_TS(:EMPRESA_ID)), :EMPRESA_ID, :US_HW, :US_WIN, :SERIAL)
  matching (DIA, COD_E, USUARIO_HW, USUARIO_WINDOWS, SERIALHD);

  for select count(distinct USUARIO_HW) QTDE, 'USUARIOS_HW' DESCRICAO
      from STATS_US
      where DIA = :CURRENT_D and
            COD_E = :EMPRESA_ID
      union
      select count(distinct USUARIO_WINDOWS) QTDE, 'USUARIOS_WIN' DESCRICAO
      from STATS_US
      where DIA = :CURRENT_D and
            COD_E = :EMPRESA_ID
      union
      select count(distinct SERIALHD) QTDE, 'COMPUTADORES' DESCRICAO
      from STATS_US
      where DIA = :CURRENT_D and
            COD_E = :EMPRESA_ID
        into :QTDE, :DESCRICAO
  do
  begin
    select ENVIADO
    from STATS
    where DIA = :CURRENT_D and
          COD_E = :EMPRESA_ID and
          DESCRICAO = :DESCRICAO
      into :ENVIADO;

    if (coalesce(ENVIADO, '') <> 'S') then
    begin
      update or insert into STATS (DIA, COD_E, DESCRICAO, QUANTIDADE, TIPO)
      values (:CURRENT_D, :EMPRESA_ID, :DESCRICAO, coalesce(:QTDE, 0), 1)
      matching (DIA, COD_E, DESCRICAO, TIPO);
    end

    suspend;

    -- Registro acumulado do mes

    select sum(QUANTIDADE)
    from STATS
    where DIA >= :FIRST_D and
          DIA <= :LAST_D and
          COD_E = :EMPRESA_ID and
          DESCRICAO = :DESCRICAO and
          TIPO = 1
      into :QTDE;
    
    update or insert into STATS (DIA, COD_E, DESCRICAO, QUANTIDADE, TIPO)
    values (:LAST_D, :EMPRESA_ID, :DESCRICAO, coalesce(:QTDE, 0), 4)
    matching (DIA, COD_E, DESCRICAO, TIPO);

  end

end ^

ALTER PROCEDURE SP_TEF_CARTDIG RETURNS (ID VARCHAR(8) CHARACTER SET NONE,
DESCRICAO VARCHAR(60) CHARACTER SET NONE)
AS 
begin
