ALTER PROCEDURE SP_TIMESTAMPTOSTR (VALOR TIMESTAMP,
DEFVALUE VARCHAR(64) CHARACTER SET NONE = '0')
RETURNS (RESULT VARCHAR(64) CHARACTER SET NONE)
AS 
begin
  RESULT = VALOR || '';
  while (reverse(RESULT) starting '0') do
    RESULT = substring(RESULT from 1 for char_length(RESULT) - 1);

  if (reverse(RESULT) starting '.') then
    RESULT = substring(RESULT from 1 for char_length(RESULT) - 1);

  if (RESULT is null) then
    RESULT = DEFVALUE;

  suspend;
end ^

ALTER PROCEDURE SP_TIMETOSTR (VALOR TIME,
DEFVALUE VARCHAR(64) CHARACTER SET NONE = '0')
RETURNS (RESULT VARCHAR(64) CHARACTER SET NONE)
AS 
begin
  RESULT = VALOR || '';
  while (reverse(RESULT) starting '0') do
    RESULT = substring(RESULT from 1 for char_length(RESULT) - 1);

  if (reverse(RESULT) starting '.') then
    RESULT = substring(RESULT from 1 for char_length(RESULT) - 1);

  if (RESULT is null) then
    RESULT = DEFVALUE;

  suspend;
end ^

ALTER PROCEDURE STRZERO (VALOR BIGINT,
QTD INTEGER = 0)
RETURNS (RESULT VARCHAR(50) CHARACTER SET NONE)
AS 
declare variable I integer;
declare variable VVAL varchar(50);
BEGIN

i = 0;

RESULT = rtrim(cast(:valor as varchar(50)));
vval = cast(:valor as varchar(50));
vval=rtrim(vval);

while (i < (:QTD - char_length(:vval)))do
begin

RESULT = '0' || RESULT;

i = i + 1;

end

SUSPEND;

END ^

ALTER PROCEDURE UTIL_SPLIT_BLOB_TO_ROW (BLOBTEXT VARCHAR(1000) CHARACTER SET NONE)
RETURNS (MNUMBER INTEGER,
RETSTRING VARCHAR(1000) CHARACTER SET NONE)
AS 
declare variable LSTRING varchar(1000);
declare variable POS1 integer;
declare variable POS2 integer;
declare variable INTLEN integer;
BEGIN
  lstring = SUBSTRING( BLOBTEXT FROM 1 FOR 1000);

  pos1 = 1;
  intlen = CHAR_LENGTH(lstring);
  MNUMBER = 0;

  while (pos1 < intlen) do
  BEGIN
    MNUMBER = MNUMBER + 1;
    pos2 = POSITION (ASCII_CHAR(13) IN SUBSTRING(lstring FROM pos1));
 
    IF (pos2 = 0) THEN
    BEGIN
      pos2 = intlen;
    END
 
    retstring = SUBSTRING (lstring FROM pos1 FOR (pos2 - 1));
    pos1 = pos2 + pos1;
 
    suspend;
  END
END;
 
 ^

ALTER PROCEDURE VALE_DOC_PRG (PNDOC INTEGER,
PTIPO CHAR(3) CHARACTER SET NONE,
PCOD_EMPRESA INTEGER)
RETURNS (TIPO CHAR(4) CHARACTER SET NONE,
NDOC INTEGER,
TIPO_VENDA CHAR(3) CHARACTER SET NONE,
COD_EMPRESA INTEGER,
DATA TIMESTAMP,
VALOR_VALE DOUBLE PRECISION,
QUANT_VALE DOUBLE PRECISION)
AS 
begin
  /* Procedure Text */
  select 'VALE' as tipo, coalesce(fp.nrequisicao, 0) ndoc, coalesce(fp.tpdocs, '') tipo, fp.cod_empresa, fp.data_mov,
  sum((-1)*coalesce(fp.valordoc, 0)) valor_vale,
  count(distinct(fp.rec_numvend)) quant_dev from formpagamento fp
  inner join recibos rec on rec.nrecibo = fp.rec_numvend and rec.cod_empresa = fp.cod_empresa and rec.prg_fid = 'S'
  inner join controles ctr on ctr.codigo_ctrl = fp.cod_controle and ctr.codigo_emp = fp.cod_empresa
  where fp.nrequisicao = :pndoc and fp.tpdocs = :ptipo and fp.cod_empresa = :pcod_empresa
  and fp.ativo = 1 and fp.rec_tipvend = 'REC' and fp.recibo = 'S'
  group by 1, 2, 3, 4, 5
  into :tipo, :ndoc, :tipo_venda, :cod_empresa, :data, :valor_vale, :quant_vale;
  suspend;
end ^

ALTER PROCEDURE VINC_HIST_PROD (CODEMPRESA INTEGER)
RETURNS (RESULT VARCHAR(10) CHARACTER SET NONE)
AS 
  declare variable gr integer;
  declare variable cd char(6);
  declare variable id integer;
begin

  /* obtendo dados diretamenta da nota ou da venda*/
  for

  select s.seqid, nfi.grupo_prod, nfi.cod_prod grupo_cod from (
    select he.* from hist_estoque_diario he
      left join produtos pr on he.grupo_prod = pr.grupo_prod and he.cod_prod = pr.cod_prod and he.cod_empresa = pr.cod_empresa
      where pr.grupo_prod is null and he.cod_empresa = :codempresa
    ) as s -- s: sem vinculo
    left join notafiscal nf on nf.num_nf = s.numero and trim(s.tipor) = 'NF' and nf.cod_empresa = s.cod_empresa
      and nf.cod_cliente = s.cod_cliente and nf.natureza_nf = 'E'
    left join notafiscal_item nfi on nfi.cod_nf = nf.cod_nf and nfi.cod_empresa = nf.cod_empresa and nfi.nitem = s.nitem
    left join produtos_alteracoes pa on pa.descr_prod_anterior = nfi.descricao_item
    where trim(s.tipor) = 'NF'
  
    union all
    
    select s.seqid, pvp.grupo_prod, pvp.cod_prod from (
      select he.* from hist_estoque_diario he
      left join produtos pr on he.grupo_prod = pr.grupo_prod and he.cod_prod = pr.cod_prod and he.cod_empresa = pr.cod_empresa
      where pr.grupo_prod is null and he.cod_empresa = :codempresa
    ) as s -- s: sem vinculo
    left join pedvenda pv on pv.nped = s.numero and pv.tipo = trim(s.tipor) and pv.cod_empresa = s.cod_empresa
    left join pedvenda_prod pvp on pvp.nped = pv.nped and pvp.tipo = pv.tipo and pvp.cod_empresa = pv.cod_empresa
      and pvp.nitem = s.nitem and pvp.quant_ped_item = s.qtde and pvp.vlun_ped_item = s.valor_unit
    inner join produtos_alteracoes pa on pa.descr_prod_anterior = pvp.descr_prod_ped
      and pa.grupo_prod = pvp.grupo_prod and pa.cod_prod = pvp.cod_prod and pa.cod_empresa = pvp.cod_empresa
    where trim(s.tipor) in ('REQ', 'OS')

  into :id, :gr, :cd
  do
  begin

    if (trim(coalesce(cd, '')) <> '') then
    begin

      update hist_estoque_diario h set
        h.grupo_prod_old = h.grupo_prod, h.cod_prod_old = h.cod_prod,
        h.grupo_prod = :gr, h.cod_prod = :cd
        where h.tipo = 'P' and h.seqid = :id and h.cod_empresa = :codempresa;

      --newprod = gr||'-'||cd;

      --suspend;
    end

  end

  /* Atualizando outros registros que nao tenham referencia como acima, mas que apoos o update foi gravado o os campos old*/
  for
    select distinct s.seqid, h.grupo_prod, h.cod_prod from (
      select he.* from hist_estoque_diario he
      left join produtos pr on he.grupo_prod = pr.grupo_prod and he.cod_prod = pr.cod_prod and he.cod_empresa = pr.cod_empresa
      where pr.grupo_prod is null and he.cod_empresa = :codempresa
      ) as s -- s: sem vinculo
    inner join hist_estoque_diario h on h.grupo_prod_old = s.grupo_prod and h.cod_prod_old = s.cod_prod
             
  into :id, :gr, :cd
  do
  begin
    update hist_estoque_diario h set
      h.grupo_prod_old = h.grupo_prod, h.cod_prod_old = h.cod_prod,
      h.grupo_prod = :gr, h.cod_prod = :cd
      where h.tipo = 'P' and h.seqid = :id and h.cod_empresa = :codempresa;

    --newprod = gr||'-'||cd;

    --suspend;
  end

  /* obtendo dados da tabela de alteracao de codigo e descricao dos produtos */
  for
    select distinct s.seqid, pa.grupo_prod, pa.cod_prod from (
      select he.* from hist_estoque_diario he
      left join produtos pr on he.grupo_prod = pr.grupo_prod and he.cod_prod = pr.cod_prod and he.cod_empresa = pr.cod_empresa
      where pr.grupo_prod is null and he.cod_empresa = :codempresa
      ) as s -- s: sem vinculo
      inner join produtos_alteracoes pa on pa.valor_anterior = s.grupo_prod||'|'||trim(s.cod_prod)||'|'
        and pa.grupo_prod||'|'||trim(pa.cod_prod)||'|' <> pa.valor_anterior
        and pa.cod_empresa = s.cod_empresa and s.data >= pa.data_ini and s.data <= pa.data_alteracao      

  into :id, :gr, :cd
  do
  begin
    update hist_estoque_diario h set
      h.grupo_prod_old = h.grupo_prod, h.cod_prod_old = h.cod_prod,
      h.grupo_prod = :gr, h.cod_prod = :cd
      where h.tipo = 'P' and h.seqid = :id and h.cod_empresa = :codempresa;

    --newprod = gr||'-'||cd;

    --suspend;
  end

  /* Atualizando outros registros que nao tenham referencia como acima, mas que apoos o update foi gravado o os campos old*/
  for
    select distinct s.seqid, h.grupo_prod, h.cod_prod from (
      select he.* from hist_estoque_diario he
      left join produtos pr on he.grupo_prod = pr.grupo_prod and he.cod_prod = pr.cod_prod and he.cod_empresa = pr.cod_empresa
      where pr.grupo_prod is null and he.cod_empresa = :codempresa
      ) as s -- s: sem vinculo
    inner join hist_estoque_diario h on h.grupo_prod_old = s.grupo_prod and h.cod_prod_old = s.cod_prod
             
  into :id, :gr, :cd
  do
  begin
    update hist_estoque_diario h set
      h.grupo_prod_old = h.grupo_prod, h.cod_prod_old = h.cod_prod,
      h.grupo_prod = :gr, h.cod_prod = :cd
      where h.tipo = 'P' and h.seqid = :id and h.cod_empresa = :codempresa;

    --newprod = gr||'-'||cd;

    --suspend;
  end

  /* o que restou que os updates acima nao conseguiram fazer */
  for
    select distinct s.seqid, hd.grupo_at, hd.cod_at from (
      select he.* from hist_estoque_diario he
      left join produtos pr on he.grupo_prod = pr.grupo_prod and he.cod_prod = pr.cod_prod and he.cod_empresa = pr.cod_empresa
      where pr.grupo_prod is null and he.cod_empresa = :codempresa
      ) as s -- s: sem vinculo
      inner join sp_hist_prod_datas(s.grupo_prod, s.cod_prod, s.cod_empresa) hd on s.data >= hd.data_ini and s.data <= hd.data_fim
                
  into :id, :gr, :cd
  do
  begin
    update hist_estoque_diario h set
      h.grupo_prod_old = h.grupo_prod, h.cod_prod_old = h.cod_prod,
      h.grupo_prod = :gr, h.cod_prod = :cd
      where h.tipo = 'P' and h.seqid = :id and h.cod_empresa = :codempresa;

    --newprod = gr||'-'||cd;

    --suspend;
  end

  result = 'OK';
  suspend;
end ^

ALTER PROCEDURE VOLTA_ESTOQUE (VGRUPO INTEGER,
VCOD_PROD CHAR(6) CHARACTER SET NONE,
QUANT DOUBLE PRECISION,
VESTS DOUBLE PRECISION,
VESTM DOUBLE PRECISION,
VESTC DOUBLE PRECISION,
VDATA TIMESTAMP,
COD_EMPRESA INTEGER)
AS 
BEGIN
  UPDATE PRODUTOS SET EST_F = EST_F+:QUANT,ESTS = ESTS+:VESTS,
  ESTM = ESTM+:VESTM,ESTC = ESTC+:VESTC,
  DT_ULT_VND = DT_ULT_VNDA  WHERE GRUPO_PROD = :VGRUPO AND 
  COD_PROD = :VCOD_PROD and cod_empresa = :cod_empresa and ativo=1;
END ^

ALTER PROCEDURE VOLTA_ESTOQUE_GRADE (VGRUPO INTEGER,
VCOD_PROD CHAR(6) CHARACTER SET NONE,
VCOD_GRADE INTEGER,
QUANT DOUBLE PRECISION,
COD_EMPRESA INTEGER)
AS 
BEGIN
  UPDATE COD_GRADE_PROD SET QTDE = QTDE+:QUANT WHERE GRUPO_PROD = :VGRUPO AND 
  COD_PROD = :VCOD_PROD AND COD_GRADE = :VCOD_GRADE and COD_EMPRESA = :COD_EMPRESA;
END ^
