/* Triggers only will work for SQL triggers */
CREATE TRIGGER TI_AGENDAMENTO_BI0 FOR AGENDAMENTO 
ACTIVE BEFORE INSERT POSITION 0 
as
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (new.DATA_CADASTRO is null) then
    select CURRENT_D
    from SP_CURRENT_TS(new.COD_EMPRESA)
      into new.DATA_CADASTRO;

  update CLIENTES
  set DATA_AGENDADA = new.DATA_AGENDADA
  where COD_CLIENTE = new.COD_CLIENTE and
        COD_EMPRESA = new.COD_EMPRESA;
  if ((coalesce(new.CODMOD_POTVEIC, 0)) <> 0) then
    update CLIENTES
    set MODELO_POTVEICCP = (select TIPMODELO.DESCRICAO
                            from TIPMODELO
                            where TIPMODELO.CODIGO = new.CODMOD_POTVEIC and
                                  TIPMODELO.COD_EMPRESA = new.COD_EMPRESA)
    where COD_CLIENTE = new.COD_CLIENTE and
          COD_EMPRESA = new.COD_EMPRESA;
  if (coalesce((select COD_VENDEDORV
                from CLIENTES
                where COD_CLIENTE = new.COD_CLIENTE and
                      COD_EMPRESA = new.COD_EMPRESA), 0) = 0) then
    update CLIENTES
    set COD_VENDEDORV = new.COD_VENDEDOR
    where COD_CLIENTE = new.COD_CLIENTE and
          COD_EMPRESA = new.COD_EMPRESA;
end ^

CREATE TRIGGER TI_AGENDAMENTO_AU0 FOR AGENDAMENTO 
ACTIVE AFTER UPDATE POSITION 0 
AS
begin
  if (old.data_agendada <> new.data_agendada) then
    update clientes set data_agendada = new.data_agendada where cod_cliente = new.cod_cliente and cod_empresa = new.cod_empresa;

  if (old.codmod_potveic <> new.codmod_potveic) then
  begin
  if ((coalesce(new.codmod_potveic,0)) <> 0) then
    update clientes set MODELO_POTVEICCP = (select tipmodelo.descricao from tipmodelo where
    tipmodelo.codigo = new.codmod_potveic and tipmodelo.cod_empresa = new.cod_empresa) where cod_cliente = new.cod_cliente and cod_empresa = new.cod_empresa;
  end
end ^

