END ^

CREATE TRIGGER TI_BAIXA_CREDITOS_VL_P_EST FOR BAIXA_CREDITOS 
ACTIVE BEFORE INSERT POSITION 0 
AS
begin
  new.valor_para_estorno = new.valor_quitado;      
  new.valor_para_estorno_ctb = coalesce(new.vl_contabil, 0);

  if (new.tp_operacao = 'T') then
    new.valor_para_estorno = new.valor_c;
  else if (coalesce(new.valor_c, 0) < coalesce(new.valor_quitado, 0)) then
    new.valor_para_estorno = new.valor_c;
  
  if (coalesce(new.vl_contabil, 0) > coalesce(new.valor_quitado, 0)) then
    new.valor_para_estorno_ctb = new.valor_quitado;
end ^

CREATE TRIGGER TR_BALANCO_PRODUTOS_GRADE FOR BALANCO_PRODUTOS 
ACTIVE AFTER UPDATE OR DELETE POSITION 0 
AS
begin
  /* Trigger text */
  if (deleting) then
  begin
    delete from cod_grade_balanco
    where grupo_prod = old.grupo_prod
    and cod_prod = old.cod_prod
    and cod_empresa = old.cod_empresa;
  end
  else if (updating) then
  begin
    if (coalesce(new.qtde_prod, 0) <= 0) then
    begin
      delete from cod_grade_balanco
      where grupo_prod = new.grupo_prod
      and cod_prod = new.cod_prod
      and cod_empresa = new.cod_empresa;
    end
  end
end;
 
 ^

