    AND COD_EMPRESA = old.cod_empresa;
  end
end;
 
 ^

CREATE TRIGGER TR_BOLETAS_ENV_EMAIL_WHAT FOR BOLETAS 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
begin
  /* Trigger text */
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (inserting) then
  begin
    if (trim(coalesce(new.env_whatsapp_bol, '')) = 'S') then
    begin
      INSERT INTO ENV_DOC
      (NUM_DOC, COD_EMPRESA, TIPO_ENV, DATA_ENV, COD_USUARIO)
      VALUES ('BOL_' || new.n_seq_bol, new.cod_empresa, 'W', new.data_whatsapp_bol, new.cod_us_whatsapp_bol);

      new.env_whatsapp_bol    = null;
      new.data_whatsapp_bol   = null;
      new.cod_us_whatsapp_bol = null;
    end

    if (trim(coalesce(new.env_email_bol, '')) = 'S') then
    begin
      INSERT INTO ENV_DOC
      (NUM_DOC, COD_EMPRESA, TIPO_ENV, DATA_ENV, COD_USUARIO)
      VALUES ('BOL_' || new.n_seq_bol, new.cod_empresa, 'E', new.data_email_bol, new.cod_us_email_bol);

      new.env_email_bol       = null;
      new.data_email_bol      = null;
      new.cod_us_email_bol    = null;
    end
  end
  else if (updating) then
  begin
    if ((trim(coalesce(old.env_whatsapp_bol, '')) <> trim(coalesce(new.env_whatsapp_bol, '')))
        and (trim(coalesce(new.env_whatsapp_bol, '')) = 'S')) then
    begin
      INSERT INTO ENV_DOC
      (NUM_DOC, COD_EMPRESA, TIPO_ENV, DATA_ENV, COD_USUARIO)
      VALUES ('BOL_' || new.n_seq_bol, new.cod_empresa, 'W', new.data_whatsapp_bol, new.cod_us_whatsapp_bol);

      new.env_whatsapp_bol    = null;
      new.data_whatsapp_bol   = null;
      new.cod_us_whatsapp_bol = null;
    end
    else if ((trim(coalesce(old.env_whatsapp_bol, '')) <> trim(coalesce(new.env_whatsapp_bol, '')))
        and  (  (trim(coalesce(new.env_whatsapp_bol, 'N')) = 'N') )  ) then
    begin
      DELETE FROM ENV_DOC
      WHERE NUM_DOC = 'BOL_' || new.n_seq_bol
      AND COD_EMPRESA = new.cod_empresa
      AND TIPO_ENV = 'W';

      new.env_whatsapp_bol    = null;
      new.data_whatsapp_bol   = null;
      new.cod_us_whatsapp_bol = null;
    end

    if ((trim(coalesce(old.env_email_bol, '')) <> trim(coalesce(new.env_email_bol, '')))
        and (trim(coalesce(new.env_email_bol, '')) = 'S')) then
    begin
      INSERT INTO ENV_DOC
      (NUM_DOC, COD_EMPRESA, TIPO_ENV, DATA_ENV, COD_USUARIO)
      VALUES ('BOL_' || new.n_seq_bol, new.cod_empresa, 'E', new.data_email_bol, new.cod_us_email_bol);

      new.env_email_bol       = null;
      new.data_email_bol      = null;
      new.cod_us_email_bol    = null;
    end
    else if ((trim(coalesce(old.env_email_bol, '')) <> trim(coalesce(new.env_email_bol, '')))
        and  (  (trim(coalesce(new.env_email_bol, 'N')) = 'N') )   )  then
    begin
      DELETE FROM ENV_DOC
      WHERE NUM_DOC = 'BOL_' || new.n_seq_bol
      AND COD_EMPRESA = new.cod_empresa
      AND TIPO_ENV = 'E';

      new.env_email_bol       = null;
      new.data_email_bol      = null;
      new.cod_us_email_bol    = null;
    end
  end
end;
 
 ^

CREATE TRIGGER TI_CAMPOSNF_CODIGO FOR CAMPOSNF 
ACTIVE BEFORE INSERT POSITION 0 
AS
