CREATE TRIGGER TR_CLIENTES_EC FOR CLIENTES 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
  DECLARE VARIABLE ECOMMERCE INTEGER;
  DECLARE VARIABLE VSINC_ECOMMERCE VARCHAR(1);
  DECLARE VARIABLE IDCOMMERCE INTEGER; 
begin
  /* Trigger text */
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit;

  SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
  WHERE CONFIG_SISTEMA.CHAVE = 'e-commerce_hab'
  AND CONFIG_SISTEMA.COD_EMPRESA = NEW.COD_EMPRESA INTO: ECOMMERCE;

  SELECT CASE WHEN (CUPOM_DESCONTO_EC.ID > 0) THEN 'S' ELSE 'N' END SINC_ECOMMERCE,
  CLIENTES.ID_COMMERCE FROM CLIENTES
  INNER JOIN CUPOM_DESCONTO_EC ON
    CUPOM_DESCONTO_EC.COD_CLIENTE = CLIENTES.COD_CLIENTE
    AND CUPOM_DESCONTO_EC.COD_EMPRESA = CLIENTES.COD_EMPRESA
    AND CUPOM_DESCONTO_EC.CODIGO_CUPOM = CLIENTES.CPFCGC
  WHERE CLIENTES.COD_CLIENTE = NEW.COD_CLIENTE
  AND CLIENTES.COD_EMPRESA = NEW.COD_EMPRESA INTO :VSINC_ECOMMERCE, :IDCOMMERCE;

  if ((COALESCE(IDCOMMERCE, 0) <= 0) and (COALESCE(ECOMMERCE, 0) <= 0)) then
    exit;

  if ((updating) and (COALESCE(VSINC_ECOMMERCE, 'N') = 'S')) then
  begin
      execute statement
       'update cupom_desconto_ec set
          cupom_desconto_ec.cod_cliente = '||new.cod_cliente||',
          cupom_desconto_ec.cod_empresa = '||new.cod_empresa||',
          cupom_desconto_ec.codigo_cupom = '''||new.cpfcgc||'''
        where cupom_desconto_ec.cod_cliente = '||old.cod_cliente||'
        and cupom_desconto_ec.cod_empresa = '||old.cod_empresa||'
        and cupom_desconto_ec.codigo_cupom = '''||old.cpfcgc||''';';
  end
end;
 
 ^

