CREATE TRIGGER TI_CL_COM_CONTR_PROD_SERV_VLCTR FOR CLIENTES_COM_CONTRATO 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
  DECLARE VARIABLE VSERV T_VL_TODOS;
  DECLARE VARIABLE VPROD T_VL_TODOS;
begin
  /* Trigger text */
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (coalesce(new.cod_servico, 0) > 0) then
    exit;

  if (coalesce(new.assinatura_vindi_id, 0) > 0) then
    exit;

  select sum(coalesce(qtde, 0) * coalesce(valor_un, 0)) from clientes_com_contrato_serv
  where cod_contrato = new.cod_contrato
  and cod_empresa = new.cod_empresa
    into :vserv;

  vserv = coalesce(:vserv, 0);

  select sum(coalesce(qtde, 0) * coalesce(valor_un, 0)) from clientes_com_contrato_prod
  where cod_contrato = new.cod_contrato
  and cod_empresa = new.cod_empresa
    into :vprod;

  vprod = coalesce(vprod, 0);

  if (coalesce(vserv, 0) + coalesce(vprod, 0) > 0) then
    new.valor_contrato = Round(coalesce(:vserv, 0) + coalesce(:vprod, 0), 2);
  else
    new.valor_contrato = 0;

  if (coalesce(vprod, 0) > 0) then
    new.valor_prod = Round(coalesce(vprod, 0), 2);
  else
    new.valor_prod = 0;

  if (coalesce(vserv, 0) > 0) then
    new.valor_serv = Round(coalesce(vserv, 0), 2);
  else
    new.valor_serv = 0;    
end ^

