CREATE TRIGGER TI_CL_COM_CONTR_SERV_VLCTR FOR CLIENTES_COM_CONTRATO_SERV 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
  DECLARE VARIABLE VDESCR_SERV VARCHAR(75);
  DECLARE VARIABLE VDESCR_CONTRATO VARCHAR(75);
begin
  /* Trigger text */
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  update clientes_com_contrato set ind_inclalt = ind_inclalt
  where cod_contrato = new.cod_contrato
  and cod_empresa = new.cod_empresa;

  select coalesce(clientes_com_contrato.descr_contrato, '') from clientes_com_contrato
  where clientes_com_contrato.cod_contrato = new.cod_contrato
  and clientes_com_contrato.cod_empresa = new.cod_empresa
    into :vdescr_contrato;

  if (trim(coalesce(vdescr_contrato, '')) = '') then
  begin
    select tipo_servico.desc_servico from tipo_servico
    where tipo_servico.cod_servico = new.cod_servico
	  into :vdescr_serv;

    if (trim(coalesce(vdescr_serv, '')) <> '') then
    begin
	  update clientes_com_contrato set descr_contrato = trim(coalesce(:vdescr_serv, ''))
	  where cod_contrato = new.cod_contrato
	  and cod_empresa = new.cod_empresa;
    end
  end
end ^

