CREATE TRIGGER COD_BARRA_AIUD_CODBAR_ETI FOR COD_BARRA 
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 0 
AS
  declare variable aexiste smallint;
  declare variable acb_prod varchar(20);
  declare variable acb_cb varchar(20);
begin
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
     exit;
  if ((inserting) or ((updating) and ( old.cod_barra <> new.cod_barra))) then
  begin
    select count(cod_prod) from produtos pr
      where pr.grupo_prod = new.grupo_prod and pr.cod_prod = new.cod_prod and
        pr.cod_empresa = new.cod_empresa and pr.num_fab_prod = new.cod_barra
      into :aexiste;

    if (coalesce(aexiste,0) > 0) then
      exit;

    update produtos pr set pr.cod_barra_eti = new.cod_barra
      where pr.grupo_prod = new.grupo_prod and pr.cod_prod = new.cod_prod and
        pr.cod_empresa = new.cod_empresa;
  end
  else if (deleting) then
  begin
    select first 1 pr.num_fab_prod, cb.cod_barra from produtos pr
      left join cod_barra cb on pr.grupo_prod = cb.grupo_prod and pr.cod_prod = cb.cod_prod and
        pr.cod_empresa = cb.cod_empresa and
        pr.num_fab_prod <> cb.cod_barra and cb.cod_barra <> old.cod_barra
      where pr.grupo_prod = old.grupo_prod and pr.cod_prod = old.cod_prod and
        pr.cod_empresa = old.cod_empresa
        into :acb_prod, acb_cb;

    if (coalesce(acb_cb,'') = '') then
      acb_cb = acb_prod;
      
    update produtos pr set pr.cod_barra_eti = :acb_cb
      where pr.grupo_prod = old.grupo_prod and pr.cod_prod = old.cod_prod and
        pr.cod_empresa = old.cod_empresa;
  end
end
 
 ^

