CREATE TRIGGER TR_COD_GRADE_BALANCO_GRADE FOR COD_GRADE_BALANCO 
ACTIVE AFTER DELETE POSITION 0 
AS
  declare variable vqtdecont double precision default 00000.00;
  declare variable vqtdedif  double precision default 00000.00;
begin
  /* Trigger text */
  if (deleting) then
  begin
    if (coalesce(old.cod_grade , 0) > 0) then
    begin
      select sum(coalesce(qtde, 0)) qtde, sum(coalesce(qtd_dif_bal, 0)) qtd_dif_bal from cod_grade_balanco
      where grupo_prod = old.grupo_prod
      and cod_prod = old.cod_prod
      and cod_empresa = old.cod_empresa
      and cod_grade > 0 into :vqtdecont, :vqtdedif;

      update balanco_produtos set qtde_prod = coalesce(:vqtdecont, 0), qtd_dif_bal = coalesce(:vqtdedif, 0)
      where grupo_prod = old.grupo_prod
      and cod_prod = old.cod_prod
      and cod_empresa = old.cod_empresa;
    end
  end
end;
 
 ^

