CREATE TRIGGER TI_COM_FAT_CLIENTES FOR COM_FAT 
ACTIVE AFTER INSERT OR UPDATE POSITION 0 
AS
  DECLARE VARIABLE vFaturamento CHAR(1);
  DECLARE VARIABLE vCodVersaoEst INTEGER;
  DECLARE VARIABLE vCor VARCHAR(10);
  DECLARE VARIABLE vAnoFab INTEGER;
  DECLARE VARIABLE vAnoMod INTEGER;
  DECLARE VARIABLE vDescricao VARCHAR(60);
  DECLARE VARIABLE vCodVend INTEGER;
  DECLARE VARIABLE vDataVend TIMESTAMP;
begin
    IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
       exit;

    if (coalesce(new.TIPO_VENDA_V, '') <> 'N') then
        exit;

    if (coalesce(new.NATUREZA, '') <> 'S') then
        exit;

    SELECT FATURAMENTO FROM NAT_OP WHERE CODIGO_NOP = new.NATOP_V
    into: vFaturamento;

    if (coalesce(vfaturamento, 'N') <> 'S') then
      exit;

    if ((trim(coalesce(old.status_v, '')) <> trim(coalesce(new.status_v, '')))) then
    begin
        if (trim(coalesce(new.status_v, '')) = 'FECHADO') then
        begin
            SELECT EST.VERSAOEST, SUBSTRING(TRIM(EST.COREST) FROM 1 FOR 10) COREST, EST.ANO_FABEST, EST.ANO_MODEST, TP.DESCRICAO FROM EST_MOTO EST
              INNER JOIN TIPMODELO TP ON TP.CODIGO = EST.VERSAOEST AND TP.COD_EMPRESA = EST.COD_EMPRESA
              WHERE EST.CHASSI_C = NEW.CHASSIV AND EST.CODIGO = NEW.COD_ESTMOTO AND EST.COD_EMPRESA = NEW.COD_EMPRESA
            INTO : VCODVERSAOEST, VCOR, VANOFAB, VANOMOD, VDESCRICAO;

            UPDATE CLIENTES SET COD_VENDEDORV = new.COVEND_V, DATA_ULT_COMPRAV = new.DATA_VEN,
              CODMODELO_POTVEIC = :vCodVersaoEst, COR_POTVEIC = :vCor,
              ANO_POTVEIC = :vAnoFab, ANOMOD_POTVEIC = :vAnoMod, MODELO_POTVEIC = :vDescricao,
              COD_VENDEDORV_ANT = COD_VENDEDORV, DATA_ULT_COMPRAV_ANT = DATA_ULT_COMPRAV,
              CODMODELO_POTVEIC_ANT = CODMODELO_POTVEIC, COR_POTVEIC_ANT = COR_POTVEIC,
              ANO_POTVEIC_ANT = ANO_POTVEIC, ANOMOD_POTVEIC_ANT = ANOMOD_POTVEIC, MODELO_POTVEIC_ANT = MODELO_POTVEIC
            WHERE COD_CLIENTE = new.CLIENTES_V AND COD_EMPRESA = new.COD_EMPRESA;
        end
        else if ((trim(coalesce(new.status_v, '')) = 'ABERTO') or (trim(coalesce(new.status_v, '')) = 'CANCELADO')) then
        begin
            SELECT COD_VENDEDORV_ANT, DATA_ULT_COMPRAV_ANT,
             CODMODELO_POTVEIC_ANT, COR_POTVEIC_ANT,
             ANO_POTVEIC_ANT, ANOMOD_POTVEIC_ANT, MODELO_POTVEIC_ANT FROM CLIENTES CL
             WHERE COD_CLIENTE = new.CLIENTES_V AND COD_EMPRESA = new.COD_EMPRESA
            into: vcodvend, vdatavend, vcodversaoest, vcor, vanofab, vanomod, vdescricao;

            UPDATE CLIENTES SET COD_VENDEDORV = COD_VENDEDORV_ANT, DATA_ULT_COMPRAV = DATA_ULT_COMPRAV_ANT,
              CODMODELO_POTVEIC = CODMODELO_POTVEIC_ANT, COR_POTVEIC = COR_POTVEIC_ANT,
              ANO_POTVEIC = ANO_POTVEIC_ANT, ANOMOD_POTVEIC = ANOMOD_POTVEIC_ANT, MODELO_POTVEIC = MODELO_POTVEIC_ANT,
              COD_VENDEDORV_ANT = null, DATA_ULT_COMPRAV_ANT = null,
              CODMODELO_POTVEIC_ANT = null, COR_POTVEIC_ANT = null,
              ANO_POTVEIC_ANT = null, ANOMOD_POTVEIC_ANT = null, MODELO_POTVEIC_ANT = null
            WHERE COD_CLIENTE = new.CLIENTES_V AND COD_EMPRESA = new.COD_EMPRESA;
        end
    end
end ^

CREATE TRIGGER TI_COM_FAT_ULT_COMPRA FOR COM_FAT 
ACTIVE AFTER INSERT OR UPDATE POSITION 0 
AS
  declare variable vnped integer;
  declare variable vtipo char(3);
  declare variable vdata_fech timestamp;
  declare variable vvalor_total double precision default 00000.00;
  declare variable vvenda char(1);
begin
  /* Trigger text */
  vnped = 0;
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (trim(new.NATUREZA) <> 'S') then
    exit;

  vvenda = 'N';
  select first 1 venda from tipo_vendas where trim(tipo) = 'VEI' and tipo_os = new.tipo_v into :vvenda;

  if (coalesce(vvenda, 'N') <> 'S') then
    exit;

  if (inserting) then
  begin
    if ((trim(coalesce(old.STATUS_V, '')) <> trim(coalesce(new.STATUS_V, '')))
      and (trim(coalesce(new.STATUS_V, '')) = 'FECHADO')) then
    begin
      update clientes set
        nped_ult_compra = new.N_COMANDO,
        tipo_ult_compra = 'MOT',
        data_ult_compra = new.DATA_FECH,
        valor_ult_compra = new.VALTOT_V
      where cod_cliente = new.CLIENTES_V
      and cod_empresa = new.COD_EMPRESA;
    end
  end
  else if (updating) then
  begin
    if ((trim(coalesce(old.STATUS_V, '')) <> trim(coalesce(new.STATUS_V, '')))
      and (trim(coalesce(new.STATUS_V, '')) = 'FECHADO')) then
    begin
      update clientes set
        nped_ult_compra = new.N_COMANDO,
        tipo_ult_compra = 'MOT',
        data_ult_compra = new.DATA_FECH,
        valor_ult_compra = new.VALTOT_V
      where cod_cliente = new.CLIENTES_V
      and cod_empresa = new.COD_EMPRESA;
    end
    else if ((trim(coalesce(old.STATUS_V, '')) <> trim(coalesce(new.STATUS_V, '')))
      and (trim(coalesce(old.STATUS_V, '')) = 'FECHADO')) then
    begin
      select ndoc, tipo, data_fech, valor_total from ret_dados_ult_compra(new.COD_EMPRESA, new.CLIENTES_V)
        into :vnped, :vtipo, :vdata_fech, :vvalor_total;

      if (coalesce(:vnped , 0) > 0) then
      begin
        update clientes set
          nped_ult_compra = :vnped,
          tipo_ult_compra = :vtipo,
          data_ult_compra = :vdata_fech,
          valor_ult_compra = :vvalor_total
        where cod_cliente = new.CLIENTES_V
        and cod_empresa = new.COD_EMPRESA;
      end
      else
      begin
        update clientes set
          nped_ult_compra = null,
          tipo_ult_compra = null,
          data_ult_compra = null,
          valor_ult_compra = null
        where cod_cliente = new.CLIENTES_V
        and cod_empresa = new.COD_EMPRESA;
      end
    end
  end
end;
 
 ^

