CREATE TRIGGER TR_CONTAS_A_PAGAR_FORNECEDOR FOR CONTAS_A_PAGAR 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
  declare variable vnome_cliente varchar(35);
  declare variable vcpfcgc varchar(18);
begin
  /* Trigger text */
