    end
end ^

CREATE TRIGGER CONTAS_A_PAGAR_DESPESAS FOR CONTAS_A_PAGAR 
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 0 
AS
DECLARE VARIABLE  vCodigoEmp Integer;
DECLARE VARIABLE  vCodDespesa Integer;
DECLARE VARIABLE  vObs char(3000);
DECLARE VARIABLE  vDataVenc char(16);
DECLARE VARIABLE  vValorCtpNovo double precision default 00000.00;
DECLARE VARIABLE  vValorCtp double precision default 00000.00;
DECLARE VARIABLE  vValorTotCtp double precision default 00000.00;
DECLARE VARIABLE  vDocCtp char(50);
DECLARE VARIABLE  vDocCtpOrig char(50);
DECLARE VARIABLE  vtotDocNQuitados Integer;
DECLARE VARIABLE  vtotDocCtp Integer;
begin
   if (inserting) then
     exit;

   IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
     exit;

   if (coalesce(old.cod_despesa, 0) <= 0) then
    exit;

   vCodDespesa = old.cod_despesa;
   vCodigoEmp = old.codigo_emp;
   vDocCtpOrig = trim(old.n_doc_ctp);
   if (updating) then
     vValorCtpNovo = new.valor_ctp;
   else
     vValorCtpNovo = old.valor_ctp;
   vObs = '';
   vValorTotCtp = 0;

   for select (substring(cast(trim(n_doc_ctp) as varchar(50)) from 1 for 50))
      n_doc_ctp, valor_ctp,
     (substring(cast(data_venc_ctp as varchar(50)) from 9 for 2)||'/'||
     substring(cast(data_venc_ctp as varchar(50)) from 6 for 2)||'/'||
     substring(cast(data_venc_ctp as varchar(50)) from 1 for 4)) data_venc_ctp from contas_a_pagar
   where codigo_emp = :vCodigoEmp and cod_despesa = :vCodDespesa
   into : vDocCtp, vValorCtp, vDataVenc do
   begin
     if (trim(vObs) = '') then
     begin
       if (trim(vDocCtp) = trim(vDocCtpOrig)) then
         vObs = trim(vDocCtp) ||'   '|| trim(vDataVenc) ||'   '|| 'R$ '|| replace(cast(trunc(vValorCtpNovo, 4) as numeric(15,2)), '.', ',');
       else
         vObs = trim(vDocCtp) ||'   '|| trim(vDataVenc) ||'   '|| 'R$ '|| replace(cast(trunc(vValorCtp, 4) as numeric(15,2)), '.', ',');
     end
     else
     begin
       if (trim(vDocCtp) = trim(vDocCtpOrig)) then
       begin
         if (deleting) then
           vObs = trim(vObs);
         else
           vObs = trim(vObs) || ascii_char(13) || trim(vDocCtp) ||'   '|| trim(vDataVenc) ||'   '|| 'R$ '|| replace(cast(trunc(vValorCtpNovo, 4) as numeric(15,2)), '.', ',');
       end
       else
         vObs = trim(vObs) || ascii_char(13) || trim(vDocCtp) ||'   '|| trim(vDataVenc) ||'   '|| 'R$ '|| replace(cast(trunc(vValorCtp, 4) as numeric(15,2)), '.', ',');
     end
     if (trim(vDocCtp) = trim(vDocCtpOrig)) then
     begin
      if (deleting) then
        vValorTotCtp = trunc(vValorTotCtp, 4);
      else
        vValorTotCtp = trunc(vValorTotCtp, 4) + trunc(vValorCtpNovo, 4);
     end
     else
       vValorTotCtp = trunc(vValorTotCtp, 4) + trunc(vValorCtp, 4);
   end

   if ((coalesce(old.status_ctp, '') <> coalesce(new.status_ctp, ''))
     or (coalesce(old.valor_ctp, 0) <> coalesce(new.valor_ctp, 0))) then
   begin
       select count(*) tot_n_quitados from contas_a_pagar
       where codigo_emp = :vCodigoEmp and cod_despesa = :vCodDespesa
       and (coalesce(trim(status_ctp), '') <> 'QUITADO')
        into : vtotDocNQuitados;
    
       if (vtotDocNQuitados > 0) then
         update despesas_veic d set d.valor_despesa = :vValorTotCtp,
          d.obs = :vObs, d.status_despesa = 'PENDENTE' where d.cod_despesa = :vCodDespesa and d.cod_empresa = :vCodigoEmp;
       else
         update despesas_veic d set d.valor_despesa = :vValorTotCtp,
          d.obs = :vObs, d.status_despesa = 'QUITADA' where d.cod_despesa = :vCodDespesa and d.cod_empresa = :vCodigoEmp;
   end

   if (deleting) then
   begin
       select count(*) tot_doc from contas_a_pagar
       where codigo_emp = :vCodigoEmp and cod_despesa = :vCodDespesa
        into : vtotDocCtp;

      if (vtotDocCtp <= 0) then
        delete from despesas_veic d
        where d.cod_despesa = :vCodDespesa and d.cod_empresa = :vCodigoEmp;
   end
end;
 
 ^

