CREATE TRIGGER CCREDITOS_UP_ITEMCARTA FOR CONTROLE_CREDITOS 
ACTIVE AFTER UPDATE OR DELETE POSITION 0 
as
declare variable vqtd integer;
declare variable vcoditemcarta integer;
declare variable current_ts timestamp;
begin
  if (updating) then
  begin
  if ((trim(coalesce(old.status_c,''))<>trim(coalesce(new.status_c,''))) or
     (old.status_c is null and (not new.status_c is null)))  then
  begin
    if ((trim(coalesce(new.status_c,'')) = 'QUITADO') and (not new.datq_c is null)) then
    begin
      update itens_carta_cred set itens_carta_cred.solucionado='S',
      itens_carta_cred.dt_solucao_cred= coalesce(new.data_baixa,new.datq_c) where itens_carta_cred.cod_cred = new.cod_cred
        and itens_carta_cred.cod_empresa = new.codigo_emp;

      for select itens_carta_cred.cod_itemcarta  from itens_carta_cred
        where itens_carta_cred.cod_cred = new.cod_cred and itens_carta_cred.cod_empresa = new.codigo_emp
        into :vcoditemcarta do
      begin
        select count(itens_carta_cred.cod_itemcarta) from itens_carta_cred
          where itens_carta_cred.cod_itemcarta = :vcoditemcarta
          and itens_carta_cred.cod_empresa=new.codigo_emp and (itens_carta_cred.solucionado='N' or (itens_carta_cred.solucionado is null))
          into :vqtd;
          if ((vqtd is null) or (vqtd = 0)) then
            update itens_carta set itens_carta.dt_solucao=coalesce(new.data_baixa,new.datq_c)
            where itens_carta.codigo = :vcoditemcarta and itens_carta.cod_empresa=new.codigo_emp and itens_carta.versaocarta=1;
      end
    end
    else  if ((trim(coalesce(old.status_c,'')) = 'QUITADO') and (new.status_c is null or (trim(coalesce(new.status_c,'')) = ''))) then
    begin
      update itens_carta_cred set itens_carta_cred.solucionado= null,
      itens_carta_cred.dt_solucao_cred = null where itens_carta_cred.cod_cred = new.cod_cred
        and itens_carta_cred.cod_empresa = new.codigo_emp;

      for select itens_carta_cred.cod_itemcarta  from itens_carta_cred
        where itens_carta_cred.cod_cred = new.cod_cred and itens_carta_cred.cod_empresa = new.codigo_emp
        into :vcoditemcarta do
      begin
        select count(itens_carta_cred.cod_itemcarta) from itens_carta_cred
          where itens_carta_cred.cod_itemcarta = :vcoditemcarta
          and itens_carta_cred.cod_empresa=new.codigo_emp and (itens_carta_cred.solucionado='N' or (itens_carta_cred.solucionado is null))
          into :vqtd;
          if ((not vqtd is null) or (vqtd > 0)) then
            update itens_carta set itens_carta.dt_solucao=null
            where itens_carta.codigo = :vcoditemcarta and itens_carta.cod_empresa=new.codigo_emp and itens_carta.versaocarta=1;
      end
    end
  end
  end
  else if (deleting) then
  begin    
    select CURRENT_D from SP_CURRENT_TS(old.codigo_emp) into :CURRENT_TS;

    for select itens_carta_cred.cod_itemcarta  from itens_carta_cred
      where itens_carta_cred.cod_cred = old.cod_cred and itens_carta_cred.cod_empresa = old.codigo_emp
      into :vcoditemcarta do
    begin
      select count(itens_carta_cred.cod_itemcarta) from itens_carta_cred
        where itens_carta_cred.cod_itemcarta = :vcoditemcarta
        and itens_carta_cred.cod_empresa=old.codigo_emp
        and itens_carta_cred.cod_cred<>old.cod_cred
        and (itens_carta_cred.solucionado='N' or (itens_carta_cred.solucionado is null))
        into :vqtd;
        if ((vqtd is null) or (vqtd = 0)) then
          update itens_carta set itens_carta.dt_solucao= :CURRENT_TS
          where itens_carta.codigo = :vcoditemcarta and itens_carta.cod_empresa=old.codigo_emp and itens_carta.versaocarta=1;
    end
    delete from itens_carta_cred  where itens_carta_cred.cod_cred = old.cod_cred
      and itens_carta_cred.cod_empresa = old.codigo_emp;
  end
end
 
 ^

CREATE TRIGGER TI_EVD_PAF_CP FOR CUPOM 
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 0 
AS                                      
  declare variable vcodempresa integer; 
  declare variable vtiporegistro varchar(3);
  declare variable vdata timestamp;
  declare variable vcamposchave varchar(100);
  declare variable vvalorechave varchar(100);
  declare variable vmd5 varchar(256);
  declare variable vacao varchar(1);
begin
  vtiporegistro = 'CP';
  vcamposchave = '|COD_TERMINAL|NSERIEECF|COD_EMPRESA|REGISTRO|CUPOM|';
  if (inserting) then
  begin              
    vcodempresa =  new.cod_empresa;
    vdata = new.data;
    vvalorechave = '|'||new.cod_terminal||'|'||new.nserieecf||'|'||new.cod_empresa||'|'||new.registro||'|'||new.cupom||'|';
    vmd5 = new.md5;
    vacao = 'I';
    execute procedure sp_evd_paf(vcodempresa, vtiporegistro, vdata, vcamposchave, vvalorechave, substring(vmd5 from 1 for 32), vacao);
  end
  else if ((deleting) or (updating)) then
  begin              
    vcodempresa =  old.cod_empresa;
    vdata = old.data;
    vvalorechave = '|'||old.cod_terminal||'|'||old.nserieecf||'|'||old.cod_empresa||'|'||old.registro||'|'||old.cupom||'|';
    vmd5 = old.md5;
    vacao = 'D';
    if ((deleting) or (coalesce(new.md5, '') <> '') and (coalesce(old.md5, '') = '')) then
      execute procedure sp_evd_paf(vcodempresa, vtiporegistro, vdata, vcamposchave, vvalorechave, substring(vmd5 from 1 for 32), vacao);
  end
END
 
 ^

CREATE TRIGGER CUPOM2_BIU_CALC_IMP FOR CUPOM2 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
begin
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
     exit;

  if ((old.cst_pis = new.cst_pis) and
      (old.aliq_pis = new.aliq_pis)) then
    exit;

  if ((coalesce(new.aliq_pis, 0) = 0) or (coalesce(new.aliq_cofins, 0) = 0))  then
  begin
    new.aliq_pis = 0;
    new.aliq_cofins = 0;
    new.base_pis = 0;
    new.base_cofins = 0;
    new.valor_pis = 0;
    new.valor_cofins = 0;
    exit;
  end

  if (new.cst_pis in ('01', '02')) then
  begin
    new.base_pis = round(coalesce(new.total,0) + coalesce(new.rat_acres,0) + coalesce(new.perc_acresc,0) -
                         coalesce(new.rat_desc,0) - coalesce(new.perc_desc,0), 2);
    new.base_cofins = new.base_pis;
    new.valor_pis = round( new.base_pis * new.aliq_pis / 100, 2);
    new.valor_cofins = round( new.base_cofins * new.aliq_cofins / 100, 2);
  end
  else if (new.cst_pis = '03') then
  begin
    new.base_pis = round(new.quantidade, 3);
    new.base_cofins = new.base_pis;
    new.valor_pis = round( new.base_pis * new.aliq_pis, 2);
    new.valor_cofins = round( new.base_cofins * new.aliq_cofins, 2);
  end
  else
  begin     
    new.base_pis = 0;
    new.base_cofins = 0;
    new.valor_pis = 0;
    new.valor_cofins = 0;
  end
end ^

