CREATE TRIGGER TR_DTEC_CUPOM_DESCONTO_EC FOR CUPOM_DESCONTO_EC 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
AS 
 DECLARE VARIABLE VSEQID BIGINT; 
 DECLARE VARIABLE CAMPOS_CHAVE VARCHAR(255);
 DECLARE VARIABLE VALORES_CHAVE VARCHAR(255);
 DECLARE VARIABLE VDELETE INTEGER;
begin 
  /* Trigger text */ 
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit; 

  VDELETE = 0; 
  if (deleting) then 
    VDELETE = 1; 

  if ((vdelete > 0) or (coalesce(old.codigo_cupom, '') <> coalesce(new.codigo_cupom, ''))) then 
  begin 
    if (COALESCE(OLD.ID_COMMERCE, 0) <= 0) then 
     exit; 

    if (coalesce(old.codigo_cupom, '') <> coalesce(new.codigo_cupom, '')) then 
     new.ID_COMMERCE = null; 
    SELECT GEN_ID(SEQ_DEL_EC, 1) FROM RDB$DATABASE INTO :VSEQID; 
    CAMPOS_CHAVE =  '|ID|COD_EMPRESA|'; 
    VALORES_CHAVE = '|'||OLD.ID||'|'||OLD.COD_EMPRESA||'|'; 
    INSERT INTO DEL_EC(SEQID, COD_EMPRESA, TABELA, DATA_HORA_ALT_WS, CAMPOS_CHAVE, VALORES_CHAVE, ID_COMMERCE)  
    VALUES(:VSEQID, old.COD_EMPRESA, 'CUPOM_DESCONTO_EC', CURRENT_TIMESTAMP, :CAMPOS_CHAVE, :VALORES_CHAVE, OLD.ID_COMMERCE); 
  end 
  else if ((inserting)or(updating)) then 
  begin 
    NEW.SEQID_EC = (SELECT GEN_ID(SEQ_EC_CUPOM_DESCONTO_EC, 1) FROM RDB$DATABASE); 
  end 
end;
 
