CREATE TRIGGER ATENT_MOTO FOR ENT_MOTO 
ACTIVE BEFORE DELETE POSITION 0 
AS
declare variable stat_nf integer;
BEGIN
  stat_nf = 0;
  select count(NF_TRANSITO.NUM_NOTAT) from NF_TRANSITO
            where old.NUM_NOTA = NF_TRANSITO.num_notaT AND old.COD_EMPRESA = NF_TRANSITO.COD_EMPRESA
            into :stat_nf;
 if (stat_nf > 0) then
 begin
  UPDATE NF_TRANSITO SET NF_TRANSITO.STATUST = '' WHERE old.NUM_NOTA = NF_TRANSITO.num_notaT AND old.COD_EMPRESA = NF_TRANSITO.COD_EMPRESA;
 end
END ^

CREATE TRIGGER ATITEM_NF_ENT FOR ENT_MOTO_ITENS 
ACTIVE BEFORE DELETE POSITION 0 
AS
declare variable stat_nf integer;
BEGIN
  stat_nf = 0;
  select count(NUM_NOTA) from EST_MOTO 
            where EST_MOTO.NUM_NOTA = OLD.num_nota and
            EST_MOTO.CHASSI_C = OLD.CHASSI_C AND EST_MOTO.COD_EMPRESA = OLD.COD_EMPRESA
            into :stat_nf;
 if (stat_nf > 0) then
 begin
  DELETE FROM EST_MOTO WHERE EST_MOTO.num_nota = old.num_nota
  AND EST_MOTO.CHASSI_C = old.CHASSI_C AND EST_MOTO.COD_EMPRESA = old.COD_EMPRESA;
 end
 else
 begin
  select count(NFAQ_US) from MTUSADAS
            where MTUSADAS.NFAQ_US = old.num_nota and
            MTUSADAS.CHASSI_US = old.CHASSI_C AND
            MTUSADAS.COD_EMPRESA = old.COD_EMPRESA
            into :stat_nf;
            if (stat_nf > 0) then
            begin
               DELETE FROM MTUSADAS WHERE MTUSADAS.NFAQ_US = old.num_nota
               AND MTUSADAS.CHASSI_US = old.CHASSI_C
               AND MTUSADAS.COD_EMPRESA = old.COD_EMPRESA;
            end
 end
END ^

