CREATE TRIGGER TI_EQUIPAMENTO_SUGESTAO FOR EQUIPAMENTO 
ACTIVE AFTER INSERT OR UPDATE POSITION 0 
AS
    declare variable vsugservico integer;
    declare variable vusaraparelho char(3);
    declare variable vcodserv integer;
    declare variable vcodsug integer;
    declare variable vcodsugos integer;
    declare variable vinterm integer;
    declare variable vdatacad timestamp;
    declare variable vhoracad char(8);
    declare variable vexistesug integer;  
    declare variable current_ts timestamp;
begin
    IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
        exit;

    if (new.cod_equip <= 0) then
        exit;

    select empresa.dadvap  from empresa
    where empresa.cod_empresa = new.cod_empresa
    into: vusaraparelho;

    if (vusaraparelho <> 'SIM') then
        exit;

    select config_sistema.value1_f from config_sistema
    where config_sistema.chave like 'sug_serv_hab'
    and config_sistema.cod_empresa = new.cod_empresa
    into: vSugServico;

    if (vsugservico <= 0) then
        exit;

    select first 1 sugestaoservico.cod_sug from sugestaoservico
    where sugestaoservico.cod_equip = new.cod_equip and sugestaoservico.cod_empresa = new.cod_empresa
    and coalesce(sugestaoservico.status, '') <> 'CANCELADA'
    into: vExisteSug;

    if (vExisteSug > 0) then
        exit;

    select current_d, current_ts from sp_current_ts(new.cod_empresa)
      into :vDataCad, :current_ts;

    select case when(extract(hour from :current_ts) <=9) then '0'|| extract(hour from :current_ts)
    else extract(hour from :current_ts)
    end ||':'|| case when (extract(minute from :current_ts) <= 9) then
        '0'|| extract(minute from :current_ts)
    else extract(minute from :current_ts) end from rdb$database
    into: vHoraCad;

    for select regras_sug.codigo, regras_sug.interv_mes_serv from regras_sug
    inner join regras_sug_itens on regras_sug_itens.codigo = regras_sug.codigo and regras_sug_itens.cod_empresa = regras_sug.cod_empresa
    where regras_sug_itens.cod_tipo = new.cod_equip and regras_sug_itens.cod_empresa = new.cod_empresa and regras_sug.ativo = 1
    and regras_sug.tipo = 'E'
    into: vCodServ, vInterM do
    begin
        if (vInterM > 0) then
        begin
            select cod from incrementa_codigo(new.cod_empresa, 'SUGESTAOSERVICO') into: vCodSug;

            select cod from incrementa_codigo(new.cod_empresa, 'SUG_OS') into: vCodSugOs;

            INSERT INTO SUG_OS
            (COD_SUG_OS, COD_EMPRESA, COD_EQUIP, COD_VEIC, CHASSI, PLACA, US_CAD, DATA_CAD, HORA_CAD,
            KM, NDOC, TPDOC, COD_SERV_SUG, COD_VENDEDOR, ATIVO)
            VALUES
            (:vCodSugOs, new.cod_empresa, new.cod_equip, null, null, null, new.us_cad, :vDataCad, :vHoraCad,
            null, null, null, :vcodserv, coalesce(new.us_cad, 0), 1);
    
            INSERT INTO SUGESTAOSERVICO
            (COD_SUG, COD_EMPRESA, COD_EQUIP, COD_VEIC, CHASSI, PLACA, COD_SUG_OS, ULT_ATD, DATA, HORA,
            ATIVO, COD_CLIENTE, US_CAD, DATA_CAD, HORA_CAD, NDOC_ANT, TPDOC_ANT, COD_SERV_SUG, DIAS, TIPO)
            VALUES
            (:vCodSug, new.cod_empresa, new.cod_equip, null, null, null, null,
            new.us_cad, (:vDataCad + (:vInterM * 30)), :vHoraCad,
            1, new.cod_prop,  coalesce(new.us_cad, 0), :vDataCad, :vHoraCad,
            null, null, :vcodserv, (:vInterM * 30), 'INTERVALO MESES ENTRE AS REVISOES');
        end
    end
end
 
 ^

