CREATE TRIGGER TI_EST_MOTO_FILA_RESERVA_REORDE FOR EST_MOTO 
ACTIVE BEFORE UPDATE POSITION 0 
AS
  declare variable vPrev1 char(3);
  declare variable vPrev2 char(3);
  declare variable vCodFila integer;
  declare variable vOrdem integer;
  declare variable vreordenar char(1);
begin
    IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
     exit;

    select trim(coalesce(empresa.reordenar_fila_res, 'N')) from empresa
    where empresa.cod_empresa = new.cod_empresa
    into :vreordenar;

    if (trim(vreordenar) <> 'S') then
     exit;

    if ((updating) and  (trim(coalesce(old.status_res, 'N')) = 'S') and (trim(coalesce(old.status_res, 'N')) <> trim(coalesce(new.status_res, 'N')))) then
    begin
         select first 1 ordem, prev_cheg from fila_reserva_veic
         where cod_modelo = new.versaoest and ano_fab = new.ano_fabest and ano_mod = new.ano_modest
         and cod_cor = new.cod_cor and ativo = 1 and coalesce(status_res, 'N') = 'N'
         order by ordem
          into: vordem, vprev1;

         if (vordem > 0) then
         begin
           for select codigo, prev_cheg from fila_reserva_veic
           where cod_modelo = new.versaoest and ano_fab = new.ano_fabest and ano_mod = new.ano_modest
           and cod_cor = new.cod_cor and ordem > :vordem and ativo = 1 and coalesce(status_res, 'N') = 'N'
           order by ordem
            into: vcodfila, vprev2 do
           begin
             update fila_reserva_veic set prev_cheg = :vprev1
             where codigo = :vcodfila and cod_empresa = new.cod_empresa;

             vprev1 = vprev2;
           end
         end
    end
end;
 
 ^

CREATE TRIGGER EST_MOTO_HIST FOR EST_MOTO 
ACTIVE BEFORE DELETE POSITION 0 
AS
begin
  DELETE FROM HIST_ESTMOTO
  WHERE CHASSI_C = old.CHASSI_C AND CODIGO = OLD.CODIGO AND COD_EMPRESA = OLD.COD_EMPRESA;

  DELETE FROM PENDENCIAS_VEIC
  WHERE CHASSI_C = old.CHASSI_C AND CODIGO = OLD.CODIGO AND COD_EMPRESA = OLD.COD_EMPRESA;

  DELETE FROM DESPESAS_VEIC
  WHERE CHASSI_C = old.CHASSI_C AND CODIGO = OLD.CODIGO AND COD_EMPRESA = OLD.COD_EMPRESA;
end ^

CREATE TRIGGER TI_ESTOQUE_DIARIO_VEICULOS FOR EST_MOTO 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
as
  declare variable  pveiculos char(1);
  declare variable  pchassi char(20);
  declare variable current_d timestamp;
begin
  select trim(empresa.VERSAO_VEICULO) from empresa
  where empresa.cod_empresa = new.cod_empresa
  into :pveiculos;

  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
   exit;

  if (trim(pveiculos) <> '4') then
   exit;

  if ((inserting) or (updating)) then
  begin
    if (trim(coalesce(new.status_estoque, '')) = '') then
     new.status_estoque = 'N';
    if (trim(coalesce(new.status_res, '')) = '') then
     new.status_res = 'N';
    if (trim(coalesce(new.status_transdep, '')) = '') then
     new.status_transdep = 'N';
    if (trim(coalesce(new.status_demonst, '')) = '') then
     new.status_demonst = 'N';
    if (trim(coalesce(new.status_canc, '')) = '') then
     new.status_canc = 'N';
    if (trim(coalesce(new.usado_troca, '')) = '') then
     new.usado_troca = 'N';
  end

  if (inserting) then
  begin
    if (trim(coalesce(new.status_estoque, 'N')) = 'S') then
    begin 
      select current_d from sp_current_ts(new.cod_empresa) into :current_d;

      select first 1 coalesce(est.chassi, '') from estoque_diario est
      where est.tipo = 'V' and est.dia = :current_d and est.chassi = new.chassi_c and est.cod_empresa = new.cod_empresa
      into: pchassi;

      if (trim(coalesce(pchassi, '')) = '') then
      begin
          INSERT INTO ESTOQUE_DIARIO (TIPO, SEQID, COD_EMPRESA, DIA, GRUPO_PROD, COD_PROD, COD_GRADE, CHASSI, ESTOQUE, CUSTO_MEDIO, SITUACAO)
          VALUES ('V', (select cod from incrementa_codigo(new.cod_empresa,'ESTOQUE_DIARIO')), new.cod_empresa, :current_d, null, null, null, new.chassi_c, 1, coalesce(new.preco_custo_rep, 0), new.status_uso);
      end
      else
      begin
         UPDATE ESTOQUE_DIARIO SET ESTOQUE = 1
         WHERE TIPO = 'V' AND DIA = :current_d AND CHASSI = new.chassi_c  AND COD_EMPRESA = new.cod_empresa;
      end
    end
  end
  else if (updating) then
  begin     
    select current_d from sp_current_ts(new.cod_empresa) into :current_d;

     select first 1 coalesce(est.chassi, '') from estoque_diario est
     where est.tipo = 'V' and est.dia = :current_d and est.chassi = new.chassi_c and est.cod_empresa = new.cod_empresa
     into: pchassi;

     if ((trim(coalesce(old.status_estoque, 'N')) <> trim(coalesce(new.status_estoque, 'N')))
     and (trim(coalesce(new.status_estoque, 'N')) = 'S')) then
     begin
        if (trim(coalesce(pchassi, '')) = '') then
        begin
           INSERT INTO ESTOQUE_DIARIO (TIPO, SEQID, COD_EMPRESA, DIA, GRUPO_PROD, COD_PROD, COD_GRADE, CHASSI, ESTOQUE, CUSTO_MEDIO, SITUACAO)
           VALUES ('V', (select cod from incrementa_codigo(new.cod_empresa,'ESTOQUE_DIARIO')), new.cod_empresa, :current_d, null, null, null, new.chassi_c, 1, coalesce(new.preco_custo_rep, 0), new.status_uso);
        end
        else
        begin
           UPDATE ESTOQUE_DIARIO SET ESTOQUE = 1
           WHERE TIPO = 'V' AND DIA = :current_d AND CHASSI = new.chassi_c  AND COD_EMPRESA = new.cod_empresa;
        end
     end
     else if ((trim(coalesce(old.status_estoque, 'N')) <> trim(coalesce(new.status_estoque, 'N')))
     and (trim(coalesce(new.status_estoque, 'N')) = 'N')) then
     begin
        if (trim(coalesce(pchassi, '')) = '') then
        begin
           INSERT INTO ESTOQUE_DIARIO (TIPO, SEQID, COD_EMPRESA, DIA, GRUPO_PROD, COD_PROD, COD_GRADE, CHASSI, ESTOQUE, CUSTO_MEDIO, SITUACAO)
           VALUES ('V', (select cod from incrementa_codigo(new.cod_empresa,'ESTOQUE_DIARIO')), new.cod_empresa, :current_d, null, null, null, new.chassi_c, 0, coalesce(new.preco_custo_rep, 0), new.status_uso);
        end
        else
        begin
           UPDATE ESTOQUE_DIARIO SET ESTOQUE = 0
           WHERE TIPO = 'V' AND DIA = :current_d AND CHASSI = new.chassi_c  AND COD_EMPRESA = new.cod_empresa;
        end
     end

  end
  else if (deleting) then
  begin  
    select current_d from sp_current_ts(old.cod_empresa) into :current_d;

    if (trim(coalesce(old.status_estoque, 'N')) = 'S') then
    begin
      select first 1 coalesce(est.chassi, '') from estoque_diario est
      where est.tipo = 'V' and est.dia = :current_d and est.chassi = old.chassi_c and est.cod_empresa = old.cod_empresa
      into: pchassi;

      if (trim(coalesce(pchassi, '')) = '') then
      begin
          INSERT INTO ESTOQUE_DIARIO (TIPO, SEQID, COD_EMPRESA, DIA, GRUPO_PROD, COD_PROD, COD_GRADE, CHASSI, ESTOQUE, CUSTO_MEDIO, SITUACAO)
          VALUES ('V', (select cod from incrementa_codigo(old.cod_empresa,'ESTOQUE_DIARIO')), old.cod_empresa, :current_d, null, null, null, old.chassi_c, 0, coalesce(old.preco_custo_rep, 0), new.status_uso);
      end
      else
      begin
         UPDATE ESTOQUE_DIARIO SET ESTOQUE = 0
         WHERE TIPO = 'V' AND DIA = :current_d AND CHASSI = old.chassi_c AND COD_EMPRESA = old.cod_empresa;
      end
    end
  end
end
 
 ^

