CREATE TRIGGER TI_FILA_RESERVA_REORDENAR FOR FILA_RESERVA_VEIC 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
  declare variable vPrev1 char(3);
  declare variable vPrev2 char(3);
  declare variable vCodFila integer;
  declare variable vreordenar char(1);
begin
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit;

  if (coalesce(NEW.COD_VENDEDOR, 0) <= 0) then
  begin
    new.cod_cliente = null;
    new.nome_res = null;
    new.fone_res = null;
    new.tipo_res = null;
    new.sit_res = null;
    new.grupo_cota_rd = null;
    new.data_assembleia = null;
    new.data_res = null;
    new.hora_res = null;

    select trim(coalesce(empresa.reordenar_fila_res, 'N')) from empresa
    where empresa.cod_empresa = new.cod_empresa
    into :vreordenar;

    if (trim(vreordenar) <> 'S') then
     exit;

    if ((updating) and (coalesce(old.cod_vendedor, 0) > 0) and (coalesce(new.cod_vendedor, 0) = 0)) then
    begin
        vprev1 = new.prev_cheg;

        for select codigo, prev_cheg from fila_reserva_veic
        where cod_modelo = new.cod_modelo and ano_fab = new.ano_fab and ano_mod = new.ano_mod
        and cod_cor = new.cod_cor and ordem > new.ordem and ativo = 1 and coalesce(status_res, 'N') = 'N'
        order by ordem
         into: vcodfila, vprev2 do
        begin
            update fila_reserva_veic set prev_cheg = :vprev1
            where codigo = :vcodfila and cod_empresa = new.cod_empresa;

            vprev1 = vprev2;
        end
        if (vcodfila > 0) then
        begin
          new.ordem = (select cod from incrementa_codigo(new.cod_empresa, 'FILA_RESERVA_VEIC_ORDEM'));
          new.prev_cheg = :vprev1;
        end
    end
  end
end;
 
 ^

CREATE TRIGGER TI_EVD_PAF_FINCP FOR FINCUPOM 
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 0 
AS                                      
  declare variable vcodempresa integer; 
  declare variable vtiporegistro varchar(3);
  declare variable vdata timestamp;
  declare variable vcamposchave varchar(100);
  declare variable vvalorechave varchar(100);
  declare variable vmd5 varchar(256);
  declare variable vacao varchar(1);
begin
  vtiporegistro = 'FC';
  vcamposchave = '|COD_TERMINAL|NSERIEECF|REGISTRO|TIPO_DOC|';
  if (inserting) then
  begin              
    vcodempresa =  new.cod_empresa;
    vdata = new.data;
    vvalorechave = '|'||new.cod_terminal||'|'||new.nserieecf||'|'||new.registro||'|'||new.tipo_doc||'|';
    vmd5 = new.md5;
    vacao = 'I';
    execute procedure sp_evd_paf(vcodempresa, vtiporegistro, vdata, vcamposchave, vvalorechave, substring(vmd5 from 1 for 32), vacao);
  end
  else if ((deleting) or (updating)) then
  begin              
    vcodempresa =  old.cod_empresa;
    vdata = old.data;
    vvalorechave = '|'||old.cod_terminal||'|'||old.nserieecf||'|'||old.registro||'|'||old.tipo_doc||'|';
    vmd5 = old.md5;
    vacao = 'D';
    if ((deleting) or (coalesce(new.md5, '') <> '') and (coalesce(old.md5, '') = '')) then
      execute procedure sp_evd_paf(vcodempresa, vtiporegistro, vdata, vcamposchave, vvalorechave, substring(vmd5 from 1 for 32), vacao);
  end
END
 
 ^

