CREATE TRIGGER FORMPAGAMENTO_BU_NFCE FOR FORMPAGAMENTO 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
  declare variable tamanhodoc integer;
  declare variable postraco integer;
begin   
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (inserting) then
  begin
    postraco = coalesce((select result from pos('-', trim(new.ndoc))), 0);
    tamanhodoc = postraco - 1;
    if (
      (new.cod_nfce > 0) and
      ((new.ndoc_ant is null) or (new.ndoc_ant = '')) and
      (postraco > 0)
      ) then
      new.ndoc_ant = (select result from strzero(new.nrequisicao, 6))||
                     substring(new.ndoc from :postraco for (char_length(trim(new.ndoc)) - :tamanhodoc ) );
  end

  if (updating) then
  begin
    if (
      (old.tipdoc <> 'S2') or
      (old.n_processamento is null) or (old.n_processamento <= 0) or
      (old.cod_nfce is null) or (old.cod_nfce <= 0) or
      (old.ndoc_ant is null) or (old.ndoc_ant = '')
      ) then
      exit;
  
    update controle_creditos cc set cc.n_doc_c = old.ndoc_ant
      where cc.cod_cred = old.n_processamento and cc.cod_emp_mult = old.cod_empresa
      and char_length(cc.n_doc_c) > 5;
  end
end
 
 ^

