CREATE TRIGGER T_GRADE_REPL_INTER FOR GRADE 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
AS
  DECLARE VARIABLE VREPLICACAO_INTERNA INTEGER;
  DECLARE VARIABLE VCODEMPF INTEGER;
  DECLARE VARIABLE VCOD_EMP INTEGER;
  DECLARE VARIABLE VEMP_REPL_INTERNA INTEGER;
  DECLARE VARIABLE VEXISTE INTEGER;
begin
  /* Trigger text */
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit;

  if (deleting) then
  begin
      if (coalesce(old.COD_GRADE, 0) <= 0) then
        exit;

      SELECT COD_EMPRESA_FISICA FROM EMPDESVOLV WHERE COD_EMPDES = 1 INTO :VCODEMPF;

      if (coalesce(old.COD_EMPRESA, 0) <> COALESCE(VCODEMPF, 0)) THEN
        exit;

      select count(*) from tab_rep where tabela = 'GRADE' into :VREPLICACAO_INTERNA;

      if (coalesce(vreplicacao_interna, 0) <= 0) then
        exit;

      FOR SELECT COD_EMPRESA, COALESCE(EMP_REPL_INTERNA, :VCODEMPF) EMP_REPL_INTERNA FROM EMPRESA
          WHERE ATIVO = 1 AND COD_EMPRESA <> old.COD_EMPRESA
          into :VCOD_EMP, VEMP_REPL_INTERNA do
      begin
         SELECT COD_GRADE FROM GRADE WHERE COD_GRADE = coalesce(old.COD_GRADE, 0) and COD_EMPRESA = :VCOD_EMP into :VEXISTE;
    
         if (coalesce(VEXISTE, 0) > 0) then
         begin
            delete from grade where cod_grade = coalesce(old.cod_grade, 0) and cod_empresa = :VCOD_EMP;
         end
      end
  end
  else if ((inserting) or (updating)) then
  begin
      if (coalesce(new.COD_GRADE, 0) <= 0) then
        exit;

      SELECT COD_EMPRESA_FISICA FROM EMPDESVOLV WHERE COD_EMPDES = 1 INTO :VCODEMPF;

      if (coalesce(new.COD_EMPRESA, 0) <> COALESCE(VCODEMPF, 0)) THEN
        exit; 

      select count(*) from tab_rep where tabela = 'GRADE' into :VREPLICACAO_INTERNA;

      if (coalesce(vreplicacao_interna, 0) <= 0) then
        exit;

      FOR SELECT COD_EMPRESA, COALESCE(EMP_REPL_INTERNA, :VCODEMPF) EMP_REPL_INTERNA FROM EMPRESA
          WHERE ATIVO = 1 AND COD_EMPRESA <> new.COD_EMPRESA
          into :VCOD_EMP, VEMP_REPL_INTERNA do
      begin
          if (coalesce(VEMP_REPL_INTERNA, 0) = coalesce(VCODEMPF, 0)) then
          begin
              SELECT COD_GRADE FROM GRADE WHERE COD_GRADE = coalesce(new.COD_GRADE, 0) and COD_EMPRESA = :VCOD_EMP into :VEXISTE;
    
              if (coalesce(VEXISTE, 0) <= 0) then
              begin
                insert into grade (cod_grade, cod_empresa, descricao, descricao1, ativo, tipo_ec, descricao_ec, tipo_ec1, descricao_ec1)
                values (new.COD_GRADE, :VCOD_EMP, new.DESCRICAO, new.DESCRICAO1, new.ATIVO, new.TIPO_EC, new.DESCRICAO_EC, new.TIPO_EC1, new.DESCRICAO_EC1);
              end
              else
              begin
                update grade set descricao = new.DESCRICAO, descricao1 = new.DESCRICAO1, ativo = new.ATIVO,
                    tipo_ec = new.TIPO_EC, descricao_ec = new.DESCRICAO_EC,
                    tipo_ec1 = new.TIPO_EC1, descricao_ec1 = new.DESCRICAO_EC1
                where cod_grade = coalesce(new.COD_GRADE, 0) and cod_empresa = :VCOD_EMP;
              end
          end
      end
  end
end;
 
 ^

