CREATE TRIGGER ATITEM_NF_ENTRADA FOR ITEM_NF_ENTRADA 
ACTIVE BEFORE DELETE POSITION 0 
as
declare variable stat_nf integer;
declare variable stat_nf1 integer;
begin
  stat_nf = 0;
  stat_nf1 = 0;
  select count(NUM_NOTA_NFE) from CUSTOS 
              where CUSTOS.num_nota_nfe = old.num_nota_nfe and
              CUSTOS.FORNEC = old.cod_forn_nfe and custos.COD_EMPRESA = old.COD_EMPRESA
              into :stat_nf;
  select count(NF_ENTRADA.NUM_NOTA_NFE) from NF_ENTRADA 
            where old.num_nota_nfe = NF_ENTRADA.num_nota_nfe and
            old.cod_forn_nfe =  NF_ENTRADA.COD_FORN_NFE and  old.COD_EMPRESA = NF_ENTRADA.COD_EMPRESA and
            DA = 'S' into :stat_nf1;
 if (stat_nf > 0) then
 begin
  delete from CUSTOS where custos.num_nota_nfe = old.num_nota_nfe
              and custos.cod_prod = old.cod_prod
              and custos.grupo_prod = old.grupo_prod
              and custos.fornec = old.COD_FORN_NFE and  old.COD_EMPRESA = custos.COD_EMPRESA;
  /* altera estoque do produto */
  if ((old.ALTERA_ESTOQUE_CFOP <> 'N') or (old.altera_estoque_cfop is null))  then
  begin
      if (old.CAMP_ENTEST = 'D') then
      begin
       update produtos set est_r = est_r-(old.quant_item_nfe)
             where produtos.cod_prod = old.cod_prod
             and produtos.grupo_prod = old.grupo_prod and produtos.cod_empresa = old.COD_EMPRESA;
      end
      else
      begin
       update produtos set est_f = est_f-(old.quant_item_nfe)
             where produtos.cod_prod = old.cod_prod
             and produtos.grupo_prod = old.grupo_prod and produtos.cod_empresa = old.COD_EMPRESA;
      end
      if (stat_nf1 > 0) then
      begin
       update produtos set ests = ests-(old.quant_item_nfe)
              where produtos.cod_prod = old.cod_prod
              and produtos.grupo_prod = old.grupo_prod and produtos.cod_empresa = old.COD_EMPRESA;
      end
      if (stat_nf1 = 0) then
      begin
       update produtos set estc = estc-(old.quant_item_nfe)
              where produtos.cod_prod = old.cod_prod
              and produtos.grupo_prod = old.grupo_prod and produtos.cod_empresa = old.COD_EMPRESA;
       if (old.mnf = 'S') then
       begin
        update produtos set estm = estm-(old.quant_item_nfe)
              where produtos.cod_prod = old.cod_prod
              and produtos.grupo_prod = old.grupo_prod and produtos.cod_empresa = old.COD_EMPRESA;
       end
      end
  end
 end
end ^

CREATE TRIGGER TI_ITEM_PEDIDO_BI_STATUS_PED FOR ITEM_PEDIDO 
ACTIVE BEFORE UPDATE POSITION 0 
AS
  declare variable vnum_ped integer;
  declare variable vstatus_ped char(10);  
  declare variable current_d timestamp;
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  select status_ped from pedido
    where num_ped = new.num_ped and cod_empresa = new.cod_empresa
      into :vstatus_ped;

   if ((new.recebido = 'S') and (rtrim(vstatus_ped) = 'EFETIVADO')) then
   begin
     select first 1 num_ped from item_pedido
       where num_ped = new.num_ped and cod_empresa = new.cod_empresa and
       ((grupo_prod <> new.grupo_prod) or (cod_prod <> new.cod_prod) or (nitem <> new.nitem) ) and coalesce(recebido, '') <> 'S'
         into :vnum_ped;
     if (coalesce(vnum_ped, 0) = 0) then
     begin     
       select current_d from sp_current_ts(new.cod_empresa) into :current_d;

       update pedido set status_ped = 'RECEBIDO', data_chg_ped = :current_d
         where num_ped = new.num_ped and cod_empresa = new.cod_empresa;
     end
   end
   else if ((new.recebido <> 'S') and (rtrim(vstatus_ped) = 'RECEBIDO')) then
   begin
     update pedido set status_ped = 'EFETIVADO', data_chg_ped = null
       where num_ped = new.num_ped and cod_empresa = new.cod_empresa;
   end
end
 
 ^

CREATE TRIGGER TI_ITEM_PEDIDO_NF_REC_BIUD_QT_R FOR ITEM_PEDIDO_NF_REC 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
AS
  declare variable vqtde_ped T_D_QUANT;
  declare variable vqtde_recebida T_D_QUANT;
  declare variable vgrupo_prod integer;
  declare variable vcod_prod char(6);
  declare variable vnum_ped integer;
  declare variable vcod_empresa integer;
  declare variable vnitem integer;
  declare variable vcod_nf integer;
  declare variable vnitem_nf integer;
begin

  if ((inserting) or (updating)) then
  begin
    vgrupo_prod = new.grupo_prod;
    vcod_prod = new.cod_prod;
    vnum_ped = new.num_ped;
    vcod_empresa = new.cod_empresa;
    vnitem = new.nitem;
    vcod_nf = new.cod_nf;
    vnitem_nf = new.nitem_nf;
  end
  else if (deleting) then
  begin
    vgrupo_prod = old.grupo_prod;
    vcod_prod = old.cod_prod;
    vnum_ped = old.num_ped;
    vcod_empresa = old.cod_empresa;
    vnitem = old.nitem;
    vcod_nf = old.cod_nf;
    vnitem_nf = old.nitem_nf;
  end

  select sum(qtde_recebida) from item_pedido_nf_rec
    where num_ped = :vnum_ped and grupo_prod = :vgrupo_prod and
    cod_prod = :vcod_prod and cod_empresa = :vcod_empresa and
    nitem = :vnitem and ((cod_nf <> :vcod_nf) or (nitem_nf <> :vnitem_nf))
      into :vqtde_recebida;

  select sum(quant_it_prod) quant_it_prod from item_pedido
    where num_ped = :vnum_ped and grupo_prod = :vgrupo_prod and
    cod_prod = :vcod_prod and cod_empresa = :vcod_empresa and
    nitem = :vnitem
      into :vqtde_ped;

  if ((inserting) or (updating)) then
  begin
    vqtde_recebida = coalesce(vqtde_recebida, 0) + new.qtde_recebida;
  end
  else if (deleting) then
  begin
    vqtde_recebida = coalesce(vqtde_recebida, 0) - old.qtde_recebida;
  end

  if (coalesce(vqtde_ped, 0) <= coalesce(vqtde_recebida, 0)) then
  begin
    update item_pedido set recebido = 'S'
      where num_ped = :vnum_ped and grupo_prod = :vgrupo_prod and
      cod_prod = :vcod_prod and cod_empresa = :vcod_empresa and
      nitem = :vnitem and coalesce(recebido, '') <> 'S';
  end
  else if (coalesce(vqtde_ped, 0) > coalesce(vqtde_recebida, 0)) then
  begin
    update item_pedido set recebido = 'N'
      where num_ped = :vnum_ped and grupo_prod = :vgrupo_prod and
      cod_prod = :vcod_prod and cod_empresa = :vcod_empresa and
      nitem = :vnitem and coalesce(recebido, '') = 'S';
  end
end
 
 ^

