CREATE TRIGGER TR_KITS_PROD_EC FOR KITS_PROD 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
  DECLARE VARIABLE VSINC_ECOMMERCE VARCHAR(1);
  DECLARE VARIABLE IDCOMMERCE INTEGER;
  DECLARE VARIABLE ECOMMERCE INTEGER;
  DECLARE VARIABLE VSQL VARCHAR(100);
begin
  /* Trigger text */
   IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit;

  VSQL = '';

  SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
  WHERE CONFIG_SISTEMA.CHAVE = 'e-commerce_hab'
  AND CONFIG_SISTEMA.COD_EMPRESA = NEW.COD_EMPRESA INTO: ECOMMERCE;

  SELECT KITS_PROD_EC.SINC_ECOMMERCE, KITS_PROD_EC.ID_COMMERCE FROM KITS_PROD_EC
  WHERE KITS_PROD_EC.CODIGO_KIT = NEW.CODIGO_KIT
  AND KITS_PROD_EC.COD_EMPRESA = NEW.COD_EMPRESA INTO :VSINC_ECOMMERCE, :IDCOMMERCE;

  if ((COALESCE(IDCOMMERCE, 0) <= 0) and (COALESCE(ECOMMERCE, 0) <= 0)) then
    exit;

  if (trim(OLD.LISTA_IMAGENS) <> trim(NEW.LISTA_IMAGENS)) then
  begin
    if (coalesce(new.ALTEROU_IMAGEM, 'N') <> 'S') then
        new.ALTEROU_IMAGEM = 'S';
  end

  IF (COALESCE(IDCOMMERCE, 0) > 0) THEN
    new.ID_COMMERCE = :IDCOMMERCE;
    
  if (updating) then
    if ((coalesce(old.ativo, 0) <> coalesce(new.ativo, 0)) and (new.ativo = 0)) then
        VSQL = ' kits_prod_ec.disponivel = ''N'', ';

    execute statement
      'update kits_prod_ec set '||VSQL||'
         kits_prod_ec.codigo_kit = '||new.codigo_kit||',
         kits_prod_ec.cod_empresa = '||new.cod_empresa||'
      where kits_prod_ec.codigo_kit = '||new.codigo_kit||'
      and kits_prod_ec.cod_empresa = '||new.cod_empresa||';';
end;
 
 ^

