CREATE TRIGGER TR_DTEC_KITS_PROD_EC FOR KITS_PROD_EC 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
AS 
 DECLARE VARIABLE VSEQID BIGINT; 
 DECLARE VARIABLE CAMPOS_CHAVE VARCHAR(255);
 DECLARE VARIABLE VALORES_CHAVE VARCHAR(255);
 DECLARE VARIABLE VDELETE INTEGER;
begin 
  /* Trigger text */ 
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit; 

  VDELETE = 0; 
  if (updating) then 
    if (coalesce(old.sinc_ecommerce, 'N') <> (coalesce(new.sinc_ecommerce, 'N')) 
     and (coalesce(old.sinc_ecommerce, 'N') = 'S') and (coalesce(new.sinc_ecommerce, 'N') = 'N')) then 
      VDELETE = 1; 

  if (deleting) then 
    VDELETE = 1; 

  if (vdelete > 0) then 
  begin 
    if (COALESCE(OLD.ID_COMMERCE, 0) <= 0) then 
     exit; 

    SELECT GEN_ID(SEQ_DEL_EC, 1) FROM RDB$DATABASE INTO :VSEQID; 
    CAMPOS_CHAVE =  '|CODIGO_KIT|COD_EMPRESA|'; 
    VALORES_CHAVE = '|'||OLD.CODIGO_KIT||'|'||OLD.COD_EMPRESA||'|'; 
    INSERT INTO DEL_EC(SEQID, COD_EMPRESA, TABELA, DATA_HORA_ALT_WS, CAMPOS_CHAVE, VALORES_CHAVE, ID_COMMERCE)  
    VALUES(:VSEQID, old.COD_EMPRESA, 'KITS_PROD_EC', CURRENT_TIMESTAMP, :CAMPOS_CHAVE, :VALORES_CHAVE, OLD.ID_COMMERCE); 
    NEW.ID_COMMERCE = 0;
  end 
  else if ((inserting)or(updating)) then 
  begin 
    NEW.SEQID_EC = (SELECT GEN_ID(SEQ_EC_KITS_PROD_EC, 1) FROM RDB$DATABASE); 
  end 
end;
 
 ^

CREATE TRIGGER TR_DTEC_KITS_PROD_KITS_EC FOR KITS_PROD_KITS 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
AS
    DECLARE VARIABLE ECOMMERCE INTEGER;
    DECLARE VARIABLE IDCOMMERCE INTEGER;
    DECLARE VARIABLE VSEQID BIGINT;
    DECLARE VARIABLE VDELETE INTEGER;    
    DECLARE VARIABLE VIDCOMMERCE_KIT INTEGER;
begin
    /* Trigger text */
    IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
        exit;

    if ((inserting)or(updating)) then
    begin
      SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
      WHERE CONFIG_SISTEMA.CHAVE = 'e-commerce_hab'
      AND CONFIG_SISTEMA.COD_EMPRESA = NEW.COD_EMPRESA INTO: ECOMMERCE;
    
      SELECT KITS_PROD_EC.ID_COMMERCE FROM KITS_PROD_EC
      WHERE KITS_PROD_EC.CODIGO_KIT = NEW.CODIGO_KIT
      AND KITS_PROD_EC.COD_EMPRESA = NEW.COD_EMPRESA INTO: IDCOMMERCE;
    end
    else if (deleting) then
    begin
      SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
      WHERE CONFIG_SISTEMA.CHAVE = 'e-commerce_hab'
      AND CONFIG_SISTEMA.COD_EMPRESA = OLD.COD_EMPRESA INTO: ECOMMERCE;
    
      SELECT KITS_PROD_EC.ID_COMMERCE FROM KITS_PROD_EC
      WHERE KITS_PROD_EC.CODIGO_KIT = OLD.CODIGO_KIT
      AND KITS_PROD_EC.COD_EMPRESA = OLD.COD_EMPRESA INTO: IDCOMMERCE;
    end

    if ((COALESCE(IDCOMMERCE, 0) <= 0) and (COALESCE(ECOMMERCE, 0) <= 0)) then
      exit;

    VDELETE = 0;
    if (updating) then
        if (coalesce(old.ativo, 0) <> (coalesce(new.ativo, 0)) and (coalesce(new.ativo, 0) = 0)) then
            VDELETE = 1;

    if (updating) then
        if (coalesce(old.sinc_ecommerce, 'N') <> (coalesce(new.sinc_ecommerce, 'N'))
          and (coalesce(old.sinc_ecommerce, 'N') = 'S') and (coalesce(new.sinc_ecommerce, 'N') = 'N')) then
            VDELETE = 1;

    if (deleting) then
        VDELETE = 1;

    if (vdelete > 0) then
    begin
        SELECT ID_COMMERCE FROM KITS_PROD_EC WHERE KITS_PROD_EC.CODIGO_KIT = old.CODIGO_KIT AND KITS_PROD_EC.COD_EMPRESA = old.COD_EMPRESA into :VIDCOMMERCE_KIT;

        if (COALESCE(VIDCOMMERCE_KIT, 0) > 0) then
        begin
            SELECT GEN_ID(SEQ_DEL_EC, 1) FROM RDB$DATABASE INTO :VSEQID; 
            INSERT INTO DEL_EC(SEQID, COD_EMPRESA, TABELA, DATA_HORA_ALT_WS, ID_COMMERCE)  
            VALUES(:VSEQID, old.COD_EMPRESA, 'KITS_PROD_EC', (select CURRENT_TS from SP_CURRENT_TS(old.COD_EMPRESA)), :VIDCOMMERCE_KIT);
        end

        execute statement
           'update kits_prod set
              kits_prod.codigo_kit = '||old.codigo_kit||',
              kits_prod.cod_empresa = '||old.cod_empresa||'
            where kits_prod.codigo_kit = '||old.codigo_kit||'
            and kits_prod.cod_empresa = '||old.cod_empresa||';';
    end
    else if ((inserting)or(updating)) then
    begin
        if (inserting) then
        begin
            SELECT ID_COMMERCE FROM KITS_PROD_EC WHERE KITS_PROD_EC.CODIGO_KIT = new.CODIGO_KIT AND KITS_PROD_EC.COD_EMPRESA = new.COD_EMPRESA into :VIDCOMMERCE_KIT;

            if (COALESCE(VIDCOMMERCE_KIT, 0) > 0) then
            begin
                SELECT GEN_ID(SEQ_DEL_EC, 1) FROM RDB$DATABASE INTO :VSEQID; 
                INSERT INTO DEL_EC(SEQID, COD_EMPRESA, TABELA, DATA_HORA_ALT_WS, ID_COMMERCE)  
                VALUES(:VSEQID, new.COD_EMPRESA, 'KITS_PROD_EC', (select CURRENT_TS from SP_CURRENT_TS(old.COD_EMPRESA)), :VIDCOMMERCE_KIT);
            end
        end
        else if (updating) then
            if ((coalesce(old.grupo_prod, 0) <> coalesce(new.grupo_prod, 0))
                or (coalesce(old.cod_prod, '') <> coalesce(new.cod_prod, ''))
                or (coalesce(old.quant_prod_kit, 0) <> coalesce(new.quant_prod_kit, 0))) then
            begin
                SELECT ID_COMMERCE FROM KITS_PROD_EC WHERE KITS_PROD_EC.CODIGO_KIT = new.CODIGO_KIT AND KITS_PROD_EC.COD_EMPRESA = new.COD_EMPRESA into :VIDCOMMERCE_KIT;

                if (COALESCE(VIDCOMMERCE_KIT, 0) > 0) then
                begin
                    SELECT GEN_ID(SEQ_DEL_EC, 1) FROM RDB$DATABASE INTO :VSEQID; 
                    INSERT INTO DEL_EC(SEQID, COD_EMPRESA, TABELA, DATA_HORA_ALT_WS, ID_COMMERCE)  
                    VALUES(:VSEQID, new.COD_EMPRESA, 'KITS_PROD_EC', (select CURRENT_TS from SP_CURRENT_TS(old.COD_EMPRESA)), :VIDCOMMERCE_KIT);
                end
            end

        NEW.SEQID_EC = (SELECT GEN_ID(SEQ_EC_KITS_PROD_KITS, 1) FROM RDB$DATABASE);
        execute statement
           'update kits_prod set
              kits_prod.codigo_kit = '||new.codigo_kit||',
              kits_prod.cod_empresa = '||new.cod_empresa||'
            where kits_prod.codigo_kit = '||new.codigo_kit||'
            and kits_prod.cod_empresa = '||new.cod_empresa||';';
    end
end
 
 ^

