CREATE TRIGGER TI_LANCDEBCRED_SALDODEBCRED FOR LANC_DEBCRED 
ACTIVE AFTER INSERT OR DELETE POSITION 0 
AS
  declare variable vsaldo t_vl_todos;
  declare variable current_d timestamp;
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;
    
  if (inserting) then
  begin  
    select current_d from sp_current_ts(new.cod_empresa) into :current_d;

    if (new.cod_vendedor is not null) then
    begin
      select sdc.saldo from saldo_debcred sdc
      where sdc.cod_vendedor = new.cod_vendedor
      and sdc.cod_empresa = new.cod_empresa
      and sdc.data = :current_d
        into :vsaldo;

      if (row_count > 0) then
      begin
        if ((round((coalesce(vsaldo, 0) + coalesce(new.vl_lancdebcred, 0)), 5)) = 0.00000) then
        begin
          update saldo_debcred sdc set sdc.saldo = 0
          where sdc.cod_vendedor = new.cod_vendedor
          and sdc.cod_empresa = new.cod_empresa
          and sdc.data = :current_d;
        end
        else
        begin
          update saldo_debcred sdc set sdc.saldo = coalesce(:vsaldo, 0) + coalesce(new.vl_lancdebcred, 0)
          where sdc.cod_vendedor = new.cod_vendedor
          and sdc.cod_empresa = new.cod_empresa
          and sdc.data = :current_d;
        end
      end
      else
      begin
        select first 1 coalesce(sdc.saldo, 0) from saldo_debcred sdc
        where sdc.cod_vendedor = new.cod_vendedor
        and sdc.cod_empresa = new.cod_empresa
        order by sdc.cod_saldo desc
          into :vsaldo;

        if (row_count = 0) then
          vsaldo=0;

        insert into saldo_debcred (COD_SALDO, COD_EMPRESA, COD_VENDEDOR, SALDO, DATA)
        values ((select COD from INCREMENTA_CODIGO(new.cod_empresa, 'SALDO_DEBCRED')),
        new.cod_empresa, new.cod_vendedor, (coalesce(:vsaldo, 0) + coalesce(new.vl_lancdebcred, 0)), :current_d);
      end
    end
  end
  else
  begin   
    select current_d from sp_current_ts(old.cod_empresa) into :current_d;

    if (old.cod_vendedor is not null) then
    begin
      select sdc.saldo from saldo_debcred sdc
      where sdc.cod_vendedor = old.cod_vendedor
      and sdc.cod_empresa = old.cod_empresa
      and sdc.data = :current_d
        into :vsaldo;

      if (row_count > 0) then
      begin
        if ((round((coalesce(vsaldo, 0) - coalesce(old.vl_lancdebcred, 0)), 5)) = 0.00000) then
        begin
          update saldo_debcred sdc set sdc.saldo = 0
          where sdc.cod_vendedor = old.cod_vendedor
          and sdc.cod_empresa = old.cod_empresa
          and sdc.data = :current_d;
        end
        else
        begin
          update saldo_debcred sdc set sdc.saldo = coalesce(sdc.saldo, 0) - coalesce(old.vl_lancdebcred, 0)
          where sdc.cod_vendedor = old.cod_vendedor
          and sdc.cod_empresa = old.cod_empresa
          and sdc.data = :current_d;
        end
      end
      else
      begin
        select first 1 sdc.saldo from saldo_debcred sdc
        where sdc.cod_vendedor = old.cod_vendedor
        and sdc.cod_empresa = old.cod_empresa
        order by sdc.cod_saldo desc
          into :vsaldo;

        if (vsaldo is null) then
          vsaldo=0;

        insert into saldo_debcred (COD_SALDO, COD_EMPRESA, COD_VENDEDOR, SALDO, DATA)
        values ((select COD from INCREMENTA_CODIGO(old.cod_empresa, 'SALDO_DEBCRED')),
        old.cod_empresa, old.cod_vendedor, coalesce(:vsaldo, 0) - coalesce(old.vl_lancdebcred, 0), :current_d);
      end
    end
  end
end;
 
 ^

CREATE TRIGGER LOCALIDADE_BI_GUID FOR LOCALIDADE 
ACTIVE BEFORE INSERT POSITION 0 
as
