CREATE TRIGGER TI_EVD_PAF_MAPALIQ FOR MAPA_RESUMO_ALIQ 
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 0 
AS                                      
  declare variable vcodempresa integer; 
  declare variable vtiporegistro varchar(3);
  declare variable vdata timestamp;
  declare variable vcamposchave varchar(100);
  declare variable vvalorechave varchar(100);
  declare variable vmd5 varchar(256);
  declare variable vacao varchar(1);
begin
  vtiporegistro = 'MR';
  vcamposchave = '|COD_TERMINAL|NSERIEECF|COD_EMPRESA|COORED|ALIQ_SEQ|';
  if (inserting) then
  begin              
    vcodempresa =  new.cod_empresa;
    select first 1 data_mov from resumod where cod_terminal = new.cod_terminal and nserieecf = new.nserieecf and
      cod_empresa = new.cod_empresa and coored = new.coored into :vdata;
    vvalorechave = '|'||new.cod_terminal||'|'||new.nserieecf||'|'||new.cod_empresa||'|'||new.coored||'|'||new.aliq_seq||'|';
    vmd5 = new.md5;
    vacao = 'I';
    execute procedure sp_evd_paf(vcodempresa, vtiporegistro, vdata, vcamposchave, vvalorechave, substring(vmd5 from 1 for 32), vacao);
  end
  else if ((deleting) or (updating)) then
  begin              
    vcodempresa =  old.cod_empresa;
    select first 1 data_mov from resumod where cod_terminal = old.cod_terminal and nserieecf = old.nserieecf and
      cod_empresa = old.cod_empresa and coored = old.coored into :vdata;
    vvalorechave = '|'||old.cod_terminal||'|'||old.nserieecf||'|'||old.cod_empresa||'|'||old.coored||'|'||old.aliq_seq||'|';
    vmd5 = old.md5;
    vacao = 'D';
    if ((deleting) or (coalesce(new.md5, '') <> '') and (coalesce(old.md5, '') = '')) then
      execute procedure sp_evd_paf(vcodempresa, vtiporegistro, vdata, vcamposchave, vvalorechave, substring(vmd5 from 1 for 32), vacao);
  end
END
 
 ^

