CREATE TRIGGER NFCE_BI_ID FOR NFCE 
ACTIVE BEFORE INSERT POSITION 0 
as
begin
  if (coalesce(new.COD_NFCE, 0) = 0) then
    new.COD_NFCE = (select COD from INCREMENTA_CODIGO(new.COD_EMPRESA, 'NFCE'));
  if (coalesce(new.GUIDT, '') = '') then
    new.GUIDT = (select GUID from SPDB_GUID);  

  if ((coalesce(new.COD_NFCE_ORIGINAL, 0) = 0) and
      (new.tpemis = '9') and
      (trim(coalesce(new.GUID_NFCE_ORIGINAL, '')) <> '')) then
    new.COD_NFCE_ORIGINAL = (select first 1 COD_NFCE from NFCE where GUIDT = new.GUID_NFCE_ORIGINAL and COD_EMPRESA = new.COD_EMPRESA);

  if ((coalesce(new.COD_NFCE_CONTING, 0) = 0) and
      (new.status = 'A Cancelar') and
      (trim(coalesce(new.GUID_NFCE_CONTING, '')) <> '')) then
    new.COD_NFCE_CONTING = (select first 1 COD_NFCE from NFCE where GUIDT = new.GUID_NFCE_CONTING and COD_EMPRESA = new.COD_EMPRESA);
end
 
 ^

CREATE TRIGGER NFCE_BI_MOV_OPERADOR FOR NFCE 
ACTIVE BEFORE INSERT POSITION 0 
as
  declare variable movid integer;
  declare variable operadorid integer;
  declare variable current_ts timestamp;
begin       
  if (substring(user from 1 for 4) = 'REPL') then
    exit;
  -- mov_id = 0, o sistema preencheu "0" para a trigger obter o id do movimento
  if ((new.mov_id = 0) and (coalesce(new.operador, 0) > 0)) then
  begin
    select first 1 mov.operador, mov.id from nfce_movimento mov
      where mov.cod_emissor = new.cod_emissor and mov.cod_empresa = new.cod_empresa and mov.dia_fech is null
        order by mov.dia_mov asc
      into :operadorid, :movid;

    if (coalesce(operadorid, 0) > 0) then
      if (coalesce(operadorid, 0) <> coalesce(new.operador, 0)) then
        exception exc_nfce_mov_abrt_out;

    if (movid is null) then
    begin
      select current_d from sp_current_ts(new.cod_empresa) into :current_ts;
      insert into nfce_movimento (dia_mov, cod_empresa, cod_emissor, operador) values (:current_ts, new.cod_empresa, new.cod_emissor, new.operador)
        returning id into :movid;
    end

    if (movid is null) then
      exception exc_nfce_movimento;

    new.mov_id = movid;
  end

  if ((new.mov_id > 0) and (coalesce(new.mov_seq, 0) = 0)) then
  begin
    update nfce_movimento mov set mov.count_op = coalesce(mov.count_op, 0) + 1
      where mov.id = new.mov_id and mov.cod_empresa = new.cod_empresa
        returning mov.count_op into new.mov_seq;
  end
end
 
 ^

CREATE TRIGGER NFCE_BU_DATA_LANC FOR NFCE 
ACTIVE BEFORE UPDATE POSITION 0 
AS
  declare variable dataemissao timestamp;
  declare variable dataini timestamp;
  declare variable datafim timestamp;
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;
  if ((new.situacao_nfce in ('Autorizada', 'Denegada', 'Cancelada')) and (new.dhemi is not null)) then
  begin
    select start_date, end_date from date_of_month(new.dhemi)
      into :dataini, :datafim;

    if ((new.data_lanc < :dataini) or (new.data_lanc > :datafim)) then
    begin
      select data from date_of(new.dhemi) into :dataemissao;

      if (:dataemissao is not null) then
        new.data_lanc = :dataemissao;
    end
  end
end ^

CREATE TRIGGER NFCE_BU_NORC FOR NFCE 
ACTIVE BEFORE UPDATE POSITION 0 
AS
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;
  if (coalesce(old.norc, 0) <> coalesce(new.norc, 0)) then
  begin
    if (coalesce(old.norc, 0) > 0) then
      update pedvenda set cod_nfce = null where nped = old.norc and tipo = 'ORC' and cod_empresa = old.cod_empresa and cod_nfce = old.cod_nfce;
      
    if (coalesce(new.norc, 0) > 0) then
      update pedvenda set cod_nfce = new.norc where nped = new.norc and tipo = 'ORC' and cod_empresa = new.cod_empresa and cod_nfce is null;
  end
end ^

CREATE TRIGGER NFCE_BIU_CONT_ALT FOR NFCE 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
as
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (inserting) then
    new.CONT_ALT = 0;
  else
  if (updating) then
    if ((coalesce(new.CONT_ALT, 0)) >= 9999) then
      new.CONT_ALT = 1;
    else
      new.CONT_ALT = coalesce(new.CONT_ALT, 0) + 1;
  if (updating) then
    if ((coalesce(new.CONT_MSG, 0)) >= 9999) then
      new.CONT_MSG = 1;
end
 
