CREATE TRIGGER NFCE_ITEM_CALC_IMP FOR NFCE_ITEM 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
AS
  --declare variable calcular char(1);
  declare variable update_pis char(1);
  declare variable update_icms char(1);
  declare variable update_icef char(1);
  declare variable update_iss char(1);
  declare variable update_fcp char(1);
  declare variable valor_tmp t_vl_todos;
  declare variable naousaricms t_vl_todos;
  declare variable scontext_compl_id varchar(255);
  declare variable icodnfce_compl integer;
BEGIN             
  if (substring(user from 1 for 4) = 'REPL') then
     exit;

  select RDB$GET_CONTEXT('USER_SESSION', 'COD_NFCE_COMPL') from RDB$DATABASE
    into :scontext_compl_id;

  if (coalesce(scontext_compl_id, '') = cast(new.cod_nfce as varchar(255))) then
    exit;

  select cod_nfce_complementada from nfce where cod_nfce = new.cod_nfce and cod_empresa = new.cod_empresa
    into :icodnfce_compl;

  if (coalesce(icodnfce_compl,  0) > 0) then
    exit;

  if (((inserting) or ( updating)) and (new.cfop in (5401, 5402, 5403))) then
    new.cfop = 5405;

--  calcular = 'N';--coalesce(new.calcular, 'N');
  update_icms = 'N';
  update_icef = 'N';
  update_pis = 'N';
  update_iss = 'N';
  update_fcp = 'N';

  if ((inserting) or (deleting) ) then
  begin
--    calcular = 'S';
    update_icms = 'S';
    update_icef = 'S';
    update_pis = 'S';
    update_iss = 'S';
    update_fcp = 'S';
  end
  else if (updating) then
    if ((old.vprod <> new.vprod) or
      (old.vseg <> new.vseg) or
      (old.vdesc <> new.vdesc) or  
      --((old.vfrete <> new.vfrete) and (new.frete_na_base = 'S')) or
      (old.vfrete <> new.vfrete) or
      (old.voutro <> new.voutro) or
      (old.frete_na_base <> new.frete_na_base)) then-- or
    begin              
      update_icms = 'S';
      update_icef = 'S';
      update_pis = 'S';
      update_iss = 'S';
      update_fcp = 'S';
    end
    else
    begin                   
      if ((old.icm_cst <> new.icm_cst) or
         (old.icm_csosn <> new.icm_csosn)) then
      begin
        update_icms = 'S';
        update_icef = 'S';
        update_fcp = 'S';
      end

      if ((old.icm_cst <> new.icm_cst) or
        (old.icm_csosn <> new.icm_csosn) or
        (old.icm_predbc <> new.icm_predbc) or
        (old.icm_picms <> new.icm_picms) or
        (old.icm_pcredsn <> new.icm_pcredsn)) then-- or
        update_icms = 'S';
        
      if ((old.icm_cst <> new.icm_cst) or
        (old.icm_csosn <> new.icm_csosn) or
        (old.icm_predbcefet <> new.icm_predbcefet) or
        (old.icm_picmsefet <> new.icm_picmsefet)) then
        update_icef = 'S';

      if ((old.pis_reset <> new.pis_reset) or
        (old.pis_cst <> new.pis_cst) or
        (old.pis_ppis <> new.pis_ppis) or
        (old.pis_valiqprod <> new.pis_valiqprod) or
        (old.cofins_cst <> new.cofins_cst) or
        (old.cofins_pcofins <> new.cofins_pcofins) or
        (old.cofins_valiqprod <> new.cofins_valiqprod)) then-- or
        update_pis = 'S';

      if ((old.iss_valiq <> new.iss_valiq) or
        (old.iss_retido <> new.iss_retido) ) then
        update_iss = 'S';
        
      if ((old.fcp_pfcp <> new.fcp_pfcp) or
        (old.fcp_pfcpst <> new.fcp_pfcpst) ) then
        update_fcp = 'S';
    end

  if ((update_icms = 'N') and (update_pis = 'N') and (update_iss = 'N') and (update_fcp = 'N') and (update_icef = 'N')) then
    exit;

  --if (new.frete_na_base = 'S') then
  --  valor_tmp = new.vfrete;
  --else
  --   valor_tmp = 0;
  --valor_tmp = valor_tmp + new.vprod + new.vseg + new.voutro - new.vdesc;

  valor_tmp = coalesce(new.vprod, 0) +
              coalesce(new.vseg, 0) +
              coalesce(new.voutro, 0) +
              iif(coalesce(new.frete_na_base, 'S') = 'S', coalesce(new.vfrete, 0), 0) -
              coalesce(new.vdesc, 0);

  IF (update_icms = 'S') THEN
  begin
    if ((coalesce(new.icm_pcredsn,0) > 0) and ((new.icm_csosn = '101') or (new.icm_csosn = '900'))) then
    begin
      new.icm_vcredicmssn = round(valor_tmp * new.icm_pcredsn / 100, 2);
      new.icm_predbc = 0;
      new.icm_picms = 0;
      new.icm_vbc = 0;
      new.icm_vicms = 0;
    end
    else if (coalesce(new.icm_csosn, '') <> '') then
    begin               
      new.icm_pcredsn = 0;
      new.icm_vcredicmssn = 0;
      new.icm_predbc = 0;
      new.icm_picms = 0;
      new.icm_vbc = 0;
      new.icm_vicms = 0;
    end
    else if ((new.icm_picms > 0) and ((new.icm_cst = '00') or (new.icm_cst = '20') or (new.icm_cst = '90'))) then
    begin
      if (new.icm_cst = '00') then
        new.icm_predbc = 0;
  
      new.icm_vbc = valor_tmp;
      if (new.icm_predbc > 0) then
        new.icm_vbc = new.icm_predbc * new.icm_vbc / 100;
  
      new.icm_vbc = round(new.icm_vbc, 2);
      new.icm_vicms = round(new.icm_vbc * new.icm_picms / 100, 2);
      
      new.icm_pcredsn = 0;
      new.icm_vcredicmssn = 0;
    end
    else
    begin
      new.icm_predbc = 0;
      new.icm_picms = 0;
      new.icm_vbc = 0;
      new.icm_vicms = 0;
      new.icm_pcredsn = 0;
      new.icm_vcredicmssn = 0;
    end
  end

  if (update_icef = 'S') then
  begin
    if ((new.icm_cst = 60) and (coalesce(new.icm_picmsefet, 0) > 0)) then
    begin
      if (coalesce(new.icm_predbcefet, 0) > 0) then
        new.icm_vbcefet = round(valor_tmp * (100 - new.icm_predbcefet) / 100, 2);
      else
      begin
        new.icm_vbcefet    = round(valor_tmp, 0);
        new.icm_predbcefet = 0;
      end
      new.icm_vicmsefet  = round(new.icm_vbcefet * new.icm_picmsefet / 100, 2);
    end
    else
    begin
      new.icm_predbcefet = 0;
      new.icm_picmsefet  = 0;
      new.icm_vbcefet    = 0;
      new.icm_vicmsefet  = 0;
    end
  end

  valor_tmp = coalesce(new.vprod, 0) +
              coalesce(new.vseg, 0) +
              coalesce(new.voutro, 0) +
              coalesce(new.vfrete, 0) -
              coalesce(new.vdesc, 0);

  naousaricms = 0;
  select value1_f from config_sistema where chave = 'nfc_bc_picofins_sem_icms' and cod_empresa = new.cod_empresa
    into :naousaricms;     

  if (trunc(coalesce(naousaricms, 0)) <> 1) then
    valor_tmp = valor_tmp -
                coalesce(new.icm_vcredicmssn, 0) -
                coalesce(new.icm_vicms, 0);

  valor_tmp = iif(valor_tmp > 0, valor_tmp, 0);

  if (update_pis = 'S') then
  begin
    new.cofins_cst = new.pis_cst;
  
    if (
      ( (new.pis_cst = '03') and (new.pis_valiqprod > 0) )
      or
      ( ( (new.pis_cst = '01') or (new.pis_cst = '02') ) and (new.pis_ppis > 0) )
      ) then
    begin
      if (new.pis_cst = '03') then
      begin
        new.pis_qbcprod = new.qcom;
        new.pis_vpis = round(new.pis_qbcprod * new.pis_valiqprod, 2);
        new.pis_vbc = 0;
        new.pis_ppis = 0;
      end
      else
      begin
        new.pis_vbc = round(valor_tmp, 2);
        new.pis_vpis = round(new.pis_ppis * new.pis_vbc / 100, 2);
        new.pis_qbcprod = 0;
        new.pis_valiqprod = 0;
      end
    end
    else
    begin
      new.pis_vbc = 0;
      if (new.pis_cst <> '05') then --Quando cst 05, no sped tem de permanecer a aliquota, porem base e valor zero
        new.pis_ppis = 0;
      new.pis_qbcprod = 0;
      new.pis_valiqprod = 0;
      new.pis_vpis = 0;
    end
  
    if (
      ( (new.cofins_cst = '03') and (new.cofins_valiqprod > 0) )
      or
      ( ( (new.cofins_cst = '01') or (new.cofins_cst = '02') ) and (new.cofins_pcofins > 0) )
      ) then
    begin
      if (new.cofins_cst = '03') then
      begin
        new.cofins_qbcprod = new.qcom;
        new.cofins_vcofins = round(new.cofins_qbcprod * new.cofins_valiqprod, 2);
        new.cofins_vbc = 0;
        new.cofins_pcofins = 0;
      end
      else
      begin
        new.cofins_vbc = round(valor_tmp, 2);
        new.cofins_vcofins = round(new.cofins_pcofins * new.cofins_vbc / 100, 2);
        new.cofins_qbcprod = 0;
        new.cofins_valiqprod = 0;
      end
    end
    else
    begin
      new.cofins_vbc = 0;
      if (new.cofins_cst <> '05') then
        new.cofins_pcofins = 0;
      new.cofins_qbcprod = 0;
      new.cofins_valiqprod = 0;
      new.cofins_vcofins = 0;
    end
  end    

  valor_tmp = coalesce(new.vprod, 0) +
              coalesce(new.vseg, 0) +
              coalesce(new.voutro, 0) +
              coalesce(new.vfrete, 0) -
              coalesce(new.vdesc, 0);

  if (update_iss = 'S') then
  begin
    if (new.iss_valiq > 0) then
    begin
      new.iss_vbc = round(valor_tmp, 2);
      if ((new.iss_retido = 'S') or (new.iss_retido = 'C'))  then
      begin
        new.iss_vissret = round(new.iss_vbc * new.iss_valiq / 100, 2);
        new.iss_vissqn = 0;
      end
      else
      begin
        new.iss_vissqn = round(new.iss_vbc * new.iss_valiq / 100, 2);
        new.iss_vissret = 0;
      end
    end
    else
    begin
      new.iss_vbc = 0;
      new.iss_valiq = 0;
      new.iss_vissqn = 0;
      new.iss_vissret = 0;
      new.iss_retido = 'N';
    end
  end

  if (update_fcp = 'S') then
  begin
    if (new.icm_cst in ('10', '20','70', '90')) then
      new.fcp_vbcfcp = coalesce(new.icm_vbc, 0);

    if (new.icm_cst in ('00', '10', '20','70', '90')) then
      new.fcp_vfcp = round(coalesce(new.icm_vbc, 0) * new.fcp_pfcp / 100, 2);

    if (new.icm_cst = '51') then
    begin
      new.fcp_vbcfcp = valor_tmp;
      new.fcp_vfcp   = round(coalesce(new.fcp_vbcfcp, 0) * new.fcp_pfcp / 100, 2);
    end

    if ((new.icm_cst in ('10' , '30' , '70' , '90' )) or
      (new.icm_csosn in ('201', '202', '203', '900'))) then
    begin
      new.fcp_vbcfcpst = new.fcp_vbcfcp;
      new.fcp_vfcpst   = round(coalesce(new.fcp_vbcfcpst, 0) * new.fcp_pfcpst / 100, 2);
    end
    
    if (not new.icm_cst in ('10', '20', '70', '90')) then
      new.fcp_vbcfcp = 0;

    if (not new.icm_cst in ('00', '10', '20', '70', '90')) then
    begin
      new.fcp_pfcp = 0;
      new.fcp_vfcp = 0;
    end

    if (((not new.icm_cst   in ( '10',  '30',  '70',  '90')) and (trim(coalesce(new.icm_csosn, '')) =  '')) or
        ((not new.icm_csosn in ('201', '202', '203', '900')) and (trim(coalesce(new.icm_csosn, '')) <> ''))) then
    begin
      new.fcp_vbcfcpst = 0;
      new.fcp_pfcpst   = 0;
      new.fcp_vfcpst   = 0;
    end
  
    if (((new.icm_cst                 <>  '60') and (trim(coalesce(new.icm_csosn, '')) =  '')) or
        ((coalesce(new.icm_csosn, '') <> '500') and (trim(coalesce(new.icm_csosn, '')) <> ''))) then
    begin
      new.fcp_vbcfcpstret = 0;
      new.fcp_pfcpstret   = 0;
      new.fcp_vfcpstret   = 0;
    end
  
    if (coalesce(new.fcp_pfcp, 0) <= 0) then
    begin
      new.fcp_pfcp   = 0;
      new.fcp_vbcfcp = 0;
      new.fcp_vfcp   = 0;
    end
  
    if (coalesce(new.fcp_pfcpst, 0) <= 0) then
    begin
      new.fcp_pfcpst   = 0;
      new.fcp_vbcfcpst = 0;
      new.fcp_vfcpst   = 0;
    end
  end
end
 
 ^

CREATE TRIGGER NFCE_MOVIMENTO_BI_ID FOR NFCE_MOVIMENTO 
ACTIVE BEFORE INSERT POSITION 0 
AS
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;
  if (coalesce(new.id, 0) = 0) then
  begin
    select max(mov.id) from nfce_movimento mov where mov.cod_empresa = new.cod_empresa
      into new.id;
    new.id = coalesce(new.id, 0) + 1;
  end
end ^

CREATE TRIGGER NFCE_MOVIMENTO_LANC_BI_ID FOR NFCE_MOVIMENTO_LANC 
ACTIVE BEFORE INSERT POSITION 0 
as
BEGIN   
  if (substring(user from 1 for 4) = 'REPL') then
    exit;
  if (coalesce(new.mov_seq, 0) = 0) then
  begin
    update nfce_movimento mov set mov.count_op = coalesce(mov.count_op, 0) + 1
      where mov.id = new.mov_id and mov.cod_empresa = new.cod_empresa
        returning mov.count_op into new.mov_seq;
  end
END ^

CREATE TRIGGER NFCE_PAGAMENTO_BI_ID FOR NFCE_PAGAMENTO 
ACTIVE BEFORE INSERT POSITION 0 
as
begin
  if (coalesce(new.SEQID, 0) = 0) then
    new.SEQID = (select COD from INCREMENTA_CODIGO(new.COD_EMPRESA, 'NFCE_PAGAMENTO'));
  if (coalesce(new.GUIDT, '') = '') then
    new.GUIDT = (select GUID from SPDB_GUID);
  if (coalesce(new.GUID_NFCE, '') = '') then
    new.GUID_NFCE = (select GUIDT from NFCE where COD_NFCE = new.COD_NFCE and COD_EMPRESA = new.COD_EMPRESA);
end ^

CREATE TRIGGER NFCE_PAGAMENTO_BIU1_CODNFCE_TRC FOR NFCE_PAGAMENTO 
ACTIVE BEFORE INSERT OR UPDATE POSITION 1 
AS
  declare variable nfceId integer;
  declare variable status varchar(10);
  declare variable situacao varchar(16);
begin
  if (trim(coalesce(new.guid_tr_cartao, '')) = '') then
    exit;

  select nfce.status, nfce.situacao_nfce from nfce
    where nfce.cod_nfce = new.cod_nfce and nfce.cod_empresa = new.cod_empresa
  into :status, :situacao;

  if (coalesce(status, '') <> 'Fechada') then
    exit;

  if (coalesce(situacao, '') in ('Cancelada', 'Denegada', 'Inutilizada')) then
    exit;

  select nrequisicao from transacao_cartao
    where guidt = new.guid_tr_cartao and cod_empresa = new.cod_empresa and tpdocs = 'NFCE'
  into :nfceid;

  if (coalesce(nfceid, 0) = 0) then
    exit;

  if (nfceid <> new.cod_nfce) then
    update transacao_cartao set nrequisicao = new.cod_nfce
      where guidt = new.guid_tr_cartao and cod_empresa = new.cod_empresa and tpdocs = 'NFCE';
end ^

CREATE TRIGGER NFCE_STATUS_SERVICO_BI_ID FOR NFCE_STATUS_SERVICO 
ACTIVE BEFORE INSERT POSITION 0 
AS
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;
  
  if (new.DATAHORA is null) then
    select CURRENT_TS
    from SP_CURRENT_TS(new.COD_EMPRESA)
      into new.DATAHORA;  

  if (coalesce(new.ID, 0) <= 0) then
    new.ID = next value for SEQ_STATUS_SERVICO;	

  if (new.ID > 99999999) then
    execute statement 'ALTER SEQUENCE SEQ_STATUS_SERVICO RESTART WITH 0';
end ^

CREATE TRIGGER NFC_CENTRAL_ACOES_BI0 FOR NFC_CENTRAL_ACOES 
ACTIVE BEFORE INSERT POSITION 0 
as
  declare variable CURRENT_TS timestamp;
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  select CURRENT_TS
  from SP_CURRENT_TS(new.COD_EMPRESA)
    into :CURRENT_TS;

  if (coalesce(new.SEQID, 0) = 0) then
    new.SEQID = gen_id(GEN_NFC_CENTRAL_ACOES, 1);
  if (new.DATA_CADASTRO is null) then
    new.DATA_CADASTRO = CURRENT_TS;
end ^

CREATE TRIGGER TI_BI_NFSE_CANCELADAS_SEQID FOR NFSE_CANCELADAS 
ACTIVE BEFORE INSERT POSITION 0 
AS
    DECLARE VARIABLE COD INTEGER;
BEGIN
    SELECT COD FROM INCREMENTA_CODIGO(NEW.COD_EMPRESA, 'NFSE_CANCELADAS_SEQID') INTO :COD;
    NEW.SEQID = :COD;
END ^

CREATE TRIGGER NF_DESTINADAS_BU_HIST FOR NF_DESTINADAS 
ACTIVE BEFORE UPDATE POSITION 0 
AS
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (coalesce(old.csitconf, 0) <> coalesce(new.csitconf, 0)) then
    if (not exists (select first 1 1 from nf_destinadas_hist where chave_nfe = new.chave_nfe and cod_empresa = new.cod_empresa and csitconf = new.csitconf)) then
      insert into nf_destinadas_hist (chave_nfe, cod_empresa, csitconf, data)
      values (new.chave_nfe, new.cod_empresa, new.csitconf, (select ts.current_ts from sp_current_ts(new.cod_empresa) ts));
end
 
 ^

CREATE TRIGGER NOTAFISCAL_BI_GUID FOR NOTAFISCAL 
ACTIVE BEFORE INSERT POSITION 0 
as
begin
  if (coalesce(new.GUIDT, '') = '') then
    new.GUIDT = (select GUID from SPDB_GUID);
end ^

CREATE TRIGGER NOTAFISCAL_BU_AJUSTE_EST FOR NOTAFISCAL 
ACTIVE BEFORE UPDATE POSITION 0 
AS
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (coalesce(new.id_ajuste, 0) = 0) then
    exit;

  if (((coalesce(old.status ,'') <> coalesce(new.status ,'')) and (coalesce(new.status ,'') = 'Cancelada')) or
     (((coalesce(old.situacao_nfe ,'') <> coalesce(new.situacao_nfe ,'')) and (coalesce(new.situacao_nfe ,'') in ('Cancelada', 'Inutilizada', 'Denegada'))))) then
  begin
    update estoque_ajuste_itens set cod_nf = null, nitem = null
      where id_ajuste = old.id_ajuste and cod_empresa = old.cod_empresa and cod_nf = old.cod_nf;

    update estoque_ajuste set status = 'Aberto'
      where id_ajuste = old.id_ajuste and cod_empresa = old.cod_empresa and status = 'Concluido';

    new.id_ajuste = null;
  end
end ^

CREATE TRIGGER TI_NOTAFISCAL_COM_FAT_NFE FOR NOTAFISCAL 
ACTIVE BEFORE UPDATE POSITION 0 
AS
begin
  if ((new.tipo_nf = 'V') and (new.modelo_nf = '55') and
    (new.natureza_nf = 'S') and (new.n_comando > 0)) then
  begin
    if ((new.situacao_nfe <> old.situacao_nfe) or
    ((not new.situacao_nfe is null) and (old.situacao_nfe is null)) )  then
    begin
      update com_fat set
        com_fat.resultado_envio = new.resultado_envio,
        com_fat.data_autorizacao = new.data_autorizacao,
        com_fat.situacao_nfe = new.situacao_nfe,
        com_fat.digest = new.digest,
        com_fat.protocolo = new.protocolo,
        com_fat.codigoerro = new.codigoerro,
        com_fat.descricaoerro = new.descricaoerro,
        com_fat.temporesposta = new.temporesposta,
        com_fat.hora_envio = new.hora_envio,
        com_fat.tiponfe = new.tiponfe,
        com_fat.danfeimpresso = new.danfeimpresso,
        com_fat.datahora_envio = new.datahora_envio,
        com_fat.chave_nfe = new.chave_nfe,
        com_fat.n_form_seguranca = new.n_form_seguranca,
        com_fat.num_nf_vndant = new.num_nf_vndant,
        com_fat.sub_serieant = new.sub_serieant,
        com_fat.just_cancelamento = new.just_cancelamento,
        com_fat.com_prod = new.com_prod,
        com_fat.com_serv = new.com_serv,
        com_fat.inutilnfant = new.inutilnfant
      where com_fat.n_comando = new.n_comando and
        com_fat.cod_empresa = new.cod_empresa;
    end
    
    if ((new.resultado_envio <> old.resultado_envio) or
    ((not new.resultado_envio is null) and (old.resultado_envio is null)) )  then
    begin
      update com_fat set
        com_fat.resultado_envio = new.resultado_envio
      where com_fat.n_comando = new.n_comando and
        com_fat.cod_empresa = new.cod_empresa;
    end
  end
end ^

CREATE TRIGGER TI_NOTAFISCAL_HIST_ESTMOTO FOR NOTAFISCAL 
ACTIVE BEFORE UPDATE POSITION 0 
AS
begin
if ((new.cod_nf > 0) and
   ((coalesce(new.situacao_nfe, '') <> coalesce(old.situacao_nfe,'')) or
   (coalesce(new.status, '') <> coalesce(old.status,'')))) then
 begin
     update hist_estmoto h set h.situacao_nfe = new.situacao_nfe, h.status_nfe = new.status
     where (trim(coalesce(h.tipo, '')) = 'NF')
     and (trim(coalesce(h.natureza, '')) = new.natureza_nf)
     and h.numdoc = new.cod_nf and h.cod_empresa = new.cod_empresa;
 end
end ^

CREATE TRIGGER NOTAFISCAL_AU_NUMNF_REP FOR NOTAFISCAL 
ACTIVE AFTER UPDATE POSITION 0 
AS
declare variable VNUMNF integer;
begin
  if ( (old.emissao_propria = new.emissao_propria) and
       (old.natureza_nf = new.natureza_nf) and
       (old.num_gerado = new.num_gerado) and
       (old.status = new.status) and
       (old.num_nf = new.num_nf) ) then
    exit;

    if ((((new.emissao_propria = 'S') and (new.natureza_nf = 'S')) or
    ((new.emissao_propria = 'S') and (new.natureza_nf = 'E') and (new.num_gerado = 'S'))) and
    (new.num_nf > 0) ) then
  begin

    select first 1 num_nf from notafiscal nf where nf.num_nf = new.num_nf and nf.cod_empresa = new.cod_empresa and
      nf.modelo_nf = new.modelo_nf and nf.serie = new.serie and nf.emissao_propria = 'S' and
      nf.cod_nf <> new.cod_nf and
      ((nf.natureza_nf = 'S') or ( (nf.natureza_nf = 'E') and (nf.num_gerado = 'S') )) into :VNUMNF;

    if (coalesce(:vnumnf,0) > 0) then
      EXCEPTION exc_num_nf_repetido;

  end
end
 
 ^

CREATE TRIGGER TR_NOTAFISCAL_EST_PRE_NF FOR NOTAFISCAL 
ACTIVE AFTER UPDATE POSITION 0 
AS
  declare variable vtipo_item char(1);
  declare variable vgrupo_prod integer;
  declare variable vcod_prod char(6);
  declare variable vcod_grade integer;
  declare variable vnitem integer;
  declare variable vquantidade t_d_quant;
  declare variable vvalor_unitario t_vl_todos;
  declare variable vvalor_total t_vl_todos;
  declare variable vprec_cusm_prod t_vl_todos;
  declare variable vcodigo_nop t_n_geral;
  declare variable valt_est char(1);
  declare variable valiq_icm t_n_geral;
  declare variable vbase_icm t_vl_todos;
  declare variable vvalor_icm t_vl_todos;
  declare variable valiq_icmsub t_n_geral;
  declare variable vbase_icmsub t_vl_todos;
  declare variable vvalor_icmsub t_vl_todos;
  declare variable valiq_ipi t_n_geral;
  declare variable vbase_ipi t_vl_todos;
  declare variable vvalor_ipi t_vl_todos;
  declare variable vchassi char(17);
  declare variable vbaixa_estoque integer;
begin
  /* Trigger text */
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (new.natureza_nf <> 'S') then
    exit;

  if (new.tipo_nf <> 'P') then
    exit;

  if (trim(coalesce(old.status, '')) <> 'ImportaXML') then
    exit;

  if (trim(coalesce(new.status, '')) <> 'Fechada') then
    exit;
  
  select config_sistema.value1_f from config_sistema
  where config_sistema.chave = 'nf_s_baixa_estoque_import'
  and config_sistema.cod_empresa = new.cod_empresa into :vbaixa_estoque;

  if (coalesce(vbaixa_estoque, 0) <= 0) then
    exit;

  for select notafiscal_item.tipo_item,
      notafiscal_item.grupo_prod,
      notafiscal_item.cod_prod,
      notafiscal_item.cod_grade,
      notafiscal_item.nitem,
      notafiscal_item.quantidade,
      notafiscal_item.valor_unitario,
      notafiscal_item.valor_total,
      notafiscal_item.prec_cusm_prod,
      notafiscal_item.codigo_nop,
      nat_op.alt_est,
      notafiscal_item.aliq_icm,
      notafiscal_item.base_icm,
      notafiscal_item.valor_icm,
      notafiscal_item.aliq_icmsub,
      notafiscal_item.base_icmsub,
      notafiscal_item.valor_icmsub,
      notafiscal_item.aliq_ipi,
      notafiscal_item.base_ipi,
      notafiscal_item.valor_ipi,
      notafiscal_item.chassi from notafiscal_item
      left join nat_op on nat_op.codigo_nop = notafiscal_item.codigo_nop
      where notafiscal_item.cod_nf = new.cod_nf
      and notafiscal_item.cod_empresa = new.cod_empresa
      order by notafiscal_item.nitem
        into :vtipo_item, :vgrupo_prod, :vcod_prod, :vcod_grade,
          :vnitem, :vquantidade, :vvalor_unitario, :vvalor_total,
          :vprec_cusm_prod, :vcodigo_nop, :valt_est,
          :valiq_icm, :vbase_icm, :vvalor_icm,
          :valiq_icmsub, :vbase_icmsub, :vvalor_icmsub,
          :valiq_ipi, :vbase_ipi, :vvalor_ipi,
          :vchassi do
  begin
    if ((trim(coalesce(vtipo_item, '')) = 'P') and (coalesce(valt_est, 'S') <> 'N')) then
    begin
      update notafiscal_item set notafiscal_item.altera_estoque_cfop = 'S'
      where notafiscal_item.cod_nf = new.cod_nf
      and notafiscal_item.cod_empresa = new.cod_empresa
      and notafiscal_item.nitem = :vnitem;

      execute procedure movimenta_estoque
        (:vgrupo_prod, :vcod_prod, new.cod_empresa, :vcod_grade, 0, :vquantidade, 1);

      insert into hist_estoque_diario_prod (tipo, seqid, cod_empresa,
       tipor, natureza, data, grupo_prod, cod_prod, cod_grade, chassi, numero, qtde,
       valor_unit, valor_tot, alterou_custo, custo_med, nitem, cod_cliente, cod_vendedor, cod_cfop,
       aliq_icm, base_icm, valor_icm, aliq_st, base_st, valor_st,
       aliq_ipi, base_ipi, valor_ipi, cod_nf, baixou_est)
      values (:vtipo_item, (select cod from incrementa_codigo(new.cod_empresa, 'HIST_ESTOQUE_DIARIO_PROD')), new.cod_empresa,
       'NF', 'S', new.data_lanc, :vgrupo_prod, :vcod_prod, :vcod_grade, :vchassi, new.num_nf, :vquantidade,
       :vvalor_unitario, :vvalor_total, 'N', :vprec_cusm_prod, :vnitem, new.cod_cliente, new.cod_vendedor, :vcodigo_nop,
       :valiq_icm, :vbase_icm, :vvalor_icm, :valiq_icmsub, :vbase_icmsub, :vvalor_icmsub,
       :valiq_ipi, :vbase_ipi, :vvalor_ipi, new.cod_nf, 'S');
    end
  end
end ^

CREATE TRIGGER NOTAFISCAL_DEL_CONTAS_A_PAG FOR NOTAFISCAL 
ACTIVE BEFORE DELETE POSITION 0 
as
  declare variable vunificado char(1);
begin
  if ((old.natureza_nf = 'E') and (old.emissao_propria = 'N')) then
  begin
    select coalesce(e.financeiro_unificado, '')
      from empresa e where e.cod_empresa = old.cod_empresa into :vunificado;

    if (:vunificado = 'S') then
    begin
      delete from contas_a_pagar where num_nota_nfe = old.num_nf and
        cod_forn_nfe = old.cod_cliente and cod_emp_mult = old.cod_empresa and
        (( status_ctp <> 'QUITADO' ) or ( status_ctp is null ));
    end
    else
    begin
      delete from contas_a_pagar where num_nota_nfe = old.num_nf and
        cod_forn_nfe = old.cod_cliente and codigo_emp = old.cod_empresa and
        (( status_ctp <> 'QUITADO' ) or ( status_ctp is null ));
    end
  end
end ^

CREATE TRIGGER TI_NOTAFISCAL_NF_TRANSITO FOR NOTAFISCAL 
ACTIVE BEFORE DELETE POSITION 0 
AS
  DECLARE VARIABLE STAT_NF INTEGER;
BEGIN
  IF ((OLD.TIPO_NF = 'V') AND (OLD.NATUREZA_NF = 'E')) THEN
  BEGIN
    STAT_NF = 0;
    SELECT COUNT(NF_TRANSITO.NUM_NOTAT) FROM NF_TRANSITO
              WHERE OLD.NUM_NF = NF_TRANSITO.NUM_NOTAT AND OLD.COD_EMPRESA = NF_TRANSITO.COD_EMPRESA
              AND SUBSTRING(RTRIM(LTRIM(OLD.SERIE)) FROM 1 FOR 3) = NF_TRANSITO.SERIET
              AND OLD.N_CAIXA = NF_TRANSITO.N_CAIXA
              INTO :STAT_NF;
    IF (STAT_NF > 0) THEN
    BEGIN
      UPDATE NF_TRANSITO SET NF_TRANSITO.STATUST = '' WHERE OLD.NUM_NF = NF_TRANSITO.NUM_NOTAT
      AND SUBSTRING(RTRIM(LTRIM(OLD.SERIE)) FROM 1 FOR 3) = LTRIM(RTRIM(NF_TRANSITO.SERIET))
      AND OLD.COD_EMPRESA = NF_TRANSITO.COD_EMPRESA AND OLD.N_CAIXA = NF_TRANSITO.N_CAIXA;
    END
  END
END ^

CREATE TRIGGER NOTAFISCAL_BOLETAS FOR NOTAFISCAL 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
begin
  if ((coalesce(new.situacao_nfe,'')='Autorizada') and (coalesce(old.situacao_nfe,'') <> new.situacao_nfe) and (trim(new.modelo_nf)='55')) then
  begin
   update boletas set boletas.nf_aut = 'S' where boletas.num_nf_vnd = new.num_nf and boletas.cod_empresa = new.cod_empresa and boletas.nf_aut <> 'S' and cast (boletas.sub_serie as varchar(11)) = cast(new.serie as varchar(11));
  end
  else if (trim(new.modelo_nf) <> '55') then
  begin
   update boletas set boletas.nf_aut = 'S' where boletas.num_nf_vnd = new.num_nf and boletas.cod_empresa = new.cod_empresa and boletas.nf_aut <> 'S' and cast (boletas.sub_serie as varchar(11)) = cast(new.serie as varchar(11));
  end
end ^

CREATE TRIGGER NOTAFISCAL_DATA_ESTOQUE FOR NOTAFISCAL 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
as
  declare variable CURRENT_TS timestamp;
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  select CURRENT_D
  from SP_CURRENT_TS(new.COD_EMPRESA)
    into :CURRENT_TS;

  if (updating) then
  begin
    if ((trim(coalesce(old.STATUS, '')) <> trim(coalesce(new.STATUS, ''))) and
        (trim(coalesce(new.STATUS, '')) = 'Fechada')) then
      new.DATA_ESTOQUE = :CURRENT_TS;
  end
  else
  if (inserting) then
  begin
    if (trim(coalesce(new.STATUS, '')) = 'Fechada') then
      new.DATA_ESTOQUE = :CURRENT_TS;
  end
end
 
 ^

CREATE TRIGGER TI_NOTAFISCAL_MOD21 FOR NOTAFISCAL 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
begin
  if (((new.MODELO_NF <> '06') and (new.MODELO_NF <> '21') and (new.MODELO_NF <> '22'))
    and (not new.ID_MODELO21 is null)) then
    new.ID_MODELO21 = null;
  if ((new.MODELO_NF = '06') or (new.MODELO_NF = '21') or (new.MODELO_NF = '22')) then
    if ((new.ID_MODELO21 is null) or (old.data_lanc <> new.data_lanc)) then
      new.ID_MODELO21 = (select result from strzero(extract(month from new.data_lanc), 2))||extract(year from new.data_lanc);
end ^

