CREATE TRIGGER NOTAFISCAL_ITEM_HIST_ESTOQUE_D FOR NOTAFISCAL_ITEM 
ACTIVE BEFORE DELETE POSITION 0 
AS
 declare variable vnatureza char(1);
 declare variable vtiponf char(1);
 declare variable vnumero integer;
 declare variable vcodcliente integer;
 declare variable vcodvendedor integer;
 declare variable vdataestoque timestamp;
 declare variable vstatus varchar(10);
 declare variable CURRENT_TS timestamp;
begin
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit;

  select notafiscal.natureza_nf, notafiscal.tipo_nf, notafiscal.num_nf, notafiscal.cod_cliente, notafiscal.cod_vendedor,
  notafiscal.data_estoque, notafiscal.status from notafiscal
  where notafiscal.cod_nf = old.cod_nf and notafiscal.cod_empresa = old.cod_empresa
    into :vnatureza, :vtiponf, :vnumero, :vcodcliente, :vcodvendedor, :vdataestoque, :vstatus;

  if (trim(vnatureza) <> 'E') then
    exit;

  if (trim(vtiponf) <> 'P') then
    exit;

  if (trim(coalesce(vstatus, '')) <> 'Fechada') then
    exit;

  if (trim(old.altera_estoque_cfop) = 'N') then
    exit;

  insert into hist_estoque_diario_prod (tipo, seqid, cod_empresa,
   tipor, natureza, data, grupo_prod, cod_prod, cod_grade, chassi, numero, qtde,
   valor_unit, valor_tot, alterou_custo, custo_med, nitem, cod_cliente, cod_vendedor, cod_cfop,
   aliq_icm, base_icm, valor_icm, aliq_st, base_st, valor_st,
   aliq_ipi, base_ipi, valor_ipi, cod_nf)
   values (old.tipo_item, (select cod from incrementa_codigo(old.cod_empresa, 'HIST_ESTOQUE_DIARIO_PROD')), old.cod_empresa,
   'NF', 'E', :vdataestoque, old.grupo_prod, old.cod_prod, old.cod_grade, old.chassi, :vnumero, old.quantidade,
   old.valor_unitario, old.valor_total, 'N', old.prec_cusm_prod, old.nitem, :vcodcliente, :vcodvendedor, old.codigo_nop,
   old.aliq_icm, old.base_icm, old.valor_icm, old.aliq_icmsub, old.base_icmsub, old.valor_icmsub,
   old.aliq_ipi, old.base_ipi, old.valor_ipi, old.cod_nf);

  select current_d from sp_current_ts(old.cod_empresa) into :current_ts;

  insert into hist_estoque_diario_prod (tipo, seqid, cod_empresa,
   tipor, natureza, data, grupo_prod, cod_prod, cod_grade, chassi, numero, qtde,
   valor_unit, valor_tot, alterou_custo, custo_med, nitem, cod_cliente, cod_vendedor, cod_cfop,
   aliq_icm, base_icm, valor_icm, aliq_st, base_st, valor_st,
   aliq_ipi, base_ipi, valor_ipi, cod_nf)
   values (old.tipo_item, (select cod from incrementa_codigo(old.cod_empresa, 'HIST_ESTOQUE_DIARIO_PROD')), old.cod_empresa,
   'NF', 'S', :current_ts, old.grupo_prod, old.cod_prod, old.cod_grade, old.chassi, :vnumero, old.quantidade,
   old.valor_unitario, old.valor_total, 'N', old.prec_cusm_prod, old.nitem, :vcodcliente, :vcodvendedor, old.codigo_nop,
   old.aliq_icm, old.base_icm, old.valor_icm, old.aliq_icmsub, old.base_icmsub, old.valor_icmsub,
   old.aliq_ipi, old.base_ipi, old.valor_ipi, old.cod_nf);
end ^

CREATE TRIGGER NOTAFISCAL_ITEM_BIU_SINT_CALC FOR NOTAFISCAL_ITEM 
ACTIVE BEFORE INSERT OR UPDATE POSITION 10 
AS
  declare variable vliq double precision;
  declare variable vimpostos double precision;
  declare variable vbc double precision;
  declare variable cst char(3);
begin  
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  select first 1
         (iif(nf.frete_f_nfe = 'S', 0, coalesce(new.rateio_frete, 0)) - iif(nf.totais_com_deson = 'N', 0, coalesce(new.vicmdeson, 0))),
         (iif(new.tipo_item = 'S', coalesce(new.base_iss, 0), coalesce(new.base_icm, 0)))
  from notafiscal_item nfi
    inner join notafiscal nf on nf.cod_nf = nfi.cod_nf and nf.cod_empresa = nfi.cod_empresa
  where nfi.cod_nf = new.cod_nf and nfi.cod_empresa = new.cod_empresa and nfi.nitem = new.nitem
    into :vliq, :vbc;

  vliq =   coalesce(vliq, 0)
         + coalesce(new.valor_total, 0)
         + coalesce(new.rateio_seguro, 0)
         + coalesce(new.rateio_outdesp, 0)
         + coalesce(new.valor_icmsub, 0)
         + coalesce(new.fcp_vfcpst, 0)
         + coalesce(new.valor_ipi, 0)
         + coalesce(new.nfe_vipidevol, 0)
         - coalesce(new.rateio_desconto, 0)
         - coalesce(new.vpisdeson, 0)
         - coalesce(new.vcofinsdeson, 0);

  vimpostos = + coalesce(new.valor_icmsub, 0)
              + coalesce(new.fcp_vfcpst, 0)
              + coalesce(new.valor_ipi, 0)
              + coalesce(new.nfe_vipidevol, 0);

  vbc = coalesce(vbc, 0);

  cst = iif(new.tipo_item = 'S', '040', new.cst);
  
  select c.visento, c.voutro, 0 from sp_calc_vl_sint(:cst, :vliq, :vbc, :vimpostos) as c
    into new.vlisento, new.vloutras, new.vln_trib;

  vbc = 0;
end
 
 ^

CREATE TRIGGER NOTAFISCAL_DEL_TRIBDFE FOR NOTAFISCAL_ITEM 
ACTIVE BEFORE UPDATE OR DELETE POSITION 0 
as
begin
  if ( deleting and (coalesce(old.dfe_trib_id, '') <> '')) then
  begin
    delete from dfe_trib_contexto
    where id = old.dfe_trib_id and origem = 0;
  end
  if ( updating and (coalesce(old.dfe_trib_id, '') <> '') and (coalesce(new.dfe_trib_id, '') = '')) then
  begin
    delete from dfe_trib_contexto
    where id = old.dfe_trib_id and origem = 0;
  end
end ^

CREATE TRIGGER NOTAFISCAL_ITEM_BU_PEDCL FOR NOTAFISCAL_ITEM 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
AS
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (new.tipo_item <> 'P' or coalesce(Trim(new.cod_prod),  '') = '' or new.grupo_prod is null) then
    exit;

  -- qualquer alteracao na referencia do pedido vamos excluir

  -- aqui quando deixa algum campo vazio
  if ( updating and
    (coalesce(trim(old.xped_compra), '') <> '' and old.nitemped_compra > 0) and
    (coalesce(trim(new.xped_compra), '') = '' or new.nitemped_compra = 0)
  ) then
    delete from pedidocompracl_itens_env
      where cod_nf = old.cod_nf and cod_empresa = old.cod_empresa and nitem_nf = old.nitem;

  -- aqui quando muda o numero do pedido ou numero do item
  else if ( deleting or ( updating and
    (coalesce(trim(old.xped_compra), '') <> '' and old.nitemped_compra > 0) and
    (old.xped_compra <> new.xped_compra or old.nitemped_compra <> new.nitemped_compra))
  ) then
  begin
    delete from pedidocompracl_itens_env
      where cod_nf = old.cod_nf and cod_empresa = old.cod_empresa and nitem_nf = old.nitem;

    if (updating) then
      delete from pedidocompracl_itens_env
        where cod_nf = new.cod_nf and cod_empresa = new.cod_empresa and nitem_nf = new.nitem;
  end
  
  -- aqui altera apenas a quantidade
  else if ( updating and
    (coalesce(old.xped_compra, '') = new.xped_compra and coalesce(old.nitemped_compra, 0) = new.nitemped_compra and coalesce(old.quantidade, 0) <> new.quantidade)
  ) then
  begin
    update pedidocompracl_itens_env set qtde_env = new.quantidade
        where cod_nf = new.cod_nf and cod_empresa = new.cod_empresa and nitem_nf = new.nitem;
  end

  -- registro no historico de envios
  if ( inserting or ( updating and
    (coalesce(trim(new.xped_compra), '') <> '' and new.nitemped_compra > 0) and
    (coalesce(old.xped_compra,'') <> new.xped_compra or coalesce(old.nitemped_compra, 0) <> new.nitemped_compra))
  ) then
  begin
    merge into pedidocompracl_itens_env env
    using (
      select pit.codigo, pit.nitem, pit.quant, sum(coalesce(env.qtde_env,0)) qtde_env,
             sum(iif((env.nitem_nf = new.nitem) and (env.cod_nf = new.cod_nf), 1, 0)) nitemexiste
      from pedidocompracl_itens pit
        inner join notafiscal nf on nf.cod_nf = new.cod_nf and nf.cod_empresa = new.cod_empresa
        inner join pedidocompracl pd on pd.codigo = pit.codigo and pd.cod_empresa = pit.cod_empresa and pd.cod_cliente = nf.cod_cliente
        left join pedidocompracl_itens_env env on env.codigo = pit.codigo and env.cod_empresa = pit.cod_empresa
          and env.nitem = pit.nitem
      where pit.grupo_prod = new.grupo_prod and pit.cod_prod = new.cod_prod and pit.cod_empresa = new.cod_empresa
        and pit.cod_grade = coalesce(new.cod_grade, 0) and pit.nitem_nfe = new.nitemped_compra
        and coalesce(pit.enviado,'') <> 'S'
      group by codigo, nitem, quant
      having sum(coalesce(env.qtde_env,0)) < pit.quant
    ) pit
    on (pit.qtde_env > 0 and pit.nitemexiste > 0)
    when not matched then
      insert (codigo, cod_empresa, nitem, cod_nf, nitem_nf, qtde_env)
      values (pit.codigo, new.cod_empresa, pit.nitem, new.cod_nf, new.nitem, new.quantidade);
  end
end
 
 ^

