CREATE TRIGGER TI_OS_ITEM_PROD_UP FOR OS_ITEM_PROD 
ACTIVE AFTER UPDATE POSITION 0 
AS
begin
  /* Trigger text */
  if (( old.grupo_prod <> new.grupo_prod ) or ( old.cod_prod <> new.cod_prod ) or (old.codigo_nop <> new.codigo_nop)) then
    update pedvenda_prod set pedvenda_prod.grupo_prod = new.grupo_prod, pedvenda_prod.cod_prod = new.cod_prod,
    pedvenda_prod.codigo_nop = new.codigo_nop where pedvenda_prod.grupo_prod = old.grupo_prod and
    pedvenda_prod.cod_prod = old.cod_prod and pedvenda_prod.codigo_nop = old.codigo_nop and
    pedvenda_prod.cod_empresa = old.cod_empresa and pedvenda_prod.nped = old.n_os and
    ((pedvenda_prod.tipo = 'OS') or (pedvenda_prod.tipo = 'OS '));
