CREATE TRIGGER TI_EVD_PAF_DOCBASEATEST FOR PAF_DOC_BASE_ATEST 
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 0 
AS                                      
  declare variable vcodempresa integer; 
  declare variable vtiporegistro varchar(3);
  declare variable vdata timestamp;
  declare variable vcamposchave varchar(100);
  declare variable vvalorechave varchar(100);
  declare variable vmd5 varchar(256);
  declare variable vacao varchar(1);
begin
  vtiporegistro = 'AE';
  vcamposchave = '|DATA_AT|COD_EMPRESA|';
  if (inserting) then
  begin              
    vcodempresa =  new.cod_empresa;
    vdata = new.data_at;
    vvalorechave = '|'||new.data_at||'|'||new.cod_empresa||'|';
    vmd5 = new.md5;
    vacao = 'I';
    execute procedure sp_evd_paf(vcodempresa, vtiporegistro, vdata, vcamposchave, vvalorechave, substring(vmd5 from 1 for 32), vacao);
  end
  else if ((deleting) or (updating)) then
  begin              
    vcodempresa =  old.cod_empresa;
    vdata = old.data_at;
    vvalorechave = '|'||old.data_at||'|'||old.cod_empresa||'|';
    vmd5 = old.md5;
    vacao = 'D';
    if ((deleting) or (coalesce(new.md5, '') <> '') and (coalesce(old.md5, '') = '')) then
      execute procedure sp_evd_paf(vcodempresa, vtiporegistro, vdata, vcamposchave, vvalorechave, substring(vmd5 from 1 for 32), vacao);
  end
END
 
 ^

CREATE TRIGGER PEDIDOCOMPRACL_ITENS_ENV_BID0 FOR PEDIDOCOMPRACL_ITENS_ENV 
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 0 
AS
  declare variable qtdeped t_vl_todos;
  declare variable qtdeenv t_vl_todos;
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  qtdeped = null;
  qtdeenv = null;

  -- caso a subtracao da quantidade com a soma dos enviados seja maior que zero
  if (deleting) then
    for select pit.quant, sum(coalesce(env.qtde_env,0))
      from pedidocompracl_itens pit
      left join pedidocompracl_itens_env env on env.codigo = pit.codigo and env.cod_empresa = pit.cod_empresa and env.nitem = pit.nitem
        and env.cod_nf <> old.cod_nf and env.nitem_nf <> old.nitem_nf
      where pit.codigo = old.codigo and pit.cod_empresa = old.cod_empresa and pit.nitem = old.nitem
      group by quant
        into :qtdeped, :qtdeenv
    do
    begin
      if (qtdeped > qtdeenv) then
        update pedidocompracl_itens pit set pit.enviado = 'N'
          where pit.codigo = old.codigo and pit.cod_empresa = old.cod_empresa and pit.nitem = old.nitem and coalesce(pit.enviado, '') <> 'N';
    end

  if (not deleting) then
    for select pit.quant, sum(coalesce(env.qtde_env,0))
      from pedidocompracl_itens pit
      inner join pedidocompracl_itens_env env on env.codigo = pit.codigo and env.cod_empresa = pit.cod_empresa and env.nitem = pit.nitem
      where pit.codigo = new.codigo and pit.cod_empresa = new.cod_empresa and pit.nitem = new.nitem
      group by quant
        into :qtdeped, :qtdeenv
    do
    begin
      update pedidocompracl_itens pit set pit.enviado = iif((:qtdeenv - :qtdeped) > -0.001, 'S', 'N')
        where pit.codigo = new.codigo and pit.cod_empresa = new.cod_empresa and pit.nitem = new.nitem and coalesce(pit.enviado, '') <> iif((:qtdeenv - :qtdeped) > -0.001, 'S', 'N');
    end
end
 
 ^

