            'Iniciado');
  end
end ^

CREATE TRIGGER PEDVENDA_BIU_CONF_TOTAL FOR PEDVENDA 
ACTIVE BEFORE UPDATE POSITION 0 
AS
  declare variable vverificar_total char(1);
  declare variable val_tot t_vl_todos;
  declare variable val_acr t_vl_todos;
  declare variable val_des t_vl_todos;
  declare variable sum_prod t_vl_todos;
  declare variable sum_serv t_vl_todos;
  declare variable sum_total t_vl_todos;
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  vverificar_total = 'N';
  if ((coalesce(old.status_ped, '') <> 'FECHADA') and (coalesce(new.status_ped, '') = 'FECHADA')) then
    vverificar_total = 'S';
  else if ((coalesce(old.prep_impressao, 'N') <> coalesce(new.prep_impressao, 'S')) and (coalesce(new.prep_impressao, 'S') = 'S')) then
    vverificar_total = 'S';

  if (trim(vverificar_total) = 'S') then
  begin
    sum_prod = 0;
    sum_serv = 0;
    sum_total = 0;

    --Produtos
    select sum(coalesce(pvp.vltot_ped_item, 0)),
      sum(coalesce(pvp.rateio_desc, 0)),
      sum(coalesce(pvp.rateio_acresc, 0)) from pedvenda_prod pvp
      where pvp.nped = new.nped and pvp.tipo = new.tipo and pvp.cod_empresa = new.cod_empresa
        and coalesce(pvp.status, '') = ''
        into :val_tot, :val_des, val_acr;

    sum_prod = coalesce(val_tot, 0);
    sum_total = coalesce(sum_total, 0) + coalesce(val_tot, 0) + coalesce(val_acr, 0) - coalesce(val_des, 0);

    --Servicos
    select sum(coalesce(pvs.valor_tot_serv, 0)),
      sum(coalesce(pvs.rateio_desc, 0)),
      sum(coalesce(pvs.rateio_acresc, 0)) from pedvenda_serv pvs
      where pvs.nped = new.nped and pvs.tipo = new.tipo and pvs.cod_empresa = new.cod_empresa
        and coalesce(pvs.status, '') = ''
        into :val_tot, :val_des, val_acr;

    sum_serv = coalesce(val_tot, 0);
    sum_total = coalesce(sum_total, 0) + coalesce(val_tot, 0) + coalesce(val_acr, 0) - coalesce(val_des, 0);

    --Produtos Terceiro
    select sum(coalesce(pvpt.vl_total, 0)),
      sum(0),
      sum(0) from pedvenda_prod_terc pvpt
      where pvpt.nped = new.nped and pvpt.tipo = new.tipo and pvpt.cod_empresa = new.cod_empresa
        into :val_tot, :val_des, val_acr;

    sum_total = coalesce(sum_total, 0) + coalesce(val_tot, 0) + coalesce(val_acr, 0) - coalesce(val_des, 0);

    --Servicos Terceiro
    select sum(coalesce(pvt.vl_servt, 0)),
      sum(0),
      sum(0) from pedvenda_serv_terc pvt
      where pvt.nped = new.nped and pvt.tipo = new.tipo and pvt.cod_empresa = new.cod_empresa
        into :val_tot, :val_des, val_acr;

    sum_total = coalesce(sum_total, 0) + coalesce(val_tot, 0) + coalesce(val_acr, 0) - coalesce(val_des, 0);

    if (round(sum_total, 2) <> round(new.valor_total, 2)) then
    begin
      if ((coalesce(old.status_ped, '') <> 'FECHADA') and (coalesce(new.status_ped, '') = 'FECHADA')) then
        exception EXC_PED_CONF_TOTAL;
      else if ((coalesce(old.prep_impressao, 'N') <> coalesce(new.prep_impressao, 'N')) and (coalesce(new.prep_impressao, 'N') = 'S')) then
        exception EXC_PED_IMPRESSAO_TOTAL;
    end
  end
end ^

CREATE TRIGGER TI_PEDVENDA_BU_NOME_CL FOR PEDVENDA 
INACTIVE BEFORE UPDATE POSITION 0 
AS
declare variable vnomecl varchar(35);
begin
  vnomecl = '';
  if ((old.tipo = 'ORC') and (coalesce(new.nome_cli_orc, '') <> '') and (coalesce(new.nome_cli_orc, '') <> coalesce(old.nome_clientedav, '') )) then
  begin
    vnomecl = substring(new.nome_cli_orc from 1 for 35);
  end
  else
  if (new.cod_cliente <> old.cod_cliente) then
  begin
    select substring(cl.nome_cliente from 1 for 35) from clientes cl
      where cl.cod_cliente = new.cod_cliente and cl.cod_empresa = old.cod_empresa
      into :vnomecl;
  end
  
  if ((coalesce(:vnomecl,'') <> coalesce(old.nome_clientedav, '')) and ( coalesce(:vnomecl,'') <> '')) then
    new.nome_clientedav = :vnomecl;
end ^

CREATE TRIGGER TI_PEDVENDA_SUG_OS FOR PEDVENDA 
ACTIVE BEFORE UPDATE POSITION 0 
AS
    DECLARE VARIABLE vSugServico integer;
begin
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit;

  select config_sistema.value1_f from config_sistema
  where config_sistema.chave like 'sug_serv_hab'
  and config_sistema.cod_empresa = 1
  into: vSugServico;

  if (vsugservico <= 0) then
    exit;

  if (trim(coalesce(new.tipo, '')) <> 'OS') then
    exit;

  if ((trim(coalesce(old.status_ped, '')) <> trim(coalesce(new.status_ped, '')))
      and trim(coalesce(old.status_ped, '')) = 'FECHADA') then
  begin
      delete from sug_os
      where sug_os.ndoc = new.nped and sug_os.tpdoc = trim(coalesce(new.tipo, '')) and sug_os.cod_empresa = new.cod_empresa;

      update sugestaoservico set sugestaoservico.status = null, sugestaoservico.ndoc = null, sugestaoservico.tpdoc  = null
      where sugestaoservico.ndoc = new.nped and sugestaoservico.tpdoc = trim(coalesce(new.tipo, '')) and sugestaoservico.cod_empresa = new.cod_empresa;
  end
end ^

CREATE TRIGGER PEDVENDA_AU_SIT_CP_FAT FOR PEDVENDA 
ACTIVE AFTER UPDATE POSITION 0 
AS
  declare variable vnumnf integer;
  declare variable vnumoc integer;
  declare variable vcodig integer;    
  declare variable current_ts timestamp;
begin
  if ((coalesce(old.ncupom, 0) = 0) and (coalesce(new.ncupom, 0) > 0)) then
  begin
    select first 1 COD_OCORRENCIA from OCORRENCIAS_OS where NPED = new.nped and TIPO = new.tipo and COD_EMPRESA = new.cod_empresa
      and SITUACAO = 'FATURAMENTO' and STATUS_SITUACAO = 'Iniciado' into :vnumoc; 

    select CURRENT_TS from SP_CURRENT_TS(new.COD_EMPRESA) into :CURRENT_TS;

    if (coalesce(vnumoc,0) = 0) then
    begin
      select COD from INCREMENTA_CODIGO(new.cod_empresa, 'OCORRENCIAS_OS') into vcodig;
      insert into OCORRENCIAS_OS (COD_OCORRENCIA, NPED, TIPO, COD_EMPRESA, HISTORICO_OC, DATA_E_HORA, ATIVO, N_OS, SITUACAO, STATUS_SITUACAO)
        values (:vcodig, new.nped, new.tipo, new.cod_empresa, 'FATURAMENTO - Iniciado', :current_ts , 1, new.nped, 'FATURAMENTO', 'Iniciado');
    end
    
    select first 1 COD_OCORRENCIA from OCORRENCIAS_OS where NPED = new.nped and TIPO = new.tipo and COD_EMPRESA = new.cod_empresa
      and SITUACAO = 'FATURAMENTO' and STATUS_SITUACAO = 'Finalizado' into :vnumoc;

    if (coalesce(vnumoc,0) = 0) then
    begin
      select COD from INCREMENTA_CODIGO(new.cod_empresa, 'OCORRENCIAS_OS') into vcodig;
      insert into OCORRENCIAS_OS (COD_OCORRENCIA, NPED, TIPO, COD_EMPRESA, HISTORICO_OC, DATA_E_HORA, ATIVO, N_OS, SITUACAO, STATUS_SITUACAO)
        values (:vcodig, new.nped, new.tipo, new.cod_empresa, 'FATURAMENTO - Finalizado', :current_ts , 1, new.nped, 'FATURAMENTO', 'Finalizado');
    end

  end
  else if ((coalesce(old.ncupom, 0) > 0) and (coalesce(new.ncupom, 0) = 0)) then
  begin
    if ((coalesce(new.num_nf, 0) = 0) and (coalesce(new.num_nfeext, 0) = 0)) then
    begin
      select first 1 pp.n_nf from pedvenda_prod pp
        where pp.nped = new.nped and pp.tipo = new.tipo and pp.cod_empresa = new.cod_empresa and pp.n_nf > 0
        into :vnumnf;

      if (coalesce(vnumnf,0) = 0) then
      begin
        delete from OCORRENCIAS_OS where NPED = new.nped and TIPO = new.tipo and COD_EMPRESA = new.cod_empresa and
          SITUACAO = 'FATURAMENTO';
      end
    end
  end
end
 
 ^

