CREATE TRIGGER TI_PEDVENDA_BIU_STS_SEP_AUTO FOR PEDVENDA 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
  declare variable nivelus integer;
  declare variable nivelpro integer;
  declare variable vuser char(10);
  declare variable vcodigo integer;
  declare variable vseparacaoativada char(1);
begin
  if ((coalesce(new.idmobile,0) > 0) and
    (coalesce(old.env_mobile, 'N') = 'N') and
    (coalesce(new.env_mobile, 'N') = 'S') and
    (coalesce(new.status_sep_conf, '') = '')) then
  begin
    select e.usar_separacao_ped from empresa e where e.cod_empresa = new.cod_empresa into :vseparacaoativada;

    if (coalesce(:vseparacaoativada,'') = 'S') then
    begin
      select first 1 s.nivel_us, s.usuario from senhas s where s.codigo = new.cod_vendedor and s.cod_empresa = new.cod_empresa into :nivelus, :vuser;
      select first 1 tb.nivel_processo, tu.cod_empresa from tabela_processos tb
        left join tabela_processos_usuarios tu on tu.cod_processo = tb.cod_processo and tu.cod_empresa = tb.cod_empresa and tu.usuario = :vuser
        where tb.cod_processo = 'VND182' and tb.cod_empresa = new.cod_empresa into :nivelpro, :vcodigo;

      if ((coalesce(:nivelus, 0) > 0) and (coalesce(:nivelpro, 0) > 0)) then
      begin
        if ((:nivelus >= nivelpro) or (coalesce(:vcodigo,0) > 0))  then
        begin
          new.status_sep_conf = 'SEPARACAO';
        end
      end
    end
  end
end
 
 ^

CREATE TRIGGER TI_PEDVENDA_EMAIL_MARKETING FOR PEDVENDA 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
DECLARE VARIABLE  vEnvEmail char(1);
DECLARE VARIABLE  vEmail varchar(256);
DECLARE VARIABLE  vTipv char(1);
DECLARE VARIABLE  vOrcamentoSoPecas Integer;
DECLARE VARIABLE  vExistEmail Integer;
DECLARE VARIABLE  vTemp varchar(60);   
DECLARE VARIABLE CURRENT_TS timestamp;
begin
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit;

  if ((not inserting) and (not updating)) then
    exit;

  select coalesce(emp.env_mail_mark, 'N') from empresa emp
  where emp.cod_empresa = new.cod_empresa and emp.ativo = 1
  into : vEnvEmail;

  if (trim(coalesce(vEnvEmail, '')) <> 'S') then
    exit;

  select coalesce(cl.rec_mail_mark, 'N'), cl.email from clientes cl
  where cl.cod_cliente = new.cod_cliente and cl.cod_empresa = new.cod_empresa
   into : vEnvEmail, vEmail;

  if (trim(coalesce(vEnvEmail, '')) <> 'S') then
    exit;

  if (trim(coalesce(vEmail, '')) = '') then
    exit;

  if ((trim(new.tipo) = 'REQ') or (trim(new.tipo) = 'ORC')) then
  begin
      if (trim(new.tipo) = 'ORC') then
      begin
        select count(*) from pedvenda_serv serv
        where serv.nped = new.nped and serv.tipo = new.tipo and serv.cod_empresa = new.cod_empresa
         into : vOrcamentoSoPecas;
      end

      if ((trim(new.tipo) = 'REQ') or ((trim(new.tipo) = 'ORC') and (coalesce(vOrcamentoSoPecas, 0) = 0))) then
      begin
          select coalesce(tp.env_email, 'N') env_email from pedvenda pd
          left join tipo_vendas tp on tp.sigla = pd.tipv and tp.tipo = 'REQ'
          where pd.nped = new.nped and pd.tipo = new.tipo and pd.cod_empresa = new.cod_empresa
          into : vEnvEmail;
      end
      else
      begin
          select coalesce(tp.env_email, 'N') env_email from pedvenda pd
          left join tipo_vendas tp on tp.sigla = pd.tipo_orc and tp.tipo = new.tipo
          where pd.nped = new.nped and pd.tipo = new.tipo and pd.cod_empresa = new.cod_empresa
          into : vEnvEmail;
      end 
  end
  else
  begin
      select coalesce(tp.env_email, 'N') env_email from pedvenda pd
      left join tipo_vendas tp on tp.tipo_os = pd.tipo_os and tp.tipo = new.tipo
      where pd.nped = new.nped and pd.tipo = new.tipo and pd.cod_empresa = new.cod_empresa
      into : vEnvEmail;
  end

  if ((trim(coalesce(vEnvEmail, '')) <> 'A') and (trim(coalesce(vEnvEmail, '')) <> 'F')) then
     exit;

   select count(*) from email_marketing e
   where e.cod_documento = new.nped and trim(e.tipo) = trim(new.tipo) and e.cod_empresa = new.cod_empresa
    into : vExistEmail;

   if (coalesce(vexistemail, 0) > 0) then
     exit;

   if (trim(new.tipo) = 'ORC') then
     vTemp = 'Envio do Orcamento Num: ' || new.nped;
   else if (trim(new.tipo) = 'REQ') then
     vTemp = 'Envio da Requisicao Num: ' || new.nped;
   else
     vTemp = 'Envio da Ordem de Servico Num: ' || new.nped;

  select CURRENT_TS
  from SP_CURRENT_TS(new.COD_EMPRESA)
    into :CURRENT_TS;

    if (inserting) then
    begin
      if (trim(coalesce(vEnvEmail, '')) <> 'A') then
       exit;

      insert into email_marketing (CODIGO, COD_EMPRESA, COD_DOCUMENTO, ASSUNTO, TIPO, DESCRICAO, DATA_HORA, TP_ENVIO)
      values ((select cod from incrementa_codigo(new.cod_empresa, 'EMAIL_MARKETING')),
       new.cod_empresa, new.nped,
       :vTemp, trim(new.tipo), :vTemp, :CURRENT_TS, 'I');
   end
   if (updating) then
   begin
      if ( (trim(coalesce(vEnvEmail, '')) = 'A')
      or ( (trim(coalesce(old.status_ped, '')) <> trim(coalesce(new.status_ped, '')) )
        and (trim(coalesce(new.status_ped, '')) = 'FECHADA') and (trim(coalesce(vEnvEmail, '')) = 'F')) )  then

      insert into email_marketing (CODIGO, COD_EMPRESA, COD_DOCUMENTO, ASSUNTO, TIPO, DESCRICAO, DATA_HORA, TP_ENVIO)
      values ((select cod from incrementa_codigo(new.cod_empresa, 'EMAIL_MARKETING')),
       new.cod_empresa, new.nped,
       :vTemp, trim(new.tipo), :vTemp, :CURRENT_TS, 'I');
   end
end
 
 ^

