CREATE TRIGGER TR_PEDVENDA_COD_US_FECH FOR PEDVENDA 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (coalesce(new.id_commerce, 0) <= 0) then
    exit;

  if (inserting) then
  begin
    if (coalesce(new.cod_us_fech, 0) <= 0) then
      new.cod_us_fech = new.cod_vendedor;
  end
  else if (updating) then
  begin
    if (coalesce(new.cod_us_fech, 0) <= 0) then
      new.cod_us_fech = new.cod_vendedor;
  end
end;
 
