CREATE TRIGGER TR_PEDVENDA_METODO_ENT FOR PEDVENDA 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
  declare variable vmetodo_entrega varchar(100);
begin
  /* Trigger text */
  if (inserting) then
  begin
    if (coalesce(new.id_commerce, 0) <= 0) then
      exit;

    select display from formas_envio_ec f
    where f.cod_forma = new.cod_forma_rast
    and f.cod_empresa =  new.cod_empresa
      into :vmetodo_entrega;

    if (coalesce(vmetodo_entrega, '') <> '') then
      new.metodo_entrega = coalesce(:vmetodo_entrega, '');
  end
  else if (updating) then
  begin
    if (coalesce(new.id_commerce, 0) <= 0) then
      exit;

    select display from formas_envio_ec f
    where f.cod_forma = new.cod_forma_rast
    and f.cod_empresa =  new.cod_empresa
      into :vmetodo_entrega;

    if (coalesce(vmetodo_entrega, '') <> '') then
       new.metodo_entrega = coalesce(:vmetodo_entrega, '');
  end
end;
 
