CREATE TRIGGER TI_PEDVENDAPROD_DEBCRED FOR PEDVENDA_PROD 
ACTIVE AFTER UPDATE POSITION 1 
AS
  declare variable vstatus varchar(10);
  declare variable vdescricao varchar(48);
  declare variable vdescricaonew varchar(48);
  declare variable vempusadebcred char(1);
  declare variable vtipo varchar(3);
  declare variable vtipv varchar(1);
  declare variable vtipo_os varchar(10);   
  declare variable current_t timestamp;
  declare variable current_d timestamp;
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (coalesce(new.usar_debcred, 'S') = 'N') then
    exit;

  if ((coalesce(old.vl_debcred, 0) = 0) and (coalesce(new.vl_debcred, 0) = 0)) then
    exit;

  select coalesce(e.usardebitocredito, '') as usardebitocredito from empresa e
  where e.cod_empresa = new.cod_empresa
    into :vempusadebcred;

  if (vempusadebcred <> 'S') then
    exit;

  select v.status_ped, v.tipo, v.tipv, v.tipo_os from pedvenda v
  where v.nped = new.nped
  and v.tipo = new.tipo
  and v.cod_empresa = new.cod_empresa
    into :vstatus, :vtipo, :vtipv, :vtipo_os;

  if (vstatus is null) then
    vstatus='';
  if ((vstatus = 'FECHADA') and (coalesce(new.status,'') <> 'CANCELADO')) then
  begin
    if ((select retorno from sp_retorno_debitocredito(:vtipo, :vtipv, :vtipo_os)) <> 'S') then
      exit;
    /*No caso de alterar o vendedor da venda ja fechada, lancar um credito ou debito para o new e old vendedor*/
    if (coalesce(new.vl_debcred, 0) > 0) then
    begin
      vdescricao    = 'ESTORNO DE CREDITO: ITEM ';
      vdescricaonew = 'LANCAMENTO DE CREDITO: ITEM ';
    end
    else if (coalesce(new.vl_debcred, 0) < 0) then
    begin
      vdescricao    = 'ESTORNO DE DEBITO: ITEM ';
      vdescricaonew = 'LANCAMENTO DE DEBITO: ITEM ';
    end

    if ((coalesce(old.cod_vendedor, 0)) <> (coalesce(new.cod_vendedor, 0)))  then
    begin     
      select current_d, current_t from sp_current_ts(new.cod_empresa) into :current_d, :current_t;

      if ((not(old.cod_vendedor is null)) and (coalesce(old.vl_debcred, 0) <> 0)) then
      begin
        insert into LANC_DEBCRED (COD_LANC, COD_EMPRESA, COD_VENDEDOR, DATA_LANC, HORA_LANC, ORIGEM_LANC, VL_LANCDEBCRED, NPEDORIGEM, DESCRICAO)
        values ((select COD from INCREMENTA_CODIGO(old.cod_empresa, 'LANC_DEBCRED')),
        old.cod_empresa, old.cod_vendedor, :current_d ,:current_t, old.tipo,
        - (coalesce(old.vl_debcred, 0)), old.nped, :vdescricao||'|'||old.nitem||'|'||old.grupo_prod||'|'||old.cod_prod);
      end

      if ((not(new.cod_vendedor is null)) and (coalesce(new.vl_debcred, 0) <> 0)) then
      begin
        insert into LANC_DEBCRED (COD_LANC, COD_EMPRESA, COD_VENDEDOR, DATA_LANC, HORA_LANC, ORIGEM_LANC, VL_LANCDEBCRED, NPEDORIGEM, DESCRICAO)
        values ((select COD from INCREMENTA_CODIGO(new.cod_empresa, 'LANC_DEBCRED')),
        new.cod_empresa, new.cod_vendedor, :current_d, :current_t, new.tipo,
        (coalesce(new.vl_debcred, 0)), new.nped, :vdescricaonew||'|'||new.nitem||'|'||new.grupo_prod||'|'||new.cod_prod);
      end
    end
  end
end ^

