CREATE TRIGGER TI_DEL_PEDVENDA_PROD FOR PEDVENDA_PROD 
ACTIVE AFTER DELETE POSITION 0 
AS
begin
  if (old.tipo = 'REQ') then
  begin
    delete from reqvenda_itens where reqvenda_itens.nreq = old.nped and
    reqvenda_itens.cod_empresa = old.cod_empresa and reqvenda_itens.grupo_prod = old.grupo_prod and
    reqvenda_itens.cod_prod = old.cod_prod and reqvenda_itens.codigo_nop = old.codigo_nop and reqvenda_itens.cod_grade=old.cod_grade;
  end
  if ((old.tipo = 'OS') or (old.tipo = 'OS '))  then
  begin
    delete from  os_item_prod where os_item_prod.n_os = old.nped and
    os_item_prod.cod_empresa = old.cod_empresa and os_item_prod.grupo_prod = old.grupo_prod and
    os_item_prod.cod_prod = old.cod_prod and os_item_prod.codigo_nop = old.codigo_nop;
  end
  if (old.tipo = 'ORC') then
  begin
    delete from itemprod_orc where itemprod_orc.n_orc = old.nped and
    itemprod_orc.cod_empresa = old.cod_empresa and itemprod_orc.grupo_prod = old.grupo_prod and
    itemprod_orc.cod_prod = old.cod_prod;
  end
end ^

