CREATE TRIGGER TI_PEDVENDA_PROD_UNQ_CONV FOR PEDVENDA_PROD 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
  DECLARE VARIABLE VUNIDADE VARCHAR(6);
begin
  /* Trigger text */
  if ((trim(coalesce(new.unidade, '')) = '') or (trim(coalesce(new.unidade_conv, '')) = '')) then
  begin
    select unidade from produtos
    where grupo_prod = new.grupo_prod
    and cod_prod = new.cod_prod
    and cod_empresa = new.cod_empresa
      into :vunidade;

    if (trim(coalesce(new.unidade, '')) = '') then
      if (trim(coalesce(vunidade, '')) <> '') then
        new.unidade = upper(trim(vunidade));

    if (trim(coalesce(new.unidade_conv, '')) = '') then
      if (trim(coalesce(vunidade, '')) <> '') then
        new.unidade_conv = upper(trim(vunidade));
  end
end ^

CREATE TRIGGER TI_PEDVENDA_PROD_DEV FOR PEDVENDA_PROD 
ACTIVE AFTER INSERT OR UPDATE POSITION 0 
AS
  DECLARE VARIABLE  vstatus_ped varchar(10);
  DECLARE VARIABLE  vexiste_dev char(1);
  DECLARE VARIABLE  vgrupoprod Integer;
  DECLARE VARIABLE  vcodprod char(6);
  DECLARE VARIABLE  vcodgrade Integer;
  DECLARE VARIABLE  vquant_ped double precision default 00000.00;
  DECLARE VARIABLE  vquant_dev double precision default 00000.00;
begin
  if (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
   exit;

  vstatus_ped = '';
  vexiste_dev = 'N';
  vgrupoprod = 0;
  vcodprod = 0;
  vquant_ped = 0;
  vquant_dev = 0;

  /* Trigger text */
  if (inserting) then
  begin
    select status_ped from pedvenda
    where nped = new.nped
    and tipo = new.tipo
    and cod_empresa = new.cod_empresa into :vstatus_ped;

    if (coalesce(vstatus_ped, '') = 'CANCELADO') then
      exit;

    select case when (count(*) > 0) then 'S' else 'N' end from devolucao
    where cod_venda = new.nped
    and tipo_venda = new.tipo
    and cod_empresa = new.cod_empresa
      into :vexiste_dev;

    for select grupo_prod, cod_prod, cod_grade, sum(coalesce(quant_ped_item, 0)) quant from pedvenda_prod
        where nped = new.nped
        and tipo = new.tipo
        and cod_empresa = new.cod_empresa
        and (status <> 'CANCELADO' or status is null)
        group by 1, 2, 3
          into :vgrupoprod, :vcodprod, :vcodgrade, :vquant_ped do
    begin
      select sum(coalesce(quant, 0)) quant from devolucao
      where cod_venda = new.nped
      and tipo_venda = new.tipo
      and grupo_prod = :vgrupoprod
      and cod_prod = :vcodprod
      and cod_grade = :vcodgrade
      and cod_empresa = new.cod_empresa
        into :vquant_dev;

      if ((coalesce(vexiste_dev, 'N') = 'S') and (coalesce(vquant_dev, 0) <= 0)) then
      begin
        update pedvenda set dev = 'P' where nped = new.nped and tipo = new.tipo and cod_empresa = new.cod_empresa and (coalesce(dev, '') <> 'P');
        exit;
      end
      else if ((coalesce(vexiste_dev, 'N') = 'S') and (coalesce(vquant_ped, 0) > coalesce(vquant_dev, 0))) then
      begin
        update pedvenda set dev = 'P' where nped = new.nped and tipo = new.tipo and cod_empresa = new.cod_empresa and (coalesce(dev, '') <> 'P');
        exit;
      end
    end

    if (coalesce(vexiste_dev, 'N') = 'N') then
      update pedvenda set dev = null where nped = new.nped and tipo = new.tipo and cod_empresa = new.cod_empresa and (coalesce(dev, '') <> '');
    else
      update pedvenda set dev = 'T' where nped = new.nped and tipo = new.tipo and cod_empresa = new.cod_empresa and (coalesce(dev, '') <> 'T');
  end
  else if (updating) then
  begin
    select status_ped from pedvenda
    where nped = new.nped
    and tipo = new.tipo
    and cod_empresa = new.cod_empresa into :vstatus_ped;

    if (coalesce(vstatus_ped, '') = 'CANCELADO') then
      exit;

    select case when (count(*) > 0) then 'S' else 'N' end from devolucao
    where cod_venda = new.nped
    and tipo_venda = new.tipo
    and cod_empresa = new.cod_empresa
      into :vexiste_dev;

    for select grupo_prod, cod_prod, cod_grade, sum(coalesce(quant_ped_item, 0)) quant from pedvenda_prod
        where nped = new.nped
        and tipo = new.tipo
        and cod_empresa = new.cod_empresa
        and (status <> 'CANCELADO' or status is null)
        group by 1, 2, 3
          into :vgrupoprod, :vcodprod, :vcodgrade, :vquant_ped do
    begin
      select sum(coalesce(quant, 0)) quant from devolucao
      where cod_venda = new.nped
      and tipo_venda = new.tipo
      and grupo_prod = :vgrupoprod
      and cod_prod = :vcodprod
      and cod_grade = :vcodgrade
      and cod_empresa = new.cod_empresa
        into :vquant_dev;

      if ((coalesce(vexiste_dev, 'N') = 'S') and (coalesce(vquant_dev, 0) <= 0)) then
      begin
        update pedvenda set dev = 'P' where nped = new.nped and tipo = new.tipo and cod_empresa = new.cod_empresa and (coalesce(dev, '') <> 'P');
        exit;
      end
      else if ((coalesce(vexiste_dev, 'N') = 'S') and (coalesce(vquant_ped, 0) > coalesce(vquant_dev, 0))) then
      begin
        update pedvenda set dev = 'P' where nped = new.nped and tipo = new.tipo and cod_empresa = new.cod_empresa and (coalesce(dev, '') <> 'P');
        exit;
      end
    end

    if (coalesce(vexiste_dev, 'N') = 'N') then
      update pedvenda set dev = null where nped = new.nped and tipo = new.tipo and cod_empresa = new.cod_empresa and (coalesce(dev, '') <> '');
    else
      update pedvenda set dev = 'T' where nped = new.nped and tipo = new.tipo and cod_empresa = new.cod_empresa and (coalesce(dev, '') <> 'T');
  end
end;
 
 ^

