CREATE TRIGGER PEDVENDA_PROD_ALMOX FOR PEDVENDA_PROD 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
AS
 declare variable almox char(2);
 declare variable nitem integer;
 declare variable current_d timestamp;
 declare variable current_t timestamp;
begin
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
   exit;

  if (inserting) then
  begin
    select trim(empresa.almox) from empresa
    where empresa.cod_empresa = new.cod_empresa
    into :almox;
  
    if (((new.tipo = 'REQ')or(new.tipo = 'OS')) and (coalesce(new.status,'')='') and (almox ='S2') and (new.cod_pedido > 0)) then
    begin
      delete from controle_almoxarifado
      where controle_almoxarifado.cod_pedido = new.cod_pedido and controle_almoxarifado.cod_empresa = new.cod_empresa and controle_almoxarifado.nitem = coalesce(new.nitem_pedido, 1);
    end
  end
  else if (deleting)then
  begin
    select trim(empresa.almox) from empresa
    where empresa.cod_empresa = old.cod_empresa
    into :almox;
  
    if(((old.tipo = 'REQ')or(old.tipo = 'OS')) and (almox ='S2') and(old.cod_pedido > 0))  then
    begin
      select current_d, current_t from sp_current_ts(old.cod_empresa) into :current_d, :current_t;

      insert into controle_almoxarifado (controle_almoxarifado.cod_pedido, controle_almoxarifado.nitem,
      controle_almoxarifado.cod_empresa,  controle_almoxarifado.tipv, controle_almoxarifado.cod_cond_pag,
      controle_almoxarifado.cod_vendedor, controle_almoxarifado.grupo_prod, controle_almoxarifado.cod_prod,
      controle_almoxarifado.num_fab_prod, controle_almoxarifado.quant, controle_almoxarifado.vlun,
      controle_almoxarifado.vltot, controle_almoxarifado.cod_grade,
      controle_almoxarifado.codigo_nop, controle_almoxarifado.sit_atd, controle_almoxarifado.descr_prod,
      controle_almoxarifado.data_pedido, controle_almoxarifado.hora_pedido, controle_almoxarifado.cod_cliente)
    
      select pedvenda_prod.cod_pedido, 1 nitem, pedvenda_prod.cod_empresa, pedvenda.tipv, coalesce(pedvenda.cod_cond_pag, 1),
      pedvenda_prod.cod_vendedor, pedvenda_prod.grupo_prod, pedvenda_prod.cod_prod, pedvenda_prod.num_fab_prod,
      pedvenda_prod.quant_ped_item, pedvenda_prod.vlun_ped_item, pedvenda_prod.vltot_ped_item,
      pedvenda_prod.cod_grade, pedvenda_prod.codigo_nop, 'DV' sit_atd, pedvenda_prod.descr_prod_ped,
      :current_d, :current_t, pedvenda.cod_cliente from pedvenda inner join pedvenda_prod on pedvenda_prod.nped = pedvenda.nped
      and pedvenda_prod.tipo = pedvenda.tipo and pedvenda_prod.cod_empresa = pedvenda.cod_empresa
      where pedvenda_prod.nped = old.nped and pedvenda_prod.nitem = old.nitem
      and pedvenda_prod.cod_empresa = old.cod_empresa and pedvenda_prod.tipo = old.tipo;
    end
  end
  if(updating) then
  begin

    select trim(empresa.almox) from empresa
    where empresa.cod_empresa = new.cod_empresa
    into :almox;
  
    if ((coalesce(old.status,'')<>new.status) and (new.status = 'CANCELADO') and (((new.tipo = 'REQ'))or(new.tipo = 'OS')) and (almox ='S2') and(new.cod_pedido > 0))then
    begin
       select current_d, current_t from sp_current_ts(old.cod_empresa) into :current_d, :current_t;

       insert into controle_almoxarifado (controle_almoxarifado.cod_pedido, controle_almoxarifado.nitem,
       controle_almoxarifado.cod_empresa, controle_almoxarifado.tipv, controle_almoxarifado.cod_cond_pag,
       controle_almoxarifado.cod_vendedor, controle_almoxarifado.grupo_prod, controle_almoxarifado.cod_prod,
       controle_almoxarifado.num_fab_prod, controle_almoxarifado.quant, controle_almoxarifado.vlun,
       controle_almoxarifado.vltot, controle_almoxarifado.cod_grade, controle_almoxarifado.codigo_nop,
       controle_almoxarifado.sit_atd, controle_almoxarifado.descr_prod,
       controle_almoxarifado.data_pedido, controle_almoxarifado.hora_pedido, controle_almoxarifado.cod_cliente)
    
       select pedvenda_prod.cod_pedido, 1 nitem, pedvenda_prod.cod_empresa, pedvenda.tipv, coalesce(pedvenda.cod_cond_pag, 1),
       pedvenda_prod.cod_vendedor, pedvenda_prod.grupo_prod, pedvenda_prod.cod_prod, pedvenda_prod.num_fab_prod,
       pedvenda_prod.quant_ped_item, pedvenda_prod.vlun_ped_item, pedvenda_prod.vltot_ped_item,
       pedvenda_prod.cod_grade, pedvenda_prod.codigo_nop, 'DV' sit_atd, pedvenda_prod.descr_prod_ped,
       :current_d, :current_t, pedvenda.cod_cliente from pedvenda inner join pedvenda_prod on pedvenda_prod.nped = pedvenda.nped
       and pedvenda_prod.tipo = pedvenda.tipo and pedvenda_prod.cod_empresa = pedvenda.cod_empresa
       where pedvenda_prod.nped = new.nped and pedvenda_prod.nitem = new.nitem
       and pedvenda_prod.cod_empresa = new.cod_empresa and pedvenda_prod.tipo = new.tipo;
    end
  
    if ((coalesce(old.status,'')='') and (old.quant_ped_item > new.quant_ped_item) and ((new.tipo = 'REQ')or(new.tipo = 'OS')) and (almox ='S2') and(new.cod_pedido > 0))then
    begin
      select current_d, current_t from sp_current_ts(old.cod_empresa) into :current_d, :current_t;

      select (count(*) + 1) as nitem from controle_almoxarifado
      where controle_almoxarifado.cod_pedido = new.cod_pedido
      into :nitem;
      
      insert into controle_almoxarifado (controle_almoxarifado.cod_pedido, controle_almoxarifado.nitem,
      controle_almoxarifado.cod_empresa, controle_almoxarifado.tipv, controle_almoxarifado.cod_cond_pag,
      controle_almoxarifado.cod_vendedor, controle_almoxarifado.data_pedido, controle_almoxarifado.hora_pedido,
      controle_almoxarifado.grupo_prod, controle_almoxarifado.cod_prod, controle_almoxarifado.num_fab_prod,
      controle_almoxarifado.quant, controle_almoxarifado.vlun, controle_almoxarifado.vltot, controle_almoxarifado.cod_grade,
      controle_almoxarifado.codigo_nop, controle_almoxarifado.sit_atd, controle_almoxarifado.descr_prod,
      controle_almoxarifado.cod_vendedor1,  controle_almoxarifado.data_atd, controle_almoxarifado.hora_atd, controle_almoxarifado.cod_cliente)
      
      select pedvenda_prod.cod_pedido, :nitem as nitem, pedvenda_prod.cod_empresa, pedvenda.tipv, coalesce(pedvenda.cod_cond_pag, 1),
      pedvenda_prod.cod_vendedor, pedvenda_prod.data_atd, pedvenda_prod.hora_atd,
      pedvenda_prod.grupo_prod, pedvenda_prod.cod_prod, pedvenda_prod.num_fab_prod,
      old.quant_ped_item - new.quant_ped_item, pedvenda_prod.vlun_ped_item, (old.quant_ped_item - new.quant_ped_item) * pedvenda_prod.vlun_ped_item,
      pedvenda_prod.cod_grade, pedvenda_prod.codigo_nop, 'DV' sit_atd, pedvenda_prod.descr_prod_ped,
      pedvenda_prod.cod_almoxarifado, :current_d, :current_t, pedvenda.cod_cliente
      from pedvenda inner join pedvenda_prod on pedvenda_prod.nped = pedvenda.nped
      and pedvenda_prod.tipo = pedvenda.tipo and pedvenda_prod.cod_empresa = pedvenda.cod_empresa
      where pedvenda_prod.nped = new.nped and pedvenda_prod.nitem = new.nitem
      and pedvenda_prod.cod_empresa = new.cod_empresa and pedvenda_prod.tipo = new.tipo;
    end

  end
end
 
 ^

CREATE TRIGGER TI_PEDVENDA_PROD_CONF FOR PEDVENDA_PROD 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
AS
DECLARE VARIABLE  vnped Integer;
DECLARE VARIABLE  vtipo char(3);
DECLARE VARIABLE  vcod_empresa Integer;
DECLARE VARIABLE  vgrupo_prod Integer;
DECLARE VARIABLE  vcod_prod char(6);
DECLARE VARIABLE  vnitem Integer;
DECLARE VARIABLE  vcod_grade Integer;
DECLARE VARIABLE  vquantConf double precision default 00000.00;
DECLARE VARIABLE  vquantVnd double precision default 00000.00;
DECLARE VARIABLE  vquantConfTemp double precision default 00000.00;
DECLARE VARIABLE  vconfTp char(1);
DECLARE VARIABLE  vconfProd char(1);
DECLARE VARIABLE  vTipV char(1);
DECLARE VARIABLE  vtotvenda float;
DECLARE VARIABLE  vtotprod float;
DECLARE VARIABLE  vtotacresc float;
DECLARE VARIABLE  vtotdesc float;
DECLARE VARIABLE  valtEst char(1);
DECLARE VARIABLE  vCodigoConf Integer;
DECLARE VARIABLE  vStatusItem varchar(10);
DECLARE VARIABLE  vOK smallint;
DECLARE VARIABLE  vAbaterItens char(1);
DECLARE VARIABLE  vNAbaterItens char(1);
DECLARE VARIABLE VGRUPOPRODPDC integer;
begin
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
   exit;

  select coalesce(emp.abater_itens, '') from empresa emp
  where emp.cod_empresa = new.cod_empresa and emp.ativo = 1
  into :vAbaterItens;

  if (trim(vAbaterItens) <> 'S') then
   exit;

  select coalesce(tp.usar_conferencia_produto, '') usar_conferencia_produto ,
  coalesce(tp.n_usar_conferencia_produto, '') n_usar_conferencia_produto , coalesce(pd.tipv, '') tipv from pedvenda pd
  left join tipo_vendas tp on tp.sigla = pd.tipv and tp.tipo = new.tipo
  where pd.nped = new.nped
  and pd.tipo = new.tipo
  and pd.cod_empresa = new.cod_empresa
  and pd.cod_vendedor = new.cod_vendedor
  and tp.ativo = 1
    into :vconfTp, :vNAbaterItens, :vTipV;

  if (trim(vNAbaterItens) = 'S') then
   exit;

  vOK = 0;
  vquantVnd = trunc(new.quant_ped_item, 4);

  if ((inserting) and (upper(coalesce(trim(new.status), '')) = 'CANCELADO') and (upper(coalesce(vconfTp, '')) <> 'S')) then
   exit;

  if ((updating) and (upper(coalesce(trim(old.status), '')) = 'CANCELADO') and (upper(coalesce(trim(new.status), '')) = 'CANCELADO') and (upper(coalesce(vconfTp, '')) <> 'S')) then
   exit;

  if ((updating) and (coalesce(old.nitem, 0) <> coalesce(new.nitem, 0)) and (upper(coalesce(vconfTp, '')) <> 'S')
    and (upper(coalesce(trim(old.status), '')) <> 'CANCELADO')
    and (upper(coalesce(trim(new.status), '')) <> 'CANCELADO')) then
  begin
    select first 1 pdc.grupo_prod from pedvenda pv
    left join pedvenda_prod pp on pp.nped = pv.nped and pp.tipo = pv.tipo and pv.cod_empresa = pp.cod_empresa
    left join pedvenda_prod_conf pdc on pdc.nped_conf = pp.nped and pdc.tipo_conf = pp.tipo and pdc.nitem_conf = pp.nitem and pdc.cod_empresa = pp.cod_empresa
    where pdc.nped = old.nped
    and pdc.tipo = old.tipo
    and pdc.nitem = old.nitem
    and pdc.cod_empresa = old.cod_empresa
      into :vgrupoprodpdc;

    if (coalesce(vgrupoprodpdc, 0) > 0) then
    begin
      update pedvenda_prod_conf pdc set pdc.nitem = new.nitem
      where pdc.nped = new.nped
      and pdc.tipo = new.tipo
      and pdc.grupo_prod = new.grupo_prod
      and pdc.cod_prod = new.cod_prod
      and pdc.cod_grade = new.cod_grade
      and pdc.nitem = old.nitem
      and pdc.cod_empresa = new.cod_empresa;
    end
    else
    begin
      update pedvenda_prod_conf pdc set pdc.nitem = new.nitem
      where pdc.nped = new.nped
      and pdc.tipo = new.tipo
      and pdc.nitem = old.nitem
      and pdc.cod_empresa = new.cod_empresa;
    end
  end

  if (((updating) and (upper(coalesce(trim(new.status), '')) = '') and (old.cod_vendedor <> new.cod_vendedor) and (upper(coalesce(vconfTp, '')) <> 'S'))
    or ((updating) and (upper(coalesce(trim(new.status), '')) = '') and (old.quant_ped_item <> new.quant_ped_item) and (upper(coalesce(vconfTp, '')) <> 'S'))
    or ((updating) and (upper(coalesce(trim(new.status), '')) = 'CANCELADO') and (old.quant_ped_item = new.quant_ped_item) and (upper(coalesce(vconfTp, '')) <> 'S'))
    or ((deleting) and (upper(coalesce(vconfTp, '')) <> 'S'))) then
  begin
    vOK = 1;
    if ((old.tipo = 'REQ') and (upper(coalesce(vconfTp, '')) <> 'S'))  then
    begin
      for select pdc.nped_conf, pdc.tipo_conf, pdc.nitem_conf, sum(pdc.quant) quant,
          pdc.cod_empresa from pedvenda_prod_conf pdc
          inner join pedvenda pd on pd.nped = pdc.nped_conf and pd.tipo = pdc.tipo_conf and pd.cod_empresa = pdc.cod_empresa
          where coalesce(pd.status_ped, '') = ''
          and pdc.nped = old.nped
          and pdc.tipo = old.tipo
          and pdc.nitem = old.nitem
          and pdc.cod_empresa = old.cod_empresa
          and pdc.cod_vendedor = old.cod_vendedor
          group by pdc.nped, pdc.tipo, pdc.nitem, pdc.nped_conf, pdc.tipo_conf, pdc.nitem_conf, pdc.cod_empresa
            into  :vnped, :vtipo, :vnitem, :vquantConfTemp, :vcod_empresa do
      begin
        if (coalesce(vnped, 0) > 0) then
        begin
          select first 1 trunc(coalesce(pdi.quant_ped_item, 0), 4), pdi.status from pedvenda_prod pdi
          where pdi.nped = :vnped
          and pdi.tipo = :vtipo
          and pdi.cod_empresa = :vcod_empresa
          and pdi.nitem = :vnitem
          and pdi.grupo_prod = old.grupo_prod
          and pdi.cod_prod = old.cod_prod
          and pdi.cod_grade = old.cod_grade
          order by pdi.status
            into :vquantConf, :vstatusItem;
                                   
          if (upper(coalesce(trim(vStatusItem) , '')) = 'CANCELADO') then
            vquantConf = vquantConfTemp;
          else
            vquantConf = vquantConfTemp + vquantConf;

          update pedvenda_prod pdi set pdi.status = Null,
          pdi.nped_conf = Null, pdi.tipo_conf = Null, pdi.nitem_conf = Null,
          pdi.quant_ped_item = (:vquantConf),
          pdi.vltot_ped_item = (:vquantConf * old.vlun_ped_item),
          pdi.vltot_ped_nf = (:vquantConf * old.vlun_ped_nf)
          where pdi.nped = :vnped
          and pdi.tipo = :vtipo
          and pdi.cod_empresa = :vcod_empresa
          and pdi.nitem = :vnitem
          and pdi.grupo_prod = old.grupo_prod
          and pdi.cod_prod = old.cod_prod
          and pdi.cod_grade = old.cod_grade;

          delete from pedvenda_prod_conf pdc
          where pdc.nped = old.nped
          and pdc.tipo = old.tipo
          and pdc.nitem = old.nitem
          and pdc.cod_empresa = old.cod_empresa;

          select (sum(coalesce(pdi.quant_ped_item, 0) * coalesce(pdi.vlun_ped_item, 0)) + sum(coalesce(pdi.acresc_item, 0)) - sum(coalesce(pdi.desc_item, 0))) as totovenda,
          (sum(coalesce(pdi.quant_ped_item, 0) * coalesce(pdi.vlun_ped_item, 0))) as totprod,
          (sum(coalesce(pdi.rateio_acresc, 0))) as acrescimo, (sum(coalesce(pdi.rateio_desc, 0))) as desconto from pedvenda_prod pdi
          where pdi.nped = :vnped
          and pdi.tipo = :vtipo
          and pdi.cod_empresa = :vcod_empresa
          and (coalesce(pdi.status, '') = '')
            into :vtotvenda, :vtotprod, :vtotacresc, :vtotdesc;
        
          update pedvenda pd set pd.valor_total = :vtotvenda,
          pd.tot_prod = :vtotprod,
          pd.acrescimo = :vtotacresc,
          pd.desconto = :vtotdesc
          where pd.nped = :vnped
          and pd.tipo = :vtipo
          and pd.cod_empresa = :vcod_empresa;
        end
      end

      if ((deleting) and (coalesce(vnped, 0) > 0)) then
      begin
        select (sum(coalesce(pdi.quant_ped_item, 0) * coalesce(pdi.vlun_ped_item, 0)) + sum(coalesce(pdi.acresc_item, 0)) - sum(coalesce(pdi.desc_item, 0))) as totovenda,
        (sum(coalesce(pdi.quant_ped_item, 0) * coalesce(pdi.vlun_ped_item, 0))) as totprod,
        (sum(coalesce(pdi.rateio_acresc, 0))) as acrescimo, (sum(coalesce(pdi.rateio_desc, 0))) as desconto from pedvenda_prod pdi
        where pdi.nped = new.nped
        and pdi.tipo = new.tipo
        and pdi.cod_empresa = :vcod_empresa
        and (coalesce(pdi.status, '') = '')
          into :vtotvenda, :vtotprod, :vtotacresc, :vtotdesc;

        update pedvenda pd set pd.valor_total = :vtotvenda,
        pd.tot_prod = :vtotprod,
        pd.acrescimo = :vtotacresc,
        pd.desconto = :vtotdesc
        where pd.nped = old.nped
        and pd.tipo = old.tipo
        and pd.cod_empresa = :vcod_empresa;
      end
    end
  end

  if ((inserting) or ((updating) and (vOk = 1))) then
  begin
    if ((new.tipo = 'REQ') and (upper(coalesce(vconfTp, '')) <> 'S'))  then
    begin
      while (trunc(vquantVnd, 4) > 0) do
      begin
        if ((updating) and (upper(coalesce(trim(new.status), '')) = 'CANCELADO')) then
         break;

        select first 1 tp.usar_conferencia_produto, pdi.nped, pdi.tipo, pdi.cod_empresa, pdi.grupo_prod, pdi.cod_prod, pdi.nitem, pdi.cod_grade, pdi.quant_ped_item, coalesce(pdi.status,'') status   from pedvenda pd
        inner join pedvenda_prod pdi on pdi.nped = pd.nped and pdi.tipo = pd.tipo and pdi.cod_empresa = pd.cod_empresa
        left join tipo_vendas tp on tp.sigla = pd.tipv and tp.tipo = pd.tipo
        where coalesce(pd.status_ped, '') = ''
        and (coalesce(pdi.status, '') = '')
        and (coalesce(tp.usar_conferencia_produto, '') = 'S')
        and pdi.grupo_prod = new.grupo_prod
        and pdi.cod_prod = new.cod_prod
        and pd.tipo = new.tipo
        and pd.cod_empresa = new.cod_empresa
        and pdi.cod_grade = new.cod_grade
        and pd.cod_vendedor = new.cod_vendedor
        order by pd.nped, pd.tipo, pd.cod_empresa
          into :vconfProd, :vnped, :vtipo, :vcod_empresa, :vgrupo_prod, :vcod_prod, :vnitem, :vcod_grade, :vquantConf, :vstatusItem;

        select first 1 coalesce(pdi.status,'') status from pedvenda_prod pdi
        where pdi.nped = :vnped
        and pdi.tipo = :vtipo
        and pdi.cod_empresa = :vcod_empresa
        and pdi.grupo_prod = :vgrupo_prod
        and pdi.cod_prod = :vcod_prod
        and pdi.nitem = :vnitem
        and pdi.cod_grade = :vcod_grade
        order by pdi.status
          into :vstatusItem;

        if (trim(vStatusItem) = 'CANCELADO') then
          break;

        if (upper(vconfProd) = 'S') then
        begin
          if ((coalesce(vnped, 0) > 0) and (vtipo = new.tipo) and (vcod_empresa = new.cod_empresa)
            and (vgrupo_prod = new.grupo_prod) and (vcod_prod = new.cod_prod) and (vcod_grade = new.cod_grade)) then
          begin
            if (trunc(vquantVnd, 4) >= trunc(vquantConf, 4)) then
            begin
              vquantConfTemp = trunc(vquantConf, 4);

              update pedvenda_prod pdi set pdi.status = 'CANCELADO',
              pdi.codigo_nop = gen_id(gen_itens_canc, 1),
              pdi.nped_conf = new.nped, pdi.tipo_conf = new.tipo, pdi.nitem_conf = new.nitem
              where pdi.nped = :vnped
              and pdi.tipo = :vtipo
              and pdi.cod_empresa = :vcod_empresa
              and pdi.grupo_prod = :vgrupo_prod
              and pdi.cod_prod = :vcod_prod
              and pdi.nitem = :vnitem
              and pdi.cod_grade = :vcod_grade;

              insert into pedvenda_prod_conf (codigo, nped, tipo, nitem, cod_empresa, quant, nped_conf, nitem_conf, tipo_conf, cod_vendedor, tipv, grupo_prod, cod_prod, cod_grade)
              values ((select cod from incrementa_codigo(new.cod_empresa, 'PRODUTOS_PROD_CONF')), new.nped, new.tipo, new.nitem, new.cod_empresa, :vquantConfTemp, :vnped, :vnitem, :vtipo, new.cod_vendedor, :vTipV, new.grupo_prod, new.cod_prod, new.cod_grade);

              vquantVnd = trunc(vquantVnd, 4) -  trunc(vquantConf, 4);
            end
            else
            begin
              vquantConfTemp = trunc(vquantVnd, 4);

              update pedvenda_prod pdi set pdi.quant_ped_item = (:vquantConf - :vquantVnd),
              pdi.vltot_ped_item = ((:vquantConf - :vquantVnd) * new.vlun_ped_item),
              pdi.vltot_ped_nf = ((:vquantConf - :vquantVnd) * new.vlun_ped_nf),
              pdi.nped_conf = new.nped, pdi.tipo_conf = new.tipo, pdi.nitem_conf = new.nitem
              where pdi.nped = :vnped
              and pdi.tipo = :vtipo
              and pdi.cod_empresa = :vcod_empresa
              and pdi.grupo_prod = :vgrupo_prod
              and pdi.cod_prod = :vcod_prod
              and pdi.nitem = :vnitem
              and pdi.cod_grade = :vcod_grade;

              insert into pedvenda_prod_conf (codigo, nped, tipo, nitem, cod_empresa, quant, nped_conf, nitem_conf, tipo_conf, cod_vendedor, tipv, grupo_prod, cod_prod, cod_grade)
              values ((select cod from incrementa_codigo(new.cod_empresa, 'PRODUTOS_PROD_CONF')), new.nped, new.tipo, new.nitem, new.cod_empresa, :vquantConfTemp, :vnped, :vnitem, :vtipo, new.cod_vendedor, :vTipV, new.grupo_prod, new.cod_prod, new.cod_grade);

              vquantVnd = 0;
            end

            select (sum(coalesce(pdi.quant_ped_item, 0) * coalesce(pdi.vlun_ped_item, 0)) + sum(coalesce(pdi.acresc_item, 0)) - sum(coalesce(pdi.desc_item, 0))) as totovenda,
            (sum(coalesce(pdi.quant_ped_item, 0) * coalesce(pdi.vlun_ped_item, 0))) as totprod,
            (sum(coalesce(pdi.rateio_acresc, 0))) as acrescimo, (sum(coalesce(pdi.rateio_desc, 0))) as desconto from pedvenda_prod pdi
            where pdi.nped = :vnped
            and pdi.tipo = :vtipo
            and pdi.cod_empresa = :vcod_empresa
            and (coalesce(pdi.status, '') = '')
              into :vtotvenda, :vtotprod, :vtotacresc, :vtotdesc;
        
            update pedvenda pd set pd.valor_total = :vtotvenda,
            pd.tot_prod = :vtotprod,
            pd.acrescimo = :vtotacresc,
            pd.desconto = :vtotdesc
            where pd.nped = :vnped
            and pd.tipo = :vtipo
            and pd.cod_empresa = :vcod_empresa;
          end
        end
        else
          break;
      end
    end
  end
end;
 
 ^

CREATE TRIGGER TI_EVD_PAF_PVPROD FOR PEDVENDA_PROD 
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 0 
AS                                      
  declare variable vcodempresa integer; 
  declare variable vtiporegistro varchar(3);
  declare variable vdata timestamp;
  declare variable vcamposchave varchar(100);
  declare variable vvalorechave varchar(100);
  declare variable vmd5 varchar(256);
  declare variable vacao varchar(1);
  declare variable vtemregistro integer;     
  declare variable vconsultaexclusao varchar(100);
begin
  vtiporegistro = 'PP';
  vcamposchave = '|NPED|TIPO|GRUPO_PROD|COD_PROD|NITEM|COD_GRADE|COD_EMPRESA|CODIGO_NOP|';
  if (((coalesce(new.nprevenda, 0) > 0) and (inserting)) or ((coalesce(old.nprevenda, 0) > 0 ) and ((deleting) or (updating) )))  then
  begin
    if (inserting) then
    begin              
      vcodempresa =  new.cod_empresa;
      vdata = new.data_inclusao;
      vvalorechave = '|'||new.nped||'|'||new.tipo||'|'||new.cod_prod||'|'||new.nitem||'|'||new.cod_grade||'|'||new.cod_empresa||'|'||trunc(new.codigo_nop)||'|';
      vmd5 = new.md5;
      vacao = 'I';
      execute procedure sp_evd_paf(vcodempresa, vtiporegistro, vdata, vcamposchave, vvalorechave, substring(vmd5 from 1 for 32), vacao);
    end
    else if ((deleting) or (updating)) then
    begin
      vcodempresa =  old.cod_empresa;
      vdata = old.data_inclusao;
      vvalorechave = '|'||old.nped||'|'||old.tipo||'|'||old.cod_prod||'|'||old.nitem||'|'||old.cod_grade||'|'||old.cod_empresa||'|'||Trunc(old.codigo_nop)||'|';
      vmd5 = old.md5;
      vacao = 'D';
      if ((updating) and (coalesce(new.md5, '') <> '') and (coalesce(old.md5, '') = '')) then
        execute procedure sp_evd_paf(vcodempresa, vtiporegistro, vdata, vcamposchave, vvalorechave, substring(vmd5 from 1 for 32), vacao);
      else if (deleting) then
      begin
        vconsultaexclusao = 'P|'||old.grupo_prod||'|'||rtrim(old.cod_prod)||'|';
        select first 1 ep.seqid from evidencias_paf ep
          where ep.cod_empresa = :vcodempresa and ep.registro = 'PPD' and --PPD e incluido pelo sistema, sendo assim quando excluir
          ep.campos_chave = cast(old.nprevenda as varchar(32)) and
          ep.valores_campos = :vconsultaexclusao into :vtemregistro;      --pelo banco de dados nao vai ter este registro la e vai gerar uma evidencia
        if (coalesce(:vtemregistro, 0) = 0) then
          execute procedure sp_evd_paf(vcodempresa, vtiporegistro, vdata, vcamposchave, vvalorechave, substring(vmd5 from 1 for 32), vacao);
        else
          delete from evidencias_paf ep where ep.seqid = :vtemregistro and ep.cod_empresa = :vcodempresa;
      end
    end
  end
END
 
 ^

