CREATE TRIGGER TI_PEDVENDA_SERV_AI_CONTA_CLIEN FOR PEDVENDA_SERV 
ACTIVE AFTER INSERT POSITION 0 
AS
begin
  if ((new.tipo = rtrim('OS')) and (new.nitem = 1))  then
    update pedvenda p set p.status_conta_cliente = 'Conta de Cliente Aberta'
      where p.nped = new.nped and p.tipo = new.tipo and p.cod_empresa = new.cod_empresa and
      coalesce(p.status_conta_cliente, '' ) = '' and coalesce(p.status_ped, '' ) <> 'FECHADA' ;
end ^

CREATE TRIGGER TI_DEL_PEDVENDA_SERV FOR PEDVENDA_SERV 
ACTIVE AFTER DELETE POSITION 0 
AS
begin
  if ((old.tipo = 'OS') or (old.tipo = 'OS '))  then
  begin
    delete from  os_item_serv where os_item_serv.n_os = old.nped and
    os_item_serv.cod_empresa = old.cod_empresa and os_item_serv.cod_servico = old.cod_servico and
    os_item_serv.codigo_nop = old.codigo_nop;
