  end
end ^

CREATE TRIGGER TI_PEDVENDA_SERV_TMO_SERV_OS FOR PEDVENDA_SERV 
ACTIVE AFTER DELETE POSITION 0 
AS
DECLARE VARIABLE  vregistros Integer;
begin
 IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
   exit;

 if (coalesce(trim(old.tipo), '') = 'OS') then
 begin
   select count(*) from pedvenda_serv pd
   where pd.nped = old.nped and pd.tipo = trim(old.tipo) and pd.cod_empresa = old.cod_empresa
   and pd.cod_servico = old.cod_servico and pd.cod_vendedor = old.cod_vendedor
   into vregistros;

   if (coalesce(vregistros, 0) <= 0) then
   begin
       delete from tmo_serv_os tm
       where tm.n_os = old.nped and tm.cod_vendedor = old.cod_vendedor
       and tm.cod_servico = old.cod_servico and tm.cod_empresa = old.cod_empresa;
   end
 end
end ^

