CREATE TRIGGER PQDEL_MOBILE FOR PRECO_PRODUTOS_QTDE 
ACTIVE AFTER DELETE POSITION 0 
as
  declare variable CURRENT_TS timestamp;
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  select CURRENT_TS
  from SP_CURRENT_TS(old.COD_EMPRESA)
    into :CURRENT_TS;

  insert into DEL_MOBILE (SEQID, COD_EMPRESA, DATA_HORA_DEL, ID_DEL, TABELA)
  values ((select COD
           from INCREMENTA_CODIGO(old.COD_EMPRESA, 'DEL_MOBILE')), old.COD_EMPRESA, :CURRENT_TS, old.SEQID,
          'PRECO_PRODUTOS_QTDE');
