    inner join producao_item_indice on
    producao_item_indice.cod_producao = producao.cod_producao and producao_item_indice.cod_empresa = producao.cod_empresa
    where producao_item_indice.cod_producao = new.cod_producao and producao_item_indice.cod_empresa = new.cod_empresa;
end ^

CREATE TRIGGER PRODUCAO_DATA_ESTOQUE FOR PRODUCAO 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
as
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (updating) then
  begin
    if ((trim(coalesce(old.STATUS, '')) <> trim(coalesce(new.STATUS, ''))) and
        (trim(coalesce(new.STATUS, '')) = 'FECHADO')) then
      select CURRENT_D
      from SP_CURRENT_TS(new.COD_EMPRESA)
        into new.DATA_ESTOQUE;
  end
  else
  if (inserting) then
  begin
    if (trim(coalesce(new.STATUS, '')) = 'FECHADO') then
      select CURRENT_D
      from SP_CURRENT_TS(new.COD_EMPRESA)
        into new.DATA_ESTOQUE;
  end
end
 
