CREATE TRIGGER TI_PRODUTOS_ALT_PRECO FOR PRODUTOS 
ACTIVE BEFORE UPDATE POSITION 0 
as
begin
  if (old.PREC_TAB_PROD <> new.PREC_TAB_PROD) then
    select CURRENT_D
    from SP_CURRENT_TS(new.COD_EMPRESA)
      into new.DATA_ALT_PRECO;

  if ((coalesce(old.ICM_PROD, 0) <> coalesce(new.ICM_PROD, 0)) or (coalesce(old.ISENTO_PROD, '') <> coalesce(new.ISENTO_PROD, '')) or (coalesce(old.N_INCIDENCIA_PROD, '') <> coalesce(new.N_INCIDENCIA_PROD, ''))) then
  begin
    if ((coalesce(new.ICM_PROD, 0) > 0) and
        (coalesce(old.SIT_TRIB, '') <> 'T')) then
      new.SIT_TRIB = 'T';
    else
    if ((coalesce(new.ISENTO_PROD, '') = 'S') and
        (coalesce(old.SIT_TRIB, '') <> 'I')) then
      new.SIT_TRIB = 'I';
    else
    if ((coalesce(new.N_INCIDENCIA_PROD, '') = 'S') and
        (coalesce(old.SIT_TRIB, '') <> 'N')) then
      new.SIT_TRIB = 'N';
    else
    if (coalesce(old.SIT_TRIB, '') <> 'F') then
      new.SIT_TRIB = 'F';
  end
end ^

