CREATE TRIGGER TI_PRODUTOS_CP2 FOR PRODUTOS 
ACTIVE AFTER UPDATE POSITION 0 
AS
begin
  if ((old.grupo_prod <> new.grupo_prod) or (old.cod_prod <> new.cod_prod)) then
  begin
    update cupom2 set grupo_prod = new.grupo_prod, cod_prod = new.cod_prod
        where grupo_prod = old.grupo_prod and cod_prod = old.cod_prod and cod_empresa = old.cod_empresa;
    update  custos set grupo_prod = new.grupo_prod, cod_prod = new.cod_prod
        where grupo_prod = old.grupo_prod and cod_prod = old.cod_prod and cod_empresa = old.cod_empresa;
    update  inv_tipo74 set grupo_prod = new.grupo_prod, cod_prod = new.cod_prod
        where grupo_prod = old.grupo_prod and cod_prod = old.cod_prod and cod_empresa = old.cod_empresa;
    update ecf set grupo_prod = new.grupo_prod, cod_prod = new.cod_prod
        where grupo_prod = old.grupo_prod and cod_prod = old.cod_prod and cod_empresa = old.cod_empresa;
    update estoque_ini set grupo_prod = new.grupo_prod, cod_prod = new.cod_prod
        where grupo_prod = old.grupo_prod and cod_prod = old.cod_prod and cod_empresa = old.cod_empresa;
    update estoque_ini_grade set grupo_prod = new.grupo_prod, cod_prod = new.cod_prod
        where grupo_prod = old.grupo_prod and cod_prod = old.cod_prod and cod_empresa = old.cod_empresa;
    update nf_serie_d_itens set grupo_prod = new.grupo_prod, cod_prod = new.cod_prod
        where grupo_prod = old.grupo_prod and cod_prod = old.cod_prod and cod_empresa = old.cod_empresa;
    update hist_estoque_diario set grupo_prod = new.grupo_prod, cod_prod = new.cod_prod
        where grupo_prod = old.grupo_prod and cod_prod = old.cod_prod and cod_empresa = old.cod_empresa;
  end
end ^

CREATE TRIGGER TI_PRODUTOS_EC_INDTEC FOR PRODUTOS 
ACTIVE AFTER UPDATE POSITION 0 
AS
  DECLARE VARIABLE ECOMMERCE INTEGER;
  DECLARE VARIABLE ESTMANUAL_ECOMMERCE INTEGER;
  DECLARE VARIABLE VSINC_ECOMMERCE VARCHAR(1);
  DECLARE VARIABLE IDCOMMERCE INTEGER;
  DECLARE VARIABLE VTIPO_ITEM CHAR(2);
  DECLARE VARIABLE VGRUPO_PROD_TMP INTEGER;
  DECLARE VARIABLE VCOD_PROD_TMP CHAR(6);
  DECLARE VARIABLE VCOD_EMPRESA_TMP INTEGER;   
begin
  /* Trigger text */
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit;

  SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
  WHERE CONFIG_SISTEMA.CHAVE = 'e-commerce_hab'
  AND CONFIG_SISTEMA.COD_EMPRESA = NEW.COD_EMPRESA INTO: ECOMMERCE;

  SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
  WHERE CONFIG_SISTEMA.CHAVE = 'e-commerce_controle_est_manual'
  AND CONFIG_SISTEMA.COD_EMPRESA = NEW.COD_EMPRESA INTO: ESTMANUAL_ECOMMERCE;

  SELECT PRODUTOS_EC.SINC_ECOMMERCE, PRODUTOS_EC.ID_COMMERCE FROM PRODUTOS_EC
  WHERE PRODUTOS_EC.GRUPO_PROD = NEW.GRUPO_PROD AND PRODUTOS_EC.COD_PROD = NEW.COD_PROD
  AND PRODUTOS_EC.COD_EMPRESA = NEW.COD_EMPRESA INTO :VSINC_ECOMMERCE, :IDCOMMERCE;

  if ((COALESCE(IDCOMMERCE, 0) <= 0) and (COALESCE(ECOMMERCE, 0) <= 0)) then
    exit;

  if (COALESCE(ESTMANUAL_ECOMMERCE, 0) > 0) then
    exit;

  if (updating) then
  begin
    if (coalesce(old.est_f, 0) <> coalesce(new.est_f, 0)) then
    begin
      /* Atualizar produto acabado */
      for select distinct
        ind.grupo_prod_acabado,
        ind.cod_prod_acabado,
        ind.cod_empresa,
        coalesce(pr.tipo_item, '00') tipo_item from indice_tecnico ind
        inner join produtos pr on pr.grupo_prod = ind.grupo_prod_acabado and pr.cod_prod = ind.cod_prod_acabado and ind.cod_empresa = pr.cod_empresa
        where ind.grupo_prod_mprima = new.grupo_prod
        and ind.cod_prod_mprima = new.cod_prod
        and ind.cod_empresa = new.cod_empresa
         into :vgrupo_prod_tmp, :vcod_prod_tmp, :vcod_empresa_tmp, :vtipo_item do
      begin
        if (coalesce(vtipo_item, '00') = '04') then
        begin               
          vcod_prod_tmp = trim(vcod_prod_tmp);
          update produtos_ec set
            produtos_ec.grupo_prod = :vgrupo_prod_tmp,
            produtos_ec.cod_prod = :vcod_prod_tmp,
            produtos_ec.cod_empresa = :vcod_empresa_tmp
          where produtos_ec.grupo_prod = :vgrupo_prod_tmp
          and produtos_ec.cod_prod = :vcod_prod_tmp
          and produtos_ec.cod_empresa = :vcod_empresa_tmp;

          update produtos_ec_grade set
            produtos_ec_grade.grupo_prod = :vgrupo_prod_tmp,
            produtos_ec_grade.cod_prod = :vcod_prod_tmp,
            produtos_ec_grade.cod_empresa = :vcod_empresa_tmp
          where produtos_ec_grade.grupo_prod = :vgrupo_prod_tmp
          and produtos_ec_grade.cod_prod = :vcod_prod_tmp
          and produtos_ec_grade.cod_empresa = :vcod_empresa_tmp;
        end
      end
    end
  end
end;
 
 ^

CREATE TRIGGER TI_PRODUTOS_PRECO_QTDE_ALT FOR PRODUTOS 
ACTIVE AFTER UPDATE POSITION 0 
AS
  DECLARE VARIABLE VRECALCULAR_PRECOS INTEGER;
  DECLARE VARIABLE VCASAS_DECIMAIS INTEGER;
begin
  /* Trigger text */
  if (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit;

  if (COALESCE(old.PREC_TAB_PROD, 0) = COALESCE(new.PREC_TAB_PROD, 0)) then
    exit;

  SELECT COALESCE(VALUE1_F, 0) FROM CONFIG_SISTEMA
  WHERE CHAVE = 'prod_cad_recalcular_preco_por_quantidade'
  AND COD_EMPRESA = new.COD_EMPRESA
    into :VRECALCULAR_PRECOS;

  if (COALESCE(VRECALCULAR_PRECOS, 0) <= 0) then
    exit;

  SELECT CASAS_DECIMAIS FROM EMPRESA
  WHERE COD_EMPRESA = new.COD_EMPRESA
    into :VCASAS_DECIMAIS;

  VCASAS_DECIMAIS = COALESCE(VCASAS_DECIMAIS, 0);
  if (COALESCE(VCASAS_DECIMAIS, 0) <= 0) then
    VCASAS_DECIMAIS = 2;

  UPDATE PRECO_PRODUTOS_QTDE set PRECO_VENDA = ROUND((PROPORCAO_TABELA * new.PREC_TAB_PROD), :VCASAS_DECIMAIS)
  WHERE GRUPO_PROD = new.GRUPO_PROD
  AND COD_PROD = new.COD_PROD
  AND COD_EMPRESA = new.COD_EMPRESA
  AND PROPORCAO_TABELA > 0;
end ^

CREATE TRIGGER TI_PRODUTOS_PROMOCAO_ALT FOR PRODUTOS 
ACTIVE AFTER UPDATE POSITION 0 
AS
  DECLARE VARIABLE VRECALCULAR_PRECOS INTEGER;
  DECLARE VARIABLE VCASAS_DECIMAIS INTEGER;
  DECLARE VARIABLE VCOD_TAB INTEGER;
  DECLARE VARIABLE VCOD_TPPRECO INTEGER;
begin
  /* Trigger text */
  if (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit;

  if (COALESCE(old.PREC_TAB_PROD, 0) = COALESCE(new.PREC_TAB_PROD, 0)) then
    exit;

  SELECT CASAS_DECIMAIS FROM EMPRESA
  WHERE COD_EMPRESA = new.COD_EMPRESA
    into :VCASAS_DECIMAIS;

  VCASAS_DECIMAIS = COALESCE(VCASAS_DECIMAIS, 0);
  if (COALESCE(VCASAS_DECIMAIS, 0) <= 0) then
    VCASAS_DECIMAIS = 2;

  -- Atualizar tabela avulsas
  for SELECT DISTINCT COD_PROMOCAO, COD_TPPRECO FROM PROMOCAO_PRODUTO
  WHERE GRUPO_PROD = new.GRUPO_PROD
  AND COD_PROD = new.COD_PROD
  AND COD_EMPRESA = new.COD_EMPRESA
  AND COD_TPPRECO = 5
    into :VCOD_TAB, :VCOD_TPPRECO do
  begin
    if (COALESCE(VCOD_TAB, 0) > 0) then
    begin
      SELECT CASE WHEN (COALESCE(RECALC_PRECO, 'N') = 'S') then
                    1
                  else
                    0
             END FROM PROMOCAO
      WHERE COD_PROMOCAO = :VCOD_TAB
      AND COD_TPPRECO = :VCOD_TPPRECO
      AND COD_EMPRESA = new.COD_EMPRESA
        into :VRECALCULAR_PRECOS;

      if (COALESCE(VRECALCULAR_PRECOS, 0) > 0) then
      begin
        UPDATE PROMOCAO_PRODUTO set VALOR_PROMOCAO = ROUND((PROPORCAO_TABELA * new.PREC_TAB_PROD), :VCASAS_DECIMAIS)
        WHERE GRUPO_PROD = new.GRUPO_PROD
        AND COD_PROD = new.COD_PROD
        AND COD_EMPRESA = new.COD_EMPRESA
        AND COD_PROMOCAO = :VCOD_TAB
        AND COD_TPPRECO = :VCOD_TPPRECO
        AND PROPORCAO_TABELA > 0;
      end
    end
  end

  -- Atualizar tabela localidade, setor, cidade
  for SELECT COD_TPPRECO FROM TIPO_PRECO
  WHERE COD_TPPRECO in (2, 3, 4)
  AND COD_EMPRESA = new.COD_EMPRESA
    into :VCOD_TPPRECO do
  begin
    if (COALESCE(VCOD_TAB, 0) > 0) then
    begin
      SELECT CASE WHEN (COALESCE(RECALC_PRECO, 'N') = 'S') then
                    1
                  else
                    0
             END FROM TIPO_PRECO
      WHERE COD_TPPRECO = :VCOD_TPPRECO
      AND COD_EMPRESA = new.COD_EMPRESA
        into :VRECALCULAR_PRECOS;

      if (COALESCE(VRECALCULAR_PRECOS, 0) > 0) then
      begin
        UPDATE PROMOCAO_PRODUTO set VALOR_PROMOCAO = ROUND((PROPORCAO_TABELA * new.PREC_TAB_PROD), :VCASAS_DECIMAIS)
        WHERE GRUPO_PROD = new.GRUPO_PROD
        AND COD_PROD = new.COD_PROD
        AND COD_EMPRESA = new.COD_EMPRESA
        AND COD_TPPRECO = :VCOD_TPPRECO
        AND PROPORCAO_TABELA > 0;
      end
    end
  end
end ^

CREATE TRIGGER TI_PROD_AU_SPED_0205 FOR PRODUTOS 
ACTIVE AFTER UPDATE POSITION 0 
AS
  declare variable vseqid integer;
  declare variable vvalorant varchar(32);
  declare variable vdescrant varchar(75);
  declare variable vvalornew varchar(32);
  declare variable vdescrnew varchar(75);
  declare variable vdataini timestamp;
  declare variable vtipo_alt char(1); -- tipo_alt para gravar   
  declare variable current_d timestamp;
begin
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
   exit;  

  if (old.ativo = 3) then
    exit;

  select current_d from sp_current_ts(new.cod_empresa) into :current_d;
   
  vtipo_alt = '';
  if (((old.grupo_prod <> new.grupo_prod) or (old.cod_prod <> new.cod_prod)) and (old.descr_prod <> new.descr_prod)) then
    vtipo_alt = 'A'; -- ambos
  else if ((old.grupo_prod <> new.grupo_prod) or (old.cod_prod <> new.cod_prod)) then
    vtipo_alt = 'C'; -- codigo
  else if (old.descr_prod <> new.descr_prod) then
    vtipo_alt = 'D'; -- descricao

  if (vtipo_alt <> '') then
  begin
    select seqid, valor_anterior, descr_prod_anterior from produtos_alteracoes where grupo_prod = old.grupo_prod and cod_prod = old.cod_prod and cod_empresa = old.cod_empresa and data_alteracao = :current_d
      into :vseqid, :vvalorant, :vdescrant;
    if (coalesce(vseqid, 0) = 0) then -- sem alteracao no dia
    begin
      select first 1 data_alteracao from produtos_alteracoes where grupo_prod = old.grupo_prod and cod_prod = old.cod_prod and cod_empresa = old.cod_empresa and data_alteracao < :current_d order by data_alteracao desc
        into :vdataini;
      if ((:vdataini  is null) and (not old.dat_cad_prod is null)) then -- data de cadastro do prduto
        vdataini = old.dat_cad_prod;
      else if (:vdataini is null) then -- caso nao tenha data registrada sera registrado com data posterior 365 dias
        vdataini = :current_d - 365;
      else
        vdataini = :vdataini + 1; -- caso encontre a data, esta sera usada como data inicial da alteracao
      if (:vdataini > :current_d) then
        vdataini = :current_d;
      select cod from incrementa_codigo(new.cod_empresa, 'PRODUTOS_ALTERACOES') into :vseqid;
      insert into produtos_alteracoes (seqid, grupo_prod, cod_prod, cod_empresa, tipo_alt, valor_anterior, data_alteracao, data_ini, descr_prod_anterior)
        values ( :vseqid, new.grupo_prod, new.cod_prod, new.cod_empresa, :vtipo_alt, old.grupo_prod||'|'||rtrim(old.cod_prod)||'|', :current_d, :vdataini, rtrim(old.descr_prod));
    end
    else
    begin
      vvalornew = new.grupo_prod||'|'||rtrim(new.cod_prod)||'|';
      vdescrnew = rtrim(new.descr_prod);
      if ((vvalorant = vvalornew) and (vdescrant = vdescrnew)) then
        delete from produtos_alteracoes where seqid = :vseqid and cod_empresa = old.cod_empresa;
      else
      begin
        if ((vvalorant <> vvalornew) and (vdescrant <> vdescrnew)) then
          vtipo_alt = 'A';
        else if (vvalorant <> vvalornew) then
          vtipo_alt = 'C';
        else
          vtipo_alt = 'D';
        update produtos_alteracoes set tipo_alt = :vtipo_alt where seqid = :vseqid and cod_empresa = old.cod_empresa;
      end
    end
  end
end
 
 ^

CREATE TRIGGER PRODUTOS_BU_CALC_DIF_MKT FOR PRODUTOS 
ACTIVE AFTER UPDATE POSITION 9 
as
  declare variable DIG integer;
begin

  if (coalesce(new.PREC_CUSM_PROD, 0) > 0) then
    if (round(coalesce(old.PREC_CUSM_PROD, 0), 2) <> round(coalesce(new.PREC_CUSM_PROD, 0), 2)) then
    begin
      select CASAS_DECIMAIS
      from EMPRESA
      where COD_EMPRESA = new.COD_EMPRESA
        into :DIG;

      DIG = iif(coalesce(DIG, 0) <= 0, 2, DIG);
      DIG = iif(DIG > 10, 3, DIG);

      update PROMOCAO_PRODUTO PP
      set PP.VALOR_PROMOCAO = round(new.PREC_CUSM_PROD * (1 + (PP.MARKUP / 100)), :DIG),
          PP.PORCENTAGEM = 0
      where PP.GRUPO_PROD = new.GRUPO_PROD and
            PP.COD_PROD = new.COD_PROD and
            PP.COD_EMPRESA = new.COD_EMPRESA and
            coalesce(PP.MARKUP, 0) > 0;
    end
end ^

