CREATE TRIGGER TI_PRODUTOS_DESCR_PROD FOR PRODUTOS 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
begin
  /* Trigger text */
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit;

  new.descr_prod = replace(new.descr_prod, ASCII_CHAR(13), ' ');
  new.descr_prod = replace(new.descr_prod, ASCII_CHAR(10), ' ');
end ^

CREATE TRIGGER TR_PRODUTOS_CA FOR PRODUTOS 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
  DECLARE VARIABLE COMERCIO_ABERTO INTEGER;
  DECLARE VARIABLE ENV_COMERCIO_ABERTO CHAR(1);
  DECLARE VARIABLE ID_COMERCIO_ABERTO INTEGER;
  DECLARE VARIABLE VSQL VARCHAR(100);
begin
  /* Trigger text */
   IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit;

  VSQL = '';

  SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
  WHERE CONFIG_SISTEMA.CHAVE = 'comercio_aberto_hab'
  AND CONFIG_SISTEMA.COD_EMPRESA = NEW.COD_EMPRESA INTO: COMERCIO_ABERTO;

  SELECT COALESCE(PRODUTOS_EC.ENV_COMERCIO_ABERTO, 'N') ENV_COMERCIO_ABERTO,
  COALESCE(PRODUTOS_EC.ID_COMERCIO_ABERTO, 0) ID_COMERCIO_ABERTO FROM PRODUTOS_EC
  WHERE PRODUTOS_EC.GRUPO_PROD = NEW.GRUPO_PROD
  AND PRODUTOS_EC.COD_PROD = NEW.COD_PROD
  AND PRODUTOS_EC.COD_EMPRESA = NEW.COD_EMPRESA
    INTO :ENV_COMERCIO_ABERTO, :ID_COMERCIO_ABERTO;

  if ((COALESCE(ID_COMERCIO_ABERTO, 0) <= 0) and (COALESCE(COMERCIO_ABERTO, 0) <= 0)) then
    exit;

  if (trim(old.LISTA_IMAGENS) <> trim(new.LISTA_IMAGENS)) then
  begin
    if (coalesce(new.ALTEROU_IMAGEM, 'N') <> 'S') then
        new.ALTEROU_IMAGEM = 'S';
    if (coalesce(new.ALTEROU_IMAGEM_GRADE, 'N') <> 'S') then
        new.ALTEROU_IMAGEM_GRADE = 'S';
  end

  if (COALESCE(ID_COMERCIO_ABERTO, 0) > 0) THEN
    new.ID_COMERCIO_ABERTO = :ID_COMERCIO_ABERTO;
    
  if (updating) then
  begin
    if ((coalesce(old.ativo, 0) <> coalesce(new.ativo, 0)) and (new.ativo = 0)) then
      VSQL = ' produtos_ec.env_comercio_aberto = ''N'', ';
    else if ((coalesce(old.ativo, 0) <> coalesce(new.ativo, 0)) and (new.ativo = 99)) then
      VSQL = ' produtos_ec.env_comercio_aberto = ''N'', ';
  end

  execute statement
   'update produtos_ec set '||VSQL||'
      produtos_ec.grupo_prod = '||new.grupo_prod||',
      produtos_ec.cod_prod = '''||new.cod_prod||''',
      produtos_ec.cod_empresa = '||new.cod_empresa||'
    where produtos_ec.grupo_prod = '||new.grupo_prod||'
    and produtos_ec.cod_prod = '''||new.cod_prod||'''
    and produtos_ec.cod_empresa = '||new.cod_empresa||';';

  update produtos_ec_grade set
    produtos_ec_grade.grupo_prod = new.grupo_prod,
    produtos_ec_grade.cod_prod = new.cod_prod,
    produtos_ec_grade.cod_empresa = new.cod_empresa
  where produtos_ec_grade.grupo_prod = new.grupo_prod
  and produtos_ec_grade.cod_prod = new.cod_prod
  and produtos_ec_grade.cod_empresa = new.cod_empresa;
end;
 
 ^

CREATE TRIGGER TR_PRODUTOS_CASHBACK FOR PRODUTOS 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
  DECLARE VARIABLE COD_INTEG BIGINT;
  DECLARE VARIABLE SINC INTEGER;
  DECLARE VARIABLE ACAO CHAR(1);
begin
  /* Trigger text */
  select produtos_integ.cod_integ from produtos_integ
  where produtos_integ.grupo_prod = new.grupo_prod
  and produtos_integ.cod_prod = new.cod_prod
  and produtos_integ.cod_empresa = new.cod_empresa
    into :cod_integ;

  if (coalesce(cod_integ, 0) = 0) then
    exit;

  SINC = 0;

  if (inserting) then
  begin
    ACAO = 'I';

    SINC = 1;
  end
  else if (updating) then
  begin
    ACAO = 'A';

    if (old.grupo_prod <> new.grupo_prod) then
      SINC = 1;
    else if (old.cod_prod <> new.cod_prod) then
      SINC = 1;
    else if (old.perc_comissao_cashback <> new.perc_comissao_cashback) then
      SINC = 1;
    else if (old.dias_venc_cashback <> new.dias_venc_cashback) then
      SINC = 1;
    else if (old.ativo <> new.ativo) then
      SINC = 1;
  end

  if (SINC = 1) then
  begin
    INSERT INTO CENTRAL_CASHBACK (CODIGO, COD_EMPRESA, TABELA, ORIGEM, GRUPO_PROD, COD_PROD, DATA)
    VALUES ((SELECT COD FROM INCREMENTA_CODIGO(new.COD_EMPRESA, 'CENTRAL_CASHBACK')),
            new.COD_EMPRESA,
            'PRODUTOS',
            :ACAO,
            new.GRUPO_PROD,
            new.COD_PROD,
            CURRENT_TIMESTAMP
    );
  end
end;
 
 ^

CREATE TRIGGER TR_PRODUTOS_CA_SEQ FOR PRODUTOS 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
as
  declare variable IDCOMERCIO_ABERTO integer;
  declare variable COMERCIO_ABERTO integer;
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  SELECT CONFIG_SISTEMA.VALUE1_F from CONFIG_SISTEMA
  WHERE CONFIG_SISTEMA.CHAVE = 'comercio_aberto_hab'
  AND CONFIG_SISTEMA.COD_EMPRESA = NEW.COD_EMPRESA INTO :COMERCIO_ABERTO;
    
  SELECT PRODUTOS_EC.ID_COMERCIO_ABERTO from PRODUTOS_EC
  WHERE PRODUTOS_EC.GRUPO_PROD = NEW.GRUPO_PROD
  AND PRODUTOS_EC.COD_PROD = NEW.COD_PROD
  AND PRODUTOS_EC.COD_EMPRESA = NEW.COD_EMPRESA INTO :IDCOMERCIO_ABERTO;

  if ((COALESCE(IDCOMERCIO_ABERTO, 0) <= 0) and (COALESCE(COMERCIO_ABERTO, 0) <= 0)) then
    exit;

  if ((old.ATIVO = 1) and
      (new.ATIVO = 0)) then
    update PRODUTOS_EC
    set ENV_COMERCIO_ABERTO = 'N'
    where GRUPO_PROD = old.GRUPO_PROD and
          COD_PROD = old.COD_PROD and
          COD_EMPRESA = old.COD_EMPRESA and
          ENV_COMERCIO_ABERTO = 'S';

  if (coalesce(IDCOMERCIO_ABERTO, 0) > 0) then
    new.ID_COMERCIO_ABERTO = :IDCOMERCIO_ABERTO;
end ^

CREATE TRIGGER TR_PRODUTOS_EC FOR PRODUTOS 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS
  DECLARE VARIABLE ECOMMERCE INTEGER;  
  DECLARE VARIABLE SINC_ECOMMERCE VARCHAR(1);
  DECLARE VARIABLE IDCOMMERCE INTEGER;
  DECLARE VARIABLE VSQL VARCHAR(100);
begin
  /* Trigger text */
   IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit;

  VSQL = '';

  SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
  WHERE CONFIG_SISTEMA.CHAVE = 'e-commerce_hab'
  AND CONFIG_SISTEMA.COD_EMPRESA = NEW.COD_EMPRESA INTO: ECOMMERCE;

  SELECT COALESCE(PRODUTOS_EC.SINC_ECOMMERCE, 'N') SINC_ECOMMERCE,
  COALESCE(PRODUTOS_EC.ID_COMMERCE, 0) ID_COMMERCE FROM PRODUTOS_EC
  WHERE PRODUTOS_EC.GRUPO_PROD = NEW.GRUPO_PROD
  AND PRODUTOS_EC.COD_PROD = NEW.COD_PROD
  AND PRODUTOS_EC.COD_EMPRESA = NEW.COD_EMPRESA
    INTO :SINC_ECOMMERCE, :IDCOMMERCE;

  if ((COALESCE(IDCOMMERCE, 0) <= 0) and (COALESCE(ECOMMERCE, 0) <= 0)) then
    exit;

  if (trim(old.LISTA_IMAGENS) <> trim(new.LISTA_IMAGENS)) then
  begin
    if (coalesce(new.ALTEROU_IMAGEM, 'N') <> 'S') then
        new.ALTEROU_IMAGEM = 'S';
    if (coalesce(new.ALTEROU_IMAGEM_GRADE, 'N') <> 'S') then
        new.ALTEROU_IMAGEM_GRADE = 'S';
  end

  IF (COALESCE(IDCOMMERCE, 0) > 0) THEN
    new.ID_COMMERCE = :IDCOMMERCE;

  if (updating) then
  begin
    if ((coalesce(old.ativo, 0) <> coalesce(new.ativo, 0)) and (new.ativo = 0)) then
      VSQL = ' produtos_ec.disponivel = ''N'', ';
    else if ((coalesce(old.ativo, 0) <> coalesce(new.ativo, 0)) and (new.ativo = 99)) then
      VSQL = ' produtos_ec.sinc_ecommerce = ''N'', ';
  end

  execute statement
   'update produtos_ec set '||VSQL||'
      produtos_ec.grupo_prod = '||new.grupo_prod||',
      produtos_ec.cod_prod = '''||new.cod_prod||''',
      produtos_ec.cod_empresa = '||new.cod_empresa||'
    where produtos_ec.grupo_prod = '||new.grupo_prod||'
    and produtos_ec.cod_prod = '''||new.cod_prod||'''
    and produtos_ec.cod_empresa = '||new.cod_empresa||';';

  execute statement
   'update kits_prod_kits set
      kits_prod_kits.grupo_prod = '||new.grupo_prod||',
      kits_prod_kits.cod_prod = '''||new.cod_prod||''',
      kits_prod_kits.cod_empresa = '||new.cod_empresa||'
    where kits_prod_kits.grupo_prod = '||new.grupo_prod||'
    and kits_prod_kits.cod_prod = '''||new.cod_prod||'''
    and kits_prod_kits.cod_empresa = '||new.cod_empresa||';';

  update produtos_ec_grade set
    produtos_ec_grade.grupo_prod = new.grupo_prod,
    produtos_ec_grade.cod_prod = new.cod_prod,
    produtos_ec_grade.cod_empresa = new.cod_empresa
  where produtos_ec_grade.grupo_prod = new.grupo_prod
  and produtos_ec_grade.cod_prod = new.cod_prod
  and produtos_ec_grade.cod_empresa = new.cod_empresa;

  if (updating) then
    if (coalesce(SINC_ECOMMERCE, 'N') = 'N') then
    begin
      update produtos_ec_grade set
        produtos_ec_grade.sinc_ecommerce = 'N'
      where produtos_ec_grade.grupo_prod = new.grupo_prod
      and produtos_ec_grade.cod_prod = new.cod_prod
      and produtos_ec_grade.cod_empresa = new.cod_empresa
      and produtos_ec_grade.sinc_ecommerce = 'S';
    end
end;
 
 ^

