CREATE TRIGGER PRODUTOS_BIU_HIST_PRECO FOR PRODUTOS 
ACTIVE AFTER INSERT OR UPDATE POSITION 10 
as
  declare variable perc t_vl_todos;
  declare variable preco t_vl_todos;
  declare variable qtde t_vl_todos;
  declare variable tabela_id char(36);
begin

  EXECUTE PROCEDURE
  sp_handle_hist_preco(new.prec_tab_prod, old.prec_tab_prod, new.prec_cusm_prod, old.prec_cusm_prod, 0, 'VAREJO', new.cod_empresa, new.grupo_prod, new.cod_prod);
                   
  EXECUTE PROCEDURE
  sp_handle_hist_preco(new.prec_publico, old.prec_publico, new.prec_cusm_prod, old.prec_cusm_prod, 0, 'ATACADO', new.cod_empresa, new.grupo_prod, new.cod_prod);
                   
  EXECUTE PROCEDURE
  sp_handle_hist_preco(new.prec_30_prod, old.prec_30_prod, new.prec_cusm_prod, old.prec_cusm_prod, 0, '30_DIAS', new.cod_empresa, new.grupo_prod, new.cod_prod);
                   
  EXECUTE PROCEDURE
  sp_handle_hist_preco(new.prec_60_prod, old.prec_60_prod, new.prec_cusm_prod, old.prec_cusm_prod, 0, '60_DIAS', new.cod_empresa, new.grupo_prod, new.cod_prod);
                   
  EXECUTE PROCEDURE
  sp_handle_hist_preco(new.prec_90_prod, old.prec_90_prod, new.prec_cusm_prod, old.prec_cusm_prod, 0, '90_DIAS', new.cod_empresa, new.grupo_prod, new.cod_prod);
                   
  EXECUTE PROCEDURE
  sp_handle_hist_preco(new.preco_promocao, old.preco_promocao, new.prec_cusm_prod, old.prec_cusm_prod, 0, 'PROMOCAO', new.cod_empresa, new.grupo_prod, new.cod_prod);

  if (coalesce(new.prec_cusm_prod, 0) > 0) then
    if (round(coalesce(old.prec_cusm_prod, 0), 2) <> round(coalesce(new.prec_cusm_prod, 0), 2)) then
    begin

      update promocao_produto set guidt = (select guid from spdb_guid)
        where grupo_prod = new.grupo_prod and cod_prod = new.cod_prod and cod_empresa = new.cod_empresa and guidt is null;
      
      for select pp.porcentagem, pp.valor_promocao, pp.guidt from promocao_produto pp
            where grupo_prod = new.grupo_prod and cod_prod = new.cod_prod and cod_empresa = new.cod_empresa and guidt is not null
            into :perc, :preco, :tabela_id
      do
      begin
        preco = coalesce(preco, 0);
        perc = coalesce(perc, 0);
        if ((preco = 0) and (perc > 0) and (coalesce(new.prec_tab_prod, 0) > 0)) then
          preco = coalesce(new.prec_tab_prod, 0) * (1 - (perc / 100));

        if (preco > 0) then   
          EXECUTE PROCEDURE
          sp_handle_hist_preco(:preco, :preco, coalesce(new.prec_cusm_prod, 0), 0, 0, :tabela_id, new.cod_empresa, new.grupo_prod, new.cod_prod);

      end

      update preco_produtos_qtde set guidt = (select guid from spdb_guid)
        where grupo_prod = new.grupo_prod and cod_prod = new.cod_prod and cod_empresa = new.cod_empresa and guidt is null;

      for select pq.quant, pq.preco_venda, pq.guidt from preco_produtos_qtde pq
            where grupo_prod = new.grupo_prod and cod_prod = new.cod_prod and cod_empresa = new.cod_empresa and guidt is not null
            into :qtde, :preco, :tabela_id
      do
      begin
        preco = coalesce(preco, 0);
        qtde = coalesce(qtde, 0);

        if (preco > 0) then   
          EXECUTE PROCEDURE
          sp_handle_hist_preco(:preco, :preco, coalesce(new.prec_cusm_prod, 0), 0, :qtde, :tabela_id, new.cod_empresa, new.grupo_prod, new.cod_prod);
      end
    end
end ^

