CREATE TRIGGER TR_DTCA_PRODUTOS_EC FOR PRODUTOS_EC 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
as
  DECLARE VARIABLE COMERCIOABERTO INTEGER;
  DECLARE VARIABLE VSEQID BIGINT;
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if ((inserting)or(updating)) then 
  begin
    SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
    WHERE CONFIG_SISTEMA.CHAVE = 'comercio_aberto_hab'
    AND CONFIG_SISTEMA.COD_EMPRESA = NEW.COD_EMPRESA INTO: COMERCIOABERTO;
  end
  else if (deleting) then
  begin
    SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
    WHERE CONFIG_SISTEMA.CHAVE = 'comercio_aberto_hab'
    AND CONFIG_SISTEMA.COD_EMPRESA = OLD.COD_EMPRESA INTO: COMERCIOABERTO;
  end

  if ((inserting)or(updating)) then 
  begin
    if ((NEW.ID_COMERCIO_ABERTO <= 0) and (COALESCE(COMERCIOABERTO, 0) <= 0)) then
        exit;
  end
  else if (deleting) then
  begin
     if ((OLD.ID_COMERCIO_ABERTO <= 0) and (COALESCE(COMERCIOABERTO, 0) <= 0)) then
        exit;
  end

  if (inserting) then
  begin
    select count(COD_GRADE)
    from COD_GRADE_PROD
    where GRUPO_PROD = new.GRUPO_PROD and
          COD_PROD = new.COD_PROD and
          COD_EMPRESA = new.COD_EMPRESA and
          COD_GRADE > 0
      into :VSEQID;

    if (VSEQID = 0) then
      new.SEQID_CA = (select gen_id(SEQ_DEL_CA, 1)
                      from RDB$DATABASE);
    exit;
  end

  if ((old.ENV_COMERCIO_ABERTO = 'S') and
      (new.ENV_COMERCIO_ABERTO = 'N')) then
    update PRODUTOS_EC_GRADE
    set PRODUTOS_EC_GRADE.ENV_COMERCIO_ABERTO = 'N'
    where PRODUTOS_EC_GRADE.GRUPO_PROD = old.GRUPO_PROD and
          PRODUTOS_EC_GRADE.COD_PROD = old.COD_PROD and
          PRODUTOS_EC_GRADE.COD_EMPRESA = old.COD_EMPRESA and
          PRODUTOS_EC_GRADE.ENV_COMERCIO_ABERTO = 'S';

  if (coalesce(old.ID_COMERCIO_ABERTO, 0) <= 0) then
    exit;

  if (deleting) then
  begin
    select gen_id(SEQ_DEL_CA, 1)
    from RDB$DATABASE
      into :VSEQID;
    insert into DEL_CA (SEQID, COD_EMPRESA, TABELA, DATA_HORA_ALT, ID_COMERCIO_ABERTO)
    values (:VSEQID, old.COD_EMPRESA, 'PRODUTOS_EC', (select CURRENT_TS from SP_CURRENT_TS(old.COD_EMPRESA)), old.ID_COMERCIO_ABERTO);
  end
  else
  if ((inserting) or (updating)) then
  begin
    new.SEQID_CA = (select gen_id(SEQ_DEL_CA, 1)
                    from RDB$DATABASE);
  end
end
 
 ^

CREATE TRIGGER TR_DTEC_PRODUTOS_EC FOR PRODUTOS_EC 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
AS 
 DECLARE VARIABLE ECOMMERCE INTEGER;
 DECLARE VARIABLE ESTMANUAL_ECOMMERCE INTEGER;
 DECLARE VARIABLE VSEQID BIGINT; 
 DECLARE VARIABLE CAMPOS_CHAVE VARCHAR(255);
 DECLARE VARIABLE VALORES_CHAVE VARCHAR(255);
 DECLARE VARIABLE VDELETE INTEGER;
 DECLARE VARIABLE VESTOQUE DOUBLE PRECISION DEFAULT 00000.00;
 DECLARE VARIABLE VQUANT_MAT_PRIMA DOUBLE PRECISION DEFAULT 00000.00;
 DECLARE VARIABLE VQUANT_TEMP DOUBLE PRECISION DEFAULT 00000.00;
 DECLARE VARIABLE VTIPO_ITEM CHAR(2);
 DECLARE VARIABLE VMATERIA_PRIMA INTEGER;
begin 
  /* Trigger text */ 
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit; 

  VDELETE = 0; 
  if (updating) then 
    if (coalesce(old.sinc_ecommerce, 'N') <> (coalesce(new.sinc_ecommerce, 'N')) 
     and (coalesce(old.sinc_ecommerce, 'N') = 'S') and (coalesce(new.sinc_ecommerce, 'N') = 'N')) then 
      VDELETE = 1; 

  if (deleting) then 
    VDELETE = 1; 

  if ((inserting)or(updating)) then
  begin
    SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
    WHERE CONFIG_SISTEMA.CHAVE = 'e-commerce_hab'
    AND CONFIG_SISTEMA.COD_EMPRESA = NEW.COD_EMPRESA INTO: ECOMMERCE;

    SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
    WHERE CONFIG_SISTEMA.CHAVE = 'e-commerce_controle_est_manual'
    AND CONFIG_SISTEMA.COD_EMPRESA = NEW.COD_EMPRESA INTO: ESTMANUAL_ECOMMERCE;

    SELECT COALESCE(TIPO_ITEM, '00') FROM PRODUTOS
    WHERE GRUPO_PROD = NEW.GRUPO_PROD AND COD_PROD = NEW.COD_PROD AND COD_EMPRESA = NEW.COD_EMPRESA INTO: VTIPO_ITEM;
  end
  else if (deleting) then
  begin
    SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
    WHERE CONFIG_SISTEMA.CHAVE = 'e-commerce_hab'
    AND CONFIG_SISTEMA.COD_EMPRESA = OLD.COD_EMPRESA INTO: ECOMMERCE;
  end

  if (vdelete > 0) then 
  begin 
    if (COALESCE(OLD.ID_COMMERCE, 0) <= 0) then 
     exit; 

    SELECT GEN_ID(SEQ_DEL_EC, 1) FROM RDB$DATABASE INTO :VSEQID; 
    CAMPOS_CHAVE =  '|GRUPO_PROD|COD_PROD|COD_EMPRESA|'; 
    VALORES_CHAVE = '|'||OLD.GRUPO_PROD||'|'||OLD.COD_PROD||'|'||OLD.COD_EMPRESA||'|'; 
    INSERT INTO DEL_EC(SEQID, COD_EMPRESA, TABELA, DATA_HORA_ALT_WS, CAMPOS_CHAVE, VALORES_CHAVE, ID_COMMERCE)  
    VALUES(:VSEQID, old.COD_EMPRESA, 'PRODUTOS_EC', CURRENT_TIMESTAMP, :CAMPOS_CHAVE, :VALORES_CHAVE, OLD.ID_COMMERCE); 
    NEW.ID_COMMERCE = 0;
  end 
  else if ((inserting)or(updating)) then 
  begin 
    NEW.SEQID_EC = (SELECT GEN_ID(SEQ_EC_PRODUTOS_EC, 1) FROM RDB$DATABASE); 

    if ((updating) and (COALESCE(ESTMANUAL_ECOMMERCE, 0) <= 0)) then
    begin
      /* Alterar estoque produto acabado */
      if ((coalesce(vtipo_item, '00') = '04') and (coalesce(new.variacao, 'N') = 'N')) then
      begin
        vmateria_prima = 0;
        vquant_temp = coalesce(new.estoque_ec, 0);

        for select distinct
          coalesce(ind.quant, 0) quant,
          coalesce(est.estoque, 0) estoque from indice_tecnico ind
        inner join produtos_pdc_var prodac on
          prodac.grupo_prod = ind.grupo_prod_acabado
          and prodac.cod_prod = ind.cod_prod_acabado
          and prodac.cod_empresa = ind.cod_empresa
        inner join produtos_pdc_var_it prodit on
          prodit.id_ind = prodac.id_ind
          and prodit.grupo_prod = ind.grupo_prod_mprima
          and prodit.cod_prod = ind.cod_prod_mprima
          and prodit.cod_empresa = ind.cod_empresa
        left join getestoquedisponivel(
          ind.grupo_prod_mprima,
          ind.cod_prod_mprima,
          coalesce(prodit.cod_grade, 0),
          ind.cod_empresa,
          0,
          '',
          0,
          0) est on 1 = 1
        where ind.grupo_prod_acabado = new.grupo_prod
        and ind.cod_prod_acabado = new.cod_prod
        and ind.cod_empresa = new.cod_empresa
        union
        select distinct
          coalesce(ind.quant, 0) quant,
          coalesce(est.estoque, 0) estoque from indice_tecnico ind
        left join cod_grade_prod cprod on
          cprod.grupo_prod = ind.grupo_prod_mprima
          and cprod.cod_prod = ind.cod_prod_mprima
          and cprod.cod_empresa = ind.cod_empresa
        left join getestoquedisponivel(
          ind.grupo_prod_mprima,
          ind.cod_prod_mprima,
          coalesce(cprod.cod_grade, 0),
          ind.cod_empresa,
          0,
          '',
          0,
          0) est on 1 = 1
        where ind.grupo_prod_acabado = new.grupo_prod
        and ind.cod_prod_acabado = new.cod_prod
        and ind.cod_empresa = new.cod_empresa
        and (select count(*) from produtos_pdc_var prodac2
             inner join produtos_pdc_var_it prodit2 on
                prodit2.id_ind = prodac2.id_ind
                and prodit2.grupo_prod = ind.grupo_prod_mprima
                and prodit2.cod_prod = ind.cod_prod_mprima
                and prodit2.cod_empresa = prodac2.cod_empresa
             where prodac2.grupo_prod = ind.grupo_prod_acabado
                and prodac2.cod_prod = ind.cod_prod_acabado
                and prodac2.cod_grade = 0
                and prodac2.cod_empresa = ind.cod_empresa) = 0

          into :vquant_mat_prima, :vestoque do
        begin
          if (vmateria_prima = 0) then
            if (coalesce(vestoque, 0) > 0) then
              vquant_temp = (coalesce(vestoque, 0) / coalesce(vquant_mat_prima, 0));
            else
              vquant_temp = 0;

          if ((coalesce(vestoque, 0) / coalesce(vquant_mat_prima, 0)) < (coalesce(vquant_temp, 0))) then
            if (coalesce(vestoque, 0) > 0) then
              vquant_temp = (coalesce(vestoque, 0) / coalesce(vquant_mat_prima, 0));
            else
              vquant_temp = 0;

          vmateria_prima = 1;
        end
        new.estoque_ec = trunc(coalesce(vquant_temp, 0));
      end
    end
  end 
end;
 
 ^

CREATE TRIGGER TR_DTCA_PRODUTOS_EC_GRADE FOR PRODUTOS_EC_GRADE 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
as
  DECLARE VARIABLE COMERCIO_ABERTO INTEGER;
  DECLARE VARIABLE ID_COMERCIO_ABERTO INTEGER;
  DECLARE VARIABLE VSEQID BIGINT;
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if ((inserting)or(updating)) then 
  begin
    SELECT CONFIG_SISTEMA.VALUE1_F from CONFIG_SISTEMA
    WHERE CONFIG_SISTEMA.CHAVE = 'comercio_aberto_hab'
    AND CONFIG_SISTEMA.COD_EMPRESA = NEW.COD_EMPRESA INTO :COMERCIO_ABERTO;
    
    SELECT PRODUTOS_EC.ID_COMERCIO_ABERTO from PRODUTOS_EC
    WHERE PRODUTOS_EC.GRUPO_PROD = NEW.GRUPO_PROD
    AND PRODUTOS_EC.COD_PROD = NEW.COD_PROD
    AND PRODUTOS_EC.COD_EMPRESA = NEW.COD_EMPRESA INTO :ID_COMERCIO_ABERTO;
  end
  else if (deleting) then
  begin
    SELECT CONFIG_SISTEMA.VALUE1_F from CONFIG_SISTEMA
    WHERE CONFIG_SISTEMA.CHAVE = 'comercio_aberto_hab'
    AND CONFIG_SISTEMA.COD_EMPRESA = OLD.COD_EMPRESA INTO :COMERCIO_ABERTO;
    
    SELECT PRODUTOS_EC.ID_COMERCIO_ABERTO from PRODUTOS_EC
    WHERE PRODUTOS_EC.GRUPO_PROD = OLD.GRUPO_PROD
    AND PRODUTOS_EC.COD_PROD = OLD.COD_PROD
    AND PRODUTOS_EC.COD_EMPRESA = OLD.COD_EMPRESA INTO :ID_COMERCIO_ABERTO;
  end

  if ((inserting)or(updating)) then 
  begin
    if ((COALESCE(NEW.ID_COMERCIO_ABERTO, 0) <= 0) and (COALESCE(ID_COMERCIO_ABERTO, 0) <= 0) and (COALESCE(COMERCIO_ABERTO, 0) <= 0)) then
      exit;
  end
  else if (deleting) then
  begin
    if ((COALESCE(OLD.ID_COMERCIO_ABERTO, 0) <= 0) and (COALESCE(ID_COMERCIO_ABERTO, 0) <= 0) and (COALESCE(COMERCIO_ABERTO, 0) <= 0)) then
      exit;
  end

  if ((deleting) and
      (coalesce(old.ID_COMERCIO_ABERTO, 0) > 0)) then
  begin
    select gen_id(SEQ_DEL_CA, 1)
    from RDB$DATABASE
      into :VSEQID;
    insert into DEL_CA (SEQID, COD_EMPRESA, TABELA, DATA_HORA_ALT, ID_COMERCIO_ABERTO)
    values (:VSEQID, old.COD_EMPRESA, 'PRODUTOS_EC_GRADE', (select CURRENT_TS from SP_CURRENT_TS(old.COD_EMPRESA)), old.ID_COMERCIO_ABERTO);
  end
  else if ((inserting) or (updating)) then
  begin
    new.SEQID_CA = (select gen_id(SEQ_DEL_CA, 1) from RDB$DATABASE);
  end
end;
 
 ^

CREATE TRIGGER TR_DTEC_PRODUTOS_EC_GRADE FOR PRODUTOS_EC_GRADE 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
AS
 DECLARE VARIABLE ECOMMERCE INTEGER;
 DECLARE VARIABLE ESTMANUAL_ECOMMERCE INTEGER;
 DECLARE VARIABLE ID_COMMERCE INTEGER;
 DECLARE VARIABLE VSEQID BIGINT;
 DECLARE VARIABLE CAMPOS_CHAVE VARCHAR(255);
 DECLARE VARIABLE VALORES_CHAVE VARCHAR(255);
 DECLARE VARIABLE VDELETE INTEGER;
 DECLARE VARIABLE VESTOQUE DOUBLE PRECISION DEFAULT 00000.00;
 DECLARE VARIABLE VQUANT_MAT_PRIMA DOUBLE PRECISION DEFAULT 00000.00;
 DECLARE VARIABLE VQUANT_TEMP DOUBLE PRECISION DEFAULT 00000.00;
 DECLARE VARIABLE VVARIACAO CHAR(1);
 DECLARE VARIABLE VTIPO_ITEM CHAR(2);
 DECLARE VARIABLE VMATERIA_PRIMA INTEGER;
begin 
  /* Trigger text */ 
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit; 

  VDELETE = 0; 
  if (updating) then 
    if (coalesce(old.sinc_ecommerce, 'N') <> (coalesce(new.sinc_ecommerce, 'N')) 
     and (coalesce(old.sinc_ecommerce, 'N') = 'S') and (coalesce(new.sinc_ecommerce, 'N') = 'N')) then 
      VDELETE = 1; 

  if (deleting) then 
    VDELETE = 1; 

  if ((inserting)or(updating)) then 
  begin
    SELECT CONFIG_SISTEMA.VALUE1_F from CONFIG_SISTEMA
    WHERE CONFIG_SISTEMA.CHAVE = 'e-commerce_hab'
    AND CONFIG_SISTEMA.COD_EMPRESA = NEW.COD_EMPRESA INTO :ECOMMERCE;

    SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
    WHERE CONFIG_SISTEMA.CHAVE = 'e-commerce_controle_est_manual'
    AND CONFIG_SISTEMA.COD_EMPRESA = NEW.COD_EMPRESA INTO: ESTMANUAL_ECOMMERCE;
    
    SELECT PRODUTOS_EC.ID_COMMERCE, PRODUTOS_EC.VARIACAO from PRODUTOS_EC
    WHERE PRODUTOS_EC.GRUPO_PROD = NEW.GRUPO_PROD
    AND PRODUTOS_EC.COD_PROD = NEW.COD_PROD
    AND PRODUTOS_EC.COD_EMPRESA = NEW.COD_EMPRESA INTO :ID_COMMERCE, :VVARIACAO;

    SELECT COALESCE(TIPO_ITEM, '00') FROM PRODUTOS
    WHERE GRUPO_PROD = NEW.GRUPO_PROD AND COD_PROD = NEW.COD_PROD AND COD_EMPRESA = NEW.COD_EMPRESA INTO: VTIPO_ITEM;
  end
  else if (deleting) then
  begin
    SELECT CONFIG_SISTEMA.VALUE1_F from CONFIG_SISTEMA
    WHERE CONFIG_SISTEMA.CHAVE = 'e-commerce_hab'
    AND CONFIG_SISTEMA.COD_EMPRESA = OLD.COD_EMPRESA INTO :ECOMMERCE;
    
    SELECT PRODUTOS_EC.ID_COMMERCE from PRODUTOS_EC
    WHERE PRODUTOS_EC.GRUPO_PROD = OLD.GRUPO_PROD
    AND PRODUTOS_EC.COD_PROD = OLD.COD_PROD
    AND PRODUTOS_EC.COD_EMPRESA = OLD.COD_EMPRESA INTO :ID_COMMERCE;
  end

  if (vdelete > 0) then 
  begin 
    if (COALESCE(OLD.ID_COMMERCE, 0) <= 0) then 
     exit; 

    SELECT GEN_ID(SEQ_DEL_EC, 1) FROM RDB$DATABASE INTO :VSEQID; 
    CAMPOS_CHAVE =  '|GRUPO_PROD|COD_PROD|COD_GRADE|COD_EMPRESA|'; 
    VALORES_CHAVE = '|'||OLD.GRUPO_PROD||'|'||OLD.COD_PROD||'|'||OLD.COD_GRADE||'|'||OLD.COD_EMPRESA||'|'; 
    INSERT INTO DEL_EC(SEQID, COD_EMPRESA, TABELA, DATA_HORA_ALT_WS, CAMPOS_CHAVE, VALORES_CHAVE, ID_COMMERCE)  
    VALUES(:VSEQID, old.COD_EMPRESA, 'PRODUTOS_EC_GRADE', CURRENT_TIMESTAMP, :CAMPOS_CHAVE, :VALORES_CHAVE, OLD.ID_COMMERCE); 
    NEW.ID_COMMERCE = 0;
  end 
  else if ((inserting)or(updating)) then 
  begin 
    NEW.SEQID_EC = (SELECT GEN_ID(SEQ_EC_PRODUTOS_EC_GRADE, 1) FROM RDB$DATABASE); 

    if ((updating) and (COALESCE(ESTMANUAL_ECOMMERCE, 0) <= 0)) then
    begin
      /* Alterar estoque produto acabado */
      if ((coalesce(vtipo_item, '00') = '04') and (coalesce(vvariacao, 'N') = 'S')) then
      begin
        vmateria_prima = 0;
        vquant_temp = coalesce(new.estoque_ec, 0);

        for select distinct
          coalesce(ind.quant, 0) quant,
          coalesce(est.estoque, 0) estoque from indice_tecnico ind
        inner join produtos_pdc_var prodac on
          prodac.grupo_prod = ind.grupo_prod_acabado
          and prodac.cod_prod = ind.cod_prod_acabado
          and prodac.cod_grade = new.cod_grade
          and prodac.cod_empresa = ind.cod_empresa
        inner join produtos_pdc_var_it prodit on
          prodit.id_ind = prodac.id_ind
          and prodit.grupo_prod = ind.grupo_prod_mprima
          and prodit.cod_prod = ind.cod_prod_mprima
          and prodit.cod_empresa = ind.cod_empresa
        left join getestoquedisponivel(
          ind.grupo_prod_mprima,
          ind.cod_prod_mprima,
          coalesce(prodit.cod_grade, 0),
          ind.cod_empresa,
          0,
          '',
          0,
          0) est on 1 = 1
        where ind.grupo_prod_acabado = new.grupo_prod
        and ind.cod_prod_acabado = new.cod_prod
        and ind.cod_empresa = new.cod_empresa
        union
        select distinct
          coalesce(ind.quant, 0) quant,
          coalesce(est.estoque, 0) estoque from indice_tecnico ind
        left join cod_grade_prod acab on
          acab.grupo_prod = ind.grupo_prod_acabado
          and acab.cod_prod = ind.cod_prod_acabado
          and acab.cod_grade = new.cod_grade
          and acab.cod_empresa = ind.cod_empresa
        left join cod_grade_prod cprod on
          cprod.grupo_prod = ind.grupo_prod_mprima
          and cprod.cod_prod = ind.cod_prod_mprima
          and cprod.cod_empresa = ind.cod_empresa
        left join getestoquedisponivel(
          ind.grupo_prod_mprima,
          ind.cod_prod_mprima,
          coalesce(cprod.cod_grade, 0),
          ind.cod_empresa,
          0,
          '',
          0,
          0) est on 1 = 1
        where ind.grupo_prod_acabado = new.grupo_prod
        and ind.cod_prod_acabado = new.cod_prod
        and ind.cod_empresa = new.cod_empresa
        and (select count(*) from produtos_pdc_var prodac2
             where prodac2.grupo_prod = ind.grupo_prod_acabado
                and prodac2.cod_prod = ind.cod_prod_acabado
                and prodac2.cod_grade = coalesce(acab.cod_grade, 0)
                and prodac2.cod_empresa = ind.cod_empresa) = 0

          into :vquant_mat_prima, :vestoque do
        begin
          if (vmateria_prima = 0) then
            if (coalesce(vestoque, 0) > 0) then
              vquant_temp = (coalesce(vestoque, 0) / coalesce(vquant_mat_prima, 0));
            else
              vquant_temp = 0;

          if ((coalesce(vestoque, 0) / coalesce(vquant_mat_prima, 0)) < (coalesce(vquant_temp, 0))) then
            if (coalesce(vestoque, 0) > 0) then
              vquant_temp = (coalesce(vestoque, 0) / coalesce(vquant_mat_prima, 0));
            else
              vquant_temp = 0;

          vmateria_prima = 1;
        end
        new.estoque_ec = trunc(coalesce(vquant_temp, 0));

        if (vmateria_prima > 0) then
        begin
          update produtos_ec set produtos_ec.estoque_ec =
            coalesce((select sum(coalesce(produtos_ec_grade.estoque_ec, 0)) from produtos_ec_grade
                      where produtos_ec_grade.grupo_prod = new.grupo_prod
                      and produtos_ec_grade.cod_prod = new.cod_prod
                      and produtos_ec_grade.cod_empresa = new.cod_empresa), 0)
          where produtos_ec.grupo_prod = new.grupo_prod
          and produtos_ec.cod_prod = new.cod_prod
          and produtos_ec.cod_empresa = new.cod_empresa;
        end
      end
    end
  end 
end;
 
 ^

