CREATE TRIGGER TR_PROD_SIMILARES_ORDEM FOR PROD_SIMILARES_GRUPOS_ITENS 
ACTIVE AFTER DELETE POSITION 0 
AS
 declare variable vgrupo_prod integer;
 declare variable vcod_prod char(6);
 declare variable vdescr_grupo varchar(75);
begin
  /* Trigger text */
  if (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
   exit;

  if (coalesce(old.principal, 'N') <> 'S') then
    exit;

  select first 1 pr.descr_prod, ps.grupo_prod, ps.cod_prod from prod_similares_grupos_itens ps
  inner join produtos pr on pr.grupo_prod = ps.grupo_prod and pr.cod_prod = ps.cod_prod and pr.cod_empresa = ps.cod_empresa
  inner join prod_similares_grupos gr on gr.cod_grupo_sim = ps.cod_grupo_sim
    and gr.cod_empresa = ps.cod_empresa
  where ps.cod_grupo_sim = old.cod_grupo_sim
  and ps.cod_empresa = old.cod_empresa
  and ps.principal <> 'S'
  and not (ps.grupo_prod = old.grupo_prod and ps.cod_prod = old.cod_prod)
     into :vdescr_grupo, :vgrupo_prod, :vcod_prod;
  begin
     update prod_similares_grupos_itens ps set ps.principal = 'S'
     where ps.cod_grupo_sim = old.cod_grupo_sim
     and ps.cod_empresa = old.cod_empresa
     and ps.grupo_prod = :vgrupo_prod
     and ps.cod_prod = :vcod_prod;
  end
end;
 
 ^

