CREATE TRIGGER TI_PROM_PROD_BI_PROPORC_PREC FOR PROMOCAO_PRODUTO 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
as
  declare variable VPREC_TAB_PROD T_VL_TODOS;
  declare variable VPREC_CUSM_PROD T_VL_TODOS;
begin
  if ((COALESCE(new.PROPORCAO_TABELA, 0) > 0) and (coalesce(new.MARKUP, 0) > 0)) then
    new.PROPORCAO_TABELA = 0;

  else
  if ((coalesce(new.PROPORCAO_TABELA, 0) <= 0) and
      (coalesce(new.VALOR_PROMOCAO, 0) > 0) and
      (coalesce(new.COD_TPPRECO, 0) > 1)) then
  begin
    select PREC_CUSM_PROD, PREC_TAB_PROD
    from PRODUTOS
    where GRUPO_PROD = new.GRUPO_PROD and
          COD_PROD = new.COD_PROD and
          COD_EMPRESA = new.COD_EMPRESA
      into :VPREC_CUSM_PROD, :VPREC_TAB_PROD;

    if (coalesce(VPREC_TAB_PROD, 0) > 0.1) then
    begin
      if (coalesce(VPREC_CUSM_PROD, 0) >= coalesce(VPREC_TAB_PROD, 0)) then
        new.PROPORCAO_TABELA = 0;
      else
      begin
        if (coalesce(VPREC_TAB_PROD, 0) > 0) then
          new.PROPORCAO_TABELA = new.VALOR_PROMOCAO / VPREC_TAB_PROD;
        else
          new.PROPORCAO_TABELA = 0;
      end
    end
  end
end ^

CREATE TRIGGER TI_PROM_PROD_PPRECO FOR PROMOCAO_PRODUTO 
ACTIVE BEFORE INSERT OR UPDATE POSITION 1 
AS
  DECLARE VARIABLE VRECALCULAR_PRECOS INTEGER;
  DECLARE VARIABLE VCASAS_DECIMAIS INTEGER;
  DECLARE VARIABLE VPREC_TAB_PROD T_VL_TODOS;
  DECLARE VARIABLE VPREC_CUSM_PROD T_VL_TODOS;
begin
  if ((COALESCE(new.PROPORCAO_TABELA, 0) > 0) and (coalesce(new.MARKUP, 0) > 0)) then
    new.PROPORCAO_TABELA = 0;

  if ((COALESCE(new.PROPORCAO_TABELA, 0) > 0) AND (COALESCE(new.COD_TPPRECO, 0) > 1)) then
  begin
    if (COALESCE(new.COD_LOCALIDADE, 0) > 0) then
    begin
        SELECT CASE WHEN (COALESCE(RECALC_PRECO, 'N') = 'S') then
                      1
                    else
                      0
               END FROM TIPO_PRECO
        WHERE COD_TPPRECO = 2
        AND COD_EMPRESA = new.COD_EMPRESA
          into :VRECALCULAR_PRECOS;
    end
    else if (COALESCE(new.COD_SETOR, 0) > 0) then
    begin
        SELECT CASE WHEN (COALESCE(RECALC_PRECO, 'N') = 'S') then
                      1
                    else
                      0
               END FROM TIPO_PRECO
        WHERE COD_TPPRECO = 3
        AND COD_EMPRESA = new.COD_EMPRESA
          into :VRECALCULAR_PRECOS;
    end
    else if (COALESCE(new.COD_CIDADE, 0) > 0) then
    begin
        SELECT CASE WHEN (COALESCE(RECALC_PRECO, 'N') = 'S') then
                      1
                    else
                      0
               END FROM TIPO_PRECO
        WHERE COD_TPPRECO = 4
        AND COD_EMPRESA = new.COD_EMPRESA
          into :VRECALCULAR_PRECOS;
    end
    else
    begin
        SELECT CASE WHEN (COALESCE(RECALC_PRECO, 'N') = 'S') then
                      1
                    else
                      0
               END FROM PROMOCAO
        WHERE COD_PROMOCAO = new.COD_PROMOCAO
        AND COD_TPPRECO = new.COD_TPPRECO
        AND COD_EMPRESA = new.COD_EMPRESA
          into: VRECALCULAR_PRECOS;
    end

    if ((COALESCE(new.VALOR_PROMOCAO, 0) > 0) and (COALESCE(VRECALCULAR_PRECOS, 0) <= 0)) then
      exit;

    SELECT CASAS_DECIMAIS FROM EMPRESA
    WHERE COD_EMPRESA = new.COD_EMPRESA
      into :VCASAS_DECIMAIS;

    VCASAS_DECIMAIS = COALESCE(VCASAS_DECIMAIS, 0);
    if (COALESCE(VCASAS_DECIMAIS, 0) <= 0) then
      VCASAS_DECIMAIS = 2;

    SELECT PREC_CUSM_PROD, PREC_TAB_PROD FROM PRODUTOS
    WHERE GRUPO_PROD = new.GRUPO_PROD AND COD_PROD = new.COD_PROD AND COD_EMPRESA = new.COD_EMPRESA
      into :VPREC_CUSM_PROD, :VPREC_TAB_PROD;

    if (COALESCE(new.INF, '') = 'V') then
    begin
      if (coalesce(VPREC_CUSM_PROD, 0) >= coalesce(VPREC_TAB_PROD, 0)) then
        new.PROPORCAO_TABELA = 0;
      else
      begin
        if (coalesce(VPREC_TAB_PROD, 0) > 0) then
          new.PROPORCAO_TABELA = new.VALOR_PROMOCAO / VPREC_TAB_PROD;
        else
          new.PROPORCAO_TABELA = 0;
      end
    end
    else if (COALESCE(new.PROPORCAO_TABELA, 0) > 0) then
    begin
      if (COALESCE(new.VALOR_PROMOCAO, 0) <> ROUND((new.PROPORCAO_TABELA * VPREC_TAB_PROD), VCASAS_DECIMAIS)) then
        if (COALESCE(VPREC_TAB_PROD, 0) <= 0.1) then
          new.VALOR_PROMOCAO = 0;
        else
          new.VALOR_PROMOCAO = ROUND((new.PROPORCAO_TABELA * VPREC_TAB_PROD), :VCASAS_DECIMAIS);
    end
  end
end ^

CREATE TRIGGER PROMOCAO_PRODUTO_BU_CALC_MKT FOR PROMOCAO_PRODUTO 
ACTIVE BEFORE INSERT OR UPDATE POSITION 9 
as
  declare variable CUSTO T_VL_TODOS;
  declare variable PRECO T_VL_TODOS;
  declare variable DIG integer;
begin

  if (round(coalesce(new.MARKUP, 0), 2) > 0) then
  begin

    select P.PREC_CUSM_PROD, E.CASAS_DECIMAIS
    from PRODUTOS P
      inner join EMPRESA E on E.COD_EMPRESA = P.COD_EMPRESA
    where P.GRUPO_PROD = new.GRUPO_PROD and
          P.COD_PROD = new.COD_PROD and
          P.COD_EMPRESA = new.COD_EMPRESA
      into :CUSTO, :DIG;

    if (coalesce(CUSTO, 0) <= 0) then
      exit;

    DIG = iif(coalesce(DIG, 0) <= 0, 2, DIG);
    DIG = iif(DIG > 10, 3, DIG);
    PRECO = round(CUSTO * (1 + (new.MARKUP / 100)), :DIG);

    if (abs(new.VALOR_PROMOCAO - PRECO) > 0.01) then
      new.VALOR_PROMOCAO = PRECO;
  end
end ^

CREATE TRIGGER TR_PROMOCAO_PRODUTO_EC FOR PROMOCAO_PRODUTO 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
AS 
   DECLARE VARIABLE GRUPO_PROD INTEGER; 
   DECLARE VARIABLE COD_PROD CHAR(6); 
   DECLARE VARIABLE VCOD_EMPRESA INTEGER;
   DECLARE VARIABLE COD_PROMOCAO INTEGER;
   DECLARE VARIABLE ECOMMERCE INTEGER; 
   DECLARE VARIABLE VATUALIZAR INTEGER;
 BEGIN
   /* TRIGGER TEXT */ 
   IF(SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN 
    EXIT; 

   if (DELETING) then
   begin 
     if (COALESCE(OLD.COD_PROMOCAO, 0) <= 0) then 
         exit; 
     GRUPO_PROD = OLD.GRUPO_PROD; 
     COD_PROD = OLD.COD_PROD; 
     VCOD_EMPRESA = OLD.COD_EMPRESA;
     COD_PROMOCAO = OLD.COD_PROMOCAO;
   end 
   else 
   begin 
     if (COALESCE(NEW.COD_PROMOCAO, 0) <= 0) then 
         exit; 
     GRUPO_PROD = NEW.GRUPO_PROD; 
     COD_PROD = NEW.COD_PROD; 
     VCOD_EMPRESA = NEW.COD_EMPRESA;
     COD_PROMOCAO = NEW.COD_PROMOCAO;
   end 

  SELECT CONFIG_SISTEMA.VALUE1_F FROM CONFIG_SISTEMA
  WHERE CONFIG_SISTEMA.CHAVE = 'e-commerce_hab'
  AND CONFIG_SISTEMA.COD_EMPRESA = :VCOD_EMPRESA INTO: ECOMMERCE;

  IF(COALESCE(ECOMMERCE, 0) <= 0) THEN
    exit;

   SELECT CONFIG_API.COD_TAB_PRECO FROM CONFIG_API
      WHERE CONFIG_API.COD_EMPRESA = :VCOD_EMPRESA AND CONFIG_API.API = 'TRAYCOMMERCE' and CONFIG_API.COD_TAB_PRECO = :COD_PROMOCAO
      INTO: VATUALIZAR;

   if (COALESCE(VATUALIZAR, 0) <= 0) then
     SELECT PROMOCAO_ORDEM_EC.COD_PROMOCAO FROM PROMOCAO_ORDEM_EC
        WHERE PROMOCAO_ORDEM_EC.COD_PROMOCAO = :COD_PROMOCAO AND PROMOCAO_ORDEM_EC.COD_EMPRESA = :VCOD_EMPRESA
        INTO: VATUALIZAR;

   if (COALESCE(VATUALIZAR, 0) <> COALESCE(COD_PROMOCAO, 0)) then
     exit;

   update produtos_ec set produtos_ec.grupo_prod = :grupo_prod,
    produtos_ec.cod_prod = :cod_prod,
    produtos_ec.cod_empresa = :VCOD_EMPRESA
  where produtos_ec.grupo_prod = :grupo_prod
    and produtos_ec.cod_prod = :cod_prod
    and produtos_ec.cod_empresa = :VCOD_EMPRESA;
END;
 
 ^

CREATE TRIGGER PROMOCAO_PRODUTO_BIU_HIST_PREC FOR PROMOCAO_PRODUTO 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 10 
as
  declare variable perc t_vl_todos;
  declare variable preco t_vl_todos;
  declare variable custo t_vl_todos;
  declare variable preco_produto t_vl_todos;
begin

  if (deleting) then
  begin
    if (coalesce(old.guidt, '') <> '') then
    begin

      update PRODUTOS_HISTORICO_PRECO
      set DESCRICAO = (select tp.detalhe || ' - ' || tp.tipo
                       from vw_tabela_precos tp
                       where tp.grupo_prod = old.grupo_prod and tp.cod_prod = old.cod_prod and tp.cod_empresa = old.cod_empresa and
                             tp.cod_promocao = old.cod_promocao and
                             tp.cod_localidade = old.cod_localidade and tp.cod_setor = old.cod_setor and tp.cod_cidade = old.cod_cidade)
      where tabela_id = old.guidt and
            grupo_prod = old.grupo_prod and cod_prod = old.cod_prod and cod_empresa = old.cod_empresa;
    end

    exit;
  end

  if ((round(coalesce(old.valor_promocao, 0), 2) <> round(coalesce(new.valor_promocao, 0), 2))
   or (round(coalesce(old.porcentagem, 0), 2) <> round(coalesce(new.porcentagem, 0), 2)))  then
  begin
    preco = coalesce(new.valor_promocao, 0);
    perc = coalesce(new.porcentagem, 0);

    select prec_tab_prod, prec_cusm_prod from produtos where grupo_prod = new.grupo_prod and cod_prod = new.cod_prod and cod_empresa = new.cod_empresa
      into :preco_produto, :custo;

    if ((preco = 0) and (perc > 0) and (coalesce(preco_produto, 0) > 0)) then
      preco = coalesce(preco_produto, 0) * (1 - (perc / 100));
  
    if (coalesce(new.guidt, '') = '') then
      new.guidt = (select guid from spdb_guid);
  
    EXECUTE PROCEDURE
    sp_handle_hist_preco(preco, 0, :custo, 0, 0, new.guidt, new.cod_empresa, new.grupo_prod, new.cod_prod);
  end
end
 
 ^

