CREATE TRIGGER ATFORMPGRQ FOR REQVENDA 
ACTIVE BEFORE DELETE POSITION 0 
AS
declare variable stat_nf integer;
BEGIN
  stat_nf = 0;
  select count(FORMPAGAMENTO.NREQUISICAO) from FORMPAGAMENTO
            where FORMPAGAMENTO.NREQUISICAO = old.NREQ AND FORMPAGAMENTO.COD_EMPRESA = old.COD_EMPRESA AND
            FORMPAGAMENTO.TPDOCS = 'REQ' into :stat_nf;
 if (stat_nf > 0) then
 begin
  DELETE FROM FORMPAGAMENTO WHERE FORMPAGAMENTO.NREQUISICAO = old.nreq AND FORMPAGAMENTO.COD_EMPRESA = old.COD_EMPRESA AND
            FORMPAGAMENTO.TPDOCS = 'REQ';
 end
END ^

