CREATE TRIGGER ATINSERT_RQVENDA FOR REQVENDA_ITENS 
ACTIVE BEFORE INSERT POSITION 0 
AS
 declare variable cod_empresa integer;
 declare variable nec_ac integer;
 declare variable nec_acprod char(1);
 declare variable dias_acprod integer;
BEGIN
  select reqvenda.cod_cliente from REQVENDA 
            where reqvenda.nreq = new.nreq AND REQVENDA.COD_EMPRESA =
new.COD_EMPRESA
            into :nec_ac;
 if (nec_ac <> 0) then /* se cliente na req */
 begin
  nec_acprod='';
  dias_acprod=0;
  select nec_acomp,dias_acomp, cod_empresa from produtos where 
  produtos.grupo_prod = new.grupo_prod and
  produtos.cod_empresa = new.cod_empresa and
  produtos.cod_prod = new.cod_prod into :nec_acprod, :dias_acprod,
:cod_empresa;
  if (nec_acprod <> '') then 
  begin
   /* altera acompanhamento do cliente */
   update clientes set nec_acomp = :nec_acprod,dias_acomp = :dias_acprod
   where clientes.cod_cliente = :nec_ac and cod_empresa = :cod_empresa;
  end
 end
END ^

CREATE TRIGGER TI_REQVENDA_ITENS_UP FOR REQVENDA_ITENS 
ACTIVE AFTER UPDATE POSITION 0 
AS
begin
  if (( old.grupo_prod <> new.grupo_prod ) or ( old.cod_prod <> new.cod_prod ) or (old.codigo_nop <> new.codigo_nop) or (old.cod_grade <> new.cod_grade) ) then
    update pedvenda_prod set pedvenda_prod.grupo_prod = new.grupo_prod, pedvenda_prod.cod_prod = new.cod_prod,
    pedvenda_prod.codigo_nop = new.codigo_nop, pedvenda_prod.cod_grade = new.cod_grade
    where pedvenda_prod.grupo_prod = old.grupo_prod and pedvenda_prod.cod_prod = old.cod_prod and
    pedvenda_prod.codigo_nop = old.codigo_nop and pedvenda_prod.cod_grade = old.cod_grade and
    pedvenda_prod.cod_empresa = old.cod_empresa and pedvenda_prod.nped = old.nreq and
    pedvenda_prod.tipo = 'REQ';
end ^

CREATE TRIGGER ATITEM_RQVENDA FOR REQVENDA_ITENS 
INACTIVE BEFORE DELETE POSITION 0 
AS
 declare variable stat_aberta integer;
BEGIN
  select count(reqvenda.NREQ) from REQVENDA 
            where reqvenda.nreq = old.nreq and reqvenda.COD_EMPRESA =
old.COD_EMPRESA AND
            ((reqvenda.status_rq is null) or (reqvenda.status_rq = '')) into :stat_aberta;
 if (stat_aberta = 0) then /* se requisicao confirmada */
 begin
  /* altera estoque do produto */
  update produtos set est_f = est_f+(old.quant_rq_item)
         where produtos.cod_prod = old.cod_prod
         and produtos.grupo_prod = old.grupo_prod
         and produtos.cod_empresa = old.cod_empresa;
  if ((old.tp_nf_req = '1') or (old.tp_nf_req = '3')) then
  begin
   update produtos set estc = estc+(old.quant_rq_item)
          where produtos.cod_prod = old.cod_prod
          and produtos.grupo_prod = old.grupo_prod
          and produtos.cod_empresa = old.cod_empresa;
   update produtos set estm = estm+(old.quant_rq_item)
          where produtos.cod_prod = old.cod_prod
          and produtos.grupo_prod = old.grupo_prod
          and produtos.cod_empresa = old.cod_empresa;
  end
  if ((old.tp_nf_req = '2') or (old.tp_nf_req = '4')) then
  begin
   update produtos set estc = estc+(old.quant_rq_item)
          where produtos.cod_prod = old.cod_prod
          and produtos.grupo_prod = old.grupo_prod
          and produtos.cod_empresa = old.cod_empresa;
  end
  if (old.tp_nf_req = '5') then
  begin
   update produtos set ests = ests+(old.quant_rq_item)
          where produtos.cod_prod = old.cod_prod
          and produtos.grupo_prod = old.grupo_prod
          and produtos.cod_empresa = old.cod_empresa;
  end
 end
END ^

