CREATE TRIGGER TI_SINCOFF_SCHEMA_BIU FOR SINCOFF_SCHEMA 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
as
  declare variable EXISTE integer;
  declare variable CAMPO_E varchar(31);
begin
  if (inserting) then
  begin
    select max(ID) + 1
    from SINCOFF_SCHEMA
      into new.ID;

    if (new.ID is null) then
      new.ID = 1;

    select count(EMPDESVOLV.DADOS_OFFLINE)
    from EMPDESVOLV
    where EMPDESVOLV.COD_EMPDES = 1 and
          EMPDESVOLV.DADOS_OFFLINE in ('S', 'C')
      into :EXISTE;

    if (coalesce(EXISTE, 0) = 0) then
      exception EXC_SO_NO_CONF;
  end

  if (updating) then
    if ((old.TABELA <> new.TABELA) or (old.ID <> new.ID)) then
      exception EXC_RI_TAB_ALT_NOT_ALLOW;

  if (not deleting) then
  begin
    --new.empresas_id = coalesce(new.empresas_id, '0');
    new.TABELA = upper(trim(coalesce(new.TABELA, '')));
    new.ATIVO = coalesce(new.ATIVO, 1);
    new.CAMPOS = iif(new.CAMPOS is null, null, upper(replace(new.CAMPOS, ' ', '')));

    if (new.TABELA in ('CODIGO')) then
      exception EXC_SO_TAB_NOTREP;

    select count(T.TABELA)
    from SPDB_TABLES T
    where T.TABELA = new.TABELA
      into :EXISTE;

    if (EXISTE = 0) then
      exception EXC_RI_TAB_NOT_EXISTS;

    select E.CAMPO_EMP
    from SPDB_EMP_KEY(new.TABELA) E
      into :CAMPO_E;

    if (CAMPO_E = '') then
      new.EMPRESAS_ID = null;

    if (CAMPO_E <> '') then
      if (coalesce(new.EMPRESAS_ID, '') = '') then
        exception EXC_SINCOFF_SCHEMA_EMP_ID_EMPTY;
  end
  else
  if (old.TABELA in ('NFCE', 'NFCE_DEST', 'NFCE_INFADIC', 'NFCE_ITEM', 'NFCE_PAGAMENTO', 'NFCE_MOVIMENTO', 'NFCE_MOVIMENTO_LANC', 'CLIENTES', 'PRODUTOS', 'GRADE',
                     'COD_GRADE_PROD', 'PEDVENDA')) then
    exception EXC_SO_DEL_TABS_NFCE;
end
 
 ^

CREATE TRIGGER SINCOFF_SCHEMA_AIUD_MK_OBJ FOR SINCOFF_SCHEMA 
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 1 
as
  declare variable CAMPOS blob sub_type 1 segment size 512;
  declare variable REMOVER smallint;
begin
  if ((deleting) or (new.ATIVO = 0)) then
  begin
    CAMPOS = '';
    REMOVER = 1;
  end
  else
  begin
    CAMPOS = new.CAMPOS;
    REMOVER = 0;
  end

  execute procedure SPSO_MAKE_OBJ(iif(deleting, old.TABELA, new.TABELA), :CAMPOS, :REMOVER);
end
 
 ^

