CREATE TRIGGER TI_SPED_CREDITOS_PERIODO_UTIL FOR SPED_CREDITOS_PERIODO_UTIL 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
AS
begin
  if (inserting) then
    update sped_creditos_periodo scp set scp.valor_pis_util = coalesce(scp.valor_pis_util, 0) + coalesce(new.valor_pis_util,0),
      scp.valor_cofins_util = coalesce(scp.valor_cofins_util, 0) + coalesce(new.valor_cofins_util,0)
    where scp.ano = new.ano and scp.mes = new.mes and scp.cnpj = new.cnpj and scp.sped = new.sped;

  if (deleting) then
    update sped_creditos_periodo scp set scp.valor_pis_util = coalesce(scp.valor_pis_util, 0) - coalesce(old.valor_pis_util,0),
      scp.valor_cofins_util = coalesce(scp.valor_cofins_util, 0) - coalesce(old.valor_cofins_util,0)
    where scp.ano = old.ano and scp.mes = old.mes and scp.cnpj = old.cnpj and scp.sped = old.sped;
    
  if (updating) then
    update sped_creditos_periodo scp set scp.valor_pis_util = coalesce(scp.valor_pis_util, 0) - coalesce(old.valor_pis_util,0) + coalesce(new.valor_pis_util,0),
      scp.valor_cofins_util = coalesce(scp.valor_cofins_util, 0) - coalesce(old.valor_cofins_util,0) + coalesce(new.valor_cofins_util,0)
    where scp.ano = new.ano and scp.mes = new.mes and scp.cnpj = new.cnpj and scp.sped = new.sped;
end
 
 ^

