CREATE TRIGGER TR_DTCA_TIPO_SERVICO FOR TIPO_SERVICO 
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0 
as
  declare variable VSEQID bigint;
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (deleting) then
  begin
    select gen_id(SEQ_DEL_CA, 1)
    from RDB$DATABASE
      into :VSEQID;
    insert into DEL_CA (SEQID, COD_EMPRESA, TABELA, DATA_HORA_ALT, ID_COMERCIO_ABERTO)
    values (:VSEQID, old.COD_EMPRESA, 'TIPO_SERVICO', (select CURRENT_TS from SP_CURRENT_TS(old.COD_EMPRESA)), old.ID_COMERCIO_ABERTO);
  end
  else
  if ((inserting) or (updating)) then
  begin
    if ((old.ATIVO = 1) and
        (new.ATIVO = 0)) then
      if (new.ENV_COMERCIO_ABERTO = 'S') then
        new.ENV_COMERCIO_ABERTO = 'N';

    new.SEQID_CA = (select gen_id(SEQ_DEL_CA, 1)
                    from RDB$DATABASE);
  end
end
 
 ^

