AS
  declare variable nfceId integer;
begin
  if ((new.tpdocs <> 'NFCE') or (trim(coalesce(new.guidt, '')) = ''))  then
    exit;

  select first 1 cod_nfce from nfce_pagamento
    where guid_tr_cartao = new.guidt and cod_empresa = new.cod_empresa
    order by cod_nfce desc
  into :nfceid;

  if (coalesce(nfceid, 0) = 0) then
    exit;

  if (nfceid <> new.nrequisicao) then
    new.nrequisicao = nfceid;
end

 
 ^

CREATE TRIGGER TR_DTEC_VALOR_TIPO_GRADE_EC FOR VALOR_TIPO_GRADE_EC 
ACTIVE BEFORE INSERT OR UPDATE POSITION 0 
AS 
  DECLARE VARIABLE VSEQID BIGINT; 
begin 
  /* Trigger text */ 
  IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
    exit; 

  if ((inserting)or(updating)) then 
  begin 
    NEW.SEQID_EC = (SELECT GEN_ID(SEQ_EC_VALOR_TIPO_GRADE_EC, 1) FROM RDB$DATABASE); 
  end 
end;
 
 ^

CREATE TRIGGER TI_VEICULOS_SUGESTAO FOR VEICULOS 
ACTIVE AFTER INSERT OR UPDATE POSITION 0 
AS
    DECLARE VARIABLE vSugServico integer;
    DECLARE VARIABLE vUsarAparelho char(3);
    DECLARE VARIABLE vCodServ integer;
    DECLARE VARIABLE vCodSug integer;
    DECLARE VARIABLE vCodSugOs integer;
    DECLARE VARIABLE vMesP integer;
    DECLARE VARIABLE vDias integer;
    DECLARE VARIABLE vDataCad timestamp;
    DECLARE VARIABLE current_ts timestamp;
    DECLARE VARIABLE vHoraCad char(8);
    DECLARE VARIABLE vExisteSug integer;
begin
    IF (SUBSTRING(USER FROM 1 FOR 4) = 'REPL') THEN
        exit;

    if (new.modelo <= 0) then
        exit;

    if (coalesce(new.km_v, 0) > 0) then
        exit;

    select empresa.dadvap from empresa
    where empresa.cod_empresa = new.cod_empresa
    into: vusaraparelho;

    if (trim(vusaraparelho) = 'SIM') then
        exit;

    select config_sistema.value1_f from config_sistema
    where config_sistema.chave = 'sug_serv_hab'
    and config_sistema.cod_empresa = new.cod_empresa
    into: vSugServico;

    if (vsugservico <= 0) then
        exit;

    select first 1 sugestaoservico.cod_sug from sugestaoservico
    where sugestaoservico.placa = new.placa and sugestaoservico.chassi = new.chassi
    and sugestaoservico.cod_veic = new.codigo and sugestaoservico.cod_empresa = new.cod_empresa
    and coalesce(sugestaoservico.status, '') <> 'CANCELADA'
    into: vExisteSug;

    if (vExisteSug > 0) then
        exit;

    select current_d, current_ts from sp_current_ts(new.cod_empresa) into :vDataCad, :current_ts;

    select case when(extract(hour from :current_ts) <=9) then '0'|| extract(hour from :current_ts)
    else extract(hour from :current_ts)
    end ||':'|| case when (extract(minute from :current_ts) <= 9) then
        '0'|| extract(minute from :current_ts)
    else extract(minute from :current_ts) end from rdb$database
    into: vHoraCad;

    for select regras_sug.codigo,
     case when(regras_sug.mes_ret_serv1 > 0) then regras_sug.mes_ret_serv1 else regras_sug.interv_mes_serv end from regras_sug
    inner join regras_sug_itens on regras_sug_itens.codigo = regras_sug.codigo and regras_sug_itens.cod_empresa = regras_sug.cod_empresa
    where regras_sug_itens.cod_tipo = new.modelo and regras_sug_itens.cod_empresa = new.cod_empresa and regras_sug.ativo = 1
    and regras_sug.tipo = 'V'
    into: vCodServ, vMesP  do
    begin
        if (vMesP > 0) then
        begin
            vDias = vMesP;

            select cod from incrementa_codigo(new.cod_empresa, 'SUGESTAOSERVICO') into: vCodSug;

            select cod from incrementa_codigo(new.cod_empresa, 'SUG_OS') into: vCodSugOs;

            INSERT INTO SUG_OS
            (COD_SUG_OS, COD_EMPRESA, COD_EQUIP, COD_VEIC, CHASSI, PLACA, US_CAD, DATA_CAD, HORA_CAD,
            KM, NDOC, TPDOC, COD_SERV_SUG, COD_VENDEDOR, ATIVO)
            VALUES
            (:vCodSugOs, new.cod_empresa, null, new.codigo, new.chassi, new.placa, new.us_cad, :vDataCad, :vHoraCad,
            0, null, null, :vcodserv, coalesce(new.us_cad, 0), 1);

            INSERT INTO SUGESTAOSERVICO
            (COD_SUG, COD_EMPRESA, COD_EQUIP, COD_VEIC, CHASSI, PLACA, COD_SUG_OS, ULT_ATD, DATA, HORA,
            ATIVO, COD_CLIENTE, US_CAD, DATA_CAD, HORA_CAD, NDOC_ANT, TPDOC_ANT, COD_SERV_SUG, DIAS, TIPO)
            VALUES
            (:vCodSug, new.cod_empresa, null, new.codigo, new.chassi, new.placa, null,
            new.us_cad, (:vDataCad + (:vDias * 30)), :vHoraCad,
            1, new.cod_cliente, coalesce(new.us_cad, 0), :vDataCad, :vHoraCad,
            null, null, :vcodserv, (:vDias * 30), 'MES PRIMEIRA REVISAO');
        end
    end
end
 
 ^

CREATE TRIGGER VERSAO_HW_BI_CURR_TS FOR VERSAO_HW 
ACTIVE BEFORE INSERT POSITION 0 
as
begin
  if (substring(user from 1 for 4) = 'REPL') then
    exit;

  if (new.DATA_DOWNLOAD is null) then
    select CURRENT_D
	from SP_CURRENT_TS
	  into new.DATA_DOWNLOAD;
end ^

COMMIT WORK ^
SET TERM ; ^

